PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE users (
  id        INTEGER PRIMARY KEY AUTOINCREMENT,
  username  TEXT NOT NULL UNIQUE,
  password  TEXT NOT NULL,   -- bcrypt hash
  email     TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE comics (
  id                 INTEGER PRIMARY KEY AUTOINCREMENT,

  -- Identificación
  title              TEXT NOT NULL,
  series             TEXT,
  number             INTEGER,
  volume             INTEGER,
  isbn               TEXT,
  ean                TEXT,

  -- Autores
  writer             TEXT,
  artist             TEXT,
  colorist           TEXT,
  cover_artist       TEXT,

  -- Editorial
  publisher          TEXT,
  collection         TEXT,
  publish_date       TEXT,
  original_publisher TEXT,
  original_title     TEXT,

  -- Descripción
  synopsis           TEXT,
  genre              TEXT,
  format             TEXT CHECK(format IN ('grapa','tomo','integral','omnibus','manga','novela_grafica','otro') OR format IS NULL),
  pages              INTEGER,
  language           TEXT,

  -- Portada
  cover_url          TEXT,

  -- Estado personal
  read_status        TEXT NOT NULL DEFAULT 'unread' CHECK(read_status IN ('unread','reading','read')),
  owned              INTEGER NOT NULL DEFAULT 0,
  rating             INTEGER CHECK(rating BETWEEN 1 AND 5 OR rating IS NULL),
  notes              TEXT,

  -- Metadata
  created_at         TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at         TEXT NOT NULL DEFAULT (datetime('now'))
, collection_id INTEGER REFERENCES collections(id), price REAL, binding TEXT, authors TEXT);
CREATE TABLE books (
  id                INTEGER PRIMARY KEY AUTOINCREMENT,

  -- Identificación
  title             TEXT NOT NULL,
  isbn              TEXT,
  isbn13            TEXT,
  ean               TEXT,

  -- Autores
  author            TEXT,
  translator        TEXT,
  illustrator       TEXT,

  -- Editorial
  publisher         TEXT,
  publish_date      TEXT,
  edition           TEXT,
  original_title    TEXT,
  original_language TEXT,

  -- Descripción
  synopsis          TEXT,
  genre             TEXT,
  subgenre          TEXT,
  pages             INTEGER,
  language          TEXT,
  saga              TEXT,
  saga_number       INTEGER,

  -- Portada
  cover_url         TEXT,

  -- Estado personal
  read_status       TEXT NOT NULL DEFAULT 'unread' CHECK(read_status IN ('unread','reading','read')),
  owned             INTEGER NOT NULL DEFAULT 0,
  rating            INTEGER CHECK(rating BETWEEN 1 AND 5 OR rating IS NULL),
  notes             TEXT,

  -- Metadata
  created_at        TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at        TEXT NOT NULL DEFAULT (datetime('now'))
, price REAL, binding TEXT);
CREATE TABLE collections (
  id              INTEGER PRIMARY KEY AUTOINCREMENT,
  whakoom_id      TEXT UNIQUE,
  whakoom_type    TEXT,
  title           TEXT NOT NULL,
  publisher       TEXT,
  cover_url       TEXT,
  total_issues    INTEGER,
  description     TEXT,
  url             TEXT,
  created_at      TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at      TEXT NOT NULL DEFAULT (datetime('now'))
, tracking INTEGER NOT NULL DEFAULT 0, format TEXT, status TEXT, edition_details TEXT, synopsis TEXT, authors TEXT, issues TEXT, whakoom_synced_at TEXT, rating INTEGER CHECK(rating BETWEEN 1 AND 5 OR rating IS NULL), notes TEXT);
 Pero eso significa también que el hogar de Thor se ha convertido en un objetivo. ¿Y qué ocurre mientras tanto con los asgardianos y los habitantes del resto de los mundos, incluida la Tierra?','https://www.whakoom.com/ediciones/6704','2026-04-12 13:52:04','2026-04-12 13:52:07',1,'Grapa 40 pp','En curso','Vol. 5, salvo los números 8 a 22 que pertenecen al vol. 4 de la numeración de Marvel.','¡Un nuevo comienzo que lanza a Thor hacia "La Edad Heroica"!. Matt Fraction y Pasqual Ferry se hacen cargo de la colección del Dios del Trueno, y querrás estar aquí ara contarlo. Asgard debe encontrar su nuevo lugar como el Reino Dorado, el más glorioso de los Nueve Mundos de la mitología Pero eso significa también que el hogar de Thor se ha convertido en un objetivo. ¿Y qué ocurre mientras tanto con los asgardianos y los habitantes del resto de los mundos, incluida la Tierra?','[{"name":"Jason Aaron","role":"Guion"},{"name":"Matt Wilson","role":"Color"},{"name":"Al Ewing","role":"Guion"},{"name":"Russell Dauterman","role":"Dibujo, Tinta"},{"name":"Donny Cates","role":"Guion"},{"name":"Matt Fraction","role":"Guion, Dibujo"},{"name":"Nic Klein","role":"Dibujo, Tinta"},{"name":"Matt Hollingsworth","role":"Color"},{"name":"Esad Ribic","role":"Dibujo, Tinta, Color"},{"name":"Ive Svorcina","role":"Dibujo, Tinta, Color"}]','[{"id":"PNokk","number":1,"title":"Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-) #1","subtitle":"La Edad Heroica","cover":"https://i1.whakoom.com/small/10/0a/f4f9ed9926c64266a8a98976d68f64a3.jpg","published":true,"releaseDate":null},{"id":"yPNZ8","number":2,"title":"Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-) #2","subtitle":"La Edad Heroica","cover":"https://i1.whakoom.com/small/33/2a/2f21b32950624f6b9ecc86525bb0e31b.jpg","published":true,"releaseDate":null},{"id":"PNb87","number":3,"title":"Thor / El Poderoso Thor /