INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(8,'Absolute Green Lantern #1','Absolute Green Lantern',1,NULL,'9773081596007-00001',NULL,'Al Ewing','Jahnoy Lindsay',NULL,NULL,'Panini Comics España',NULL,'2025-09-04',NULL,NULL,replace(replace('Contiene Absolute Green Lantern #1 USA\r\nLlega la nueva serie que reinventa a uno de los iconos clásicos de DC. Al Ewing y Jahnoy Lindsay se dan a lo cósmico en el Universo Absolute: Sin el Green Lantern Corps, sin el anillo, sin la fuerza de voluntad... ¡lo que queda es Absolute Green Lantern!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1774953601979-pkq69k.jpg','read',0,NULL,NULL,'2026-03-30 06:12:22','2026-03-31 10:40:02',2,NULL,'grapa',NULL);
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(11,'Absolute Green Lantern #2','Absolute Green Lantern',2,NULL,'9773081596007-00002',NULL,'Al Ewing','Jahnoy Lindsay',NULL,NULL,'Panini Comics España',NULL,'2025-10-02',NULL,NULL,replace(replace('Contiene Absolute Green Lantern #2 USA \r\nHa llegado Abin Sur, y está aquí para juzgar a toda la gente de Evergreen, incluidos Jo Mullein y Hal Jordan. Pero ¿este alienígena es amigo enemigo, y qué traerá su juicio?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1774890804212-b2ixfm.jpg','read',0,NULL,NULL,'2026-03-30 17:13:25','2026-04-07 17:41:38',2,NULL,NULL,NULL);
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(12,'Absolute Green Lantern #4','Absolute Green Lantern',4,NULL,'9773081596007-00004',NULL,'Al Ewing','Jahnoy Lindsay',NULL,NULL,'Panini Comics España',NULL,'2025-12-04',NULL,NULL,replace(replace('Contiene Absolute Green Lantern #4 USA\r\nJo y Hal idean un plan para defenderse ante Abin Sur y liberar Evergreen. Pero... ¿acaso comprenden realmente la naturaleza de Abin Sur y sus planes para Evergreen o, de estar equivocados, acabarán creando un desastre aún mayor?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1774890805921-38l8a9.jpg','read',0,NULL,NULL,'2026-03-30 17:13:26','2026-04-07 17:41:38',2,NULL,NULL,NULL);
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(13,'Absolute Green Lantern #5','Absolute Green Lantern',5,NULL,'9773081596007-00005',NULL,'Al Ewing','Jahnoy Lindsay',NULL,NULL,'Panini Comics España',NULL,'2026-01-08',NULL,NULL,replace(replace('Contiene: Absolute Green Lantern 5\r\n¿Qué sucedió en Evergreen? Las pistas se encuentran ocultas entre los restos de la pequeña ciudad reducida a escombros. Mientas tanto, Jo deberá hacer frente a la amenaza creciente de Hal Jordan.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1774890807127-j02ovt.jpg','read',0,NULL,NULL,'2026-03-30 17:13:27','2026-04-07 17:41:32',2,NULL,NULL,NULL);
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(15,'Absolute Green Lantern #6','Absolute Green Lantern',6,NULL,'9773081596007-00006',NULL,'Al Ewing','Jahnoy Lindsay',NULL,NULL,'Panini Comics España',NULL,'2026-02-05',NULL,NULL,replace(replace('Contiene: Con Absolute Green Lantern 6\r\nAl Ewing y Jahnoy Lindsay nos acercan al día del juicio final. Jo Mullein y Hal Jordan han de afrontar el momento en el que son juzgados, y quién sabe cuál será el veredicto del extraño ente que llegó a la Tierra para cambiar las vidas de ambos...','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775240912607-ekbp6r.jpg','read',0,NULL,NULL,'2026-03-30 17:13:33','2026-04-07 17:41:32',2,NULL,'grapa','[{"name":"Al Ewing","role":"Guion"},{"name":"Jahnoy Lindsay","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(16,'Absolute Green Lantern #3','Absolute Green Lantern',3,NULL,'9773081596007-00003',NULL,'Al Ewing','Jahnoy Lindsay',NULL,NULL,'Panini Comics España',NULL,'2025-11-06',NULL,NULL,replace(replace('Contiene Absolute Green Lantern #3 USA\r\nHal Jordan se ve superado por su maldición y vuelve la mirada hacia Jo. ¿Podrá la nueva Green Lantern averiguar cómo imponerse o terminará por extinguirse su luz? Continúa la increíble revisión de uno de los grandes iconos de DC.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775240905670-030qne.jpg','read',0,NULL,NULL,'2026-03-30 17:13:35','2026-04-07 17:41:32',2,NULL,'grapa','[{"name":"Jahnoy Lindsay","role":"Dibujo"},{"name":"Al Ewing","role":"Guion"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(17,'En este rincón del mundo','En este rincón del mundo',NULL,NULL,'979-1-387-78102-6',NULL,'Fumiyo Kouno',NULL,NULL,NULL,'Planeta Cómic',NULL,'2025-10-08',NULL,NULL,replace(replace('Un drama familiar durante la guerra.\r\nEsta obra es un drama familiar ambientado en la ciudad militar de Kure, en la prefectura de Hiroshima durante la guerra. La protagonista, Suzu, se casa y se muda de Hiroshima a Kure, donde se enfrenta con incertidumbre a una nueva familia, una nueva ciudad y un nuevo mundo. Sin embargo, vive cada día con valentía y dignidad... Este título podría considerarse la segunda parte del célebre y longevo éxito de la era Heisei &quot;La ciudad al atardecer, el país de los cerezos&quot;,','\r',char(13)),'\n',char(10)),NULL,NULL,448,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775240896552-rh6136.jpg','unread',0,4,NULL,'2026-03-30 21:18:02','2026-04-04 21:27:32',NULL,NULL,'Rústica','[{"name":"Fumiyo Kouno","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(21,'Absolute Green Lantern #7','Absolute Green Lantern',7,NULL,'9773081596007-00007',NULL,'Al Ewing','Jason Howard',NULL,NULL,'Panini Comics España',NULL,'2026-03-05',NULL,NULL,replace(replace('Contiene: Con Absolute Green Lantern 7\r\nAl Ewing continúa construyendo una mitología propia en torno a Green Lantern. ¿Cuán lejos se encuentra el mundo del que viene? A través de las profundidades del espacio, los Blackstars dirigen su mirada hacia la Tierra... y solo Tomar Re puede frenar su llegada.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1774936770670-m5ngrh.jpg','read',0,NULL,NULL,'2026-03-31 05:59:31','2026-04-07 17:41:32',2,NULL,NULL,NULL);
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(29,'Absolute Wonder Woman #7','Absolute Wonder Woman',7,NULL,'9773081289008-00007',NULL,'Kelly Thompson','Jordie Bellaire',NULL,NULL,'Panini Comics España',NULL,'2025-10-02',NULL,NULL,replace(replace('Contiene: Absolute Wonder Woman 7\r\nDiana ya escapó en una ocasión del Inframundo. ¿Podrá hacerlo por segunda vez? Diana y Circe siempre supieron que este momento llegaría, pero cuando finalmente lo hace... el precio puede ser más elevado del que están dispuestas a pagar. Además, sigue la historia de la pequeña Diana.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1774952640540-3kr7bk.jpg','read',0,NULL,NULL,'2026-03-31 10:24:02','2026-04-07 17:41:32',10,NULL,'grapa',NULL);
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(30,'Absolute Superman #2','Absolute Superman',2,NULL,'9773081287004-00002',NULL,'Jason Aaron','Rafa Sandoval',NULL,NULL,'Panini Comics España',NULL,'2025-05-08',NULL,NULL,replace(replace('Contiene Absolute Superman 2\r\nLa Corporación Lázaro ha enviado a su equipo de Pacificadores más curtidos en batalla para localizar al misterioso fugitivo que interfiere con sus explotaciones mineras. Jamás habrían esperado que fuera una testaruda agente la que finalmente lograse ponerle las esposas a este superhombre llegado de otro planeta. Ella es la primera sorprendida.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775240890120-1zvrpx.jpg','read',0,NULL,NULL,'2026-03-31 10:24:36','2026-04-07 17:41:32',8,NULL,'grapa','[{"name":"Jason Aaron","role":"Guion"},{"name":"Rafa Sandoval","role":"Dibujo, Tinta"},{"name":"Ulises Arreola","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(31,'Absolute Superman #1','Absolute Superman',1,NULL,'9773081287004-00001',NULL,'Jason Aaron','Rafa Sandoval',NULL,NULL,'Panini Comics España',NULL,'2025-04-03',NULL,NULL,replace(replace('Contiene Absolute Superman 1\r\nEl héroe más brillante y puro del Universo DC, sin su fortaleza, sin una familia, sin un hogar… ¡El Hombre de Acero en su versión Absolute! Solo y aislado, será aquí donde comprendas la profunda importancia que tiene para los héroes el entorno y la comunidad que los esculpe.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775240882470-756sal.jpg','read',0,4,NULL,'2026-03-31 10:24:49','2026-04-07 17:41:32',8,NULL,'Grapa','[{"name":"Jason Aaron","role":"Guion"},{"name":"Rafa Sandoval","role":"Dibujo, Tinta"},{"name":"Ulises Arreola","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(34,'Frontier','Frontier',NULL,NULL,'978-8-412-75850-4',NULL,'Guillaume Singelin','Guillaume Singelin',NULL,NULL,'Grafito Editorial',NULL,'2024-02-29',NULL,NULL,replace(replace('Cuando la Tierra se asfixia ante la sobreexplotación de sus últimos recursos, la humanidad se dirige a un nuevo territorio, el espacio, más allá de los planetas del sistema solar: La Frontera. \r\nEn esta nueva fiebre del oro, tres destinos se entrecruzan: Ji-soo, una científica apasionada por lo desconocido; Camina, una aguerrida y experimentada mercenaria; y Alex, un minero que, como muchos descendientes humanos nunca ha pisado la Tierra. \r\nUna historia de aventuras que narra el tumultuoso viaje de este trío, así como su vida cotidiana en ese nuevo mundo. \r\nFRONTIER nos presenta a una nueva humanidad completamente desconectada de su hogar natal, la Tierra, y que ahora únicamente mira hacia las estrellas.','\r',char(13)),'\n',char(10)),NULL,NULL,200,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775241174933-31jpk6.jpg','read',0,5,NULL,'2026-04-03 18:32:55','2026-04-06 18:19:34',NULL,26,NULL,'[{"name":"Guillaume Singelin","role":"Guion, Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(35,'See You in Memories','See You in Memories',NULL,NULL,'979-1-387-78087-6',NULL,'Pen So',NULL,NULL,NULL,'Planeta Cómic',NULL,'2026-01-28',NULL,NULL,replace(replace('Cuando la cantante y compositora Mat Yi Lei se hizo viral en internet de la noche a la mañana, pensó que por fin podría cumplir su sueño de dedicarse a la música profesionalmente. Sin embargo, tal y como esa popularidad llegó, se fue, y sus canciones empezaron a recibir todo tipo de críticas y comentarios. En vistas de lo sucedido, su padre, aunque con buenas intenciones, le dijo que abandonara su sueño de ser una estrella, y tras una discusión, Mat Yi se fue de casa.\r\nTres años después, ha sido hallada inconsciente en la calle con un cuaderno de dibujo en la mano y no recuerda nada de lo que ha sucedido en los últimos tres años. Decidida a descubrir lo sucedido con sus recuerdos, Mat Yi se embarca en la búsqueda de la verdad ayudada por ese cuaderno repleto de ilustraciones de Hong Kong.\r\nEsta edición incluye la historia de Mat Yi y su cuaderno de bocetos.','\r',char(13)),'\n',char(10)),NULL,NULL,132,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775294448473-t6vb4v.jpg','unread',0,NULL,NULL,'2026-04-04 09:20:49','2026-04-04 09:20:49',NULL,30,NULL,'[{"name":"Pen So","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(36,'Shin Zero #1','Shin Zero',1,NULL,'978-8-412-99244-1',NULL,'Mathieu Bablet','Guillaume Singelin',NULL,NULL,'Grafito Editorial',NULL,'2025-11-06',NULL,NULL,replace(replace('Uberización: (procedente del nombre de la empresa estadounidense de servicios UBER). Término que define la revisión del modelo económico de una empresa o sector de actividad tras la llegada de un nuevo actor que propone ofertar los mismos servicios a precios reducidos, realizados/ejecutados por trabajadores autónomos en lugar de personal asalariado que se contratan a través de plataformas on-line.\r\nMathieu Bablet y Gillaume Singelin nos traen esta serie de género séntai en 3 volúmenes del sello LABEL619. Con una crítica a la uberización del modelo superheroico los autores exploran temas de nuestra actualidad.','\r',char(13)),'\n',char(10)),NULL,NULL,216,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775294524752-km0gy1.jpg','read',0,NULL,NULL,'2026-04-04 09:22:07','2026-04-07 17:41:32',13,NULL,'tapa dura','[{"name":"Mathieu Bablet","role":"Guion"},{"name":"Guillaume Singelin","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(38,'El escultor','El escultor',NULL,NULL,NULL,NULL,'Scott McCloud',NULL,NULL,NULL,'Planeta Cómic',NULL,NULL,NULL,NULL,'Un cómic de Scott McCloud.Publicado por Planeta Cómic',NULL,NULL,496,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775294680342-f39y0d.jpg','read',0,NULL,NULL,'2026-04-04 09:24:41','2026-04-07 17:41:32',NULL,NULL,'Rústica','[{"name":"Scott McCloud","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(43,'Atelier of Witch Hat. Edición Grimorio #1','Atelier of Witch Hat. Edición Grimorio',1,NULL,'979-1-387-83191-2',NULL,'Kamome Shirahama','Kamome Shirahama',NULL,NULL,'Milky Way Ediciones',NULL,'2025-11-27',NULL,NULL,replace(replace('Coco, que vive en una pequeña aldea, siempre ha anhelado ser maga. Sin embargo, “solo aquellos que nacen con habilidad para la magia pueden llegar a ser magos”. Y ese no es su caso: ella es una niña normal y corriente. A pesar de esta ley inquebrantable, Coco intenta realizar un conjuro después de haber espiado al mago Qifrey cuando este visita el taller de costura de su madre y, sin esperarlo, el conjuro surte efecto… ¡y causa una desgracia!\r\nQifrey llega a tiempo de rescatarla y se la lleva a su atelier, donde la muchacha se convierte en su nueva aprendiz. Allí comparte el día a día con otras tres aprendices: la alegre Tetia, la práctica Riche y la estricta Agete. A partir de ese momento, Coco comienza a recorrer el arduo camino que le permita llegar a ser una gran hechicera. Un camino no exento de peligros… y enemigos…\r\n-Incluye un marcapáginas-','\r',char(13)),'\n',char(10)),NULL,NULL,432,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775295737296-m25h39.jpg','read',0,NULL,NULL,'2026-04-04 09:42:18','2026-04-07 17:41:32',14,NULL,'tapa dura','[{"name":"Kamome Shirahama","role":"Guion, Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(44,'El Cuarto Mundo. Clásicos DC #1','El Cuarto Mundo. Clásicos DC',1,NULL,'8480002110440-00001',NULL,'Jack Kirby','Jack Kirby',NULL,NULL,'Planeta Cómic',NULL,'2005-09-01',NULL,NULL,'Jack Kirby',NULL,NULL,176,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775466643434-qgvooz.jpg','unread',0,NULL,NULL,'2026-04-04 09:43:26','2026-04-06 09:10:44',15,NULL,'Rústica','[{"name":"Jack Kirby","role":"Guion, Dibujo"},{"name":"Vince Colletta","role":"Tinta"},{"name":"Mike Royer","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(45,'El Cuarto Mundo. Clásicos DC #2','El Cuarto Mundo. Clásicos DC',2,NULL,'8480002110440-00002',NULL,'Jack Kirby','Jack Kirby',NULL,NULL,'Planeta Cómic',NULL,'2005-11-01',NULL,NULL,'Jack Kirby',NULL,NULL,176,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775295809739-julpgg.jpg','unread',0,NULL,NULL,'2026-04-04 09:43:30','2026-04-04 09:43:30',15,NULL,'Rústica','[{"name":"Jack Kirby","role":"Guion, Dibujo"},{"name":"Mike Roger","role":"Tinta"},{"name":"Vince Colletta","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(46,'El Cuarto Mundo. Clásicos DC #3','El Cuarto Mundo. Clásicos DC',3,NULL,'8480002110440-00003',NULL,'Jack Kirby','Jack Kirby',NULL,NULL,'Planeta Cómic',NULL,'2005-12-01',NULL,NULL,replace(replace('The Forever People 1-6 USA\r\nEstrenamos en estas páginas «Forever People», una serie de la que jamás se llegó a ver un solo número en España. Es la gran saga del «Cuarto Mundo» vista desde la perspectiva de unos jóvenes de New Génesis muy especiales en los que las referencias a la época hippie en que se realizaron estos episodios es constante. Una muestra más del inmenso talento de Jack Kirby.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775295833490-vd88r3.jpg','unread',0,NULL,NULL,'2026-04-04 09:43:54','2026-04-04 09:43:54',15,NULL,'Rústica 112-176 pp','[{"name":"Jack Kirby","role":"Guion, Dibujo"},{"name":"Vince Colletta","role":"Tinta"},{"name":"Mike Roger","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(47,'El Cuarto Mundo. Clásicos DC #4','El Cuarto Mundo. Clásicos DC',4,NULL,'8480002110440-00004',NULL,'Jack Kirby','Jack Kirby',NULL,NULL,'Planeta Cómic',NULL,'2006-01-01',NULL,NULL,replace(replace('The Forever People 7-11, The Young Gods of SuperTown y Weird Mistery Tales 1-2 USA\r\nLos últimos episodios de «Forever People» tuvieron una curiosa mezcla de distintos subgéneros del cómic: horror, superhéroes, aventura, ciencia ficción. Todo bajo la batuta del genio creativo de Jack Kirby, que se atreve a integrar al famoso personaje Deadman en las historias. Además, se ofrecen en rigurosa exclusiva dos historias cortas apenas conocidas que se publicaron en «Weird Mistery Tales». Ya al final, el impresionante retorno del Hombre Infinito.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775295837134-vrz3o3.jpg','unread',0,NULL,NULL,'2026-04-04 09:43:58','2026-04-04 09:43:58',15,NULL,'Rústica 112-176 pp','[{"name":"Jack Kirby","role":"Guion, Dibujo"},{"name":"Mark Evanier","role":"Dibujo"},{"name":"Steve Sherman","role":"Dibujo"},{"name":"Mike Roger","role":"Tinta"},{"name":"Vince Colletta","role":"Tinta"}]');
