INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(50,'El Cuarto Mundo. Clásicos DC #7','El Cuarto Mundo. Clásicos DC',7,NULL,'8480002110440-00007',NULL,'Jack Kirby','Jack Kirby',NULL,NULL,'Planeta Cómic',NULL,'2006-04-01',NULL,NULL,'Superman',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775295849500-9vdyig.jpg','unread',0,NULL,NULL,'2026-04-04 09:44:10','2026-04-04 09:44:10',15,NULL,'Rústica 112-176 pp','[{"name":"Jack Kirby","role":"Guion, Dibujo"},{"name":"Robert Kanigher","role":"Guion"},{"name":"Werner Roth","role":"Dibujo"},{"name":"Vince Colletta","role":"Tinta"},{"name":"Mike Roger","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(51,'El Cuarto Mundo. Clásicos DC #8','El Cuarto Mundo. Clásicos DC',8,NULL,'8480002110440-00008',NULL,'Jack Kirby','Jack Kirby',NULL,NULL,'Planeta Cómic',NULL,'2006-06-01',NULL,NULL,replace(replace('Mister Miracle 1-6 USA\r\nLa última colección que conforma el entramado del Cuarto Mundo de Jack Kirby empieza a publicarse a partir de este número. Le ha llegado el turno a la serie regular «Mister Miracle», aunque sea la última no significa que sea la menos importante. De hecho, en sus páginas se encuentran las primeras apariciones de personajes tan importantes como Mister Milagro, Big Barda, el Dr. Vundabar o la Abuela Bondad. ¡Todo está listo para que empiece la recta final de esta épica saga!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775295852725-p7nti1.jpg','unread',0,NULL,NULL,'2026-04-04 09:44:13','2026-04-04 09:44:13',15,NULL,'Rústica 112-176 pp','[{"name":"Jack Kirby","role":"Guion, Dibujo"},{"name":"Vince Colletta","role":"Tinta"},{"name":"Mike Roger","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(52,'El Cuarto Mundo. Clásicos DC #9','El Cuarto Mundo. Clásicos DC',9,NULL,'8480002110440-00009',NULL,'Jack Kirby','Jack Kirby',NULL,NULL,'Planeta Cómic',NULL,'2006-07-01',NULL,NULL,replace(replace('Mister Miracle 7-11 USA\r\nCuando los números de «Mister Miracle» recopilados en este tomo fueron publicados en Estados Unidos, esta ya se había convertido en la única serie del Cuarto Mundo en el mercado. Todas las demás habían sido víctimas de la cancelación y Jack Kirby no tuvo otro remedio que enfocar estos números desde otra perspectiva. El material incluido aquí es testigo de aquellos meses, cuando el Cuarto Mundo quedó restringido a una única serie y Kirby hizo todo lo posible por mantenerla en pie. Se trata de un tesoro único dada su importancia histórica, con apariciones relevantes de personajes como la Abuela Bondad o Kanto y hasta la aparición de Ted Brown, el hijo de Mister Milagro original.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775295855867-tfosdu.jpg','unread',0,NULL,NULL,'2026-04-04 09:44:17','2026-04-04 09:44:17',15,NULL,'Rústica 112-176 pp','[{"name":"Jack Kirby","role":"Guion, Dibujo"},{"name":"Mike Roger","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(53,'El Cuarto Mundo. Clásicos DC #10','El Cuarto Mundo. Clásicos DC',10,NULL,'8480002110440-00010',NULL,'Jack Kirby','Jack Kirby',NULL,NULL,'Planeta Cómic',NULL,'2006-07-01',NULL,NULL,replace(replace('Mister Miracle 13-18 USA\r\nEn este número de «Clásicos DC: Cuarto Mundo» se recopilan las últimas historias que Jack Kirby hizo para «Mister Miracle». Se trata de unas aventuras completamente alejadas del mundo de los Nuevos Dioses, con historias superheroicas de estilo clásico que se ven aderezadas con la introducción de Shilo Norman, el joven aspirante a Mister Milagro que Scott Free acoge como discípulo. El último número sí que ofrece un regreso a las raíces con la presencia de los personajes principales del Cuarto Mundo, en una despedida tan antológica como nostálgica del universo creado por Jack Kirby.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775295860973-15wdek.jpg','unread',0,NULL,NULL,'2026-04-04 09:44:21','2026-04-04 09:44:21',15,NULL,'Rústica 112-176 pp','[{"name":"Jack Kirby","role":"Guion, Dibujo"},{"name":"Mike Roger","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(54,'JLA / JLE. Clásicos DC #1','JLA / JLE. Clásicos DC',1,NULL,'8480002109239-00001',NULL,'J.M. DeMatteis','Kevin Maguire',NULL,NULL,'Planeta Cómic',NULL,'2005-12-01',NULL,NULL,replace(replace('Contiene: Justice League Vol. 1 #1-6, Justice League International #1 USA\r\nEn 1987 aparece una nueva generación de superhéroes sin precedentes al unir comedia y acción como hilo conductor de sus aventuras. Este tomo recoge los primeros números publicados de este grupo que lucha en pos de la justicia internacional, compuesto por Batman, Blue Beetle, Martian Manhunter, Guy Gardner, Black Canary, Mister Miracle, Dr. Fate, Booster Gold, Doctor Light y Shazam.','\r',char(13)),'\n',char(10)),NULL,NULL,224,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775296092956-88jyzm.jpg','unread',0,NULL,NULL,'2026-04-04 09:48:13','2026-04-04 09:48:13',16,NULL,'Rústica','[{"name":"J.M. DeMatteis","role":"Guion"},{"name":"Kevin Maguire","role":"Dibujo"},{"name":"Al Gordon","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(55,'JLA / JLE. Clásicos DC #2','JLA / JLE. Clásicos DC',2,NULL,'8480002109239-00002',NULL,'J.M. DeMatteis','Kevin Maguire',NULL,NULL,'Planeta Cómic',NULL,'2006-02-01',NULL,NULL,replace(replace('Contiene: JLI #8-15, Suicide Squad #13, Annual #2, Justice League International Annual #1 USA\r\nEn 1987 aparece una nueva generación de superhéroes sin precedentes al unir comedia y acción como hilo conductor de sus aventuras. Este tomo recoge los primeros números publicados de este grupo que lucha en pos de la justicia internacional, compuesto por Batman, Blue Beetle, Martian Manhunter, Guy Gardner, Black Canary, Mister Miracle, Dr. Fate, Booster Gold, Doctor Light y Shazam.','\r',char(13)),'\n',char(10)),NULL,NULL,224,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775296094732-3gi4rt.jpg','unread',0,NULL,NULL,'2026-04-04 09:48:15','2026-04-04 09:48:15',16,NULL,'Rústica','[{"name":"J.M. DeMatteis","role":"Guion"},{"name":"Keith Giffen","role":"Guion"},{"name":"Kevin Maguire","role":"Dibujo"},{"name":"Steve Leialoha","role":"Dibujo"},{"name":"Bill Willingham","role":"Dibujo"},{"name":"Al Gordon","role":"Tinta"},{"name":"Joe Rubinstein","role":"Tinta"},{"name":"Gene D''Angelo","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(56,'JLA / JLE. Clásicos DC #3','JLA / JLE. Clásicos DC',3,NULL,'843-2-715-02471-2',NULL,'J.M. DeMatteis','Kevin Maguire',NULL,NULL,'Planeta Cómic',NULL,'2006-05-01',NULL,NULL,replace(replace('Contiene: JLI #16-23 USA\r\nEn este número de Clásicos DC: JLA/JLE no hay tiempo para el descanso. El mejor detective del mundo debe convertirse en el agente secreto más irresistible del planeta cuando la Liga decide infiltrarse en el país enemigo Bialya. Mientras tanto, otra rama del grupo marcha en busca de Mister Milagro por todo el universo sin saber que se encontrará con Lobo y que caerá en las fauces de Apokolips, con Darkseid al acecho. Todo esto con un Guy Gardner amnésico y un Manga Khan que regresa en busca de venganza. ¿Quién dijo que ser superhéroe no era divertido?','\r',char(13)),'\n',char(10)),NULL,NULL,224,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775296096636-z9agdg.jpg','unread',0,NULL,NULL,'2026-04-04 09:48:17','2026-04-04 09:48:17',16,NULL,'Rústica','[{"name":"J.M. DeMatteis","role":"Guion"},{"name":"Keith Giffen","role":"Guion"},{"name":"Kevin Maguire","role":"Dibujo"},{"name":"Ty Templeton","role":"Dibujo"},{"name":"Al Gordon","role":"Tinta"},{"name":"Joe Rubinstein","role":"Tinta"},{"name":"Gene D''Angelo","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(57,'JLA / JLE. Clásicos DC #4','JLA / JLE. Clásicos DC',4,NULL,'843-2-715-02472-9',NULL,'J.M. DeMatteis','Mike McKone',NULL,NULL,'Planeta Cómic',NULL,'2006-06-01',NULL,NULL,replace(replace('Contiene: JLI #24-25, JLE #1-3, JLA #26-27 USA\r\nEn este número de Clásicos DC: JLA/JLE se produce un hecho histórico que marcará la colección en dos embajadas para cubrir todos los frentes y ser más internacional que nunca. Seréis testigos de la creción de la nueva sede en Europa, comandada por el Capitán Átomo, y a su vez, en la Liga de la Justicia de América, Batman se encontrará con la Cazadora mientras se enfrenta a un Blue Beetle poseído y con ansias de matar a Maxwell Lord. ¡La división del grupo en dos sólo garantiza el doble de diversión a partir de ahora!','\r',char(13)),'\n',char(10)),NULL,NULL,224,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775296098009-jss9k1.jpg','unread',0,NULL,NULL,'2026-04-04 09:48:18','2026-04-04 09:48:18',16,NULL,'Rústica','[{"name":"J.M. DeMatteis","role":"Guion"},{"name":"Keith Giffen","role":"Guion"},{"name":"Mike McKone","role":"Dibujo"},{"name":"Bart Sears","role":"Dibujo"},{"name":"Ty Templeton","role":"Dibujo"},{"name":"Pablo Marcos","role":"Tinta"},{"name":"Joe Rubinstein","role":"Tinta"},{"name":"Gene D''Angelo","role":"Color"}]');
