INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(72,'DC Pocket #26','DC Pocket',26,NULL,'978-8-419-21015-9',NULL,'Jeph Loeb','Tim Sale',NULL,NULL,'ECC Ediciones',NULL,'2022-03-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman: Dark Victory núms. 0-13 USA\r\nTras desentrañar el misterio de Festivo, Batman observa la repetición de un patrón criminal similar que se está cobrando como víctimas a integrantes del Departamento de Policía de Gotham. Apodado el Ahorcado, este nuevo asesino en serie pondrá en jaque al Caballero Oscuro, preocupado por la escalada de violencia que asola la ciudad… y por la atención que requiere su nuevo pupilo: Dick Grayson, llamado a convertirse en Robin, el Chico Maravilla.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775298836123-xlkchn.jpg','unread',0,NULL,NULL,'2026-04-04 10:33:58','2026-04-04 10:33:58',17,NULL,'rustica','[{"name":"Jeph Loeb","role":"Guion"},{"name":"Tim Sale","role":"Dibujo, Tinta"},{"name":"Gregory Wright","role":"Color"},{"name":"Heroic Age","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(73,'DC Pocket #2','DC Pocket',2,NULL,'978-8-418-78489-7',NULL,'Scott Snyder','Greg Capullo',NULL,NULL,'ECC Ediciones',NULL,'2021-08-31',NULL,NULL,replace(replace('Durante la investigación de un brutal asesinato, Batman descubre pistas que relacionan el crimen con el Tribunal de los Búhos: una organización secreta asociada a leyendas urbanas y canciones populares de Gotham. Pero, lejos de ser producto de mentes fabuladoras, la misteriosa sociedad parece hundir sus raíces en la historia oculta de la ciudad. ¿Hasta dónde llegan el poder y la influencia de sus nuevos enemigos? El Mejor Detective del Mundo tratará de averiguarlo… tal vez a costa de su cordura.\r\nCoincidiendo con el nacimiento del Nuevo Universo DC, Scott Snyder (','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775485216206-dx56no.jpg','unread',0,NULL,NULL,'2026-04-04 10:34:29','2026-04-06 14:20:17',17,17.67,'rustica','[{"name":"Scott Snyder","role":"Guion"},{"name":"Greg Capullo","role":"Dibujo"},{"name":"James Tynion IV","role":"Guion"},{"name":"Rafael Albuquerque","role":"Dibujo"},{"name":"Jason Fabok","role":"Dibujo, Tinta"},{"name":"Jonathan Glapion","role":"Tinta"},{"name":"FCO Plascencia","role":"Color"},{"name":"Dave McCaig","role":"Color"},{"name":"Peter Steigerwald","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(74,'DC Pocket #7','DC Pocket',7,NULL,'978-8-418-86278-6',NULL,'Brian Azzarello','Jim Lee',NULL,NULL,'ECC Ediciones',NULL,'2021-11-03',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Superman núms. 204-215 USA\r\nLa Tierra ha sufrido los efectos de un acontecimiento extraordinario. Millones de personas se han desvanecido sin dejar rastro. Nadie se ha librado del cataclismo. Ni siquiera Superman. Pero ha pasado ya un año y el héroe tiene aún muchas preguntas por responder. Las dudas lo están matando. Cuando llegue la hora de entrar en acción, Superman se enfrentará a un dilema formidable: ¿hasta dónde está dispuesto a arriesgar «por el mañana»?\r\nRecopila una de las más grandes historias narradas del Hombre de Acero. A cargo Brian Azzarello (100 Balas) y los lápices de Jim Lee (All-Star Batman y Robin, el chico maravilla) acompañado a las tintas por Scott Williams y con color de Alex Sinclair. Este volumen incluye los números originales de Superman núms. 204 a 215 USA.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775298953787-qxkgow.jpg','unread',0,NULL,NULL,'2026-04-04 10:35:54','2026-04-04 10:35:54',17,NULL,'rustica','[{"name":"Brian Azzarello","role":"Guion"},{"name":"Jim Lee","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(75,'DC Pocket #9','DC Pocket',9,NULL,'978-8-418-86280-9',NULL,'Jeph Loeb','Jim Lee',NULL,NULL,'ECC Ediciones',NULL,'2021-11-03',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 608 a 619 USA\r\n¡La llegada de Silencio!\r\nGotham City se ha visto infectada por una epidemia criminal y todos los enemigos de Batman han salido a la luz con tal de sumir su vida en el caos más absoluto. Pero ellos ni siquiera sospechan que son meros peones del maligno Silencio y de su elaborado juego de venganza contra Bruce Wayne. Forzado más allá del límite, el Hombre Murciélago necesitará algo más que las habilidades del mejor detective del mundo para descubrir la verdadera identidad de este misterioso genio de la estrategia antes de que sea demasiado tarde.\r\n¡Obra de tres grandes del cómic —el guionista Jeph Loeb (Batman: El largo Halloween, Batman: Victoria oscura), el dibujante Jim Lee (Liga de la Justicia, Escuadrón Suicida) y el entintador Scott Williams (All-Star Batman y Robin, Superman)—, este inolvidable relato presenta el caso más personal del Cruzado de la Capa hasta la fecha! Aquí se recopilan los números del 608 al 619 de Batman, un interludio de Silencio publicado en el número 0 de Wizard.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775298960167-4jy8hp.jpg','unread',0,NULL,NULL,'2026-04-04 10:36:01','2026-04-04 10:36:01',17,NULL,'rustica','[{"name":"Jeph Loeb","role":"Guion"},{"name":"Jim Lee","role":"Dibujo"},{"name":"Scott Williams","role":"Tinta"},{"name":"Alex Sinclair","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(76,'DC Pocket #10','DC Pocket',10,NULL,'978-8-418-97409-0',NULL,'Grant Morrison','Frank Quitely',NULL,NULL,'ECC Ediciones',NULL,'2021-11-30',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: All Star Superman núms. 1 a 12 USA\r\nCon la premisa de Superman muriéndose a causa de una sobrecarga masiva de energía solar, Grant Morrison (El Asco) y Frank Quitely (El Multiverso) narran a lo largo de este volumen las últimas semanas del Hombre de Acero. Durante este tiempo, Superman se enfrentará a dos supervivientes de Krypton, a amenazas alienígenas y, por supuesto, a Lex Luthor en una última batalla por la supervivivencia de la Tierra. Y todo esto mientras, como Clark Kent, intenta poner en orden su propia vida privada ante su inminente e irremediable muerte.\r\nPocas veces el título de un cómic es tan acertado como este All-Star Superman es una historia arrebatadora en la que se dan cita &quot;todas las estrellas&quot; del universo de Superman para crear una aventura que aúna un guion soberbio, un dibujo fuera de serie y una épica como nunca se ha visto. ¿Logrará Superman salvar a la humanidad por última vez? ¿Y sobrevivirá él a su envenenamiento solar? Sé testigo del destino del Hombre del Mañana en uno de sus cómics más memorables.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775298964754-yrs1fy.jpg','read',0,NULL,NULL,'2026-04-04 10:36:05','2026-04-07 17:41:13',17,NULL,'rustica','[{"name":"Grant Morrison","role":"Guion"},{"name":"Frank Quitely","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(77,'DC Pocket #12','DC Pocket',12,NULL,'978-8-418-97411-3',NULL,'Mark Waid','Alex Ross',NULL,NULL,'ECC Ediciones',NULL,'2021-11-30',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Kingdom Come núms. 1 a 4 USA\r\nSuperman se ha retirado, y sin su influencia, el mundo ha aceptado a una nueva generación de héroes encabezados por Magog que recurren a la violencia y a la barbarie para impartir su particular visión de la justicia. No obstante, la amenaza de un futuro apocalíptico fuerza el regreso del Hombre de Acero... y el choque con los recién llegados será inevitable.\r\nEn 1996, el guionista Mark Waid y el dibujante Alex Ross asombraron al mundo con Kingdom Come, un Otros Mundos que sirvió como alegoría de la situación que vivía el género superheróico y que se convirtió en un clásico instantáneo.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775298973664-0ngq4u.jpg','unread',0,NULL,NULL,'2026-04-04 10:36:14','2026-04-04 10:36:14',17,NULL,'rustica','[{"name":"Mark Waid","role":"Guion"},{"name":"Alex Ross","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(78,'DC Pocket #24','DC Pocket',24,NULL,'978-8-419-16318-9',NULL,'Geoff Johns','Andy Kubert',NULL,NULL,'ECC Ediciones',NULL,'2022-03-29',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Flashpoint núms. 1 a 5 USA\r\nBarry Allen es un héroe. Protege a los inocentes y lucha contra el mal como Flash... el Hombre más Rápido del Mundo. Pero este no es el mundo que conocía. Este es un mundo en el que Wonder Woman y Aquaman han sumido a millones de personas en las tinieblas de la guerra... en el que ningún ser humano ha portado jamás la luz de Green Lantern... en el que Batman tiene tanta sangre en las manos como sus enemigos... en el que nadie ha oído hablar jamás de Superman...En el que el hombre más rápido que existe no es más que un hombre corriente.\r\nSin poderes y a solas, Barry Allen recuerda la realidad tal como fue. Ahora debe convencer a estos héroes tan extraños como peligrosos —siniestras versiones de los hombres y las mujeres junto a los que una vez luchó— para que apoyen su causa y devuelvan el mundo al buen camino. Llevará su tiempo, pero tiempo es algo que él no tiene. Porque independientemente de que triunfe o fracase... El mundo jamás volverá a ser el mismo.\r\nEl equipo creativo formado por las superestrellas Geoff Johns y Andy Kubert tienen el orgullo de presentar Flashpoint... ¡un acontecimiento inolvidable que lleva al Universo DC más allá del punto de no retorno!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775299004843-gwawp9.jpg','unread',0,NULL,NULL,'2026-04-04 10:36:45','2026-04-04 10:36:45',17,NULL,'rustica','[{"name":"Geoff Johns","role":"Guion"},{"name":"Andy Kubert","role":"Dibujo"},{"name":"Sandra Hope","role":"Tinta"},{"name":"Jesse Delperdang","role":"Tinta"},{"name":"Alex Sinclair","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(79,'DC Pocket #38','DC Pocket',38,NULL,'978-8-419-27939-2',NULL,'Tom King','Barnaby Bagenda',NULL,NULL,'ECC Ediciones',NULL,'2022-07-26',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Omega Men Vol.3  1-12 USA\r\nKyle Rayner, el White Lantern, está muerto. Le mataron los Omega Men. En una emisión en directo. Son unos insurgentes violentos, una organización terrorista, una secta fanática. O son unos patriotas... la última esperanza para la libertad en un sector olvidado del universo. En el sistema Vega, depende de a quién le preguntes.\r\nPero a pesar de lo que la galaxia crea haber visto, el White Lantern de la Tierra sigue vivo... prisionero de los Omega Men. Lo que de verdad quieren es que se sume a ellos en su incansable guerra contra la todopoderosa Ciudadela y su tiránico Virrey.\r\nMientras Kyle va conociendo a este variopinto grupo de forajidos, se cuestionará todo lo que sabe sobre lo que significa ser un héroe. En este extraño sistema donde los Green Lanterns están prohibidos, ¿romperá su juramento y se unirá a la revolución? ¿O al final descubrirá que los Omega Men son unos monstruos?\r\nDe uno de los escritores más laureados de la industria, Tom King (Batman, Grayson), y del magnífico dibujante Barnaby Bagenda (A1) llega Green Lantern presenta: Omega Men, que recopila al completo esta revolucionaria historia de ciencia ficción, aclamada por la crítica, que se enclava en el corazón del Universo DC. ¡Si buscas una historia trepidante que te haga pensar, con acción, intriga, romance y venganza, este libro es el Alfa y el Omega!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775299051326-ymmgx9.jpg','unread',0,NULL,NULL,'2026-04-04 10:37:32','2026-04-04 10:37:32',17,NULL,'rustica','[{"name":"Tom King","role":"Guion"},{"name":"Barnaby Bagenda","role":"Dibujo"},{"name":"Toby Cypress","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(80,'DC Pocket #40','DC Pocket',40,NULL,'978-8-419-32547-1',NULL,'Brian Michael Bendis','Alex Maleev',NULL,NULL,'ECC Ediciones',NULL,'2022-07-26',NULL,NULL,'EDICIÓN ORIGINAL: DC',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775299061140-y7j1n3.jpg','unread',0,NULL,NULL,'2026-04-04 10:37:42','2026-04-04 10:37:42',17,NULL,'rustica','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Alex Maleev","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(81,'DC Pocket #79','DC Pocket',79,NULL,'978-8-419-81171-4',NULL,'Tim Seeley','Freddie E. Williams II',NULL,NULL,'ECC Ediciones',NULL,'2023-08-29',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Injustice: Gods Among Us vs. Masters of the Universe núms. 1 a 6 USA\r\nEn Injustice vs. Masters del Universo, Tim Seeley y Freddie E. Williams II nos ofrecen el crossover definitivo: una miniserie de seis entregas íntegramente recopilada en el presente tomo, que narra la colisión de dos universos de ficción fascinantes.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775334247119-eipl0x.jpg','read',0,NULL,NULL,'2026-04-04 20:24:08','2026-04-07 17:40:46',17,NULL,'rustica','[{"name":"Tim Seeley","role":"Guion"},{"name":"Freddie E. Williams II","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(82,'DC Pocket #74','DC Pocket',74,NULL,'978-8-419-81111-0',NULL,'Keith Giffen','Dexter Soy',NULL,NULL,'ECC Ediciones',NULL,'2023-07-18',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: DC Universe vs. Masters of the Universe núms. 1-6, DC Comics Presents núm. 47 USA\r\nEl mundo de Eternia se ha sumido en la oscuridad. La malvada\r\nHorda ha superado sus defensas. Y Hordak, un conquistador\r\ndivino de poder imparable, es el soberano supremo.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775334252527-82gb4u.jpg','read',0,NULL,NULL,'2026-04-04 20:24:14','2026-04-07 17:40:46',17,NULL,'rustica','[{"name":"Keith Giffen","role":"Guion"},{"name":"Tony Bedard","role":"Guion"},{"name":"Paul Kupperberg","role":"Guion"},{"name":"Dexter Soy","role":"Dibujo, Color"},{"name":"Pop Mhan","role":"Dibujo"},{"name":"Derlis Santacruz","role":"Dibujo"},{"name":"Eduardo Francisco","role":"Dibujo"},{"name":"Curt Swan","role":"Dibujo"},{"name":"Andrés Ponce","role":"Tinta"},{"name":"Mike DeCarlo","role":"Tinta"},{"name":"Verónica Gandini","role":"Color"},{"name":"Tony Aviña","role":"Color"},{"name":"Rex Lokus","role":"Color"},{"name":"Gene D''Angelo","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(83,'DC Pocket #104','DC Pocket',104,NULL,'978-8-410-10882-0',NULL,'Geoff Johns','Jason Fabok',NULL,NULL,'ECC Ediciones',NULL,'2024-03-13',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman: Three Jokers 1-3\r\nEl criminal. El payaso. El cómico. Hace muchos años que el Joker se convirtió en la némesis de Batman por méritos propios. No solo ha intentado matarlo a él sino a toda Gotham City con un sinfín de ardides que el héroe, hasta la fecha, siempre ha podido truncar. Lo que el Caballero Oscuro ignoraba era que no tiene un solo enemigo. Tiene tres. Y ahora, va a tener que detenerlos a todos en compañía de los dos pupilos que más han sufrido en sus carnes el sadismo del Príncipe Payaso del Crimen. En Tres Jokers, el guionista Geoff Johns y el dibujante Jason Fabok, el equipo creativo de Liga de la Justicia: La guerra de Darkseid, se reúnen para contarnos una historia terrorífica y trepidante protagonizada por Batman, Batgirl y Capucha Roja.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775334274698-k8bi5k.jpg','read',0,NULL,NULL,'2026-04-04 20:24:36','2026-04-07 17:40:46',17,NULL,'rustica','[{"name":"Geoff Johns","role":"Guion"},{"name":"Jason Fabok","role":"Dibujo, Tinta"},{"name":"Brad Anderson","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(84,'DC Pocket #93','DC Pocket',93,NULL,'978-8-419-97213-2',NULL,'Grant Morrison','Doug Mahnke',NULL,NULL,'ECC Ediciones',NULL,'2023-12-14',NULL,NULL,replace(replace('Edición original: DC Universe núm. 0, Final Crisis núms. 1-3, Final Crisis: Requiem, Final Crisis: Superman Beyond núms. 1-2 USA.\r\nSe ha producido un asesinato en la Tierra. Pero no es uno más. La víctima es un dios de otro mundo, lo cual obliga a los Guardianes del Universo a acordonar nuestro planeta mientras se suceden otros acontecimientos. Por ejemplo, Libra, un enemigo antaño anecdótico de la Liga de la Justicia de América, ha obtenido un poder insólito, pero ¿quién le ha otorgado su nuevo poder? Héroes que sucumben a las fuerza del mal, otros que regresan de la tumba, un club que esclaviza a los metahumanos jóvenes para convertirlos en carne de apuestas... Son apenas los primeros ingredientes de una trama cósmica que solo es capaz de contarnos Grant Morrison acompañado por dibujantes de la talla de J.G. Jones o Doug Mahnke.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775334280348-moahd1.jpg','unread',0,NULL,NULL,'2026-04-04 20:24:41','2026-04-04 20:24:41',17,NULL,'rustica','[{"name":"Grant Morrison","role":"Guion"},{"name":"Peter J. Tomasi","role":"Guion"},{"name":"Doug Mahnke","role":"Dibujo"},{"name":"J.G. Jones","role":"Dibujo"},{"name":"Carlos Pacheco","role":"Dibujo"},{"name":"Matthew Clark","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(85,'DC Pocket #100','DC Pocket',100,NULL,'978-8-410-10829-5',NULL,'Grant Morrison','Doug Mahnke',NULL,NULL,'ECC Ediciones',NULL,'2024-02-14',NULL,NULL,replace(replace('Contiene Final Crisis 4-7, Final Crisis: Submit USA.\r\nDarkseid ha triunfado. La Ecuación de la Antivida está causando estragos en la Tierra y está trans-formando a sus habitantes. Y por supuesto, entre los sometidos se encuentran muchos héroes y heroínas. Con semejante panorama, una resistencia encabezada por Green Arrow, Canario Negro y Oráculo se reúne en el Salón de la Justicia mientras, en el futuro, Superman encuentra la posible so-lución al conflicto gracias a la Legión de Superhéroes. Sin embargo, lo que el Hombre de Acero no se espera es que está a punto de sufrir una tragedia personal irreparable. Grant Morrison escribe esta segunda entrega de Crisis Final, dibujada por autores de la talla de Carlos Pacheco, J.G. Jones y Doug Mahnke.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775334286990-kq98px.jpg','unread',0,NULL,NULL,'2026-04-04 20:24:48','2026-04-04 20:24:48',17,NULL,'rustica','[{"name":"Grant Morrison","role":"Guion"},{"name":"Peter J. Tomasi","role":"Guion"},{"name":"Doug Mahnke","role":"Dibujo"},{"name":"J.G. Jones","role":"Dibujo"},{"name":"Carlos Pacheco","role":"Dibujo"},{"name":"Matthew Clark","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(90,'DC Pocket #132','DC Pocket',132,NULL,'978-8-410-33096-2',NULL,'Jim Starlin','Jim Aparo',NULL,NULL,'ECC Ediciones',NULL,'2024-10-09',NULL,NULL,replace(replace('Edición original: Batman núms. 426-429, Batman Annual núm. 25 USA\r\nJason Todd, el segundo Robin, ha ayudado a Batman a resolver muchos casos; sin embargo, últimamente, está aflorando una ira que no es digna del Chico Maravilla. Cuando su mentor decide apartarlo temporalmente de las calles, el muchacho aprovecha para buscar a su madre biológica. Mientras tanto, el Joker ha vuelto a quedar en libertad y tiene un plan nuevo que transformará para siempre la vida del Dúo Dinámico. Una muerte en la familia es una de las historias más famosas y trascendentales de la historia de Batman, y por fin aparece en formato de bolsillo. Escrita por Jim Starlin y dibujada por el legendario Jim Aparo, es un torrente de acción y emociones que ya ha cautivado a varias generaciones de lectores.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775414794475-k0vz15.jpg','unread',0,NULL,NULL,'2026-04-05 18:46:35','2026-04-05 18:46:35',17,NULL,'bolsillo','[{"name":"Jim Starlin","role":"Guion"},{"name":"Jim Aparo","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(91,'DC Pocket #76','DC Pocket',76,NULL,'978-8-419-81168-4',NULL,'Geoff Johns','Gary Frank',NULL,NULL,'ECC Ediciones',NULL,'2023-08-08',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman: Earth One vol. 3\r\nHarvey Dent ha muerto. ¿O no? Bruce Wayne, tratando de equilibrar sus dos vidas, tiene que averiguar la verdad y para ello accederá a su creciente red de agentes, entre ellos Alfred Pennyworth, Jim Gordon, Waylon Jones (alias “Killer Croc”) y una recién llegada muy astuta llamada Catwoman.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775414825532-nz1f87.jpg','unread',0,NULL,NULL,'2026-04-05 18:47:06','2026-04-05 18:47:06',17,NULL,'rustica','[{"name":"Geoff Johns","role":"Guion"},{"name":"Gary Frank","role":"Dibujo"},{"name":"Jonathan Sibal","role":"Tinta"},{"name":"Brad Anderson","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(92,'DC Pocket #67','DC Pocket',67,NULL,'978-8-419-73347-4',NULL,'Geoff Johns','Gary Frank',NULL,NULL,'ECC Ediciones',NULL,'2023-05-09',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman: Earth One vol. 2 USA\r\nSe avecinan cambios en Gotham City. Entre la muerte del alcalde Oswald Cobblepot y la aparición de “Batman”, un nuevo amanecer arroja su luz sobre la ciudad, célebre por sus tinieblas y su corrupción. La nueva alcaldesa, Jessica Dent, y su hermano —el fiscal del distrito, Harvey Dent— se han unido al Caballero Oscuro y al detective Jim Gordon en su cruzada contra los criminales de Gotham. Pero surge una nueva amenaza... y le encanta jugar a los acertijos.\r\nSi respondéis mal, moriréis. Si respondéis correctamente...\r\nEsta segunda entrega del bestseller de las listas del New York Times, Batman: Tierra Uno, vuelve a unir al guionista Geoff Johns y al dibujante Gary Frank para presentar ante los lectores a algunos de los más infames antagonistas del Hombre Murciélago... pero con cambios y giros inesperados que construyen una mitología tan novedosa como increíble para uno de los personajes de ficción más populares que existen.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775414857151-jlfety.jpg','unread',0,NULL,NULL,'2026-04-05 18:47:38','2026-04-05 18:47:38',17,NULL,'rustica','[{"name":"Geoff Johns","role":"Guion"},{"name":"Gary Frank","role":"Dibujo"},{"name":"Jonathan Sibal","role":"Tinta"},{"name":"Brad Anderson","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(93,'DC Pocket #27','DC Pocket',27,NULL,'978-8-419-21016-6',NULL,'Jeph Loeb','Tim Sale',NULL,NULL,'ECC Ediciones',NULL,'2022-03-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Catwoman: When in Rome... núms. 1-6 USA\r\nSelina Kyle, más conocida como Catwoman, es la ladrona más reputada de Gotham City. Siempre en precario equilibrio sobre la línea que separa el bien del mal, tiene un misterioso origen que por fin decide investigar, emprendiendo para ello un viaje con destino a Roma. Con la colaboración de Edward Nigma, el ingenioso Acertijo, descubrirá que en la capital italiana le aguardan viejos conocidos y peligrosas situaciones relacionadas con un codiciado anillo y con las grandes familias criminales de los Falcone y los Verinni. Durante el transcurso de los acontecimientos narrados en Batman: Victoria oscura, la ladrona más famosa del noveno arte se ausentó de su ciudad. ¿Cuál fue su destino? ¿Qué razones impulsaron el inesperado viaje?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775414880436-ak5qdq.jpg','read',0,NULL,NULL,'2026-04-05 18:48:01','2026-04-06 11:04:38',17,NULL,'rustica','[{"name":"Jeph Loeb","role":"Guion"},{"name":"Tim Sale","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(94,'DC Pocket #55','DC Pocket',55,NULL,'978-8-419-58643-8',NULL,'Brian Augustyn','Mike Mignola',NULL,NULL,'ECC Ediciones',NULL,'2023-01-11',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Gotham by Gaslight USA\r\n¿Cómo sería la ciudad de Gotham de hace más de un siglo? En una época de misterio y superstición, ¿cómo reaccionaría la gente de Gotham a una extraña criatura de la noche, un vigilante vestido de murciélago temido por los culpables y los inocentes por igual? Algunos vivirían aterrorizados. Otros descansarían más tranquilos. Solo un hombre podría no darse cuenta de nada... un hombre con otras cuestiones de las que preocuparse. ¿Su nombre? Nadie lo sabe a ciencia cierta. La mayoría de la gente lo conoce tan solo como Jack. Jack el Destripador.\r\nBatman: Gotham a luz de gas recopila la clásica aventura del encuentro del Batman de la era victoriana con el carnicero de Whitechapel, junto con su aclamada secuela, El amo del futuro, donde el Caballero Oscuro se enfrenta con un profeta loco decidido a impedir que Gotham City entre en el siglo XX. Esta mezcla inolvidable de historia, fantasía, ciencia ficción y acción demuestra por qué Batman sigue siendo uno de los héroes más populares del mundo.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775414893512-ufhbbo.jpg','unread',0,NULL,NULL,'2026-04-05 18:48:14','2026-04-05 18:48:14',17,NULL,'rustica','[{"name":"Brian Augustyn","role":"Guion"},{"name":"Mike Mignola","role":"Dibujo"},{"name":"Eduardo Barreto","role":"Dibujo, Tinta"},{"name":"Philip Craig Russell","role":"Tinta"},{"name":"David Hornung","role":"Color"},{"name":"Steve Oliff","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(95,'DC Pocket #51','DC Pocket',51,NULL,'978-8-419-51888-0',NULL,'Chuck Dixon','Marcos Martín',NULL,NULL,'ECC Ediciones',NULL,'2022-11-22',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batgirl: Year One núms. 1-9, Batgirl/Robin Year One (extras) USA\r\n¡Una Chica Murciélago! Todo está listo para celebrar la Mascarada Millonaria, una gala benéfica organizada por la policía de Gotham, pero hay un aguafiestas: ¡Polilla Asesina! Y el criminal podría salirse con la suya de no ser por la irrupción de una nueva justiciera, una joven llamada Barbara Gordon que se dará a conocer como... ¿Batgirl? ¿Quién es en realidad y qué relación la une a Batman y Robin? En estas páginas se responde a esa pregunta y a muchas más mientras villanos como Luciérnaga y Blockbuster, y héroes como Canario Negro o Jason Bard, acompañan a la protagonista en su audaz debut junto a Chuck Dixon (Batman: Tierra de nadie), Scott Beatty, Marcos Martín y Álvaro López.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775414909459-pkkto0.jpg','unread',0,NULL,NULL,'2026-04-05 18:48:30','2026-04-05 18:48:30',17,NULL,'rustica','[{"name":"Chuck Dixon","role":"Guion"},{"name":"Scott Beatty","role":"Guion"},{"name":"Marcos Martín","role":"Dibujo"},{"name":"Álvaro López","role":"Tinta"},{"name":"Javier Rodríguez","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(96,'DC Pocket #46','DC Pocket',46,NULL,'978-8-419-35170-8',NULL,'Peter J. Tomasi','Jorge Jiménez',NULL,NULL,'ECC Ediciones',NULL,'2022-09-28',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Super Sons núms. 1 a 5 USA\r\n¡Los hijos de Superman y Batman asumen el protagonismo y forman un superequipo a regañadientes en esta nueva serie surgida del evento Renacimiento!\r\nCuando Robin (Damian Wayne) descubre una conexión entre una serie de crímenes misteriosos y los efectos secundarios del extraño y letal Virus Amazo, necesita que Superboy (Jonathan Kent) le ayude a investigar. Sin embargo, nuestros héroes se enteran de que un adolescente llamado Kid Amazo tiene planes que ponen en peligro a la Liga de la Justicia y se ven obligados a recurrir a quien menos esperan: ¡Lex Luthor!\r\nY aunque la extraña pareja de jóvenes héroes sobreviva a la participación de Luthor, tendrá que afrontar un peligro posiblemente peor: ¡la alianza entre Alfred Pennyworth, el tutor de Robin, y Lois Lane, la madre de Superboy!\r\nEl aplaudido guionista Peter J. Tomasi (Superman) y la superestrella del dibujo Jorge Jiménez (Sociedad de Tierra 2) lanzan una nueva y explosiva generación de aventuras en este primer volumen de Superhijos, que recopila los números del 1 al 5 de la popular serie original.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775414946700-hgdz9c.jpg','unread',0,NULL,NULL,'2026-04-05 18:49:07','2026-04-05 18:49:07',17,NULL,'rustica','[{"name":"Peter J. Tomasi","role":"Guion"},{"name":"Jorge Jiménez","role":"Dibujo, Tinta"},{"name":"Alisson Borges","role":"Dibujo, Tinta"},{"name":"Alejandro Sánchez","role":"Color"},{"name":"Hi-Fi Desing","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(97,'DC Pocket #127','DC Pocket',127,NULL,'978-8-410-33038-2',NULL,'Chuck Dixon','Stjepan Šejić',NULL,NULL,'ECC Ediciones',NULL,'2024-09-04',NULL,NULL,'Edición original: Joker: Devil',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775414985400-8z0uv5.jpg','unread',0,NULL,NULL,'2026-04-05 18:49:50','2026-04-05 18:49:50',17,NULL,'rustica','[{"name":"Chuck Dixon","role":"Guion"},{"name":"Paul Dini","role":"Guion"},{"name":"Stjepan Šejić","role":"Guion, Dibujo"},{"name":"Graham Nolan","role":"Dibujo"},{"name":"Yvel Guichet","role":"Dibujo"},{"name":"Scott Hanna","role":"Tinta"},{"name":"Aaron Sowd","role":"Tinta"},{"name":"Pat Garrahy","role":"Color"},{"name":"Heroic Age","role":"Color"},{"name":"Richard Horie","role":"Color"},{"name":"Tanya Horie","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(98,'DC Pocket #31','DC Pocket',31,NULL,'978-8-419-16321-9',NULL,'Geoff Johns','Gary Frank',NULL,NULL,'ECC Ediciones',NULL,'2022-05-03',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núms. 7 a 11, 0, 14 a 16 y 18 a 21 USA (historias de complemento)\r\nBilly Batson debe convertirse en... ¡Shazam!\r\nLa existencia del joven Billy Batson da un vuelco cuando un hechicero en apuros lo transforma en un ser casi omnipotente. Con apenas 15 años y el poder de un dios en las manos, la vida es un sueño del que el adolescente despierta brutalmente al encontrarse a su némesis oscura, el despiadado y poderosísimo Black Adam. Si Billy sobrevive al enfrentamiento, la Tierra tendrá un nuevo campeón. Si no, dará comienzo una era de dominación y terror.\r\nEl guionista Geoff Johns y el dibujante Gary Frank (equipo creativo de El origen de Superman y El Reloj del Juicio Final) se reúnen de nuevo en una vibrante historia publicada originalmente como complemento de la primera serie de la Liga de la Justicia aparecida tras los sucesos de Flashpoint ¡Un relato que revitaliza al Capitán Marvel y le devuelve el lugar que le corresponde en el panteón de DC Comics!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775415090841-3j05nr.jpg','unread',0,NULL,NULL,'2026-04-05 18:51:31','2026-04-05 18:51:31',17,NULL,'rustica','[{"name":"Geoff Johns","role":"Guion"},{"name":"Gary Frank","role":"Dibujo, Tinta"},{"name":"Brad Anderson","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(99,'DC Pocket #48','DC Pocket',48,NULL,'978-8-419-35171-5',NULL,'David S. Goyer','Don Kramer',NULL,NULL,'ECC Ediciones',NULL,'2022-10-25',NULL,NULL,replace('EDICIÓN ORIGINAL: JSA núms. 56-58, Hawkman núms. 23-25 USA \rLa Sociedad de la Justicia de América fue el primer supergrupo de la historia. Décadas después de su fundación, varias generaciones de héroes comparten aventuras. Y entre ellos, se encuentra un hombre que no termina de encajar. Se trata de Black Adam, que ahora pretende utilizar su inmenso poder para liberar el país que lo vio nacer. Y cuando algunos compañeros de grupo decidan acompañarlo a una misión en la que todo saldrá mal, se desatará una lucha fratricida de consecuencias imprevisibles.\rGeoff Johns, Rags Morales y otros autores nos presentan esta nueva edición de El reinado oscuro, una saga crucial para el mito de Black Adam que se publicó originalmente en las colecciones Hawkman y JSA.','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775415108288-v6hclv.jpg','unread',0,NULL,NULL,'2026-04-05 18:51:49','2026-04-05 18:51:49',17,NULL,'rustica','[{"name":"David S. Goyer","role":"Guion"},{"name":"Geoff Johns","role":"Guion"},{"name":"Don Kramer","role":"Dibujo"},{"name":"Leonard Kirk","role":"Dibujo"},{"name":"Rags Morales","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(100,'DC Pocket #59','DC Pocket',59,NULL,'978-8-419-62616-5',NULL,'Tom King','Andy Kubert',NULL,NULL,'ECC Ediciones',NULL,'2023-02-14',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Superman: Up in the Sky núms. 1 a 6 USA\r\n¡Superman echa a volar en esta emocionante aventura!\r\nUnos alienígenas han abducido a una niña llamada Alice, y Superman está decidido a localizarla en algún punto del cielo. El Hombre de Acero hará lo indecible durante la búsqueda y aceptará numerosos desafíos. Boxeará contra Mighto, evitará un ataque con misiles espaciales y combatirá junto al Sargento Rock en la Segunda Guerra Mundial.\r\nMientras esté fuera, se preocupará por los habitantes de Metropolis y también por Lois Lane, el amor de su vida, y no podrá evitar plantearse un dilema filosófico importante: ¿es correcto salvar a una sola persona en lugar de centrarse en salvar a miles? Superman: Arriba, en el cielo, obra del guionista Tom King (Batman, Strange Adventures) y del dibujante Andy Kubert (El Caballero Oscuro III: La raza superior, Flashpoint), recopila los números del 1 al 6 de la impactante serie original.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775415159761-6ubzzs.jpg','unread',0,NULL,NULL,'2026-04-05 18:52:40','2026-04-05 18:52:40',17,NULL,'rustica','[{"name":"Tom King","role":"Guion"},{"name":"Andy Kubert","role":"Dibujo"},{"name":"Sandra Hope","role":"Tinta"},{"name":"Brad Anderson","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(101,'DC Pocket #86','DC Pocket',86,NULL,'978-8-419-92004-1',NULL,'Will Pfeifer','Patrick Gleason',NULL,NULL,'ECC Ediciones',NULL,'2023-10-24',NULL,NULL,replace(replace('Edición original: Aquaman núm. 15-20 USA.\r\nWill Pfeifer y el dibujante Patrick Gleason unen fuerzas en una de las aventuras más aplaudidas de la historia contemporánea de Aquaman, un momento que demuestra la valía de este héroe no solo por sus poderes sino también por su capacidad para el liderazgo y la compasión. Sub Diego supone también la presentación de una heroína que compartirá esta época turbulenta con nuestro protagonista: ¡Aquagirl!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775415193455-1o5f2s.jpg','unread',0,NULL,NULL,'2026-04-05 18:53:15','2026-04-05 18:53:15',17,NULL,'rustica','[{"name":"Will Pfeifer","role":"Guion"},{"name":"Patrick Gleason","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(102,'DC Pocket #94','DC Pocket',94,NULL,'978-8-419-97215-6',NULL,'Grant Morrison','Frank Quitely',NULL,NULL,'ECC Ediciones',NULL,'2023-12-21',NULL,NULL,replace(replace('Contiene: JLA: Earth-2, Crime Syndicate #1 segunda historia (The Paranoid Titan), Crime Syndicate #2 segunda historia (An Owl in the Light), Crime Syndicate #3 segunda historia (Tools of the Trade), Crime Syndicate #5 segunda historia (The Quick and the Dead)\r\nTransportados a otra Tierra por un extraño visitante, los miembros de la Liga de la Justicia descubren un extraño reflejo del mundo que conocen. Todo es opuesto, la historia ha cambiado y la Tierra se ve regida por crueles versiones retorcidas de los héroes. En un mundo donde el mal siempre triunfa, ¿cómo puede la Liga de la Justicia lograr prevalecer?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775415205425-bhkh7p.jpg','unread',0,NULL,NULL,'2026-04-05 18:53:26','2026-04-05 18:53:26',17,NULL,'rustica','[{"name":"Grant Morrison","role":"Guion"},{"name":"Frank Quitely","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(103,'DC Pocket #102','DC Pocket',102,NULL,'978-8-410-10831-8',NULL,'Kurt Busiek','Carlos Pacheco',NULL,NULL,'ECC Ediciones',NULL,'2024-02-28',NULL,NULL,replace(replace('Contiene Superman núms. 654-658, 662-664, 667, Superman Annual 13 USA.\r\nSuperman ha salvado Metropolis y el mundo entero un sinfín de veces. Intergang, el Juguetero, Lex Luthor, Brainiac... Su lista de adversarios es larga e imponente. Y ahora, se enfrenta a un nuevo enemigo en la remota nación de Kazajistán. Sin embargo, en el pasado, Arión, el que fuera el hechi-cero supremo de Atlantis, presiente que el héroe está a punto de cometer un error que condenará a la Tierra a un futuro apocalíptico que conviene evitar a toda costa. El guionista Kurt Busiek y el dibujante Carlos Pacheco, acompañado por el entintador Jesús Merino, nos presentan La caída de Camelot, una saga repleta de acción que reflexiona sobre las consecuencias de los actos y los errores del hombre más poderoso del universo.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775415211894-udaw7w.jpg','unread',0,NULL,NULL,'2026-04-05 18:53:32','2026-04-05 18:53:32',17,NULL,'rustica','[{"name":"Kurt Busiek","role":"Guion"},{"name":"Carlos Pacheco","role":"Dibujo"},{"name":"Fabian Nicieza","role":"Guion"},{"name":"Renato Guedes","role":"Dibujo, Color"},{"name":"Jesús Merino","role":"Tinta"},{"name":"José Wilson Magalhaes","role":"Tinta"},{"name":"Dave Stewart","role":"Color"},{"name":"Alex Sinclair","role":"Color"},{"name":"Peter Pantazis","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(104,'DC Pocket #140','DC Pocket',140,NULL,'978-8-410-42993-2',NULL,'Geoff Johns','Gary Frank',NULL,NULL,'ECC Ediciones',NULL,'2024-12-04',NULL,NULL,replace(replace('Edición original: Action Comics núms. 844-846 y 851 USA, Action Comics annual núms. 10-11 USA\r\nSuperman siempre se ha considerado el último hijo de Krypton. Hasta ahora. Cuando un cohete se estrella en las calles de Metropolis, el Hombre de Acero rescata de su interior a un niño, al parecer kryptoniano, que Lois y él no dudan en adoptar. No obstante, formar parte de la familia Kent conlleva ciertos peligros, incluido que te acechen otros tres supervivientes del malogrado planeta natal de nuestro héroe. Pero ¿qué quieren el General Zod y sus secuaces del pequeño Chris? Geoff Johns y Adam Kubert unen fuerzas con el legendario director de cine Richard Donner en Superman: Último hijo, una historia épica y también emotiva que se completa con relatos breves dibujados por Arthur Adams, Gary Frank, Joe Kubert y otras estrellas del cómic.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775415249357-3fklc8.jpg','unread',0,NULL,NULL,'2026-04-05 18:54:12','2026-04-05 18:54:12',17,NULL,'rustica','[{"name":"Geoff Johns","role":"Guion"},{"name":"Richard Donner","role":"Guion"},{"name":"Gary Frank","role":"Dibujo"},{"name":"Rags Morales","role":"Dibujo"},{"name":"Tony S. Daniel","role":"Dibujo"},{"name":"Joe Kubert","role":"Dibujo"},{"name":"Phil Jimenez","role":"Dibujo"},{"name":"Adam Kubert","role":"Dibujo"},{"name":"Arthur Adams","role":"Dibujo"},{"name":"Eric Wight","role":"Dibujo"},{"name":"Stéphane Roux","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(105,'DC Pocket #87','DC Pocket',87,NULL,'978-8-419-92054-6',NULL,'Jill Thompson','Jill Thompson',NULL,NULL,'ECC Ediciones',NULL,'2023-11-07',NULL,NULL,replace(replace('Edición original: Wonder woman: The true amazon\r\nUna historia que define el carácter de un personaje... Hermosa, emotiva e inolvidable. En este original y singular acercamiento a los orígenes de Wonder Woman, la escritora e ilustradora Jill Thompson nos muestra a la princesa Diana como nunca antes la habíamos visto.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775484516466-hi7wa2.jpg','unread',0,NULL,NULL,'2026-04-05 18:55:35','2026-04-06 14:08:38',17,NULL,'rustica','[{"name":"Jill Thompson","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(106,'DC Pocket #103','DC Pocket',103,NULL,'978-8-410-10881-3',NULL,'Geoff Johns','Jim Lee',NULL,NULL,'ECC Ediciones',NULL,'2024-03-06',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League 1-6\r\n¡Unidos contra la invasión de Apokolips! Batman y Green Lantern han hecho un hallazgo extraordinario que augura la llegada de Darkseid, un dictador de otro mundo que ahora pretende conquistar la Tierra. Acompañados por Superman, Flash, Wonder Woman y Aquaman, estos héroes novatos deberán superar sus diferencias para salvarnos a todos. Y no estarán solos. A su lado, también se encontrará Victor Stone, un joven con un pasado trágico cuyos flamantes poderes están muy relacionados con Apokolips. El guionista Geoff Johns y el dibujante Jim Lee nos presentan el origen de la Liga de la Justicia, el grupo de superhéroes más poderoso del Universo DC.¡Empieza una nueva era dorada de la mano de los mejores personajes del mundo del cómic!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775485226604-dvi78p.jpg','unread',0,NULL,NULL,'2026-04-05 18:55:48','2026-04-06 14:20:28',17,24.95,'rustica','[{"name":"Geoff Johns","role":"Guion"},{"name":"Jim Lee","role":"Dibujo"},{"name":"Scott Williams","role":"Tinta"},{"name":"Sandra Hope","role":"Tinta"},{"name":"Mark Irwin","role":"Tinta"},{"name":"Joe Weems","role":"Tinta"},{"name":"Matt Banning","role":"Tinta"},{"name":"Alex Sinclair","role":"Color"},{"name":"Hi-Fi Desing","role":"Color"},{"name":"Gabe Eltaeb","role":"Color"},{"name":"Tony Aviña","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(107,'DC Pocket #69','DC Pocket',69,NULL,'978-8-419-73348-1',NULL,'Joshua Williamson','Howard Porter',NULL,NULL,'ECC Ediciones',NULL,'2023-05-16',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: The Flash núms. 70-75 USA\r\nBarry Allen está estancado. Como policía forense de Central City, su trabajo consiste en atrapar a los criminales después de que actúen. Parece que haya perdido la carrera incluso antes de abandonar la casilla de salida. Pero una noche, cae un rayo... y todo cambia. Electrocutado y cubierto de productos químicos, Barry sale del coma siendo más rápido que una bala, más rápido que el sonido y más rápido que nadie. Y más le vale, porque mientras aprende a usar unos poderes impresionantes, recorren su ciudad delincuentes de nuevo cuño como Tortuga, su antítesis, o James Jesse, también conocido como Trickster.\r\nEl guionista Joshua Williamson se une a Howard Porter para mostrarnos el pasado del Hombre más Rápido del Mundo en Flash: Año uno.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775415377031-k961xs.jpg','unread',0,NULL,NULL,'2026-04-05 18:56:20','2026-04-05 18:56:20',17,NULL,'rustica','[{"name":"Joshua Williamson","role":"Guion"},{"name":"Howard Porter","role":"Dibujo, Tinta"},{"name":"Hi-Fi Desing","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(108,'DC Compact #2','DC Compact',2,NULL,'979-1-370-13048-0',NULL,'Brian Michael Bendis','Nick Derington',NULL,NULL,'Panini Comics España',NULL,'2025-07-17',NULL,NULL,replace(replace('Contiene: Batman: Universe 1-6 y Batman Giant 3-14\r\n¡El Caballero Oscuro se embarca en una aventura global escrita por Brian Michael Bendis! Fuera de los límites de Gotham, tras la pista de un robo de Acertijo, Batman llega hasta el Lejano Oeste para encontrarse con el pistolero de leyenda Jonah Hex. Será el primero de varios encuentros superheroicos, necesarios para hacer frente al enemigo más brillante contra el que haya luchado jamás Batman','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775415425579-n5bgy4.jpg','read',0,NULL,NULL,'2026-04-05 18:57:08','2026-04-07 17:40:32',18,NULL,'bolsillo','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Nick Derington","role":"Dibujo, Tinta"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(109,'DC Compact #1','DC Compact',1,NULL,'978-8-410-51997-8',NULL,'Jeph Loeb','Tim Sale',NULL,NULL,'Panini Comics España',NULL,'2025-07-10',NULL,NULL,replace(replace('Contiene: Superman for All Seasons 1-4\r\nEn un pequeño pueblo de Kansas, un joven Clark Kent empieza a manifestar extraños poderes. Destinado a convertirse en el Hombre de Acero, tendrá mucho que asimilar en este clásico moderno que retrata las experiencias y aventuras que acabarían por transformar a un humilde muchacho de campo en el mayor héroe del mundo.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775466622133-c8e3la.jpg','read',0,NULL,NULL,'2026-04-05 18:57:19','2026-04-07 17:40:32',18,10.99,'bolsillo','[{"name":"Jeph Loeb","role":"Guion"},{"name":"Tim Sale","role":"Dibujo, Tinta"},{"name":"Bjarne Hansen","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(110,'DC Compact #3','DC Compact',3,NULL,'979-1-370-13147-0',NULL,'Alan Davis','Alan Davis',NULL,NULL,'Panini Comics España',NULL,'2025-08-21',NULL,NULL,replace(replace('Contiene: Justice League: The Nail 1-3\r\nUn clavo, el más insignificante de los objetos, impidió que Ma y Pa Kent encontrara a un bebé llegado de otra galaxia. Como consecuencia de ello, el mundo nunca ha conocido a Superman. En su lugar, los miembros de La Liga de la Justicia se alzan como los más poderosos protectores de la Tierra, pero, desde la fundación del grupo, un héroe destaca sobre el resto como su inspiración, su guía y su eje moral. El guionista y artista Alan Davis crea un mundo diferente, en que el poder y la ética serán puestos a prueba. Y todo por algo tan simple como un clavo.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775415441396-y6f0ch.jpg','read',0,NULL,NULL,'2026-04-05 18:57:22','2026-04-07 17:40:32',18,NULL,'bolsillo','[{"name":"Alan Davis","role":"Guion, Dibujo"},{"name":"Mark Farmer","role":"Tinta"},{"name":"Patricia Mulvihill","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(111,'DC Compact #4','DC Compact',4,NULL,'979-1-370-13178-4',NULL,'Andy Diggle','Jock',NULL,NULL,'Panini Comics España',NULL,'2025-09-18',NULL,NULL,replace(replace('Contiene: Green Arrow: Year One 1-6\r\n¡El origen definitivo del Arquero Esmeralda! Oliver Queen, un millonario aficionado a las emociones fuertes no se preocupa por nadie ni por nada, incluido él mismo. Tras ser traicionado por uno de sus empleados de confianza y abandonado en una isla desierta, descubrirá algo que sí le importa: ¡sobrevivir! Armado con un arco y flechas hechas a mano, por primera vez en su vida debe encontrar la fuerza dentro de sí mismo para buscar no sólo venganza, sino justicia.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775415444681-tinsnz.jpg','read',0,NULL,NULL,'2026-04-05 18:57:25','2026-04-07 17:40:32',18,NULL,'bolsillo','[{"name":"Andy Diggle","role":"Guion"},{"name":"Jock","role":"Dibujo, Tinta"},{"name":"David Baron","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(112,'DC Compact #5','DC Compact',5,NULL,'979-1-370-13234-7',NULL,'Darwyn Cooke','Darwyn Cooke',NULL,NULL,'Panini Comics España',NULL,'2025-10-16',NULL,NULL,'Contiene Batman: Ego, Batman: Gotham Knights 23 y 33, Catwoman: Selina',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775415448793-yu3ajo.jpg','read',0,5,NULL,'2026-04-05 18:57:29','2026-04-12 19:09:01',18,NULL,'rústica','[{"name":"Darwyn Cooke","role":"Guion, Dibujo, Tinta, Color"},{"name":"Paul Grist","role":"Guion"},{"name":"Amanda Conner","role":"Guion, Dibujo"},{"name":"Jimmy Palmiotti","role":"Guion"},{"name":"Tim Sale","role":"Guion, Dibujo, Tinta, Color"},{"name":"Bill Wray","role":"Dibujo, Tinta"},{"name":"Jonathan Babcock","role":"Tinta"},{"name":"Rick Parker","role":"Tinta"},{"name":"Richard Starkings","role":"Tinta"},{"name":"John H. Hill","role":"Tinta"},{"name":"Matt Hollingsworth","role":"Guion, Color"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(113,'DC Compact #10','DC Compact',10,NULL,'979-1-370-13543-0',NULL,'Christopher Moeller','Christopher Moeller',NULL,NULL,'Panini Comics España',NULL,'2026-03-19',NULL,NULL,replace(replace('Contiene: JLA: A League of One y JLA Classified: Cold Steel 1-2 USA \r\nLa épica obra escrita y pintada por Christopher Moeller reunida en un solo volumen. Una profecía vaticina la muerte de la Liga de la Justicia en una batalla contra un dragón. Wonder Woman ha de vencer ella misma al equipo antes de enfrentarse a la criatura. A continuación, el equipo acude al espacio con la misión de detener un conflicto entre dos facciones en guerra.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775417411004-o0scb9.jpg','unread',0,NULL,NULL,'2026-04-05 18:57:34','2026-04-05 19:30:12',18,NULL,'bolsillo','[{"name":"Christopher Moeller","role":"Guion, Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(114,'Marvel Essentials #4','Marvel Essentials',4,NULL,'978-8-410-51365-5',NULL,'Cullen Bunn','Ramon Rosanas',NULL,NULL,'Panini Comics España',NULL,'2024-07-11',NULL,NULL,replace(replace('Contiene Night Of The Living Deadpool 1-4 y Return Of The Living Deadpool 1-4\r\nMasacre despierta del coma para descubrir que el apocalipsis zombi ha tenido lugar. Cullen Bunn, uno de los más importantes guionistas del Mercenario Bocazas, se une a Ramón Rosanas y Nik Virella en una historia que homenajea “La noche de los muertos vivientes”.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775415475951-v8aoqw.jpg','read',0,NULL,NULL,'2026-04-05 18:57:59','2026-04-07 17:40:32',19,NULL,'rustica','[{"name":"Cullen Bunn","role":"Guion"},{"name":"Ramon Rosanas","role":"Dibujo, Tinta, Color"},{"name":"Nik Virella","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(115,'Marvel Essentials #18','Marvel Essentials',18,NULL,'978-8-410-51755-4',NULL,'Jeph Loeb','Tim Sale',NULL,NULL,'Panini Comics España',NULL,'2025-02-13',NULL,NULL,replace(replace('Contiene: Daredevil: Yellow 1-6\r\nEn esta aclamada reconstrucción de los primeros días del Diablo Guardián, el equipo ganador del Premio Eisner formado por Jeph Loeb y Tim Sale (Spiderman: Azul, Batman: El largo Halloween) ofrece una extraordinaria aventura superheroica salpicada con un toque de comedia romántica. Esta edición de Daredevil: Amarillo contiene un completo cuaderno de bocetos de Tim Sale y una introducción a cargo de Stan Lee, el legendario autor detrás de la creación del Universo Marvel.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775466391650-onqe7u.jpg','read',0,5,NULL,'2026-04-05 18:59:09','2026-04-07 17:40:32',19,9.99,'rustica','[{"name":"Jeph Loeb","role":"Guion"},{"name":"Tim Sale","role":"Dibujo, Tinta"},{"name":"Matt Hollingsworth","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(116,'Justicia','Justicia',NULL,NULL,'978-8-408-09591-0',NULL,'Alex Ross','Alex Ross',NULL,NULL,'Booket',NULL,'2010-11-01',NULL,NULL,replace(replace('Justice #1-12\r\nEn esta impactante y excelente maxiserie de 12 capítulos, Alex Ross, Jim Krueger y Doug Braithwaite presentan su versión de lo que es la historia definitiva de la Liga de la Justicia. Amparados en una encarnación clásica de la JLA, todos estos autores relatan la conspiración más destructiva de todas cuando los villanos del Universo DC se alían para acabar con la JLA justo cuando menos se lo esperan.','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775474707605-2ww290.jpg','read',0,NULL,NULL,'2026-04-05 19:00:23','2026-04-06 15:11:54',NULL,NULL,'Rústica','[{"name":"Alex Ross","role":"Guion, Dibujo, Tinta"},{"name":"Jim Krueger","role":"Guion"},{"name":"Doug Braithwaite","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(117,'Carbono & Silicio','Carbono & Silicio',NULL,NULL,'978-8-418-26605-8',NULL,'Mathieu Bablet','Mathieu Bablet',NULL,NULL,'Dibbuks',NULL,'2023-04-20',NULL,NULL,'Año 2048. Carbono y Silicio, las últimas creaciones de los laboratorios de la Fundación Tomorrow, son prototipos de una nueva generación de robots diseñados para cuidar personas ancianas. Conocedores de que el final de su vida ya está estipulada, están deseosos de descubrir el mundo exterior. Mientras intentan escapar se terminan separándose. Cada uno de ellos continúa con su propia vida y libra una batalla de siglos para encontrar su lugar en un planeta que está plagado de desastres climáticos, graves problemas políticos y humanitarios.',NULL,NULL,256,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775466449121-u41qil.jpg','read',0,5,NULL,'2026-04-06 08:10:41','2026-04-06 11:04:02',NULL,31,NULL,'[{"name":"Mathieu Bablet","role":"Guion, Dibujo, Tinta, Color"},{"name":"Cathy Fernandez","role":"Color"},{"name":"Carla de Almeida","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(118,'Absolute Batman #1','Absolute Batman',1,NULL,'9773081286007-00001',NULL,'Scott Snyder','Nick Dragotta',NULL,NULL,'Panini Comics España',NULL,'2025-04-03',NULL,NULL,replace(replace('Contiene: Absolute Batman 1\r\nEs uno de los héroes más icónicos héroes de DC, pero sin su mansión, sin su dinero, sin su mayordomo… ¡Lo que queda es el Caballero Oscuro en su versión Absolute! Prepárate para esta reinterpretación de la mitología de Batman y, también, de un viejo conocido, Alfred Pennyworth.','\r',char(13)),'\n',char(10)),NULL,NULL,24,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775463076195-nxdck3.jpg','read',0,NULL,NULL,'2026-04-06 08:11:18','2026-04-06 11:03:13',21,3.3,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Nick Dragotta","role":"Dibujo, Tinta"},{"name":"Frank Martin","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(119,'Absolute Batman #2','Absolute Batman',2,NULL,'9773081286007-00002',NULL,'Scott Snyder','Nick Dragotta',NULL,NULL,'Panini Comics España',NULL,'2025-05-08',NULL,NULL,replace(replace('Contiene: Absolute Batman 2\r\nBatman nació de un acto de violencia, una horrible tragedia que deformó la trayectoria de su futuro. Pero, después de que cierto agente del MI6 observe la solitaria vida de Bruce Wayne, descubrirá las interconexiones entre la hermética vida del héroe y las múltiples capas de la banda de la Máscara Negra... Presencia la lucha de intelecto y poderío físico entre Batman... y Alfred Pennyworth.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775463098613-wue3ri.jpg','read',0,NULL,NULL,'2026-04-06 08:11:39','2026-04-06 11:03:51',21,NULL,'Grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Nick Dragotta","role":"Dibujo, Tinta"},{"name":"Frank Martin","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(120,'Absolute Batman #3','Absolute Batman',3,NULL,'9773081286007-00003',NULL,'Scott Snyder','Nick Dragotta',NULL,NULL,'Panini Comics España',NULL,'2025-06-05',NULL,NULL,replace(replace('Contiene: Absolute Batman 3\r\nBatman y Alfred han formado una alianza, pero la Máscara Negra también ha hecho nuevos amigos… y llegan ahora a Gotham para sembrar el caos absoluto. Descubre además el oscuro secreto que golpeará a Bruce y le hará cuestionarse todo.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775463100342-foboy7.jpg','read',0,NULL,NULL,'2026-04-06 08:11:41','2026-04-06 11:03:48',21,NULL,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Nick Dragotta","role":"Dibujo, Tinta"},{"name":"Frank Martin","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(121,'Absolute Batman #4','Absolute Batman',4,NULL,'9773081286007-00004',NULL,'Scott Snyder','Gabriel Hernández Walta',NULL,NULL,'Panini Comics España',NULL,'2025-07-03',NULL,NULL,replace(replace('Contiene: Absolute Batman 4\r\nGabriel Hernández Walta se une a la serie estrella del año para descubrirnos el origen de Batman, explorar el pasado de Bruce Wayne y señalar hacia un futuro con un potencial aún más grande. ¿Cómo llegó a establecerse como una enorme fuerza de la naturaleza? ¿Y cómo, a raíz de su trágica infancia y el consejo de su padre, se convirtió en lo que es?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775463102182-9rso2w.jpg','read',0,NULL,NULL,'2026-04-06 08:11:42','2026-04-06 11:03:45',21,NULL,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Frank Martin","role":"Color"},{"name":"Gabriel Hernández Walta","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(122,'Absolute Batman #5','Absolute Batman',5,NULL,'9773081286007-00005',NULL,'Scott Snyder','Nick Dragotta',NULL,NULL,'Panini Comics España',NULL,'2025-08-07',NULL,NULL,replace(replace('Contiene: Absolute Batman 5\r\nCon las vidas de sus amigos en juego, ¿podrá un Wayne molido y derrotado comprometerse a sí mismo y a sus valores ante Máscara Negra? ¿Y qué tendrá esto que ver con el alcalde James Gordon y su relación con el joven Bruce? Todo esto y más en la penúltima entrega del arco inicial de Absolute Batman.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775463103668-hlle7l.jpg','read',0,NULL,NULL,'2026-04-06 08:11:44','2026-04-06 11:03:42',21,NULL,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Nick Dragotta","role":"Dibujo, Tinta"},{"name":"Frank Martin","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(123,'Absolute Batman #6','Absolute Batman',6,NULL,'9773081286007-00006',NULL,'Scott Snyder','Nick Dragotta',NULL,NULL,'Panini Comics España',NULL,'2025-09-04',NULL,NULL,replace(replace('Contiene: Absolute Batman 6\r\nLa conclusión del primer arco argumental. Bruce Wayne debe echar abajo los planes de Máscara Negra. ¿Podrá sin la ayuda de Alfred Pennyworth? Y sus amigos de la infancia, Edward Nygma, Waylon Jones, Harvey Dent, Oswald Cobblepot... ¿qué rol tendrán en el legado de Batman?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775463106191-5vnhd7.jpg','read',0,NULL,NULL,'2026-04-06 08:11:47','2026-04-06 11:03:39',21,NULL,'Grapa 24 pp','[{"name":"Scott Snyder","role":"Guion"},{"name":"Nick Dragotta","role":"Dibujo, Tinta"},{"name":"Frank Martin","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(124,'Absolute Batman #7','Absolute Batman',7,NULL,'9773081286007-00007',NULL,'Scott Snyder','Marcos Martín',NULL,NULL,'Panini Comics España',NULL,'2025-10-02',NULL,NULL,replace(replace('Contiene: Absolute Batman 7\r\n¡Un número muy especial, dibujado por el español Marcos Martín! Mientras Gotham City se congela, descubrimos la verdad sobre el joven Victor Fries, científico ocasional cuyo experimento lo alteró todo y que mantiene conexiones con el misterioso Joker.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775463108083-b0fvtf.jpg','read',0,NULL,NULL,'2026-04-06 08:11:48','2026-04-06 11:03:36',21,NULL,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Marcos Martín","role":"Dibujo, Tinta"},{"name":"Munsta Vicente","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(125,'Absolute Batman #8','Absolute Batman',8,NULL,'9773081286007-00008',NULL,'Scott Snyder','Marcos Martín',NULL,NULL,'Panini Comics España',NULL,'2025-11-06',NULL,NULL,replace(replace('Contiene: Absolute Batman 8\r\nGotham se encuentra sumida en las gélidas manos de Mr. Freeze. Batman tendrá que luchar como nunca contra esta nueva amenaza. Y, al final, ¿qué terrorífica verdad saldrá a la luz sobre Arca M y... el Joker?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775463109624-ffrmfd.jpg','read',0,NULL,NULL,'2026-04-06 08:11:50','2026-04-06 11:03:33',21,NULL,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Marcos Martín","role":"Dibujo, Tinta"},{"name":"Munsta Vicente","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(126,'Absolute Batman #9','Absolute Batman',9,NULL,'9773081286007-00009',NULL,'Scott Snyder','Nick Dragotta',NULL,NULL,'Panini Comics España',NULL,'2025-12-04',NULL,NULL,replace(replace('Contiene: Absolute Batman 9\r\n¡Comienza un nuevo arco! El Arca M ha nacido para proteger a los más necesitados... o al menos así se presenta, pero su verdadero objetivo consiste en la creación del mal encarnado. Bruce trata de infiltrarse y dar con sus secretos, pero un nuevo villano de Gotham llegará para ocuparse de él... un viejo adversario de Alfred... un hombre conocido como Bane.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775463111272-vbsr6n.jpg','read',0,NULL,NULL,'2026-04-06 08:11:51','2026-04-06 11:03:30',21,NULL,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Nick Dragotta","role":"Dibujo, Tinta"},{"name":"Frank Martin","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(127,'Absolute Batman #10','Absolute Batman',10,NULL,'9773081286007-00010',NULL,'Scott Snyder','Nick Dragotta',NULL,NULL,'Panini Comics España',NULL,'2026-01-08',NULL,NULL,replace(replace('Contiene: Absolute Batman 10\r\nBruce Wayne se encuentra atrapado en los horrores del Arca M mientras su mejor amigo, Waylon Jones, se enfrenta a una tortura inimaginable, pero a Batman le espera algo aún más terrorífico, más que cualquier cosa a la que haya hecho frente hasta ahora: la verdadera forma de Bane, y cómo éste planea quebrar al héroe.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775463112621-mmbvhq.jpg','read',0,NULL,NULL,'2026-04-06 08:11:53','2026-04-06 11:03:28',21,NULL,'Grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Nick Dragotta","role":"Dibujo, Tinta"},{"name":"Frank Martin","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(128,'Absolute Batman #11','Absolute Batman',11,NULL,'9773081286007-00011',NULL,'Scott Snyder','Clay Mann',NULL,NULL,'Panini Comics España',NULL,'2026-02-05',NULL,NULL,replace(replace('Contiene: Absolute Batman 11\r\nBruce Wayne se encuentra atrapado en los horrores del Arca M mientras su mejor amigo, Waylon Jones, se enfrenta a una tortura inimaginable, pero a Batman le espera algo aún más terrorífico, más que cualquier cosa a la que haya hecho frente hasta ahora: la verdadera forma de Bane, y cómo éste planea quebrar al héroe.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775463114419-a6ddmq.jpg','read',0,NULL,NULL,'2026-04-06 08:11:55','2026-04-06 11:03:25',21,NULL,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Clay Mann","role":"Dibujo, Tinta"},{"name":"Ivan Plascencia","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(129,'Absolute Batman #12','Absolute Batman',12,NULL,'9773081286007-00012',NULL,'Scott Snyder','Nick Dragotta',NULL,NULL,'Panini Comics España',NULL,'2026-03-05',NULL,NULL,replace(replace('Contiene: Absolute Batman 12 y 13\r\nA merced de Bane. Batman ha visto días mejores, pero conserva su fortaleza de cuerpo y mente. ¿Cuánto tiempo podrá aguantar el brutal ataque de la mole inhumana conocida como Bane? Llega el enfrentamiento final. Si Batman no logra vencer a la bestia, quedará atrapado para siempre en el Arca M.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775464512887-4lpts0.jpg','read',0,NULL,NULL,'2026-04-06 08:11:57','2026-04-06 11:03:19',21,3.3,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Nick Dragotta","role":"Dibujo, Tinta"},{"name":"Frank Martin","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(130,'Absolute Batman #13','Absolute Batman',13,NULL,'9773081286007-00013',NULL,'Scott Snyder','Nick Dragotta',NULL,NULL,'Panini Comics España',NULL,'2026-04-01',NULL,NULL,replace(replace('Contiene: Con Absolute Batman 14\r\nScott Snyder y Nick Dragotta cierran su arco más impactante hasta la fecha con un enfrentamiento que no te puedes perder: ¡Batman y Catwoman contra Bane! Después de que se asiente el polvo... ¿qué futuro tendrá Batman, si es que tiene uno?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775466401354-slkro7.jpg','read',0,NULL,NULL,'2026-04-06 08:11:58','2026-04-07 17:40:32',21,NULL,'Grapa 24 pp','[{"name":"Scott Snyder","role":"Guion"},{"name":"Nick Dragotta","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(131,'Doggy Bags #1','Doggy Bags',1,NULL,'978-8-415-85075-5',NULL,'RUN','RUN',NULL,NULL,'Dibbuks',NULL,'2015-05-03',NULL,NULL,replace(replace('El primer tomo de una nueva serie pulp fuera de serie. Tres historias al más puro estilo de los cómics para adultos de los cincuenta, llenas de salvaje violencia. En este primer volumen, Singelin nos introducirá en una banda de moteros, Maudoux nos trasladará a Japón para luchar contra sicarios y Run nos mostrará lo duro que puede ser el desierto cuando te persigue la policía. Cada uno de ellos nos ofrece una historieta fiel a su característico estilo pero que consigue forjar un volumen compacto y coherente en el que las palabras horror, terror, sangriento y extraño no son baldías. Salvaje, brutal y... delicioso.\r\nFresh Flesh & Hot Chrome / Masiko / Vivo o muerto','\r',char(13)),'\n',char(10)),NULL,NULL,112,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775473615662-fj9wge.jpg','read',0,3,NULL,'2026-04-06 11:06:58','2026-04-06 14:13:31',22,14,'Rústica','[{"name":"RUN","role":"Guion, Dibujo, Tinta"},{"name":"Guillaume Singelin","role":"Guion, Dibujo, Tinta"},{"name":"Florent Maudoux","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(132,'Doggy Bags #2','Doggy Bags',2,NULL,'978-8-415-85099-1',NULL,'RUN','Guillaume Singelin',NULL,NULL,'Dibbuks',NULL,'2016-02-09',NULL,NULL,replace(replace('Elwood and the 40 Freak Bitches / The Border / Vuelo Express 666 USA || P.V.P.: 14,00 €\r\nManteniendo el espíritu y el estilo del primer tomo, Run vuelve a la carga con más violencia, más sangre y menos censura si cabe. En el segundo tomo acompañaremos a un asesino en su misión de salvar a la humanidad de pecadoras del infierno, vigilaremos la frontera para que no se cuele ningún indeseado e intentaremos sobrevivir a un sangriento vuelo comercial. Tres historias brutales de la mano de grandes autores del cómic actual.','\r',char(13)),'\n',char(10)),NULL,NULL,112,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775473632112-uq3cz5.jpg','read',0,3,NULL,'2026-04-06 11:07:13','2026-04-06 14:13:42',22,14,'Rústica','[{"name":"RUN","role":"Guion"},{"name":"Guillaume Singelin","role":"Dibujo"},{"name":"Mathieu Bablet","role":"Dibujo"},{"name":"Kieran","role":"Dibujo"},{"name":"Antoine Ozanam","role":"Guion"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(133,'Doggy Bags #3','Doggy Bags',3,NULL,'978-8-416-50737-5',NULL,'Florent Maudoux','Florent Maudoux',NULL,NULL,'Dibbuks',NULL,'2016-10-26',NULL,NULL,replace(replace('Ciudad de Juárez, capital mundial del crimen, el narcotráfico y los secuestros es el lugar en el que se ambienta este monográfico dedicado a México. En este tercer volumen damos la bienvenida a tres nuevos autores. Gasparutto y Giugiano nos traen &quot;El día de los muertos&quot;, una historia ambientada en esa festividad y en la que un policía orquesta la venganza contra el cartel más temido de la ciudad. Neyef nos ofrece junto a Run la historia &quot;Room 213&quot;. Un líder de un famoso cartel es perseguido por la Santa Muerte para que pague por los crímenes cometidos. La tercera historia recae sobre Florent Maudoux. Disfrutamos una vez más del magnifico personaje de Masiko que buscará revancha a través de la exótica y sensual danza de los 13 velos.\r\nEl Día de los Muertos / La danza de los 13 velos / Room 213','\r',char(13)),'\n',char(10)),NULL,NULL,112,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775473635468-reo1g2.jpg','unread',0,NULL,NULL,'2026-04-06 11:07:16','2026-04-06 11:07:16',22,14,'Rústica','[{"name":"RUN","role":""},{"name":"Guillaume Singelin","role":""},{"name":"Florent Maudoux","role":"Guion, Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(134,'Doggy Bags #4','Doggy Bags',4,NULL,'978-8-416-50774-0',NULL,'RUN','RUN',NULL,NULL,'Dibbuks',NULL,'2017-06-15',NULL,NULL,'La familia de Doggy Bags sigue creciendo con la incorporación de dos nuevos autores. Esta vez son los El Diablo y Nicolab los que se unen con su historia Selection, en el que un traficante de armas de gran renombre debe hacer frente a la ley de la selección natural después de naufragar en una isla desierta. Run toma las riendas de guión y dibujo en Lady in White, en el que perturbadoras desapariciones tienen lugar en las carreteras de Oregón. Singelin regresa en una historia de militares, Geronimo, que retrata el asesinato del líder de Al Qaeda por un equipo de Navy Seals....',NULL,NULL,112,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775473637634-z4lshx.jpg','unread',0,NULL,NULL,'2026-04-06 11:07:18','2026-04-06 11:07:18',22,14,'Rústica','[{"name":"RUN","role":"Guion, Dibujo"},{"name":"Guillaume Singelin","role":"Dibujo"},{"name":"Nicolab","role":"Dibujo"},{"name":"El Diablo","role":"Guion"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(135,'Creepshow #1','Creepshow',1,NULL,'978-8-410-46333-2',NULL,'Paul Dini','Chris Burnham',NULL,NULL,'Moztros',NULL,'2025-02-27',NULL,NULL,replace(replace('¡LA DIVERSIÓN Y LOS SUSTOS MÁS GRANDES!\r\nEste fenómeno mundial, basado en la exitosa serie televisiva, reúne diez historias aterradoras de los mejores talentos del cómic que te harán morir de miedo.\r\n¿Qué es eso que acecha en la oscuridad? ¿Quién se te acerca por la espalda? ¿Y por qué parece que la muerte se aproxima lentamente? Ah, claro, es… ¡Creepshow!\r\nCon historias de: Paul Dini, Chris Burham, Erica Henderson, Francesco Francavilla, Kyle Starks ¡y muchos más!','\r',char(13)),'\n',char(10)),NULL,NULL,80,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775473691725-pgvipr.jpg','read',0,3,NULL,'2026-04-06 11:08:13','2026-04-06 14:13:03',23,20,'tapa dura','[{"name":"Paul Dini","role":"Guion"},{"name":"Chris Burnham","role":"Guion, Dibujo, Tinta"},{"name":"John McCrea","role":"Dibujo, Tinta"},{"name":"Steve Langford","role":"Guion"},{"name":"Erica Henderson","role":"Dibujo, Tinta, Color"},{"name":"Francesco Francavilla","role":"Guion, Dibujo, Tinta, Color"},{"name":"Kyle Starks","role":"Guion"},{"name":"Adriano Lucas","role":"Color"},{"name":"Mike Spicer","role":"Color"},{"name":"David Lapham","role":"Guion, Dibujo, Tinta"},{"name":"Maria Lapham","role":"Guion"},{"name":"Trish Mullvihill","role":"Color"},{"name":"Steve Foxe","role":"Guion"},{"name":"L. Marlow Francavilla","role":"Guion"},{"name":"Ariela Kristantina","role":"Guion"},{"name":"Jorge Corona","role":"Dibujo, Tinta"},{"name":"Jean-Francois Beaulieu","role":"Color"},{"name":"Fran Galán","role":"Dibujo, Tinta, Color"},{"name":"Henry Barajas","role":"Guion"},{"name":"Dani","role":"Dibujo, Tinta"},{"name":"Brad Simpson","role":"Color"},{"name":"Steve Orlando","role":"Guion"},{"name":"Marianna Ignazzi","role":"Dibujo, Tinta"},{"name":"Fabiana Mascolo","role":"Color"},{"name":"Clay McLeod Chapman","role":"Guion"},{"name":"Anwita Citriya","role":"Dibujo, Tinta"},{"name":"Jordie Bellaire","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(136,'Creepshow #2','Creepshow',2,NULL,'978-8-410-46350-9',NULL,'Garth Ennis','Becky Cloonan',NULL,NULL,'Moztros',NULL,'2025-05-22',NULL,NULL,replace(replace('Contenido: Creepshow vol. 2 #1-5\r\n¡ESTAR ATERRADO NUNCA FUE TAN DIVERTIDO… ¡OTRA VEZ!\r\n¡La exitosa antología de terror basada en la icónica serie de TV regresa más escalofriante que nunca! ¡Nuestro espeluznante anfitrión desafía a los autores más destacados de los cómics para asustar a sus lectores como nunca antes!\r\nY con un reparto de perturbadores artistas como GARTH ENNIS, BECKY CLOONAN, MICHAEL WALSH, ZOE THOROGOOD y SALADIN AHMED, ¡los lectores podrían morir de espanto antes de terminar el libro!\r\nNO DIGAS QUE NO TE LO ADVERTIMOS.','\r',char(13)),'\n',char(10)),NULL,NULL,80,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775473779284-aq0trv.jpg','unread',0,NULL,NULL,'2026-04-06 11:09:41','2026-04-06 11:09:41',23,20,'rústica','[{"name":"Garth Ennis","role":"Guion"},{"name":"Becky Cloonan","role":"Dibujo, Tinta"},{"name":"Lee Loughridge","role":"Color"},{"name":"Michael Walsh","role":"Guion, Dibujo, Tinta, Color"},{"name":"Nick Dragotta","role":"Guion, Dibujo, Tinta"},{"name":"Jean-Francois Beaulieu","role":"Color"},{"name":"Saladin Ahmed","role":"Guion"},{"name":"Artyom Topilin","role":"Dibujo, Tinta, Color"},{"name":"Phil Hester","role":"Guion, Dibujo, Tinta"},{"name":"Mike Spicer","role":"Color"},{"name":"Dan Watters","role":"Guion"},{"name":"Abigail Larson","role":"Dibujo, Tinta, Color"},{"name":"Joel Farrelly","role":"Guion"},{"name":"Goran Sudzuka","role":"Dibujo, Tinta"},{"name":"Ive Svorcina","role":"Co