INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(137,'Creepshow #3','Creepshow',3,NULL,'978-8-410-46377-6',NULL,'Chip Zdarsky','Kagan McLeod',NULL,NULL,'Moztros',NULL,'2025-07-10',NULL,NULL,replace(replace('¡En esta nueva entrega de la antología nominada al premio Eisner, el Creep encuentra nuevos modos de hacer incluso más terroríficas las peores pesadillas que podamos imaginar!\r\nEsta vez, con la ayuda de un elenco de autores verdaderamente escalofriante, en el que destacan los multipremiados Chip Zdarsky y Kami Garcia, los nominados a los premios Eisner Jorge Fornés, James Stokoe y Mike Carey, el ganador del premio Oscar John Ridley o el cineasta español Eugenio Mira (','\r',char(13)),'\n',char(10)),NULL,NULL,80,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775473815174-zhcfgj.jpg','unread',0,NULL,NULL,'2026-04-06 11:10:16','2026-04-06 11:10:16',23,20,'tapa dura','[{"name":"Chip Zdarsky","role":"Guion"},{"name":"Kagan McLeod","role":"Dibujo"},{"name":"Eugenio Mira","role":"Guion"},{"name":"Jorge Fornés","role":"Dibujo"},{"name":"Jordie Bellaire","role":"Color"},{"name":"Chris Condon","role":"Guion"},{"name":"Martín Morazzo","role":"Dibujo"},{"name":"Chris O''Halloran","role":"Color"},{"name":"Mike Carey","role":"Guion"},{"name":"Mark Torres","role":"Dibujo"},{"name":"Ed Brisson","role":"Guion"},{"name":"Kael Ngu","role":"Dibujo"},{"name":"James Stokoe","role":"Guion, Dibujo"},{"name":"John Ridley","role":"Guion"},{"name":"Stefano Raffaele","role":"Dibujo"},{"name":"Romulo Fajardo Jr.","role":"Color"},{"name":"John Arcudi","role":"Guion"},{"name":"Shawn McManus","role":"Dibujo"},{"name":"Acky Bright","role":"Guion, Dibujo"},{"name":"Kami Garcia","role":"Guion"},{"name":"Isaac Goodhart","role":"Dibujo"},{"name":"Miquel Muerto","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(138,'Monstruos de Universal #1','Monstruos de Universal',1,NULL,'978-8-419-90392-1',NULL,'James Tynion IV','Martin Simmonds',NULL,NULL,'Moztros',NULL,'2024-07-18',NULL,NULL,replace('Cuando el Dr. John Seward le permite el ingreso a su asilo a un extraño paciente llamado Renfield, un pobre hombre desquiciado con la mente totalmente perturbada, este comienza a contarle historias sobre un demonio que se ha instalado en la casa de al lado para aterrorizarlo. Mientras el Dr. Seward intenta ponerle lógica a lo imposible y comprender el relato de esta alma torturada... su hija será una de las próximas presas del retorcido y temible Conde Drácula! El talentoso equipo creativo detrás de El Departamento de la Verdad, formado por James Tynion IV (El Armario, W0rldtr33) y Martin Simmonds (Razorblades, Patrulla X), vuelve a unirse para contarnos una nueva versión de la historia del monstruo que lo empezó todo.\rContiene: Universal Monsters: Dracula 1-4.','\r',char(13)),NULL,NULL,128,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775484723591-ah0rjg.jpg','read',0,3,NULL,'2026-04-06 14:10:56','2026-04-06 14:13:23',25,16.5,'Rústica','[{"name":"James Tynion IV","role":"Guion"},{"name":"Martin Simmonds","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(139,'Monstruos de Universal #2','Monstruos de Universal',2,NULL,'978-8-410-46324-0',NULL,'Ram V','Matthew Roberts',NULL,NULL,'Moztros',NULL,'2025-01-23',NULL,NULL,replace('Años después de los sucesos de la película «The Creature from the Black Lagoon», la periodista Kate Marsden persigue a un infame asesino en serie en el corazón del Amazonas. Siguiendo el rastro de este perturbado, pronto se enfrenta a una nueva amenaza inesperada. Pero, ¿es un aliado o un enemigo? ¿O acaso es simplemente el monstruo de la Laguna Negra? Los aclamados creadores Dan Watters («Home Sick Pilots»), Ram V («Batman: Detective Comics») y Matthew Roberts («Creepshow»), junto con el colorista Dave Stewart, presentan una nueva historia épica protagonizada por la criatura clásica de la Universal Pictures.\rContiene: Universal Monsters: The Creature from the Black Lagoon Lives! 1-5.','\r',char(13)),NULL,NULL,128,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775484682566-9txio4.jpg','read',0,2,NULL,'2026-04-06 14:11:26','2026-04-06 14:13:16',25,18.9,'tapa dura','[{"name":"Ram V","role":"Guion"},{"name":"Dan Watters","role":"Guion"},{"name":"Matthew Roberts","role":"Dibujo, Tinta"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(140,'Monstruos de Universal #3','Monstruos de Universal',3,NULL,'978-8-410-46334-9',NULL,'Michael Walsh','Michael Walsh',NULL,NULL,'Moztros',NULL,'2025-02-13',NULL,NULL,replace(replace('¡UNA VISIÓN MODERNA DEL TERROR QUE RESUCITA A UNO DE LOS MONSTRUOS MÁS ICÓNICOS!\r\nEl aclamado creador Michael Walsh (','\r',char(13)),'\n',char(10)),NULL,NULL,128,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775484727494-pw0dow.jpg','read',0,5,NULL,'2026-04-06 14:12:08','2026-04-06 14:13:13',25,NULL,'rústica','[{"name":"Michael Walsh","role":"Guion, Dibujo, Tinta"},{"name":"Toni-Marie Griffin","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(141,'Monstruos de Universal #4','Monstruos de Universal',4,NULL,'978-8-410-46399-8',NULL,'Faith Erin Hicks','Lee Loughridge',NULL,NULL,'Moztros',NULL,'2025-10-23',NULL,NULL,replace(replace('Atormentada por el siniestro encuentro que vivió de pequeña, Helen Grosvenor es una mujer que nació entre dos mundos y no se siente parte de ninguno. Sin embargo, cuando una voz familiar empieza a llamarla, Helen recibe un papel inesperado en el auge de un monstruo conocido como… La Momia.\r\nLa guionista superventas Faith Erin Hicks, autora de la trilogía de La ciudad sin nombre, y el colorista Lee Loughridge forman equipo creativo para ofrecer una reinterpretación audaz de la célebre historia. ¡El clásico del terror de Universal Pictures cobra vida como nunca antes!\r\n112 pp, PVP 18,90 €\rContiene: Universal Monsters: The Mummy 1-4.','\r',char(13)),'\n',char(10)),NULL,NULL,112,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775484729738-swx15w.jpg','read',0,4,NULL,'2026-04-06 14:12:10','2026-04-06 14:13:11',25,18.9,'tapa dura','[{"name":"Faith Erin Hicks","role":"Guion"},{"name":"Lee Loughridge","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(142,'Monstruos de Universal #5','Monstruos de Universal',5,NULL,'979-1-387-95337-9',NULL,'James Tynion IV','Dani - Danai Kilaidonis',NULL,NULL,'Moztros',NULL,'2026-02-26',NULL,NULL,replace(replace('Contiene: Universal Monsters: The Invisible Man 1-4.\r\n¡EL ORIGEN DE UN MONSTRUO INVISIBLE!\r\nJack Griffin siempre ha sido invisible para gente que le rodea… o, al menos, así lo percibe. Cuando un descubrimiento experimental ofrece un camino para convertir sus sueños de invisibilidad en realidad, nadie, ni siquiera la mujer a la que ama, se interpondrá en su camino. Presencia el legendario descenso a la locura de Griffin, mientras su humanidad se desvanece y el monstruo de su interior se revela, dejando paso tan solo al… ¡Hombre Invisible!\r\n¡Un equipo de ensueño para el género de terror! James Tynion IV (Something is Killing the Children, The Nice House on the Lake) y DaNi (En lo profundo del bosque), revelan su visión de uno de los monstruos más terroríficos de la historia del cine.','\r',char(13)),'\n',char(10)),NULL,NULL,128,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775484732603-zpwjts.jpg','read',0,4,NULL,'2026-04-06 14:12:13','2026-04-06 14:13:08',25,NULL,'lujo','[{"name":"James Tynion IV","role":"Guion"},{"name":"Dani - Danai Kilaidonis","role":"Dibujo, Tinta"},{"name":"Brad Simpson","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(143,'El armario','El armario',NULL,NULL,'978-8-418-95579-2',NULL,'James Tynion IV','Gavin Fullerton',NULL,NULL,'Moztros',NULL,'2023-05-18',NULL,NULL,replace('Incluye: The Closet #1-3 USA\rEsta historia de terror existencial comienza cuando Thom decide trasladarse junto a su mujer y su hijo Jamie a Portland, en la otra punta del país, en un intento casi desesperado de empezar de nuevo y salvar la armonía familiar que se desmorona a su alrededor. Jamie comenzará a insistir en que el monstruo que vivía en su armario también se ha mudado a Portland con ellos para continuar aterrorizándolo, lo que llevará a Thom a enfrentarse no solo a los monstruos creados por la fantasía de su hijo (o tal vez no) sino también a sus propios monstruos interiores, que creía enterrados en el pasado. \rNo podéis dejar pasar la oportunidad de leer este nuevo relato de horror psicológico de James Tynion IV (Hay algo matando niños, Batman) y Gavin Fullerton (Bog Bodies, Bags), que os llevará de paseo por un viaje en familia asfixiante lleno de monstruos y pecados del pasado que regresan para clamar venganza.','\r',char(13)),NULL,NULL,112,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775484864248-x5unxz.jpg','read',0,5,NULL,'2026-04-06 14:14:26','2026-04-06 14:14:37',NULL,19.9,NULL,'[{"name":"James Tynion IV","role":"Guion"},{"name":"Gavin Fullerton","role":"Dibujo, Tinta"},{"name":"Chris O''Halloran","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(144,'Sentient','Sentient',NULL,NULL,'978-8-413-34683-0',NULL,'Jeff Lemire','Gabriel Hernández Walta',NULL,NULL,'Panini Comics España',NULL,'2020-12-17',NULL,NULL,replace(replace('Contiene Sentient 1-6 \r\nUn cómic a cargo de los ganadores del Premio Eisner Jeff Lemire (Black Hammer) y Gabriel Hernández-Walta (La Visión). Bienvenidos al SS Montgomery. Después de que un ataque aniquile a cada adulto a bordo de esta colonia espacial, Valerie, la inteligencia artificial a cargo de la nave, debe proteger a los niños supervivientes. Mientras son perseguidos por peligrosas fuerzas, ¿superará Valerie su programación y se convertirá en una salvadora para los niños?','\r',char(13)),'\n',char(10)),NULL,NULL,168,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775484897332-c54bw7.jpg','unread',0,NULL,NULL,'2026-04-06 14:14:59','2026-04-06 14:14:59',NULL,24,NULL,'[{"name":"Jeff Lemire","role":"Guion"},{"name":"Gabriel Hernández Walta","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(146,'DC Horror Presents','DC Horror Presents',NULL,NULL,'979-1-370-13179-1',NULL,'Francesco Francavilla','Danny Earls',NULL,NULL,'Panini Comics España',NULL,'2025-10-23',NULL,NULL,replace(replace('Contiene DC Horror Presents… números 1 a 4 publicados en USA por DC Comics. Serie abierta.\r\n¡Explora los rincones más oscuros del Universo DC! En esta trepidante antología, los titanes del terror dan un toque único a personajes conocidos. Una antología para los fans del terror, con historias únicas escritas y dibujadas por leyendas del género, reunidas con carta blanca para explorar sus ideas más salvajes y espeluznantes. Nunca has visto el Universo DC así. Hazte este volumen... ¡si te atreves!','\r',char(13)),'\n',char(10)),NULL,NULL,104,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775485055338-irjtlf.jpg','read',0,3,NULL,'2026-04-06 14:17:36','2026-04-06 14:17:43',NULL,21,NULL,'[{"name":"Francesco Francavilla","role":""},{"name":"Danny Earls","role":""},{"name":"Patrick Horvath","role":""},{"name":"David Dastmalchian","role":""},{"name":"Leah Kilpatrick","role":""},{"name":"LaToya Morgan","role":""},{"name":"The Boulet Brothers","role":""},{"name":"Aaron Sagers","role":""},{"name":"Cat Staggs","role":""},{"name":"Walt Barna","role":""},{"name":"Brandon Hay","role":""},{"name":"Steve Kostanski","role":""},{"name":"Patton Oswalt","role":""},{"name":"Jordan Blum","role":""},{"name":"Butch K. Mapa","role":""},{"name":"Ryan Kelly","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(147,'Alien: Blanco, negro y sangre','Alien: Blanco, negro y sangre',NULL,NULL,'979-1-370-13026-8',NULL,'Dev Pramanik','Luigi Teruel',NULL,NULL,'Panini Comics España',NULL,'2025-07-24',NULL,NULL,replace(replace('Contiene: Alien: Black, White & Blood 1-4\r\nEl universo de Aliens como sólo Marvel podría haberlo imaginado... ¡en escalofriante blanco, negro, rojo... y verde! Marvel Comics y 20th Century Studios presentan un festín sangriento en forma de antología. Guionistas superestrellas se unen a los dibujantes favoritos de los lectores en una combinación terrorífica.','\r',char(13)),'\n',char(10)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775485309479-wp54fv.jpg','unread',0,NULL,NULL,'2026-04-06 14:21:50','2026-04-06 14:21:50',NULL,25,'Rústica','[{"name":"Dev Pramanik","role":""},{"name":"Luigi Teruel","role":""},{"name":"Tomasso Bianchi","role":""},{"name":"Pornsak Puchetshote","role":""},{"name":"Cody Ziglar","role":""},{"name":"Stephanie Phillips","role":""},{"name":"Chris Cross","role":""},{"name":"Collin Kelly","role":""},{"name":"Michael Dowling","role":""},{"name":"Steve Foxe","role":""},{"name":"Jethro Morales","role":""},{"name":"Partha Pratim","role":""},{"name":"Marcelo Ferreira","role":""},{"name":"Ryan Cady","role":""},{"name":"Claire Roe","role":""},{"name":"Jackson Lanzing","role":""},{"name":"Bryan H","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(150,'Los Picapiedra: Integral','Los Picapiedra: Integral',NULL,NULL,'978-8-417-64491-8',NULL,'Mark Russell','Steve Pugh',NULL,NULL,'ECC Ediciones',NULL,'2018-11-13',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: The Flintstones núms. 1 a 12 USA\r\n¡YABBA-DABBA DO!\r\nEn el pueblo de Piedradura, Pedro y Vilma Picapiedra, su hija Pebbles, sus vecinos los Mármol, y sus amigos, compañeros de trabajo y dinoaparatos protagonizan divertidas aventuras ambientadas en una Edad de Piedra que bien podría ser reflejo de nuestra era, tan confusa y cautivadora como alienante. Esta versión moderna de la icónica serie de animación de Hanna-Barbera es oscuramente hilarante, y dirige su mordaz mirada sobre asuntos como el consumismo, la religión, la política y las relaciones interpersonales.\r\nEntre 2016 y 2017, el equipo creativo formado por Mark Russell (Prez, Superman) y Steve Pugh (Animal Man, La Cosa del Pantano) se embarcó en una serie limitada que convirtió a la primera familia de los dibujos animados en protagonistas de una obra maestra del cómic contemporáneo. A través de 12 entregas, íntegramente recopiladas en este volumen, construyeron una brillante sátira que sedujo a la crítica, cosechando nominaciones a los premios Eisner 2018 en las categorías de mejor serie limitada, mejor publicación de humor y mejor guionista.','\r',char(13)),'\n',char(10)),NULL,NULL,320,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775487899022-k4nfh4.jpg','read',0,5,NULL,'2026-04-06 15:05:00','2026-04-06 15:05:13',NULL,30.5,NULL,'[{"name":"Mark Russell","role":"Guion"},{"name":"Steve Pugh","role":"Dibujo, Tinta"},{"name":"Rick Leonardi","role":"Dibujo"},{"name":"Scott Hanna","role":"Dibujo, Tinta"},{"name":"Chris Chuckry","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(151,'Marvel Gold. Marvel 75 Años: La era clásica','Marvel Gold. Marvel 75 Años: La era clásica',NULL,NULL,'978-8-490-94164-5',NULL,'Stan Lee','Steve Ditko',NULL,NULL,'Panini Comics España',NULL,'2015-05-28',NULL,NULL,replace(replace('Edición original: Fantastic Four 1, 48-50 y 236, Amazing Fantasy 15, The Avengers 1, 57, 58, 164-166, The Amazing Spider-Man 31-33, 121 y 122, Captain America 110-113, The Silver Surfer 3, The X-Men 65, 66, 141 y 142, The Incredible Hulk 181, Iron Man 128 y Daredevil 191 USA\r\nEn 1939, la publicación de Marvel Comics #1 USA por parte de Timely Comics lanzó el mayor cosmos de ficción jamás creado... ¡El Universo Marvel! 75 años después, la historia de La Casa de las Ideas está jalonada por inmensos hitos, que marcaron a generaciones de lectores: Los Cuatro Fantásticos, Spiderman, Los Vengadores, La Patrulla-X, Hulk, Daredevil...','\r',char(13)),'\n',char(10)),NULL,NULL,696,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775488625521-vgpv4c.jpg','unread',0,NULL,NULL,'2026-04-06 15:17:07','2026-04-06 15:17:31',NULL,30,'lujo','[{"name":"Stan Lee","role":"Guion"},{"name":"Steve Ditko","role":"Guion, Dibujo, Tinta"},{"name":"Jim Steranko","role":"Guion, Dibujo"},{"name":"Roy Thomas","role":"Guion"},{"name":"Gerry Conway","role":"Guion"},{"name":"Dennis O''Neil","role":"Guion"},{"name":"Len Wein","role":"Guion"},{"name":"Jim Shooter","role":"Guion"},{"name":"John Byrne","role":"Guion, Dibujo, Tinta"},{"name":"David Michelinie","role":"Guion"},{"name":"Bob Layton","role":"Guion, Tinta"},{"name":"Chris Claremont","role":"Guion"},{"name":"Frank Miller","role":"Guion, Dibujo"},{"name":"Roger Stern","role":"Guion"},{"name":"Jack Kirby","role":"Dibujo"},{"name":"John Buscema","role":"Dibujo"},{"name":"Gil Kane","role":"Dibujo"},{"name":"Neal Adams","role":"Dibujo"},{"name":"Sal Buscema","role":"Dibujo"},{"name":"Herb Trimpe","role":"Dibujo"},{"name":"John Romita Jr.","role":"Dibujo"},{"name":"Ron Frenz","role":"Dibujo"},{"name":"George Klein","role":"Tinta"},{"name":"Christopher Rule","role":"Tinta"},{"name":"Stan Goldberg","role":"Color"},{"name":"Dick Ayers","role":"Tinta"},{"name":"Joe Sinnott","role":"Tinta"},{"name":"George Tuska","role":"Tinta"},{"name":"John Romita Sr.","role":"Tinta"},{"name":"Tony Mortellaro","role":"Tinta"},{"name":"Dave Hunt","role":"Color"},{"name":"Artie Simek","role":"Color"},{"name":"Tom Palmer","role":"Tinta"},{"name":"Sam Grainger","role":"Tinta"},{"name":"Jack Abel","role":"Tinta"},{"name":"Glynis Oliver","role":"Color"},{"name":"Pablo Marcos","role":"Tinta"},{"name":"Phil Rachelson","role":"Color"},{"name":"Bob Sharen","role":"Color"},{"name":"Terry Austin","role":"Tinta"},{"name":"Lynn Varley","role":"Color"},{"name":"Christie Scheele","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(152,'Marvel Must-Have #18','Marvel Must-Have',18,NULL,'978-8-411-50429-4',NULL,'Mark Millar','Terry Dodson',NULL,NULL,'Panini Comics España',NULL,'2021-04-15',NULL,NULL,replace(replace('Contiene Marvel Knights: Spider-Man Vol. 1 #1-12\r\nLa peor pesadilla de Spiderman se ha hecho realidad. Uno de sus enemigos ha descubierto su identidad secreta y está usando esa información para golpear a la familia de Peter Parker. Ahora, Tía May ha sido secuestrada, y Mary Jane puede ser la siguiente. Forzado a un terrible juego del gato y el ratón, Spidey tendrá que enfrentarse a todos sus grandes enemigos, en una de sus mejores y más excitantes sagas del siglo XXI.','\r',char(13)),'\n',char(10)),NULL,NULL,16,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775488698205-oc24ix.jpg','unread',0,NULL,NULL,'2026-04-06 15:18:24','2026-04-06 15:18:24',27,25,'lujo','[{"name":"Mark Millar","role":"Guion"},{"name":"Terry Dodson","role":"Dibujo"},{"name":"Rachel Dodson","role":"Tinta"},{"name":"Ian Hannin","role":"Color"},{"name":"Frank Cho","role":"Dibujo, Tinta"},{"name":"Laura Martin","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(153,'Marvel Must-Have #1','Marvel Must-Have',1,NULL,'978-6-076-36085-9',NULL,'Mark Millar','Steve McNiven',NULL,NULL,'Panini Comics España',NULL,'2020-09-17',NULL,NULL,replace(replace('Contiene: Civil War 1-7 USA\r\nEl Universo Marvel está cambiando. Es tiempo de elegir: ¿De qué lado estás? Un conflicto que se ha estado labrando durante años estalla al fin, rompiendo en dos a la comunidad superheroica, y enfrentando a amigo contra amigo, hermano contra hermano. Spiderman, Los Vengadores, La Patrulla-X, Los Cuatro Fantásticos... todos se verán afectados. Todos deberán elegir su lugar en la guerra. Nadie está a salvo en la saga que cambió para siempre las reglas del juego.','\r',char(13)),'\n',char(10)),NULL,NULL,16,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775488716784-znwzb2.jpg','unread',0,NULL,NULL,'2026-04-06 15:18:37','2026-04-06 15:18:37',27,NULL,'tapa dura','[{"name":"Mark Millar","role":"Guion"},{"name":"Steve McNiven","role":"Dibujo, Tinta"},{"name":"Dexter Vines","role":"Tinta"},{"name":"Mark Morales","role":"Tinta"},{"name":"John Dell","role":"Tinta"},{"name":"Tim Townsend","role":"Tinta"},{"name":"Morry Hollowell","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(154,'Marvel Must-Have #4','Marvel Must-Have',4,NULL,'978-8-411-01516-5',NULL,'Mark Millar','Steve McNiven',NULL,NULL,'Panini Comics España',NULL,'2020-09-17',NULL,NULL,replace(replace('Contiene: Wolverine vol 3 66-72 y Old Man Logan Giant-Size.\r\nUna epopeya apocalíptica protagonizada por Lobezno en el mejor estilo de Mad Max que nos lleva varias décadas hacia el futuro. Nadie sabe qué ocurrió la noche en que los héroes cayeron: Sólo que todos desaparecieron y el mal ha triunfado desde entonces. En el último medio siglo, nadie ha visto al hombre simplemente conocido como Logan. Pero algo le hará salir de las sombras. Su amigo Ojo de Halcón necesita recorrer miles de kilómetros para poner a su familia a salvo. Lobezno se prepara para el viaje de su vida.','\r',char(13)),'\n',char(10)),NULL,NULL,16,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775488724976-pn5dl2.jpg','unread',0,NULL,NULL,'2026-04-06 15:18:46','2026-04-06 15:18:46',27,NULL,'tapa dura','[{"name":"Mark Millar","role":"Guion"},{"name":"Steve McNiven","role":"Dibujo"},{"name":"Dexter Vines","role":"Tinta"},{"name":"Mark Morales","role":"Tinta"},{"name":"Jay Leisten","role":"Tinta"},{"name":"Morry Hollowell","role":"Color"},{"name":"Christina Strain","role":"Color"},{"name":"Justin Ponsor","role":"Color"},{"name":"Jason Keith","role":"Color"},{"name":"Paul Mounts","role":"Color"},{"name":"Nathan Fairbairn","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(155,'Marvel Must-Have #7','Marvel Must-Have',7,NULL,'978-8-411-01635-3',NULL,'Frank Miller','John Romita Jr.',NULL,NULL,'Panini Comics España',NULL,'2020-10-01',NULL,NULL,replace(replace('Contiene: Daredevil: The Man Without Fear #1-5 (1993-94) USA.\r\nEl origen definitivo del Diablo Guardián narrado por el autor que mejor le conoce y por uno de los mejores dibujantes que han pasado por su serie. Un fuego arde en lo más profundo de Matthew Murdock, el hijo de un boxeador asesinado por la mafia al que un accidente cambió su vida para siempre. Pronto, un justiciero enmascarado vigilará las calles más oscuras de la ciudad. Pero, antes de que eso ocurra, un niño ciego tendrá que recorrer el camino que le llevará a convertirse en el guardián de la Cocina del Infierno.','\r',char(13)),'\n',char(10)),NULL,NULL,16,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775488737977-jnot7l.jpg','unread',0,NULL,NULL,'2026-04-06 15:18:59','2026-04-06 15:18:59',27,NULL,'tapa dura','[{"name":"Frank Miller","role":"Guion"},{"name":"John Romita Jr.","role":"Dibujo"},{"name":"Al Williamson","role":"Tinta"},{"name":"Christie Scheele","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(156,'Marvel Must-Have #11','Marvel Must-Have',11,NULL,'978-8-411-01431-1',NULL,'Jim Starlin','George Perez',NULL,NULL,'Panini Comics España',NULL,'2020-12-03',NULL,NULL,replace(replace('Contiene: The Infinity Gauntlet #1-6 USA (1991)\r\nThanos ha logrado reunir todas las Gemas del Infinito. Ahora el Titán Loco tiene un poder casi divino, y ha decidido ofrecerle a su adorada Muerte una prueba definitiva de su amor: la mitad de las almas de los seres vivos del universo. Para tratar de revertir este genocidio a escala cósmica, los héroes de la Tierra supervivientes se reunirán bajo el liderazgo de Adam Warlock y Estela Plateada. Aunque quizás ni siquiera el poder combinado de Los Vengadores, Los 4 Fantásticos y La Patrulla-X sea suficiente para derrotar a Thanos y su Guantelete del Infinito.','\r',char(13)),'\n',char(10)),NULL,NULL,16,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775488747093-956a2m.jpg','read',0,NULL,NULL,'2026-04-06 15:19:08','2026-04-07 17:40:32',27,NULL,'tapa dura','[{"name":"Jim Starlin","role":"Guion"},{"name":"George Perez","role":"Dibujo"},{"name":"Ron Lim","role":"Dibujo"},{"name":"Joe Rubinstein","role":"Tinta"},{"name":"Tom Christopher","role":"Tinta"},{"name":"Bruce N. Solotoff","role":"Tinta"},{"name":"Max Scheele","role":"Color"},{"name":"Ian Laughlin","role":"Color"},{"name":"Evelyn Stein","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(157,'Marvel Must-Have #12','Marvel Must-Have',12,NULL,'978-8-411-01432-8',NULL,'Greg Pak','Carlo Pagulayan',NULL,NULL,'Panini Comics España',NULL,'2021-01-14',NULL,NULL,replace(replace('Contiene: The Incredible Hulk vol 2 #92-105 USA, Amazing Fantasy vol 2 #15 USA y Giant-Size Hulk vol 2 #1 USA.\r\nLos mayores heroes del universo marvel decidieron exiliar a Hulk lejos de la Tierra para que no pudiera seguir causando daño. El destino; un planeta deshabitado y paradisíaco en el que no amenazara a ningún ser vivo. Por desgracia, un error inesperado provoca que Hulk acabe en un planeta inhóspito, donde el Gigante Verde se convierte en un gladiador bajo la bota de los poderosos. Pero el viejo mandíbulas de jade pronto se unirá a la rebelión local, convirtiéndose en el héroe de todo un pueblo. \r\nCon la aparición especial de Estela Plateada.','\r',char(13)),'\n',char(10)),NULL,NULL,16,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775488750775-vinubz.jpg','read',0,NULL,NULL,'2026-04-06 15:19:11','2026-04-07 17:40:32',27,NULL,'tapa dura','[{"name":"Greg Pak","role":"Guion"},{"name":"Carlo Pagulayan","role":"Dibujo"},{"name":"Aaron Lopresti","role":"Dibujo"},{"name":"Peter David","role":"Guion"},{"name":"Michael Avon Oeming","role":"Dibujo"},{"name":"Alex Niño","role":"Dibujo, Tinta"},{"name":"Marshall Rogers","role":"Dibujo"},{"name":"Juan Santacruz","role":"Dibujo"},{"name":"Gary Frank","role":"Dibujo"},{"name":"Takeshi Miyazawa","role":"Dibujo"},{"name":"Jeffrey Huet","role":"Tinta"},{"name":"Mike Allred","role":"Tinta"},{"name":"Danny Miki","role":"Tinta"},{"name":"Sandu Florea","role":"Tinta"},{"name":"Raúl Fernandez","role":"Tinta"},{"name":"Jonathan Sibal","role":"Tinta"},{"name":"Chris Sotomayor","role":"Color"},{"name":"Laura Martin","role":"Color"},{"name":"Lovern Kindzierski","role":"Color"},{"name":"Studio F","role":"Color"},{"name":"Christina Strain","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(158,'Marvel Must-Have #25','Marvel Must-Have',25,NULL,'978-8-411-01637-7',NULL,'J.M. DeMatteis','Michael Zeck',NULL,NULL,'Panini Comics España',NULL,'2021-07-22',NULL,NULL,replace(replace('Contiene Web Of Spider-Man #31-32 USA, The Amazing Spider-Man #293-294 y Peter Parker, The Spectacular Spider-Man #131-132 USA.\r\nEl legendario equipo creativo compuesto por J. M. DeMatteis y Mike Zeck elaboran la historia definitiva de venganza, en esta revolucionaria e inigualable saga, considerada la mejor aventura moderna de Spiderman. Kraven El Cazador ha acechado y acabado con la vida de todos los animales conocidos por el hombre. Pero hay una bestia que se le resiste, una que se burló de él en cada encuentro: el superhéroe conocido como Spiderman. Ahora el tiempo de jugar ha terminado. Acabará con la araña, la enterrará y se convertirá en ella. Empieza la última cacería de Kraven.','\r',char(13)),'\n',char(10)),NULL,NULL,16,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775488776256-gwa94l.jpg','unread',0,NULL,NULL,'2026-04-06 15:19:37','2026-04-06 15:19:37',27,NULL,'tapa dura','[{"name":"J.M. DeMatteis","role":"Guion"},{"name":"Michael Zeck","role":"Dibujo, Color"},{"name":"Bob McLeod","role":"Color"},{"name":"Janet Jackson","role":"Color"},{"name":"Bob Sharen","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(159,'Marvel Must-Have #31','Marvel Must-Have',31,NULL,'978-8-411-01084-9',NULL,'Frank Miller','David Mazzucchelli',NULL,NULL,'Panini Comics España',NULL,'2021-11-18',NULL,NULL,replace(replace('Contiene: Daredevil Vol1. #227-233 USA\r\n“Y yo os digo… Que un hombre sin esperanza es un hombre sin miedo”. Aquí llega la edición definitiva de la historia definitiva de Daredevil, escrita y dibujada por Frank Miller y David Mazzucchelli, dos auténticas leyendas del Noveno Arte. Karen Page, el antiguo amor de Matt Murdock, ha cambiado la identidad secreta del Diablo Guardián por una dosis de droga. Ahora, Daredevil debe encontrar fortaleza mientras Kingpin le golpea como nunca antes lo ha hecho.','\r',char(13)),'\n',char(10)),NULL,NULL,16,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775488785972-560hey.jpg','unread',0,NULL,NULL,'2026-04-06 15:19:46','2026-04-06 15:19:46',27,NULL,'grapa','[{"name":"Frank Miller","role":"Guion"},{"name":"David Mazzucchelli","role":"Dibujo, Tinta, Color"},{"name":"Christie Scheele","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(160,'Marvel Must-Have #47','Marvel Must-Have',47,NULL,'978-8-411-01384-0',NULL,'Joe Michael Straczynski','Esad Ribic',NULL,NULL,'Panini Comics España',NULL,'2022-06-09',NULL,NULL,replace(replace('Contiene: Silver Surfer: Requiem 1-4\r\nDurante incontables años, la entidad que una vez fuera conocida como Norrin Radd ha navegado a través de las galaxias, explorando la oscuridad situada entre las estrellas y asistiendo al nacimiento y a la caída de poderosas civilizaciones. Ahora, su camino está próximo a llegar a su fin. Joe Michael Straczynski (El Asombroso Spiderman) y Esad Ribic (Thor) narran una aventura de Estela Plateada que ocupará para siempre un lugar destacado en tu corazón y en tu biblioteca.','\r',char(13)),'\n',char(10)),NULL,NULL,16,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775488841629-kujwz2.jpg','unread',0,NULL,NULL,'2026-04-06 15:20:06','2026-04-06 15:20:43',27,15,'tapa dura','[{"name":"Joe Michael Straczynski","role":"Guion"},{"name":"Esad Ribic","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(161,'Marvel Must-Have #51','Marvel Must-Have',51,NULL,'978-8-411-01455-7',NULL,'Greg Pak','John Romita Jr.',NULL,NULL,'Panini Comics España',NULL,'2022-08-11',NULL,NULL,replace(replace('Contiene: World War Hulk 1-5 y World War Hulk Prologue: World Breaker\r\n¡El más aplastante evento de la historia de Marvel! Exiliado por un grupo de supuestos héroes al planeta de Sakaar y tras conquistar aquel mundo, Hulk regresa a la Tierra... ¡Y busca venganza contra Iron Man, Reed Richards, el Doctor Extraño, Rayo Negro y todo el que se cruce en su camino! Más fuerte que nunca, y con la ayuda de una monstruosa compañía de aliados, esta vez el Goliat Verde quiere romper en dos nuestro hogar. Con guiones del genial creador de “Planeta Hulk” y dibujos del legendario John Romita Jr.','\r',char(13)),'\n',char(10)),NULL,NULL,16,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775488856049-kmuh1g.jpg','read',0,NULL,NULL,'2026-04-06 15:20:09','2026-04-07 17:40:32',27,NULL,'grapa','[{"name":"Greg Pak","role":"Guion"},{"name":"John Romita Jr.","role":"Dibujo"},{"name":"Peter David","role":"Guion"},{"name":"Al Rio","role":"Dibujo"},{"name":"Lee Weeks","role":"Dibujo, Tinta"},{"name":"Sean Phillips","role":"Dibujo"},{"name":"Klaus Janson","role":"Tinta"},{"name":"Tom Palmer","role":"Tinta"},{"name":"Christina Strain","role":"Color"},{"name":"William Murai","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(162,'Spiderman Noir: La colección completa. Marvel Omnibus','Spiderman Noir: La colección completa. Marvel Omnibus',NULL,NULL,'978-8-410-51229-0',NULL,'David Hine','Carmine Di Giandomenico',NULL,NULL,'Panini Comics España',NULL,'2020-11-19',NULL,NULL,replace(replace('Contiene Spider-Man Noir 1-4, Spider-Man Noir: Eyes Without A Face 1-4, Edge of Spider-Verse 1, Spider-Verse Team-Up 1, Spider-Geddon: Spider-Man Noir Video Comic\r\nTodas las aventuras de Spiderman Noir en solitario, en un único volumen. Un gran poder conlleva una gran responsabilidad. Pero cuando aquellos que tienen ese poder abusan de él, el pueblo tiene la responsabilidad de derribarlos. El año es 1933. Nueva York está gobernada por políticos corruptos, policías que no hacen nada por proteger a los inocentes y hombres de negocios sin escrúpulos. Es entonces cuando una araña cambia el destino de Peter Parker, pero no es la historia que esperas. ¡Un Hombre Araña con sabor a pulp y género negro!','\r',char(13)),'\n',char(10)),NULL,NULL,256,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775488936755-t8uhjf.jpg','unread',0,NULL,NULL,'2026-04-06 15:22:19','2026-04-06 15:22:19',NULL,25,'lujo','[{"name":"Carmine Di Giandomenico","role":"Dibujo, Tinta, Color"},{"name":"David Hine","role":"Guion"},{"name":"Fabrice Sapolsky","role":"Guion"},{"name":"Richard Isanove","role":"Dibujo, Tinta, Color"},{"name":"Bob McLeod","role":"Dibujo, Tinta"},{"name":"Tim Eldred","role":"Dibujo"},{"name":"Paco Díaz","role":"Tinta"},{"name":"Andrew Crossley","role":"Color"},{"name":"Andres Mossa","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(163,'Estela Plateada de Dan Slott y Mike Allred. Marvel Omnibus','Estela Plateada de Dan Slott y Mike Allred. Marvel Omnibus',NULL,NULL,'978-8-411-01831-9',NULL,'Dan Slott','Mike Allred',NULL,NULL,'Panini Comics España',NULL,'2020-05-14',NULL,NULL,replace(replace('Contiene: Silver Surfer 1-14, 1-14 y material de All-New Marvel Now! Point One\r\n¡La legendaria etapa en un único volumen! \r\nTe presentamos a Dawn Greenwood, la chica terráquea a la que Estela Plateada enseñará el Universo con nuevos ojos, mientras se enfrentan a increíbles peligros. Descubre el cómic que ensancha los límites de la imaginación.\r\nEn 2014, Dan Slot y Mike y Laura Allred relanzaron la serie del surfista galáctico para contarnos su más bella historia. La línea Marvel Omnibus recupera esta aclamada etapa, ganadora de un Premio Eisner 2016.','\r',char(13)),'\n',char(10)),NULL,NULL,696,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775488969164-1zitib.jpg','unread',0,NULL,NULL,'2026-04-06 15:22:50','2026-04-06 15:22:50',NULL,45,'grapa','[{"name":"Dan Slott","role":"Guion"},{"name":"Mike Allred","role":"Dibujo, Tinta"},{"name":"Laura Allred","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(164,'Masacre de Gerry Duggan. Marvel Omnibus #1','Masacre de Gerry Duggan. Marvel Omnibus',1,NULL,'978-8-491-67954-7',NULL,'Gerry Duggan','Patrick Olliffe',NULL,NULL,'Panini Comics España',NULL,'2019-06-20',NULL,NULL,replace(replace('Contiene Deadpool 1-12 y Marvel Now What?! USA\r\nUna de las etapas más memorables de la historia de Masacre comienza aquí. Wade Wilson debe derrotar a un ejército de presidentes muertos, y eso es sólo el comienzo. La llegada de la Agente Preston, relatos del pasado y mucho más en un volumen hilarante.','\r',char(13)),'\n',char(10)),NULL,NULL,272,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775489008654-u7m7qd.jpg','unread',0,NULL,NULL,'2026-04-06 15:23:33','2026-04-06 15:23:33',28,35,NULL,'[{"name":"Gerry Duggan","role":"Guion"},{"name":"Brian Posehn","role":"Guion"},{"name":"Patrick Olliffe","role":"Dibujo"},{"name":"Tony Moore","role":"Dibujo, Tinta"},{"name":"Scott Koblish","role":"Dibujo, Tinta"},{"name":"Mike Hawthorne","role":"Dibujo, Tinta"},{"name":"John Livesay","role":"Tinta"},{"name":"Jason Gorder","role":"Tinta"},{"name":"John Kalisz","role":"Color"},{"name":"Val Staples","role":"Color"},{"name":"John Lucas","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(165,'Masacre de Gerry Duggan. Marvel Omnibus #2','Masacre de Gerry Duggan. Marvel Omnibus',2,NULL,'978-8-413-34339-6',NULL,'Gerry Duggan','Scott Koblish',NULL,NULL,'Panini Comics España',NULL,'2020-02-20',NULL,NULL,replace(replace('Contiene Deadpool 13-19, Annual 1 y Thunderbolts Annual 1\r\nTodo comienza con una aventura perdida, en la que Masacre viaja hasta los años setenta, cuando Luke Cage y Danny Rand tenían su negocio de Héroes de Alquiler... Pero la amenaza que encuentren entonces regresará en el presente. Y a continuación, Arma X recluta a Wade junto a Lobezno y al Capitán América para hacer frente a un enemigo común.','\r',char(13)),'\n',char(10)),NULL,NULL,272,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775489021617-opmo3u.jpg','unread',0,NULL,NULL,'2026-04-06 15:23:42','2026-04-06 15:23:42',28,NULL,'Cartoné 240-272 pp','[{"name":"Gerry Duggan","role":"Guion"},{"name":"Brian Posehn","role":"Guion"},{"name":"Ben Acker","role":"Guion"},{"name":"Ben Blacker","role":"Guion"},{"name":"Scott Koblish","role":"Dibujo, Tinta"},{"name":"Declan Shalvey","role":"Dibujo, Tinta"},{"name":"Evan Shaner","role":"Dibujo, Tinta"},{"name":"Matteo Lolli","role":"Dibujo, Tinta"},{"name":"Val Staples","role":"Color"},{"name":"Jordie Bellaire","role":"Color"},{"name":"Verónica Gandini","role":"Color"},{"name":"James Campbell","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(167,'Transmetropolitan #1','Transmetropolitan',1,NULL,'978-8-416-30314-4',NULL,'Warren Ellis','Darick Robertson',NULL,NULL,'ECC Ediciones',NULL,'2014-12-31',NULL,NULL,replace(replace('￼Recopila Transmetropolitan #1-6 USA.\r\n&quot;El periodista Spider Jerusalem ha pasado los últimos cinco años de su vida aislado en un refugio en la montaña. Ahora regresa a la ciudad trayendo consigo la verdad y el caos. Armado con un computador portátil y un lenguaje vitriólico, se convierte en el azote de los poderosos denunciando los abusos y las mentiras caiga quien caiga, sea líder religioso, presentador televisivo o presidente de la nación (a quien Spider llama, cariñosamente, “la bestia”).\r\nCon este volumen, ECC inicia la reedición en diez tomos de una obra demoledora. El guionista Warren Ellis (Planetary) y el dibujante Darick Robertson firman una sátira feroz que carga contra el conformismo y la pasividad de una sociedad enferma.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775489170709-o0gn3v.jpg','read',0,NULL,NULL,'2026-04-06 15:26:14','2026-04-07 17:40:32',29,NULL,'Rústica','[{"name":"Warren Ellis","role":"Guion"},{"name":"Darick Robertson","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(168,'Transmetropolitan #2','Transmetropolitan',2,NULL,'978-8-416-37411-3',NULL,'Warren Ellis','Darick Robertson',NULL,NULL,'ECC Ediciones',NULL,'2015-02-24',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Transmetropolitan núms. 7 a 12 USA\r\nBienvenidos al futuro. es un lugar inquietante, corrupto y superpoblado. Ni más ni menos como el presente, pero en este porvenir incierto existe el periodista Spider Jerusalem. Dotado de un olfato finísimo para la noticia, Spider le toma el pulso a la actualidad destilando veneno en cada uno de sus artículos. En esta ocasión investiga el destino de los reanimados, asiste a la conversión del amor en un virus informático y trata de esquivar la última voluntad de su exesposa, que incluye un encuentro cara a cara con el hijo de ambos. si es que el niño tuviera cara o, siquiera, una cabeza sobre los hombros, claro.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775489185715-ntf0jy.jpg','read',0,NULL,NULL,'2026-04-06 15:26:26','2026-04-07 17:40:32',29,NULL,'Rústica','[{"name":"Warren Ellis","role":"Guion"},{"name":"Darick Robertson","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(169,'Transmetropolitan #3','Transmetropolitan',3,NULL,'978-8-416-40901-3',NULL,'Warren Ellis','Darick Robertson',NULL,NULL,'ECC Ediciones',NULL,'2015-04-29',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Transmetropolitan núms. 13 a 18 USA\r\nSe avecina año electoral y la campaña se presenta muy reñida. La ciudadanía debe escoger entre los dos grandes males: el ultraconservador Bob Heller (cuya fotografía ilustra el término &quot;fascista&quot; en el diccionario) y el sonriente Senador Callahan (un lobo con piel de cordero). Ante semejante pareja de candidatos, Spider Jerusalem se lanza a cubrir la campaña con la acidez, la locura y la falta de escrúpulos que lo caracterizan. El resultado, naturalmente, es explosivo.\r￼￼￼￼￼￼￼￼￼￼￼￼￼￼￼￼￼￼￼￼￼￼￼￼￼￼Warren Ellis (Planetary, Hellblazer) y Darick Robertson descienden a las cloacas de la política para construir una sátira demencial que no deja títere con cabeza.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775489188599-8n7v9m.jpg','read',0,NULL,NULL,'2026-04-06 15:26:29','2026-04-07 17:40:32',29,NULL,'Rústica','[{"name":"Warren Ellis","role":"Guion"},{"name":"Darick Robertson","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(170,'Transmetropolitan #4','Transmetropolitan',4,NULL,NULL,NULL,'Warren Ellis','Darick Robertson',NULL,NULL,'ECC Ediciones',NULL,'2015-07-01',NULL,NULL,'EDICIÓN ORIGINAL: Transmetropolitan núms. 19 a 24 USA, Vertigo: Winter',NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775489204508-u9hxsp.jpg','read',0,NULL,NULL,'2026-04-06 15:26:45','2026-04-07 17:40:32',29,NULL,'Rústica','[{"name":"Warren Ellis","role":"Guion"},{"name":"Darick Robertson","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(171,'Transmetropolitan #5','Transmetropolitan',5,NULL,'978-8-416-47564-3',NULL,'Warren Ellis','Darick Robertson',NULL,NULL,'ECC Ediciones',NULL,'2015-08-26',NULL,NULL,'EDICIÓN ORIGINAL: Transmetropolitan núms. 25 a 30 USA  El senador Callahan ha alcanzado la presidencia de los Estados Unidos y su siguiente objetivo es destruir a Spider Jerusalem empleando para ello todo el poder de su nuevo cargo. Pero se topará con un periodista afilado, psicótico y completamente desprovisto de escrúpulos.',NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775489207333-l1fl5x.jpg','read',0,NULL,NULL,'2026-04-06 15:26:48','2026-04-07 17:40:32',29,NULL,'Rústica','[{"name":"Warren Ellis","role":"Guion"},{"name":"Darick Robertson","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(172,'Transmetropolitan #6','Transmetropolitan',6,NULL,NULL,NULL,'Warren Ellis','Darick Robertson',NULL,NULL,'ECC Ediciones',NULL,'2015-10-29',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Transmetropolitan núms. 31 a 36 USA  Spider Jerusalem inicia el segundo asalto en su combate particular contra el Presidente Callahan. Los pronósticos dan como vencedor al Presidente, pero el periodista se reserva un golpe devastador en forma de reportaje escandaloso dirigido a la mandíbula de su adversario…\r\nPublicada entre 1997 y 2002, Transmetropolitan es recordada como una de las mejores colecciones publicadas por el sello Vertigo. Surgida de la colaboración entre Warren Ellis (Planetary) y Darick Robertson (The Boys), vuelve a estar disponible en las librerías especializadas, gracias a esta edición integrada por 10 tomos en rústica de periodicidad bimestral.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775490392961-akd3zt.jpg','read',0,NULL,NULL,'2026-04-06 15:26:50','2026-04-07 17:40:32',29,NULL,'rústica','[{"name":"Warren Ellis","role":"Guion"},{"name":"Darick Robertson","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(173,'Transmetropolitan #7','Transmetropolitan',7,NULL,NULL,NULL,'Warren Ellis','Darick Robertson',NULL,NULL,'ECC Ediciones',NULL,'2015-12-23',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Transmetropolitan núms. 37 a 42 USA En su empeño por derribar al Presidente Callahan, Spider Jerusalem inicia un viaje devastador por las zonas más sórdidas de la ciudad, enfrentándose a la miseria, la demencia y la desolación.\r\nPublicada entre 1997 y 2002, Transmetropolitan es recordada como una de las mejores colecciones publicadas por el sello Vertigo. Surgida de la colaboración entre Warren Ellis (Planetary) y Darick Robertson (The Boys), vuelve a estar disponible en las librerías especializadas, gracias a esta edición integrada por 10 tomos en rústica de periodicidad bimestral.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775489212072-9owxuc.jpg','read',0,NULL,NULL,'2026-04-06 15:26:53','2026-04-07 17:40:32',29,NULL,'rústica','[{"name":"Warren Ellis","role":"Guion"},{"name":"Darick Robertson","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(174,'Transmetropolitan #8','Transmetropolitan',8,NULL,NULL,NULL,'Warren Ellis','Darick Robertson',NULL,NULL,'ECC Ediciones',NULL,'2016-02-29',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Transmetropolitan núms. 43 a 48 USA\r\nEl Departamento de Policía de baja por enfermedad, un francotirador paseándose por los tejados, una tormenta de proporciones bíblicas amenazando con destruir los archivos audiovisuales… Solo Spider Jerusalem es capaz de descubrir el nexo oculto tras esta cadena de desgracias.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775489214872-xcpxnn.jpg','read',0,NULL,NULL,'2026-04-06 15:26:56','2026-04-07 17:40:55',29,NULL,'Rústica','[{"name":"Warren Ellis","role":"Guion"},{"name":"Darick Robertson","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(175,'Transmetropolitan #9','Transmetropolitan',9,NULL,NULL,NULL,'Warren Ellis','Darick Robertson',NULL,NULL,'ECC Ediciones',NULL,'2016-04-28',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Transmetropolitan vol. 9: The cure  Spider Jerusalem sale a la caza de su último gran reportaje, y su olfato periodístico le conducirá adonde sea necesario. Como objetivo final, reunir las piezas de un escándalo mayúsculo que involucre al Presidente. \r\nPublicada entre 1997 y 2002, Transmetropolitan es recordada como una de las mejores colecciones publicadas por el sello Vertigo. Surgida de la colaboración entre Warren Ellis (Planetary) y Darick Robertson (The Boys), vuelve a estar disponible en las librerías especializadas, gracias a esta edición integrada por 10 tomos en rústica de periodicidad bimestral.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775489218472-aukw5w.jpg','read',0,NULL,NULL,'2026-04-06 15:26:59','2026-04-07 17:40:55',29,NULL,'rústica','[{"name":"Warren Ellis","role":"Guion"},{"name":"Darick Robertson","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(176,'Transmetropolitan #10','Transmetropolitan',10,NULL,'978-8-416-74682-8',NULL,'Warren Ellis','Darick Robertson',NULL,NULL,'ECC Ediciones',NULL,'2016-06-28',NULL,NULL,replace('EDICIÓN ORIGINAL: Transmetropolitan núms. 55 a 60, Transmetropolitan: I Hate It Here USA, Transmetropolitan: Filth of the City USA\rLlega el momento de despedirnos de las aventuras de Spider Jerusalem, con un último tomo que cerrará hilos argumentales y rendirá tributo al futuro distópico creado por Warren Ellis y Darick Robertson a través de los especiales La escoria de la ciudad y Odio todo esto, en los que participan los mejores autores de la industria.','\r',char(13)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775489221187-d4kprv.jpg','read',0,NULL,NULL,'2026-04-06 15:27:02','2026-04-07 17:39:50',29,NULL,'Rústica','[{"name":"Warren Ellis","role":"Guion"},{"name":"Darick Robertson","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(177,'Muerdeuñas #1','Muerdeuñas',1,NULL,'978-8-467-91859-5',NULL,'Joshua Williamson','Mike Henderson',NULL,NULL,'Norma Editorial',NULL,'2015-04-17',NULL,NULL,replace(replace('Contiene Nailbiter #1-5 USA\r\nEl pueblo de Buckaroo, Oregón, es la cuna de ni más ni menos que dieciséis asesinos en serie hasta la fecha y el agente Carroll del FBI está decidido a descubrir por qué. Pero cuando desaparece de pronto, una extraña alianza se forma para encontrarlo: la sheriff de Buckaroo, un agente de la NSA con un turbio pasado y el último y más notorio de los carniceros de Buckaroo, Edward “Muerdeuñas” Warren','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775490437558-vug9s8.jpg','read',0,NULL,NULL,'2026-04-06 15:47:22','2026-04-07 17:39:50',30,15,'Rústica','[{"name":"Joshua Williamson","role":"Guion"},{"name":"Mike Henderson","role":"Dibujo, Tinta"},{"name":"Adam Guzowski","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(178,'Muerdeuñas #2','Muerdeuñas',2,NULL,'978-8-467-91997-4',NULL,'Joshua Williamson','Mike Henderson',NULL,NULL,'Norma Editorial',NULL,'2015-11-12',NULL,NULL,replace(replace('Contiene Nailbiter #6-10 USA\r\nEl pueblo de Buckaroo, Oregón, es la cuna de ni más ni menos que dieciséis asesinos en serie hasta la fecha y el investigador que puede tener la clave de esta maldición se encuentra en coma tras sufrir una cruel tortura. Su amigo Finch y la sheriff Crane continúan su investigación de los hechos, pero nuevos sucesos prometen complicarles la tarea.\r\nJoshua Williamson y Mike Henderson ofrecen nuevas pistas y plantean nuevos y sangrientos misterios en este nuevo episodio que cuenta con Brian Michael Bendis como invitado especiales','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775490453853-2fhmbb.jpg','read',0,NULL,NULL,'2026-04-06 15:47:34','2026-04-07 07:51:37',30,NULL,'Rústica','[{"name":"Joshua Williamson","role":"Guion"},{"name":"Mike Henderson","role":"Dibujo, Tinta"},{"name":"Adam Guzowski","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(179,'Muerdeuñas #3','Muerdeuñas',3,NULL,'978-8-467-92324-7',NULL,'Joshua Williamson','Mike Henderson',NULL,NULL,'Norma Editorial',NULL,'2016-08-25',NULL,NULL,replace(replace('Contiene Nailbiter #11-15 USA\r\nEl pueblo de Buckaroo, Oregón, es la cuna de ni más ni menos que dieciséis asesinos en serie hasta la fecha y el investigador que pue-de tener la clave de esta maldición se encuentra en coma tras sufrir una cruel tortura. Su amigo Finch y la sheriﬀ Crane continúan su investigación de los hechos y la clave de todo la puede tener el asesino conocido como el\r\nMuerdeuñas. Joshua Williamson y Mike Henderson aceleran el ritmo y derraman más sangre en una trama que mantiene la tensión desde la primera hasta la última página.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775490457444-hfk822.jpg','read',0,NULL,NULL,'2026-04-06 15:47:38','2026-04-07 07:51:37',30,NULL,'Rústica','[{"name":"Joshua Williamson","role":"Guion"},{"name":"Mike Henderson","role":"Dibujo, Tinta"},{"name":"Adam Guzowski","role":"Color"},{"name":"Adam Markiewicz","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(180,'Muerdeuñas #4','Muerdeuñas',4,NULL,NULL,NULL,'Joshua Williamson','Mike Henderson',NULL,NULL,'Norma Editorial',NULL,'2016-10-27',NULL,NULL,replace(replace('Contiene Nailbiter #16-20 USA\r\nEl pueblo de Buckaroo, Oregón, es la cuna de ni más ni menos que dieciséis asesinos en serie hasta la fecha y el investigador que puede tener la clave de esta maldición acaba de despertar del coma en que se encontraba tras sufrir una cruel tortura. Su amigo Finch y la sheriff Crane continúan su investigación que les llevará a perseguir a un nuevo asesino conocido como el Asesino Demoníaco.\r\nJoshua Williamson y Mike Henderson dan una nueva vuelta de tuerca en uno de los thrillers más intensos de los últimos tiempos.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775490460348-9ht6nh.jpg','read',0,NULL,NULL,'2026-04-06 15:47:41','2026-04-07 07:51:37',30,NULL,'Rústica','[{"name":"Joshua Williamson","role":"Guion"},{"name":"Mike Henderson","role":"Dibujo, Tinta"},{"name":"Adam Guzowski","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(181,'Muerdeuñas #5','Muerdeuñas',5,NULL,'978-8-467-92760-3',NULL,'Joshua Williamson','Mike Henderson',NULL,NULL,'Norma Editorial',NULL,'2017-07-24',NULL,NULL,replace(replace('Contiene Nailbiter Hack/Slash Special USA y Nailbiter #21-25 USA\r\nEl pueblo de Buckaroo, Oregón, es la cuna de ni más ni menos que dieciséis asesinos en serie hasta la fecha y la joven Alice está cerca de descubrir por qué. Su madre, la sheriff Crane quiere protegerla del peligro, pero debe continuar su investigación. ¿Será su padre, el Muerdeuñas, quien la salve de un destino sangriento? \r\nJoshua Williamson y Mike Henderson se acercan al final de uno de los misterios más bien guardados del cómic.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775490466920-qw4s5i.jpg','read',0,NULL,NULL,'2026-04-06 15:47:47','2026-04-07 07:51:37',30,NULL,'Rústica','[{"name":"Joshua Williamson","role":"Guion"},{"name":"Mike Henderson","role":"Dibujo, Tinta"},{"name":"Adam Guzowski","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(182,'Muerdeuñas #6','Muerdeuñas',6,NULL,'978-8-467-92715-3',NULL,'Joshua Williamson','Mike Henderson',NULL,NULL,'Norma Editorial',NULL,'2017-11-15',NULL,NULL,replace(replace('Contiene Nailbiter #26-30 USA\r\nEl pueblo de Buckaroo, Oregón, es la cuna de ni más ni menos que dieciséis asesinos en serie hasta la fecha y el misterioso motivo de tan horrible legado está a punto de desvelarse. La sheriff Crane, su hija Alice, el asesino conocido como el Muerdeuñas y el experto en interrogatorios Finch se enfrentan finalmente a la verdad y posiblemente a sus muertes. \r\nJoshua Williamson y Mike Henderson nos ofrecen la esperada conclusión a este apasionante thriller de asesinos en serie.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775490471017-pl0mbt.jpg','read',0,NULL,NULL,'2026-04-06 15:47:52','2026-04-07 07:51:37',30,NULL,'Rústica','[{"name":"Joshua Williamson","role":"Guion"},{"name":"Mike Henderson","role":"Dibujo, Tinta"},{"name":"Adam Guzowski","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(183,'Muerdeuñas #7','Muerdeuñas',7,NULL,'978-8-467-94671-0',NULL,'Joshua Williamson','Mike Henderson',NULL,NULL,'Norma Editorial',NULL,'2021-08-20',NULL,NULL,replace(replace('Dieciséis de los más conocidos asesinos en serie del mundo nacieron y se criaron en Buckaroo, Oregón. El peor y más infame era Edward Charles Warren... jel Muerdeuñas! Sus víctimas: gente que se mordía las uñas. Los mataba, y después mordia sus uñas por ellos. Era el único con las respuestas acerca de por qué este pequeño pueblo originó a tantos asesinos en serie. Pero el agente Finch y la sheriff Crane resolvieron y enterraron ese misterio. O eso creen... Ahora, unos violentos asesinatos que imitan a los infames carniceros de Buckaroo se suceden en Portland, Oregón, y si Finch quiere que las muertes acaben, ¡debe colaborar con la hija del Muerdeuñas!\r\nSigue este nuevo misterio, en la serie que mezcla Twin Peaks y True Detective con el horror de El silencio de los corderos.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775490474527-h4d593.jpg','read',0,NULL,NULL,'2026-04-06 15:47:55','2026-04-07 07:51:37',30,NULL,'Rústica','[{"name":"Joshua Williamson","role":"Guion"},{"name":"Mike Henderson","role":"Dibujo, Tinta"},{"name":"Adam Guzowski","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(184,'Muerdeuñas #8','Muerdeuñas',8,NULL,'978-8-467-94874-5',NULL,'Joshua Williamson','Mike Henderson',NULL,NULL,'Norma Editorial',NULL,'2021-12-10',NULL,NULL,replace(replace('¿QUIÉN ESTÁ DETRÁS DEL REGRESO DE LOS ASESINOS DE BUCKAROO?\r\nLos secretos del Muerdeuñas han convertido un juego de instituto en una guerra a muerte entre asesinos en serie! Su hija, la sheriff Crane y el agente Finch deben regresar al destruido Buckaroo para encontrar a la horrible mente que se halla tras ese baño de sangre antes de que se extienda! Sé testigo del horror mientras MUERDEUÑAS VUELVE avanza hacia su impactante conclusión!','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775490477052-n0wy9v.jpg','read',0,NULL,NULL,'2026-04-06 15:47:57','2026-04-07 07:51:37',30,NULL,'Rústica','[{"name":"Joshua Williamson","role":"Guion"},{"name":"Mike Henderson","role":"Dibujo, Tinta"},{"name":"Adam Guzowski","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(185,'American Vampire #1','American Vampire',1,NULL,'978-8-415-84422-8',NULL,'Scott Snyder','Rafael Albuquerque',NULL,NULL,'ECC Ediciones',NULL,'2013-05-03',NULL,NULL,replace(replace('Astuto y despiadado como una serpiente de cascabel, Skinner Sweet tiene fama de ser terco e intratable. Es el primer vampiro concebido en tierra americana, pero no es la habitual criatura de la noche. Es más fuerte, más fiero y el sol renueva sus energías... Sweet es el primero de una nueva raza de chupasangres: el vampiro americano.\r\n45 años después de alzarse de su tumba, Sweet se encuentra en Los Ángeles en los años veinte, donde los jóvenes y bellos se ven atraídos como polillas por las luces de Hollywood. Sin embargo, hay algo más que simples humanos acechando allí, como la joven actriz Pearl Jones está a punto de descubrir. Cuando su sueño de convertirse en una estrella de cine se transforma en una pesadilla sangrienta, Sweet le da su única oportunidad de sobrevivir, así como el poder de vengarse.\r\nEl legendario maestro del terror Stephen King (Saga La Torre Oscura, It) se une al escritor Scott Snyder (All-Star Batman) y al dibujante Rafael Albuquerque (Batgirl) para guiarnos a través de décadas de expansión americana y evolución de los no muertos. Este volumen recopila los cinco primeros números de la aclamada serie Vertigo, con una nueva introducción del propio Stephen King.','\r',char(13)),'\n',char(10)),NULL,NULL,200,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775490935789-aqvvjt.jpg','read',0,NULL,NULL,'2026-04-06 15:55:40','2026-04-07 07:51:37',31,15.96,'cartone','[{"name":"Scott Snyder","role":"Guion"},{"name":"Rafael Albuquerque","role":"Dibujo"},{"name":"Stephen King","role":"Guion"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(186,'American Vampire #2','American Vampire',2,NULL,'978-8-467-49865-3',NULL,'Rafael Albuquerque','Scott Snyder',NULL,NULL,'Planeta Cómic / ECC Ediciones',NULL,'2011-09-01',NULL,NULL,'EDICION USA: American Vampire #6-11',NULL,NULL,200,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775490966733-iwmd51.jpg','read',0,NULL,NULL,'2026-04-06 15:56:07','2026-04-07 07:51:37',31,NULL,'cartone','[{"name":"Rafael Albuquerque","role":""},{"name":"Scott Snyder","role":""},{"name":"Matt Santolouco","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(187,'American Vampire #3','American Vampire',3,NULL,'978-8-415-52013-9',NULL,'Rafael Albuquerque','Scott Snyder',NULL,NULL,'Planeta Cómic / ECC Ediciones',NULL,'2012-02-01',NULL,NULL,'EDICION USA: American Vampire #12-18',NULL,NULL,200,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775490969312-qu47qt.jpg','read',0,NULL,NULL,'2026-04-06 15:56:09','2026-04-07 07:51:37',31,NULL,'cartone','[{"name":"Rafael Albuquerque","role":""},{"name":"Scott Snyder","role":""},{"name":"Danijel Zezelj","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(188,'American Vampire #4','American Vampire',4,NULL,'978-8-415-62877-4',NULL,'Scott Snyder','Jordi Bernet',NULL,NULL,'Planeta Cómic / ECC Ediciones',NULL,'2013-04-01',NULL,NULL,replace(replace('EDICION USA: American Vampire #19-25 \r\nMucho antes de su transformación en una nueva y peligrosa clase de vampiro, el sanguinario Skinner Sweet luchó codo con codo contra los nativos americanos junto al hombre que acabaría convirtiéndose en su más encarnizado enemigo, Jim Book. Sucedió en Nuevo México en 1871, ocho décadas antes de que el rebelde adolescente Travis Kidd afrontase una carrera desesperada sobre el asfalto de las carreteras californianas. Una carrera de automóviles contra un conductor que no teme a la muerte… porque ya está muerto.','\r',char(13)),'\n',char(10)),NULL,NULL,200,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775490971092-594zog.jpg','read',0,NULL,NULL,'2026-04-06 15:56:11','2026-04-07 07:51:37',31,NULL,'cartone','[{"name":"Rafael Albuquerque","role":"Tinta"},{"name":"Scott Snyder","role":"Guion"},{"name":"Jordi Bernet","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(189,'American Vampire #5','American Vampire',5,NULL,'978-8-415-74894-6',NULL,'Scott Snyder','Rafael Albuquerque',NULL,NULL,'Planeta Cómic / ECC Ediciones',NULL,'2013-03-01',NULL,NULL,replace(replace('EDICION USA: American Vampire #26-33\r\nAstuto y despiadado como una serpiente de cascabel, Skinner Sweet tiene fama de ser terco e intratable. Es el primer vampiro concebido en tierra americana, pero no es la habitual criatura de la noche. Es más fuerte, más fiero y el sol renueva sus energías... Sweet es el primero de una nueva raza de chupasangres: el vampiro americano.45 años después de alzarse de su tumba, Sweet se encuentra en Los Ángeles en los años veinte, donde los jóvenes y bellos se ven atraídos como polillas por las luces de Hollywood. Sin embargo, hay algo más que simples humanos acechando allí, como la joven actriz Pearl Jones está a punto de descubrir. Cuando su sueño de convertirse en una estrella de cine se transforma en una pesadilla sangrienta, Sweet le da su única oportunidad de sobrevivir, así como el poder de vengarse.El legendario maestro del terror Stephen King se une al escritor Scott Snyder y al dibujante Rafael Albuquerque para guiarnos a través de décadas de expansión americana y evolución de los no muertos. Este volumen recopila los cinco primeros números de la aclamada serie Vertigo, con una nueva introducción de Stephen King.','\r',char(13)),'\n',char(10)),NULL,NULL,200,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775490973511-tufv07.jpg','unread',0,NULL,NULL,'2026-04-06 15:56:14','2026-04-06 15:56:14',31,NULL,'cartone','[{"name":"Rafael Albuquerque","role":"Dibujo"},{"name":"Scott Snyder","role":"Guion"},{"name":"Roger Cruz","role":"Dibujo"},{"name":"Riccardo Burchielli","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(190,'American Vampire #6','American Vampire',6,NULL,'978-8-415-99087-1',NULL,'Rafael Albuquerque','Scott Snyder',NULL,NULL,'Planeta Cómic / ECC Ediciones',NULL,'2014-02-01',NULL,NULL,replace(replace('EDICION USA: American vampire #34, American Vampire: The Long Road Home núm. 1, American Vampire Anthology núm. 1 USA\r\nEn este tomo se cierra, en el ecuador del siglo XX, el primer ciclo de esta grandiosa epopeya vampírica, estableciendo un antes y un después en la historia de Skinner Sweet y Pearl Jones. Además, la carretera se tiñe de sangre en el one-shot rockabilly De cabeza al infierno, y algunos de los mejores autores de la industria norteamericana del cómic ofrecen su particular visión del universo de American Vampire en una antología que amplía los horizontes de la actual serie estrella del sello Vertigo de DC Comics.','\r',char(13)),'\n',char(10)),NULL,NULL,200,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775490978576-lx2cfk.jpg','unread',0,NULL,NULL,'2026-04-06 15:56:19','2026-04-06 15:56:19',31,NULL,'cartone','[{"name":"Rafael Albuquerque","role":""},{"name":"Scott Snyder","role":""},{"name":"Jason Aaron","role":""},{"name":"Jeff Lemire","role":""},{"name":"Fabio Moon","role":""},{"name":"Gabriel Bá","role":""},{"name":"Greg Rucka","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(191,'Suicidas #1','Suicidas',1,NULL,NULL,NULL,'Lee Bermejo','Lee Bermejo',NULL,NULL,'ECC Ediciones',NULL,'2016-03-30',NULL,NULL,replace(replace('Contiene Suiciders #1-6 USA\r\nCuando el Grande golpeó la Ciudad de Ángeles, solo sobrevivieron los fuertes y los salvajes. Se construyó un muro enorme para proteger la ciudad resucitada, donde la industria del entretenimiento adoptó una nueva forma. Mientras las masas pobres, sucias e indeseables luchaban por sobrevivir fuera de los muros de la ciudad, los gladiadores mejorados biotecnológicamente y conocidos como los Suicidas se convirtieron en dioses en el coliseo que había dentro.\r\nPero el mejor Suicida, el más grande de todos no es un mero dios. Él es el Santo. Ante las cámaras, habla de la necesidad de limpiar Nuevos Ángeles de los indignos; y en la arena, eso es justamente lo que hace. Apenas se sabe nada de ese hombre que parece una montaña enmascarada, y ese misterio deja a sus fans con ganas de más. Pero el Santo tiene sus propios secretos. Secretos sobre la enorme corporación que financia su estilo de vida lujoso y controla todos sus movimientos. Secretos sobre la periodista asesinada en su mansión. Secretos sobre su pasado que podrían hacer temblar los cimientos de Nuevos Ángeles como nunca lo ha hecho nada antes...\r\nEl aclamado guionista y dibujante Lee Bermejo desvela una visión valiente, bella y violenta de la distopia en el primer volumen de Suicidas. ¿Tienes lo que hace falta para sobrevivir?','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775491007815-3nwiz6.jpg','read',0,NULL,NULL,'2026-04-06 15:56:50','2026-04-06 16:01:01',32,NULL,'Rústica','[{"name":"Lee Bermejo","role":"Guion, Dibujo, Tinta"},{"name":"Matt Hollingsworth","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(192,'Suicidas #2','Suicidas',2,NULL,'978-8-416-94598-6',NULL,'Lee Bermejo','Lee Bermejo',NULL,NULL,'ECC Ediciones',NULL,'2017-01-31',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Suiciders: Kings of Hel.L.A. núms. 1 a 6 USA  \r\nARGUMENTO: Los hermanos Johnny y Trix Costello fueron testigos del asesinato de su padre cuando apenas eran unos críos. Ahora, Johnny lidera una de las pandillas más salvajes de Los Ángeles: los Reyes del Infierno. Las cosas se complican cuando los pandilleros tropiezan con el Coyote, un “suicida” retirado que mantiene una relación tormentosa con su exmujer y el hijo de ambos.\r\nLee Bermejo (Joker) se asocia con los talentosos dibujantes Alessandro Vitti (Red Lanterns) y Gerardo Zaffino (Karnak) para explorar en Suicidas: Los reyes del infierno el territorio siniestro, urbano y apocalíptico que había fundado en el primer volumen de Suicidas. Un relato feroz de acción, drama y suspense contado con el rigor narrativo de tres creadores en estado de gracia.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775491014412-0l13oh.jpg','read',0,NULL,NULL,'2026-04-06 15:56:55','2026-04-06 16:00:58',32,NULL,'Rústica','[{"name":"Lee Bermejo","role":"Guion, Dibujo"},{"name":"Alessandro Vitti","role":"Dibujo"},{"name":"Gerardo Zaffino","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(193,'Trillium','Trillium',NULL,NULL,'978-8-416-19459-9',NULL,'Jeff Lemire','Jeff Lemire',NULL,NULL,'ECC Ediciones',NULL,'2014-09-01',NULL,NULL,replace(replace('El tiempo y el espacio colisionan cuando William, un excombatiente de la Primera Guerra Mundial, y Nika, una xenóloga del siglo XXXVIII, se encuentran a los pies de unas ruinas incas en la Amazonia. Mientras su propio pasado se desmorona y su cordura es puesta a prueba, ambos emprenderán una carrera desesperada para encontrar una flor milagrosa, el trillium, que contiene el secreto de la salvación de la humanidad.\r\nJeff Lemire, guionista de Animal Man, Green Arrow y Constantine y autor de la premiada Essex County, afronta en Trillium su obra más ambiciosa como autor completo: una odisea por los pliegues de la realidad, desde los confines del universo hasta las profundidades del alma humana.','\r',char(13)),'\n',char(10)),NULL,NULL,192,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775491070145-y72wnn.jpg','read',0,NULL,NULL,'2026-04-06 15:57:53','2026-04-06 16:00:53',NULL,NULL,'Rústica','[{"name":"Jeff Lemire","role":"Guion, Dibujo, Tinta"},{"name":"José Villarrubia","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(194,'Punk Rock Jesus','Punk Rock Jesus',NULL,NULL,'978-8-415-84475-4',NULL,'Sean Murphy','Sean Murphy',NULL,NULL,'ECC Ediciones',NULL,'2013-05-03',NULL,NULL,'J2 propone el reality show definitivo: Crear un clon humano con ADN extraído del Santo Sudario, implantarlo en el útero de una madre adolescente virginal y que esta dé a luz en directo a un niño que podría ser el segundo advenimiento de Jesucristo. El niño llamado Chris se convierte al instante en una estrella, y todos sus momentos se graban y se retransmiten a miles de millones de espectadores fieles. Los fanáticos religiosos aman u odian el programa, los políticos enfurecidos debaten su influencia y la comunidad científica teme sus implicaciones. Pero cuando Chris descubre los siniestros secretos que hay tras su creación, se convierte en un rebelde con causa... y con guitarra. Si decide llevar ese mensaje antisistema hasta las masas, ¿podrán las fuerzas combinadas del fundamentalismo religioso y de la avaricia corporativa derrotar al poder del punk?',NULL,NULL,224,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775491334974-in03so.jpg','read',0,NULL,NULL,'2026-04-06 16:02:03','2026-04-06 16:03:01',NULL,16.95,'Rústica','[{"name":"Sean Murphy","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(195,'Clase Letal #1','Clase Letal',1,NULL,'978-8-467-91950-9',NULL,'Rick Remender','Wes Craig',NULL,NULL,'Norma Editorial',NULL,'2015-07-24',NULL,NULL,'Corresponde a Deadly Class Vol.1 TPB (Image Comics). &quot;Es 1987 y Marcus López, un adolescente sin hogar, no tiene razones para seguir viviendo. Pero un día una chica misteriosa le propone que entre en la escuela Kings Dominion de Artes Letales . Un lugar clandestino y brutal adonde los reyes del crimen mundial mandan a sus hijos para formarlos como expertos asesinos. Aquí el asesinato es un arte y matar una asignatura más a dominar. Rick Remender (Ciencia Oscura) presenta su obra más personal acompañado de Wes Craig (Batman: Origen) y Lee Loughridge (Fear Agent) con un intenso y violento viaje a la subcultura de los 80.&quot;',NULL,NULL,440,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775491431550-v93odk.jpg','read',0,NULL,NULL,'2026-04-06 16:03:55','2026-04-06 16:03:58',33,18,'rustica','[{"name":"Rick Remender","role":"Guion"},{"name":"Wes Craig","role":"Dibujo"},{"name":"Lee Loughridge","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(196,'Merlín. Biblioteca Robin Wood','Merlín. Biblioteca Robin Wood',NULL,NULL,'978-8-416-19464-3',NULL,'Robin Wood','Enrique Alcatena',NULL,NULL,'ECC Ediciones',NULL,'2014-10-01',NULL,NULL,replace(replace('Incluye los capítulos 0 al 9 de Merlín publicados en la revista Nippur Magnum.\r\nCorren tiempos oscuros en Inglaterra. La guerra, el habre y la muerte se han apoderado de todo su territorio. Por eso, los seres mágicos qeu antes poblaban sus bosques toman la decisión de abandonar el mundo de los hombres y trasladarse a otro plano de existencia. Para evitarlo, el mago Merlín urde un plan: forjar un soberano que levante un reino perfecto donde los hombres y los duendes puedan vivir en paz. En 1993, el guionista Robin Wood y el gran dibujante Enrique Alcatena combinaron sus talentos para dar forma a la leyenda del mago Merlín, a la historia del reino de Camelot y a la vida del niño que selló su destino arrancando una espada de una roca.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775491579565-3e98dl.jpg','read',0,5,NULL,'2026-04-06 16:06:05','2026-04-06 16:06:22',NULL,NULL,'Rústica','[{"name":"Robin Wood","role":"Guion"},{"name":"Enrique Alcatena","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(197,'El resurgir','El resurgir',NULL,NULL,'978-8-416-25534-4',NULL,'Scott Snyder','Sean Murphy',NULL,NULL,'ECC Ediciones',NULL,'2014-10-29',NULL,NULL,'Ante la alarma suscitada por un sorprendente hallazgo en las profundidades del Círculo Polar Ártico, el Departamento de Seguridad Nacional de los Estados Unidos solicita la ayuda de la Bióloga Marina Lee Archer. Y aunque en primera instancia responde con reticencia, pronto comprende el alcance de una misión que tal vez permita desentrañar aterradores misterios relacionados con la mitología y el folclore marinos, el origen de la humanidad… y su descorazonador futuro.',NULL,NULL,232,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775491790573-pbm97g.jpg','read',0,NULL,NULL,'2026-04-06 16:09:53','2026-04-06 16:09:58',NULL,NULL,'Rústica','[{"name":"Scott Snyder","role":"Guion"},{"name":"Sean Murphy","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(198,'Deadman de Kelley Jones','Deadman de Kelley Jones',NULL,NULL,'978-8-467-43556-6',NULL,'Mike Baron','Kelley Jones',NULL,NULL,'Planeta Cómic',NULL,'2007-09-01',NULL,NULL,replace(replace('Edición original: Deadman: Love After Death Nº 1 y 2, Deadman: Exorcism Nº 1 y 2, Action Comics Weekly 618 a 621, 623 a 626 USA          \r\nCoincidiendo con el mes especial dedicado a Deadman, se recopila en un único volumen todo el trabajo realizado por Kelley Jones para el hombre muerto más famoso de Gotham. Desde las miniseries de dos números Exorcism y Love After Death hasta las historias de complemento que aparecieron en Action Comics Weekly, todo escrito por Mike Baron. Jones aporta un punto de vista único y personal a Deadman, que viene a enriquecer más los presentados por Neal Adams y José Luis García López en sendos libros publicados este mes.','\r',char(13)),'\n',char(10)),NULL,NULL,272,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775491891380-zm4t96.jpg','read',0,4,NULL,'2026-04-06 16:11:32','2026-04-06 16:13:25',NULL,16.95,'Rústica','[{"name":"Mike Baron","role":"Guion"},{"name":"Kelley Jones","role":"Dibujo"},{"name":"Daniel Vozzo","role":"Color"},{"name":"Tony DeZuñiga","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(199,'Batman: El Ankh','Batman: El Ankh',NULL,NULL,'978-8-417-24334-0',NULL,'Chuck Dixon','John Van Fleet',NULL,NULL,'ECC Ediciones',NULL,'2017-10-30',NULL,NULL,replace('Contiene Batman: The Ankh #1-2 USA\rArgumento: Procede de una era antigua, muy anterior a la existencia de Batman, muy anterior a la existencia de Gotham. Viene de un lugar remoto en busca de redención y venganza. Su nombre es Khatera. Nacida en los tiempos de los faraones, ahora regresa a la vida y sus propósitos son tan misteriosos como la magia que la ha traído de vuelta desde la oscuridad. Ningún mortal puede detenerla. Ni siquiera Batman.','\r',char(13)),NULL,NULL,104,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775491949841-xutd1m.jpg','unread',0,NULL,NULL,'2026-04-06 16:12:30','2026-04-06 16:12:30',NULL,10.5,'Rústica','[{"name":"Chuck Dixon","role":"Guion"},{"name":"John Van Fleet","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(200,'Superman / Batman / Wonder Woman: Metrópolis','Superman / Batman / Wonder Woman: Metrópolis',NULL,NULL,'978-8-416-94595-5',NULL,'Randy Lofficier','Ted McKeever',NULL,NULL,'ECC Ediciones',NULL,'2017-02-06',NULL,NULL,'EDICIÓN ORIGINAL: Superman',NULL,NULL,208,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775491993049-i1v0mz.jpg','read',0,NULL,NULL,'2026-04-06 16:13:08','2026-04-06 16:13:21',NULL,NULL,'Rústica','[{"name":"Randy Lofficier","role":"Guion"},{"name":"Jean-Marc Lofficier","role":"Guion"},{"name":"Ted McKeever","role":"Dibujo, Tinta, Color"},{"name":"Roy Thomas","role":"Guion"},{"name":"Chris Chuckry","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(201,'Batman: La maldición que cayó sobre Gotham. Otros mundos','Batman: La maldición que cayó sobre Gotham. Otros mundos',NULL,NULL,'978-8-415-92540-8',NULL,'Mike Mignola','Mike Mignola',NULL,NULL,'ECC Ediciones',NULL,'2013-08-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman: The doom that came to Gotham núms. 1 a 3 USA \r\nAlejado de su ciudad natal durante dos décadas, Bruce Wayne organiza un equipo de rescate con la intención de averiguar qué le sucedió a la Expedición Cobblepot, accidentada en la Antártida. Una vez allí, el acaudalado aventurero –que en realidad es Batman– descubre una cueva donde se conservan los vestigios de un mal ancestral, cuya terrible naturaleza le impulsa a destruir semejante lugar y regresar a su hogar: una Gotham City donde comienzan a suceder acontecimientos extraordinarios...\r\nCreada por Mike Mignola en colaboración con Richard Pace y Troy Nixey, Batman: La maldición que cayó sobre Gotham se ajusta al concepto de la línea Otros Mundos: relatos donde se saca a los héroes de sus escenarios habituales y se les coloca en tiempos y lugares extraños; en este caso, para establecer un punto de encuentro entre el imaginario lovecraftiano y la mitología del Caballero Oscuro.','\r',char(13)),'\n',char(10)),NULL,NULL,160,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775492059565-cw980v.jpg','unread',0,NULL,NULL,'2026-04-06 16:14:23','2026-04-06 16:14:50',NULL,14.95,'Rústica','[{"name":"Mike Mignola","role":"Guion, Dibujo, Tinta, Color"},{"name":"Richard Pace","role":"Guion"},{"name":"Troy Nixey","role":"Dibujo"},{"name":"Dennis Janke","role":"Tinta"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(202,'Superman: Hijo Rojo','Superman: Hijo Rojo',NULL,NULL,'978-8-416-40921-1',NULL,'Mark Millar','Dave Johnson',NULL,NULL,'ECC Ediciones',NULL,'2013-04-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL USA:  Superman: Red Son #1-3. Incluye Extras.\r\nEn esta versión de la conocida historia, cierto cohete kryptoniano se estrella en la Tierra, llevando a un bebé que un día se convertirá en el ser más poderoso del planeta. Pero su nave no se estrella en América. No crece en Smallville, Kansas. En lugar de eso, encuentra su hogar en una granja colectiva de la Unión Soviética. \r\nSurgida de la mente de Mark Millar, el autor de las aclamadas obras The Authority y Wanted, llega esta visión extrañamente diferente sobre el mito de Superman. Con artistas de la talla de Dave Johnson, Kilian Plunkett, Andrew Robinson y Walden Wong, además de una introducción a cargo del productor cinematográfico Tom DeSanto (X-Men, Transformers y Transformers 2: La venganza de los caídos), este tomo también contiene una extensa galería de bocetos de Johnson, Plunkett y Alex Ross.','\r',char(13)),'\n',char(10)),NULL,NULL,168,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775492145493-4l6be4.jpg','read',0,3,NULL,'2026-04-06 16:15:50','2026-04-06 16:15:54',NULL,24.95,'Rústica','[{"name":"Mark Millar","role":"Guion"},{"name":"Dave Johnson","role":"Dibujo"},{"name":"Andrew Robinson","role":"Tinta"},{"name":"Paul Mounts","role":"Color"},{"name":"Kilian Plunkett","role":"Dibujo"},{"name":"Walden Wong","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(203,'Superman: La Llegada de H','Superman: La Llegada de H''el',3,NULL,'978-8-415-92507-1',NULL,'Scott Lobdell','Mike Johnson',NULL,NULL,'ECC Ediciones',NULL,'2013-07-01',NULL,NULL,replace(replace('Comics USA: Superman 16-17, Supergirl 17, Superboy 17\r\nHistorias:\r\n¡El palito mas corto! \r\n¡Una causa perdida)  \r\nUna chica contra una diosa  \r\nFuria en el fin del mundo \rLa Tierra está en jaque tras la llegada de un kryptoniano llamado H’El, que consiguió embaucar a Supergirl para ayudarlo en su propósito de activar una máquina para regresar al pasado y evitar la destrucción de Krypton. Cuando descubrieron que el plan de H’El causaría colateralmente la destrucción de la Tierra, Superman, Superboy y la Liga de la Justicia tomaron cartas en el asunto para impedir que el villano lograra su objetivo.\rAhora, parapetado en la Fortaleza de la Soledad de Superman como base de operaciones, H’El está listo para la última fase de su plan. ¿Conseguirán los héroes de la Tierra derrotarlo y salvar su mundo?','\r',char(13)),'\n',char(10)),NULL,NULL,96,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775492214761-vdlbrv.jpg','read',0,NULL,NULL,'2026-04-06 16:16:47','2026-04-07 07:51:37',34,NULL,'Rústica','[{"name":"Scott Lobdell","role":""},{"name":"Mike Johnson","role":""},{"name":"Tom DeFalco","role":""},{"name":"Kenneth Rocafort","role":""},{"name":"Mahmud Asrar","role":""},{"name":"R. B. Silva","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(204,'Green Lantern Corps #7','Green Lantern Corps',7,NULL,'978-8-467-49380-1',NULL,'Peter J. Tomasi','Luke Ross',NULL,NULL,'Planeta Cómic',NULL,'2010-07-01',NULL,NULL,replace(replace('La noche más oscura ha empezado. La lucha entre muertos y vivos se extiende por todo el universo y son muchos los héroes que están haciendo frente a los zombis: Superman, Batman, Booster Gold y, por supuesto, Hal Jordan. Ahora ha llegado el momento de que el resto del Cuerpo de Green Lanterns aporte su granito de arena aunque, por el momento, aún no puedan moverse de Oa. Eso sí, es solo cuestión de tiempo que se unan a una contienda que ha puesto en jaque a toda la creación y que amenaza incluso con consumirla.\r\nN° edición original 39-42','\r',char(13)),'\n',char(10)),NULL,NULL,168,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775492289749-4u2uas.jpg','read',0,NULL,NULL,'2026-04-06 16:18:14','2026-04-07 07:51:37',35,NULL,'Rústica','[{"name":"Luke Ross","role":"Dibujo"},{"name":"Patrick Gleason","role":"Dibujo"},{"name":"Peter J. Tomasi","role":"Guion"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(205,'Green Lantern: Prólogo a la Ascensión del Tercer Ejército','Green Lantern: Prólogo a la Ascensión del Tercer Ejército',NULL,NULL,'978-8-415-84410-5',NULL,'Geoff Johns','Peter J. Tomasi',NULL,NULL,'ECC Ediciones',NULL,'2013-04-01',NULL,NULL,replace(replace('Contiene: GREEN LANTERN 0, GREEN LANTERN CORPS 0, GREEN LANTERN: NEW GUARDIANS 0 USA.\r\nLa sociedad nunca ha tratado bien a Simon Baz. Pero ahora, se va a convertir en... ¡el Green Lantern oficial de la Tierra! Descubre el origen de este nuevo personaje y también el de otros más conocidos como Guy Gardner o Atrocitus en un volumen donde autores como Geoff Johns (Liga de la Justicia), Doug Mahnke (Crisis final) o Peter J. Tomasi (Batman y Robin) preparan la saga La ascensión del Tercer Ejército, que pondrá patas arriba la franquicia de Green Lantern durante los próximos meses.','\r',char(13)),'\n',char(10)),NULL,NULL,96,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775492347527-ovojnv.jpg','read',0,NULL,NULL,'2026-04-06 16:19:09','2026-04-07 07:51:37',NULL,NULL,'Rústica','[{"name":"Geoff Johns","role":""},{"name":"Peter J. Tomasi","role":""},{"name":"Tony Bedard","role":""},{"name":"Peter Milligan","role":""},{"name":"Doug Mahnke","role":""},{"name":"Fernando Pasarín","role":""},{"name":"Aaron Kuder","role":""},{"name":"Andrei Bressan","role":""},{"name":"Ardian Syaf","role":""}]');
