INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(207,'Green Lantern: Apagón','Green Lantern: Apagón',NULL,NULL,'978-8-416-07015-2',NULL,'Charles Soule','Bernard Chang',NULL,NULL,'ECC Ediciones',NULL,'2014-02-28',NULL,NULL,replace(replace('USA: Green Lantern Vol. 5 nº 24, Green Lantern: New Guardians Vol. 1 nº 24, Green Lantern Corps Vol. 2 nº 24, Red Lanterns Vol. 1 nº 24, Green Lantern Vol. 5 Annual nº 02\r\n¿Quién es Relic? Cuando encontraron la Anomalía, el único White Lantern del universo conocido -Kyle Rayner- y los Guardianes Templarios -supervivientes de su legendaria estirpe que pasaron miles de millones de años en cautiverio- ni siquiera imaginaban que en su interior podría habitar un enemigo así. Científico de un universo desaparecido por culpa de los Forjaluces, Relic encuentra un nuevo propósito al despertar en nuestra existencia como un poderosos ente cósmico y decide que no se dentedrá ante nada hasta terminar con los Lanterns de cuaqluier color. Su amenaza es de tal magnitud que quizá todos los Corps se vean obligados a unirse contra él en un desesperado intento de evitar el Apagón.','\r',char(13)),'\n',char(10)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775492445714-dfmalb.jpg','read',0,NULL,NULL,'2026-04-06 16:20:48','2026-04-07 07:51:37',NULL,NULL,'Rústica','[{"name":"Charles Soule","role":"Guion"},{"name":"Justin Jordan","role":"Guion"},{"name":"Robert Venditti","role":"Guion"},{"name":"Bernard Chang","role":"Dibujo"},{"name":"Billy Tan","role":"Dibujo"},{"name":"Brad Walker","role":"Dibujo"},{"name":"Van Jensen","role":"Guion"},{"name":"Alessandro Vitti","role":"Dibujo"},{"name":"Rafael Albuquerque","role":"Dibujo, Tinta"},{"name":"Sean Chen","role":"Dibujo"},{"name":"Rob Hunter","role":"Tinta"},{"name":"Andrew Hennessy","role":"Tinta"},{"name":"Marc Deering","role":"Tinta"},{"name":"Ryan Winn","role":"Tinta"},{"name":"Jonathan Sibal","role":"Tinta"},{"name":"Walden Wong","role":"Tinta"},{"name":"Alex Sinclair","role":"Color"},{"name":"Marcelo Maiolo","role":"Color"},{"name":"Will Quintana","role":"Color"},{"name":"Gabe Eltaeb","role":"Color"},{"name":"Andrew Dalhouse","role":"Color"},{"name":"J.G. Jones","role":"Dibujo, Tinta"},{"name":"Paul Mounts","role":"Color"},{"name":"Stephen Segovia","role":"Dibujo, Tinta"},{"name":"Dave McCaig","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(208,'Detective Marciano: Identidad','Detective Marciano: Identidad',NULL,NULL,'978-8-419-32579-2',NULL,'Steve Orlando','Riley Rossmo',NULL,NULL,'ECC Ediciones',NULL,'2022-07-26',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Martian Manhunter Vol. 5 Núms. 1-12 USA\r\nJohn Jones es uno de los policías más competentes de Midleton, Colorado. No obstante, mientras investiga un macabro asesinato, descubre que hay un elemento de su pasado que ha regresado para atormentarlo. Y es que Jones no es un humano normal. De hecho, ni siquiera es humano. Es J’onn J’onzz, el único superviviente de Marte, cuya civilización desapareció hace mucho tiempo. Como Detective Marciano, se ha enfrentado a numerosas amenazas en solitario y en compañía de la Liga de la Justicia, pero ¿sobrevivirá al caso más complicado de su carrera?','\r',char(13)),'\n',char(10)),NULL,NULL,296,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775492752479-r711q3.jpg','read',0,2,NULL,'2026-04-06 16:25:53','2026-04-06 16:27:08',NULL,27.5,'Rústica','[{"name":"Steve Orlando","role":"Guion"},{"name":"Riley Rossmo","role":"Dibujo, Tinta"},{"name":"Ivan Plascencia","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(209,'Aquaman. La espada de Atlantis','Aquaman. La espada de Atlantis',NULL,NULL,'978-8-467-44250-2',NULL,'Kurt Busiek','Jackson Guice',NULL,NULL,'Planeta Cómic',NULL,'2007-09-01',NULL,NULL,'Aquaman: Sword of Atlantis 40-49 USA',NULL,NULL,240,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775492783913-dtg88m.jpg','read',0,NULL,NULL,'2026-04-06 16:26:17','2026-04-06 16:26:32',NULL,NULL,'Rústica','[{"name":"Jackson Guice","role":"Dibujo, Tinta"},{"name":"Dan Brown","role":""},{"name":"Kurt Busiek","role":"Guion"},{"name":"Mike Manley","role":"Dibujo"},{"name":"Ricardo Villagrán","role":"Dibujo, Tinta"},{"name":"Tony DeZuñiga","role":"Tinta"},{"name":"Daniel Brown","role":"Color"},{"name":"Peter Pantazis","role":"Color"},{"name":"Phil Winslade","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(210,'La Liga de los Jinetes','La Liga de los Jinetes',NULL,NULL,'978-8-416-79670-0',NULL,'Chuck Dixon','J. H. Williams III',NULL,NULL,'ECC Ediciones',NULL,'2016-07-28',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice Riders USA\r\nEn 1997, el guionista Chuck Dixon (Batman: El Caballero Oscuro - Bane) y el dibujante J.H. Williams III (Promethea, Sandman: Obertura) firmaron un relato trepidante que combinaba western, aventura, steampunk y superhéroes en uno de los mejores títulos de la línea Otros Mundos. \r\nDesde su inauguración en 1989, la línea Otros Mundos explora una atractiva premisa:¿Qué habría ocurrido con los héroes DC si hubieran vivido en otra época, en otro mundo, inmersos en unas circunstancias diferentes? En nuestro catálogo encontraréis las mejores obras surgidas al amparo de dichas preguntas.','\r',char(13)),'\n',char(10)),NULL,NULL,72,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775492813742-zlpzn0.jpg','unread',0,NULL,NULL,'2026-04-06 16:26:56','2026-04-06 16:26:56',NULL,NULL,'Rústica','[{"name":"Chuck Dixon","role":"Guion"},{"name":"J. H. Williams III","role":"Dibujo"},{"name":"Mick Gray","role":"Tinta"},{"name":"Lee Loughridge","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(211,'Antes conocidos como Liga de la Justicia','Antes conocidos como Liga de la Justicia',NULL,NULL,'978-8-496-32541-8',NULL,'J.M. DeMatteis','Kevin Maguire',NULL,NULL,'Norma Editorial',NULL,'2004-06-01',NULL,NULL,replace(replace('Traducción de la serie limitada Formerly Known As Justice League 1-6.\r\nToda la desternillante miniserie protagonizada por la clásica Liga de la Justicia de Giffen y DeMatteis en un solo tomo','\r',char(13)),'\n',char(10)),NULL,NULL,140,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775492871328-vmc8eg.jpg','read',0,4,NULL,'2026-04-06 16:27:57','2026-04-06 16:29:23',NULL,NULL,'Rústica','[{"name":"J.M. DeMatteis","role":"Guion"},{"name":"Joe Rubinstein","role":"Tinta"},{"name":"Keith Giffen","role":"Guion"},{"name":"Kevin Maguire","role":"Dibujo"},{"name":"Lee Loughridge","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(212,'Batman / Tortugas Ninja','Batman / Tortugas Ninja',NULL,NULL,'978-8-416-84011-2',NULL,'James Tynion IV','Freddie E. Williams II',NULL,NULL,'ECC Ediciones',NULL,'2016-09-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman / Teenage Mutant Ninja Turtles núms. 1-6 USA \r\nARGUMENTO: A Gotham City llegan visitas de otra dimensión... ¡y por sus caparazones no parecen visitas corrientes! Cuando las Tortugas Ninja se ven varadas junto a su maestro en la ciudad de Batman, empieza una cuenta atrás que podría poner fin a sus vidas si no logran volver a su hogar. Pero... ¿lo conseguirán cuando sus más acérrimos enemigos, Shredder y el Clan del Pie, amenazan con unirse al Pingüino, a Ra’s al Ghul y a todos los presos del Asilo Arkham?\r\nDC Comics e IDW suman fuerzas en uno de los cruces más esperados por los fans de quirópteros y quelonios por igual, hecho realidad gracias a James Tynion IV (Batman Eterno, Constantine: Hellblazer) y Freddie E. Williams II (Red Robin, Green Arrow).','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775492923237-koo4im.jpg','read',0,NULL,NULL,'2026-04-06 16:28:44','2026-04-06 16:29:19',NULL,13.95,'Rústica','[{"name":"James Tynion IV","role":"Guion"},{"name":"Freddie E. Williams II","role":"Dibujo"},{"name":"Jeremy Colwell","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(213,'Batman / Tortugas Ninja II','Batman / Tortugas Ninja II',NULL,NULL,'978-8-417-54953-4',NULL,'James Tynion IV','Freddie E. Williams II',NULL,NULL,'ECC Ediciones',NULL,'2018-09-13',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman/Teenage Mutant Ninja Turtles II núms. 1 a 6 USA\r\nDonatello llega a Gotham City, donde se reencuentra con sus amigos Batman y Robin en un momento que no es precisamente oportuno. Y es que la Liga de Asesinos ha decidido prescindir de Ra’s al Ghul tras el incidente con Shredder, y ahora la organización cuenta con un líder nuevo que es aún más temible que la Cabeza del Demonio.\r\nLos guionistas James Tynion IV (Batman: Detective Comics) y Ryan Ferrier y el dibujante Freddie Williams II (Siete Soldados de la Victoria) nos traen la secuela del éxito Batman/Tortugas Ninja, un volumen repleto de aventuras, del humor habitual de estos mutantes y, por supuesto, de enemigos propios de dos de los universos de ficción más populares del mundo del cómic.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775492947752-c8yaha.jpg','read',0,NULL,NULL,'2026-04-06 16:29:10','2026-04-06 16:29:15',NULL,NULL,'Rústica','[{"name":"James Tynion IV","role":"Guion"},{"name":"Ryan Ferrier","role":"Guion"},{"name":"Freddie E. Williams II","role":"Dibujo, Tinta"},{"name":"Jeremy Colwell","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(214,'La Visión. 100% Marvel #1','La Visión. 100% Marvel',1,NULL,'978-8-490-94602-2',NULL,'Tom King','Gabriel Hernández Walta',NULL,NULL,'Panini Comics España',NULL,'2016-06-16',NULL,NULL,replace(replace('Contiene The Vision v2, 1-6 USA \r\n¡Llega una de las más aclamadas series del momento! La Visión quiere ser humano. ¿Y qué hay más humano que la familia? Ahora, la tiene. Una mujer y dos hijos. Se parecen a él, tienen sus poderes y la necesidad de confundirse con los demás. ¿Qué puede ir mal?','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775493014899-jm7mgw.jpg','read',0,NULL,NULL,'2026-04-06 16:30:20','2026-04-07 07:51:37',36,13.5,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Gabriel Hernández Walta","role":"Dibujo, Tinta"},{"name":"Jordie Bellaire","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(215,'La Visión. 100% Marvel #2','La Visión. 100% Marvel',2,NULL,'978-8-490-94876-7',NULL,'Tom King','Gabriel Hernández Walta',NULL,NULL,'Panini Comics España',NULL,'2017-02-09',NULL,NULL,replace(replace('Contiene The Vision v2, 7-12 USA\r\nLa conclusión de la más aclamada obra Marvel de los últimos tiempos. Hace algún tiempo, un robot creó una familia, y las cosas fueron bien por un tiempo. Luego llegaron las muertes, las mentiras, las traiciones, las batallas ganadas y las perdidas.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775493035276-huogn7.jpg','read',0,NULL,NULL,'2026-04-06 16:30:35','2026-04-07 07:51:37',36,NULL,'Rústica','[{"name":"Tom King","role":"Guion"},{"name":"Gabriel Hernández Walta","role":"Dibujo, Tinta"},{"name":"Jordie Bellaire","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(216,'Thanos: Infinito (2013). 100% Marvel','Thanos: Infinito (2013). 100% Marvel',NULL,NULL,'978-8-490-24558-3',NULL,'Jason Aaron','Simone Bianchi',NULL,NULL,'Panini Comics España',NULL,'2013-11-01',NULL,NULL,replace(replace('Contiene Thanos Rising 1-5 USA\r\nEl prólogo del evento Marvel protagonizado por el Titán Loco. ¿Quién es realmente este aterrador villano? La verdad sale la luz, en este relato de tragedia, engaño y destino en el que dos auténticas estrellas del cómic mundial narran la vida de Thanos. ¿De dónde vino? ¿Qué espera del Universo? ¿Por qué está obsesionado con la encarnación de la muerte? Jason Aaron (Lobezno y La Patrulla-X, Thor: Dios del Trueno y Simone Bianchi (Astonishing X-Men) sacan a relucir las entrañas del más temible villano cósmico jamás creado.','\r',char(13)),'\n',char(10)),NULL,NULL,120,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775493066935-hzw4lq.jpg','read',0,3,NULL,'2026-04-06 16:31:10','2026-04-06 16:31:17',NULL,NULL,'Rústica','[{"name":"Jason Aaron","role":"Guion"},{"name":"Simone Bianchi","role":"Dibujo, Tinta, Color"},{"name":"Simone Peruzzi","role":"Color"},{"name":"Ive Svorcina","role":"Color"},{"name":"Riccardo Pieruccini","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(217,'Lobezno: Snikt! 100% Marvel','Lobezno: Snikt! 100% Marvel',NULL,NULL,'977-2-424-81800-4',NULL,'Tsutomu Nihei','Tsutomu Nihei',NULL,NULL,'Panini Comics España',NULL,'2005-05-01',NULL,NULL,replace(replace('Contiene Wolverine: Snikt! 1-5 USA\r\nEn una ciudad semi abandonada, entre ruinas mastodónticas, los últimos supervivientes de la raza humana huyen del monstruo de carne y metal que les da caza despiadadamente. La última esperanza es un mutante venido del pasado...','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775493098637-bwpgzl.jpg','read',0,4,NULL,'2026-04-06 16:31:40','2026-04-06 16:31:44',NULL,10,'Rústica','[{"name":"Tsutomu Nihei","role":"Guion, Dibujo, Tinta"},{"name":"Guru-eFX","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(218,'Marvel Noir: Daredevil','Marvel Noir: Daredevil',NULL,NULL,'978-8-498-85412-1',NULL,'Alexander Irvine','Tomm Coker',NULL,NULL,'Panini Comics España',NULL,'2010-06-01',NULL,NULL,replace(replace('Contiene: Daredevil Noir #1-4 USA (2009).\r\nUna visión única del Diablo Guardián. Durante la época de la Ley Seca, la Cocina del Infierno es el territorio de Kingpin. Su único problema es un vigilante enmascarado que se hace llamar Daredevil. Pero el infierno se vuelve más caliente después de que el gánster Orville Halloran salga de la cárcel de Sing Sing. Para el investigador privado Foggy Nelson y su ayudante Matt Murdock, todo empieza cuando una mujer desesperada llama a su puerta.','\r',char(13)),'\n',char(10)),NULL,NULL,104,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775493850400-9ylm7g.jpg','read',0,4,NULL,'2026-04-06 16:44:13','2026-04-06 16:44:21',NULL,NULL,'Rústica','[{"name":"Alexander Irvine","role":"Guion"},{"name":"Daniel Freedman","role":"Color"},{"name":"Tomm Coker","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(219,'Marvel Zombies vs Army of Darkness. El ejército de las tinieblas','Marvel Zombies vs Army of Darkness. El ejército de las tinieblas',NULL,NULL,'978-8-496-99138-5',NULL,'John Layman','Fabiano Neves',NULL,NULL,'Panini Comics España',NULL,'2008-03-01',NULL,NULL,replace(replace('Contiene Marvel Zombies Vs. Army of Darkness 1-5 USA\r\n¡El cruce editorial más indigesto del siglo! Los Marvel Zombies se ven las caras con Ash, el héroe protagonista de El Ejército de las Tinieblas, la mítica película dirigida por Sam Raimi y que ahora se ha convertido en un espectacular cómic. Ash se las ha visto con toda clase de no-muertos, pero nunca como éstos. Contempla cómo sus acciones, lejos de solucionar nada, ayudarán a que héroes y villanos se conviertan en zombies, en un cómic realizado con el asesoramiento de Robert Kirkman y con Arthur Suydam como portadista.','\r',char(13)),'\n',char(10)),NULL,NULL,128,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775493928115-iarjum.jpg','read',0,NULL,NULL,'2026-04-06 16:45:29','2026-04-06 16:45:34',NULL,11,'Rústica','[{"name":"Fabiano Neves","role":"Dibujo"},{"name":"John Layman","role":"Guion"},{"name":"June Chung","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(221,'Ghost Rider. 100% Marvel #1','Ghost Rider. 100% Marvel',1,NULL,'978-8-496-87123-6',NULL,'Daniel Way','Javier Saltares',NULL,NULL,'Panini Comics España',NULL,'2007-09-01',NULL,NULL,replace(replace('Contiene: Ghost Rider Vol. 6 #1-5 USA\r\n¡La colección 100 % Marvel continúa con la nueva serie del Espíritu de la Venganza y su primer arco argumental: &quot;Círculo vicioso&quot;! Johnny Blaze hizo un trato con el Diablo. Ahora, atrapado en el infierno, ha encontrado una manera de escapar, pero, ¿cuál será el precio? Junto a él, alguien más ha huido, y el Motorista Fantasma debe llevarle de vuelta, antes de que consiga instaurar el hades sobre la faz de la Tierra. En el camino, encontrará a ciertos enemigos que prefieren verle fracasar en tal misión. Y tal vez lo consigan.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775493993566-s8rknq.jpg','read',0,NULL,NULL,'2026-04-06 16:46:37','2026-04-07 07:47:33',37,NULL,'rustica','[{"name":"Daniel Way","role":"Guion"},{"name":"Javier Saltares","role":"Dibujo"},{"name":"Mark Texeira","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(222,'Ghost Rider. 100% Marvel #2','Ghost Rider. 100% Marvel',2,NULL,'978-8-496-99106-4',NULL,'Daniel Way','Javier Saltares',NULL,NULL,'Panini Comics España',NULL,'2008-01-01',NULL,NULL,replace(replace('Contiene: Ghost Rider Vol. 6 #6-11 USA\r\nCon dos historias autoconclusivas, la segunda ligada con la conclusión de Civil War. ¿Cómo acabó Johnny Blaze en el infierno? Muy sencillo. Murió. Y cuando lo hizo, su alma eterna descendió al abismo, llevando con ella al Motorista Fantasma. Esta es la historia de cómo y porqué ocurrió todo eso, cortesía del guionista Daniel Way y de la leyenda del cómic de terror Richard Corben. Además: en una pequeña localidad al norte de Chicago, alguien está dejando un reguero de decapitados. El sheriff cree conocer quién es el culpable.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775494009481-2n8kzi.jpg','read',0,NULL,NULL,'2026-04-06 16:46:50','2026-04-07 07:47:33',37,NULL,'rustica','[{"name":"Daniel Way","role":"Guion"},{"name":"Javier Saltares","role":"Dibujo"},{"name":"Mark Texeira","role":"Dibujo"},{"name":"Richard Corben","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(224,'Ghost Rider: Autopista al infierno. 100% Marvel','Ghost Rider: Autopista al infierno. 100% Marvel',NULL,NULL,'978-8-496-73428-9',NULL,'Clayton Crain','Garth Ennis',NULL,NULL,'Panini Comics España',NULL,'2007-02-01',NULL,NULL,replace(replace('Contiene: Ghost Rider Vol. 5 #1-6 USA (Road To Damnation).\r\n¡El esperado regreso del Espíritu de la Venganza! Coincidiendo con el estreno en cines de la película protagonizada por Nicholas Cage, llega a las librerías este espectacular tomo escrito por Garth Ennis (MAX Punisher) y dibujado por el artista digital Clayton Crain. Johnny Blaze está pagando un precio incalculable por el trato que hizo con el Diablo. Pero, ¿está condenado a correr por las autopistas del infierno durante toda la eternidad? Su última esperanza descansa en un inesperado aliado.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775494194603-3ai19a.jpg','read',0,NULL,NULL,'2026-04-06 16:49:58','2026-04-06 16:50:29',NULL,NULL,'Rústica','[{"name":"Clayton Crain","role":""},{"name":"Garth Ennis","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(225,'Ghost Rider: Reguero de lágrimas. 100% Marvel','Ghost Rider: Reguero de lágrimas. 100% Marvel',NULL,NULL,'978-8-498-85013-0',NULL,'Garth Ennis','Clayton Crain',NULL,NULL,'Panini Comics España',NULL,'2008-08-01',NULL,NULL,replace(replace('Correspondencia Original: Ghost Rider: Trail Of Tears 1 a 6\r\n¡La precuela de Ghost Rider: Autopista al infierno! Como teniente del ejército confederado, Travis Parham se mantuvo hundido hasta el cuello en barro y sangre, rodeado por la metralla y los gritos de sus hombres. Dos años después, Parham ha conseguido rehacer su vida. Sin embargo, el tranquilo mundo de Parham va a llegar a su final. De lo más profundo se alza una fuerza de la naturaleza que trasciende sus sueños más extraños, una ira salvaje que sabe una o dos cosas sobre la maldad, e incluso algunas más sobre la venganza.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775494434856-c6etfl.jpg','read',0,NULL,NULL,'2026-04-06 16:53:56','2026-04-06 16:53:58',NULL,12,'Rústica','[{"name":"Clayton Crain","role":"Dibujo"},{"name":"Garth Ennis","role":"Guion"},{"name":"Matt Hollingsworth","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(226,'Batman: El último caballero de la Tierra #1','Batman: El último caballero de la Tierra',1,NULL,'978-8-417-96089-6',NULL,'Scott Snyder','Greg Capullo',NULL,NULL,'ECC Ediciones',NULL,'2019-09-17',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman: Last Knight on Earth - Book One USA\r\nBruce Wayne se despierta en el Asilo Arkham. Joven. Cuerdo. Y… sin haber sido nunca Batman. Así comienza esta épica aventura del Caballero Oscuro, embarcado en una misión que le llevará a recorrer parajes devastados. En su camino, se encontrará con numerosas caras familiares, mientras trata de desentrañar las claves de su enigmático pasado y de averiguar qué sucedió para que el mundo que conocía haya desaparecido.\r\nScott Snyder y Greg Capullo, el equipo creativo responsable de sagas como El tribunal de los búhos o Noches Oscuras: Metal, afrontan uno de sus proyectos más ambiciosos: Batman: El último caballero de la Tierra, miniserie de tres entregas en la que están dispuestos a narrar… ¿la última historia de Batman?','\r',char(13)),'\n',char(10)),NULL,NULL,56,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775495439965-k08ya3.jpg','read',0,NULL,NULL,'2026-04-06 17:10:44','2026-04-07 07:47:33',38,NULL,'cartone','[{"name":"Scott Snyder","role":"Guion"},{"name":"Greg Capullo","role":"Dibujo"},{"name":"Jonathan Glapion","role":"Tinta"},{"name":"FCO Plascencia","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(227,'Batman: El último caballero de la Tierra #2','Batman: El último caballero de la Tierra',2,NULL,'978-8-418-04356-7',NULL,'Scott Snyder','Greg Capullo',NULL,NULL,'ECC Ediciones',NULL,'2019-11-12',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman: Last Knight on Earth - Book One USA\r\nEl mundo ha sido destruido y, con la única compañía de la cabeza decapitada del Joker, Batman intenta descubrir quién es el responsable de lo acontecido. A medida que se adentra en parajes más y más peligrosos que dificultan sobremanera su misión, el Caballero Oscuro encuentra un inesperado aliado en el lugar conocido como la llanura de la soledad…\r\nResponsable de sagas tan exitosas como El tribunal de los búhos o Noches Oscuras: Metal, el equipo creativo formado por Scott Snyder y Greg Capullo se reúnen de nuevo para desarrollar uno de sus proyectos más ambiciosos: Batman: El último caballero de la Tierra, miniserie que con esta entrega alcanza su ecuador.','\r',char(13)),'\n',char(10)),NULL,NULL,56,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775495460220-y58aql.jpg','read',0,NULL,NULL,'2026-04-06 17:11:00','2026-04-07 07:47:33',38,NULL,'Rústica','[{"name":"Scott Snyder","role":"Guion"},{"name":"Greg Capullo","role":"Dibujo"},{"name":"Jonathan Glapion","role":"Tinta"},{"name":"FCO Plascencia","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(228,'Batman: El último caballero de la Tierra #3','Batman: El último caballero de la Tierra',3,NULL,'978-8-418-18055-2',NULL,'Scott Snyder','Greg Capullo',NULL,NULL,'ECC Ediciones',NULL,'2020-03-10',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman: Last Knight on Earth - Book Three USA\r\nGotham ha sido transformada bajo el reinado de Omega, quien somete a sus ciudadanos bajo el control de la señal de la antivida. ¿Podrá Batman lograr lo que ningún otro héroe ha conseguido y liberar al mundo de la sombra de su oscuro reflejo? Con la inestimable ayuda de sus más fieles aliados, el Cruzado de la Capa afronta la batalla definitiva. ¿Será demasiado tarde?\r\nResponsable de sagas tan exitosas como El tribunal de los búhos o Noches Oscuras: Metal, el equipo creativo formado por Scott Snyder y Greg Capullo pone punto y final a Batman: El último caballero de la Tierra. Uno de sus proyectos más ambiciosos, con el que ponen un broche de oro a su aportación a la mitología del Hombre Murciélago.','\r',char(13)),'\n',char(10)),NULL,NULL,56,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775495462941-d43wzp.jpg','read',0,NULL,NULL,'2026-04-06 17:11:03','2026-04-07 07:47:33',38,NULL,'Rústica','[{"name":"Scott Snyder","role":"Guion"},{"name":"Greg Capullo","role":"Dibujo"},{"name":"Jonathan Glapion","role":"Tinta"},{"name":"FCO Plascencia","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(229,'Marvel One-Shot #6','Marvel One-Shot',6,NULL,'9788410515970-00006',NULL,'Jonathan Hickman','Esad Ribic',NULL,NULL,'Panini Comics España',NULL,'2025-09-11',NULL,NULL,'¡El choque de los Vengadores contra los Xenomorfos! Todo ha llevado a esto: el organismo más perfecto del universo ha llegado a la Tierra, un planeta lleno de superhumanos. ¿Cuál será el primero en caer? El legendario equipo creativo compuesto por Jonathan Hickman y Esad Ribić (',NULL,NULL,160,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775495493847-7skkns.jpg','read',0,3,NULL,'2026-04-06 17:11:37','2026-04-06 17:11:59',39,14,'Rústica','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"Esad Ribic","role":"Dibujo, Tinta"},{"name":"Ive Svorcina","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(231,'Marvel One-Shot #8','Marvel One-Shot',8,NULL,'9788410515970-00008',NULL,'Benjamin Percy','Marcelo Ferreira',NULL,NULL,'Panini Comics España',NULL,'2025-11-13',NULL,NULL,replace(replace('Una ola de calor deja a Nueva York a oscuras y a Spiderman de patrulla mientras los ánimos se caldean por toda la ciudad. Bajo sus mugrientas alcantarillas y subterráneos acecha una amenaza como ninguna otra a la que Peter Parker se haya enfrentado antes. Presentamos a un Depredador sin honor ni clan: solo sed de sangre. ¡Escrito por Benjamin Percy y exquisitamente representado por el artista superestrella Marcelo Ferreira!\r\n104 pp | 11 €','\r',char(13)),'\n',char(10)),NULL,NULL,104,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775495565160-umpma3.jpg','read',0,4,NULL,'2026-04-06 17:12:46','2026-04-06 17:13:15',39,NULL,'Rústica','[{"name":"Benjamin Percy","role":"Guion"},{"name":"Marcelo Ferreira","role":"Dibujo"},{"name":"Jay Leisten","role":"Tinta"},{"name":"Frank D''Armata","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(232,'TMNT. Las Tortugas Ninja #1','TMNT. Las Tortugas Ninja',1,NULL,'978-8-498-14745-2',NULL,'Kevin Eastman','Kevin Eastman',NULL,NULL,'Norma Editorial',NULL,'2006-11-01',NULL,NULL,replace(replace('Teenage Mutant Ninja Turtles #1-6, TMNT Micro-Series: Raphael\r\n¡Ya están aquí las Tortugas Ninja! Mientras Donatello, Raphael, Michaelangelo y Leonardo preparan su regreso a la gran pantalla con una película de animación digital, Kevin Eastman y Peter Laird nos presentan las primeras aventuras de estas criaturas, que se han convertido en un fenómeno mundial en todos los ámbitos. Su origen,sus peores enemigos y sus aventuras más locas nos esperan en esta serie.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775495692904-6wzaxd.jpg','unread',0,NULL,NULL,'2026-04-06 17:14:56','2026-04-06 17:14:56',40,NULL,'rustica','[{"name":"Kevin Eastman","role":"Guion, Dibujo, Tinta"},{"name":"Peter Laird","role":"Guion, Dibujo, Tinta"},{"name":"Richard Corben","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(233,'TMNT. Las Tortugas Ninja #2','TMNT. Las Tortugas Ninja',2,NULL,'978-8-498-14746-9',NULL,'Kevin Eastman','Kevin Eastman',NULL,NULL,'Norma Editorial',NULL,'2007-02-01',NULL,NULL,replace(replace('Teenage Mutant Ninja Turtles #7-10, TMNT Micro-Series: Leonardo\rContinúan las historias originales de las criaturas de Kevin Eastman y Peter Laird . LAS TORTUGAS NINJA, todo un fenómeno de masas mundial, regresan a lo más alto y con más fuerza que nunca gracias al estreno de la próxima película de animación digital. \r\nNuestros amigos mutantes vuelven a la Tierra después de su viaje por el espacio exterior, pero no están solos. Unos temibles triceratones los han acompañado por error en su viaje de vuelta a casa. Y eso no será todo, porque su peor enemigo está sediento de venganza.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775495710335-rfzg5h.jpg','unread',0,NULL,NULL,'2026-04-06 17:15:11','2026-04-06 17:15:11',40,NULL,'rustica','[{"name":"Kevin Eastman","role":"Guion, Dibujo, Tinta"},{"name":"Peter Laird","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(234,'TMNT. Las Tortugas Ninja #3','TMNT. Las Tortugas Ninja',3,NULL,'978-8-498-14747-6',NULL,'Kevin Eastman','Kevin Eastman',NULL,NULL,'Norma Editorial',NULL,'2007-04-01',NULL,NULL,replace(replace('Teenage Mutant Ninja Turtles #11, #19-21, #28, Tales of the TMNT\r\nEl cuarteto de mutantes adolescentes creado por Kevin Eastman y Peter Laird, protagoniza una nueva aventura llena de acción en una serie que se ha convertido en un referente del cómic americano independiente. Las tortugas ninja deberán enfrentarse de nuevo a sus peores y más terribles enemigos.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775495713242-pzpl30.jpg','unread',0,NULL,NULL,'2026-04-06 17:15:13','2026-04-06 17:15:13',40,NULL,'rustica','[{"name":"Kevin Eastman","role":"Guion, Dibujo, Tinta"},{"name":"Peter Laird","role":"Guion, Dibujo, Tinta"},{"name":"Steve Murphy","role":"Dibujo"},{"name":"Jim Lawson","role":"Dibujo"},{"name":"Ryan Brown","role":"Dibujo"},{"name":"Eric Talbot","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(235,'TMNT. Las Tortugas Ninja #4','TMNT. Las Tortugas Ninja',4,NULL,'978-8-498-14748-3',NULL,'Kevin Eastman','Kevin Eastman',NULL,NULL,'Norma Editorial',NULL,'2007-06-01',NULL,NULL,replace('Teenage Mutant Ninja Turtles #48-53\rEl autoimpuesto exilio de las Tortugas Ninja toca a su fin. Tras la muerte de Shredder, el caso se ha apoderado de Nueva York. Ha llegado el momento de que los héroes con caparazón vuelvan a la ciudad y se enfrenten a las bandas criminales que se han adueñado de las calles.','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775495715502-vkjdzl.jpg','unread',0,NULL,NULL,'2026-04-06 17:15:16','2026-04-06 17:15:16',40,NULL,'rustica','[{"name":"Kevin Eastman","role":"Guion, Dibujo, Tinta"},{"name":"Peter Laird","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(236,'TMNT. Las Tortugas Ninja #5','TMNT. Las Tortugas Ninja',5,NULL,'978-8-498-14749-0',NULL,'Peter Laird','Jim Lawson',NULL,NULL,'Norma Editorial',NULL,'2007-09-01',NULL,NULL,replace(replace('Teenage Mutant Ninja Turtles #54-62\rLegamos al final de la serie clásica de Las Tortugas Ninja. Eastman y Laird , los creadores de los héroes con caparazón más famosos del mundo, firman el final de la saga “ciudad en guerra”. ¡Empieza una nueva era! \r\nLa familia que formaban las tortugas ninja y sus amigos ya no existe. Casey intenta enderezar su vida con Gabby, April huye a California escapando de sus problemas, y Splinter busca el camino de la iluminación. Mientras tanto, la ciudad se está cayendo a pedazos y nadie puede hacer nada por salvarla.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775495718575-t1vx2p.jpg','unread',0,NULL,NULL,'2026-04-06 17:15:19','2026-04-06 17:15:19',40,NULL,'rustica','[{"name":"Peter Laird","role":"Guion"},{"name":"Jim Lawson","role":"Guion, Dibujo"},{"name":"Keith Aiken","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(239,'Vampirella de Pepe González #1','Vampirella de Pepe González',1,NULL,'978-8-416-05146-5',NULL,'T. Casey Brennan','José González',NULL,NULL,'Planeta Cómic',NULL,'2014-09-02',NULL,NULL,replace(replace('Contiene Vampirella magazine 12 a 25 y Annual 1972. PVP 35€\r\nRecopilatorio de las historietas de Pepe González a partir de la reedición que está realizando Dynamite en EEUU en &quot;Vampirella Archives&quot;. La portada corresponde a Vampirella Archives Volume 2 (Dynamite).','\r',char(13)),'\n',char(10)),NULL,NULL,264,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775496476148-vlwj6t.jpg','unread',0,NULL,NULL,'2026-04-06 17:27:58','2026-04-06 17:27:58',41,35,NULL,'[{"name":"José González","role":"Dibujo"},{"name":"T. Casey Brennan","role":"Guion"},{"name":"J. R. Cochran","role":"Guion"},{"name":"Bill DuBay","role":"Guion"},{"name":"Steve Englehart","role":"Guion"},{"name":"Archie Goodwin","role":"Guion"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(243,'PTSD','PTSD',NULL,NULL,'978-8-412-48454-0',NULL,'Guillaume Singelin','Guillaume Singelin',NULL,NULL,'Grafito Editorial',NULL,'2023-03-02',NULL,NULL,replace(replace('Hemos vuelto de una guerra que duró demasiado.\r\nYa no estamos en el campo de batalla, pero nos la trajimos con nosotros.\r\nNos acompaña siempre, dentro de nuestra cabeza. Siempre alerta, siempre en tensión.\r\nAhora vivimos en la calle, abandonados. Es difícil confiar cuando siempre estás esperando un ataque, es imposible dormir cuando los recuerdos te persiguen y solo se callan con calmantes.\r\nEstamos a merced de las bandas que imponen su ley y se aprovechan de nuestra debilidad a golpes y a tiros. Cada vez quedamos menos.\r\nPero se han olvidado de algo.\r\nSigo siendo una soldado. Y ahora están en mi punto de mira.','\r',char(13)),'\n',char(10)),NULL,NULL,200,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775499552582-uyibgm.jpg','read',0,5,NULL,'2026-04-06 18:19:13','2026-04-06 18:19:17',NULL,20,'Rústica','[{"name":"Guillaume Singelin","role":"Guion, Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(244,'Silent Jenny','Silent Jenny',NULL,NULL,'978-8-410-28744-0',NULL,'Mathieu Bablet','Mathieu Bablet',NULL,NULL,'Nuevo Nueve',NULL,'2025-11-03',NULL,NULL,'En un futuro lejano el cambio climático no se ha detenido y la desaparición de los insectos ha provocado la no polinización, dejando estériles grandes extensiones de tierra. Se ha puesto en marcha una dinámica de supervivencia, se han formado islas móviles conocidas como &quot;mónadas&quot; y la gente intenta ayudarse mutuamente, cada uno siguiendo sus propios hábitos y costumbres que vamos descubriendo a medida que nos adentramos en el libro. Jenny es una investigadora bastante solitaria que intenta encontrar el camino de vuelta al mundo anterior. Trata de hallar el ADN de las abejas para poder clonarlas y recrear insectos polinizadores. Pero se da cuenta de que eso no es posible. El mundo antiguo ya no existe y lo que hay que hacer es inventar uno nuevo.',NULL,NULL,312,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775499595893-4ei5ea.jpg','unread',0,NULL,NULL,'2026-04-06 18:19:57','2026-04-06 18:19:57',NULL,45,NULL,'[{"name":"Mathieu Bablet","role":"Guion, Dibujo, Tinta, Color"}]');
