INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(246,'El nombre de la rosa #2','El nombre de la rosa',2,NULL,'978-8-426-42571-3',NULL,'Milo Manara','Milo Manara',NULL,NULL,'Lumen',NULL,'2026-02-26',NULL,NULL,'En 1327, el fraile franciscano Guillermo de Baskerville llega, acompañado del novicio Adso de Melk, a una abadía de monjes benedictinos para participar en un importante cónclave, que se verá amenazado por una serie de enigmáticas muertes. A medida que fray Guillermo investigue y se acerque a la peligrosa verdad, su joven aprendiz descubrirá los secretos de un mundo oscuro y lleno de sensualidad. El maestro indiscutible del cómic Milo Manara completa con este segundo volumen la soberbia adaptación gráfica del «thriller histórico más influyente de la historia de la literatura» (',NULL,NULL,72,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775499627697-5m4940.jpg','unread',0,NULL,NULL,'2026-04-06 18:20:28','2026-04-06 18:20:28',42,20.9,'Cartoné 72 pp','[{"name":"Milo Manara","role":"Guion, Dibujo, Tinta, Color"}]');
