INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(248,'Patomas. Disney Limited Edition #1','Patomas. Disney Limited Edition',1,NULL,'978-8-418-81428-0',NULL,'Guido Martina','Giovan Battista Carpi',NULL,NULL,'Panini Comics España',NULL,'2023-06-17',NULL,NULL,replace(replace('Contiene Paperinik il diabolico vendicatore.\r\nPaperinik alla riscossa.\r\nPaperinik torna a colpire.\r\nPaperinik e la giustizia ultrasonica.\r\nPaperinik e il castello delle tre torri.\r\nIl doppio trionfo di Paperinik.\r\nPaperinik e la scuola del Krimen.\r\nIncluye','\r',char(13)),'\n',char(10)),NULL,NULL,416,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775499782259-m76ga1.jpg','unread',0,NULL,NULL,'2026-04-06 18:23:05','2026-04-06 18:23:05',43,45.95,'bolsillo','[{"name":"Guido Martina","role":"Guion"},{"name":"Giovan Battista Carpi","role":"Dibujo"},{"name":"Romano Scarpa","role":"Dibujo"},{"name":"Massimo De Vita","role":"Dibujo"},{"name":"Giorgio Cavazzano","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(249,'Mickey Mouse Mystery Magazine. Disney Limited Edition #1','Mickey Mouse Mystery Magazine. Disney Limited Edition',1,NULL,'978-8-410-49727-6',NULL,'Tito Faraci','Giorgio Cavazzano',NULL,NULL,'Panini Comics España',NULL,'2025-07-24',NULL,NULL,'Por fin en versión íntegra una de las más increíbles e intrigantes sagas protagonizadas por Mickey Mouse! Con guion del genial Tito Faraci y dibujos de algunos de los más grandes artistas disneyanos contemporáneos, las hazañas de Mickey en la turbulenta urbe de Anderville muestran una visión &quot;diferente&quot; de nuestro ratón... pero a la vez fiel al espíritu de sus mejores aventuras realizadas por el mítico Floyd Gottfredson en los años treinta y cuarenta del siglo pasado. Cuando el género negro y el universo Disney se dan la mano... todo puede suceder!',NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775499813659-wcanwb.jpg','unread',0,NULL,NULL,'2026-04-06 18:23:37','2026-04-06 18:23:37',44,48.95,NULL,'[{"name":"Tito Faraci","role":"Guion"},{"name":"Ezio Sisto","role":"Guion"},{"name":"Francesco Artibani","role":"Guion"},{"name":"Giorgio Cavazzano","role":"Dibujo"},{"name":"Alessandro Perina","role":"Dibujo"},{"name":"Giuseppe Zironi","role":"Dibujo"},{"name":"Claudio Sciarrone","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(250,'La Espada de Hielo. Disney Limited Edition','La Espada de Hielo. Disney Limited Edition',NULL,NULL,'978-8-418-81425-9',NULL,'Massimo De Vita','Massimo De Vita',NULL,NULL,'Panini Comics España',NULL,'2023-03-30',NULL,NULL,replace(replace('Contiene una antología de las historietas publicadas en los números 1411 a 1413, 1464, 1465, 1517, 1936, 1937 y 3497 a 3500 de Topolino. \r\n«Existen otras dimensiones fuera de la nuestra. En una de ellas, en la fría y nevada tierra de Ululandia...». Cuatro décadas después de su publicación original, la obra maestra de Massimo De Vita regresa en una magnífica edición. Mickey y Goofy recorren las tierras de Argaar junto con Yor, Boz y muchos otros personajes, en lucha contra el Príncipe de las Nieblas. Este volumen, primera recopilación en castellano de esta mítica saga, contiene la historia original de «La Espada de Hielo», las secuelas que aparecieron poco después de su publicación y la nueva entrega aparecida en 2022.','\r',char(13)),'\n',char(10)),NULL,NULL,440,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775499830213-j8gqsm.jpg','unread',0,NULL,NULL,'2026-04-06 18:23:51','2026-04-06 18:23:51',NULL,49.95,'lujo','[{"name":"Massimo De Vita","role":"Guion, Dibujo"},{"name":"Marco Nucci","role":"Guion"},{"name":"Cristian Canfailla","role":"Dibujo, Tinta"},{"name":"Fabio Celoni","role":"Dibujo, Tinta"},{"name":"Alfons Moliné","role":"Guion"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(251,'La saga de Maese Pato. Disney Limited Edition','La saga de Maese Pato. Disney Limited Edition',NULL,NULL,'978-8-418-81429-7',NULL,'Giovan Battista Carpi','Giovan Battista Carpi',NULL,NULL,'Panini Comics España',NULL,'2023-07-27',NULL,NULL,'Por primera vez en tomo una de las más emblemáticas sagas disneyanas! Realizada por el mítico dúo que nos trajo a Patomas, Guido Martina y Giovan Battista Carpi, La saga de Maese Pato nos lleva a la Italia medieval, donde conoceremos a Maese Pato, un acaudalado mercader (y ancestro lejano del tío Gilito) que vivirá una increíble epopeya a lo largo de siete hilarantes capítulos, con guiños a Dante Alighieri y El conde de Montecristo de Alexandre Dumas. Más de 200 páginas repletas de historia... e histeria!',NULL,NULL,224,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775499895554-8p4bnw.jpg','unread',0,NULL,NULL,'2026-04-06 18:24:56','2026-04-06 18:24:56',NULL,34.95,NULL,'[{"name":"Giovan Battista Carpi","role":"Guion, Dibujo, Tinta"},{"name":"Guido Martina","role":"Guion"}]');
