INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(253,'Marvel Disney #2','Marvel Disney',2,NULL,'978-8-410-51845-2',NULL,'Luca Barbieri','Giada Perissinotto',NULL,NULL,'Panini Comics España',NULL,'2025-03-06',NULL,NULL,replace(replace('Contiene: What If...? Donald Duck Became Wolverine y The Mighty Thor y What If...? Minnie Became Captain Marvel One-Shots\r\n¡El tratamiento What If llega a Disney! Celebramos el 90º aniversario de Donald y el 50º aniversario de Lobezno uniendo a ambos personajes. A continuación, Donald tendrá que demostrar que es digno de alzar el martillo de Thor y, finalmente, Minnie llega más alto, más lejos y más rápido... ¡como la Capitana Marvel!','\r',char(13)),'\n',char(10)),NULL,NULL,72,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775499945030-cj24ve.jpg','read',0,NULL,NULL,'2026-04-06 18:25:45','2026-04-07 07:47:33',45,4.5,'Rústica','[{"name":"Luca Barbieri","role":"Guion"},{"name":"Giada Perissinotto","role":"Dibujo, Tinta"},{"name":"Lucio Ruvidotti","role":"Color"},{"name":"Steve Behling","role":"Guion"},{"name":"Riccardo Secchi","role":"Guion"},{"name":"Lorenzo Pastrovicchio","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(254,'Marvel Disney #3','Marvel Disney',3,NULL,'979-1-370-13193-7',NULL,'Steve Behling','Lorenzo Pastrovicchio',NULL,NULL,'Panini Comics España',NULL,'2025-11-06',NULL,NULL,replace(replace('Contiene: What If...? Mickey and Friends Became the Fantastic Four, Mickey and Friends Became The Avengers, Donald Duck Became Iron Man y What If...? Goofy Became Spider-Man.\r\nTus personajes favoritos de Disney caracterizados como La Primera Familia de Marvel. Mickey con poderes elásticos, Minnie con capacidad para volverse invisible, Goofy enciende su llama, Donald se convierte en roca... con estos increíbles poderes, son Los 4 Fantásticos. Además, Mickey y amigos se convierten en Los Vengadores y Donald se transforma en Iron Man.','\r',char(13)),'\n',char(10)),NULL,NULL,72,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775499947085-89looc.jpg','read',0,NULL,NULL,'2026-04-06 18:25:47','2026-04-07 07:47:33',45,4.5,'Rústica','[{"name":"Steve Behling","role":"Guion"},{"name":"Riccardo Secchi","role":"Guion"},{"name":"Lorenzo Pastrovicchio","role":"Dibujo, Tinta"},{"name":"Lucio Ruvidotti","role":"Color"},{"name":"Luca Barbieri","role":"Guion"},{"name":"Alessandro Pastrovicchio","role":"Dibujo, Tinta"},{"name":"Donald Soffritti","role":"Dibujo, Tinta"},{"name":"Francesco D''Ippolito","role":"Dibujo, Tinta"}]');
