INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(258,'Colección Clásicos de la Literatura Disney #7','Colección Clásicos de la Literatura Disney',7,NULL,'7500827010068-00007',NULL,'Bruno Enna','Fabio Celoni',NULL,NULL,'RBA',NULL,'2025-01-17',NULL,NULL,replace(replace('Incluye los capítulos:\r\n-Mickey y Drácula\r\n-Donald y las aventuras en Transilvania\r\nEn esta historia inspirada en la famosa novela de Bram Stoker, Mickey viaja hasta el castillo del vanidoso conde Drácula y se ve envuelto en situaciones increíbles y, por momentos, inquietantes. Minnie, Goofy y muchos otros personajes tomarán luego el relevo para, entre todos, vencer al enigmático conde gracias a su heroísmo y a una buena dosis de... ¡ajo! En Donald y Las aventuras en Transilvania nuestro protagonista se enfrenta a murciélagos, pasadizos secretos y otros peligros para ayudar a Tío Gilito a descifrar el misterioso secreto del conde Patescu.','\r',char(13)),'\n',char(10)),NULL,NULL,164,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775500103776-c60opp.jpg','unread',0,NULL,NULL,'2026-04-06 18:28:27','2026-04-06 18:28:27',47,NULL,'Rústica','[{"name":"Bruno Enna","role":"Guion"},{"name":"Fabio Celoni","role":"Dibujo"},{"name":"Claudia Salvatori","role":"Guion"},{"name":"Massimo De Vita","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(259,'Colección Clásicos de la Literatura Disney #1','Colección Clásicos de la Literatura Disney',1,NULL,'7500827010037-00001',NULL,'Sisto Nigro','Giampiero Ubezio',NULL,NULL,'RBA',NULL,'2024-11-05',NULL,NULL,replace(replace('Incluye  los capítulos: \r\n-Mickey y los caballeros de la mesa redonda\r\n-El rey Mickey y los caballeros de la mesa redonda\r\n-Donald y la leyenda del rey Arturo\r\n-Donald y los caballeros de los trineos voladores\r\nEn esta adaptación de Disney de una de las leyendas más famosas del mundo, encontrarás una gran cantidad de escenas cómicas y momentos llenos de humor que mantendrán a los lectores entretenidos hasta el final. Aventura, amistad, justicia y valentía se presentan siempre con un toque de ironía. En la segunda historia de este libro centrado en el ciclo artúrico, La leyenda del Rey Arturo, Donald adopta el papel del legendario monarca para retirar la espada de la piedra.','\r',char(13)),'\n',char(10)),NULL,NULL,164,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775500125823-02ba59.jpg','unread',0,NULL,NULL,'2026-04-06 18:28:46','2026-04-06 18:28:46',47,NULL,'rústica','[{"name":"Sisto Nigro","role":"Guion"},{"name":"Giampiero Ubezio","role":"Dibujo"},{"name":"Vick Lockman","role":"Guion"},{"name":"Paul Murry","role":"Dibujo"},{"name":"Sauro Pennacchioli","role":"Guion"},{"name":"Sandro Dossi","role":"Dibujo"},{"name":"Carl Barks","role":"Guion, Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(260,'Colección Clásicos de la Literatura Disney #4','Colección Clásicos de la Literatura Disney',4,NULL,'7500827010068-00004',NULL,'Mario Volta','Giampiero Ubezio',NULL,NULL,'RBA',NULL,'2024-12-17',NULL,NULL,replace(replace('Incluye  los capítulos: \r\n-Los cuentos de Edgar Allan Poe: Mickey y la caída de la casa Usher\r\n-Los cuentos de Edgar Allan Poe: Mickey y el escarabajo de oro\r\n-Los cuentos de Edgar Allan Poe: Mickey y el sobre escondido\r\nA través de las maravillosas historias escritas por su antepasado Edgar Allan Ratón, Mickey entretiene a sus sobrinos durante las largas tardes de lluvia. Misterio, intriga e ingenio se dan la mano en estas divertidas historietas que te mantendrán atento hasta la última página.','\r',char(13)),'\n',char(10)),NULL,NULL,164,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775500133184-cyyk6g.jpg','unread',0,NULL,NULL,'2026-04-06 18:28:54','2026-04-06 18:28:54',47,NULL,'Rústica','[{"name":"Giampiero Ubezio","role":"Dibujo"},{"name":"Mario Volta","role":"Guion"},{"name":"Silvio Camboni","role":"Dibujo"}]');
