INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(263,'Teenage Mutant Ninja Turtles: Negro, blanco y verde','Teenage Mutant Ninja Turtles: Negro, blanco y verde',NULL,NULL,'979-1-387-95318-8',NULL,'Dave Baker','Declan Shalvey',NULL,NULL,'Moztros',NULL,'2025-12-18',NULL,NULL,replace(replace('Contenido: Teenage Mutant Ninja Turtles: Black, White & Green núms. 1–4 USA\r\nDescubre a las Tortugas Ninja como nunca antes las habías visto: ¡en blanco, negro y verde! El presente volumen contiene relatos nuevos y atemporales de Leonardo, Raphael, Donatello y Michelangelo, contando con la participación de referentes del noveno arte que enriquecen esta legendaria franquicia.\r\nCada autor ofrece su personal visión de los personajes, al tiempo que honra la historia y la mitología que los hizo tan queridos. Desde estrellas emergentes de la escena independiente hasta pesos pesados de la industria, esta antología pone el foco en voces tan únicas como diversas.\r\nCon autores como Declan Shalvey, Jock, Riley Rossmo, Lee Garbett, Patrick Gleason y el galardonado en los premios Eisner Javier Rodríguez (Zatanna: Abajo la sala, Absolute Martian Manhunter), quien firma su primera historia como autor completo para el mercado americano.','\r',char(13)),'\n',char(10)),NULL,NULL,160,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775500300350-ccrvt0.jpg','read',0,3,NULL,'2026-04-06 18:31:42','2026-04-06 18:31:46',NULL,19.9,'Rústica','[{"name":"Dave Baker","role":"Guion"},{"name":"Declan Shalvey","role":"Guion, Dibujo"},{"name":"Gigi Dutreix","role":"Guion, Dibujo"},{"name":"Paulina Ganucheau","role":"Guion, Dibujo"},{"name":"Jesse Lonergan","role":"Guion, Dibujo"},{"name":"Lorenzo Hall","role":"Guion"},{"name":"Gavin Smith","role":"Guion, Dibujo"},{"name":"Javier Rodríguez","role":"Guion, Dibujo"},{"name":"Tyler Boss","role":"Guion, Dibujo"},{"name":"Mikey Way","role":"Guion"},{"name":"Nikola Cizmesija","role":"Dibujo"},{"name":"Lee Loughridge","role":"Color"},{"name":"Dom Reardon","role":"Guion, Dibujo"},{"name":"Jock","role":"Guion, Dibujo"},{"name":"Cameron Chittock","role":"Guion"},{"name":"Carlos Giffoni","role":"Guion"},{"name":"Dave Wielgosz","role":"Guion"},{"name":"Alexis Ziritt","role":"Dibujo"},{"name":"Michael Shelfer","role":"Dibujo"},{"name":"Lee Garbett","role":"Guion, Dibujo"},{"name":"Patrick Gleason","role":"Guion, Dibujo"},{"name":"Chris Condon","role":"Guion"},{"name":"Jeremy Holt","role":"Guion"},{"name":"Carson Thorn","role":"Dibujo"},{"name":"Sebastián Piriz","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(267,'Creepy #1','Creepy',1,NULL,'978-8-411-40603-1',NULL,'Al McWilliams','Al Williamson',NULL,NULL,'Planeta Cómic',NULL,'2010-01-01',NULL,NULL,replace(replace('Contiene las historiietas de los #1 a 5 de la colección USA de 1964. La revolución Warren, prólogo de Jon B. Cooke. Portadas. Correo dirigido al Querido Tío Creepy.\r\n¡Prepárate para una espeluznante aventura en los más horripilantes rincones de la historia de los cómics!\r\n¡Recoge tus estacas de madera, tus hachas cubiertas de sangre y todos los esqueletos de las más oscuras profundidades de tu armario, y prepárate para una espeluznante aventura en los más horripilantes rincones de la historia de los cómics!\r\nLa revista Creepy del editor Jim Warren conmocionó el mundo de la narración gráfica a principio de los años 60, cuando artistas tan magníficos como Joe Orlando, Alex Toth, Wallace Wood, Frank Frazetta y muchos otros alcanzaron nuevas cimas artísticas con sus fascinantes versiones de relatos de terror clásicos y modernos.\r\nEditor original: Dark Horse.\r\nDurante los siguientes 20 años, ninguna publicación hizo más que Creepy por llevar a los cómics terroríficas historias de calidad, y esta serie de Los archivos de Creepy resucita aquellos números originales hoy en día imposibles de encontrar.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775516267323-2mpkth.jpg','read',0,NULL,NULL,'2026-04-06 22:57:49','2026-04-07 07:37:29',50,40,NULL,'[{"name":"Al McWilliams","role":""},{"name":"Al Williamson","role":""},{"name":"Alex Toth","role":""},{"name":"Angelo Torres","role":""},{"name":"Archie Goodwin","role":""},{"name":"Arthur Porges","role":""},{"name":"Bill Pearson","role":""},{"name":"Bob Lubbers","role":""},{"name":"Frank Frazetta","role":""},{"name":"George Evans","role":""},{"name":"Gray Morrow","role":""},{"name":"Jack Davis","role":""},{"name":"Joe Orlando","role":""},{"name":"Larry Englehart","role":""},{"name":"Larry Ivie","role":""},{"name":"Maurice Whitman","role":""},{"name":"Otto Binder","role":""},{"name":"Reed Crandall","role":""},{"name":"Russ Jones","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(271,'Creepy #2','Creepy',2,NULL,'978-8-411-40604-8',NULL,'Al McWilliams','Al Williamson',NULL,NULL,'Planeta Cómic',NULL,'2010-05-01',NULL,NULL,replace('La nueva recopilación de la mítica revista de terror.\rHola, mis macabras mascotas. ¿Listos para dar otro paseo por mi cementerio de monstruosas obras maestras? Todo lo que tenéis que hacer es arrastraros al interior de este tórrido tomo. Vamos, no hay nada que temer. . . ¡A MENOS QUE OS LO PERDÁIS!\rEsta histórica edición recopila los números 6 al 10 de la serie original de Creepy, e incluye una inspirada introducción del famoso escritor y editor Roy Thomas.','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775547422640-w7juz6.jpg','read',0,NULL,NULL,'2026-04-07 07:37:03','2026-04-07 07:37:29',50,NULL,'Cartoné 232-296 pp B/N','[{"name":"Al McWilliams","role":""},{"name":"Al Williamson","role":""},{"name":"Alex Toth","role":""},{"name":"Angelo Torres","role":""},{"name":"Archie Goodwin","role":""},{"name":"Arthur Porges","role":""},{"name":"Bill Pearson","role":""},{"name":"Bob Lubbers","role":""},{"name":"Frank Frazetta","role":""},{"name":"George Evans","role":""},{"name":"Gray Morrow","role":""},{"name":"Jack Davis","role":""},{"name":"Joe Orlando","role":""},{"name":"Larry Englehart","role":""},{"name":"Larry Ivie","role":""},{"name":"Maurice Whitman","role":""},{"name":"Otto Binder","role":""},{"name":"Reed Crandall","role":""},{"name":"Russ Jones","role":""}]');
