INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(274,'Teenage Mutant Ninja Turtles #1','Teenage Mutant Ninja Turtles',1,NULL,'978-8-410-46396-7',NULL,'Jason Aaron','Joelle Jones',NULL,NULL,'Moztros',NULL,'2025-09-11',NULL,NULL,replace(replace('Contenido: Teenage Mutant Ninja Turtles: Alpha USA (historia corta Long Way from Home), Teenage Mutant Ninja Turtles núms. 1–6\r\n¡Las Tortugas Ninja regresan en esta nueva colección, perfecta para sumarse a la tortugamanía!\r\nLos cuatro hermanos abandonaron Nueva York para perseguir sus propios intereses. Raphael está en prisión.\r\nMichelangelo está viviendo en Tokio, donde se ha convertido en una estrella de televisión. Leonardo está viajando por el mundo en busca de paz. Donatello está atrapado en un zoológico de mutantes, obligado a pelear contra hombres adinerados que buscan emociones fuertes. ¿Y qué ha sucedido en la Gran Manzana mientras las Tortugas estaban dispersas por el mundo? Pronto lo descubrirán…\r\nRegreso a Nueva York es el primer arco argumental de la nueva serie regular Teenage Mutant Ninja Turtles, que cuenta con un equipo creativo de ensueño: el multipremiado guionista Jason Aaron y una alineación estelar de dibujantes integrada por Joëlle Jones, Rafael Albuquerque, Cliff Chiang, Chris Burnham, Darick Robertson y Juan Ferreyra.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775547471695-sgno51.jpg','read',0,4,NULL,'2026-04-07 07:37:54','2026-04-07 07:47:09',54,19.9,'Rústica','[{"name":"Jason Aaron","role":"Guion"},{"name":"Joelle Jones","role":"Dibujo"},{"name":"Rafael Albuquerque","role":"Dibujo"},{"name":"Cliff Chiang","role":"Dibujo, Color"},{"name":"Chris Burnham","role":"Dibujo"},{"name":"Darick Robertson","role":"Dibujo"},{"name":"Juan Ferreyra","role":"Dibujo, Color"},{"name":"Norm Rapmund","role":"Tinta"},{"name":"Brian Reber","role":"Color"},{"name":"Ronda Pattison","role":"Color"},{"name":"Marcelo Maiolo","role":"Color"},{"name":"Tony Aviña","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(275,'Teenage Mutant Ninja Turtles #2','Teenage Mutant Ninja Turtles',2,NULL,'979-1-387-95335-5',NULL,'Jason Aaron','Juan Ferreyra',NULL,NULL,'Moztros',NULL,'2026-03-12',NULL,NULL,replace(replace('Contenido: Teenage Mutant Ninja Turtle núms. 7-12 USA\r\n¡LA NUEVA ERA DE LOS CÓMICS DE LAS TMNT CONTINÚA EN ESTE SEGUNDO Y EXPLOSIVO\r\nARCO ARGUMENTAL!\r\nDespués de un año separados, el reencuentro familiar no ha ido según lo planeado. Aunque han podido dejar a un lado sus disputas fraternales, no hay tiempo para que los hermanos lo celebren. Perseguidas por una nueva fuerza policial reforzada con miembros del Pie y dirigida por el implacable fiscal Hieronymus Hale, las Tortugas deberán aguantar el peor golpe bajo hasta la fecha: ¡la ciudad de Nueva York ya no es un lugar seguro, y los héroes mutantes se verán obligados a tomar medidas drásticas!\r\nEl dibujante Juan Ferreyra se une al multipremiado guionista Jason Aaron para dar forma a un arco argumental explosivo, clave en el desarrollo de esta nueva y exitosa etapa de las Tortugas Ninja.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775547478801-43akgh.jpg','unread',0,NULL,NULL,'2026-04-07 07:37:59','2026-04-07 07:37:59',54,NULL,'Rústica','[{"name":"Jason Aaron","role":"Guion"},{"name":"Juan Ferreyra","role":"Dibujo, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(276,'Biblioteca Disney #7','Biblioteca Disney',7,NULL,'978-8-410-49702-3',NULL,'Corrado Mastantuono','Corrado Mastantuono',NULL,NULL,'Panini Comics España',NULL,'2025-02-27',NULL,NULL,'¡Una apasionante crónica en seis episodios de la juventud del Tío Gilito, escrita e ilustrada por el talentoso Corrado Mastantuono! Ambientada en la época de la fiebre del oro, nos muestra cómo el futuro',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775547501307-9yg20z.jpg','unread',0,NULL,NULL,'2026-04-07 07:38:23','2026-04-07 07:38:23',55,18,'Rústica','[{"name":"Corrado Mastantuono","role":"Guion, Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(277,'Biblioteca Disney #9','Biblioteca Disney',9,NULL,'978-8-410-49724-5',NULL,'Fabio Celoni','Fabio Celoni',NULL,NULL,'Panini Comics España',NULL,'2025-06-25',NULL,NULL,'Una historia profunda y emotiva, guionizada y dibujada por Fabio Celoni, que relata la empresa más ardua de nuestro magnate: empezar a partir de cero tras perder todas sus riquezas, desafiar al Fantasma del Destino y enfrentarse a mundos y escenarios diferentes, en un viaje tan aventurero como introspectivo. En las páginas de contenido extra desvelaremos más secretos sobre cómo se hizo este cómic, con valiosos bocetos y esbozos inéditos reunidos en esta edición especial para coleccionistas.',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775547510181-d9x4wq.jpg','unread',0,NULL,NULL,'2026-04-07 07:38:30','2026-04-07 07:38:30',55,NULL,'Rústica','[{"name":"Fabio Celoni","role":"Guion, Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(278,'Mickey Mouse: Tiras de prensa #1','Mickey Mouse: Tiras de prensa',1,NULL,'978-8-491-73831-2',NULL,'Floyd Gottfredson','Floyd Gottfredson',NULL,NULL,'Planeta Cómic',NULL,'2022-11-09',NULL,NULL,replace(replace('El público actual conoce a Mickey Mouse como un personaje risueño y bonachón. Pero durante su época dorada en los años treinta, Mickey se hizo famoso por sus heroicidades épicas. Era un aventurero atrevido y beligerante que se enfrentaba a monstruos, secuestradores y espías. Y las mayores hazañas de Mickey se llevaban a cabo en su tira cómica diaria, creada por uno de los mayores dibujantes de cómic de la historia: Floyd Gottfredson.\r\nDurante 25 años, el Mickey Mouse de Gottfredson fue una influyente tira cómica que abrió camino para muchos otros cómics de aventuras. Pero por muy célebre que fuera la obra a la que Gottfredson le dedicó toda su vida, nunca ha sido recopilada en su totalidad... ¡hasta ahora!\r\nAdéntrate en este libro y podrás ver a Mickey precipitándose hacia una mina de oro con Pete Pata de Palo, viviendo como un fugitivo tras ser acusado de robar un banco, e incluso enfrentándose a un campeón de boxeo de los pesos pesados. Nunca hubieras pensado que llegarías a ver a un ratón viviendo aventuras tan trepidantes. ¡Pero aquí lo tienes!\r\nMickey Mouse es uno de los mayores iconos del mundo. Pero… ¿conoces la personalidad salvaje e inolvidable que hay detrás del icono? Empieza a leer... y no te sorprendas si un día de estos acabas poniéndote unas orejas de ratón.\r\nEste libro recoge los grandes momentos del Mickey de la época con una calidad inigualable, con viñetas extraídas directamente de las hojas de pruebas de Disney y de selectas colecciones privadas. También podrás explorar más de cincuenta páginas de extras, desde exclusivas ilustraciones inéditas hasta tributos realizados por Warren Spector (Disney Epic Mickey) y Floyd Norman (ganador del premio Disney Legends).','\r',char(13)),'\n',char(10)),NULL,NULL,298,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775564511313-3qbsmv.jpg','unread',0,NULL,NULL,'2026-04-07 12:21:53','2026-04-07 12:21:53',56,50,NULL,'[{"name":"Floyd Gottfredson","role":"Guion, Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(279,'Lucky Luke de Goscinny y Morris. Integral #1','Lucky Luke de Goscinny y Morris. Integral',1,NULL,'978-8-467-97190-3',NULL,'Rene Goscinny','Morris',NULL,NULL,'Norma Editorial',NULL,'2025-01-17',NULL,NULL,replace(replace('Contiene: Raíles en la Pradera (Lucky Luke 9 - Des Rails sur la prairie), Lucky Luke contra Joss Jamon (Lucky Luke 11 -Lucky Luke contre Joss Jamon) , Los Primos Dalton (Lucky Luke 12 - Les Cousins Dalton), El Juez (Lucky Luke 13 -Le Juge) y La Carrera por Oklahoma (Lucky Luke 14 -Ruée sur L’Oklahoma).\r\nLA COLECCIÓN INTEGRAL DE UNA DE LAS CUMBRES DEL 9º ARTE\r\nCreado por el genial dibujante Morris en 1946, Lucky Luke fue durante años una parodia del cowboy justiciero y vagabundo que aparecía en centenares de westerns cinematográficos. Sin embargo, la llegada del portentoso guionista René Goscinny imprimió un giro a la serie, insuflando en ella grandes dosis de sutileza e ironía, y elevando al protagonista (y a sus enemigos, los Dalton) al Olimpo de los cómics. Esta edición recupera la obra maestra de Morris y Goscinny en tomos de cuidada factura acompañados por un extenso dosier con textos e imágenes inéditos. Para empezar, cinco aventuras que figuran entre lo mejor de la historieta mundial de todos los tiempos.','\r',char(13)),'\n',char(10)),NULL,NULL,256,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775564544765-3jthr5.jpg','unread',0,NULL,NULL,'2026-04-07 12:22:27','2026-04-07 12:22:27',57,45,'lujo','[{"name":"Rene Goscinny","role":"Guion"},{"name":"Morris","role":"Dibujo, Tinta, Color"}]');
