INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(317,'Los 200 primeros casos de Mortadelo y Filemón. 1958-1961','Los 200 primeros casos de Mortadelo y Filemón. 1958-1961',NULL,NULL,'978-8-402-43055-7',NULL,'Francisco Ibáñez','Francisco Ibáñez',NULL,NULL,'Bruguera - Penguin Random House',NULL,'2025-05-14',NULL,NULL,replace(replace('Descubre los inicios de Mortadelo y Filemón, los agentes más famosos de Francisco Ibáñez.\r\nAntes de trabajar en la TIA, Mortadelo y Filemón regentaban una pequeña —y desastrosa— agencia de detectives: Mortadelo y Filemón, agencia de información.\r\nEste libro recupera los 200 primeros casos de los detectives más queridos del cómic nacional en un volumen que ordena, de manera cronológica, las historias publicadas entre el 20 de enero de 1958 y el 2 de octubre de 1961.\r\nLas historietas se reproducen tal y como aparecieron en','\r',char(13)),'\n',char(10)),NULL,NULL,240,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565328178-sgp0gn.jpg','unread',0,NULL,NULL,'2026-04-07 12:35:29','2026-04-07 12:35:29',NULL,29.95,NULL,'[{"name":"Francisco Ibáñez","role":"Guion, Dibujo, Tinta"},{"name":"Jordi Canyissa","role":""},{"name":"Antoni Guiral","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(318,'13, Rue del Percebe. Edición integral','13, Rue del Percebe. Edición integral',NULL,NULL,'978-8-402-42270-5',NULL,'Francisco Ibáñez','Rubén Larrea',NULL,NULL,'Ediciones B',NULL,'2018-03-08',NULL,NULL,replace(replace('Después del gran éxito de la publicación de la integral de 13, Rue del Percebe (más de 30.000 ejemplares vendidos) llega a librerías esta nueva versión. \r\nEl álbum contiene las 342 páginas que realizó Francisco Ibáñez semanalmente de su popular y mítica serie, a partir de su primera aparición en 1961 hasta 1968 en la revista TÍO VIVO de la editorial Bruguera, dando vida a unos personajes imperecederos como son Manolo, el inquilino de la azotea, que no e otro que el gran Manuel Vázquez, Don Hurón, el tendero de los bajos del edificio, o la portera, tan carismática de la serie. \r\n«Hoy día el colmado sería una gran superficie, y la portería no existiría, sustituida por una oficina de banco; en la alcantarilla y el ascensor habría okupas; en la buhardilla estaría aporreando gente del Ayuntamiento reclamando el cobro de impuestos; los niños, en vez de cuatro, serían una decena porque todos vivirían con los abuelos y el caco, uno de esos banqueros de las preferentes... Pero, en el fondo, sería lo mismo y yo tendría los mismos problemas para llenar esos agujeritos.» Francisco Ibáñez','\r',char(13)),'\n',char(10)),NULL,NULL,352,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565346700-ziazho.jpg','read',0,NULL,NULL,'2026-04-07 12:35:47','2026-04-07 17:39:08',NULL,20.9,NULL,'[{"name":"Francisco Ibáñez","role":"Guion"},{"name":"Rubén Larrea","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(320,'Mighty Morphin Power Rangers #1','Mighty Morphin Power Rangers',1,NULL,'978-8-418-95501-3',NULL,'Kyle Higgins','Hendry Prasetya',NULL,NULL,'Moztros',NULL,'2022-02-17',NULL,NULL,replace(replace('Contiene: Mighty Morphin Power Rangers (2016) #0 - 8\r\n¡Es tiempo de metamorfosear para todos los fans de la exitosa serie! Tommy Oliver era solo el chico nuevo de Angel Grove cuando Rita Repulsa lo secuestró y lo convirtió en el malvado Green Ranger. Ahora, libre de su control mental, Tommy deberá luchar por encontrar el equilibrio entre su vida escolar, hacer nuevos amigos y los peligros de ser un héroe. Además, cuando Rita dé inicio a su plan para dominar el mundo, los Power Rangers deberán combatir la amenaza más poderosa a la que jamás se hayan enfrentado. Sin poderes y sin Zordon, dependerá de ellos salvar al mundo y salvarse a si mismos.','\r',char(13)),'\n',char(10)),NULL,NULL,228,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565429715-28q6dm.jpg','read',0,NULL,NULL,'2026-04-07 12:37:10','2026-04-07 17:39:08',61,15,'Cartoné 228 pp','[{"name":"Kyle Higgins","role":"Guion"},{"name":"Steve Orlando","role":"Guion"},{"name":"Mairghread Scott","role":"Guion"},{"name":"Hendry Prasetya","role":"Dibujo, Tinta"},{"name":"Corin Howell","role":"Dibujo, Tinta"},{"name":"Daniel Bayliss","role":"Dibujo, Tinta, Color"},{"name":"Matt Herms","role":"Color"},{"name":"Jeremy Lawson","role":"Color"},{"name":"Thony Silas","role":"Dibujo, Tinta"},{"name":"Bryan Valenza","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(321,'Mighty Morphin Power Rangers #2','Mighty Morphin Power Rangers',2,NULL,'9788418955013-00002',NULL,'Kyle Higgins','Hendry Prasetya',NULL,NULL,'Moztros',NULL,'2022-03-17',NULL,NULL,replace(replace('Contiene: Mighty Morphin Power Rangers #9 - 16\r\n¡Tras más de dos décadas, un nuevo Power Ranger hace su debut en una épica historia que pondrá de cabeza a todo el Universo Ranger! Y además, cuando Tommy y Billy quedan atrapados en el futuro distópico, tendrán que unirse a la resistencia para luchar contra el malvado Lord Drakkon si pretenden volver a su hogar, pero con Jason, Kimberly, Trini y Zack luchando contra Rita Repulsa por el control del centro del comando... ¿Siquiera habrá un mundo al cual volver?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565444190-7rlgz5.jpg','read',0,NULL,NULL,'2026-04-07 12:37:25','2026-04-07 17:39:08',61,NULL,'Cartoné 228 pp','[{"name":"Kyle Higgins","role":"Guion"},{"name":"Hendry Prasetya","role":"Dibujo"},{"name":"Thony Silas","role":"Dibujo"},{"name":"Matt Herms","role":"Color"},{"name":"Steve Orlando","role":"Guion"},{"name":"Corin Howell","role":"Dibujo"},{"name":"Jeremy Lawson","role":"Dibujo"},{"name":"Bryan Valenza","role":"Dibujo"},{"name":"Jonathan Lam","role":"Dibujo"},{"name":"Ryan Ferrier","role":"Guion"},{"name":"Bachan","role":"Dibujo"},{"name":"Daniel Bayliss","role":"Dibujo, Color"},{"name":"Triona Farrell","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(322,'Mighty Morphin Power Rangers #3','Mighty Morphin Power Rangers',3,NULL,'978-8-418-95534-1',NULL,'Kyle Higgins','Hendry Prasetya',NULL,NULL,'Moztros',NULL,'2022-08-25',NULL,NULL,replace(replace('Contiene: Mighty Morphin Power Rangers #17 - 24\r\nREGRESA EL MAYOR ENEMIGO DE LOS POWER RANGERS! El equipo vuelve a reunirse, pero ya nada es igual para los Rangers. Sin la guía de Zordon ni los constantes ataques de Rita, los Power Rangers deberán descubrir qué significa ser un héroe en este nuevo mundo. Es tiempo de nuevos aliados, nuevos villanos e historias nunca antes contadas. Aunque no tendrán tiempo para asimilar todo esto cuando una oleada de monstruos invada el planeta! El mayor desafío de los mejores héroes de todos llega de la mano de Kyle Higgins, Hendry Prasetya y Jonas Scharf.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565447166-2o09xe.jpg','read',0,NULL,NULL,'2026-04-07 12:37:27','2026-04-07 17:39:08',61,NULL,'Cartoné 228 pp','[{"name":"Kyle Higgins","role":"Guion"},{"name":"Hendry Prasetya","role":"Dibujo"},{"name":"Daniele Di Nicuolo","role":"Dibujo"},{"name":"Matt Herms","role":"Color"},{"name":"Joana Lafuente","role":"Color"},{"name":"Walter Baiamonte","role":"Color"},{"name":"Jonas Scharf","role":"Dibujo, Color"},{"name":"Ryan Ferrier","role":"Guion"},{"name":"Bachan","role":"Dibujo"},{"name":"Daniel Bayliss","role":"Dibujo"},{"name":"Jagdish Kumar","role":"Tinta"},{"name":"Triona Farrell","role":"Color"},{"name":"Sigi Ironmonger","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(323,'Mighty Morphin Power Rangers #4','Mighty Morphin Power Rangers',4,NULL,'9788418955013-00004',NULL,'Kyle Higgins','Daniele Di Nicuolo',NULL,NULL,'Moztros',NULL,'2023-01-26',NULL,NULL,replace(replace('Contiene: Mighty Morphin Power Rangers #25-30, Mighty Morphin Power Rangers FCBD Special y Mighty Morphin Power Rangers Shattered Grid #1\r\n¡LLEGA EL EVENTO MÁS GRANDE EN LA HISTORIA DE LOS CÓMICS DE LOS POWER RANGERS!\r\nLord Drakkon, una retorcida versión alternativa del Green Ranger Tommy Oliver, y su ejército recién reformado están cruzando dimensiones para ejecutar un ataque total que amenaza la existencia misma de cada Power Ranger que respire en cada mundo habitable. Es tiempo de que los Rangers de la generación Mighty Morphin unan fuerzas con algunos de los equipos de Power Rangers más populares de la historia de la franquicia para enfrentarse a lo que parece ser la batalla final… ¡una que sin dudas traerá muerte y destrucción!\r\nKyle Higgins junto a los artistas Daniele Di Nicuolo y Diego Galindo nos traen la epopeya más extraordinaria de los Power Rangers que definió para siempre al universo Ranger de los cómics.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565450287-akau8e.jpg','read',0,NULL,NULL,'2026-04-07 12:37:30','2026-04-07 17:39:08',61,NULL,'Cartoné 228 pp','[{"name":"Kyle Higgins","role":"Guion"},{"name":"Ryan Parrott","role":"Guion"},{"name":"Daniele Di Nicuolo","role":"Dibujo"},{"name":"Diego Galindo","role":"Dibujo"},{"name":"Simona DiGianfelice","role":"Dibujo"},{"name":"Walter Baiamonte","role":"Color"},{"name":"Francesco Segala","role":"Color"},{"name":"Marcelo Costa","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(324,'Mighty Morphin Power Rangers #5','Mighty Morphin Power Rangers',5,NULL,'9788418955013-00005',NULL,'Marguerite Bennett','Simone Di Meo',NULL,NULL,'Moztros',NULL,'2023-04-20',NULL,NULL,replace(replace('Contiene Mighty Morphin Power Rangers #31-39\r\n¡UN NUEVO EQUIPO DE POWER RANGERS DEBERÁ EMERGER PARA SALVAR EL UNIVERSO!\r\nTras los acontecimientos y la sorprendente conclusión de Red Quebrada, un equipo completamente nuevo de Power Rangers deberá reunirse a través del tiempo y el espacio para luchar contra un enemigo dispuesto a propagar el mal por toda la galaxia. Mientras luchan por demostrarse a sí mismos y a los demás que tienen lo necesario para sobrevivir en un nuevo entorno peligroso, este nuevo grupo de Power Rangers tendrá la difícil tarea de vencer a este nuevo villano desconocido y aterrador.\r\n¡Es tiempo de metamorfosearse con Marguerite Bennett (Batwoman, X-Men) y Simone di Meo (El Viejo Logan), junto con Francesco Mortarino y French Carlomagno, mientras los Power Rangers descubren lo que significa ser un equipo sin poderes!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565452819-x936w9.jpg','read',0,NULL,NULL,'2026-04-07 12:37:33','2026-04-07 17:39:08',61,NULL,'Cartoné 228 pp','[{"name":"Marguerite Bennett","role":"Guion"},{"name":"Simone Di Meo","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(325,'Mighty Morphin Power Rangers #6','Mighty Morphin Power Rangers',6,NULL,'9788418955013-00006',NULL,'Ryan Parrott','Daniele Di Nicuolo',NULL,NULL,'Moztros',NULL,'2023-07-27',NULL,NULL,replace(replace('Contiene Mighty Morphin Power Rangers #40-45 y Go Go Power Rangers #21-26\r\nDESPUÉS DE LOS SUCESOS DE RED QUEBRADA...\r\n¡LLEGA UN MAL NECESARIO!\r\nSin tiempo para reponerse de lo acontecido durante Red Quebrada, los Mighty Morphin Power Rangers deberán lidiar con las consecuencias de la guerra con Lord Drakkon que pesan sobre sus hombros.\r\nTommy deberá demostrar y demostrarse a sí mismo que es digno del manto del White Ranger a medida que va descubriendo el verdadero origen de sus poderes. Mientras tanto, Jason, Trini y Zack tendrán que asumir nuevos roles en los Omega Rangers y elegir entre sus amigos y su nueva misión como Rangers. Pero como si esto fuera poco, los Mighty Morphin Power Rangers tendrán que reponerse y volver a luchar. Angel Grove se enfrenta a la mayor amenaza que ha conocido jamás: el temido Lord Zedd!\r\nLos guionistas Ryan Parrott (Rogue Sun) y Sina Grace (Iceman) se unen a los artistas Daniele di Nicuolo (Siete Secretos), Francesco Mortarino (Ms. Marvel), Daniel Bayliss (Firefly), y Eduardo Francisco (Aventuras de Superman) para presentarnos la primera parte de un nuevo evento en la vida de los Power Rangers: Un Mal Necesario.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565456657-7cx6jp.jpg','read',0,NULL,NULL,'2026-04-07 12:37:37','2026-04-07 17:39:08',61,NULL,'Cartoné 228 pp','[{"name":"Ryan Parrott","role":"Guion"},{"name":"Sina Grace","role":"Guion"},{"name":"Daniele Di Nicuolo","role":"Dibujo"},{"name":"Francesco Mortarino","role":"Dibujo"},{"name":"Daniel Bayliss","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(326,'Mighty Morphin Power Rangers #7','Mighty Morphin Power Rangers',7,NULL,'9788418955013-00007',NULL,'Kyle Higgins','Hendry Prasetya',NULL,NULL,'Moztros',NULL,'2023-11-23',NULL,NULL,replace(replace('Contiene Mighty Morphin Power Rangers #51-55 y Power Rangers: Drakkon New Dawn #1-3\r\nLos Mighty Morphin Power Rangers y los Omega Rangers pensaban que habían dejado atrás a su mayor amenaza, pero ¡Lord Drakkon ha vuelto para acabar con los Rangers de una vez por todas! La versión malvada del heroico Tommy Oliver ha regresado con un nuevo propósito, nuevos secretos y una nueva misión del más inesperado de los aliados.\r\n¿Conseguirán los Rangers unirse una vez más para derrotar el poder de Lord Zedd y sus nuevos Dark Rangers? ¿O los destruirá por completo la verdad acerca de Lord Drakkon antes de la batalla? Además, Ranger Slayer, la versión alternativa de Kimberly Hart, ha regresado a su dimensión natal para reconstruirla tras el reinado de Lord Drakkon. Pero, para salvar a sus seres queridos, su única opción será convertirse en lo que más odia: la nueva gobernante de su mundo, sentada en el trono de Drakkon.\r\nLos guionistas Ryan Parrott y Anthony Burch, junto a los artistas Moisés Hidalgo y Simone Ragazzoni, presenta la conclusión épica de la primera etapa de la colección de los Power Rangers. ¡Prepárate para concluir una era y comenzar otra como ninguna que hayas leído hasta la fecha!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565458997-pbuxob.jpg','read',0,NULL,NULL,'2026-04-07 12:37:40','2026-04-07 17:39:08',61,NULL,'Cartoné 228 pp','[{"name":"Kyle Higgins","role":"Guion"},{"name":"Hendry Prasetya","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(328,'Ultimate Marvel (2012-2016) #1','Ultimate Marvel (2012-2016)',1,NULL,'9770005456003-00001',NULL,'Jonathan Hickman','Esad Ribic',NULL,NULL,'Panini Comics España',NULL,'2012-05-01',NULL,NULL,replace(replace('Contiene Ultimate Comics Ultimates 1 y 2, Ultimate Comics All-New Spider-Man 1 y Ultimate Comics X-Men 1 USA \r\n¡Todo el Universo Ultimate en la palma de tu mano! Arranca una nueva colección mediante la que podrás seguir todas las series abiertas dentro de la línea Ultimate, a un precio irrepetible. Una nueva era comienza para nuestros héroes, que tratan de encontrar su lugar en el mundo. Los Ultimates afrontan una amenaza que ni siquiera ellos pueden detener; Miles Morales, el nuevo Spiderman, se presenta en sociedad; y de las cenizas de La Patrulla-X nace un nuevo sueño. ¡Querrás estar allí!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565682619-3augir.jpg','read',0,NULL,NULL,'2026-04-07 12:41:25','2026-04-07 17:39:08',63,NULL,'rustica','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"Esad Ribic","role":"Dibujo"},{"name":"Dean White","role":"Color"},{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Sara Pichelli","role":"Dibujo"},{"name":"Justin Ponsor","role":"Color"},{"name":"Nick Spencer","role":"Guion"},{"name":"Paco Medina","role":"Dibujo"},{"name":"Juan Vlasco","role":"Tinta"},{"name":"Marte Gracia","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(329,'Ultimate Marvel (2012-2016) #2','Ultimate Marvel (2012-2016)',2,NULL,'9770005456003-00002',NULL,'Jonathan Hickman','Esad Ribic',NULL,NULL,'Panini Comics España',NULL,'2012-06-01',NULL,NULL,replace(replace('Contiene Ultimate Comics Ultimates 3, Ultimate Comics Spider-Man 2 y 3 y Ultimate Comics X-Men 2 y 3 USA \r\n¡El segundo número de la única colección que necesitas seguir para tener todo un universo en tus manos! En Ultimates, los Hijos del mañana han transformado a los dioses en mortales: la única esperanza de todo un panteón reside en los Ultimates. ¿Podrán salvar Asgard? En Spiderman, Miles Morales tiene una importante decisión que tomar: ¿Seguirá los pasos de Peter Parker o emprenderá su propio camino? Y en La Patrulla-X, el gobierno ha señalado a los mutantes como terroristas. ¿Seguirán dispuestos a defender a la humanidad?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565694115-tiar3e.jpg','read',0,NULL,NULL,'2026-04-07 12:41:35','2026-04-07 17:39:08',63,NULL,'rustica','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"Esad Ribic","role":"Dibujo, Tinta"},{"name":"Dean White","role":"Color"},{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Sara Pichelli","role":"Dibujo, Tinta"},{"name":"Justin Ponsor","role":"Color"},{"name":"Nick Spencer","role":"Guion"},{"name":"Paco Medina","role":"Dibujo"},{"name":"Juan Vlasco","role":"Tinta"},{"name":"Marte Gracia","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(330,'Ultimate Marvel (2012-2016) #3','Ultimate Marvel (2012-2016)',3,NULL,'9770005456003-00003',NULL,'Jonathan Hickman','Esad Ribic',NULL,NULL,'Panini Comics España',NULL,'2012-07-01',NULL,NULL,replace(replace('Contiene Ultimate Comics Ultimates 4, Ultimate Comics All-New Spider-Man 4, Ultimate Comics X-Men 4 y 5 USA \r\n¡El cómic que reúne las aventuras de Ultimates, el nuevo Spiderman y la renovada Patrulla-X! Los Ultimates han vuelto oficialmente, pero... ¿podrán parar una amenaza más poderosa que los mismos dioses? Mientras tanto, Miles Morales aprende por las malas que ser un superhéroe no es tan fácil como parece. ¿Qué secretos esconden sus nuevos poderes? Y por último, La Patrulla-X asiste al regreso de Stryker, en el peor de los días posibles. ¿Acaso un traidor se encuentra entre ellos?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565696516-cazrxb.jpg','read',0,NULL,NULL,'2026-04-07 12:41:37','2026-04-07 17:39:08',63,NULL,'rustica','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"Esad Ribic","role":"Dibujo, Tinta"},{"name":"Dean White","role":"Color"},{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Sara Pichelli","role":"Dibujo, Tinta"},{"name":"Justin Ponsor","role":"Color"},{"name":"Nick Spencer","role":"Guion"},{"name":"Paco Medina","role":"Dibujo"},{"name":"Juan Vlasco","role":"Tinta"},{"name":"Marte Gracia","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(331,'Ultimate Marvel (2012-2016) #4','Ultimate Marvel (2012-2016)',4,NULL,'9770005456003-00004',NULL,'Brian Michael Bendis','Esad Ribic',NULL,NULL,'Panini Comics España',NULL,'2012-08-01',NULL,NULL,replace(replace('Contiene Ultimate Comics Ultimates 5, Ultimate Comics All-New Spider-Man 5 y 6 y Ultimate Comics X-Men 6 USA \r\nEl cómic que te permite tener todo el Universo Ultimate en tus manos. En Ultimates, los Niños del Mañana se han hecho con el control: todo está perdido para Thor y los Ultimates. En Spiderman, Miles descubre el legado que le ha dejado Peter Parker al tiempo que llega el nuevo Escorpión. Y en X-Men, la nueva Patrulla-X lucha contra el mortífero Stryker.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565698719-1l1e2y.jpg','read',0,NULL,NULL,'2026-04-07 12:41:39','2026-04-07 17:39:08',63,NULL,'rustica','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Esad Ribic","role":"Dibujo, Tinta"},{"name":"Jonathan Hickman","role":"Guion"},{"name":"Paco Medina","role":"Dibujo, Tinta"},{"name":"Nick Spencer","role":"Guion"},{"name":"Sara Pichelli","role":"Dibujo"},{"name":"Chris Samnee","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(332,'Ultimate Marvel (2012-2016) #5','Ultimate Marvel (2012-2016)',5,NULL,'9770005456003-00005',NULL,'Brian Michael Bendis','Esad Ribic',NULL,NULL,'Panini Comics España',NULL,'2012-09-01',NULL,NULL,replace(replace('Contiene Ultimate Comics Ultimates 6 y 7, Ultimate Comics All-New Spider-Man 7 y Ultimate Comics X-Men 7 USA \r\n¡La única colección que necesitas para tener todo el Universo Ultimate en la palma de tu mano! En Ultimates, tiene lugar el triunfal regreso del Halcón, mientras los Ultimates cambian las reglas para combatir a Reed Richards. En Spiderman, el mundo descubre la existencia del nuevo trepamuros al tiempo que este lucha contra El Escorpión, y en X-Men, tiene lugar el explosivo regreso de La Bruja Escarlata. ¿Qué opinará su hermano al respecto?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565701008-0hr4b9.jpg','read',0,NULL,NULL,'2026-04-07 12:41:42','2026-04-07 17:39:08',63,NULL,'rustica','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Esad Ribic","role":"Dibujo, Tinta"},{"name":"Jonathan Hickman","role":"Guion"},{"name":"Paco Medina","role":"Dibujo, Tinta"},{"name":"Brandon Peterson","role":"Dibujo"},{"name":"John Rauch","role":"Color"},{"name":"Edgar Delgado","role":"Color"},{"name":"Dean White","role":"Color"},{"name":"Chris Samnee","role":"Dibujo"},{"name":"Justin Ponsor","role":"Color"},{"name":"Nick Spencer","role":"Guion"},{"name":"Carlo Barberi","role":"Dibujo"},{"name":"Walter Wong","role":"Tinta"},{"name":"Marte Gracia","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(333,'Ultimate Marvel (2012-2016) #14','Ultimate Marvel (2012-2016)',14,NULL,'9770005456003-00014',NULL,'Brian Michael Bendis','Esad Ribic',NULL,NULL,'Panini Comics España',NULL,'2013-06-01',NULL,NULL,replace(replace('Contiene Ultimate Comics Ultimates 18, Ultimate Comics All-New Spider-Man 17 y Ultimate Comics. X-Men 18.1 y 19 USA \r\n¡La esperada conclusión de &quot;Unidos, resistimos&quot;! Mientras tiene lugar el ataque final de Hydra contra Estados Unidos, Thor debe decidir entre la Tierra y Asgard y el Capitán América afrontar su última tentación. A su vez, con la nación en guerra, el joven Spiderman responde a la llamada del deber superheroico y descubre su conexión secreta con Spiderwoman. Y por último, comienza una nueva dirección para los mutantes definitivos. Kitty trata de liderar a los suyos, pero alguien tiene otros planes...','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565706770-amfp6l.jpg','read',0,NULL,NULL,'2026-04-07 12:41:47','2026-04-07 17:38:50',63,NULL,'rustica','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Esad Ribic","role":"Dibujo, Tinta"},{"name":"Jonathan Hickman","role":"Guion"},{"name":"Paco Medina","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(334,'Ultimate Marvel (2012-2016) #6','Ultimate Marvel (2012-2016)',6,NULL,'9770005456003-00006',NULL,'Brian Michael Bendis','Esad Ribic',NULL,NULL,'Panini Comics España',NULL,'2012-10-01',NULL,NULL,replace(replace('Contiene Ultimate Comics Ultimates 8, Ultimate Comics All-New Spider-Man 8 y Ultimate Comics X-Men 8 y 9 USA \r\n¡Todo el Universo Ultimate en la palma de tu mano! En Ultimates, asiste al regreso de Hulk y a una decisión que puede cambiar el mundo para siempre. En Spiderman, la llegada de El Escorpión se hace sentir en todo Nueva York, a la vez que tío Aaron tiene planes para los poderes de Miles. Y en X-Men, los mutantes han alcanzado su única esperanza de supervivencia, mientras sale a la luz el campo de concentración que ha creado el gobierno para exterminar al Homo superior.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565709517-77bl8q.jpg','read',0,NULL,NULL,'2026-04-07 12:41:50','2026-04-07 17:38:50',63,NULL,'rustica','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Esad Ribic","role":"Dibujo, Tinta"},{"name":"Jonathan Hickman","role":"Guion"},{"name":"Paco Medina","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(335,'Ultimate Marvel (2012-2016) #7','Ultimate Marvel (2012-2016)',7,NULL,'9770005456003-00007',NULL,'Brian Michael Bendis','Esad Ribic',NULL,NULL,'Panini Comics España',NULL,'2012-11-01',NULL,NULL,replace(replace('Contiene Ultimate Comics Ultimates 9 y 10, Ultimate Comics All-New Spider-Man 9 y Ultimate Comics X-Men 10 USA \r\n¡Todo un universo en la palma de tu mano! En Ultimates, SHIELD ha caído, varias naciones han mordido el polvo y Estados Unidos podría ser la siguiente. ¿Cuál será el papel de los Ultimates y Nick Furia? En Spiderman, la policía sitúa a Miles Morales en su punto de mira mientras El Merodeador se enfrenta con El Escorpión, y en X-Men, Tormenta lleva a cabo una decisión desesperada mientras continúa la batalla en el campo de concentración mutante.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565711266-wu9pjz.jpg','read',0,NULL,NULL,'2026-04-07 12:41:52','2026-04-07 17:38:50',63,NULL,'rustica','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Esad Ribic","role":""},{"name":"Jonathan Hickman","role":""},{"name":"Paco Medina","role":""},{"name":"Sam Humphries","role":""},{"name":"Nick Spencer","role":""},{"name":"David Marquez","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(336,'Ultimate Marvel (2012-2016) #8','Ultimate Marvel (2012-2016)',8,NULL,'9770005456003-00008',NULL,'Brian Michael Bendis','Esad Ribic',NULL,NULL,'Panini Comics España',NULL,'2012-12-01',NULL,NULL,replace(replace('Contiene Ultimate Comics Ultimates 11, Ultimate Comics All-New Spider-Man 10 y 11 y Ultimate Comics X-Men 11 USA \r\n¡El Universo Ultimate en la palma de tu mano! En Ultimates, llega un nuevo equipo creativo: el guionista Sam Humphries y el dibujante Luke Ross se unen a Jonathan Hickman en el comienzo de una nueva era para Estados Unidos. En Spiderman, el nuevo Hombre Araña ha de enfrentarse al Merodeador... ¡Su propio tío! Pero, ¿es de verdad un mal tipo? Y en X-Men... ¡El renacimiento de Stryker!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565714903-8vaqnz.jpg','read',0,NULL,NULL,'2026-04-07 12:41:55','2026-04-07 17:38:50',63,NULL,'rustica','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Esad Ribic","role":"Dibujo, Tinta"},{"name":"Jonathan Hickman","role":"Guion"},{"name":"Paco Medina","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(337,'Ultimate Marvel (2012-2016) #9','Ultimate Marvel (2012-2016)',9,NULL,'9770005456003-00009',NULL,'Brian Michael Bendis','Esad Ribic',NULL,NULL,'Panini Comics España',NULL,'2013-01-01',NULL,NULL,replace(replace('Contiene Ultimate Comics Ultimates 12, Ultimate Comics All-New Spider-Man 12 y Ultimate Comics X-Men 12 y 13 USA \r\n¡Todo un universo en la palma de tu mano! En Ultimates, el ataque de Reed Richards contra Washington le ha convertido en el hombre más buscado del mundo, mientras que Iron Man trata de sobrevivir en La Ciudad... ¡Sin su armadura! En Spiderman, Miles debe elegir entre luchar contra su propio tío o unirse a él en su imperio criminal, si quiere proteger a su familia. Y en X-Men, tenemos el regreso de un olvidado enemigo... ¡Y Kitty Pryde debe salvar el mundo!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565717000-k0jzws.jpg','read',0,NULL,NULL,'2026-04-07 12:41:57','2026-04-07 17:38:50',63,NULL,'rustica','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Esad Ribic","role":"Dibujo, Tinta"},{"name":"Jonathan Hickman","role":"Guion"},{"name":"Paco Medina","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(338,'Ultimate Marvel (2012-2016) #10','Ultimate Marvel (2012-2016)',10,NULL,'9770005456003-00010',NULL,'Brian Michael Bendis','Esad Ribic',NULL,NULL,'Panini Comics España',NULL,'2013-02-01',NULL,NULL,replace(replace('Contiene Ultimate Comics Ultimates 13, Ultimate Comics All-New Spider-Man 13 y Ultimate Comics X-Men 14 USA \r\n¡El Universo Ultimate al alcance de tu mano! Aquí arranca el crossover que aglutina todas las series en una única trama argumental, que alterará significativamente el escenario en que se mueven nuestros héroes. En Ultimates, se produce el regreso del Capitán América, llamado a jugar un papel esencial en el futuro; en Spiderman, el Capi echa una mano al nuevo trepamuros, y en X-Men, Kitty Pryde comienza a reunir a la banda.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565719047-kwwwwf.jpg','read',0,NULL,NULL,'2026-04-07 12:42:00','2026-04-07 17:38:50',63,NULL,'rustica','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Esad Ribic","role":"Dibujo, Tinta"},{"name":"Jonathan Hickman","role":"Guion"},{"name":"Paco Medina","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(339,'Ultimate Marvel (2012-2016) #11','Ultimate Marvel (2012-2016)',11,NULL,'9770005456003-00011',NULL,'Brian Michael Bendis','Esad Ribic',NULL,NULL,'Panini Comics España',NULL,'2013-03-01',NULL,NULL,replace(replace('Contiene Ultimate Comics X-Men 15, Ultimate Comics All-New Spider-Man 14 y Ultimate Comics Ultimates 14 y 15 USA \r\nLa conclusión de &quot;Divididos, caeremos&quot;, el crossover que afecta a todo el Universo Ultimate. En X-Men, un refugiado mutantes se une a la lucha, mientras comienza la guerra por la libertad del homo superior. En Spiderman, Miles Morales se convierte en un miembro de Los Ultimates. Y en la serie de estos últimos, una crisis a nivel estatal une las fuerzas de todos los héroes... ¡Con el más sorprendente final que hayas visto jamás en el Universo Ultimate!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565721715-iw7j6i.jpg','read',0,NULL,NULL,'2026-04-07 12:42:02','2026-04-07 17:38:50',63,NULL,'rustica','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Esad Ribic","role":"Dibujo, Tinta"},{"name":"Jonathan Hickman","role":"Guion"},{"name":"Paco Medina","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(340,'Ultimate Marvel (2012-2016) #12','Ultimate Marvel (2012-2016)',12,NULL,'9770005456003-00012',NULL,'Brian Michael Bendis','Paco Medina',NULL,NULL,'Panini Comics España',NULL,'2013-04-01',NULL,NULL,replace(replace('Contiene Ultimate Comics Ultimates 16, Ultimate Comics X-Men 16 y Ultimate Comics All-New Spider-Man 15 y 16 USA \r\n&quot;Divididos, caemos&quot; ya terminó. ¿Qué podría venir a continuación? Un nuevo evento que sólo podría titularse &quot;Unidos, resistimos&quot;. Los acontecimientos que han tenido lugar han cambiado todo en el Universo Definitivo como nunca antes había ocurrido. ¡Ni siquiera &quot;Ultimatum&quot; es equiparable! ¿Qué será ahora del Capitán América, Iron Man, Thor y todos los demás? ¿Se convertirá Miles Morales en su nuevo integrante? ¿Y cuál será el destino de los mutantes en el nuevo statu quo?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565724151-h9trfr.jpg','read',0,NULL,NULL,'2026-04-07 12:42:04','2026-04-07 17:38:50',63,NULL,'rustica','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Paco Medina","role":"Dibujo, Tinta"},{"name":"Sam Humphries","role":"Guion"},{"name":"Brian Wood","role":"Guion"},{"name":"Luke Ross","role":"Dibujo"},{"name":"Carlo Barberi","role":"Dibujo"},{"name":"David Marquez","role":"Dibujo"},{"name":"Pepe Larraz","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(341,'Ultimate Marvel (2012-2016) #13','Ultimate Marvel (2012-2016)',13,NULL,'9770005456003-00013',NULL,'Brian Wood','Carlo Barberi',NULL,NULL,'Panini Comics España',NULL,'2013-05-01',NULL,NULL,replace(replace('Contiene Ultimate Comics X-Men 17 y 18, Ultimate Comics Ultimates 17 y Ultimate Comics All-New Spider-Man 16.1 USA \r\nContinúa &quot;Unidos, resistimos&quot;. Todo ha cambiado después del resultado de las elecciones. Ahora, los Ultimates deben combatir las fuerzas que amenazan con destruir el país para siempre, mientras Hydra se enfrenta a SHIELD. Además, alguien en el Daily Bugle quiere conocer la verdad sobre Spiderman y está dispuesto a todo por conseguirlo. Y también: el ejército mutante de resistencia continúa creciendo. ¿Podrá Kitty controlarlo?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565726555-xauako.jpg','read',0,NULL,NULL,'2026-04-07 12:42:07','2026-04-07 17:38:50',63,NULL,'rustica','[{"name":"Brian Wood","role":"Guion"},{"name":"Sam Humphries","role":"Guion"},{"name":"Brian Michael Bendis","role":""},{"name":"Carlo Barberi","role":"Dibujo"},{"name":"Luke Ross","role":"Dibujo"},{"name":"David Marquez","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(342,'Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-) #95','Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-)',95,NULL,'9770005339009-00095',NULL,'Dan Slott','Humberto Ramos',NULL,NULL,'Panini Comics España',NULL,'2014-09-05',NULL,NULL,replace(replace('Contiene Amazing Spider-Man v3, 1 y 2 y Superior Foes Of Spider-Man 10 USA \r\n¡Aquí está! ¡Vuelve el mayor superhéroe de todos los tiempos! El mundo ha cambiado desde que el auténtico trepamuros lo abandonara, pero también lo ha hecho Peter Parker. Aquí está un hombre que ha recibido una segunda oportunidad en la vida, y no está dispuesto a desperdiciarla. La Suerte Parker de siempre sigue ahí, pero ahora también tenemos una nueva Actitud Parker. Dan Slott, el guionista detrás de &quot;A lo grande&quot; y de &quot;Spiderman Superior&quot;, sigue al frente de las aventuras del Hombre Araña, en su mejor momento de las últimas décadas... ¡Y Humberto Ramos también ha vuelto a casa!','\r',char(13)),'\n',char(10)),NULL,NULL,176,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565765881-pa7vuc.jpg','read',0,NULL,NULL,'2026-04-07 12:42:48','2026-04-07 17:38:50',64,NULL,'rustica','[{"name":"Dan Slott","role":"Guion"},{"name":"Christos N. Gage","role":"Guion"},{"name":"Joe Caramagna","role":"Guion"},{"name":"James Asmus","role":"Guion"},{"name":"Humberto Ramos","role":"Dibujo"},{"name":"Javier Rodríguez","role":"Dibujo, Tinta"},{"name":"Giuseppe Camuncoli","role":"Dibujo"},{"name":"Chris Eliopoulos","role":"Dibujo"},{"name":"Gerardo Sandoval","role":"Dibujo"},{"name":"Andres Mossa","role":"Dibujo"},{"name":"Terry Pallot","role":"Dibujo"},{"name":"Clayton Cowles","role":"Dibujo"},{"name":"Nuno Plati","role":"Dibujo"},{"name":"Siya Oum","role":"Dibujo"},{"name":"Carmen Carnero","role":"Dibujo"},{"name":"Victor Olazaba","role":"Tinta"},{"name":"Álvaro López","role":"Tinta"},{"name":"John Dell","role":"Tinta"},{"name":"Cam Smith","role":"Tinta"},{"name":"Jim Charalampidis","role":"Tinta"},{"name":"Edgar Delgado","role":"Color"},{"name":"Antonio Fabela","role":"Color"},{"name":"Joe Quinones","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(343,'Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-) #96','Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-)',96,NULL,'9770005339009-00096',NULL,'Dan Slott','Humberto Ramos',NULL,NULL,'Panini Comics España',NULL,'2014-10-03',NULL,NULL,replace(replace('Contiene Amazing Spider-Man v3, 3 y 4 y Superior Foes Of Spider-Man 11 y 12 USA\r\nUn cómic ligado a &quot;Pecado Original&quot;. Por culpa de su último encuentro con Spiderman, Felicia Hardy lo perdió todo. Ahora, La Gata Negra ha vuelto, y no quiere que le pidan perdón ni disculpas. Quiere venganza. Y también: ¿quién es Seda y de qué manera está relacionada con el origen de nuestro trepamuros?','\r',char(13)),'\n',char(10)),NULL,NULL,176,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565785190-lwknos.jpg','read',0,NULL,NULL,'2026-04-07 12:43:06','2026-04-07 17:38:50',64,NULL,'rustica','[{"name":"Dan Slott","role":"Guion"},{"name":"Tom Peyer","role":"Guion"},{"name":"Elliott Kalan","role":"Guion"},{"name":"Nick Spencer","role":"Guion"},{"name":"Humberto Ramos","role":"Dibujo, Tinta, Color"},{"name":"Will Sliney","role":"Dibujo"},{"name":"Carmen Carnero","role":"Dibujo"},{"name":"Nuno Plati","role":"Dibujo"},{"name":"Steve Lieber","role":"Dibujo"},{"name":"Victor Olazaba","role":"Tinta"},{"name":"Terry Pallot","role":"Tinta"},{"name":"Edgar Delgado","role":"Dibujo, Tinta, Color"},{"name":"Chris Sotomayor","role":"Dibujo, Tinta, Color"},{"name":"John Rauch","role":"Color"},{"name":"Rachelle Rosenberg","role":"Color"},{"name":"Al Barrionuevo","role":"Dibujo, Tinta, Color"},{"name":"Ronald Wimberly","role":"Dibujo, Tinta, Color"},{"name":"Frank Cho","role":"Dibujo, Tinta, Color"},{"name":"Tim Sale","role":"Dibujo, Tinta, Color"},{"name":"J. Scott Campbell","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(344,'Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-) #112','Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-)',112,NULL,'9770005339009-00112',NULL,'Christos N. Gage','Paco Díaz',NULL,NULL,'Panini Comics España',NULL,'2016-02-04',NULL,NULL,replace(replace('Contiene Secret Wars: Spider-Island 1-5 USA \r\nUn cómic ligado a &quot;Secret Wars&quot;. La Reina Araña ha transformado Manhattan en una isla dominada por monstruos arácnidos. Peter Parker perdió en este territorio de Mundo de Batalla, pero los supervivientes tratan de encontrar la manera de cambiar las tornas. Y además, las aventuras de Spidergirl, por el equipo dorado de Tom DeFalco, Ron Frenz y Sal Buscema.','\r',char(13)),'\n',char(10)),NULL,NULL,176,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565793309-0akix3.jpg','read',0,NULL,NULL,'2026-04-07 12:43:13','2026-04-07 17:38:50',64,NULL,'rustica','[{"name":"Christos N. Gage","role":"Guion"},{"name":"Paco Díaz","role":"Dibujo, Tinta"},{"name":"Frank D''Armata","role":"Color"},{"name":"Tom DeFalco","role":"Guion"},{"name":"Ron Frenz","role":"Guion, Dibujo, Tinta"},{"name":"Sal Buscema","role":"Dibujo, Tinta"},{"name":"Andrew Crossley","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(345,'Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-) #97','Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-)',97,NULL,'9770005339009-00097',NULL,'Dan Slott','Joe Caramagna',NULL,NULL,'Panini Comics España',NULL,'2014-11-06',NULL,NULL,replace(replace('Contiene Amazing Spider-Man v3, 5, Giant-Size Spider-Man v2, 1 y Superior Foes Of Spider-Man 13-14 USA \r\nCon una historia relacionada con &quot;Pecado Original&quot;. El mayor secreto del mundo de Spiderman tiene un nombre: ¡Seda! ¿Quién es esta misteriosa mujer y qué tiene que ver con la Gata Negra y Electro? Además, cuatro titánicas historias del pasado de Spidey.','\r',char(13)),'\n',char(10)),NULL,NULL,176,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565799631-runfq8.jpg','read',0,NULL,NULL,'2026-04-07 12:43:20','2026-04-07 17:38:50',64,NULL,'rustica','[{"name":"Dan Slott","role":""},{"name":"Joe Caramagna","role":""},{"name":"Nick Spencer","role":""},{"name":"Humberto Ramos","role":""},{"name":"Scott Koblish","role":""},{"name":"Giancarlo Caracuzzo","role":""},{"name":"Francesca Ciregia","role":""},{"name":"Elena Casagrande","role":""},{"name":"Tim Seeley","role":""},{"name":"Steve Lieber","role":""},{"name":"Rich Ellis","role":""},{"name":"Edgar Delgado","role":""},{"name":"SotoColor Graphics","role":""},{"name":"Rachelle Rosenberg","role":""},{"name":"Kris Anka","role":""},{"name":"Victor Olazaba","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(346,'Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-) #98','Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-)',98,NULL,'9770005339009-00098',NULL,'Dan Slott','Humberto Ramos',NULL,NULL,'Panini Comics España',NULL,'2014-12-05',NULL,NULL,replace(replace('Contiene Amazing Spider-Man v3, 6, Spider-Man Spectacular One-Shot y Superior Foes of Spider-Man 15 y 16 USA \r\nEl final del primer arco de la nueva etapa de Peter Parker bajo la máscara de Spiderman. Industrias Parker prometieron un sistema de contención seguro y respetuoso con los derechos humanos, que sirviera para mantener a raya a todos los villanos... ¡Pero La Gata Negra y Electro tienen otros planes! Además: los secretos de Seda salen a la luz.','\r',char(13)),'\n',char(10)),NULL,NULL,176,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565802532-y78l3g.jpg','read',0,NULL,NULL,'2026-04-07 12:43:23','2026-04-07 17:38:50',64,NULL,'rustica','[{"name":"Dan Slott","role":"Guion"},{"name":"Humberto Ramos","role":"Dibujo, Tinta, Color"},{"name":"Joe Caramagna","role":"Guion"},{"name":"Scott Koblish","role":"Dibujo"},{"name":"Cory Hamscher","role":"Dibujo"},{"name":"Nick Spencer","role":"Guion"},{"name":"Steve Lieber","role":"Dibujo, Tinta, Color"},{"name":"Tim Seeley","role":"Dibujo"},{"name":"Jacopo Camagni","role":"Dibujo"},{"name":"Victor Olazaba","role":"Tinta"},{"name":"Edgar Delgado","role":"Dibujo, Tinta, Color"},{"name":"SotoColor Graphics","role":"Color"},{"name":"Rachelle Rosenberg","role":"Dibujo, Tinta, Color"},{"name":"Patrick Scherberger","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(347,'Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-) #99','Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-)',99,NULL,'9770005339009-00099',NULL,'Dan Slott','Giuseppe Camuncoli',NULL,NULL,'Panini Comics España',NULL,'2015-01-02',NULL,NULL,replace(replace('Con The Amazing Spider-Man v3, 7 y 8, The Superior Spider-Man 32 y 33 y The Superior Foes Of Spider-Man 17 USA\r\n&quot;Universo Spiderman&quot;, la saga más ambiciosa jamás planteada por Dan Slott se acerca... ¡Y los Hombres Araña de diferentes universos van a lamentarlo, empezando con la Spidergirl del MC2! Además, Ms. Marvel se cruza en el camino de Peter y el Spiderman Superior regresa... Pero ¿dónde está? ¿Qué está haciendo? ¿Y cómo ha llegado hasta ahí?\r\nNota: Superior Foes of Spider-man fue cancelada en el #17 USA, por lo que su serialización concluirá en este tomo.','\r',char(13)),'\n',char(10)),NULL,NULL,176,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565805175-cmbuch.jpg','read',0,NULL,NULL,'2026-04-07 12:43:25','2026-04-07 17:38:50',64,NULL,'rustica','[{"name":"Dan Slott","role":"Guion"},{"name":"Giuseppe Camuncoli","role":"Dibujo"},{"name":"Christos N. Gage","role":"Guion"},{"name":"Adam Kubert","role":"Dibujo"},{"name":"Nick Spencer","role":"Guion"},{"name":"Steve Lieber","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(348,'Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-) #100','Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-)',100,NULL,'9770005339009-00100',NULL,'Dan Slott','Ramón Pérez',NULL,NULL,'Panini Comics España',NULL,'2015-02-05',NULL,NULL,replace(replace('Contiene Amazing Spider-Man 1.1-1.5, Spider-Man / Human Torch 1-5 y material de Amazing Fantasy vol. 2, 15 USA \r\n¡La colección del Hombre Araña alcanza su número 100! Es el primer número 100 desde la llegada de Panini, hace diez años y queremos celebrarlo por todo lo alto. Empezamos con una historia que vuelve al primer día de Spiderman. Es el año uno construido por Dan Slott con el extraordinario dibujo de Ramón Pérez. Y a continuación, recuperamos, por primera vez en su formato original, la obra maestra con la que Slott comenzó a narrar las historias de Spidey: su alucinante miniserie compartida con La Antorcha Humana. Además, descubre el mayor misterio en la historia del trepamuros, y mucho más, en un tomo histórico. ¡El primer nº 100 de Spiderman en España en casi treinta años!','\r',char(13)),'\n',char(10)),NULL,NULL,176,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565807771-3qgtv4.jpg','read',0,NULL,NULL,'2026-04-07 12:43:28','2026-04-07 17:38:50',64,NULL,'rustica','[{"name":"Dan Slott","role":"Guion"},{"name":"Ramón Pérez","role":"Dibujo"},{"name":"Ty Templeton","role":"Dibujo"},{"name":"Patrick Scherberger","role":"Dibujo"},{"name":"Ian Herring","role":"Color"},{"name":"Nelson Palmer","role":"Tinta"},{"name":"Tom Palmer","role":"Tinta"},{"name":"Drew Geraci","role":"Tinta"},{"name":"Greg Adams","role":"Tinta"},{"name":"Alex Ross","role":"Dibujo, Tinta, Color"},{"name":"Felix Serrano","role":"Color"},{"name":"Paul Smith","role":"Dibujo, Tinta, Color"},{"name":"SotoColor Graphics","role":"Color"},{"name":"John Rauch","role":"Color"},{"name":"Norman Lee","role":"Tinta"},{"name":"Matt Nelson","role":"Color"},{"name":"Pete Woods","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(349,'Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-) #101','Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-)',101,NULL,'9770005339009-00101',NULL,'David Hine','Richard Isanove',NULL,NULL,'Panini Comics España',NULL,'2015-03-05',NULL,NULL,replace(replace('Contiene Guardians Of The Galaxy FCBD 2014 y Edge Of The Spider-Verse 1-5 USA \r\n¡El prólogo a &quot;Universo Spiderman&quot; está aquí! Peter Parker fue el primer Spiderman, pero hay muchos más Hombres Araña... ¡Y en esta aventura los encontrarás a todos! ¿Cómo se ven envueltos en esta monumental saga? Descúbrelo en estas páginas. Spiderman Noir, Gwen Stacy (sí, Gwen Stacy), el misterioso Dr. Aaron Aikman y muchos más, en el prólogo del mayor evento jamás narrado en la Franquicia Arácnida.','\r',char(13)),'\n',char(10)),NULL,NULL,176,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565810709-cn793n.jpg','read',0,NULL,NULL,'2026-04-07 12:43:31','2026-04-07 17:38:50',64,NULL,'rustica','[{"name":"David Hine","role":""},{"name":"Richard Isanove","role":""},{"name":"Robbi Rodriguez","role":""},{"name":"Greg Land","role":""},{"name":"Dustin Weaver","role":""},{"name":"Clay McLeod Chapman","role":""},{"name":"Elia Bonetti","role":""},{"name":"Gerard Way","role":""},{"name":"Jake Wyatt","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(350,'Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-) #102','Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-)',102,NULL,'9770005339009-00102',NULL,'Dan Slott','Olivier Coipel',NULL,NULL,'Panini Comics España',NULL,'2015-04-01',NULL,NULL,replace(replace('Contiene Amazing Spider-Man 9 y 10, Spider-Verse Team-Up 1, Spider-Verse 1 y Scarlet Spiders 1 USA \r\nAl fin... ¡&quot;Universo Spiderman&quot; empieza aquí! Olivier Coipel, el dibujante de Asedio y Dinastía de M, se une a Dan Slott para ofrecerte el mayor evento en la historia de Spiderman. Más peligroso que nunca, Morlum amenaza a todos los Hombres Araña que existen en el Multiverso, pero esta vez no está solo: tiene a la familia a su lado. ¡Todos los Spiderman que han existido están en peligro!','\r',char(13)),'\n',char(10)),NULL,NULL,176,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565813119-59nqhg.jpg','read',0,NULL,NULL,'2026-04-07 12:43:34','2026-04-07 17:38:50',64,NULL,'rustica','[{"name":"Dan Slott","role":"Guion"},{"name":"Olivier Coipel","role":"Dibujo"},{"name":"Skottie Young","role":""},{"name":"Humberto Ramos","role":"Dibujo"},{"name":"Christos N. Gage","role":"Guion"},{"name":"Roger Stern","role":"Guion"},{"name":"Mike Costa","role":""},{"name":"Paco Díaz","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(351,'Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-) #103','Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-)',103,NULL,'9770005339009-00103',NULL,'Dan Slott','Olivier Coipel',NULL,NULL,'Panini Comics España',NULL,'2015-05-07',NULL,NULL,replace(replace('Contiene Amazing Spider-Man 11 y 12, Scarlet Spiders 2 y 3 USA y Spider-Verse Team-Up 2 USA\r\nCon la tercera y cuarta parte de &quot;Universo Spiderman&quot;. Es la lucha que estabas esperando: El Asombroso Spiderman contra el Spiderman Superior. Puede que el ejército de Hombres Araña no tenga tiempo para este tipo de disputas, pero... ¡Peter y Otto quizás no piensen igual! Un choque que sirve de preludio a la gran batalla contra Morlun y su terrible familia.','\r',char(13)),'\n',char(10)),NULL,NULL,176,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565815751-7h0n8z.jpg','read',0,NULL,NULL,'2026-04-07 12:43:36','2026-04-07 17:38:50',64,NULL,'rustica','[{"name":"Dan Slott","role":"Guion"},{"name":"Olivier Coipel","role":"Dibujo"},{"name":"Christos N. Gage","role":""},{"name":"Dave Williams","role":""},{"name":"Gerry Conway","role":""},{"name":"Steven Sanders","role":""},{"name":"Mike Costa","role":""},{"name":"Paco Díaz","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(352,'Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-) #104','Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-)',104,NULL,'9770005339009-00104',NULL,'Dan Slott','Giuseppe Camuncoli',NULL,NULL,'Panini Comics España',NULL,'2015-06-05',NULL,NULL,replace(replace('Contiene Amazing Spider-Man 13, Spider-Verse Team-Up 3 y Spider-Verse 2 USA \r\nCon la quinta parte de &quot;Universo Spiderman&quot;. ¡La batalla final comienza aquí! Cada Spiderman que ha existido y sigue vivo debe luchar, y ninguno está a salvo. Además, una misión que requiere de cinco Hombres Araña, una nueva aventura de Spidergirl que recupera al mítico equipo de Tom DeFalco y Ron Frenz y las historias de las versiones de nuestro héroe que menos imaginas.','\r',char(13)),'\n',char(10)),NULL,NULL,176,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565817931-yl3qmu.jpg','read',0,NULL,NULL,'2026-04-07 12:43:39','2026-04-07 17:38:50',64,NULL,'rustica','[{"name":"Dan Slott","role":"Guion"},{"name":"Giuseppe Camuncoli","role":"Dibujo"},{"name":"Christos N. Gage","role":"Guion"},{"name":"Tom DeFalco","role":""},{"name":"Dave Williams","role":"Dibujo"},{"name":"Kathryn Immomen","role":"Guion"},{"name":"Kris Anka","role":"Dibujo"},{"name":"David Lafuente","role":"Dibujo"},{"name":"Ron Frenz","role":"Guion"},{"name":"Sal Buscema","role":"Dibujo"},{"name":"Enrique Puig","role":"Guion"},{"name":"Francisco Herrera","role":"Dibujo"},{"name":"Ty Templeton","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(353,'Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-) #105','Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-)',105,NULL,'9770005339009-00105',NULL,NULL,NULL,NULL,NULL,'Panini Comics España',NULL,'2015-07-02',NULL,NULL,replace(replace('Contiene The Amazing Spider-Man v3, 14 y 15, Spider-Gwen 1 y Silk 1 USA \r\n¡La conclusión y el epílogo de &quot;Universo Spiderman&quot;! La profecía está a punto de cumplirse, pero el Spiderman Superior tiene algo que decir al respecto. ¿Y qué aguardará a Peter Parker y el resto de los supervivientes cuando todo termine? Además, de los hechos de &quot;Universo Spiderman&quot;, llegan las aventuras en solitario de Spidergwen... ¡empezando por su origen! Y también: Seda comienza la búsqueda de su pasado.','\r',char(13)),'\n',char(10)),NULL,NULL,176,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565820246-gutdue.jpg','read',0,NULL,NULL,'2026-04-07 12:43:41','2026-04-07 17:38:50',64,NULL,'rustica',NULL);
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(354,'Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-) #106','Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-)',106,NULL,'9770005339009-00000',NULL,'Gerry Conway','Brandon Peterson',NULL,NULL,'Panini Comics España',NULL,'2015-08-06',NULL,NULL,replace(replace('Contiene The Amazing Spider-Man v3, 16.1, Annual 1, Silk 2 y Spider-Gwen 2 USA \r\nCon el comienzo de &quot;Espiral&quot;, la saga en la que el legendario Gerry Conway, el hombre que mató a Gwen Stacy, regresa a la Franquicia arácnida. El crimen organizado ha estado en tensión desde que Kingpin consiguió hacerse con Tierra de Sombras. Ahora la guerra está a punto de estallar y Spidey tendrá que hacer algo al respecto, pero no es el único... Ha llegado el momento de que regrese la Capitana Watanabe. ¡Es la hora de El Espectro!','\r',char(13)),'\n',char(10)),NULL,NULL,176,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565823764-9mw6b8.jpg','read',0,NULL,NULL,'2026-04-07 12:43:44','2026-04-07 17:38:50',64,NULL,'rustica','[{"name":"Sean Ryan","role":""},{"name":"Brandon Peterson","role":""},{"name":"Gerry Conway","role":"Guion"},{"name":"Carlo Barberi","role":""},{"name":"Robbie Thompson","role":""},{"name":"Stacey Lee","role":""},{"name":"Jason Latour","role":""},{"name":"Robbi Rodriguez","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(355,'Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-) #107','Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-)',107,NULL,'9770005339009-00107',NULL,'Gerry Conway','Carlo Barberi',NULL,NULL,'Panini Comics España',NULL,'2015-09-03',NULL,NULL,replace(replace('Contiene Amazing Spider-Man v3, 17.1 y 18.1, Silk 3 y 4 y Spider-Gwen 3 USA \r\nCon las partes dos y tres de “Espiral”, la aventura que supone el regreso a casa de Gerry Conway. La mecha se ha encendido en el mundo criminal de Nueva York, mientras Spidey y El Espectro tratan de contener las llamas. Pero, ¿qué ocurre cuando Cabeza de Martillo entra en combate? Y además, siguen las aventuras de Seda y Spider-Gwen.','\r',char(13)),'\n',char(10)),NULL,NULL,176,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565825951-b2qjqj.jpg','read',0,NULL,NULL,'2026-04-07 12:43:46','2026-04-07 17:38:50',64,NULL,'rustica','[{"name":"Gerry Conway","role":"Guion"},{"name":"Carlo Barberi","role":""},{"name":"Robbie Thompson","role":""},{"name":"Stacey Lee","role":""},{"name":"Jason Latour","role":""},{"name":"Robbi Rodriguez","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(356,'Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-) #108','Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-)',108,NULL,'9770005339009-00108',NULL,'Gerry Conway','Carlo Barberi',NULL,NULL,'Panini Comics España',NULL,'2015-10-01',NULL,NULL,replace(replace('Contiene The Amazing Spider-Man v3, 19.1 y 20.1, Marvel 75th Anniversary Celebration, Silk 5 y Spider-Gwen 4 y 5 USA \r\nCon la conclusión de “Espiral”. La ola de crímenes que asuela Nueva York continúa imparable, mientras que Spiderman se ha visto atrapado entre un grupo de supercriminales y su aliada, El Espectro! Y además, continúan las aventuras de Seda y Spider-Gwen y el mítico Tom DeFalco vuelve a casa para una pequeña gran historia del trepamuros.','\r',char(13)),'\n',char(10)),NULL,NULL,176,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565828037-c2yyul.jpg','read',0,NULL,NULL,'2026-04-07 12:43:48','2026-04-07 17:38:50',64,NULL,'rustica','[{"name":"Gerry Conway","role":"Guion"},{"name":"Carlo Barberi","role":""},{"name":"Tom DeFalco","role":""},{"name":"Stan Goldberg","role":""},{"name":"Robbie Thompson","role":""},{"name":"Stacey Lee","role":""},{"name":"Jason Latour","role":""},{"name":"Robbi Rodriguez","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(357,'Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-) #109','Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-)',109,NULL,'9770005339009-00109',NULL,'Dan Slott','Humberto Ramos',NULL,NULL,'Panini Comics España',NULL,'2015-11-05',NULL,NULL,replace(replace('Contiene Amazing Spider-Man 16-18 y Silk 6 y 7 USA \r\n“Espiral” puede haber terminado, pero eso no quiere decir que la vida de Peter Parker esté a salvo. Alguien (o algo) ha invadido Industrias Parker y está dando caza a sus empleados. Frente al sabotaje, ningún secreto está a salvo, nadie está a salvo tampoco y Peter tendrá que tomar decisiones trascendentales. Además, el final de la miniserie de Seda.','\r',char(13)),'\n',char(10)),NULL,NULL,176,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565829946-16u1t8.jpg','read',0,NULL,NULL,'2026-04-07 12:43:50','2026-04-07 17:38:50',64,NULL,'rustica','[{"name":"Dan Slott","role":"Guion"},{"name":"Christos N. Gage","role":""},{"name":"Humberto Ramos","role":"Dibujo"},{"name":"Robbie Thompson","role":""},{"name":"Stacey Lee","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(358,'Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-) #110','Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-)',110,NULL,'9770005339009-00110',NULL,'Dan Slott','Adam Kubert',NULL,NULL,'Panini Comics España',NULL,'2015-12-03',NULL,NULL,replace(replace('Contiene Amazing Spider-Man: Renew Your Vows 1-5 USA \r\nUna colección ligada a “Secret Wars”. Con los cinco capítulos de “Renueva tus votos”, la última historia de Spider-Man. Ni siquiera el trepamuros está a salvo de las Guerras Secretas. Peter Parker, Mary Jane y su hija están juntos de nuevo. ¿No era lo que habías pedido? Pues deberías tener cuidado con lo que deseas, porque puede hacerse realidad.','\r',char(13)),'\n',char(10)),NULL,NULL,176,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565833072-48kyjs.jpg','read',0,NULL,NULL,'2026-04-07 12:43:53','2026-04-07 17:38:50',64,NULL,'rustica','[{"name":"Dan Slott","role":"Guion"},{"name":"Adam Kubert","role":"Dibujo"},{"name":"John Dell","role":"Tinta"},{"name":"Justin Ponsor","role":"Color"},{"name":"Mark Morales","role":"Tinta"},{"name":"Scott Hanna","role":"Dibujo"},{"name":"Andrew Hennessy","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(359,'Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-) #111','Spiderman Vol. 7 / Spiderman Superior / El Asombroso Spiderman (2006-)',111,NULL,'9770005339009-00111',NULL,'Mike Costa','Andre Araujo',NULL,NULL,'Panini Comics España',NULL,'2016-01-07',NULL,NULL,replace(replace('Contiene Secret Wars: Spider-Verse 1-5 USA \r\nCruce con “Secret Wars”. Con las cinco partes de “Universo Spiderman”. Un grupo de Arañas afronta la vida en Mundo de Batalla. ¡Con la participación de Spider-Gwen, Spiderman Noir, Spiderman India, Anya Corazón, Spider-UK y Spiderham!','\r',char(13)),'\n',char(10)),NULL,NULL,176,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565835249-b6trby.jpg','read',0,NULL,NULL,'2026-04-07 12:43:56','2026-04-07 17:38:50',64,NULL,'rustica','[{"name":"Mike Costa","role":"Guion"},{"name":"Andre Araujo","role":"Dibujo, Tinta"},{"name":"Rachelle Rosenberg","role":"Color"},{"name":"Steven Sanders","role":"Dibujo, Tinta"},{"name":"Jim Campbell","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(360,'Batwoman. Nuevo Universo DC #1','Batwoman. Nuevo Universo DC',1,NULL,'978-8-415-62836-1',NULL,'Haden Blackman','J. H. Williams III',NULL,NULL,'ECC Ediciones',NULL,'2012-08-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batwoman 0 - 5 USA\r\nHistorias:\r\nMas alla de una sombra\r\nHidrología Parte 1. Lixiviación\r\nHidrología Parte 2. Infiltración\r\nHidrología Parte 3. Corriente creciente\r\nHidrología Parte 4. Estuario\r\nHidrología Parte 5. Evapotranspiracion\r\nMientras trata de asumir los dolorosos secretos que le ocultó su propio padre, Kate Kane afronta la necesidad de entrenar a Flamebird, empeñada en convertirse en su compañera. Pero lo que realmente preocupa a Batwoman es resolver el caso abierto a raíz de la desaparición de varios niños, aparentemente secuestrados en el barrio hispano de Gotham City. Demasiados frentes abiertos, a los que hay que sumar el hecho de que esté siendo investigada por una misteriosa agencia gubernamental…\r\nTras haber desarrollado al personaje en las páginas de Detective Comics, J.H. Williams III –Los siete soldados de la victoria, Promethea– afronta la esperada serie regular protagonizada por la Mujer Murciélago: una ambiciosa etapa que, realizada junto a W. Haden Blackman y Amy Reeder, ya se ha convertido en una de las colecciones de referecia en el Nuevo Universo DC.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565863829-57p9jx.jpg','read',0,NULL,NULL,'2026-04-07 12:44:28','2026-04-07 17:38:50',65,15.96,'Rústica','[{"name":"Haden Blackman","role":"Guion"},{"name":"J. H. Williams III","role":"Dibujo"},{"name":"Amy Reeder","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(361,'Catwoman. Nuevo Universo DC #1','Catwoman. Nuevo Universo DC',1,NULL,'978-8-415-52061-0',NULL,'Judd Winick','Guillem March',NULL,NULL,'ECC Ediciones',NULL,'2012-05-01',NULL,NULL,replace(replace('Contiene: Catwoman Vol. 4 #1-6 USA\r\nHistorias:\r\n- Y nos dejamos puesto casi todo el disfraz\r\n- Dire que dormiria mejor, pero seria mentira\r\n- Que no encuentren nada sobre mi\r\n- ¿Aun te dedicas a eso?\r\n- Esto me huele mal\r\n- Bienvenida. Sera por las malas\rFlash tomó la imprudente decisión de viajar al pasado y cambiar la historia en beneficio propio, salvando a su madre de morir a manos de otro viajero en el tiempo. El resultado fue la completa reescritura de la Historia, y el nacimiento de un mundo nuevo que pudimos ver en las páginas de Flashpoint. Finalmente, en un desesperado intento de corregir su error, volvió a cambiar el pasado provocando una paradoja que hizo pedazos la línea temporal existente para reconstruir con ellos la que conocía. O al menos lo intentó...En este Nuevo Universo DC no todo es como antes: héroes y villanos han seguido caminos semejantes a los de antaño, pero pocas veces coincidentes. Como muchos otros Selina Kyle, Catwoman, empieza hoy una nueva vida...','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565899207-9i3eum.jpg','read',0,NULL,NULL,'2026-04-07 12:45:03','2026-04-07 17:38:50',66,23.95,'Rústica','[{"name":"Judd Winick","role":""},{"name":"Guillem March","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(362,'Dial H #1','Dial H',1,NULL,'978-8-415-92518-7',NULL,'China Miéville','Riccardo Burchielli',NULL,NULL,'ECC Ediciones',NULL,'2013-07-01',NULL,NULL,replace(replace('CONTENIDO USA: Dial H Vol. 1 (2012-2013) #0-6\r\nHISTORIAS: Si quiera saber qué está pasando llame a información... / Pérdida de conexión / ¡Ven! ¡Te necesito! / Dentro de ti / Sin conexión / Reloj de arena, H de Héroe\r\nARGUMENTO: Nelson Jent no lleva una vida sana. Tiene sobrepeso, fuma y sufrió un infarto antes de cumplir los 30. En otras palabras, nadie diría que está a punto de convertirse en superhéroe. Pero cuando el azar lo conduce a una cabina telefónica en que marca el número de la policía, se convierte en... ¡Chico Chimenea! ¡Y en Capitán Lacrimoso! ¡Y en cualquier personaje extraño que se le antoje al poderoso Dial H, el artefacto más extraño del mundo!','\r',char(13)),'\n',char(10)),NULL,NULL,160,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565934959-pq5lj1.jpg','read',0,NULL,NULL,'2026-04-07 12:45:38','2026-04-07 17:38:50',67,23.95,'Rústica','[{"name":"China Miéville","role":"Guion"},{"name":"Riccardo Burchielli","role":"Dibujo"},{"name":"Matt Santolouco","role":"Dibujo, Tinta"},{"name":"Tanya Horie","role":"Color"},{"name":"Richard Horie","role":"Color"},{"name":"David Lapham","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(363,'Batman: Maldad Eterna #1','Batman: Maldad Eterna',1,NULL,'978-8-416-07001-5',NULL,'Ray Fawkes','Jeremy Haun',NULL,NULL,'ECC Ediciones',NULL,'2014-02-28',NULL,NULL,replace(replace('Contenido USA: Batman Vol. 2 #23.2, Batman and Robin Vol.2 #23.1, Detective Comics Vol. 2 #23.1 y #23.3\r\nHistorias: Historia de dos semblantes / El reino Verde / Solitario / La ciudad del miedo\r\nArgumento: Gotham está indefensa sin Batman, por lo que Dos Caras decidirá su destino con su moneda marcada. Hiedra Venenosa camina por una Gotham instalada en el caos, recordándo su pasado y planeando un futuro verde para la ciudad tras la desaparición de su cruzado enmascarado. El Acertijo ataca la torre Wayne, pero no son sus secretos lo único que busca. El espantapájaros recorre varios distritos de Gotham reclutando villanos para la guerra que se avecina con Blackgate.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565975888-rtnd9l.jpg','read',0,NULL,NULL,'2026-04-07 12:46:19','2026-04-07 17:38:50',68,NULL,'rustica','[{"name":"Ray Fawkes","role":"Guion"},{"name":"Scott Snyder","role":"Guion"},{"name":"Jeremy Haun","role":"Dibujo, Tinta"},{"name":"John Rauch","role":"Color"},{"name":"James Tynion IV","role":"Guion"},{"name":"Jorge Lucas","role":"Dibujo, Tinta"},{"name":"Dave McCaig","role":"Color"},{"name":"Derek Fridolfs","role":"Dibujo"},{"name":"Javier Pina","role":"Tinta"},{"name":"John Kalisz","role":"Color"},{"name":"Peter J. Tomasi","role":"Guion"},{"name":"Szymon Kudranski","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(364,'Batman: Maldad Eterna #2','Batman: Maldad Eterna',2,NULL,'978-8-416-07039-8',NULL,'John Layman','Cliff Richards',NULL,NULL,'ECC Ediciones',NULL,'2014-03-31',NULL,NULL,replace(replace('CONTENIDO USA: Batman: The Dark Knight núm. 23.3 USA, Batman Vol. 2 #23.1 USA, Batman and Robin Vol.2 #23.2 USA, Batman: The Dark Knight Annual núm. 1 USA y Detective Comics núm. 23.4 USA\r\nHISTORIAS: Monerías / Algo más que otra cara bonita / Exquisito terror / Descenso\r\nARGUMENTO: Hace ocho años, el Joker rememora un traumático recuerdo de su infancia mientras perpreta una de sus carnicerías en el Zoo de Gotham, momento en el que decide secuestrar a un bebe gorila y educarlo como Jackanapes. Clayface intenta demostrar a la Sociedad Secreta que no es un perdedor. El Tribunal de los Búhos no fué destruido tras la aciaga noche que desencadenó sobre Gotham, trás el ataque de la Sociedad Secreta sobre la ciudad, uno de sus miembros desencadenará un mal primigenio para evitar la destrucción del tribunal. El doctor Langstrom combina su suero con la fórmula que convirtió a su mujer en She-bat para vencerla, pero ante la ola de crímen desatada por la Sociedad Secreta no parará de mejorar su química iniciando un proceso de funestas consencuencias para su psique. La última historia está desvinculada del evento &quot;maldad eterna&quot; y en ella tres villanos de Batman (El espantapájaros, el pinguino y el sombrerero loco) son engañados para acudir una noche de Halloween a un misterioso lugar donde vivirán una terrorífica experiencia.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565984119-0djk25.jpg','read',0,NULL,NULL,'2026-04-07 12:46:25','2026-04-07 17:38:50',68,NULL,'rustica','[{"name":"John Layman","role":"Guion"},{"name":"Cliff Richards","role":"Dibujo, Tinta"},{"name":"Matt Yackey","role":"Color"},{"name":"Andy Kubert","role":"Guion"},{"name":"Andy Clarke","role":"Dibujo, Tinta"},{"name":"Blond","role":"Color"},{"name":"James Tynion IV","role":"Guion"},{"name":"Jorge Lucas","role":"Dibujo, Tinta"},{"name":"Dave McCaig","role":"Color"},{"name":"Gregg Hurwitz","role":"Guion"},{"name":"Szymon Kudranski","role":"Dibujo, Tinta"},{"name":"John Kalisz","role":"Color"},{"name":"Frank Tieri","role":"Guion"},{"name":"Scot Eaton","role":"Dibujo"},{"name":"Jaime Mendoza","role":"Tinta"},{"name":"Jeromy Cox","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(365,'Batman: Maldad Eterna #3','Batman: Maldad Eterna',3,NULL,'978-8-416-07069-5',NULL,'Gail Simone','Derlis Santacruz',NULL,NULL,'ECC Ediciones',NULL,'2014-04-30',NULL,NULL,replace(replace('CONTENIDO USA: Batman: The Dark Knight Vol. 2 #23.1, Batman Vol 2 #23.3 - 23.4 y Batman and Robin Vol. 2  #23.4 USA\r\nHISTORIAS: Ha nacido una estrella roja / Abusones / Oscuro destino / Sangre en el agua\r\nARGUMENTO: Shauna, la nueva ventrílocua, se prepara para ofrecer un show a un grupo de refugiados gothamitas mientras rememora su origen. El gobernador de Gotham, antiguo defensor de Cobblepot en el instituto, se compromete a terminar con el imperio del Pinguino, pero descubrirá el error fatal que es subestimarle. Bane emprende desde Santa Prisca su conquista de Gotham ahora que su protector ha desaparecido gracias al Sindicato del Crímen. Un grupo de policías corruptos se adentra en las alcantarillas para reunirse con un tipo que podría incrimanarles, pero antes se encontraran con Killer Croc.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565986613-klccy4.jpg','read',0,NULL,NULL,'2026-04-07 12:46:27','2026-04-07 17:38:50',68,NULL,'rustica','[{"name":"Gail Simone","role":"Guion"},{"name":"Derlis Santacruz","role":"Dibujo"},{"name":"Karl Kerschl","role":"Tinta"},{"name":"Brett Smith","role":"Color"},{"name":"Frank Tieri","role":"Guion"},{"name":"Christian Duce","role":"Dibujo, Tinta"},{"name":"Andrew Dalhouse","role":"Color"},{"name":"Peter J. Tomasi","role":"Guion"},{"name":"Graham Nolan","role":"Dibujo, Tinta"},{"name":"John Kalisz","role":"Color"},{"name":"Tim Seeley","role":"Guion"},{"name":"Francis Portela","role":"Dibujo, Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(366,'Batman: Maldad Eterna #4','Batman: Maldad Eterna',4,NULL,'978-8-416-15205-6',NULL,'Justin Gray','Jason Masters',NULL,NULL,'ECC Ediciones',NULL,'2014-05-30',NULL,NULL,replace(replace('CONTENIDO USA: Batman - The Dark Knight Vol. 2 #23.2 y #23.4 USA, Batman and Robin Vol. 2 #23.3 y Detective Comics Vol. 2 #23.2  \r\nHISTORIAS: Historia sin titular / La carne y los huesos / La torre del demonio / Harley vive\r\nARGUMENTO: Los antagonistas del Caballero Oscuro han reaccionado de formas muy distintas al nuevo orden mundial instaurado por la Sociedad Secreta y el Sindicato del Crimen. En los anteriores tomos, Dos Caras o Killer Croc rechazaban unirse al poder establecido, Hiedra Venenosa o el Acertijo parecían más interesados, Clayface se veía repudiado y otros, como la Ventrílocua o Manbat, perseguían sus propios fines. Ahora veremos cómo afecta la situación a Mr. Frío, la Hija del Joker, Ra’s al Ghul y Harley Quinn.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775565988579-4i0fha.jpg','read',0,NULL,NULL,'2026-04-07 12:46:29','2026-04-07 17:38:50',68,NULL,'rustica','[{"name":"Justin Gray","role":"Guion"},{"name":"Jimmy Palmiotti","role":"Guion"},{"name":"Jason Masters","role":"Dibujo, Tinta"},{"name":"Dave McCaig","role":"Color"},{"name":"Ann Nocenti","role":"Guion"},{"name":"Georges Jeanty","role":"Dibujo"},{"name":"Dexter Vines","role":"Tinta"},{"name":"Michelle Madsen","role":"Color"},{"name":"James Tynion IV","role":"Guion"},{"name":"Jeremy Haun","role":"Dibujo, Tinta"},{"name":"John Rauch","role":"Color"},{"name":"Matt Kindt","role":"Guion"},{"name":"Neil Googe","role":"Dibujo, Tinta"},{"name":"Will Quintana","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(367,'Superman: Maldad Eterna #1','Superman: Maldad Eterna',1,NULL,'978-8-416-07044-2',NULL,'Michael Alan Nelson','Mike Hawthorne',NULL,NULL,'ECC Ediciones',NULL,'2014-03-31',NULL,NULL,replace(replace('CONTENIDO USA: Action Comics Vol. 2 #23.1 y 23.3, Superman Vol. 3 #23.1 y 23.3\r\nHISTORIAS:¡Arriba, Arriba y a Volar! / Desarrollo detenido / Nacido entre llamas / Ida y vuelta al infierno.\r\nARGUMENTO: El magnate y científico Lex Luthor empezó a destacar cuando fue asesor del ejército de Estados Unidos; pero las fechorías que cometió hace unos años, motivadas por su obsesión con Superman, lo llevaron a cumplir una larga condena en una cárcel inexpugnable que él mismo había diseñado. Por su parte, el Hombre de Acero y su prima Supergirl recibieron no hace mucho la visita de H’El, otro kryptoniano que había sido pupilo de Jor-El y que intentó resucitar su planeta natal a costa de la Tierra y todo el sistema solar. También veremos el nacimiento del proyecto Bizarro y el origen del Superman Ciborg.','\r',char(13)),'\n',char(10)),NULL,NULL,96,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566014515-rizx6d.jpg','read',0,NULL,NULL,'2026-04-07 12:46:58','2026-04-07 17:38:33',69,NULL,'Rústica','[{"name":"Michael Alan Nelson","role":"Guion"},{"name":"Mike Hawthorne","role":"Dibujo, Tinta"},{"name":"Daniel Brown","role":"Color"},{"name":"Charles Soule","role":"Guion"},{"name":"Raymund Bermudez","role":"Dibujo"},{"name":"Dan Green","role":"Tinta"},{"name":"Ulises Arreola","role":"Color"},{"name":"Sholly Fisch","role":"Guion"},{"name":"Jeff Johnson","role":"Dibujo"},{"name":"Andy Smith","role":"Tinta"},{"name":"Javier Mena","role":"Color"},{"name":"Jordie Bellaire","role":"Color"},{"name":"Scott Lobdell","role":"Guion"},{"name":"Dan Jurgens","role":"Dibujo"},{"name":"Ray McCarthy","role":"Tinta"},{"name":"Hi-Fi Desing","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(368,'Superman: Maldad Eterna #2','Superman: Maldad Eterna',2,NULL,'978-8-416-07078-7',NULL,'Greg Pak','Aaron Kuder',NULL,NULL,'ECC Ediciones',NULL,'2014-04-30',NULL,NULL,replace(replace('CONTENIDO USA: Action Comics Vol. 2 #23.2 y #23.4, Superman Vol. 3 #23.2 y #23.4 \r\nHISTORIAS: Historia no titulada / Recolección / La chaqueta metálica / Historia no titulada\r\nARGUMENTO: Al principio de su carrera, Superman era un proscrito buscado por el ejército de Estados Unidos y la policía de Metropolis. No obstante, todo cambió cuando salvó la ciudad del alienígena Brainiac, el Coleccionista de Mundos, y se convirtió en el superhéroe respetado y querido que sigue siendo en la actualidad. Aquel primer encuentro con Brainiac también supuso el debut de Metalo, un soldado a las órdenes del General Sam Lane, padre de la periodista Lois Lane y uno de los principales detractores del Hombre de Acero. En este volumen tambien repasaremos los origenes de otros dos temibles enemigos de Superman: Parásito y el general Zod.','\r',char(13)),'\n',char(10)),NULL,NULL,96,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566026232-fule35.jpg','read',0,NULL,NULL,'2026-04-07 12:47:06','2026-04-07 17:38:33',69,NULL,'Rústica','[{"name":"Greg Pak","role":"Guion"},{"name":"Aaron Kuder","role":"Guion, Dibujo, Tinta"},{"name":"Sholly Fisch","role":"Guion"},{"name":"Ken Lashley","role":"Dibujo, Tinta"},{"name":"Pascal Alixe","role":"Dibujo, Tinta"},{"name":"Steve Pugh","role":"Dibujo, Tinta"},{"name":"Peter Pantazis","role":"Color"},{"name":"Bárbara Ciardo","role":"Color"},{"name":"David Curiel","role":"Color"},{"name":"Tony Bedard","role":"Guion"},{"name":"Hi-Fi Desing","role":"Color"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(369,'Liga de la Justicia: Maldad Eterna #1','Liga de la Justicia: Maldad Eterna',1,NULL,'974-8-416-07014-5',NULL,'Geoff Johns','Claude St. Aubin',NULL,NULL,'ECC Ediciones',NULL,'2014-02-28',NULL,NULL,replace(replace('Contenido USA: Aquaman Vol. 7 #23.1 y 23.2 USA, Justice League Dark # 23.1 USA y The Flash #23.3\r\nHistorias: Mar variable / Pescadito / Retorcido / Todos para uno\r\nArgumento: Entre los candidatos a miembros de la Sociedad Secreta se encuentran Manta Negra y el Señor del Océano, dos enemigos de Aquaman que están actualmente encerrados en Belle Rêve. También veremos como los sucesos de maldad eterna afectan a la entidad demoníaca conocida como Creeper.','\r',char(13)),'\n',char(10)),NULL,NULL,96,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566074447-sq38l3.jpg','read',0,NULL,NULL,'2026-04-07 12:47:57','2026-04-07 17:38:33',70,26.99,'Rústica','[{"name":"Geoff Johns","role":"Guion"},{"name":"Tony Bedard","role":"Guion"},{"name":"Ann Nocenti","role":"Guion"},{"name":"Dan Didio","role":"Guion"},{"name":"Brian Buccellato","role":"Guion"},{"name":"Claude St. Aubin","role":"Dibujo, Tinta"},{"name":"Geraldo Borges","role":"Dibujo"},{"name":"Fabrizio Fiorentino","role":"Dibujo"},{"name":"Tom Derenick","role":"Dibujo, Tinta"},{"name":"Chris Cross","role":"Dibujo"},{"name":"Chris Batista","role":"Dibujo"},{"name":"Blond","role":"Color"},{"name":"Ruy Jose","role":"Tinta"},{"name":"Rod Reis","role":"Color"},{"name":"Wayne Faucher","role":"Tinta"},{"name":"Andy Owens","role":"Tinta"},{"name":"Ulises Arreola","role":"Color"},{"name":"Kyle Ritter","role":"Color"},{"name":"