INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(371,'Liga de la Justicia: Maldad Eterna #3','Liga de la Justicia: Maldad Eterna',3,NULL,'978-8-416-07089-3',NULL,'Marguerite Bennett','Ben Oliver',NULL,NULL,'ECC Ediciones',NULL,'2014-05-02',NULL,NULL,replace(replace('Contenido USA: Justice League Vol. 2 #23.2, Justice League of America Vol. 3 #7.2 y 7.3, Wonder Woman Vol. 4 #23.1 USA\r\nHistorias: El último choque / Muerte por congelación / Circulos de engaño / La cacería\r\nArgumento: El Sindicato del Crimen ha derrotado a las tres Ligas de las Justicia, y la mayoría de sus miembros se encuentran en paradero desconocido. Uno de los principales afectados es Firestorm, el Hombre Nuclear, un héroe que, a pesar de su juventud, ya se ha ganado muchos enemigos. Otra víctima del Sindicato ha sido Hawkman, que se enfrentó hace poco a una misteriosa adversaria llamada Ladrona-Sombra. Por su parte, una antigua amiga de Wonder Woman es hoy una de sus peores enemigas, la perversa Cheetah.','\r',char(13)),'\n',char(10)),NULL,NULL,96,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566083561-gb87gs.jpg','read',0,NULL,NULL,'2026-04-07 12:48:04','2026-04-07 17:38:33',70,NULL,'Rústica','[{"name":"Marguerite Bennett","role":"Guion"},{"name":"Ben Oliver","role":"Dibujo"},{"name":"Cliff Richards","role":"Tinta"},{"name":"Daniel Brown","role":"Color"},{"name":"Sterling Gates","role":"Guion"},{"name":"Derlis Santacruz","role":"Dibujo, Tinta"},{"name":"Brett Smith","role":"Color"},{"name":"Tom DeFalco","role":"Guion"},{"name":"Chad Hardin","role":"Dibujo, Tinta"},{"name":"Chris Sotomayor","role":"Color"},{"name":"John Ostrander","role":"Guion"},{"name":"Victor Ibañez","role":"Dibujo, Tinta"},{"name":"Will Quintana","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(372,'La oscuridad: Año Cero','La oscuridad: Año Cero',NULL,NULL,'978-8-415-84411-2',NULL,'Jeff Lemire','Steve Pugh',NULL,NULL,'ECC Ediciones',NULL,'2013-04-01',NULL,NULL,replace(replace('CONTENIDO USA: Justice League Dark Vol. 1 (2011-2015) #0, Animal Man Vol. 2 (2011-2014) #0, Frankenstein Agent of Shade Vol 1 (2011-2013) #0, I, Vampire Vol. 1 (2011-2013) #0, Demon Knights Vol 1 (2011-2013) #0 y DC Universe Presents Vol. 1 (2011-2013) #0.\r\nARGUMENTO: ¿Quieres asomarte a la cara más oscura del Nuevo Universo DC? No tengas miedo: aquí encontrarás vampiros de los que aún provocan terror, demonios recién sacados del infierno y monstruos traídos de épocas pasadas; pero también héroes capaces de imitar los dones de los animales y magos socarrones dispuestos a proteger el mundo de lo inmaterial. El Universo DC ha cambiado, mostrando rostros que antes permanecían velados y revelando secretos hasta ahora ocultos. La puerta está abierta: ¿te atreves a cruzarla?\r\nHISTORIAS: Jóvenes cabrones / Nacimiento rojo / Conociendo al creador / Hazme ceder / Karma instantáneo / El prólogo','\r',char(13)),'\n',char(10)),NULL,NULL,128,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566129064-cr6wlw.jpg','read',0,NULL,NULL,'2026-04-07 12:48:51','2026-04-07 17:38:33',NULL,NULL,'Rústica','[{"name":"Jeff Lemire","role":"Guion"},{"name":"Matt Kindt","role":"Guion"},{"name":"Joshua Fialkov","role":"Guion"},{"name":"Tony Bedard","role":"Guion"},{"name":"Paul Cornell","role":"Guion"},{"name":"Steve Pugh","role":"Dibujo, Tinta"},{"name":"Lee Garbett","role":"Dibujo"},{"name":"Alberto Ponticelli","role":"Dibujo"},{"name":"Andrea Sorrentino","role":"Dibujo, Tinta"},{"name":"Scott McDaniel","role":"Dibujo, Tinta"},{"name":"Bernard Chang","role":"Dibujo, Tinta"},{"name":"Guy Major","role":"Color"},{"name":"Marcelo Maiolo","role":"Color"},{"name":"Wayne Faucher","role":"Tinta"},{"name":"José Villarrubia","role":"Color"},{"name":"Lovern Kindzierski","role":"Color"},{"name":"Cam Smith","role":"Tinta"},{"name":"Jack Purcell","role":"Tinta"},{"name":"Scott Hanna","role":"Tinta"},{"name":"Walden Wong","role":"Tinta"},{"name":"Peter Pantazis","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(373,'Superman: Año Cero','Superman: Año Cero',NULL,NULL,'978-8-415-84403-7',NULL,'Grant Morrison','Scott Lobdell',NULL,NULL,'ECC Ediciones',NULL,'2013-04-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Action Comics 0, Superman 0, Superboy 0, Supergirl 0, Action comics annual 01 USA\r\n¿Qué ocurrió en los instantes finales de Krypton, antes de que Zor-El enviara a Kara a la Tierra para salvarle la vida? ¿Cómo actuaría el Superman de hace unos cuantos años –cuando aún era un rudo defensor de los oprimidos– ante un caso de maltrato infantil? ¿Y qué amenazas reserva el futuro al Hombre de Acero y a todo su entorno? Todas estas preguntas y muchas más se responden en este volumen especial que contiene información complementaria a lo que hemos visto hasta ahora y un adelanto de lo que está por venir. Y además, conoceremos el origen y la historia de Superboy en este nuevo universo. ¡Descúbrelo todo en Superman: Año cero!','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566144000-ib8skz.jpg','read',0,NULL,NULL,'2026-04-07 12:49:05','2026-04-07 17:38:33',NULL,NULL,'Rústica','[{"name":"Grant Morrison","role":""},{"name":"Scott Lobdell","role":""},{"name":"Sholly Fisch","role":""},{"name":"Tom DeFalco","role":""},{"name":"Ben Oliver","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(374,'Batman. Año Cero','Batman. Año Cero',NULL,NULL,'978-8-415-84401-3',NULL,'Gregg Hurwitz','Greg Capullo',NULL,NULL,'ECC Ediciones',NULL,'2013-04-01',NULL,NULL,replace(replace('CONTENIDO USA: Batman Vol. 2 #9-11 (historias de complemento), Batman Vol. 2 #0, Detective Comics Vol. 2 #0, Batman: The dark knight Vol. 2 #0\r\nEl Caballero Oscuro, el Cruzado de la Capa, el Hombre Murciélago... diferentes apodos que designan al protector de Gotham City, referente de toda una generación de héroes. Pero ¿cuál fue el origen de Batman? ¿Qué razones le movieron a emprender su cruzada contra el crimen? ¿Cómo adquirió sus extraordinarias habilidades? Batman: Año cero responde a estas y otras preguntas, recopilando los llamados “números cero” de Batman, Detective Comics y Batman: El Caballero Oscuro para arrojar luz sobre el período iniciático del personaje. La forja de una leyenda, que ahora adquiere una nueva dimensión de la mano de autores como Scott Snyder, Greg Capullo, Gregg Hurwitz, Rafael Albuquerque o Tony Daniel, entre otros.','\r',char(13)),'\n',char(10)),NULL,NULL,112,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566164760-3x2zfv.jpg','read',0,NULL,NULL,'2026-04-07 12:49:27','2026-04-07 17:38:33',NULL,NULL,'Rústica','[{"name":"Gregg Hurwitz","role":"Guion"},{"name":"Scott Snyder","role":"Guion"},{"name":"James Tynion IV","role":"Guion"},{"name":"Greg Capullo","role":"Dibujo"},{"name":"Rafael Albuquerque","role":"Dibujo, Tinta"},{"name":"Tony S. Daniel","role":"Dibujo"},{"name":"Pere Pérez","role":"Dibujo, Tinta"},{"name":"Andy Clarke","role":"Dibujo, Tinta"},{"name":"Mico Suayan","role":"Dibujo, Tinta"},{"name":"Juan Jose Ryp","role":"Dibujo"},{"name":"Henrik Jonsson","role":"Dibujo"},{"name":"Dave McCaig","role":"Color"},{"name":"Jonathan Glapion","role":"Tinta"},{"name":"FCO Plascencia","role":"Color"},{"name":"Richard Friend","role":"Tinta"},{"name":"Sandu Florea","role":"Tinta"},{"name":"John Kalisz","role":"Color"},{"name":"Vicente Cifuentes","role":"Tinta"},{"name":"Sonia Oback","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(375,'Universo DC: Renacimiento','Universo DC: Renacimiento',NULL,NULL,'978-8-416-90146-3',NULL,'Geoff Johns','Gary Frank',NULL,NULL,'ECC Ediciones',NULL,'2016-10-27',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: DC Universe: Rebirth núm. 1 USA (one-shot)\r\nARGUMENTO: Un héroe muy apreciado, un símbolo por muchos motivos, se ha perdido en el tiempo y está desesperado por regresar. No obstante, su vuelta depende de los seres queridos y los aliados que se han olvidado de él y que, si no lo rescatan, nunca sabrán que hay un enemigo misterioso que ya les ha robado 10 años de historia.\r\nRenacimiento, la nueva etapa del Universo DC, comienza con este especial repleto de emociones y amor por unos personajes inmortales que cuenta con guion de Geoff Johns (Liga de la Justicia) y dibujo de Gary Frank (Batman: Tierra uno), Ethan Van Sciver (Green Lantern), Ivan Reis (Aquaman) y Phil Jiménez (Crisis infinita).','\r',char(13)),'\n',char(10)),NULL,NULL,80,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566217598-f0d14h.jpg','read',0,NULL,NULL,'2026-04-07 12:50:19','2026-04-07 17:38:33',NULL,7.5,'Rústica','[{"name":"Geoff Johns","role":"Guion"},{"name":"Gary Frank","role":"Dibujo, Tinta"},{"name":"Ethan Van Sciver","role":"Dibujo"},{"name":"Ivan Reis","role":"Dibujo, Tinta"},{"name":"Phil Jimenez","role":"Dibujo"},{"name":"Brad Anderson","role":"Color"},{"name":"Jason Wright","role":"Color"},{"name":"Joe Prado","role":"Tinta"},{"name":"Hi-Fi Desing","role":"Color"},{"name":"Matt Santorelli","role":"Tinta"},{"name":"Gabe Eltaeb","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(376,'Batman: La Noche de los Hombres Monstruo. Renacimiento','Batman: La Noche de los Hombres Monstruo. Renacimiento',NULL,NULL,'978-8-417-06353-5',NULL,'Steve Orlando','Riley Rossmo',NULL,NULL,'ECC Ediciones',NULL,'2017-03-28',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 7-8 USA, Nightwing núms. 5-6 USA, Detective Comics núms. 941-942 USA   \r\n¡Ya están aquí! En Gotham varias personas han coincidido en pronunciar una extraña frase antes de morir: “Se acercan los Hombres Monstruo”. Ahora esas temibles criaturas han llegado y Batman parece incapaz de vencerlas, pese a contar con aliados como Batwoman o Clayface. Pero... ¿quién está tras la colosal ofensiva? \r\nTom King (Grayson) y Riley Rossmo (Constantine: Hellblazer) se unen a muchos otros guionistas y dibujantes para relatar este épico enfrentamiento, publicado originalmente en las series americanas de Batman, Nightwing y Detective Comics. Batman: La noche de los Hombres Monstruo es el primer cruce entre títulos que edita DC tras Renacimiento, y ECC lo recopila íntegramente en este volumen.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566263328-4lam76.jpg','read',0,NULL,NULL,'2026-04-07 12:51:04','2026-04-07 17:38:33',NULL,13.5,'Rústica','[{"name":"Steve Orlando","role":"Guion"},{"name":"Tom King","role":"Guion"},{"name":"Riley Rossmo","role":"Dibujo, Tinta"},{"name":"Ivan Plascencia","role":"Color"},{"name":"Tim Seeley","role":"Guion"},{"name":"Roge Antonio","role":"Dibujo, Tinta"},{"name":"Chris Sotomayor","role":"Color"},{"name":"James Tynion IV","role":"Guion"},{"name":"Andy Macdonald","role":"Dibujo, Tinta"},{"name":"John Rauch","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(377,'Animal Man. Nuevo Universo DC #1','Animal Man. Nuevo Universo DC',1,NULL,'978-8-415-52077-1',NULL,'Jeff Lemire','Travel Foreman',NULL,NULL,'ECC Ediciones',NULL,'2012-05-01',NULL,NULL,replace(replace('CONTENIDO USA: Animal man Vol. 2 (2011-2014) #1-6\r\nHISTORIAS: La Cacería, Parte 1: La Advertencia del Rojo / La Cacería, Parte 2: Mapas / La Cacería, Parte 3: Totems / La Cacería, Parte 4: La Putrefacción / La Cacería, Conclusión: La Cadena Alimentaria / Mallas\r\nARGUMENTO: Buddy Baker, actualmente un superhéroe retirado que vive feliz junto a su esposa e hijos, retoma a veces de forma esporádica sus hazañas, pero lleva en general una existencia cotidiana... que se verá truncada por la irrupción de inesperados enemigos dispuestos a darle caza hasta las últimas consecuencias, por el regreso de la fuerza de la naturaleza llamada “el Rojo”, que también parece estar en peligro, y por el inesperado papel de Maxine, su propia hija, en los terribles acontecimientos que se desencadenan.','\r',char(13)),'\n',char(10)),NULL,NULL,184,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566289816-f4ae9e.jpg','read',0,NULL,NULL,'2026-04-07 12:51:33','2026-04-07 17:38:33',71,23.95,'Rústica','[{"name":"Jeff Lemire","role":"Guion"},{"name":"Travel Foreman","role":"Dibujo, Tinta"},{"name":"Dan Green","role":"Dibujo, Tinta"},{"name":"Lovern Kindzierski","role":"Color"},{"name":"Jeff Huet","role":"Tinta"},{"name":"Steve Pugh","role":"Dibujo, Tinta"},{"name":"John Paul Leon","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(378,'Animal Man. Nuevo Universo DC #2','Animal Man. Nuevo Universo DC',2,NULL,'978-8-415-74808-3',NULL,'Jeff Lemire','Travel Foreman',NULL,NULL,'ECC Ediciones',NULL,'2012-11-01',NULL,NULL,replace(replace('CONTENIDO USA: Animal Man Vol. 2  (2011-2014) #7-11 USA y Animal Man Vol. 2 annual #1 y Frankenstein agent of S.H.A.D.E. Vol. 1 #9\r\nHISTORIAS: Animal contra Hombre, Partes 1-2 / La Extinción Es para Siempre, Parte 1: El Jardín de Huesos / Putrefacción sin Fin / Huellas de Animales / La Extinción Es para Siempre, Parte 2: Los Guerreros de las Tierras Rojas / La Extinción Es para Siempre, Conclusión: Animal Man contra Animal Man  \r\nARGUMENTO: Buddy Baker compagina su sencilla vida familiar con trabajos esporádicos como Animal Man. Pero su mundo se ve trastocado cuando él y su hija Maxine son súbitamente convocados ante el Rojo: la red vital que conecta a todos los seres de carne y sangre. Allí se le desvela que hay una guerra en marcha y que su hija es el avatar del Rojo, la líder llamada a derrotar a la Putrefacción. Como protector del avatar, Buddy debe poner a su hija a salvo y contactar con el avatar del Verde: la Cosa del Pantano.','\r',char(13)),'\n',char(10)),NULL,NULL,184,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566297017-q5lkq3.jpg','read',0,NULL,NULL,'2026-04-07 12:51:38','2026-04-07 17:38:33',71,NULL,'Rústica','[{"name":"Jeff Lemire","role":"Guion"},{"name":"Travel Foreman","role":"Dibujo"},{"name":"Steve Pugh","role":"Dibujo, Tinta"},{"name":"Alberto Ponticelli","role":"Dibujo"},{"name":"Jeff Huet","role":"Tinta"},{"name":"Lovern Kindzierski","role":"Color"},{"name":"Wayne Faucher","role":"Tinta"},{"name":"Timothy Green II","role":"Dibujo"},{"name":"Joseph Silver","role":"Tinta"},{"name":"José Villarrubia","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(379,'Animal Man. Nuevo Universo DC #3','Animal Man. Nuevo Universo DC',3,NULL,'978-8-416-07013-8',NULL,'Jeff Lemire','Steve Pugh',NULL,NULL,'ECC Ediciones',NULL,'2014-02-27',NULL,NULL,replace(replace('CONTENIDO USA:: Animal Man Vol. 2 (2011-2014) #19- 22 USA y Animal Man Vol. 2 annual #2\r\nHISTORIAS: El funeral / Mallas. Parte 2 / El último vuelo / Especie disidente Partes 1 y 2\r\nARGUMENTO: La victoria sobre las fuerzas de la Putrefacción restauró el equilibrio en la Tierra, pero se cobró un alto precio con los sevidores del Rojo y del Verde. La vida de Buddy Baker se desmorona en todos sus aspectos, mientras una nueva amenaza contra el rojo conspira en la sombra para hacerse con el dominio de la vida.','\r',char(13)),'\n',char(10)),NULL,NULL,184,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566299589-x8b1j5.jpg','read',0,NULL,NULL,'2026-04-07 12:51:40','2026-04-07 17:38:33',71,NULL,'Rústica','[{"name":"Jeff Lemire","role":"Guion"},{"name":"Steve Pugh","role":"Dibujo, Tinta"},{"name":"Lovern Kindzierski","role":"Color"},{"name":"Timothy Green II","role":"Dibujo"},{"name":"John Paul Leon","role":"Dibujo, Tinta"},{"name":"Joseph Silver","role":"Tinta"},{"name":"Francis Portela","role":"Dibujo, Tinta"},{"name":"Travel Foreman","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(380,'Animal Man. Nuevo Universo DC #4','Animal Man. Nuevo Universo DC',4,NULL,'978-8-416-19494-0',NULL,'Jeff Lemire','Jeff Lemire',NULL,NULL,'ECC Ediciones',NULL,'2014-10-01',NULL,NULL,replace(replace('CONTENIDO USA: Animal Man Vol.2 (2011-2014) #23 a 29\r\nHISTORIAS: Especie Disidente, Conclusión / Hollywood Babilonia Partes 1 y 2 / La semilla divina / ¡Evoluciona o muere! Partes 1 y 2 / Buenas noches, Animal man\r\nARGUMENTO: Siguiendo la pista a un gatito, Animal Man cae en manos de los Disidentes, unos fanáticos que se injertan miembros de animales para entrar en comunión con la naturaleza. Lo peor es que tras estos lunáticos se oculta la mano del Hermano Sangre, un villano siniestro y manipulador que tiene un plan para adueñarse del Rojo. Este tomo finaliza el volumen 2 USA de Animal man.','\r',char(13)),'\n',char(10)),NULL,NULL,184,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566301776-t2hgxq.jpg','read',0,NULL,NULL,'2026-04-07 12:51:43','2026-04-07 17:38:33',71,NULL,'Rústica','[{"name":"Jeff Lemire","role":"Guion, Dibujo, Tinta"},{"name":"Cully Hamner","role":"Dibujo, Tinta"},{"name":"Francis Portela","role":"Dibujo, Tinta"},{"name":"Rafael Albuquerque","role":"Dibujo, Tinta"},{"name":"Steve Pugh","role":"Dibujo, Tinta"},{"name":"Travel Foreman","role":"Dibujo"},{"name":"Lovern Kindzierski","role":"Color"},{"name":"Dave McCaig","role":"Color"},{"name":"John Kalisz","role":"Color"},{"name":"José Villarrubia","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(381,'La Cosa del Pantano. Nuevo Universo DC #1','La Cosa del Pantano. Nuevo Universo DC',1,NULL,'978-8-415-62818-7',NULL,'Scott Snyder','Marco Rudy',NULL,NULL,'ECC Ediciones',NULL,'2012-07-01',NULL,NULL,replace(replace('CONTENIDO USA: Swamp Thing Vol. 5 #1-4\r\nHISTORIAS: Se alzan los huesos / Cuando llaman a tu puerta / Acércate a mi, pequeño / Flores del desierto\r\nARGUMENTO: ¿Hasta donde llegarías para salvar el mundo? ¿Matarías? ¿Renunciarías al amor de tu vida? ¿Te transformarías en un monstruo? Alec Holland está destinado a todo ello, pero no parece dispuesto a asumir su sino. Ya murió una vez hace años. Entonces fue relevado como defensor del Verde por una planta que creía ser un hombre. No es de extrañar: el engendro estaba infectado por la conciencia del humano. Ahora, un recién resucitado Alec Holland se debate entre sus ansias de vivir y la aceptación de su destino final. Es una elección muy complicada. Si se convierte en la Cosa del Pantano, renunciará a su humanidad. Si no lo hace, morirá junto al resto del universo.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566369443-p6zrql.jpg','read',0,NULL,NULL,'2026-04-07 12:52:14','2026-04-07 17:38:33',72,NULL,'rustica','[{"name":"Scott Snyder","role":"Guion"},{"name":"Marco Rudy","role":"Dibujo, Tinta"},{"name":"Victor Ibañez","role":"Dibujo, Tinta"},{"name":"Yanick Paquette","role":"Dibujo, Tinta"},{"name":"Nathan Fairbairn","role":"Color"},{"name":"Sean Parsons","role":"Tinta"},{"name":"Michel Lacombe","role":"Tinta"},{"name":"David Baron","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(382,'La Cosa del Pantano. Nuevo Universo DC #2','La Cosa del Pantano. Nuevo Universo DC',2,NULL,'978-8-415-62890-3',NULL,'Scott Snyder','Marco Rudy',NULL,NULL,'ECC Ediciones',NULL,'2012-11-01',NULL,NULL,replace(replace('CONTENIDO USA: Swampt thing Vol. 5 #5-8\r\nHISTORIAS: Carne muerta / La Reina Negra / La Cosa del Pantano / El ojo del huracán\r\nARGUMENTO: Se oyen tambores de guerra. La Putrefacción prepara una cruenta batalla contra el Verde y la única esperanza de salvación reside en que Alec Holland se convierta en la Cosa del Pantano. Desgraciadamente, el antiguo científico no está dispuesto a sacrificar su vida por nadie. Aunque quizá todo cambie ahora que ha entrado en juego Abigail Arcane, una extraña mujer por la que Holland siente algo más que deseo. No en vano ha sido la única que ha conseguido movilizar a Alec.\r\nContiene Swamp Thing #5-#8 USA','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566344457-izpxl8.jpg','read',0,NULL,NULL,'2026-04-07 12:52:25','2026-04-07 17:38:33',72,NULL,'rustica','[{"name":"Scott Snyder","role":"Guion"},{"name":"Marco Rudy","role":"Dibujo, Tinta"},{"name":"Yanick Paquette","role":"Dibujo, Tinta"},{"name":"Nathan Fairbairn","role":"Color"},{"name":"Val Staples","role":"Color"},{"name":"Lee Loughridge","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(383,'La Cosa del Pantano. Nuevo Universo DC #3','La Cosa del Pantano. Nuevo Universo DC',3,NULL,'978-8-415-74885-4',NULL,'Scott Snyder','Francesco Francavilla',NULL,NULL,'ECC Ediciones',NULL,'2013-03-01',NULL,NULL,replace(replace('CONTENIDO USA: Swamp thing vol 5 #9-11, #0\r\nHISTORIAS: Huesos rotos/ La nana de Arcane / Reunión familiar / Por los monstruos\r\nARGUMENTO: Alec Holland ha renunciado a su humanidad para salvar al mundo. Ahora es La Cosa del Pantano, el campeón de El Verde. Está dispuesto a todo para desbaratar los planes de La Putrefacción y, de paso, salvar a su amada; pero parece que ha llegado tarde. Abigail Arcane se ha convertido en un avatar de su enemigo y no dudará en arrancar la cabeza de su enamorado. Lo que sigue es una épica batalla entre dos antiguos amantes, una historia que hace que el final de Romeo y Julieta parezca feliz.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566347063-t3z2cr.jpg','read',0,NULL,NULL,'2026-04-07 12:52:27','2026-04-07 17:38:33',72,NULL,'rustica','[{"name":"Scott Snyder","role":"Guion"},{"name":"Francesco Francavilla","role":"Dibujo, Tinta, Color"},{"name":"Marco Rudy","role":"Dibujo, Tinta"},{"name":"Yanick Paquette","role":"Dibujo, Tinta"},{"name":"Nathan Fairbairn","role":"Color"},{"name":"Val Staples","role":"Color"},{"name":"Kano","role":"Dibujo, Tinta"},{"name":"Matthew Wilson","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(384,'La Cosa del Pantano. Nuevo Universo DC #4','La Cosa del Pantano. Nuevo Universo DC',4,NULL,'978-8-415-99019-2',NULL,'Charles Soule','Jesus Saiz',NULL,NULL,'ECC Ediciones',NULL,'2013-12-01',NULL,NULL,replace(replace('CONTENIDO USA: Swamp Thing Vol. 5 #19-22\r\nHISTORIAS: Jungla urbana / Este infierno verde / El poeta asesino / El Árbol del Whisky, Parte 1 de 2\r\nARGUMENTO: Alec Holland intenta asimilar los cambios que ha traído a su vida la batalla contra la Putrefacción mientras se enfrenta a un misterioso hombre llamado el Sembrador, capaz de manipular el Verde de forma antinatural. La última locura de ese misterioso enemigo ha consistido en regalar a un pueblo un árbol cuyo fruto es un whisky que altera a quien lo bebe. Y Constantine ha tomado más de un sorbo...','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566348979-5tzwvs.jpg','read',0,NULL,NULL,'2026-04-07 12:52:29','2026-04-07 17:38:33',72,NULL,'rustica','[{"name":"Charles Soule","role":"Guion"},{"name":"Jesus Saiz","role":"Dibujo, Tinta"},{"name":"Kano","role":"Dibujo, Tinta"},{"name":"Matthew Wilson","role":"Color"},{"name":"Álvaro López","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(385,'La Cosa del Pantano. Nuevo Universo DC #5','La Cosa del Pantano. Nuevo Universo DC',5,NULL,'978-8-416-07052-7',NULL,'Charles Soule','Kano',NULL,NULL,'ECC Ediciones',NULL,'2014-03-31',NULL,NULL,replace(replace('CONTENIDO USA: Swamp Thing Vol. 5 #23, #23.1 y #24 Swamp Thing Vol. 5 Annual #2.\r\nHISTORIAS: El Árbol del Whisky, Parte 2 de 2 / Una historia de retales / El sembrador / Lección aprendida.\r\nARGUMENTO: Tras poner fin a los desmanes provocados por el arbol del Whiskey, La Cosa del Pantano se enfrenta cara a cara con el Sembrador, pero la auténtica identidad de su enemigo y sus motiviaciones van más allá de lo que Holland esperaba.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566350950-tvrbct.jpg','read',0,NULL,NULL,'2026-04-07 12:52:31','2026-04-07 17:38:33',72,NULL,'rustica','[{"name":"Charles Soule","role":"Guion"},{"name":"Kano","role":"Dibujo, Tinta, Color"},{"name":"Jesus Saiz","role":"Dibujo, Tinta"},{"name":"David Lapham","role":"Dibujo, Tinta"},{"name":"Andrei Bressan","role":"Dibujo, Tinta"},{"name":"Javier Pina","role":"Dibujo"},{"name":"Álvaro López","role":"Tinta"},{"name":"Matthew Wilson","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(386,'La Cosa del Pantano. Nuevo Universo DC #6','La Cosa del Pantano. Nuevo Universo DC',6,NULL,'978-8-416-19405-6',NULL,'Charles Soule','Javier Pina',NULL,NULL,'ECC Ediciones',NULL,'2014-07-30',NULL,NULL,replace(replace('COTENIDO USA: Swamp Thing Vol. 5 #25-28 \r\nHISTORIAS: Entran Dos... ¡Pero Sale Uno! / El botín del vencedor / Mi cielo verde / Salando la tierra\r\nEl misterioso enemigo que ha puesto patas arriba el mundo de la Cosa del Pantano ha resultado ser Jason Woodrue, un hombre que en otra realidad era conocido como el Hombre Florónico, pero que en el Nuevo Universo DC ha tomado la identidad de Sembrador. Tras un difícil combate, Alec Holland pidió al Parlamento de Árboles que despojaran a Woodrue de toda conexión con el Verde. Sin embargo, estos han decidido hacer todo lo contrario. Van a permitir que Woodrue luche por convertirse en su nuevo campeón.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566353157-wl653n.jpg','read',0,NULL,NULL,'2026-04-07 12:52:34','2026-04-07 17:38:33',72,NULL,'rustica','[{"name":"Charles Soule","role":"Guion"},{"name":"Javier Pina","role":"Dibujo, Tinta"},{"name":"Jesus Saiz","role":"Dibujo, Tinta"},{"name":"Matthew Wilson","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(387,'La Cosa del Pantano. Nuevo Universo DC #7','La Cosa del Pantano. Nuevo Universo DC',7,NULL,'978-8-416-25563-4',NULL,'Charles Soule','Jesus Saiz',NULL,NULL,'ECC Ediciones',NULL,'2014-11-29',NULL,NULL,replace(replace('CONTENIDO USA:  Swamp Thing Vol. 5 #29-32\r\nHISTORIAS:El Don de los Sureen, Capítulos 1 a 3 / Azul - Verde\r\nEl Parlamento de Árboles ha utilizado a Alec Holland como si fuera una marioneta. Incluso ha llegado a obligarlo a luchar por su puesto de avatar contra Jason Woodrue. Holland, harto de esta situación, ha tomado una drástica e inesperada decisión: ha eliminado al Parlamento. Ahora, Alec ha vuelto a la Tierra acompañado de tres antiguos miembros de este pero con formas humanas solo para descubrir que tiene... ¡seguidores que lo idolatran y que están dispuestos a hacer cualquier cosa por él!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566355928-zmlkfv.jpg','read',0,NULL,NULL,'2026-04-07 12:52:36','2026-04-07 17:38:33',72,NULL,'rustica','[{"name":"Charles Soule","role":"Guion"},{"name":"Javier Pina","role":"Tinta"},{"name":"Jesus Saiz","role":"Dibujo, Tinta"},{"name":"Matthew Wilson","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(388,'La Cosa del Pantano. Nuevo Universo DC #8','La Cosa del Pantano. Nuevo Universo DC',8,NULL,'978-8-416-37445-8',NULL,'Charles Soule','Dave Bullock',NULL,NULL,'ECC Ediciones',NULL,'2015-03-25',NULL,NULL,replace(replace('CONTENIDO USA: Swamp Thing Vol. 5 #33-35, Swamp Thing: Futures End #1 y Swamp Thing Vol. 5 annual 3 \r\nHISTORIAS: El Lobo y la Dama, Capítulos 1-2 / El Zeugma / Todos los Relatos Tienen un Final, Amigo mío / Configuración\r\nARGUMENTO: Las maquinaciones de Lobo y Dama Maleza concluyen de una forma inesperada para ambos, también concluye la historia de Capucine con un inusual enfrentamiento con el demonio rimador Etrigan. Asimismo, asistiremos al nacimiento de un nuevo reino que traerá una nueva guerra: El Ritmo, el mundo de las máquinas.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566358310-7axtpw.jpg','read',0,NULL,NULL,'2026-04-07 12:52:39','2026-04-07 17:38:33',72,NULL,'rustica','[{"name":"Charles Soule","role":"Guion"},{"name":"Carmen Carnero","role":"Tinta"},{"name":"Dave Bullock","role":"Dibujo, Tinta"},{"name":"Javier Pina","role":"Dibujo, Tinta"},{"name":"Jesus Saiz","role":"Dibujo, Tinta"},{"name":"Ryan Browne","role":"Dibujo, Tinta"},{"name":"Yanick Paquette","role":"Dibujo, Tinta"},{"name":"Matthew Wilson","role":"Color"},{"name":"Matt Hollingsworth","role":"Color"},{"name":"José Villarrubia","role":"Color"},{"name":"Nathan Fairbairn","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(389,'La Cosa del Pantano. Nuevo Universo DC #9','La Cosa del Pantano. Nuevo Universo DC',9,NULL,'978-8-416-47521-6',NULL,'Charles Soule','Javier Pina',NULL,NULL,'ECC Ediciones',NULL,'2015-07-29',NULL,NULL,replace(replace('CONTENIDO USA: Swamp Thing Vol.5 #36-40 (Fín del volumen 5 USA)\r\nHISTORIAS: Calibración / Actualizaciones / Decompilación / Modos de fallo / Reinicio\r\nNos despedimos de esta serie, con el guionista Charles Soule orquestando un desenlace para la batalla entre el Reino Verde y el Reino de las Máquinas que seguro os sorprenderá. Si queréis saber qué destino correrá este atípico héroe, ¡que no se os escape este tomo!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566360759-kwwit5.jpg','read',0,NULL,NULL,'2026-04-07 12:52:41','2026-04-07 17:38:33',72,NULL,'rustica','[{"name":"Charles Soule","role":"Guion"},{"name":"Javier Pina","role":"Dibujo, Tinta"},{"name":"Jesus Saiz","role":"Dibujo, Tinta"},{"name":"Matt Hollingsworth","role":"Color"},{"name":"June Chung","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(390,'Mundo Putrefacto #1','Mundo Putrefacto',1,NULL,'978-8-415-84409-9',NULL,'Jeff Lemire','Becky Cloonan',NULL,NULL,'ECC Ediciones',NULL,'2013-04-01',NULL,NULL,replace(replace('CONTENIDO USA: Animal Man Vol. 2 #12, Swamp Thing Vol.5 #12-16 y Swamp thing Vol. 5 Annual #1\r\nHISTORIAS: Mundo Putrefacto: Prólogo, Parte 1 / Mundo Putrefacto: Prólogo, Parte 2 / Mundo Putrefacto: El Reino Verde, Parte 1 / Mundo Putrefacto: Secretos de los Muertos, Lo Oculto / Mundo Putrefacto: El Reino Verde, Parte 2 / Mundo Putrefacto: El Reino Verde, Parte 3 / Mundo Putrefacto: El Reino Verde, Parte 4\r\nARGUMENTO: La Putrefacción acecha y los campeones del Rojo y del Verde hacen lo que pueden para luchar contra ella. Alec Holland renunció a su humanidad y se convirtió en la Cosa del Pantano. Estuvo a punto de vencer al avatar de la Putrefacción, pero en el último instante se le escapó… Buddy Baker se enfrentó a su cuerpo poseído para salvar a su hijo, pero incluso después de vencer a su enemigo, su primogénito enfermó. Solo hay una manera de acabar con el mal: adentrarse en el Mundo Putrefacto…','\r',char(13)),'\n',char(10)),NULL,NULL,184,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566395481-jjexox.jpg','read',0,NULL,NULL,'2026-04-07 12:53:19','2026-04-07 17:38:33',73,24.95,'Rústica','[{"name":"Jeff Lemire","role":"Guion"},{"name":"Scott Snyder","role":"Guion"},{"name":"Becky Cloonan","role":"Dibujo, Tinta"},{"name":"Marco Rudy","role":"Dibujo, Tinta"},{"name":"Steve Pugh","role":"Dibujo, Tinta"},{"name":"Yanick Paquette","role":"Dibujo, Tinta"},{"name":"Lovern Kindzierski","role":"Color"},{"name":"Dan Green","role":"Tinta"},{"name":"Andy Owens","role":"Tinta"},{"name":"Val Staples","role":"Color"},{"name":"Nathan Fairbairn","role":"Color"},{"name":"Lee Loughridge","role":"Color"},{"name":"Scott Tuft","role":"Guion"},{"name":"Andrew Belanger","role":"Dibujo"},{"name":"Karl Kerschl","role":"Tinta"},{"name":"Tony Aviña","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(391,'Mundo Putrefacto #2','Mundo Putrefacto',2,NULL,'978-8-415-84467-9',NULL,'Matt Kindt','Alberto Ponticelli',NULL,NULL,'ECC Ediciones',NULL,'2013-06-01',NULL,NULL,replace(replace('CONTENIDO USA: Frankenstein, Agent of S.H.A.D.E. VOL. 1 #10-16 \r\nHISTORIAS: El Hijo del Anillo de Satanás, Parte 1: Derrota a la Poetisa / El Hijo del Anillo de Satanás, Parte 2: Leviatán / El Hijo del Anillo de Satanás, Parte 3: A la Tumba / Mundo Putrefacto: Los Secretos de los Muertos. El Botín de Victor  / Mundo Putrefacto: Los Secretos de los Muertos. ¿De Quién Son los Pasos que Oigo en el Puente? / El Rey Frankenstein / La bomba monstruosa\r\nARGUMENTO: Frankenstein no es el monstruo de Frankenstein sobre el que te hicieron leer en el instituto, ¿entendido, novato? Este trabaja para S.H.A.D.E., y en S.H.A.D.E. no nos gustan los lloricas: nos gustan los monstruos que hacen lo que hay que hacer para salvar el mundo, que permanecen unidos en el frente, que si es necesario hacen el sacrifi cio supremo ante el enemigo. Hasta ahora Frankenstein se ha enfrentado a criaturas de pesadilla, pero esta amenaza es distinta. La muerte viene hacia aquí, novato. Y de ella no se puede escapar.','\r',char(13)),'\n',char(10)),NULL,NULL,184,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566407520-i27dto.jpg','read',0,NULL,NULL,'2026-04-07 12:53:28','2026-04-07 17:38:33',73,NULL,'Rústica','[{"name":"Matt Kindt","role":"Guion"},{"name":"Alberto Ponticelli","role":"Dibujo"},{"name":"Wayne Faucher","role":"Tinta"},{"name":"José Villarrubia","role":"Color"},{"name":"John Kalisz","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(392,'Mundo Putrefacto #3','Mundo Putrefacto',3,NULL,'978-8-415-92514-9',NULL,'Jeff Lemire','Steve Pugh',NULL,NULL,'ECC Ediciones',NULL,'2013-06-01',NULL,NULL,replace(replace('CONTENIDO USA: Animal Man Vol. 2 #13-18 y Swamp Thing Vol.5 #17-18\r\nHISTORIAS: Mundo Putrefacto: El Reino Rojo, Partes 1 a 4 / Mundo Putrefacto: La Guerra de la Putrefacción, Partes 1 a 2 / El Reposar de los Huesos / Mundo Putrefacto: El Reino Rojo, Epílogo\r\nARGUMENTO: La guerra contra el Mundo Putrefacto se aproxima a su inevitable conclusión, y no parece que las fuerzas de la vida tengan ninguna posibilidad contra la muerte encarnada, contra esta inevitable última parte del ciclo de la vida. En el bando de la Putrefacción, caricaturas podridas de todos los héroes de la Tierra. En el bando del verde, un puñado de héroes inadaptados, ocultos, pero movidos por fervientes deseos. La Cosa del Pantano, Animal Man y Frankenstein intentarán lo imposible. ¿Qué precio habrán de pagar por triunfar?','\r',char(13)),'\n',char(10)),NULL,NULL,184,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566409603-yoj345.jpg','read',0,NULL,NULL,'2026-04-07 12:53:30','2026-04-07 17:38:33',73,NULL,'Rústica','[{"name":"Jeff Lemire","role":"Guion"},{"name":"Steve Pugh","role":"Dibujo, Tinta"},{"name":"Timothy Green II","role":"Dibujo, Tinta"},{"name":"Joseph Silver","role":"Tinta"},{"name":"Lovern Kindzierski","role":"Color"},{"name":"Scott Snyder","role":"Guion"},{"name":"Andrew Belanger","role":"Dibujo, Tinta"},{"name":"Tony Aviña","role":"Color"},{"name":"Yanick Paquette","role":"Dibujo, Tinta"},{"name":"Nathan Fairbairn","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(393,'Yo, Vampiro. Nuevo Universo DC #1','Yo, Vampiro. Nuevo Universo DC',1,NULL,'978-8-415-62857-6',NULL,'Joshua Fialkov','Andrea Sorrentino',NULL,NULL,'ECC Ediciones',NULL,'2012-09-01',NULL,NULL,replace(replace('CONTENIDO USA: I, vampire Vol. 1 (2011-2013) #1-6 \r\nHISTORIAS: Amor impuro / Las chicas solo quieren divertirse / Entumecido / Entre días / Sigue picando / Un hombre encantador\r\nARGUMENTO: Nubes oscuras se ciernen sobre la humanidad bajo un cielo rojo escarlata, y solo Andrew Bennet conoce la causa de semejante amenaza: Mary, la Reina de Sangre, ha creado un ejército de vampiros con el que planea poner fin a siglos de vida en la oscuridad para su especie. Se avecina una guerra ideológica entre el discurso integrador de Andrew y el enfrentamiento directo de Mary, y los humanos son poco más que simple carnaza.','\r',char(13)),'\n',char(10)),NULL,NULL,160,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566429039-44qa34.jpg','read',0,NULL,NULL,'2026-04-07 12:53:52','2026-04-07 17:38:33',74,NULL,'Rústica','[{"name":"Joshua Fialkov","role":"Guion"},{"name":"Andrea Sorrentino","role":"Dibujo, Tinta"},{"name":"Marcelo Maiolo","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(394,'Yo, Vampiro. Nuevo Universo DC #2','Yo, Vampiro. Nuevo Universo DC',2,NULL,'978-8-415-84470-9',NULL,'Joshua Fialkov','Andrea Sorrentino',NULL,NULL,'ECC Ediciones',NULL,'2013-06-01',NULL,NULL,replace(replace('CONTENIDO USA: I, Vampire Vol.1 (2011-2013) #9-12\r\nHISTORIAS: Fin del Mundo, Ven pronto (Que se Nos Comen las chinches) / A la Espera del Fin del Mundo / El Ahogado / Desintegración\r\nARGUMENTO: Andrew Bennett, el vampiro que antaño plantara cara al resto de su especie, ahora se ha convertido en su líder. Refugiados en el desierto de Utah, los chupasangres de Estados Unidos sobreviven como pueden sin saber que está a punto de caer literalmente del cielo una organización que pretende exterminarlos a todos: ¡la Orden de los Van Helsing! ¡Y además, la aparición estelar de Stormwatch!','\r',char(13)),'\n',char(10)),NULL,NULL,160,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566436315-wdxv2i.jpg','read',0,NULL,NULL,'2026-04-07 12:53:57','2026-04-07 17:38:33',74,NULL,'Rústica','[{"name":"Joshua Fialkov","role":"Guion"},{"name":"Andrea Sorrentino","role":"Dibujo, Tinta"},{"name":"Marcelo Maiolo","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(395,'Yo, Vampiro. Nuevo Universo DC #3','Yo, Vampiro. Nuevo Universo DC',3,NULL,'978-8-415-99023-9',NULL,'Joshua Fialkov','Andrea Sorrentino',NULL,NULL,'ECC Ediciones',NULL,'2013-11-27',NULL,NULL,replace(replace('CONTENIDO USA: I, vampire Vol. 1 (2011-2013) #13-19\r\nHISTORIAS: Degradada / El largo invierno / Aquí llega tu hombre / Hijo de Nimrod / Oleada de mutilación / En busca del fuego / Caribu\r\nARGUMENTO: Tras los dramáticos sucesos del anterior volumen, Andrew se ha convertido en una bestia sedienta de sangre, y la joven Tig le acompaña como su nueva sirviente en un camino cuyo objetivo final no es otro que el de dominar el planeta entero con un ejército invencible. Por otro lado, Mary ya no es la reina vampira que fue durante siglos, lo que no implica que haya dejado de ser uno de los seres más peligrosos sobre la faz de la Tierra. Acompañada por John, el único amigo de Andrew, y por Deborah, otra mujer del pasado del nuevo rey vampiro, se embarcará en una aventura para recuperar la humanidad perdida de su antiguo amor. Yo, vampiro llega a su impactante final.','\r',char(13)),'\n',char(10)),NULL,NULL,160,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566438973-falxo0.jpg','read',0,NULL,NULL,'2026-04-07 12:53:59','2026-04-07 17:38:33',74,NULL,'Rústica','[{"name":"Joshua Fialkov","role":"Guion"},{"name":"Andrea Sorrentino","role":"Dibujo, Tinta"},{"name":"Marcelo Maiolo","role":"Color"},{"name":"Dennis Calero","role":"Dibujo, Tinta"},{"name":"Scott Clark","role":"Dibujo, Tinta"},{"name":"Szymon Kudranski","role":"Dibujo, Tinta"},{"name":"Fernando Blanco","role":"Dibujo, Tinta"},{"name":"David Beaty","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(396,'Liga de la Justicia Oscura. Nuevo Universo DC #1','Liga de la Justicia Oscura. Nuevo Universo DC',1,NULL,'978-8-415-52091-7',NULL,'Peter Milligan','Mikel Janin',NULL,NULL,'ECC Ediciones',NULL,'2012-06-01',NULL,NULL,replace(replace('CONTENIDO USA: Justice League Dark Vol. 1 #1-4\r\nHISTORIAS: A Oscuras, Parte 1: Mujeres Imaginarias / A Oscuras, Parte 2: Materia Oscura / A Oscuras, Parte 3: Señas de Identidad y Alcohol / A Oscuras, Parte 4: Moone a la Luz de la Luna \r\nARGUMENTO: June Moone ha conseguido separarse de la bruja que la poseia, pero la entidad que era la fusión de ambas, la Encantadora, se ha desequilibrado. Sin la parte luminosa que June aportaba a la bruja, la oscuridad la domina y amenaza con destruir el mundo.','\r',char(13)),'\n',char(10)),NULL,NULL,128,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566487460-g1ynfk.jpg','read',0,NULL,NULL,'2026-04-07 12:54:50','2026-04-07 17:38:33',75,NULL,'Rústica','[{"name":"Peter Milligan","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo, Tinta"},{"name":"Ulises Arreola","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(397,'Liga de la Justicia Oscura. Nuevo Universo DC #6','Liga de la Justicia Oscura. Nuevo Universo DC',6,NULL,'978-8-415-99018-5',NULL,'Jeff Lemire','Mikel Janin',NULL,NULL,'ECC Ediciones',NULL,'2013-11-28',NULL,NULL,replace(replace('CONTENIDO USA: Justice League Dark Vol. 1 #18-21\r\nHISTORIAS: La Muerte de la Magia, Parte 4: La Batalla Final / La Ciudad del Terror, Parte 1: La Casa del Dolor / La Ciudad del Terror, Parte 2: El Evangelio de las Pesadillas / La Ciudad del Terror, Conclusión: ¡Muere, Muere, Muere, Querida! \r\nARGUMENTO: Después del esfuerzo de recuperar los Libros de la Magia de los ardides de Felix Faust –una odisea que acarreó un gran sacrificio y estuvo a punto de acabar con el grupo–, la Liga de la Justicia Oscura descubre que la crisis que desencadenaron estos místicos tomos está lejos de terminar: una amenaza fría se cierne no ya sobre ellos, sino sobre toda la magia, que se ha levantado en armas para librar una batalla en la que se decidirá su supervivencia.','\r',char(13)),'\n',char(10)),NULL,NULL,128,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566501353-28wtkp.jpg','read',0,NULL,NULL,'2026-04-07 12:55:01','2026-04-07 17:38:33',75,NULL,'Rústica','[{"name":"Jeff Lemire","role":"Guion"},{"name":"Ray Fawkes","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo, Tinta"},{"name":"Jeromy Cox","role":"Color"},{"name":"Vicente Cifuentes","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(398,'Liga de la Justicia Oscura. Nuevo Universo DC #2','Liga de la Justicia Oscura. Nuevo Universo DC',2,NULL,'978-8-415-62870-5',NULL,'Joshua Fialkov','Andrea Sorrentino',NULL,NULL,'ECC Ediciones',NULL,'2012-10-01',NULL,NULL,replace(replace('CONTENIDO USA: Justice League Dark Vol. 1 #5-7; I, Vampire Vol. 1 #7\r\nHISTORIAS: A Oscuras, Conclusión: Érase un Hombre Encorvado / A Oscuras, Post Mortem: La Maldita Reunión / El Alzamiento de los Vampiros, Parte 1: Sangre Roja, Magia Negra  / El Alzamiento de los Vampiros, Parte 2: La Culpa es de Caín\r\nARGUMENTO: Finalizada la amenaza de la Encantadora otra aún mayor se presenta: El alzamiento de los vampiros. La historia continua del primer tomo de Yo, vampiro publicado por la misma editorial. Aquél tomo finalizó con la muerte de Andrew Bennet y la liberación de Caín, el primer vampiro...y aquí vemos las consecuencias: Gotham arde con la furia de los vampiros y Batman y sus aliados se ven incapaces de detenerlos. Solo la Liga de la Justicia oscura puede ofrecer algo de esperanza para evitar una tierra gobernada por criaturas sedientas de sangre humana.','\r',char(13)),'\n',char(10)),NULL,NULL,128,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566503268-b7jjtq.jpg','read',0,NULL,NULL,'2026-04-07 12:55:04','2026-04-07 17:38:33',75,NULL,'Rústica','[{"name":"Joshua Fialkov","role":"Guion"},{"name":"Peter Milligan","role":"Guion"},{"name":"Andrea Sorrentino","role":"Dibujo"},{"name":"Daniel Sampere","role":"Dibujo, Tinta"},{"name":"Mikel Janin","role":"Dibujo, Tinta"},{"name":"Admira Wijaya","role":"Dibujo, Tinta, Color"},{"name":"Marcelo Maiolo","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(399,'Liga de la Justicia Oscura. Nuevo Universo DC #3','Liga de la Justicia Oscura. Nuevo Universo DC',3,NULL,'978-8-415-74861-8',NULL,'Jeff Lemire','Andrea Sorrentino',NULL,NULL,'ECC Ediciones',NULL,'2013-02-01',NULL,NULL,replace(replace('CONTENIDO USA: Justice League Dark Vol. 1 #8 a #10; I, Vampire Vol. 1 #8\r\nHISTORIAS: La Despedida, Parte 3 de El Alzamiento de los Vampiros / La Conclusión de El Alzamiento de los Vampiros: La Crueldad de Ser Amable / La Sala Negra, Partes 1 y 2\r\nARGUMENTO: La batalla final entre Caín y la Liga de la Justicia Oscura finaliza con la liberación de un poder superior en manos de Andrew Bennet. Pero ahora, los miembros de esta peculiar liga de la justicia deben llevar a cabo una prueba de fuego, un enfrentamiento con Felix Faust por un poder inabarcable en el que solo puede haber un ganador.','\r',char(13)),'\n',char(10)),NULL,NULL,128,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566505816-ahscu7.jpg','read',0,NULL,NULL,'2026-04-07 12:55:06','2026-04-07 17:38:33',75,NULL,'Rústica','[{"name":"Jeff Lemire","role":"Guion"},{"name":"Joshua Fialkov","role":"Guion"},{"name":"Peter Milligan","role":"Guion"},{"name":"Andrea Sorrentino","role":"Dibujo, Tinta"},{"name":"Daniel Sampere","role":"Dibujo, Tinta"},{"name":"Mikel Janin","role":"Dibujo, Tinta"},{"name":"Admira Wijaya","role":"Color"},{"name":"Ulises Arreola","role":"Color"},{"name":"Marcelo Maiolo","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(400,'Liga de la Justicia Oscura. Nuevo Universo DC #4','Liga de la Justicia Oscura. Nuevo Universo DC',4,NULL,'978-8-415-84466-2',NULL,'Jeff Lemire','Mikel Janin',NULL,NULL,'ECC Ediciones',NULL,'2013-05-01',NULL,NULL,replace(replace('CONTENIDO USA: Justice League Dark Vol. 1 #11-13 y Justice League Dark Vol. 1 Annual #1\r\nHISTORIAS: La Sala Negra, Parte 3 / La Guerra de los Libros de la Magia, Parte 1 / La Guerra de los Libros de la Magia, Parte 2: Apocalipsis / La Guerra de los Libros de la Magia, Conclusión\r\nARGUMENTO: En el viejo Universo DC, Felix Faust era una amenaza menor: un aficionado a la magia, un mago menor que mordía más de lo que era capaz de tragar e intentaba conquistar con ardides lo que no podía tomar mediante el poder. Pero claro, este no es el viejo Universo DC. Felix Faust se ha enfrentado a la Liga de la Justicia Oscura por el control de un artefacto capaz de cambiarlo todo, de modificar la realidad a su antojo y sacudir los cimientos de la magia. Los héroes lo saben: se acerca el final de la partida.','\r',char(13)),'\n',char(10)),NULL,NULL,128,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566507592-80z594.jpg','read',0,NULL,NULL,'2026-04-07 12:55:08','2026-04-07 17:38:33',75,NULL,'Rústica','[{"name":"Jeff Lemire","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo, Tinta"},{"name":"Ulises Arreola","role":"Color"},{"name":"Kyle Ritter","role":"Color"},{"name":"Victor Drujiniu","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(401,'Liga de la Justicia Oscura. Nuevo Universo DC #5','Liga de la Justicia Oscura. Nuevo Universo DC',5,NULL,'978-8-415-92568-2',NULL,'Jeff Lemire','Mikel Janin',NULL,NULL,'ECC Ediciones',NULL,'2013-10-01',NULL,NULL,replace(replace('CONTENIDO USA: Justice league dark vol. 1 #14-17\r\nHISTORIAS: Entra en la Casa del Misterio...  / La Muerte de la Magia, Parte 1: Arriba es Abajo / La Muerte de la Magia, Parte 2: La Noche del Cazador / La Muerte de la Magia, Parte 3: Prisioneros de Época \r\nARGUMENTO: La Liga de la Justicia Oscura derramó sangre, sudor y lágrimas, vio la traición cara a cara y luchó hasta el último aliento para recuperar los Libros de la Magia de las manos de Felix Faust, un hechicero que parecía disponer de un poder ilimitado a su alcance. Una vez derrotado Faust, la naturaleza impredecible de la magia, que se rebela contra toda atadura, garantizaba que los secretos en ellos contenidos iban a ser inesperados... sin embargo, nadie podía esperar lo que desencadenaron.','\r',char(13)),'\n',char(10)),NULL,NULL,128,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566509593-55cekh.jpg','read',0,NULL,NULL,'2026-04-07 12:55:10','2026-04-07 17:38:14',75,NULL,'Rústica','[{"name":"Jeff Lemire","role":"Guion"},{"name":"Ray Fawkes","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo, Tinta"},{"name":"Victor Drujiniu","role":"Tinta"},{"name":"Graham Nolan","role":"Dibujo"},{"name":"Jeromy Cox","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(402,'Aquaman. Nuevo Universo DC / Renacimiento #1','Aquaman. Nuevo Universo DC / Renacimiento',1,NULL,'978-8-415-52071-9',NULL,'Geoff Johns','Ivan Reis',NULL,NULL,'ECC Ediciones',NULL,'2012-05-01',NULL,NULL,replace(replace('Contenido USA: Aquaman Vol.7 #1-4\r\nHistorias:  &quot;La Fosa&quot;, partes 1 a 4 (de 4).  \r\nArgumento: Una criaturas surgidas de una fosa submarina atacan la superficie en busca de &quot;comida&quot;, secuestrando a varios humanos.  Aquaman y Mera irán al rescate.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566535219-3dpo9w.jpg','read',0,NULL,NULL,'2026-04-07 12:55:39','2026-04-07 17:38:14',76,23.7,'Rústica','[{"name":"Geoff Johns","role":"Guion"},{"name":"Ivan Reis","role":"Dibujo"},{"name":"Joe Prado","role":"Tinta"},{"name":"Rod Reis","role":"Color"},{"name":"Eber Ferreira","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(403,'Aquaman. Nuevo Universo DC / Renacimiento #11','Aquaman. Nuevo Universo DC / Renacimiento',11,NULL,'978-8-416-47552-0',NULL,'Jeff Parker','Paul Pelletier',NULL,NULL,'ECC Ediciones',NULL,'2015-08-26',NULL,NULL,replace(replace('Contenido USA: Aquaman Vol. 7 #37-40 \r\nHistorias: Vorágine: Capítulo 3 (la astucia de las reinas) / Capítulo 4 (el último portal) / Capítulo 5 (Pacífica) / Capítulo 6 (los confines del muundo)\r\nArgumento: Continúa la alabada etapa de Jeff Parker como guionista de la colección, mostrándonos a un Aquaman obligado a enfrentarse contra Grodd, y afrontando una amenaza relacionada con su propia familia.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566589107-899sda.jpg','read',0,NULL,NULL,'2026-04-07 12:56:29','2026-04-07 17:38:14',76,NULL,'Rústica','[{"name":"Jeff Parker","role":"Guion"},{"name":"Paul Pelletier","role":"Dibujo"},{"name":"Sean Parsons","role":"Tinta"},{"name":"Rain Beredo","role":"Color"},{"name":"Sandra Hope","role":"Tinta"},{"name":"Wayne Faucher","role":"Tinta"},{"name":"Peter Pantazis","role":"Color"},{"name":"Tony Kordos","role":"Tinta"},{"name":"Darwyn Cooke","role":"Dibujo"},{"name":"Steve Rude","role":"Dibujo"},{"name":"Amanda Conner","role":"Dibujo, Tinta"},{"name":"Richard Horie","role":"Dibujo"},{"name":"Paul Mounts","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(404,'Aquaman. Nuevo Universo DC / Renacimiento #2','Aquaman. Nuevo Universo DC / Renacimiento',2,NULL,'978-8-415-62854-5',NULL,'Geoff Johns','Ivan Reis',NULL,NULL,'ECC Ediciones',NULL,'2012-09-01',NULL,NULL,replace(replace('Contenido USA: Aquaman Vol.7 #5-8\r\nHistorias: &quot;Perdido&quot; / &quot;¡Abandonada!&quot;  / &quot;Los Otros&quot;, partes 1 y 2 \r\nArgumento: Arthur Curry parecía destinado a llevar una vida plácida junto a su esposa, Mera, al instalarse en el faro de la Bahía de la Amnistía. Poco imaginaban el enfrentamiento que les aguardaba con la Fosa, un colectivo de seres de las profundidades ante los que finalmente emergió victorioso. Pero seguramente aún no lo sepamos todo sobre ellos, ni sobre otros misterios... como el hundimiento de Atlantis y un grupo de héroes, los Otros, al que Aquaman perteneció antes de unirse a la Liga de la Justicia.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566593086-rp6h7n.jpg','read',0,NULL,NULL,'2026-04-07 12:56:33','2026-04-07 17:38:14',76,NULL,'Rústica','[{"name":"Geoff Johns","role":"Guion"},{"name":"Ivan Reis","role":"Dibujo"},{"name":"Joe Prado","role":"Tinta"},{"name":"Eber Ferreira","role":"Tinta"},{"name":"Rod Reis","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(405,'Aquaman. Nuevo Universo DC / Renacimiento #3','Aquaman. Nuevo Universo DC / Renacimiento',3,NULL,'978-8-415-74835-9',NULL,'Geoff Johns','Ivan Reis',NULL,NULL,'ECC Ediciones',NULL,'2013-01-01',NULL,NULL,replace(replace('Contenido USA: Aquaman vol.7 #9 -12\r\nHistorias: &quot;Los otros&quot;, partes 3 a 6.\r\nArgumento: Aquaman y Mera, tras vencer a los abisales seres de la Fosa, se enfrentan a nuevos retos en el mundo de la superficie: si él por poco llega a morir en pleno desierto a resultas de un ataque atlante, ella casi termina arrestada al haberse defendido de un acosador. Mientras tanto, Manta Negra empieza a asesinar a los antiguos miembros de un grupo clandestino, los Otros, del que Arthur formó parte. ¿Qué pretende el archienemigo de Aquaman y cuál es el origen de la encarnizada rivalidad entre ambos?','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566595421-ib8tn5.jpg','read',0,NULL,NULL,'2026-04-07 12:56:36','2026-04-07 17:38:14',76,NULL,'Rústica','[{"name":"Geoff Johns","role":"Guion"},{"name":"Ivan Reis","role":"Dibujo"},{"name":"Joe Prado","role":"Tinta"},{"name":"Oclair Albert","role":"Tinta"},{"name":"Andy Lanning","role":"Tinta"},{"name":"Rod Reis","role":"Color"},{"name":"Jonathan Glapion","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(406,'Aquaman. Nuevo Universo DC / Renacimiento #4','Aquaman. Nuevo Universo DC / Renacimiento',4,NULL,'978-8-415-84439-6',NULL,'Geoff Johns','Ivan Reis',NULL,NULL,'ECC Ediciones',NULL,'2013-05-01',NULL,NULL,replace(replace('Contenido USA: Aquaman Vol.7 #0, 13 y 14 y Justice League Vol.2 #15\r\nHistorias: Los Otros (conclusion) / Bajo el Agua / El Trono de Atlantis: Capítulo 1\r\nArgumento: Antes de la fundación de la Liga de la Justicia, Aquaman perteneció a un grupo clandestino de héroes, los Otros, poseedores de ancestrales reliquias atlantes. Ahora, años más tarde, Manta Negra empieza a asesinar a sus antiguos miembros uno por uno. Lo logra con Kahina la Vidente, a la que arrebata su reliquia (el Sello Dorado), y conVostok X, el cosmonauta ruso. En la Tumba del Rey Difunto, ante el cadáver de su amigo, Aquaman jura vengarse de Manta Negra y darle muerte de una vez por todas...','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566597323-0frf6v.jpg','read',0,NULL,NULL,'2026-04-07 12:56:38','2026-04-07 17:38:14',76,NULL,'Rústica','[{"name":"Geoff Johns","role":"Guion"},{"name":"Ivan Reis","role":"Dibujo, Tinta"},{"name":"Joe Prado","role":"Dibujo, Tinta"},{"name":"Rod Reis","role":"Color"},{"name":"Julio Ferreira","role":"Tinta"},{"name":"Pete Woods","role":"Dibujo"},{"name":"Pere Pérez","role":"Dibujo, Tinta"},{"name":"Mario Alquiza","role":"Tinta"},{"name":"Ruy Jose","role":"Tinta"},{"name":"Sean Parsons","role":"Tinta"},{"name":"Cam Smith","role":"Tinta"},{"name":"Tony Aviña","role":"Color"}]');
