INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(408,'Aquaman. Nuevo Universo DC / Renacimiento #6','Aquaman. Nuevo Universo DC / Renacimiento',6,NULL,'978-8-415-99049-9',NULL,'Geoff Johns','Paul Pelletier',NULL,NULL,'ECC Ediciones',NULL,'2013-12-31',NULL,NULL,replace(replace('Contenido USA: Aquaman Vol. 7 #17 a 21 USA\r\nHistorias: El trono de Atlantis: Epílogo / La muerte de un rey: Capítulo 1, Capítulo 2 y Capítulo 3 (confrontación) / El caminante de piel.\r\nArgumento: Al concluir la guerra entre Atlantis y el mundo de la superficie, nadie resulta indemne: la Liga de la Justicia recluta nuevos miembros, una sociedad secreta de villanos empieza a hacer lo mismo e incluso el gobierno de los EE.UU. aspira a fundar su propio grupo. Vulko terminó preso en las mazmorras de Atlantis por propiciar el conflicto y Orm, en Belle Rêve por las muertes en masa. Y así, con ambos entre rejas, Arthur afronta la ardua tarea de liderar el destino de Atlantis como su nuevo rey.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566604650-jqsomp.jpg','read',0,NULL,NULL,'2026-04-07 12:56:45','2026-04-07 17:38:14',76,NULL,'Rústica','[{"name":"Geoff Johns","role":"Guion"},{"name":"John Ostrander","role":"Guion"},{"name":"Paul Pelletier","role":"Dibujo"},{"name":"Manuel García","role":"Dibujo"},{"name":"Sean Parsons","role":"Tinta"},{"name":"Rod Reis","role":"Color"},{"name":"Sandra Hope","role":"Tinta"},{"name":"Wayne Faucher","role":"Tinta"},{"name":"Rob Hunter","role":"Tinta"},{"name":"Ray McCarthy","role":"Tinta"},{"name":"Peter Pantazis","role":"Color"},{"name":"Art Thibert","role":"Tinta"},{"name":"Brad Anderson","role":"Color"},{"name":"Tom Bunk","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(409,'Aquaman. Nuevo Universo DC / Renacimiento #7','Aquaman. Nuevo Universo DC / Renacimiento',7,NULL,'978-8-416-07085-5',NULL,'Geoff Johns','Paul Pelletier',NULL,NULL,'ECC Ediciones',NULL,'2014-04-29',NULL,NULL,replace(replace('Contenido USA: Aquaman Vol. 7 #22-25 y Aquaman Vol. 7 Annual 1.\r\nHistorias: La muerte de un rey: Capítulo 4, Capítulo 5 (un callejón sin salida), Capítulo 6 (el secreto de los siete mares) y Capítulo 7 (Bautismo de fuego) / El mal menor  \r\nArgumento: Arthur es al fin monarca de Atlantis, pero a la oposición de algunos de sus súbditos, leales a Orm —como Murk o Tula—, se suman muchas otras amenazas. Entre ellas, el Carroñero (cuya flota submarina llegaba dispuesta a tomar la ciudad al final del volumen anterior), Xebel (la colonia atlante de la que proceden Mera y su prometido, Nereus) y sobre todo el enigmático Rey Difunto, que tras dejar indefensos a Mera, a Nereus y casi al propio Arthur planea recuperar el trono que según él le pertenece.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566607312-4xjiix.jpg','read',0,NULL,NULL,'2026-04-07 12:56:47','2026-04-07 17:38:14',76,NULL,'Rústica','[{"name":"Geoff Johns","role":"Guion"},{"name":"Paul Pelletier","role":"Dibujo"},{"name":"Sean Parsons","role":"Tinta"},{"name":"Rod Reis","role":"Color"},{"name":"John Ostrander","role":"Guion"},{"name":"Geraldo Borges","role":"Dibujo"},{"name":"Netho Diaz","role":"Dibujo"},{"name":"Ruy Jose","role":"Tinta"},{"name":"Roy Allan Martínez","role":"Tinta"},{"name":"J.P. Mayer","role":"Tinta"},{"name":"Mariah Benes","role":"Tinta"},{"name":"Oclair Albert","role":"Tinta"},{"name":"Julio Ferreira","role":"Tinta"},{"name":"Jay Leisten","role":"Tinta"},{"name":"Hi-Fi Desing","role":"Color"},{"name":"Rob Hunter","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(410,'Aquaman. Nuevo Universo DC / Renacimiento #8','Aquaman. Nuevo Universo DC / Renacimiento',8,NULL,'978-8-416-19449-0',NULL,'Jeff Parker','Netho Diaz',NULL,NULL,'ECC Ediciones',NULL,'2014-09-01',NULL,NULL,replace(replace('Contenido USA: Aquaman Vol. 7 #26-29 USA\r\nHistorias: Presión / Vida y Muerte / Tritón / El olímpico\r\nArgumento: El reinado de Arthur se consolidó tras afrontar dos amenazas que casi le pusieron fin: el Carroñero, a cuya flota de submarinos pudo vencer con la ayuda de la colosal criatura llamada Topo, y el Rey Difunto, que resultó ser Atlan, artífice del hundimiento de Atlantis... Y reveló que Arthur carecía de sangre real al ser descendiente de Orin, asesino de su familia y usurpador del trono. Ahora Aquaman y Mera reinan en la ciudad sumergida, pero ignoran la amenaza de los Siete Mares... entre muchas otras.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566611370-2xx3bp.jpg','read',0,NULL,NULL,'2026-04-07 12:56:52','2026-04-07 17:38:14',76,NULL,'Rústica','[{"name":"Jeff Parker","role":"Guion"},{"name":"Netho Diaz","role":"Dibujo"},{"name":"Paul Pelletier","role":"Dibujo"},{"name":"Sean Parsons","role":"Tinta"},{"name":"Ruy Jose","role":"Tinta"},{"name":"Wil Quintana","role":"Color"},{"name":"Andrew Dalhouse","role":"Color"},{"name":"Rod Reis","role":"Color"},{"name":"Jeromy Cox","role":"Color"},{"name":"Norm Rapmund","role":"Tinta"},{"name":"Rain Beredo","role":"Color"},{"name":"Andrew Hennessy","role":"Tinta"},{"name":"John Katz","role":"Dibujo"},{"name":"Richard Horie","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(411,'Aquaman. Nuevo Universo DC / Renacimiento #9','Aquaman. Nuevo Universo DC / Renacimiento',9,NULL,'978-8-416-30303-8',NULL,'Jeff Parker','Paul Pelletier',NULL,NULL,'ECC Ediciones',NULL,'2014-12-30',NULL,NULL,replace(replace('Contenido USA: Aquaman Vol. 7 #30-33 \r\nHistorias: Caído / En el fango / Está vivo / Pasa a mejor vida\r\nArgumento: Los inicios de Arthur como nuevo monarca atlante no iban a ser fáciles, sin duda, pero ni él habría esperado un enfrentamiento con una colosal criatura legendaria, el Karaqan, del que apenas lograría salir con vida. Y ni siquiera una reunión de antiguos alumnos del Instituto Amnesty le sirve de consuelo, porque enseguida el Dr. Daniel Evans abre con su tridente un portal dimensional que atrae a los Hijos de los Gigantes, adversarios ancestrales de Atlantis dispuestos a aniquilar a su actual rey...','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566613996-a9jk51.jpg','read',0,NULL,NULL,'2026-04-07 12:56:54','2026-04-07 17:38:14',76,NULL,'Rústica','[{"name":"Jeff Parker","role":"Guion"},{"name":"Paul Pelletier","role":"Dibujo"},{"name":"Alvaro Martinez Bueno","role":"Dibujo"},{"name":"Sean Parsons","role":"Tinta"},{"name":"Raúl Fernandez","role":"Tinta"},{"name":"Rain Beredo","role":"Color"},{"name":"Rick Magyar","role":"Tinta"},{"name":"Graham Nolan","role":"Dibujo"},{"name":"Mike Allred","role":"Dibujo"},{"name":"John Caldwell","role":"Dibujo"},{"name":"Ant Lucia","role":"Dibujo"},{"name":"Wil Quintana","role":"Color"},{"name":"Alex Sinclair","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(412,'Aquaman. Nuevo Universo DC / Renacimiento #10','Aquaman. Nuevo Universo DC / Renacimiento',10,NULL,'978-8-416-37489-2',NULL,'Jeff Parker','Carlos Rodríguez',NULL,NULL,'ECC Ediciones',NULL,'2015-04-29',NULL,NULL,replace(replace('Contenido USA: Aquaman Vol. 7 Annual #2 USA, Aquaman Vol. 7 #34-36 USA\r\nHistorias: Tierra y Mar / Nacidos de los gigantes: Capítulo 1 y 2 / Vorágine: Capítulo 1 (El más allá) y Capítulo 2 (Poseido)\r\nArgumento: A  la luz de los secretos desvelados este mes, la vida de Arthur Curry podría cambiar para siempre. Además, este tomo contiene el segundo anual de la colección, donde nuestro protagonista forma equipo con Wonder Woman.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775566617062-l11htb.jpg','read',0,NULL,NULL,'2026-04-07 12:56:57','2026-04-07 17:38:14',76,NULL,'Rústica','[{"name":"Jeff Parker","role":"Guion"},{"name":"Carlos Rodríguez","role":"Dibujo"},{"name":"Paul Pelletier","role":"Dibujo"},{"name":"Yvel Guichet","role":"Dibujo"},{"name":"Bit","role":"Tinta"},{"name":"Rain Beredo","role":"Color"},{"name":"Sean Parsons","role":"Tinta"},{"name":"Jason Gorder","role":"Tinta"},{"name":"Wayne Faucher","role":"Tinta"},{"name":"Nathan Eyring","role":"Color"},{"name":"Alvaro Martinez Bueno","role":"Dibujo"},{"name":"Dan Panosian","role":"Dibujo"},{"name":"Mark A. Nelson","role":"Dibujo"},{"name":"Danny Miki","role":"Tinta"},{"name":"Raúl Fernandez","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(413,'Wonder Woman (2012- 2022) #1','Wonder Woman (2012- 2022)',1,NULL,'978-8-415-52098-6',NULL,'Brian Azzarello','Cliff Chiang',NULL,NULL,'ECC Ediciones',NULL,'2012-06-01',NULL,NULL,replace(replace('CONTENIDO USA: Wonder Woman Vol. 4 #1-4\r\nHISTORIAS: La aparición / En casa / Arcilla / Sangre\r\nARGUMENTO: Diana acude a Virginia a ayudar a Zola, una mujer embarazada que ha recibido la visita de dos centauros que pretenden matarla. Y todo porque hay cierta diosa del Olimpo que no ha digerido muy bien la última infidelidad de su esposo.','\r',char(13)),'\n',char(10)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775567529890-foz078.jpg','read',0,NULL,NULL,'2026-04-07 13:12:13','2026-04-07 17:38:14',77,NULL,'Rústica','[{"name":"Brian Azzarello","role":"Guion"},{"name":"Cliff Chiang","role":"Dibujo, Tinta"},{"name":"Matt Wilson","role":"Color"}]');
