INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(415,'Wonder Woman (2012- 2022) #3','Wonder Woman (2012- 2022)',3,NULL,'978-8-415-74860-1',NULL,'Brian Azzarello','Cliff Chiang',NULL,NULL,'ECC Ediciones',NULL,'2013-02-01',NULL,NULL,replace(replace('CONTENIDO USA: Wonder Woman Vol. 4 #9-12\r\nHISTORIAS: Estamos aquí reunidos... / Los votos / La salida del hijo / El legado \r\nARGUMENTO: Cuando los héroes reúnen todas sus fuerzas y parten con las armas afi ladas a enfrentarse al enemigo, no puede esperarles sino el triunfo... ¿verdad? Y más cuando se cuenta con aliados como Hefestos, el herrero de los mismos dioses. ¡Nada puede quebrar una voluntad de acero como la de la princesa amazona! Pero sin embargo, ha ocurrido. Wonder Woman fue a enfrentarse al enemigo... y Wonder Woman fue derrotada. Ahora, desde las profundidades del inframundo, tendrá que batallar como nunca antes para reclamar la victoria.','\r',char(13)),'\n',char(10)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775567549735-snhfe3.jpg','read',0,NULL,NULL,'2026-04-07 13:12:30','2026-04-07 17:38:14',77,NULL,'Rústica','[{"name":"Brian Azzarello","role":"Guion"},{"name":"Cliff Chiang","role":"Dibujo, Tinta"},{"name":"Tony Akins","role":"Dibujo"},{"name":"Dan Green","role":"Tinta"},{"name":"Matthew Wilson","role":"Color"},{"name":"Kano","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(416,'Wonder Woman (2012- 2022) #4','Wonder Woman (2012- 2022)',4,NULL,'978-8-415-84465-5',NULL,'Brian Azzarello','Cliff Chiang',NULL,NULL,'ECC Ediciones',NULL,'2013-06-01',NULL,NULL,replace(replace('CONTENIDO USA: Wonder Woman Vol. 4 #0, #13-15\r\nHISTORIAS: ¡La guarida del Minotauro! / El pecado del padre / Predicando en el desierto / La responsabilidad de un Dios\r\nARGUMENTO: Después de haber viajado hasta el mismo inframundo y haber encontrado el camino de vuelta, después de enfrentarse a dioses en un combate que parecía imposible de ganar, después de combatir a las mayores amenazas de la mitología griega, Wonder Woman se embarca en un viaje en busca de respuestas. Mientras tanto, se anuncia la llegada de un hombre: un dios de un mundo que no existía en este nuevo universo, una encarnación de la rabia, un avatar escarlata de la furia. Acompañado por el trueno, Orión se acerca.','\r',char(13)),'\n',char(10)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775567552338-hky9kh.jpg','read',0,NULL,NULL,'2026-04-07 13:12:33','2026-04-07 17:38:14',77,NULL,'Rústica','[{"name":"Brian Azzarello","role":"Guion"},{"name":"Cliff Chiang","role":"Dibujo, Tinta"},{"name":"Matthew Wilson","role":"Color"},{"name":"Tony Akins","role":"Dibujo, Tinta"},{"name":"Dan Green","role":"Tinta"},{"name":"Rick Burchett","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(417,'Wonder Woman (2012- 2022) #5','Wonder Woman (2012- 2022)',5,NULL,'978-8-415-92567-5',NULL,'Brian Azzarello','Cliff Chiang',NULL,NULL,'ECC Ediciones',NULL,'2013-10-01',NULL,NULL,replace('El panteón olímpico al completo ha tomado ya posiciones con respecto a la crisis desencadenada por el nacimiento del hijo de Zola y parece que el bando de los enemigos de Wonder Woman lleva las de ganar. ¿Cómo logrará recuperar al niño y qué papel tienen que cumplir personajes tan ambiguos e inquietantes como Guerra? Ante tal amenaza, la amazona ten- drá que confiar en la ayuda de un nuevo personaje que ha irrumpido en su vida como un trueno: el temperamental Orión.\rContiene: Wonder Woman #16-19 USA','\r',char(13)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775567555372-to6drb.jpg','read',0,NULL,NULL,'2026-04-07 13:12:36','2026-04-07 17:38:14',77,NULL,'Rústica','[{"name":"Brian Azzarello","role":""},{"name":"Cliff Chiang","role":""},{"name":"Tony Akins","role":""},{"name":"Amilcar Pinna","role":""},{"name":"Goran Sudzuka","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(418,'Wonder Woman (2012- 2022) #6','Wonder Woman (2012- 2022)',6,NULL,'978-8-415-99079-6',NULL,'Brian Azzarello','Cliff Chiang',NULL,NULL,'ECC Ediciones',NULL,'2014-01-31',NULL,NULL,replace('El hijo de Zeus con una mortal ha nacido y el panteón olímpico aún no ha puesto término a sus juegos de poder y luchas por conseguirlo. Las maquinaciones de Apolo han llevado a Wonder Woman a enfrentarse a numerosos enemigos, a saborear la traición, a descender a los mismos infiernos y a luchar contra divinidades. Recientemente, nuevos jugadores han entrado en liza en esta macabra competición: de un lejano mundo llegó Orión, un impetuoso dios de lengua incontrolable que parece nacido para el combate, y el poderoso Primogénito, decidido a utilizar sus dones para hacerse con el pequeño.\rContiene: Wonder Woman #20-23 USA','\r',char(13)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775567558750-c7yiwg.jpg','read',0,NULL,NULL,'2026-04-07 13:12:40','2026-04-07 17:38:14',77,NULL,'Rústica','[{"name":"Brian Azzarello","role":"Guion"},{"name":"Cliff Chiang","role":"Dibujo"},{"name":"Goran Sudzuka","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(419,'Wonder Woman (2012- 2022) #7','Wonder Woman (2012- 2022)',7,NULL,'978-8-416-15216-2',NULL,'Brian Azzarello','Aco',NULL,NULL,'ECC Ediciones',NULL,'2014-05-30',NULL,NULL,replace('Después del devastador enfrentamiento contra el Primogénito, Wonder Woman se retira con sus aliados - entre los que se cuenta el veleidoso Orión - a proteger al bebé y recuperarse de la contienda. La lista de bajas del conflicto se ha engrosado y aunque este ha cambiado de ciclo, está muy lejos de terminar: los enemigos de Wonder Woman aún no se han dado por vencidos y otros ya han aprovechado el presente momento de debilidad para ejecutar el próximo paso de sus planes.\rContiene Wonder Woman # 23.2 y 24-26 USA','\r',char(13)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775567567840-zjjq23.jpg','read',0,NULL,NULL,'2026-04-07 13:12:49','2026-04-07 17:38:14',77,NULL,'Rústica','[{"name":"Brian Azzarello","role":"Guion"},{"name":"Aco","role":"Dibujo"},{"name":"Goran Sudzuka","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(420,'Wonder Woman (2012- 2022) #8','Wonder Woman (2012- 2022)',8,NULL,'978-8-416-19493-3',NULL,'Brian Azzarello','Cliff Chiang',NULL,NULL,'ECC Ediciones',NULL,'2014-10-01',NULL,NULL,replace('La presión de Cassandra es cada vez más insoportable y el peligro que supone, cada vez más real: después de poner en jaque a Wonder Woman, Hermes y Orión con su juego de amenazas, se dirige a por el Primogénito, que está siendo torturado por Apolo mientras cuenta los segundos para su violenta liberación. Con Orión retornado a Nueva Génesis, Wonder Woman ha perdido un importante aliado a las puertas de un enfrentamiento en el que necesitará no uno, sino un ejército de ellos. Mientras, Zola se encuentra con Dioniso, dios de las bacanales.\rContiene Wonder Woman #27-30 USA','\r',char(13)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775567575167-l43vom.jpg','read',0,NULL,NULL,'2026-04-07 13:12:55','2026-04-07 17:38:14',77,NULL,'Rústica','[{"name":"Brian Azzarello","role":"Guion"},{"name":"Cliff Chiang","role":"Dibujo"},{"name":"Goran Sudzuka","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(421,'Wonder Woman (2012- 2022) #9','Wonder Woman (2012- 2022)',9,NULL,'978-8-416-30397-7',NULL,'Brian Azzarello','Cliff Chiang',NULL,NULL,'ECC Ediciones',NULL,'2015-02-25',NULL,NULL,replace(replace('Recopila #31-35 USA\r\nEl Primogénito ha logrado liberarse y apoderarse del Olimpo, que ahora muestra un aspecto acorde con el de su soberano. Por su parte, Hera decide redimir los errores del pasado devolviendo a las amazonas a su estado original con la excepción de Hipólita, que sigue siendo una estatua de barro. Decidida a derrotar al Primogénito y a cambiar muchas cosas en Isla Paraíso, Wonder Woman asume su papel de diosa de la guerra... y de reina de las amazonas.','\r',char(13)),'\n',char(10)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775567580630-3fkxqf.jpg','read',0,NULL,NULL,'2026-04-07 13:13:01','2026-04-07 17:38:14',77,NULL,'Rústica','[{"name":"Brian Azzarello","role":"Guion"},{"name":"Cliff Chiang","role":"Dibujo"},{"name":"Goran Sudzuka","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(424,'Wonder Woman (2012- 2022) #15 / 1','Wonder Woman (2012- 2022) #15 / 1',15,NULL,'978-8-416-94584-9',NULL,'Greg Rucka','Liam Sharp',NULL,NULL,'ECC Ediciones',NULL,'2017-01-31',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Wonder Woman: Rebirth núm. 1 (one-shot), Wonder Woman núms. 1-3 USA\r\nDespués de una pérdida inimaginable, Wonder Woman debe reconstruir su cruzada como protectora y campeona de la Tierra. Tras los acontecimientos de La Guerra de Darkseid y el especial Universo DC: Renacimiento, el lazo de la verdad, la más poderosa arma de la Mujer Maravilla, ha dejado de funcionar... ¡y oscuros secretos del pasado de las Amazonas salen a la luz! Greg Rucka, Liam Sharp, Nicola Scott y Matthew Clark construyen una historia formada por dos arcos argumentales paralelos, que exploran el pasado y el presente de este icono.\r\n¡Arranca una nueva etapa de la serie regular del álter ego de Diana Prince! ¡En formato tomo y con periodicidad bimestral! Brian Azzarello y Cliff Chiang dieron forma a una etapa de Wonder Woman que ya figura entre las más destacadas en la historia del personaje, en el amanecer del nuevo Universo DC. A continuación, David Finch y Meredith Finch tomaron el relevo, prometiendo acción trepidante y emociones fuertes. ¡Y ahora llega el turno de recibir con los brazos abiertos a Greg Rucka! El guionista de Gotham Central y Batman/Wonder Woman: Hiketeia regresa para alterar el destino de Diana, en el año de su debut cinematográfico en solitario.\r\nDescubre más detalles sobre Renacimiento en nuestra web y en el artículo ¡El Renacimiento del Universo DC ya está aquí! Desde este ejemplar añadimos una doble numeración, para así continuar con el volumen iniciado con motivo del Nuevo Universo DC.','\r',char(13)),'\n',char(10)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775825559948-1feaer.jpg','read',0,NULL,NULL,'2026-04-07 13:27:15','2026-04-12 12:19:57',77,17.67,'Rústica','[{"name":"Greg Rucka","role":"Guion"},{"name":"Liam Sharp","role":"Dibujo"},{"name":"Matthew Clark","role":"Dibujo"},{"name":"Nicola Scott","role":"Dibujo"},{"name":"Sean Parsons","role":"Tinta"},{"name":"Jeremy Colwell","role":"Color"},{"name":"Laura Martin","role":"Color"},{"name":"Romulo Fajardo Jr.","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(425,'Wonder Woman (2012- 2022) #19/5','Wonder Woman (2012- 2022) #19/5',19,NULL,'978-8-417-20612-3',NULL,'Greg Rucka','Bilquis Evely',NULL,NULL,'ECC Ediciones',NULL,'2017-09-14',NULL,NULL,replace(replace('EDICIÓN ORIGINAL:Wonder Woman nº. 16-19 USA \r\nARGUMENTO: El viaje de Wonder Woman por el mundo de los hombres sigue adelante, con el origen del que puede ser uno de sus mayores enemigos. Mientras Diana lucha por recomponer su herida psique, Barbara Ann Minerva trata de defenderse y desentrañar la verdad... ¿o en realidad está siendo conducida, sin saberlo, a una trampa definitiva? Nuevos enemigos surgen de entre las sombras, con los secretos de la vida de la Mujer Maravilla al descubierto.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775568481553-z1rp6v.jpg','read',0,NULL,NULL,'2026-04-07 13:28:02','2026-04-12 12:19:57',77,NULL,'Rústica 96-136 pp','[{"name":"Greg Rucka","role":"Guion"},{"name":"Bilquis Evely","role":"Dibujo"},{"name":"Liam Sharp","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(426,'Wonder Woman (2012- 2022) #18/4','Wonder Woman (2012- 2022) #18/4',18,NULL,'978-8-417-14773-0',NULL,'Greg Rucka','Liam Sharp',NULL,NULL,'ECC Ediciones',NULL,'2017-07-18',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Wonder Woman núms. 12-15 USA \r\nARGUMENTO:  Las mentiras ha dejado un panorama desolador para la Mujer Maravilla... y también para Steve Trevor, que ahora debe lidiar con los cambios que han trastocado para siempre su historia personal y a su relación con Diana, al borde de la locura por las recientes revelaciones. En el pasado, en el final de Wonder Woman: Año Uno, la princesa Amazona acepta al fin su destino: ¡Wonder Woman entra en acción ante un enemigo que pretende sembrar el mundo de oscuridad!','\r',char(13)),'\n',char(10)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775568505425-fwm3am.jpg','read',0,NULL,NULL,'2026-04-07 13:28:26','2026-04-12 12:19:57',77,NULL,'Rústica','[{"name":"Greg Rucka","role":"Guion"},{"name":"Liam Sharp","role":"Dibujo"},{"name":"Nicola Scott","role":"Dibujo"},{"name":"Renato Guedes","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(427,'Batgirl. Nuevo Universo DC (2015-2016) #1','Batgirl. Nuevo Universo DC (2015-2016)',1,NULL,'978-8-417-17606-8',NULL,'Brenden Fletcher','Cameron Stewart',NULL,NULL,'ECC Ediciones',NULL,'2015-08-26',NULL,NULL,replace(replace('Recopila Batgirl #35 a 40 USA   \r\n&quot;Barbara Gordon está lista para superar su traumático pasado, hacer las maletas y afrontar todo tipo de retos en Burnside, el vecindario más cool de Gotham City. Allí retomará sus estudios de posgrado, hará nuevas amistades e investigará casos como Batgirl, luciendo para la ocasión un flamante uniforme. \r\nEn Batgirl: La Chica Murciélago de Burnside, el equipo creativo integrado por Cameron Stewart, Brenden Fletcher y Babs Tarr reinventan a este carismático personaje. Siendo fieles a su esencia, proponen un enfoque moderno y divertido que ya ha conquistado a una legión de seguidores y al jurado de los Premios Eisner 2015, tal y como acredita la nominación en la categoría de mejor dibujante/entintador.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775572887425-fl9dzo.jpg','read',0,NULL,NULL,'2026-04-07 14:41:31','2026-04-07 17:38:14',78,NULL,'Rústica','[{"name":"Brenden Fletcher","role":"Guion"},{"name":"Cameron Stewart","role":"Guion, Dibujo"},{"name":"Babs Tarr","role":"Dibujo, Tinta"},{"name":"Maris Wicks","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(428,'Batgirl. Nuevo Universo DC (2015-2016) #2','Batgirl. Nuevo Universo DC (2015-2016)',2,NULL,'978-8-416-66002-5',NULL,'Cameron Stewart','Babs Tarr',NULL,NULL,'ECC Ediciones',NULL,'2016-02-29',NULL,NULL,replace(replace('144 pp \r\nRecopila Batgirl #41-44 USA, Batgirl Annual 3 USA y una historia corta de Convergence: Infinity Inc. #2 USA     \r\n&quot;Tras La Chica Murciélago de Burnside, seguimos disfrutando de las aventuras de Barbara Gordon en una nueva y emocionante etapa de la colección. En este tomo, nuestra protagonista se enfrentará a un nuevo Batman, a su propio padre, y Livewire, la Tigresa de Terciopelo y Gladius. ¡Con invitados especiales como Dick Grayson, Spoiler y Batwoman!\r\nEl equipo creativo integrado por Cameron Stewart, Brenden Fletcher y Babs Tarr reinventan a este carismático personaje. Siendo fieles a su esencia, proponen un enfoque moderno y divertido que ya ha conquistado a una legión de seguidores y al jurado de los Premios Eisner 2015, tal y como acredita la nominación en la categoría de mejor dibujante/entintador recibida por Tarr.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775572895669-694cjz.jpg','read',0,NULL,NULL,'2026-04-07 14:41:36','2026-04-07 17:38:14',78,NULL,'Rústica','[{"name":"Cameron Stewart","role":"Guion"},{"name":"Brenden Fletcher","role":"Guion"},{"name":"Babs Tarr","role":"Dibujo, Tinta, Color"},{"name":"Bengal","role":"Dibujo, Tinta, Color"},{"name":"David Lafuente","role":"Dibujo, Tinta"},{"name":"Joel Gomez","role":"Dibujo"},{"name":"Jake Wyatt","role":"Dibujo"},{"name":"Michel Lacombe","role":"Dibujo"},{"name":"Ming Doyle","role":"Dibujo, Tinta"},{"name":"Mingjue Helen Chen","role":"Dibujo, Tinta, Color"},{"name":"Serge Lapointe","role":"Color"},{"name":"Gabe Eltaeb","role":"Color"},{"name":"Ivan Plascencia","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(429,'Batgirl. Nuevo Universo DC (2015-2016) #3','Batgirl. Nuevo Universo DC (2015-2016)',3,NULL,'978-8-416-84022-9',NULL,'Cameron Stewart','Cameron Stewart',NULL,NULL,'ECC Ediciones',NULL,'2016-08-30',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batgirl núms. 45 a 52 USA\r\nNada puede estropear la boda de tu mejor amiga, ¿verdad? ¡Mentira! Al menos para Batgirl, que ve el día ideal truncado por la reaparición de Dick Grayson... Y la cosa no hará más que complicarse cuando descubra que un misterioso villano —cuya identidad se revela en estas páginas— ha estado manipulando su mente, por no mencionar que una enemiga ya conocida, al frente de su grupo terrorista, prepara una ofensiva contra la Academia Gotham. \r\nStewart y Fletcher cierran su personal e intransferible etapa de la Chica Murciélago con un clímax repleto de heroínas y villanas y un desenlace que no dejará a nadie indiferente, como tampoco lo hará el dibujo de Babs Tarr, Eleonora Carlini o Roger Robinson.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775572898186-81nipf.jpg','read',0,NULL,NULL,'2026-04-07 14:41:38','2026-04-07 17:38:14',78,NULL,'Rústica','[{"name":"Cameron Stewart","role":"Guion, Dibujo"},{"name":"Brenden Fletcher","role":"Guion"},{"name":"Babs Tarr","role":"Dibujo, Tinta"},{"name":"Eleonora Carlini","role":"Dibujo, Tinta"},{"name":"Moritat","role":"Dibujo, Tinta"},{"name":"Horacio Domingues","role":"Dibujo, Tinta"},{"name":"Roger Robinson","role":"Dibujo, Tinta"},{"name":"Ming Doyle","role":"Dibujo, Tinta"},{"name":"James Harvey","role":"Dibujo, Tinta, Color"},{"name":"John Timms","role":"Dibujo, Tinta"},{"name":"Minkyu Jung","role":"Dibujo, Tinta"},{"name":"Rob Haynes","role":"Dibujo"},{"name":"Serge Lapointe","role":"Color"},{"name":"Lee Loughridge","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(430,'Batman Inc. #1','Batman Inc.',1,NULL,'978-8-415-84484-6',NULL,'Grant Morrison','Chris Burnham',NULL,NULL,'ECC Ediciones',NULL,'2013-06-01',NULL,NULL,replace(replace('Contiene Batman Incorporated vol.2 #0 y #1-4 USA\r\nDecidido a elevar su cruzada contra el crimen a una escala global, Bruce Wayne fundó Batman Incorporated: entramado corporativo destinado a establecer una red internacional de colaboradores con la que combatir el mal que atisbó durante su peregrinaje temporal. Con la sociedad conocida como Leviatán como gran antagonista, el grupo de superhéroes formado por el Hombre Murciélago logró derrotar a uno de sus más destacados miembros: el Doctor Dédalo. Pero ahora deben afrontar la batalla decisiva en la guerra contra el terror, sabiendo que la organización criminal –liderada por un personaje sobradamente conocido por Batman– ofrece una cuantiosa recompensa por la cabeza de Damian Wayne...\rHistorias:\r\nImagen de marca / Estrella demoníaca / El ojo de la Gorgona / El ahorcado / Zona asesina','\r',char(13)),'\n',char(10)),NULL,NULL,120,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775572952712-cr0lzw.jpg','read',0,NULL,NULL,'2026-04-07 14:42:36','2026-04-07 17:38:14',79,NULL,'Rústica','[{"name":"Grant Morrison","role":"Guion"},{"name":"Chris Burnham","role":"Guion, Dibujo, Tinta"},{"name":"Frazer Irving","role":"Dibujo, Tinta, Color"},{"name":"Nathan Fairbairn","role":"Color"},{"name":"Frank Quitely","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(431,'Batman Inc. #2','Batman Inc.',2,NULL,'978-8-415-92526-2',NULL,'Grant Morrison','Andrés Guinaldo',NULL,NULL,'ECC Ediciones',NULL,'2013-08-01',NULL,NULL,replace(replace('Contiene Batman Incorporated vol.2 #5-8 USA\r\nCon una red de agentes infiltrados en los más influyentes puestos de Gotham City, Leviatán continuó con el proceso de adoctrinamiento destinado a sumar fieles a su causa. Precisamente para obtener información sobre la organización terrorista liderada por Talia al Ghul, Batman retomó el disfraz del hampón Cerillas Malone, cayendo víctima de una emboscada. Desafiando las órdenes de su padre, Damian abandonó la seguridad de la batcueva para, como Redbird, salir en su ayuda. Una exitosa misión que, sin embargo, podría marcar un antes y un después en la carrera superheroica del Chico Maravilla...\r\nHistorias:\r\nManicomio / Guirnalda de calaveras / El vientre de la ballena / El regreso del chico maravilla','\r',char(13)),'\n',char(10)),NULL,NULL,120,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775572964826-vf1uix.jpg','read',0,NULL,NULL,'2026-04-07 14:42:45','2026-04-07 17:38:14',79,NULL,'Rústica','[{"name":"Grant Morrison","role":"Guion"},{"name":"Andrés Guinaldo","role":"Dibujo"},{"name":"Chris Burnham","role":"Dibujo, Tinta"},{"name":"Jason Masters","role":"Dibujo, Tinta"},{"name":"Bit","role":"Tinta"},{"name":"Nathan Fairbairn","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(432,'Batman Inc. #3','Batman Inc.',3,NULL,'978-8-415-92581-1',NULL,'Grant Morrison','Chris Burnham',NULL,NULL,'ECC Ediciones',NULL,'2013-10-01',NULL,NULL,replace(replace('Contiene Batman Incorporated vol.2 #9-13 USA\r\nAcompañada de su inseparable Hereje y con Batman como prisionero, Talia se dirigió hacia la sede de Empresas Wayne en Gotham para afrontar la fase decisiva del gran plan de Leviatán: la utilización del Oroboro, detonador de la bomba definitiva ideada por Otto Netz. Red Robin, Wingman, Nightwing y Robin coordinaron sus esfuerzos para tratar de neutralizar la amenaza, y se produjo un enfrentamiento que terminó de forma dramática. Con el Hombre Murciélago ya liberado y devastado por la pérdida, ha llegado el momento de saldar cuentas pendientes.','\r',char(13)),'\n',char(10)),NULL,NULL,120,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775572967410-tbc9iw.jpg','read',0,NULL,NULL,'2026-04-07 14:42:48','2026-04-07 17:38:14',79,NULL,'Rústica','[{"name":"Grant Morrison","role":"Guion"},{"name":"Chris Burnham","role":"Guion, Dibujo, Tinta"},{"name":"Jason Masters","role":"Dibujo, Tinta"},{"name":"Jorge Lucas","role":"Dibujo, Tinta"},{"name":"Andrei Bressan","role":"Dibujo, Tinta"},{"name":"Nathan Fairbairn","role":"Color"},{"name":"Hi-Fi Desing","role":"Color"},{"name":"Ian Hannin","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(433,'Batman Eterno #1','Batman Eterno',1,NULL,'978-8-416-19485-8',NULL,'James Tynion IV','Jason Fabok',NULL,NULL,'ECC Ediciones',NULL,'2014-10-01',NULL,NULL,replace(replace('Recopila Batman Eternal #1-4 USA\r\nBatman Eternal es una serie de 52 números de publicación semanal en EEUU, cuya conclusión está prevista para marzo de 2015 en Estados Unidos, aunque ya se ha anunciado que tras una pausa habrá una &quot;segunda temporada&quot; de la serie, también con periodicidad semanal.','\r',char(13)),'\n',char(10)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775573027958-aj2l6g.jpg','read',0,NULL,NULL,'2026-04-07 14:43:51','2026-04-07 17:38:14',80,23.95,'Rústica','[{"name":"James Tynion IV","role":"Guion"},{"name":"John Layman","role":"Guion"},{"name":"Ray Fawkes","role":"Guion"},{"name":"Scott Snyder","role":"Guion"},{"name":"Tim Seeley","role":"Guion"},{"name":"Jason Fabok","role":"Dibujo"},{"name":"Dustin Nguyen","role":"Dibujo"}]');
