INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(435,'Batman Eterno #3','Batman Eterno',3,NULL,'978-8-416-25553-5',NULL,'James Tynion IV','Guillem March',NULL,NULL,'ECC Ediciones',NULL,'2014-11-28',NULL,NULL,replace(replace('Recopila Batman Eternal #9-12 USA\r\n&quot;Red Robin y Harper Row investigan un misterioso virus en los Narrows, Batwing y Jim Corrigan tratan de esclarecer los feno´menos extran~os del Asilo Arkham y la guerra entre criminales se recrudece: Carmine Falcone destruye el Casino Iceberg y el Profesor Pyg la sede de Rhodes Motors. Sin embargo, en el Departamento de Policía parecen empen~ados en arrestar a Batman... que acaba de viajar a Hong Kong para averiguar lo ocurrido alli´ con Falcone durante su ausencia de Gotham City.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775573045757-ubd0yw.jpg','read',0,NULL,NULL,'2026-04-07 14:44:06','2026-04-07 17:38:14',80,NULL,'Rústica','[{"name":"James Tynion IV","role":"Guion"},{"name":"John Layman","role":"Guion"},{"name":"Ray Fawkes","role":"Guion"},{"name":"Scott Snyder","role":"Guion"},{"name":"Tim Seeley","role":"Guion"},{"name":"Guillem March","role":"Dibujo"},{"name":"Riccardo Burchielli","role":"Dibujo"},{"name":"Ian Bertram","role":"Dibujo"},{"name":"Mikel Janin","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(436,'Batman Eterno #4','Batman Eterno',4,NULL,'978-8-416-25593-1',NULL,'James Tynion IV','Dustin Nguyen',NULL,NULL,'ECC Ediciones',NULL,'2014-12-31',NULL,NULL,replace('Recopila Batman Eternal #13-16 USA\r&quot;Al volver de Hong Kong, Batman no solo trae respuestas sobre lo que allí hizo Falcone, sino también a una pasajera imprevista. Mientras el juicio contra Jim Gordon sigue en la ciudad, es su hija, Batgirl, la que busca en América del Sur pruebas de la inocencia del excomisario. Poco sospecha Gordon que será él mismo quien reciba la visita más inesperada de todas en la Penitenciaría de Blackgate…&quot;','\r',char(13)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775573050194-xf7j9l.jpg','read',0,NULL,NULL,'2026-04-07 14:44:10','2026-04-07 17:38:14',80,NULL,'Rústica','[{"name":"James Tynion IV","role":"Guion"},{"name":"John Layman","role":"Guion"},{"name":"Ray Fawkes","role":"Guion"},{"name":"Scott Snyder","role":"Guion"},{"name":"Tim Seeley","role":"Guion"},{"name":"Dustin Nguyen","role":"Dibujo"},{"name":"Jason Fabok","role":"Dibujo"},{"name":"Mikel Janin","role":"Dibujo"},{"name":"Guillermo Ortego","role":"Tinta"}]');
