INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(438,'Batman Eterno #6','Batman Eterno',6,NULL,'978-8-416-30387-8',NULL,'James Tynion IV','Andy Clarke',NULL,NULL,'ECC Ediciones',NULL,'2015-02-25',NULL,NULL,replace('Recopila Batman Eternal #21-24 USA\r&quot;En Río de Janeiro, Batgirl, Capucha Roja y Batwoman obtienen pruebas de la inocencia de Jim Gordon. Bard, Killer Croc y Batman se adentran en las cloacas de Gotham para rescatar a la pequeña Jade. Y durante un motín en Blackgate, el compañero de celda de Gordon realiza una sorpredente revelación.&quot;','\r',char(13)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775573057859-x2d9p3.jpg','read',0,NULL,NULL,'2026-04-07 14:44:18','2026-04-07 17:38:14',80,NULL,'Rústica','[{"name":"James Tynion IV","role":"Guion"},{"name":"John Layman","role":"Guion"},{"name":"Ray Fawkes","role":"Guion"},{"name":"Scott Snyder","role":"Guion"},{"name":"Tim Seeley","role":"Guion"},{"name":"Andy Clarke","role":"Dibujo"},{"name":"Dustin Nguyen","role":"Dibujo"},{"name":"Jason Fabok","role":"Dibujo"},{"name":"Jorge Lucas","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(439,'Batman Eterno #7','Batman Eterno',7,NULL,'978-8-416-37432-8',NULL,'James Tynion IV','R. M. Guéra',NULL,NULL,'ECC Ediciones',NULL,'2015-03-25',NULL,NULL,replace('Recopila Batman Eternal #25-28 USA\rLa amenaza en la sombra se revela, atacando la Mansión Wayne y dejando indefenso a Alfred tras inyectarle una sobredosis de la Toxina del Miedo del Espantapájaros. No obstante, el mayordomo tuvo tiempo de poner a salvo antes a su hija, Julia. Mientras tanto, Stephanie Brown consigue lo que parece su primera gran victoria...','\r',char(13)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775573060970-0lskcl.jpg','read',0,NULL,NULL,'2026-04-07 14:44:21','2026-04-07 17:38:14',80,NULL,'Rústica','[{"name":"James Tynion IV","role":"Guion"},{"name":"John Layman","role":"Guion"},{"name":"Ray Fawkes","role":"Guion"},{"name":"Scott Snyder","role":"Guion"},{"name":"Tim Seeley","role":"Guion"},{"name":"R. M. Guéra","role":"Dibujo"},{"name":"Juan Ferreyra","role":"Dibujo"},{"name":"Javier Garrón","role":"Dibujo"},{"name":"Meghan Hetrick","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(440,'Batman Eterno #8','Batman Eterno',8,NULL,'978-8-416-37477-9',NULL,'Scott Snyder','Simon Coleby',NULL,NULL,'ECC Ediciones',NULL,'2015-04-29',NULL,NULL,replace(replace('Recopila Batman Eternal #29-33 USA\r\n&quot;Nueva entrega de esta serie coral, que saca todo el partido a la mitología del Cruzado de la Capa y a su elenco de secundarios, aliados y enemigos. Este mes, jugarán un papel especialmente importante Alfred Pennyworth, Jim Corrigan, la Hija del Joker, Batwing, el diácono Blackfire, Bane y Silencio.	\r\nPublicada en Estados Unidos como serie semanal, Batman Eterno nos traslada a la Gotham City de un futuro tan cercano como desalentador. ¿Cómo se ha llegado a esa situación? Para responder a dicho interrogante, Batman Eterno cuenta con un equipo creativo colectivo encabezado por el mismísimo Scott Snyder, gran arquitecto de las aventuras contemporáneas del Caballero Oscuro.	&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775573063864-v98ygk.jpg','read',0,NULL,NULL,'2026-04-07 14:44:24','2026-04-07 17:37:48',80,NULL,'Rústica','[{"name":"Simon Coleby","role":"Dibujo"},{"name":"Fernando Pasarín","role":"Dibujo"},{"name":"Jason Fabok","role":"Dibujo"},{"name":"Scott Snyder","role":"Guion"},{"name":"James Tynion IV","role":"Guion"},{"name":"Tim Seeley","role":"Guion"},{"name":"Kyle Higgins","role":"Guion"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(441,'Batman Eterno #9','Batman Eterno',9,NULL,'978-8-416-40927-3',NULL,'James Tynion IV','Alvaro Martinez Bueno',NULL,NULL,'ECC Ediciones',NULL,'2015-05-27',NULL,NULL,replace(replace('Recopila Batman Eternal #34 a 38 USA. En EEUU la serie acabó en el #52, y se ha anunciado una &quot;segunda temporada&quot; para más adelante.\r\n&quot;Batman Eterno afronta una fase decisiva, con Empresas Wayne en grave peligro y Batman enfrentado al Departamento de Policía de Gotham City. Además, Vicki Vale descubre un secreto que podría dar un giro inesperado a la trama, en la que Catwoman y Bane vuelven a irrumpir con fuerza.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775573066975-nixpjs.jpg','read',0,NULL,NULL,'2026-04-07 14:44:27','2026-04-07 17:37:48',80,NULL,'Rústica','[{"name":"James Tynion IV","role":"Guion"},{"name":"Kyle Higgins","role":"Guion"},{"name":"Ray Fawkes","role":"Guion"},{"name":"Scott Snyder","role":"Guion"},{"name":"Tim Seeley","role":"Guion"},{"name":"Alvaro Martinez Bueno","role":"Dibujo"},{"name":"Andrea Mutti","role":"Dibujo"},{"name":"Fernando Blanco","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(442,'Batman Eterno #10','Batman Eterno',10,NULL,'978-8-416-40977-8',NULL,'James Tynion IV','David Lafuente',NULL,NULL,'ECC Ediciones',NULL,'2015-07-01',NULL,NULL,replace(replace('Recopila Batman Eternal #39 a 43 (de 52) USA\r\n&quot;Con tan solo dos entregas más por delante, esta sorprendente serie coral afronta una fase decisiva: El Acertijo parece haber descubierto quién está detrás del plan para destrozar Gotham City, pero… ¿está dispuesto a compartir tan preciada información?&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775573069662-xtnvb8.jpg','read',0,NULL,NULL,'2026-04-07 14:44:30','2026-04-07 17:37:48',80,NULL,'Rústica','[{"name":"James Tynion IV","role":"Guion"},{"name":"Kyle Higgins","role":"Guion"},{"name":"Ray Fawkes","role":"Guion"},{"name":"Scott Snyder","role":"Guion"},{"name":"Tim Seeley","role":"Guion"},{"name":"David Lafuente","role":"Dibujo"},{"name":"Davide Furnò","role":"Dibujo"},{"name":"Félix Ruiz","role":"Dibujo"},{"name":"Goran Sudzuka","role":"Dibujo"},{"name":"Jed Dougherty","role":"Dibujo"},{"name":"Joe Quinones","role":"Dibujo"},{"name":"Paolo Armitano","role":"Dibujo"},{"name":"Roger Robinson","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(443,'Batman Eterno #11','Batman Eterno',11,NULL,'978-8-416-47510-0',NULL,'James Tynion IV','Aco',NULL,NULL,'ECC Ediciones',NULL,'2015-07-27',NULL,NULL,'EDICIÓN ORIGINAL: Batman Eternal núms. 44 a 47 USA  Afrontamos la recta final de Batman eterno, con la certeza de que el equipo creativo de esta serie coral nos deparará alguna que otra sorpresa. Si quieres estar al tanto de qué deparará el futuro al Hombre Murciélago, sus aliados y enemigos, ¡no te pierdas esta colección!',NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775573072185-upu8jt.jpg','read',0,NULL,NULL,'2026-04-07 14:44:32','2026-04-07 17:37:48',80,NULL,'Rústica','[{"name":"James Tynion IV","role":"Guion"},{"name":"Kyle Higgins","role":"Guion"},{"name":"Ray Fawkes","role":"Guion"},{"name":"Scott Snyder","role":"Guion"},{"name":"Tim Seeley","role":"Guion"},{"name":"Aco","role":"Dibujo"},{"name":"Alessandro Vitti","role":"Dibujo"},{"name":"Christian Duce","role":"Dibujo"},{"name":"Javi Fernández","role":"Dibujo"},{"name":"Juan Ferreyra","role":"Dibujo"},{"name":"Ronan Cliquet","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(444,'Batman Eterno #12','Batman Eterno',12,NULL,'978-8-416-47544-5',NULL,'James Tynion IV','Tim Seeley',NULL,NULL,'ECC Ediciones',NULL,'2015-08-26',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman Eternal núms. 48 a 52 USA\r\nEste mes finaliza la colección Batman eterno, con Gotham en llamas, los villanos campando a sus anchas por las calles de la ciudad y el genio criminal que desencadenó semejante situación decidido a llevar su malvado plan hasta sus últimas consecuencias.','\r',char(13)),'\n',char(10)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775573074367-rta1xk.jpg','read',0,NULL,NULL,'2026-04-07 14:44:35','2026-04-07 17:37:48',80,NULL,'Rústica','[{"name":"James Tynion IV","role":"Guion"},{"name":"Kyle Higgins","role":"Guion"},{"name":"Ray Fawkes","role":"Guion"},{"name":"Scott Snyder","role":"Guion"},{"name":"Tim Seeley","role":"Guion, Dibujo"},{"name":"Alvaro Martinez Bueno","role":"Dibujo"},{"name":"David Lafuente","role":"Dibujo"},{"name":"Eduardo Pansica","role":"Dibujo"},{"name":"Fernando Blanco","role":"Dibujo"},{"name":"Robson Rocha","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(445,'Mighty Morphin Power Rangers vs. Las Tortugas Ninja #1','Mighty Morphin Power Rangers vs. Las Tortugas Ninja',1,NULL,'978-8-418-95539-6',NULL,'Ryan Parrott','Simone Di Meo',NULL,NULL,'Moztros',NULL,'2022-09-08',NULL,NULL,replace(replace('Contiene Mighty Morphin Power Rangers: Teenage Mutant Ninja Turtles #1-5\r\n¡LOS POWER RANGERS VS LAS TORTUGAS NINJA EN UNA BATALLA POR EL DESTINO DE LA TIERRA! Los Power Rangers llegan a la ciudad de Nueva York tras la pista de Tommy Oliver, el Green Ranger, quien se encuentra desaparecido. ¡Aunque al poco tiempo se lo ve luchando lado a lado con el malvado Shredder y el Clan del Pie! Pero los Rangers también tendrán que lidiar con una inesperada aparición... ¡las Tortugas Ninja! ¿Podrán estos héroes encontrar la forma de trabajar juntos para derrotar a los villanos y salvar al mundo de su destrucción total?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775573145619-np530h.jpg','read',0,NULL,NULL,'2026-04-07 14:45:46','2026-04-07 17:37:48',62,NULL,'tapa dura','[{"name":"Ryan Parrott","role":"Guion"},{"name":"Simone Di Meo","role":"Dibujo, Tinta"},{"name":"Walter Baiamonte","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(446,'¡Shazam! DC Premiere. #1','¡Shazam! DC Premiere.',1,NULL,'979-1-370-13380-1',NULL,'Mark Waid','Dan Mora',NULL,NULL,'Panini Comics España',NULL,'2025-12-18',NULL,NULL,replace(replace('Contiene: Shazam! vol. 5 #1-6\r\nEl superequipo creativo compuesto por Mark Waid y Dan Mora te trae más magia! ¡Dinosaurios del espacio! ¡Gusanos homicidas y tigres parlantes! ¡Robots atómicos, mundos alienígenas, científicos locos, siniestras maldiciones y villanos traídos de todo el Universo DC! Todos ellos te dan la bienvenida a las salvajes aventuras de Billy Batson, cuyo enorme alter ego carmesí defiende la Tierra de las amenazas más extrañas. Si quieres parar a Lex Luthor o al Joker, llama a Superman o a Batman. Para crisis internacionales, acude a Wonder Woman. Pero cuando Garguax, Emperador de la Luna, se dirige a Ciudad Gorila, toca gritar “¡Shazam!”.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579265597-hht70f.jpg','read',0,NULL,NULL,'2026-04-07 16:27:49','2026-04-07 17:37:48',81,14,'Rústica','[{"name":"Mark Waid","role":"Guion"},{"name":"Dan Mora","role":"Guion, Dibujo, Tinta"},{"name":"Alejandro Sánchez","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(447,'DC One-Shot #9','DC One-Shot',9,NULL,'979-1-370-13284-2',NULL,'Jamal Campbell','Jamal Campbell',NULL,NULL,'Panini Comics España',NULL,'2025-11-06',NULL,NULL,replace(replace('Contiene Zatanna números 1-6\r\n¡La nueva gira de Zatanna, en un espectacular volumen a cargo del formidable Jamal Campbell (Far Sector)! Zatanna ha reunido al equipo y comienza con ganas este nuevo capítulo de su vida. Sin embargo, los planes se irán a pique antes siquiera de dar el primer paso. Una nueva adversaria secuestra a los suyos y enredará a Zatanna en nuevos trucos y maquinaciones.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579322413-evc6h5.jpg','read',0,3,NULL,'2026-04-07 16:28:45','2026-04-07 17:37:48',82,12,'lujo','[{"name":"Jamal Campbell","role":"Guion, Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(448,'DC One-Shot #5','DC One-Shot',5,NULL,'979-1-370-13115-9',NULL,'Dan Watters','Hayden Sherman',NULL,NULL,'Panini Comics España',NULL,'2025-08-07',NULL,NULL,replace(replace('Contiene: Batman: Dark Patterns 1-6\r\nAcompaña a Batman por los más peligrosos rincones de Gotham en uno de sus primeros casos, que le llevará al límite física y mentalmente al ver crecer la cifra de víctimas de un brutal asesino en serie. La tortura a la que somete a sus víctimas oculta algo más que sadismo, algo más que su violento deseo. Ambientada en los primeros años de la carrera de Batman, esta historia explora los misterios que definirían al mejor detective del mundo.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579332556-pqd245.jpg','read',0,NULL,NULL,'2026-04-07 16:28:53','2026-04-07 17:37:48',82,NULL,'Rústica','[{"name":"Dan Watters","role":"Guion"},{"name":"Hayden Sherman","role":"Dibujo, Tinta"},{"name":"Triona Farrell","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(449,'DC One-Shot #10','DC One-Shot',10,NULL,'979-1-370-13285-9',NULL,'Al Ewing','Steve Lieber',NULL,NULL,'Panini Comics España',NULL,'2025-11-13',NULL,NULL,replace(replace('Contiene Metamorpho: The Element Man 1-6\r\nAl Ewing y Steve Lieber presentan un enlace covalente entre amigos y enemigos, en un volumen protagonizado por Rex Mason, la rareza chalada capaz de convertirse en cualquier elemento del cuerpo humano. Descubre las aventuras de Metamorfo en la mejor de las compañías y enfrentado a un adversario a su medida.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579336838-tebc1e.jpg','read',0,3,NULL,'2026-04-07 16:28:58','2026-04-07 17:37:48',82,NULL,'Rústica','[{"name":"Steve Lieber","role":"Dibujo"},{"name":"Al Ewing","role":"Guion"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(450,'DC One-Shot #15','DC One-Shot',15,NULL,'979-1-370-13617-8',NULL,'Dan Watters','Hayden Sherman',NULL,NULL,'Panini Comics España',NULL,'2026-04-01',NULL,NULL,replace(replace('Contiene: Batman: Dark Patterns 7-12 \r\n¡Nuevos casos para el Hombre Murciélago! Primero, un cadáver aparece incinerado en el corazón de uno de los más antiguos barrios de Gotham, y el Detective Oscuro se ve envuelto en una retorcida investigación de asesinato que nos lleva de vuelta a los primeros días de la Banda de la Capucha Roja. Después, un misterioso pirómano ha ido guiando en secreto el crecimiento de Gotham y Batman, desde las sombras... y, ahora, su oscuro diseño llega a la fase final. ¿Completará con éxito su obra o se verá truncado por el mejor detective del mundo?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579342977-55vhps.jpg','unread',0,NULL,NULL,'2026-04-07 16:29:03','2026-04-07 16:29:03',82,NULL,'Rústica','[{"name":"Dan Watters","role":"Guion"},{"name":"Hayden Sherman","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(451,'All in Aquaman #1','All in Aquaman',1,NULL,'9773081601008-00001',NULL,'Jeremy Adams','John Timms',NULL,NULL,'Panini Comics España',NULL,'2025-09-11',NULL,NULL,replace(replace('Edición original Aquaman 1-3\r\nDespués de los sucesos de Absolute Power, los poderes de Arthur Curry han aumentado en escala y no dudará en usarlos. De cada uno de los siete mares han surgido Kaijus que sólo el rey puede detener con sus habilidades sobre el agua... ¡pero para eso tiene que hacer que no lo maten en el proceso! Y para eso está Dagon, su guía en este mortal viaje lleno de secretos.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579395516-0fq1f5.jpg','read',0,NULL,NULL,'2026-04-07 16:29:57','2026-04-07 17:37:48',83,NULL,'Rústica','[{"name":"Jeremy Adams","role":""},{"name":"John Timms","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(452,'All in Aquaman #2','All in Aquaman',2,NULL,'9773081601008-00002',NULL,'Jeremy Adams','Michael Shelfer',NULL,NULL,'Panini Comics España',NULL,'2025-12-11',NULL,NULL,replace(replace('Contiene: Aquaman 4-6\r\nAquaman bucea en torno al misterio de la infección del azul, y puede que esto genere una alianza maldita con una sirena asesina o tenga algo que ver con piratas y profecías... Las revelaciones se disparan en tanto que nuestro héroe trata de no verse seducido por el gran azul, y más allá de la posibilidad de un devastador fin del trayecto... la esperanza de salvar a su gente sigue viva.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579400304-b5t6fw.jpg','read',0,NULL,NULL,'2026-04-07 16:30:00','2026-04-07 17:37:48',83,NULL,'Rústica','[{"name":"Jeremy Adams","role":"Guion"},{"name":"Michael Shelfer","role":"Dibujo"},{"name":"John Timms","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(453,'All In Los Nuevos Dioses #1','All In Los Nuevos Dioses',1,NULL,'9773081503005-00001',NULL,'Ram V','Evan Cagle',NULL,NULL,'Panini Comics España',NULL,'2025-08-07',NULL,NULL,replace(replace('Contiene The New Gods números 1 a 3 publicados en USA por DC Comics.\r\nRam V y Evan Cagle acercan el Cuarto Mundo a toda una nueva generación, con una épica de proporciones cósmicas. Las reverberaciones de la muerte de un viejo dios se sienten en todo el universo, despertando ejércitos intergalácticos y los letárgicos poderes de un misterioso niño terrestre. Todo esto fue vaticinado en la profecía de la Fuente con la que su agente, Metrón, sume a los habitantes de Nueva Génesis y Apókolips en el caos... Mientras, en la Tierra, Scott Free y Barda se enfrentan al desafío de la paternidad.','\r',char(13)),'\n',char(10)),NULL,NULL,72,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579420155-7kijj2.jpg','read',0,NULL,NULL,'2026-04-07 16:30:22','2026-04-07 17:37:48',84,6.5,'grapa','[{"name":"Ram V","role":"Guion"},{"name":"Evan Cagle","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(454,'All In Los Nuevos Dioses #2','All In Los Nuevos Dioses',2,NULL,'9773081503005-00002',NULL,'Ram V','Evan Cagle',NULL,NULL,'Panini Comics España',NULL,'2025-11-06',NULL,NULL,replace(replace('Contiene The New Gods números 4 a 6 publicados en USA por DC Comics.\r\nNueva Génesis. Apókolips. La Tierra. Estos tres mundos se verán arrollados por la llegada de los inquisidores interestelares: los Nyctari. La única esperanza reside en un chaval con los poderes de un dios. ¿Será el salvador... o la reencarnación del mayor mal conocido? Sea como fuere, Mister Miracle y Big Barda deberán proteger a Kamal... y un dios caerá.','\r',char(13)),'\n',char(10)),NULL,NULL,72,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579429882-dic5b7.jpg','read',0,NULL,NULL,'2026-04-07 16:30:30','2026-04-07 17:37:48',84,6.5,'Rústica','[{"name":"Ram V","role":"Guion"},{"name":"Evan Cagle","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(455,'All In Los Nuevos Dioses #3','All In Los Nuevos Dioses',3,NULL,'9773081503005-00003',NULL,'Ram V','Evan Cagle',NULL,NULL,'Panini Comics España',NULL,'2026-02-05',NULL,NULL,replace(replace('Contiene The New Gods números 7 a 9 publicados en USA por DC Comics.\r\nNueva Génesis ha caído, los Nuevos Dioses han perdido su hogar y en su destino se cruza la Tierra, con sus propios habitantes, protectores e inmortales. Su acogida se verá afectada por las dudas de la Liga de la Justicia y el destino de Kamal, el nuevo Nuevo Dios, a quien rodea cierta profecía...','\r',char(13)),'\n',char(10)),NULL,NULL,72,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579432277-kd87p2.jpg','read',0,NULL,NULL,'2026-04-07 16:30:33','2026-04-07 17:37:48',84,6.5,'Rústica','[{"name":"Ram V","role":"Guion"},{"name":"Evan Cagle","role":""},{"name":"Pye Parr","role":""}]');
