INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(457,'Absolute Evil','Absolute Evil',NULL,NULL,'979-1-370-13616-1',NULL,'Al Ewing','Giuseppe Camuncoli',NULL,NULL,'Panini Comics España',NULL,'2026-04-01',NULL,NULL,replace(replace('Contiene: Absolute Evil One-Shot\r\nAl Ewing y Giuseppe Camuncoli arrojan luz sobre los villanos del Universo Absolute: Ra’s al Ghul, Veronica Cale, Hector Hammond, Elenore Thawne y un misterioso nuevo Joker se presentan como una fuerza unida. Sin embargo, las cosas no tardarán en descontrolarse. No te pierdas este especial que, además, trae el debut de dos grandes personajes que darán forma al Universo Absolute en su segundo año de vida','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579579620-y4ewzg.jpg','read',0,NULL,NULL,'2026-04-07 16:33:01','2026-04-12 12:19:57',NULL,3.8,'Grapa','[{"name":"Al Ewing","role":"Guion"},{"name":"Giuseppe Camuncoli","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(458,'Absolute Superman #3','Absolute Superman',3,NULL,'9773081287004-00003',NULL,'Jason Aaron','Rafa Sandoval',NULL,NULL,'Panini Comics España',NULL,'2025-06-05',NULL,NULL,replace(replace('Contiene Absolute Superman 3\r\nAños atrás, en Krypton, Jor-El y Lara estaban convencidos de que su planeta se encaminaba a un cataclismo. ¿Qué podían hacer ellos, dos peones del Gremio de Trabajadores, para salvar a toda su especie? La respuesta a esa pregunta no es la que puedas imaginarte…','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579614031-1rh57t.jpg','read',0,NULL,NULL,'2026-04-07 16:33:34','2026-04-07 17:37:48',8,NULL,'grapa','[{"name":"Jason Aaron","role":"Guion"},{"name":"Rafa Sandoval","role":"Dibujo, Tinta"},{"name":"Ulises Arreola","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(459,'Absolute Superman #4','Absolute Superman',4,NULL,'9773081287004-00004',NULL,'Jason Aaron','Rafa Sandoval',NULL,NULL,'Panini Comics España',NULL,'2025-07-03',NULL,NULL,replace(replace('Contiene: Absolute Superman 4\r\nKal-El ha emprendido la huida´, perseguido a lo largo y ancho del mundo por Pacificadores armados y por Lois Lane, la mejor agente de campo de Lázaro. Ahora, una nueva fuerza se une a la cacería: los misteriosos Hombres Omega… ¿serán amigos o enemigos?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579615936-29h938.jpg','read',0,NULL,NULL,'2026-04-07 16:33:36','2026-04-07 17:37:48',8,NULL,'grapa','[{"name":"Jason Aaron","role":"Guion"},{"name":"Rafa Sandoval","role":"Dibujo, Tinta"},{"name":"Ulises Arreola","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(460,'Absolute Superman #5','Absolute Superman',5,NULL,'9773081287004-00005',NULL,'Jason Aaron','Rafa Sandoval',NULL,NULL,'Panini Comics España',NULL,'2025-08-07',NULL,NULL,replace(replace('Contiene: Absolute Superman 5\r\nKal-El vive una vida feliz con sus padres en las Tierras Rojas de Krypton. Pero, con toda su existencia bajo amenaza, los El no tendrán más opción que posicionarse... Y luchar por la verdad.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579617627-gdv3ib.jpg','read',0,NULL,NULL,'2026-04-07 16:33:38','2026-04-07 17:37:48',8,NULL,'grapa','[{"name":"Jason Aaron","role":"Guion"},{"name":"Rafa Sandoval","role":"Dibujo, Tinta"},{"name":"Ulises Arreola","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(461,'Absolute Superman #6','Absolute Superman',6,NULL,'9773081287004-00006',NULL,'Jason Aaron','Carmine Di Giandomenico',NULL,NULL,'Panini Comics España',NULL,'2025-09-04',NULL,NULL,replace(replace('Contiene: Absolute Superman 6\r\nHace años, algo extraño ocurrió en el corazón de Estados Unidos. Algo trajo temor y oscuridad a un pequeño pueblo de Kansas... y cambió para siempre la vida de una bondadosa pareja. Bienvenido a Smallville.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579619218-26rb7h.jpg','read',0,NULL,NULL,'2026-04-07 16:33:40','2026-04-07 17:37:48',8,NULL,'Grapa','[{"name":"Jason Aaron","role":"Guion"},{"name":"Carmine Di Giandomenico","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(462,'Absolute Superman #7','Absolute Superman',7,NULL,'9773081287004-00007',NULL,'Jason Aaron','Carmine Di Giandomenico',NULL,NULL,'Panini Comics España',NULL,'2025-10-02',NULL,NULL,replace(replace('Contiene: Absolute Superman 7 \r\nLa Corporación Lázaro le ha robado la tecnología que la ha llevado al éxito mundial, mientras él opera desde una guarida oculta, con ciudades embotelladas que tortura sin descanso. ¿Quién es el misterioso Brainiac? ¿Y por qué está tan interesado en el Último Hijo de Krypton?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579621136-r978ld.jpg','read',0,NULL,NULL,'2026-04-07 16:33:41','2026-04-07 17:37:48',8,NULL,'Grapa','[{"name":"Jason Aaron","role":"Guion"},{"name":"Carmine Di Giandomenico","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(463,'Absolute Superman #8','Absolute Superman',8,NULL,'9773081287004-00008',NULL,'Jason Aaron','Rafa Sandoval',NULL,NULL,'Panini Comics España',NULL,'2025-11-06',NULL,NULL,replace(replace('Contiene: Absolute Superman 8\r\nComienza el siguiente arco argumental, con Superman entre dos fuerzas opuestas, la nefasta Corporación Lázaro y los misteriosos Hombres Omega. Kal-El solo quiere que lo dejen en paz en el único lugar de este planeta en el que se siente a salvo: Smallville.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579622919-ldl85c.jpg','read',0,NULL,NULL,'2026-04-07 16:33:44','2026-04-07 17:37:48',8,NULL,'grapa','[{"name":"Jason Aaron","role":"Guion"},{"name":"Rafa Sandoval","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(464,'Absolute Superman #9','Absolute Superman',9,NULL,'9773081287004-00009',NULL,'Jason Aaron','Rafa Sandoval',NULL,NULL,'Panini Comics España',NULL,'2025-12-04',NULL,NULL,replace(replace('Contiene: Absolute Superman 9\r\nLos misteriosos Hombres Omega han perseguido a Superman por todo el mundo, determinados a que se les escuche: solo con su ayuda y con su terrorífico poder podrán acabar con la Corporación Lázaro. Y, con su corazón lleno de rabia, Kal comienza a estar dispuesto a escuchar...','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579625552-rtqlfk.jpg','read',0,NULL,NULL,'2026-04-07 16:33:46','2026-04-07 17:37:48',8,NULL,'grapa','[{"name":"Jason Aaron","role":"Guion"},{"name":"Rafa Sandoval","role":"Dibujo"},{"name":"Fico Ossio","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(465,'Absolute Superman #10','Absolute Superman',10,NULL,'9773081287004-00010',NULL,'Jason Aaron','Carmine Di Giandomenico',NULL,NULL,'Panini Comics España',NULL,'2026-01-08',NULL,NULL,replace(replace('Contiene: Absolute Superman 10\r\nEl verdadero enemigo de Superman ha sido revelado. El infame Ra’s al Ghul, líder de la Corporación Lázaro, asesino de millones, tiene planes para el Último Hijo de Krypton. ¿Qué oscuro poder desatará la ira de Kal-El?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579627527-nk68w3.jpg','read',0,NULL,NULL,'2026-04-07 16:33:48','2026-04-07 17:37:48',8,NULL,'Grapa','[{"name":"Jason Aaron","role":"Guion"},{"name":"Carmine Di Giandomenico","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(466,'Absolute Superman #11','Absolute Superman',11,NULL,'9773081287004-00011',NULL,'Jason Aaron','Carmine Di Giandomenico',NULL,NULL,'Panini Comics España',NULL,'2026-02-05',NULL,NULL,replace(replace('Contiene: Con Absolute Superman 11\r\nSuperman lleva cinco años huyendo, siendo perseguido por todo el planeta, como si de un criminal se tratase... pero su único crimen es haber nacido en otro lugar. Ahora, su rabia en respuesta a Ra','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579629568-pvkf2d.jpg','read',0,NULL,NULL,'2026-04-07 16:33:50','2026-04-07 17:37:48',8,NULL,'grapa','[{"name":"Jason Aaron","role":"Guion"},{"name":"Carmine Di Giandomenico","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(467,'Absolute Superman #12','Absolute Superman',12,NULL,'9773081287004-00012',NULL,'Jason Aaron','Rafa Sandoval',NULL,NULL,'Panini Comics España',NULL,'2026-03-05',NULL,NULL,replace(replace('Contiene: Con Absolute Superman 12\r\nComienza la invasión de Kansas. Nadie puede desafiar la voluntad de Ra','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579631321-6cauai.jpg','read',0,NULL,NULL,'2026-04-07 16:33:51','2026-04-07 17:37:48',8,NULL,'grapa','[{"name":"Jason Aaron","role":"Guion"},{"name":"Rafa Sandoval","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(468,'Absolute Superman #13','Absolute Superman',13,NULL,'9773081287004-00013',NULL,'Jason Aaron','Rafa Sandoval',NULL,NULL,'Panini Comics España',NULL,'2026-04-01',NULL,NULL,replace(replace('Contiene: Con Absolute Superman 13\r\nComienza la Batalla de Kansas, con los tanques de la Corporación Lázaro recorriendo las calles de Smallville. Debilitado por Brainiac y Ra','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579633049-wefkuf.jpg','read',0,NULL,NULL,'2026-04-07 16:33:53','2026-04-12 12:19:57',8,NULL,'Grapa','[{"name":"Jason Aaron","role":"Guion"},{"name":"Rafa Sandoval","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(469,'Absolute Wonder Woman #1','Absolute Wonder Woman',1,NULL,'9773081289008-00001',NULL,'Kelly Thompson','Hayden Sherman',NULL,NULL,'Panini Comics España',NULL,'2025-04-03',NULL,NULL,replace(replace('Contiene Absolute Wonder Woman 1\r\nLa trinidad DC no está completa sin ella, pero sin la Isla Paraíso, sin la hermandad que la crio, sin su misión pacífica… ¡Esta es la Princesa Amazona en su versión Absolute! Y, con su montura tan negra como la magia en la que fue instruida, desde las profundidades del Hades luchará por recuperar lo que le arrebataron los dioses.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579656610-on555j.jpg','read',0,NULL,NULL,'2026-04-07 16:34:17','2026-04-07 17:37:48',10,NULL,'Grapa','[{"name":"Kelly Thompson","role":"Guion"},{"name":"Hayden Sherman","role":"Dibujo, Tinta"},{"name":"Jordie Bellaire","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(470,'Absolute Wonder Woman #2','Absolute Wonder Woman',2,NULL,'9773081289008-00002',NULL,'Kelly Thompson','Hayden Sherman',NULL,NULL,'Panini Comics España',NULL,'2025-05-08',NULL,NULL,replace(replace('Contiene Absolute Wonder Woman 2\r\nEn Gateway City nunca ha presenciado nada parecido a la aparición del Heraldo Primero, el enorme y voraz monstruo emergido desde las profundidades del océano para ensombrecer sus costas... Pero, por otra parte, también es cierto que el Heraldo nunca se ha encontrado con nadie parecido a la imparable Diana, Princesa del Inframundo.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579659174-mufbf4.jpg','read',0,NULL,NULL,'2026-04-07 16:34:20','2026-04-07 17:37:48',10,NULL,'grapa','[{"name":"Kelly Thompson","role":"Guion"},{"name":"Hayden Sherman","role":"Dibujo, Tinta"},{"name":"Jordie Bellaire","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(471,'Absolute Wonder Woman #3','Absolute Wonder Woman',3,NULL,'9773081289008-00003',NULL,'Kelly Thompson','Hayden Sherman',NULL,NULL,'Panini Comics España',NULL,'2025-06-05',NULL,NULL,replace(replace('Contiene Absolute Wonder Woman 3\r\nUn Heraldo no es más que un mensajero. A quien hay que temer es al Tetracida, pues este no deja nada a su paso. El verdadero enemigo de Diana ha sido revelado, y ella tendrá que tirar de todo lo que tiene para evitar que Gateway City sea borrada del mapa.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579661725-uteubt.jpg','read',0,NULL,NULL,'2026-04-07 16:34:22','2026-04-07 17:37:48',10,NULL,'grapa','[{"name":"Kelly Thompson","role":"Guion"},{"name":"Hayden Sherman","role":"Dibujo, Tinta"},{"name":"Jordie Bellaire","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(472,'Absolute Wonder Woman #4','Absolute Wonder Woman',4,NULL,'9773081289008-00004',NULL,'Kelly Thompson','Hayden Sherman',NULL,NULL,'Panini Comics España',NULL,'2025-07-03',NULL,NULL,replace(replace('Contiene Absolute Wonder Woman 4\r\nDiana ha hecho lo inimaginable para escapar de las fatales garras del Tetracida. Quizás se haya salvado para poder luchar un día más, pero el precio a pagar es mucho más de lo que está dispuesta a perder, ante la lucha venidera. Necesitará aliados, nuevos y viejos, para recuperar lo perdido y salvar la ciudad.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579663485-b892x6.jpg','read',0,NULL,NULL,'2026-04-07 16:34:24','2026-04-07 17:37:48',10,NULL,'grapa','[{"name":"Kelly Thompson","role":"Guion"},{"name":"Hayden Sherman","role":"Dibujo, Tinta"},{"name":"Jordie Bellaire","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(473,'Absolute Wonder Woman #5','Absolute Wonder Woman',5,NULL,'9773081289008-00005',NULL,'Kelly Thompson','Hayden Sherman',NULL,NULL,'Panini Comics España',NULL,'2025-08-07',NULL,NULL,replace(replace('Contiene Absolute Wonder Woman 5\r\nWonder Woman ha arrojado todo lo que se le ha ocurrido al Tetracida, que sigue adelante, devorando Gateway City. Con todo en riesgo, a Diana aún le queda una gran idea, pero en su estado actual, está muy lejos del poder que necesita para ponerla en práctica…','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579665279-4cq3lt.jpg','read',0,NULL,NULL,'2026-04-07 16:34:25','2026-04-07 17:37:48',10,NULL,'Grapa','[{"name":"Kelly Thompson","role":"Guion"},{"name":"Hayden Sherman","role":"Dibujo, Tinta"},{"name":"Jordie Bellaire","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(474,'Absolute Wonder Woman #6','Absolute Wonder Woman',6,NULL,'9773081289008-00006',NULL,'Kelly Thompson','Mattia De Iluis',NULL,NULL,'Panini Comics España',NULL,'2025-09-04',NULL,NULL,replace(replace('Contiene: Absolute Wonder Woman 6\r\nAl abandonar el Infierno, Diana desafió la voluntad de los dioses. Para Hades, señor del Inframundo, es algo personal. ¿El testimonio de la amazona cambiará su destino? Comienza un arco en dos partes con Mattia De Iulis como artista invitado y con una historia de complemento ilustrada por Dustin Nguyen.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579667091-x3l30b.jpg','read',0,NULL,NULL,'2026-04-07 16:34:27','2026-04-07 17:37:48',10,NULL,'grapa','[{"name":"Kelly Thompson","role":"Guion"},{"name":"Mattia De Iluis","role":"Dibujo, Tinta, Color"},{"name":"Dustin Nguyen","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(475,'Absolute Wonder Woman #8','Absolute Wonder Woman',8,NULL,'9773081289008-00008',NULL,'Kelly Thompson','Hayden Sherman',NULL,NULL,'Panini Comics España',NULL,'2025-11-06',NULL,NULL,replace(replace('Contiene: Absolute Wonder Woman 8\r\nEl Tetracida era una amenaza mucho mayor de lo que Wonder Woman hubiera imaginado. Lo verá como un juego de niños, comparado con las complejidades y males que le aguardan en el mundo del hombre. La mayor prueba para Diana espera en la misteriosa Área 41.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579668754-4xkefe.jpg','read',0,NULL,NULL,'2026-04-07 16:34:29','2026-04-07 17:37:48',10,NULL,'grapa','[{"name":"Kelly Thompson","role":"Guion"},{"name":"Hayden Sherman","role":"Dibujo, Tinta"},{"name":"Jordie Bellaire","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(476,'Absolute Wonder Woman #9','Absolute Wonder Woman',9,NULL,'9773081289008-00009',NULL,'Kelly Thompson','Hayden Sherman',NULL,NULL,'Panini Comics España',NULL,'2025-12-04',NULL,NULL,replace(replace('Contiene Absolute Wonder Woman 9\r\nEn estas páginas yace la tentación de todo lo que Diana ha deseado siempre, pero también terrores inimaginables... y ninguna escapatoria conocida. Wonder Woman ha entrado en el laberinto, y nada volverá a ser lo mismo nunca más.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579671017-1wh6bw.jpg','read',0,NULL,NULL,'2026-04-07 16:34:31','2026-04-07 17:37:48',10,NULL,'grapa','[{"name":"Kelly Thompson","role":"Guion"},{"name":"Hayden Sherman","role":"Dibujo, Tinta"},{"name":"Jordie Bellaire","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(477,'Absolute Wonder Woman #10','Absolute Wonder Woman',10,NULL,'9773081289008-00010',NULL,'Kelly Thompson','Hayden Sherman',NULL,NULL,'Panini Comics España',NULL,'2026-01-08',NULL,NULL,replace(replace('Contiene: Absolute Wonder Woman 10\r\nAquello que Diana busca en el laberinto parece eludirla. Los misterios empiezan a desenmarañarse en torno a ella. Va a acabar cuestionándose todo, hasta su misión. Mientras tanto, en Gateway City, una vieja obligación asoma la cabeza... ¡violentamente!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579672725-3m5l83.jpg','read',0,NULL,NULL,'2026-04-07 16:34:33','2026-04-07 17:37:48',10,NULL,'grapa','[{"name":"Kelly Thompson","role":"Guion"},{"name":"Hayden Sherman","role":"Dibujo, Tinta"},{"name":"Jordie Bellaire","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(478,'Absolute Wonder Woman #11','Absolute Wonder Woman',11,NULL,'9773081289008-00011',NULL,'Kelly Thompson','Hayden Sherman',NULL,NULL,'Panini Comics España',NULL,'2026-02-05',NULL,NULL,replace(replace('Contiene: Con Absolute Wonder Woman 11\r\nLa presencia de Diana en el Laberinto trastoca el equilibrio de poder, que cede peligrosamente hacia el lado del caos. Y que una laberíntica prisión subterránea se vea sumida en el caos... quizás no sea una situación ideal.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579674931-avxw27.jpg','read',0,NULL,NULL,'2026-04-07 16:34:35','2026-04-07 17:37:48',10,NULL,'grapa','[{"name":"Kelly Thompson","role":"Guion"},{"name":"Hayden Sherman","role":"Dibujo, Tinta"},{"name":"Jordie Bellaire","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(479,'Absolute Wonder Woman #12','Absolute Wonder Woman',12,NULL,'9773081289008-00012',NULL,'Kelly Thompson','Hayden Sherman',NULL,NULL,'Panini Comics España',NULL,'2026-03-05',NULL,NULL,replace(replace('Contiene: Con Absolute Wonder Woman 12\r\nCuidado con lo que deseas, Wonder Woman, porque puede que se cumpla. En compañías sorprendentes, pero no indeseadas, Diana procede a realizar sus movimientos finales en el laberinto. Incluso si logra vencer, las pérdidas serán demoledoras.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579676862-glp6bq.jpg','read',0,NULL,NULL,'2026-04-07 16:34:37','2026-04-07 17:37:48',10,NULL,'grapa','[{"name":"Kelly Thompson","role":"Guion"},{"name":"Hayden Sherman","role":"Dibujo, Tinta"},{"name":"Jordie Bellaire","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(480,'Absolute Wonder Woman #13','Absolute Wonder Woman',13,NULL,'9773081289008-00013',NULL,'Kelly Thompson','Matias Bergara',NULL,NULL,'Panini Comics España',NULL,'2026-04-01',NULL,NULL,replace(replace('Contiene: Absolute Wonder Woman 13\r\nDiana aprende más del mito de las Amazonas junto a Barbara en Gateway City, mientras una serie de violentos eventos sobrenaturales comienzan a sucederse, arrastrándola a una lucha por todo el globo. La amazona contará con la ayuda de Etta para resolver el misterio y detener los ataques. La respuesta es demasiado personal.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579678796-4kuv0q.jpg','read',0,NULL,NULL,'2026-04-07 16:34:40','2026-04-08 19:27:55',10,NULL,'Grapa','[{"name":"Kelly Thompson","role":"Guion"},{"name":"Matias Bergara","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(481,'Absolute Green Lantern #8','Absolute Green Lantern',8,NULL,'9773081596007-00008',NULL,'Al Ewing','Jahnoy Lindsay',NULL,NULL,'Panini Comics España',NULL,'2026-04-01',NULL,NULL,replace(replace('Contiene: Con Absolute Green Lantern 8\r\nLa energía verde continúa expandiéndose en el Universo Absolute. ¿Quién es Jo Mullein? La portadora del poder verde revela sus más profundos secretos... y su exmujer decidirá si le presta su ayuda o la entrega a las autoridades','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775579697313-11emdh.jpg','read',0,NULL,NULL,'2026-04-07 16:34:57','2026-04-12 12:19:57',2,NULL,'grapa','[{"name":"Al Ewing","role":"Guion"},{"name":"Jahnoy Lindsay","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(482,'Sandman: Obertura','Sandman: Obertura',NULL,NULL,'978-8-417-27635-5',NULL,'Neil Gaiman','J. H. Williams III',NULL,NULL,'ECC Ediciones',NULL,'2017-12-04',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: The Sandman: Overture núms. 1-6 USA \r\nARGUMENTO: Es conocido en toda la creación con incontables nombres. Allá donde existe la vida, él y sus siete hermanos intemporales guían las fuerzas que le dan forma. Él es Sueño de los Eternos. Estamos en el año 1915. Y el universo está a punto de llegar a su fin.\r\nCon Sandman: Obertura, el exitoso autor y maestro de la fantasía moderna Neil Gaiman regresa con su primera historia sobre el Rey del Sueño en casi 20 años, una impactante precuela de la saga original Sandman, ilustrada por el aclamado dibujante J.H. Williams III y el colorista Dave Stewart. Esta edición de lujo recopila los seis números de la relevante serie de Vertigo e incluye más de 40 páginas de material inédito, así como una sección de bocetos de Williams.','\r',char(13)),'\n',char(10)),NULL,NULL,224,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775585349791-mowlug.jpg','read',0,NULL,NULL,'2026-04-07 18:09:10','2026-04-07 18:13:41',NULL,22,'lujo','[{"name":"Neil Gaiman","role":"Guion"},{"name":"J. H. Williams III","role":"Dibujo"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(484,'The Sandman #1','The Sandman',1,NULL,'978-8-467-49133-3',NULL,'Neil Gaiman','Mike Dringenberg',NULL,NULL,'Planeta Cómic',NULL,'2010-08-01',NULL,NULL,replace(replace('Edición original: The Sandman Absolute Edition Vol. 1, The Sandman Companion USA.\r\n1916. En el mundo ocurre un extraño fenómeno: la gente se va a dormir, y no es capaz de despertar. Algo malo ha ocurrido. Algo falta, y nadie sabe decir qué es.\r\nEn Whych Cross, Inglaterra, un mago intenta raptar a la MUERTE, con el fin de lograr la vida eterna, pero su errado hechizo apresa a otra criatura mágica: un hombre pálido y delgado, de ojos profundos y cabellera negra.\r\nSUEÑO, el hermano de Muerte, ha sido capturado, y el mundo de los sueños ha quedado huérfano. Ahora nadie puede dormir bien… si no es capaz de soñar.','\r',char(13)),'\n',char(10)),NULL,NULL,496,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775585426158-66yw3f.jpg','read',0,5,NULL,'2026-04-07 18:10:29','2026-04-07 18:13:41',86,13.99,'Rústica','[{"name":"Mike Dringenberg","role":"Dibujo"},{"name":"Neil Gaiman","role":"Guion"},{"name":"Sam Kieth","role":"Dibujo"},{"name":"Chris Bachalo","role":"Dibujo"},{"name":"Michael Zulli","role":"Dibujo"},{"name":"Kelley Jones","role":"Dibujo"},{"name":"Charles Vess","role":"Dibujo"},{"name":"Colleen Doran","role":"Dibujo"},{"name":"Malcolm Jones Iii","role":"Dibujo"},{"name":"Steve Parkhouse","role":"Dibujo"},{"name":"Daniel Vozzo","role":"Color"},{"name":"Zylonol","role":"Color"},{"name":"Steve Oliff","role":"Color"},{"name":"Dave McKean","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(485,'The Sandman #2','The Sandman',2,NULL,'978-8-467-49134-0',NULL,'Neil Gaiman','Charles Vess',NULL,NULL,'Planeta Cómic',NULL,'2010-09-01',NULL,NULL,replace(replace('Edición original: The Sandman # 17-28, The Sandman Companion USA.\r\nHace 10.000 años, Morfeo condenó al Infierno a una mujer que le amaba. Los otros miembros de su familia inmortal, los Eternos, le convencen de que eso fue una injusticia. Para corregirla, debe viajar al Infierno y rescatar a su amor desterrado. Pero Lucifer, el señor del Infierno, ha jurado destruir a Morfeo, y sus planes son sutiles...','\r',char(13)),'\n',char(10)),NULL,NULL,496,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775585445523-8zlta0.jpg','read',0,NULL,NULL,'2026-04-07 18:10:46','2026-04-07 18:13:41',86,NULL,'Rústica','[{"name":"Charles Vess","role":"Dibujo"},{"name":"Colleen Doran","role":"Dibujo"},{"name":"Daniel Vozzo","role":"Dibujo"},{"name":"Dick Giordano","role":"Dibujo"},{"name":"George Pratt","role":"Dibujo"},{"name":"Kelley Jones","role":"Dibujo"},{"name":"Malcolm Jones Iii","role":"Dibujo"},{"name":"Matt Wagner","role":"Dibujo"},{"name":"Mike Dringenberg","role":"Dibujo"},{"name":"Neil Gaiman","role":"Guion"},{"name":"Philip Craig Russell","role":"Dibujo"},{"name":"Steve Oliff","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(486,'The Sandman #3','The Sandman',3,NULL,'978-8-467-49135-7',NULL,'Neil Gaiman','Bryan Talbot',NULL,NULL,'Planeta Cómic',NULL,'2010-11-01',NULL,NULL,replace(replace('Edición original: Sandman 29-39, Sandman Midnight Theatre, Winter´s Edge 01 USA.\r\nDesde que era pequeña, Barbara ha viajado en sueños a un mundo de fantasía, donde, acompañada de sus amigos imaginarios, vivía increíbles aventuras que continuaban a la noche siguiente como si se tratara de un serial televisivo. Ahora su mundo imaginario tiene que hacer frente a la amenaza del Cuco, una criatura malevola, y sus amigos deben cruzar la barrera entre la realidad y el sueño y viajar a Nueva York para encontrar a su princesa. Los dulces sueños de Barbara empiezan así a convertirse en una larga pesadilla.','\r',char(13)),'\n',char(10)),NULL,NULL,496,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775585447742-bza0ns.jpg','read',0,NULL,NULL,'2026-04-07 18:10:48','2026-04-07 18:13:41',86,NULL,'Rústica','[{"name":"Bryan Talbot","role":"Dibujo, Tinta"},{"name":"Dick Giordano","role":"Dibujo"},{"name":"Duncan Eagleson","role":"Dibujo"},{"name":"John Watkiss","role":"Dibujo"},{"name":"Neil Gaiman","role":"Guion"},{"name":"Shawn McManus","role":"Dibujo"},{"name":"Stan Woch","role":"Dibujo"},{"name":"Teddy H. Kristiansen","role":"Dibujo"},{"name":"Vince Locke","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(487,'The Sandman #4','The Sandman',4,NULL,'978-8-467-49136-4',NULL,'Neil Gaiman','Bryan Talbot',NULL,NULL,'Planeta Cómic',NULL,'2010-12-01',NULL,NULL,'Edición original: The Sandman #40-49, Vertigo Preview #1, Sandman Special #1, Winter',NULL,NULL,496,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775585449770-al8exi.jpg','read',0,NULL,NULL,'2026-04-07 18:10:50','2026-04-07 18:13:41',86,NULL,'Rústica','[{"name":"Bryan Talbot","role":"Dibujo"},{"name":"Daniel Vozzo","role":"Dibujo"},{"name":"Jill Thompson","role":"Dibujo"},{"name":"Kent Williams","role":"Dibujo"},{"name":"Mark Buckingham","role":"Dibujo"},{"name":"Michael Zulli","role":"Dibujo"},{"name":"Neil Gaiman","role":"Guion"},{"name":"Sherilyn Van Valkenburgh","role":"Dibujo"},{"name":"Vince Locke","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(488,'The Sandman #5','The Sandman',5,NULL,'978-8-467-49137-1',NULL,'Neil Gaiman','Alec Stevens',NULL,NULL,'Planeta Cómic',NULL,'2011-01-01',NULL,NULL,replace(replace('Edición original: The Sandman # 50-56, The Sandman: Dream Hunters, Absolute Sandman, Sandman Companion USA.\r\nAtrapados en el vórtice de una gran tormenta, los viajeros de otros tiempos, mitos y mundos imaginados encuentran cobijo en una misteriosa posada. Una posada en el fin del mundo. Mientras la tempestad amaina, sus clientes comparten sus historias sobre los lugares que visitaron, las cosas que vieron... y aquellos que se aparecieron en sus sueños.','\r',char(13)),'\n',char(10)),NULL,NULL,496,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775585451667-u5s7an.jpg','read',0,NULL,NULL,'2026-04-07 18:10:52','2026-04-07 18:13:41',86,NULL,'Rústica','[{"name":"Alec Stevens","role":"Dibujo"},{"name":"Bryan Talbot","role":"Dibujo"},{"name":"Daniel Vozzo","role":"Dibujo"},{"name":"Dick Giordano","role":"Dibujo"},{"name":"Jessica Kindzierski","role":"Dibujo"},{"name":"Mark Buckingham","role":"Dibujo"},{"name":"Mike Allred","role":"Dibujo"},{"name":"Neil Gaiman","role":"Guion"},{"name":"Philip Craig Russell","role":"Dibujo"},{"name":"Shea Anton Pensa","role":"Dibujo"},{"name":"Timothy Harris","role":"Dibujo"},{"name":"Vince Locke","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(489,'The Sandman #6','The Sandman',6,NULL,'978-8-467-49138-8',NULL,'Neil Gaiman','Charles Vess',NULL,NULL,'Planeta Cómic',NULL,'2011-03-01',NULL,NULL,replace(replace('Edición original: Vertigo Jam #1, The Sandman 57-69 USA.\r\nAngustiada por el secuestro y la presunta muerte de su hijo, Lyta Hall invoca a las brujas ancestrales, las Furias, para castigar y maldecir al culpable. El Señor del Sueño ha sido acusado y ahora debe permitir la entrada de las Benévolas a su reino, a riesgo de tener que aceptar un sacrificio que cambiaría el Sueño para siempre...','\r',char(13)),'\n',char(10)),NULL,NULL,496,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775585453869-yltyqy.jpg','read',0,NULL,NULL,'2026-04-07 18:10:54','2026-04-07 18:13:41',86,NULL,'Rústica','[{"name":"Charles Vess","role":"Dibujo"},{"name":"Daniel Vozzo","role":"Dibujo"},{"name":"Dean Ormston","role":"Dibujo"},{"name":"Kevin Nowlan","role":"Dibujo"},{"name":"Marc Hempel","role":"Dibujo"},{"name":"Neil Gaiman","role":"Guion"},{"name":"Richard Case","role":"Dibujo"},{"name":"Teddy H. Kristiansen","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(490,'The Sandman #7','The Sandman',7,NULL,'978-8-467-49139-5',NULL,'Neil Gaiman','Charles Vess',NULL,NULL,'Planeta Cómic',NULL,'2011-04-01',NULL,NULL,replace(replace('Edición original: The Sandman 70-75, The Sandman: Endless Nights, Absolute Sandman, Companion USA.\r\nLos acontecimientos recientes han obligado a los Eternos, por primera vez en muchísimo tiempo, a reunirse de nuevo en comunión. Es momento de reflexionar y escuchar a todos los habitantes del Sueño... y de dar paso a un nuevo despertar.','\r',char(13)),'\n',char(10)),NULL,NULL,496,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775585455834-eoi7u9.jpg','read',0,NULL,NULL,'2026-04-07 18:10:56','2026-04-07 18:13:41',86,NULL,'Rústica','[{"name":"Charles Vess","role":"Dibujo"},{"name":"Daniel Vozzo","role":"Dibujo"},{"name":"Jon J. Muth","role":"Dibujo"},{"name":"Michael Zulli","role":"Dibujo"},{"name":"Neil Gaiman","role":"Guion"},{"name":"Miguelanxo Prado","role":"Dibujo"}]');
