INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(493,'Neil Gaiman: Leyendas del abismo #2','Neil Gaiman: Leyendas del abismo',2,NULL,'978-8-415-62896-5',NULL,'Neil Gaiman','Chris Bachalo',NULL,NULL,'ECC Ediciones',NULL,'2012-11-01',NULL,NULL,replace('EDICIÓN ORIGINAL: Books of Magic, Neil Gaiman´s Midnight days USA\rTim Hunter acompaña a un ciego por el fin del universo. Jack del Verde hace un alto en el camino para enterrar a un amigo. Chester Williams conversa con un candidato a presidente. El Hombre Florónico visita la selva amazónica. John Constantine abraza a un desconocido. Y Wesley Dodds viaja a Inglaterra para encontrarse con un espejo...','\r',char(13)),NULL,NULL,368,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775585530303-115coz.jpg','unread',0,NULL,NULL,'2026-04-07 18:12:11','2026-04-07 18:12:11',87,NULL,'Cartoné 320-368 pp','[{"name":"Neil Gaiman","role":""},{"name":"Chris Bachalo","role":""},{"name":"Dave McKean","role":""},{"name":"Peter Snejbjerg","role":""},{"name":"Sergio Aragonés","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(494,'Neil Gaiman: Leyendas del Universo DC','Neil Gaiman: Leyendas del Universo DC',NULL,NULL,'978-8-415-52099-3',NULL,'Neil Gaiman','Andy Kubert',NULL,NULL,'ECC Ediciones',NULL,'2012-06-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Whattever happened to the caped crusader?, Solo num. 08, Wednesday Comics 2010- Metamorpho, Batman: Black & White núm. 08, Legend of The Green Flame USA\r\nQué invitados acudirán al funeral celebrado por Batman en un oscuro callejón de Gotham City? ¿Acaso ha muerto realmente el Hombre Murciélago? ¿Cómo ocupa sus días un fantasma que no puede acceder al Más Allá? ¿Por qué son necesarias las habilidades de un Hombre Elemental para descifrar los misterios de la Antártida? ¿Y si la relación entre Batman y el Joker no fuese como llevamos décadas imaginándola? ¿Qué fuerza oculta podría condenar a Superman y a Green Lantern a los pozos del infierno?\r\nAcompañado de grandes ilustradores como Andy Kubert, Mike Allred, Simon Bisley, Matt Wagner o Eddie Campbell, el guionista estrella Neil Gaiman (creador de la legendaria serie The Sandman e inspirador de la película Los Mundos de Coraline) ofrece en este libro su singular interpretación de personajes tan icónicos como Batman, Superman o Green Lantern. Neil Gaiman: Leyendas del Universo DC es un viaje a la fértil imaginación de uno de los autores más importantes del cómic en las últimas décadas.','\r',char(13)),'\n',char(10)),NULL,NULL,192,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775585545608-1u6nmq.jpg','unread',0,NULL,NULL,'2026-04-07 18:12:27','2026-04-07 18:12:27',NULL,19.5,NULL,'[{"name":"Neil Gaiman","role":"Guion"},{"name":"Andy Kubert","role":"Dibujo"},{"name":"Eric Shanower","role":"Dibujo"},{"name":"Jim Aparo","role":"Dibujo"},{"name":"Kevin Nowlan","role":"Dibujo"},{"name":"Mark Buckingham","role":"Dibujo"},{"name":"Mike Allred","role":"Dibujo"},{"name":"Simon Bisley","role":"Dibujo"},{"name":"Teddy H. Kristiansen","role":"Dibujo"}]');
