INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(497,'Predicador #3','Predicador',3,NULL,'978-8-467-49193-7',NULL,'Garth Ennis','Steve Dillon',NULL,NULL,'Planeta Cómic',NULL,'2010-12-01',NULL,NULL,'Sincero, cáustico y directamente profano, Predicador es un cómic que sigue el viaje épico del reverendo Jesse Custer en persecución de un Dios fugitivo, para hacerle responder por todo el sufrimiento de su creación. Desde las cenizas de una iglesia de pueblo hasta las luces brillantes de Nueva York, pasando por los pantanos de Louisiana, Jesse y sus amigos recorren el alma de América en una búsqueda de lo divino, un esfuerzo que se verá frenado por todo el mal que puedan reunir el Cielo y la Tierra.',NULL,NULL,816,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775585581878-hjyhoi.jpg','read',0,NULL,NULL,'2026-04-07 18:13:02','2026-04-07 18:13:41',88,NULL,'Rústica','[{"name":"Garth Ennis","role":""},{"name":"Steve Dillon","role":""}]');
