INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(547,'Blood The Last Vampire 2000','Blood The Last Vampire 2000',NULL,NULL,'978-9-871-07114-2',NULL,'Benkyo Tamaoki','Benkyo Tamaoki',NULL,NULL,'Ivrea',NULL,'2003-01-01',NULL,NULL,'Una pacífica comunidad se ve azotada por la amenaza de un grupo de motociclistas. Entre sus habitantes comienzan a circular rumores extraños. Una figura maligna y misteriosa secuestra a una de las víctimas de este grupo, la joven Akiko Motoyama. A lo largo de la historia de la humanidad se ha desarrollado en las sombras la guerra más importante: la de los seres humanos contra los vampiros llamados Chiropteans. Armada tan sólo con su katana la enigmática joven Saya busca a uno de estos vampiros entre la oscuridad. Una combinación perfecta de acción, intriga y terror con algunas dosis de sexo. El cómic que despeja muchos de los misterios que dejó la afamada película &quot;Blood the Last Vampire&quot;.',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775635360636-c7z1gq.jpg','read',0,NULL,NULL,'2026-04-08 08:02:43','2026-04-08 19:27:25',NULL,7.5,'Rústica','[{"name":"Benkyo Tamaoki","role":"Guion, Dibujo"}]');
