INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(555,'Blood. Ciudadela nocturna','Blood. Ciudadela nocturna',NULL,NULL,NULL,NULL,'Hirotaka Kisaragi',NULL,NULL,NULL,'Norma Editorial',NULL,'2009-05-01',NULL,NULL,'En los últimos días de soberanía británica, Hong Kong es un hervidero de mafia y corrupción. Un joven detective de la policía se resiste a abandonar un misterioso caso cuyas víctimas aparecen completamente desangradas… y su única pista es un enigmático violonchelista. Una nueva entrega de las fascinantes aventuras de humanos y quirópteros en el universo BLOOD+.',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775635481903-wbqy1u.jpg','read',0,NULL,NULL,'2026-04-08 08:04:43','2026-04-08 18:19:32',NULL,NULL,'rústica','[{"name":"Hirotaka Kisaragi","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(556,'Las flores del mal #1','Las flores del mal',1,NULL,'978-8-467-91693-5',NULL,'Shuzo Oshimi',NULL,NULL,NULL,'Norma Editorial',NULL,'2014-09-26',NULL,NULL,replace(replace('UN RETORCIDO THRILLER PSICOLÓGICO AMBIENTADO EN UN INSTITUTO \r\nTakao Kasuga es un apasionado de la literatura enamorado de la obra de Baudelaire. Un día encuentra la ropa de gimnasia de Nanako , la chica que le gusta, y casi sin darse cuenta, se la lleva. Más tarde descubre que Nakamura , una chica a la que nadie soporta, ha sido testigo de ello, y esta le impone un precio por su silencio…','\r',char(13)),'\n',char(10)),NULL,NULL,208,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775635506736-0ngrjn.jpg','read',0,NULL,NULL,'2026-04-08 08:05:10','2026-04-08 18:19:32',95,NULL,'Rústica','[{"name":"Shuzo Oshimi","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(557,'Las flores del mal #2','Las flores del mal',2,NULL,'978-8-467-91710-9',NULL,'Shuzo Oshimi',NULL,NULL,NULL,'Norma Editorial',NULL,'2014-10-30',NULL,NULL,replace(replace('UNA HISTORIA MAQUIAVÉLICA, RETORCIDA PERO MUY ORIGINAL SOBRE LA MANIPULACIÓN Y EL ACOSO ESCOLAR \r\nEl impulso que le hizo robar la ropa de gimnasia de Nanako ha puesto a Kasuga entre la espada y la pared: el único testigo del robo, la desquiciada Nakamura, lo manipula y obliga a bailar a su son, poniendo en peligro su nueva relación con Nanako y su propia cordura.','\r',char(13)),'\n',char(10)),NULL,NULL,208,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775635523198-nirp8m.jpg','read',0,NULL,NULL,'2026-04-08 08:05:24','2026-04-08 18:19:32',95,NULL,'Rústica','[{"name":"Shuzo Oshimi","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(558,'Las flores del mal #3','Las flores del mal',3,NULL,'978-8-467-91819-9',NULL,'Shuzo Oshimi',NULL,NULL,NULL,'Norma Editorial',NULL,'2015-01-23',NULL,NULL,replace(replace('NAKAMURA HA CONSEGUIDO QUE KASUGA SE DEJE LLEVAR POR SUS EMOCIONES NEGATIVAS, PERO… \r\nKasuga está confuso e indeciso: por un lado la influencia de Nakamura le empuja a actuar de manera violenta, pero por otra parte se siente liberado y extrañamente libre. Y por si fuera poco, Nanako está decidida a saber más sobre él, y teme que lo averigüe todo…','\r',char(13)),'\n',char(10)),NULL,NULL,208,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775635525937-x29s80.jpg','read',0,NULL,NULL,'2026-04-08 08:05:27','2026-04-08 18:19:32',95,NULL,'Rústica','[{"name":"Shuzo Oshimi","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(559,'Las flores del mal #4','Las flores del mal',4,NULL,'978-8-467-91852-6',NULL,'Shuzo Oshimi',NULL,NULL,NULL,'Norma Editorial',NULL,'2015-03-20',NULL,NULL,replace('KASUGA Y NAKAMURA FRACASARON EN SU INTENTO DE LLEGAR AL “OTRO LADO”.¿QUÉ LES ESPERA AHORA? \rTras su escapada, Kasuga corta con Saeki y se sumerge, él solo, en un abismo de desesperación. Pero de repente se da cuenta de que Nakamura está aún más herida y enfadada que él por el hecho de no haber sido capaces de ir “al otro lado de la montaña”… ¡¡y decide pasar a la acción!!','\r',char(13)),NULL,NULL,208,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775635528902-4bjlja.jpg','read',0,NULL,NULL,'2026-04-08 08:05:29','2026-04-08 18:19:32',95,NULL,'Rústica','[{"name":"Shuzo Oshimi","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(560,'Las flores del mal #5','Las flores del mal',5,NULL,'978-8-467-91915-8',NULL,'Shuzo Oshimi',NULL,NULL,NULL,'Norma Editorial',NULL,'2015-05-22',NULL,NULL,replace(replace('ALGUIEN DESCUBRE EL “OTRO LADO” QUE ESTÁN CREANDO KASUGA Y NAKAMURA…\r\nSaeki se da cuenta de la relación tan estrecha que existe entre Kasuga y Nakamura y los celos la corroen. Se pone en acción, abandonándolo todo, con la idea de recuperar a Kasuga, la persona que “primero pudo ver a la verdadera Nanako Saeki”...!!','\r',char(13)),'\n',char(10)),NULL,NULL,208,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775635531578-44oter.jpg','read',0,NULL,NULL,'2026-04-08 08:05:32','2026-04-08 18:19:32',95,NULL,'Rústica','[{"name":"Shuzo Oshimi","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(561,'Las flores del mal #6','Las flores del mal',6,NULL,'978-8-467-91988-2',NULL,'Shuzo Oshimi',NULL,NULL,NULL,'Norma Editorial',NULL,'2015-07-24',NULL,NULL,'Kasuga, desorientado después de que Saeki destruya su base secreta, sigue pensando en algún plan para satisfacer a Nakamura. Pero justo entonces aparecen unos agentes de policía con la libreta del “Plan”, que se ha encontrado intacta entre los restos de la base...',NULL,NULL,208,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775635534334-35lyuj.jpg','read',0,NULL,NULL,'2026-04-08 08:05:35','2026-04-08 18:19:32',95,NULL,'Rústica','[{"name":"Shuzo Oshimi","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(562,'Las flores del mal #7','Las flores del mal',7,NULL,NULL,NULL,'Shuzo Oshimi',NULL,NULL,NULL,'Norma Editorial',NULL,'2015-09-29',NULL,NULL,replace('KASUGA Y NAKAMURA INTENTAN IR “AL OTRO LADO” DURANTE EL FESTIVAL.\rKasuga y Nakamura ponen en marcha su plan la noche del festival, pero no sale como tenían previsto. Pasa el tiempo y, en una nueva ciudad, rodeado de nuevos amigos. Kasuga cursa ahora bachillerato. Siguiendo la sombra de Nakamura, de la que ha perdido el rastro, Kasuga es como una cáscara vacía.','\r',char(13)),NULL,NULL,208,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775635536645-3adgsy.jpg','read',0,NULL,NULL,'2026-04-08 08:05:37','2026-04-08 18:19:32',95,NULL,'Rústica','[{"name":"Shuzo Oshimi","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(563,'Las flores del mal #8','Las flores del mal',8,NULL,'978-8-467-92125-0',NULL,'Shuzo Oshimi',NULL,NULL,NULL,'Norma Editorial',NULL,'2016-01-21',NULL,NULL,replace('KASUGA ENCUENTRA OTRA FUENTE DE INSPIRACIÓN EN UNA COMPAÑERA DE INSTITUTO\rEl cambio de aires y de ciudad no le ha servido a Kasuga para superar y dejar atrás lo que sintió junto a Nakamura aquel verano. Deprimido constantemente y a la deriva, parece encontrar algo que le impulsa a vivir en una nueva compañera, pero…','\r',char(13)),NULL,NULL,208,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775635538957-7cffb9.jpg','read',0,NULL,NULL,'2026-04-08 08:05:40','2026-04-08 18:19:32',95,NULL,'Rústica','[{"name":"Shuzo Oshimi","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(564,'Las flores del mal #9','Las flores del mal',9,NULL,'978-8-467-92215-8',NULL,'Shuzo Oshimi',NULL,NULL,NULL,'Norma Editorial',NULL,'2016-03-18',NULL,NULL,replace(replace('KASUGA DEBE ENFRENTARSE A SUS SENTIMIENTO… Y A SU MADUREZ\r\nKasuga se siente confuso, no entiende bien lo que siente por Tokiwa porque es distinto a lo que sintió por Nakamura, pero Saeki ha sembrado la duda en su mente y ahora se lo está replanteando todo…','\r',char(13)),'\n',char(10)),NULL,NULL,208,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775635541865-0e917g.jpg','read',0,NULL,NULL,'2026-04-08 08:05:43','2026-04-08 18:19:32',95,NULL,'Rústica','[{"name":"Shuzo Oshimi","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(565,'Las flores del mal #10','Las flores del mal',10,NULL,'978-8-467-92249-3',NULL,'Shuzo Oshimi',NULL,NULL,NULL,'Norma Editorial',NULL,'2016-05-05',NULL,NULL,'Y LLEGA EL ENCUENTRO DEFINITIVO ENTRE KASUGA Y NAKAMURA Kasuga tiene sentimientos muy fuertes por Tokiwa, pero no consigue dejar de lado lo que sintió por Nakamura. ¿Pero sigue enamorado de ella, o es solo el recuerdo de lo que sintió?',NULL,NULL,208,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775635545123-ilcsog.jpg','read',0,NULL,NULL,'2026-04-08 08:05:46','2026-04-08 18:19:32',95,NULL,'Rústica','[{"name":"Shuzo Oshimi","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(566,'Las flores del mal #11','Las flores del mal',11,NULL,'978-8-467-92250-9',NULL,'Shuzo Oshimi',NULL,NULL,NULL,'Norma Editorial',NULL,'2016-07-21',NULL,NULL,replace(replace('¡NO TE PIERDAS EL ÚLTIMO VOLUMEN DE ESTA HISTORIA!\r\nDespués de más de tres años, Kasuga está dispuesto a cerrar uno de los capítulos más importantes de su vida, volviendo a ver cara a cara a Nakamura. ¿Qué sucederá en el reencuentro?','\r',char(13)),'\n',char(10)),NULL,NULL,208,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775635548615-zcxvl7.jpg','read',0,NULL,NULL,'2026-04-08 08:05:49','2026-04-08 18:19:32',95,NULL,'Rústica','[{"name":"Shuzo Oshimi","role":""}]');
