INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(600,'I Am a Hero #11','I Am a Hero',11,NULL,'978-8-467-91810-6',NULL,'Kengo Hanazawa','Kengo Hanazawa',NULL,NULL,'Norma Editorial',NULL,'2015-01-23',NULL,NULL,'Usando un foro de Internet como único contacto con el exterior, Ezaki pensaba que todo esta perdido y que moriría a manos de los ZQN. Pero cuando el grupo de Kurusu se presenta en su casa para reclutarle los acompaña por falta de alternativas aunque no las tiene todas consigo…',NULL,NULL,240,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657654997-v79n48.jpg','read',0,NULL,NULL,'2026-04-08 14:14:15','2026-04-08 18:18:47',99,NULL,'Rústica','[{"name":"Kengo Hanazawa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(601,'I Am a Hero #12','I Am a Hero',12,NULL,'978-8-467-91851-9',NULL,'Kengo Hanazawa','Kengo Hanazawa',NULL,NULL,'Norma Editorial',NULL,'2015-03-20',NULL,NULL,replace(replace('EL REFUGIO SEGURO EN EL QUE CONFIABA EZAKI YA NO LO ES TANTO...\r\nPese a llevar varios días parapetados en una casa aparentemente segura, todo cambia cuando un ZQN consigue abrirse paso hasta el grupo que ha acogido a Ezaki. Eso precipita los acontecimientos y los obliga a huir... ¿pero adónde? ¿Queda algún lugar seguro?','\r',char(13)),'\n',char(10)),NULL,NULL,240,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657656843-jgmeza.jpg','read',0,NULL,NULL,'2026-04-08 14:14:17','2026-04-08 18:18:47',99,NULL,'Rústica','[{"name":"Kengo Hanazawa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(602,'I Am a Hero #13','I Am a Hero',13,NULL,'978-8-467-91914-1',NULL,'Kengo Hanazawa','Kengo Hanazawa',NULL,NULL,'Norma Editorial',NULL,'2015-05-22',NULL,NULL,replace(replace('LOS MUERTOS VIVIENTES A LA JAPONESA SIGUEN ARRASANDO , UNA NUEVA VISIÓN DE CÓMO PODRÍA SER UN APOCALIPSIS ZOMBI\r\nLa misteriosa plaga que está diezmando a los humanos sigue extendiéndose por todo el mundo: Japón, China, Europa... Nadie está a salvo del virus ZQN, que convierte a los infectados en agresivos seres asesinos.','\r',char(13)),'\n',char(10)),NULL,NULL,240,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657659574-zlv5uq.jpg','read',0,NULL,NULL,'2026-04-08 14:14:20','2026-04-08 18:18:47',99,NULL,'Rústica','[{"name":"Kengo Hanazawa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(603,'I Am a Hero #14','I Am a Hero',14,NULL,'978-8-467-91986-8',NULL,'Kengo Hanazawa','Kengo Hanazawa',NULL,NULL,'Norma Editorial',NULL,'2015-07-24',NULL,NULL,'Un cómic de Kengo Hanazawa.Publicado por Norma Editorial',NULL,NULL,240,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657661556-l2yg5z.jpg','read',0,NULL,NULL,'2026-04-08 14:14:22','2026-04-08 18:18:47',99,NULL,'Rústica','[{"name":"Kengo Hanazawa","role":"Guion, Dibujo, Tinta"}]');
