INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(606,'I Am a Hero #17','I Am a Hero',17,NULL,'978-8-467-92167-0',NULL,'Kengo Hanazawa','Kengo Hanazawa',NULL,NULL,'Norma Editorial',NULL,'2016-03-18',NULL,NULL,replace(replace('LA LUCHA EN TOKIO SE RECRUDECE...\r\nDejamos a Hideo y Hiromi en su viaje hacia Tokio y descubrimos un reducto de humanos supervivientes liderados por un carismático personaje y un antiguo conocido del protagonista...','\r',char(13)),'\n',char(10)),NULL,NULL,240,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657667309-d9qkr5.jpg','read',0,NULL,NULL,'2026-04-08 14:14:27','2026-04-08 18:18:47',99,NULL,'Rústica','[{"name":"Kengo Hanazawa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(607,'I Am a Hero #18','I Am a Hero',18,NULL,'978-8-467-92347-6',NULL,'Kengo Hanazawa','Kengo Hanazawa',NULL,NULL,'Norma Editorial',NULL,'2016-07-21',NULL,NULL,replace(replace('EL VIRUS ZQN SIGUE APODERÁNDOSE DEL MUNDO, AUNQUE AÚN QUEDAN ALGUNOS HUMANOS QUE LUCHAN POR SOBREVIVIR\r\nHideo y Hiromi siguen en dirección a Tokio con la esperanza de encontrar alguna respuesta a las muchas preguntas que les asaltan, y a poder ser, una cura a la epidemia ZQN que asola el mundo.','\r',char(13)),'\n',char(10)),NULL,NULL,240,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657669551-xo5gqx.jpg','read',0,NULL,NULL,'2026-04-08 14:14:30','2026-04-08 18:18:47',99,NULL,'Rústica','[{"name":"Kengo Hanazawa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(608,'I Am a Hero #19','I Am a Hero',19,NULL,'978-8-467-92349-0',NULL,'Kengo Hanazawa','Kengo Hanazawa',NULL,NULL,'Norma Editorial',NULL,'2016-10-28',NULL,NULL,replace(replace('EL VIRUS ZQN SIGUE AVANZANDO INEXORABLE… ¡E INCLUSO LLEGA A NUESTRO PAÍS!\r\nHideo y Hiromi siguen su viaje a Tokio mientras en el resto del mundo las ciudades, abandonadas, han quedado a merced de los diversos tipos de ZQN… que siguen trabajando en pos de su objetivo común.','\r',char(13)),'\n',char(10)),NULL,NULL,240,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657671620-d0xjbd.jpg','read',0,NULL,NULL,'2026-04-08 14:14:32','2026-04-08 18:18:47',99,NULL,'Rústica','[{"name":"Kengo Hanazawa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(609,'I Am a Hero #20','I Am a Hero',20,NULL,'978-8-467-92566-1',NULL,'Kengo Hanazawa','Kengo Hanazawa',NULL,NULL,'Norma Editorial',NULL,'2017-02-22',NULL,NULL,replace('HIDEO VUELVE A ESTAR SOLO, POR LO QUE DEBE TOMAR LA DECISIÓN DE IR A POR HIROMI… O CONTINUAR EN SOLITARIO\rHideo creía haber encontrado cierta estabilidad y seguridad junto a Hiromi, pero su insistencia en dirigirse a Tokio escondía una compulsión, un deseo más grande que ella misma para unirse a los otros ZQN…','\r',char(13)),NULL,NULL,240,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657674134-gse1vy.jpg','read',0,NULL,NULL,'2026-04-08 14:14:35','2026-04-08 18:18:47',99,NULL,'Rústica','[{"name":"Kengo Hanazawa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(610,'I Am a Hero #21','I Am a Hero',21,NULL,'978-8-467-92695-8',NULL,'Kengo Hanazawa','Kengo Hanazawa',NULL,NULL,'Norma Editorial',NULL,'2017-07-26',NULL,NULL,replace('Los acontecimientos se precipitan y todos los personajes confluyen en la capital de Japón, algunos llevados por un impulso irrefrenable y otros dispuestos a ser héroes y salvar a sus seres queridos. \r¡Penúltimo volumen de este apasionante manga de muertos vivientes!','\r',char(13)),NULL,NULL,240,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657676419-zytk3i.jpg','read',0,NULL,NULL,'2026-04-08 14:14:37','2026-04-08 18:18:47',99,NULL,'Rústica','[{"name":"Kengo Hanazawa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(611,'I Am a Hero #22','I Am a Hero',22,NULL,'978-8-467-92903-4',NULL,'Kengo Hanazawa','Kengo Hanazawa',NULL,NULL,'Norma Editorial',NULL,'2017-10-31',NULL,NULL,replace(replace('¡TREPIDANTE VOLUMEN FINAL DE ESTE ATÍPICO MANGA SOBRE MUERTOS VIVIENTES!\r\nHideo, que empezó la historia como un mangaka fracasado y sin aspiraciones, consigue regresar a Tokio tras superar un arriesgado viaje esquivando peligros y muertos vivientes, y encontrando en su interior el valor para ser un héroe.','\r',char(13)),'\n',char(10)),NULL,NULL,240,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657679100-qtjoiu.jpg','read',0,NULL,NULL,'2026-04-08 14:14:40','2026-04-08 18:18:47',99,NULL,'Rústica','[{"name":"Kengo Hanazawa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(612,'Buenas noches, Punpun #1','Buenas noches, Punpun',1,NULL,'978-8-467-92057-4',NULL,'Inio Asano','Inio Asano',NULL,NULL,'Norma Editorial',NULL,'2015-10-28',NULL,NULL,'&quot;Punpun no es el típico estudiante de primaria. Pese a que siente los mismos impulsos que sus compañeros, empieza a descubrir a las chicas y el sexo, la situación familiar no es la más estable y deberá enfrentarse a ello como buenamente pueda… y en principio, eso es visualizándose como un ave amorfa en un entorno extraño.&quot;',NULL,NULL,2912,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657700247-cweo46.jpg','read',0,NULL,NULL,'2026-04-08 14:15:03','2026-04-08 18:18:47',100,11.43,'Rústica','[{"name":"Inio Asano","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(613,'Buenas noches, Punpun #2','Buenas noches, Punpun',2,NULL,'978-8-467-92058-1',NULL,'Inio Asano','Inio Asano',NULL,NULL,'Norma Editorial',NULL,'2015-12-09',NULL,NULL,'Punpun está pasando una etapa muy complicada en su vida: tras un incidente de violencia doméstica su padre debe separarse de ellos, su madre no tiene mucho interés en su familia y aunque ha descubierto el amor al conocer a Aiko, las circunstancias le impiden estar con ella…',NULL,NULL,2912,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657708852-uss11k.jpg','read',0,NULL,NULL,'2026-04-08 14:15:09','2026-04-08 18:18:47',100,NULL,'Rústica','[{"name":"Inio Asano","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(614,'Buenas noches, Punpun #3','Buenas noches, Punpun',3,NULL,'978-8-467-92059-8',NULL,'Inio Asano','Inio Asano',NULL,NULL,'Norma Editorial',NULL,'2016-01-21',NULL,NULL,'NOTA: La editorial emitió este comunicado el 24/02/2016. Debido a un error durante el proceso de encuadernación, una parte de la tirada del tomo 3 de Buenas noches, Punpun quedó distinta de como debería ser. Para solucionar el problema retiramos todos los tomos que aún quedaban en circulación, separamos los defectuosos de los correctos y reimprimimos los ejemplares afectados para que todos los volúmenes de este tomo quedaran igual que el resto de la colección. http://www.normaeditorial.com/blogmanga/blog/?p=8996',NULL,NULL,2912,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657711107-j3ue9t.jpg','read',0,NULL,NULL,'2026-04-08 14:15:12','2026-04-08 18:18:47',100,NULL,'Rústica','[{"name":"Inio Asano","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(615,'Buenas noches, Punpun #4','Buenas noches, Punpun',4,NULL,'978-8-467-92144-1',NULL,'Inio Asano','Inio Asano',NULL,NULL,'Norma Editorial',NULL,'2016-02-19',NULL,NULL,replace(replace('EL MANGA MÁS PERSONAL E INTROSPECTIVO DEL GENIAL INIO ASANO\r\nLa vida de los hombres Punyama no es un camino de rosas: la adolescencia de Punpun es un infierno, enamorado en silencio de Aiko, y su tío no lo lleva mucho mejor, atormentado por un terrible suceso de su pasado.','\r',char(13)),'\n',char(10)),NULL,NULL,2912,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657713698-ywhq6v.jpg','read',0,NULL,NULL,'2026-04-08 14:15:14','2026-04-08 18:18:47',100,NULL,'Rústica','[{"name":"Inio Asano","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(616,'Buenas noches, Punpun #5','Buenas noches, Punpun',5,NULL,'978-8-467-92145-8',NULL,'Inio Asano','Inio Asano',NULL,NULL,'Norma Editorial',NULL,'2016-03-18',NULL,NULL,replace(replace('NUEVO VOLUMEN DEL MANGA MÁS DESGARRADOR E INTIMISTA DE ASANO\r\nLa adolescencia de Punpun es de lo más complicada: su madre se desentiende, su tío está en el punto más bajo de su depresión y él sigue enamorado en silencio de Aiko, a la que traicionó cuando eran niños.','\r',char(13)),'\n',char(10)),NULL,NULL,2912,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657715821-mq0b8r.jpg','read',0,NULL,NULL,'2026-04-08 14:15:16','2026-04-08 18:18:47',100,NULL,'Rústica','[{"name":"Inio Asano","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(617,'Buenas noches, Punpun #6','Buenas noches, Punpun',6,NULL,'978-8-467-92146-5',NULL,'Inio Asano','Inio Asano',NULL,NULL,'Norma Editorial',NULL,'2016-04-11',NULL,NULL,replace(replace('EL MANGA MÁS PERSONAL E INTROSPECTIVO DEL GENIAL INIO ASANO\r\nPunpun ya va al instituto, pero allí se siente desplazado, fingiendo para encajar entre unos compañeros que considera insulsos y superficiales. Su cita con Kanie no puede ir peor, pero inmerso en sus propios problemas, no nota que su madre tiene los suyos propios...','\r',char(13)),'\n',char(10)),NULL,NULL,2912,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657719487-b4mkq5.jpg','read',0,NULL,NULL,'2026-04-08 14:15:20','2026-04-08 18:18:47',100,NULL,'Rústica','[{"name":"Inio Asano","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(618,'Buenas noches, Punpun #7','Buenas noches, Punpun',7,NULL,'978-8-467-92147-2',NULL,'Inio Asano','Inio Asano',NULL,NULL,'Norma Editorial',NULL,'2016-05-05',NULL,NULL,'LLEGAMOS AL MERIDIANO DE ESTA GENIAL OBRA DE INIO ASANO Punpun, ahora independizado, se aleja cada día más de sus semejantes. Finge llevar una vida despreocupada, pero el vacío es cada vez más enorme… hasta que, por casualidad, vuelve a ver a Aiko.',NULL,NULL,2912,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657722003-tz1666.jpg','read',0,NULL,NULL,'2026-04-08 14:15:22','2026-04-08 18:18:47',100,NULL,'Rústica','[{"name":"Inio Asano","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(619,'Buenas noches, Punpun #8','Buenas noches, Punpun',8,NULL,'978-8-467-92148-9',NULL,'Inio Asano','Inio Asano',NULL,NULL,'Norma Editorial',NULL,'2016-06-23',NULL,NULL,replace(replace('PUNPUN SIGUE EN UN PUNTO INDETERMINADO DE SU VIDA, AFERRADO AL SUEÑO DE AIKO\r\nLos años pasan pero Punpun sigue sin encontrar su equilibrio. Trabajando unas horas para mantenerse, apenas tiene amigos, ilusiones ni nada que le impulse a vivir salvo la esperanza de reencontrar a Aiko de nuevo… hasta que Nanjô reaparece en su vida.','\r',char(13)),'\n',char(10)),NULL,NULL,2912,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657724057-xdkeug.jpg','read',0,NULL,NULL,'2026-04-08 14:15:24','2026-04-08 18:18:47',100,NULL,'Rústica','[{"name":"Inio Asano","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(620,'Buenas noches, Punpun #9','Buenas noches, Punpun',9,NULL,'978-8-467-92149-6',NULL,'Inio Asano','Inio Asano',NULL,NULL,'Norma Editorial',NULL,'2016-07-21',NULL,NULL,replace(replace('UN FIEL REFLEJO DE LAS ANGUSTIAS, INSEGURIDADES Y ESPERANZAS DEL CAMINO A LA MADUREZ\r\nTras saborear fugazmente lo que podría haber sido la felicidad, Punpun cae en una melancolía mucho más profunda que antes. El tiempo de gracia que se había concedido llega a su fin, por lo que se plantea qué hacer con su vida...','\r',char(13)),'\n',char(10)),NULL,NULL,2912,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657726528-ktvsmm.jpg','read',0,NULL,NULL,'2026-04-08 14:15:27','2026-04-08 18:18:47',100,NULL,'Rústica','[{"name":"Inio Asano","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(621,'Buenas noches, Punpun #10','Buenas noches, Punpun',10,NULL,'978-8-467-92150-2',NULL,'Inio Asano','Inio Asano',NULL,NULL,'Norma Editorial',NULL,'2016-08-25',NULL,NULL,replace(replace('Y CUANDO PUNPUN CREÍA QUE ESTABA TOCANDO FONDO, SE REENCUENTRA CON AIKO\r\n¿Cómo se enfrentará Punpun a la realidad de una Aiko adulta? Durante años ha seguido adelante gracias a la visión idealizada de su amor de la infancia, pero es posible que al conocerla de verdad, su sueño se derrumbe.','\r',char(13)),'\n',char(10)),NULL,NULL,2912,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657728772-z7vpdy.jpg','read',0,NULL,NULL,'2026-04-08 14:15:29','2026-04-08 18:18:47',100,NULL,'Rústica','[{"name":"Inio Asano","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(622,'Buenas noches, Punpun #11','Buenas noches, Punpun',11,NULL,'978-8-467-92151-9',NULL,'Inio Asano','Inio Asano',NULL,NULL,'Norma Editorial',NULL,'2016-09-30',NULL,NULL,replace(replace('NOS EMBARCAMOS EN LA RECTA FINAL DE LA OBRA MÁS PERSONAL DE INIO ASANO\r\nUn encuentro inesperado con Aiko, la que fuera el amor de su juventud, le da a Punpun nuevas fuerzas para tomar las riendas de su vida e intentar alcanzar la felicidad con la chica con la que ha soñado más de la mitad de su vida...','\r',char(13)),'\n',char(10)),NULL,NULL,2912,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657731058-g1ex7p.jpg','read',0,NULL,NULL,'2026-04-08 14:15:31','2026-04-08 18:18:47',100,NULL,'Rústica','[{"name":"Inio Asano","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(623,'Buenas noches, Punpun #12','Buenas noches, Punpun',12,NULL,'978-8-467-92152-6',NULL,'Inio Asano','Inio Asano',NULL,NULL,'Norma Editorial',NULL,'2016-10-28',NULL,NULL,replace(replace('LAS ACCIONES DE PUNPUN LO HAN CONDUCIDO HASTA UN CALLEJÓN SIN SALIDA… ¿SERÁ ESTE SU FIN?\r\nPunpun se dispone a cumplir el sueño de Aiko, que era viajar juntos hasta Kagoshima. Pero no se trata de un simple viaje de enamorados, sino de una huida hacia delante de dos fugitivos.','\r',char(13)),'\n',char(10)),NULL,NULL,2912,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657733216-rqpw81.jpg','read',0,NULL,NULL,'2026-04-08 14:15:34','2026-04-08 18:18:47',100,NULL,'Rústica','[{"name":"Inio Asano","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(624,'Buenas noches, Punpun #13','Buenas noches, Punpun',13,NULL,'978-8-467-92153-3',NULL,'Inio Asano','Inio Asano',NULL,NULL,'Norma Editorial',NULL,'2016-10-28',NULL,NULL,replace(replace('LAS ACCIONES DE PUNPUN LO HAN CONDUCIDO HASTA UN CALLEJÓN SIN SALIDA… ¿SERÁ ESTE SU FIN?\r\nPunpun se dispone a cumplir el sueño de Aiko, que era viajar juntos hasta Kagoshima. Pero no se trata de un simple viaje de enamorados, sino de una huida hacia delante de dos fugitivos.','\r',char(13)),'\n',char(10)),NULL,NULL,2912,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657735504-vwjx9d.jpg','read',0,NULL,NULL,'2026-04-08 14:15:36','2026-04-08 18:18:47',100,NULL,'Rústica','[{"name":"Inio Asano","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(625,'Bestiarius #1','Bestiarius',1,NULL,'978-8-494-42961-3',NULL,'Masasumi Kakizaki','Masasumi Kakizaki',NULL,NULL,'Milky Way Ediciones',NULL,'2015-08-25',NULL,NULL,replace(replace('Cover Art by Masasumi Kakizaki\r\nContiene Tojushi Bestiarius Vol.1\r\nAño 85 después de Cristo.\r\nSe denominaba bestiarios a aquellos gladiadores de profesión o prisioneros de guerra forzados a combatir contra diversas bestias en la Antigua Roma. Pero... ¿puede surgir un verdadero sentimiento de amistad entre bestias y bestiarios?\r\n¿O entre ellos solamente hay sangre y muerte?\r\nLa serie más reciente del autor de Hideout y Green Blood.','\r',char(13)),'\n',char(10)),NULL,NULL,200,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657753300-tdubqq.jpg','unread',0,NULL,NULL,'2026-04-08 14:15:55','2026-04-08 14:15:55',101,NULL,'Rústica','[{"name":"Masasumi Kakizaki","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(626,'Bestiarius #2','Bestiarius',2,NULL,'978-8-494-45661-9',NULL,'Masasumi Kakizaki','Masasumi Kakizaki',NULL,NULL,'Milky Way Ediciones',NULL,'2015-10-20',NULL,NULL,replace(replace('Cover Art by Masasumi Kakizaki\rContiene Tojushi Bestiarius Vol.1 #2\rAño 86 después de Cristo.\r\nHa pasado un año desde que Finn y Durandal escaparon de las garras de Roma, sin embargo, allí no acaba la historia del valiente guerrero y el último de los guivernos. Ambos jugarán un papel importante en la vida de Arthury sus amigos, unos jóvenes dispuestos a hacerle frente al terrorífico y despiadado Imperio romano.\r\nLa serie más reciente del autor de Hideout y Green Blood.','\r',char(13)),'\n',char(10)),NULL,NULL,200,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657767839-ztudiv.jpg','unread',0,NULL,NULL,'2026-04-08 14:16:09','2026-04-08 14:16:09',101,NULL,'Rústica','[{"name":"Masasumi Kakizaki","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(627,'Bestiarius #3','Bestiarius',3,NULL,'978-8-494-49007-1',NULL,'Masasumi Kakizaki','Masasumi Kakizaki',NULL,NULL,'Milky Way Ediciones',NULL,'2016-01-26',NULL,NULL,replace(replace('Cover Art by Masasumi Kakizaki\rContiene Tojushi Bestiarius Vol.1 #3\rAño 86 después de Cristo. \r\nArthur, Galahad y Pan por fin se encuentran con Elaine. Sin embargo, el influjo y la maldad de Roma han llegado a límites insospechados, quebrantando los fuertes lazos que unen a nuestros héroes. Ahora los valientes guerreros deberán enfrentarse en la arena contra un adversario que jamás hubiesen pensado. ¿Podrán Arthur y sus amigos salir victoriosos del Coliseo romano?','\r',char(13)),'\n',char(10)),NULL,NULL,200,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657770989-n19lce.jpg','unread',0,NULL,NULL,'2026-04-08 14:16:12','2026-04-08 14:16:12',101,NULL,'Rústica','[{"name":"Masasumi Kakizaki","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(628,'Bestiarius #4','Bestiarius',4,NULL,'978-8-416-96021-7',NULL,'Masasumi Kakizaki','Masasumi Kakizaki',NULL,NULL,'Milky Way Ediciones',NULL,'2017-02-27',NULL,NULL,replace(replace('Cover Art by Masasumi Kakizaki\rContiene Tojushi Bestiarius Vol.1 #4\r\nAño 87 después de Cristo.\r\nArthur y Elaine llevan una vida tranquila alejados de la crueldad del Imperio.\r\nPero la avanzada de Roma es cada vez más cruenta, cuyo objetivo principal es la erradicación total de los subhumanos. Bajo las órdenes del Emperador Domiciano, una nueva legión llega hasta los valles de Hebden, trastornando la vida de nuestros héroes y amenazando con hacer inalcanzables los sueños de paz entre bestias y humanos...\r\nLa serie más reciente del autor de Hideout y Green Blood.','\r',char(13)),'\n',char(10)),NULL,NULL,200,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657773742-6w6034.jpg','unread',0,NULL,NULL,'2026-04-08 14:16:14','2026-04-08 14:16:14',101,NULL,'Rústica','[{"name":"Masasumi Kakizaki","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(629,'Bestiarius #5','Bestiarius',5,NULL,'978-8-417-37302-3',NULL,'Masasumi Kakizaki','Masasumi Kakizaki',NULL,NULL,'Milky Way Ediciones',NULL,'2018-01-30',NULL,NULL,replace(replace('Cover Art by Masasumi Kakizaki\rContiene Tojushi Bestiarius Vol.1 #5\r\nAño 87 después de Cristo.\r\nEl exterminio de los subhumanos planeado por Domiciano se acelera a pasos agigantados. Capturado por Roma, Lucius se verá obligado a luchar en el Coliseo contra aquellos a quienes, hasta hace poco, tenía la firme convicción de defender. Sin embargo, los sueños de libertad de Arthur, Finn, Elaine y todos aquellos que desean la paz entre bestias y subhumanos no deben morir jamás...','\r',char(13)),'\n',char(10)),NULL,NULL,200,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657776199-djzh9c.jpg','unread',0,NULL,NULL,'2026-04-08 14:16:16','2026-04-08 14:16:16',101,NULL,'Rústica','[{"name":"Masasumi Kakizaki","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(630,'Bestiarius #6','Bestiarius',6,NULL,'978-8-417-37375-7',NULL,'Masasumi Kakizaki','Masasumi Kakizaki',NULL,NULL,'Milky Way Ediciones',NULL,'2018-12-27',NULL,NULL,replace(replace('Cover Art by Masasumi Kakizaki\r\nContiene Tojushi Bestiarius Vol.1 #6','\r',char(13)),'\n',char(10)),NULL,NULL,200,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657778184-u380p1.jpg','unread',0,NULL,NULL,'2026-04-08 14:16:19','2026-04-08 14:16:19',101,NULL,'Rústica','[{"name":"Masasumi Kakizaki","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(631,'Bestiarius #7','Bestiarius',7,NULL,'978-8-417-82043-5',NULL,'Masasumi Kakizaki','Masasumi Kakizaki',NULL,NULL,'Milky Way Ediciones',NULL,'2019-08-29',NULL,NULL,replace(replace('Cover Art by Masasumi Kakizaki\rContiene Tojushi Bestiarius Vol.1 #7\r\nAño 88 después de Cristo.\r\nFinn y Durandal han sido superados con claridad por Ciro y Longinus. Consciente de que vencer a Roma es imposible y que la obsesión del emperador son él y su &quot;padre&quot;, Finn decide dirigirse a Roma para ofrecer un trato a Domiciano: le entregará su vida a cambio de que deje de perseguir al pueblo libre. Sin embargo, el emperador no es el único que tiene algo que decir sobre su propuesta... ¡¡He aquí el desenlace de esta épica lucha por la libertad!!','\r',char(13)),'\n',char(10)),NULL,NULL,200,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657781484-hok9mz.jpg','unread',0,NULL,NULL,'2026-04-08 14:16:22','2026-04-08 14:16:22',101,NULL,'Rústica','[{"name":"Masasumi Kakizaki","role":"Guion, Dibujo, Tinta"}]');
