INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(633,'Dead Dead Demons Dededede Destruction #2','Dead Dead Demons Dededede Destruction',2,NULL,'978-8-467-92239-4',NULL,'Inio Asano','Inio Asano',NULL,NULL,'Norma Editorial',NULL,'2016-03-18',NULL,NULL,replace(replace('SEGUNDO VOLUMEN DEL ÚLTIMO TRABAJO DE INIO ASANO\r\nLos tokiotas han adaptado su vida diaria a los platillos volantes que sobrevuelan la ciudad, sin preocuparse demasiado por los invasores… e ignorando si algunos ya están entre ellos.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657803048-55hv1h.jpg','unread',0,NULL,NULL,'2026-04-08 14:16:43','2026-04-08 14:16:43',102,NULL,'rustica','[{"name":"Inio Asano","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(634,'Dead Dead Demons Dededede Destruction #3','Dead Dead Demons Dededede Destruction',3,NULL,'978-8-467-92428-2',NULL,'Inio Asano','Inio Asano',NULL,NULL,'Norma Editorial',NULL,'2016-09-30',NULL,NULL,replace(replace('TERCER VOLUMEN DEL ÚLTIMO TRABAJO DE INIO ASANO\r\nLos tokiotas han adaptado su vida diaria a los platillos volantes que sobrevuelan la ciudad, sin preocuparse demasiado por los invasores… e ignorando si algunos ya están entre ellos.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657805142-ecnhww.jpg','unread',0,NULL,NULL,'2026-04-08 14:16:45','2026-04-08 14:16:45',102,NULL,'rustica','[{"name":"Inio Asano","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(635,'Dead Dead Demons Dededede Destruction #4','Dead Dead Demons Dededede Destruction',4,NULL,'978-8-467-92557-9',NULL,'Inio Asano','Inio Asano',NULL,NULL,'Norma Editorial',NULL,'2017-02-22',NULL,NULL,replace('HAY MUCHOS “INVASORES” ÚLTIMAMENTE, ¿NO?\rFutaba y su ambiguo amigo Makoto se trasladan a Tokio, el epicentro de la invasión, para empezar la universidad. Allí conocen a Kadode, Ouran y compañía, quienes intentarán —a su manera— adaptarse a la vida universitaria y llevar cada una a su modo su particular cruzada en contra (o a favor) de los “invasores”.','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657807252-gqgbyz.jpg','unread',0,NULL,NULL,'2026-04-08 14:16:47','2026-04-08 14:16:47',102,NULL,'rustica','[{"name":"Inio Asano","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(636,'Dead Dead Demons Dededede Destruction #5','Dead Dead Demons Dededede Destruction',5,NULL,'978-8-467-92673-6',NULL,'Inio Asano','Inio Asano',NULL,NULL,'Norma Editorial',NULL,'2017-06-23',NULL,NULL,replace(replace('¿SE ACERCA IRREMEDIABLEMENTE EL FIN DE LA\r\nHUMANIDAD?\r\nDiversos grupos sociales siguen enfrentándose respecto a qué hacer con los invasores: aniquilarlos o aceptarlos como parte de una nueva sociedad. Mientras, Ouran y Kadode deciden “adoptar” a Ooba, cuyo cuerpo ha sido ocupado por un “invasor”, lo que aparte de causarles algún problemilla que otro, les ayudará a posicionarse...','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657809026-3b57c9.jpg','unread',0,NULL,NULL,'2026-04-08 14:16:49','2026-04-08 14:16:49',102,NULL,'rustica','[{"name":"Inio Asano","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(637,'Dead Dead Demons Dededede Destruction #6','Dead Dead Demons Dededede Destruction',6,NULL,'978-8-467-93001-6',NULL,'Inio Asano','Inio Asano',NULL,NULL,'Norma Editorial',NULL,'2018-02-23',NULL,NULL,replace('FALTA UN MES PARA EL FIN DE LA HUMANIDAD\rParece que el fin de la humanidad está a la vuelta de la esquina, aunque los habitantes de Tokio cada vez están más cansados del tema de los “invasores” y  parece que movimientos como SHIP se deshinchan... Mientras, Kadode y Ouran siguen sus vidas, y con ellas, sus extraños líos amorosos... aunque una con más suerte que la otra.','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657811341-i8te9f.jpg','unread',0,NULL,NULL,'2026-04-08 14:16:52','2026-04-08 14:16:52',102,NULL,'rustica','[{"name":"Inio Asano","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(638,'Dead Dead Demons Dededede Destruction #7','Dead Dead Demons Dededede Destruction',7,NULL,NULL,NULL,'Inio Asano','Inio Asano',NULL,NULL,'Norma Editorial',NULL,'2020-03-06',NULL,NULL,'Un cómic de Inio Asano.Publicado por Norma Editorial',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657814293-9zzrfq.jpg','unread',0,NULL,NULL,'2026-04-08 14:16:54','2026-04-08 14:16:54',102,NULL,'rustica','[{"name":"Inio Asano","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(639,'Dead Dead Demons Dededede Destruction #8','Dead Dead Demons Dededede Destruction',8,NULL,'978-8-467-94424-2',NULL,'Inio Asano','Inio Asano',NULL,NULL,'Norma Editorial',NULL,'2021-03-26',NULL,NULL,'Un cómic de Inio Asano.Publicado por Norma Editorial',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657816192-dcnmnm.jpg','unread',0,NULL,NULL,'2026-04-08 14:16:56','2026-04-08 14:16:56',102,NULL,'rustica','[{"name":"Inio Asano","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(640,'Dead Dead Demons Dededede Destruction #9','Dead Dead Demons Dededede Destruction',9,NULL,'978-8-467-94533-1',NULL,'Inio Asano','Inio Asano',NULL,NULL,'Norma Editorial',NULL,'2021-09-03',NULL,NULL,replace(replace('¡SEGUIMOS EN UN VIAJE A TRAVÉS DE LOS RECUERDOS DE OURAN!\r\nOoba y Makoto siguen explorando los recuerdos de Ouran y observan cómo va desarrollándose su amistad con Kadode. Tras conocer al “invasor” y ocultarlo, lo disfrazan de Isobeyan y él, a cambio, les ofrece herramientas futurísticas con las que llevar a cabo el bien. Sin embargo, Kadode decide tomarse la justicia por su mano hasta el punto de cometer lo irreparable...','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657818281-9ryiqd.jpg','unread',0,NULL,NULL,'2026-04-08 14:16:59','2026-04-08 14:16:59',102,NULL,'rustica','[{"name":"Inio Asano","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(641,'Dead Dead Demons Dededede Destruction #10','Dead Dead Demons Dededede Destruction',10,NULL,'978-8-467-95903-1',NULL,'Inio Asano','Inio Asano',NULL,NULL,'Norma Editorial',NULL,'2022-09-23',NULL,NULL,'LA VUELTA DEL MAESTRO Vuelve el Maestro Asano con el penúltimo tomo de esta serie. La exactitud en el detallismo de los dibujos de Asano está a la altura del carácter magnético de sus personajes. Unos entrañables, otros extraños, pero todos dejando huella. Solo él podría conseguir que empaticemos con la especie invasora que llegó a Tokyo 3 años atrás. Una vez más, Asano nos muestra la importancia de la amistad y el cariño en un mundo caótico y abocado a la destrucción.',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657824847-i7jhq2.jpg','unread',0,NULL,NULL,'2026-04-08 14:17:06','2026-04-08 14:17:06',102,NULL,'rustica','[{"name":"Inio Asano","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(642,'Dead Dead Demons Dededede Destruction #11','Dead Dead Demons Dededede Destruction',11,NULL,'978-8-467-95904-8',NULL,'Inio Asano','Inio Asano',NULL,NULL,'Norma Editorial',NULL,'2023-04-14',NULL,NULL,'Un cómic de Inio Asano.Publicado por Norma Editorial',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657830697-7m7nn9.jpg','unread',0,NULL,NULL,'2026-04-08 14:17:11','2026-04-08 14:17:11',102,NULL,'rustica','[{"name":"Inio Asano","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(643,'Dead Dead Demons Dededede Destruction #12','Dead Dead Demons Dededede Destruction',12,NULL,'978-8-467-96353-3',NULL,'Inio Asano','Inio Asano',NULL,NULL,'Norma Editorial',NULL,'2023-08-04',NULL,NULL,'LA HUMANIDAD TERMINÓ AQUEL DÍA. La nave nodriza que, durante tantos años, ha sobrevolado Tokio y se ha convertido en un elemento más del paisaje urbano, parece a punto de explotar. ¿Podrán reaccionar a tiempo los ciudadanos del mundo? ¿Seguirán con sus anodinas preocupaciones y pueriles intereses cuando la humanidad está a un paso de la destrucción?',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657833074-83jagd.jpg','unread',0,NULL,NULL,'2026-04-08 14:17:13','2026-04-08 14:17:13',102,NULL,'rustica','[{"name":"Inio Asano","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(644,'El Barrio de la Luz','El Barrio de la Luz',NULL,NULL,'978-8-467-92655-2',NULL,'Inio Asano','Inio Asano',NULL,NULL,'Norma Editorial',NULL,'2017-04-28',NULL,NULL,'Los vecinos del Barrio de la luz pueden parecer personas cualquiera, como tú y como yo. Y en cierto modo lo son. Sin embargo, si miras a través de los ojos de Inio Asano, sus historias resultarán ser más conmovedoras y únicas de lo que a priori puede parecer. Otro genial recopilatorio de historias cortas del autor que mejor capta las inquietudes de las nuevas generaciones.',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657850186-cap7z9.jpg','read',0,NULL,NULL,'2026-04-08 14:17:33','2026-04-08 18:18:14',NULL,8.5,'Rústica','[{"name":"Inio Asano","role":"Guion, Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(645,'Nijigahara Holograph','Nijigahara Holograph',NULL,NULL,'978-8-494-23173-5',NULL,'Inio Asano','Inio Asano',NULL,NULL,'Milky Way Ediciones',NULL,'2014-09-23',NULL,NULL,'Entre los niños del pueblo se propaga un escalofriante rumor: una criatura misteriosa acecha en el túnel que hay detrás de la escuela. Cuando el cuerpo sin vida de la madre de Arie es encontrado a la entrada del túnel, la leyenda parece confirmarse. Con el fin de apaciguar la ira de la bestia, los niños deciden ofrecer en sacrificio a la desafortunada chica, quien parece ser la causa de la maldición.',NULL,NULL,300,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657880651-fa6i2q.jpg','read',0,NULL,NULL,'2026-04-08 14:18:03','2026-04-08 18:18:14',NULL,23.95,'Rústica','[{"name":"Inio Asano","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(646,'El fin del mundo y antes del amanecer','El fin del mundo y antes del amanecer',NULL,NULL,'978-8-467-92209-7',NULL,'Inio Asano','Inio Asano',NULL,NULL,'Norma Editorial',NULL,'2016-04-11',NULL,NULL,'MAGNÍFICO RECOPILATORIO DE HISTORIAS CORTAS DEL GENIAL INIO ASANO Una estudiante de instituto que quiere dejar su pequeña ciudad, un oficinista de mediana edad que se queda en paro y se busca a sí mismo, una chica que se replantea su vida varios años tras acabar su adolescencia, un mangaka que vuelve a su pueblo natal… Relatos cortos llenos de la magia y la sensibilidad de Inio Asano.',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657903153-vgca49.jpg','unread',0,NULL,NULL,'2026-04-08 14:18:25','2026-04-08 14:18:25',NULL,11.43,'Rústica','[{"name":"Inio Asano","role":"Guion, Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(647,'La chica a la orilla del mar #1','La chica a la orilla del mar',1,NULL,'84940-87-48-7',NULL,'Inio Asano','Inio Asano',NULL,NULL,'Milky Way Ediciones',NULL,'2014-01-13',NULL,NULL,replace(replace('Sato e Isobe, dos adolescentes que viven sus días de colegiales en un tranquilo pueblo costero. Ambos deciden embarcarse en una relación puramente física, pero pronto se darán cuenta que dejar de lado los sentimientos resulta muy complicado.\r\nInio Asano actualmente goza de gran popularidad entre públicos de todas las edades debido a sus historias llenas de realismo y enorme carga emocional.','\r',char(13)),'\n',char(10)),NULL,NULL,420,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657924241-p4ye1r.jpg','read',0,NULL,NULL,'2026-04-08 14:18:47','2026-04-08 18:18:14',103,18,'Rústica','[{"name":"Inio Asano","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(648,'La chica a la orilla del mar #2','La chica a la orilla del mar',2,NULL,'978-8-494-08749-3',NULL,'Inio Asano','Inio Asano',NULL,NULL,'Milky Way Ediciones',NULL,'2014-03-19',NULL,NULL,replace(replace('Sato e Isobe, dos adolescentes que viven sus días de colegiales en un tranquilo pueblo costero. Ambos deciden embarcarse en una relación puramente física, pero pronto se darán cuenta que dejar de lado los sentimientos resulta muy complicado.\r\nInio Asano actualmente goza de gran popularidad entre públicos de todas las edades debido a sus historias llenas de realismo y enorme carga emocional.','\r',char(13)),'\n',char(10)),NULL,NULL,420,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657930969-0l7eah.jpg','read',0,NULL,NULL,'2026-04-08 14:18:51','2026-04-08 18:18:14',103,NULL,'Rústica','[{"name":"Inio Asano","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(649,'A Silent Voice #1','A Silent Voice',1,NULL,'978-8-494-35401-4',NULL,'Yoshitoki Oima','Yoshitoki Oima',NULL,NULL,'Milky Way Ediciones',NULL,'2015-02-24',NULL,NULL,replace(replace('&quot;Shôko Nishimiya... Odiaba tanto a esa chica.&quot;\r\nLa diversión y la aventura son el lema de Shôya Ishida, un chico capaz de cualquier cosa con tal de vencer el aburrimiento. Pero su vida cambiará drásticamente tras conocer a Shôko Nishimiya, una chica sorda que ha sido transferida a su escuela.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657962621-zqryvn.jpg','read',0,NULL,NULL,'2026-04-08 14:19:25','2026-04-08 18:18:14',104,8,'Rústica','[{"name":"Yoshitoki Oima","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(650,'A Silent Voice #2','A Silent Voice',2,NULL,'978-8-494-35406-9',NULL,'Yoshitoki Oima','Yoshitoki Oima',NULL,NULL,'Milky Way Ediciones',NULL,'2015-04-22',NULL,NULL,replace(replace('&quot;¡Nishimiya, espera!&quot;\r\nCinco años más tarde, justo antes de quitarse la vida, Shôya Ishida decide buscar a Shôko Nishimiya, su antigua compañera de clase. Cuando tiene lugar el reencuentro y se dispone a pedirle perdón a la chica, sus voces se unen dando lugar a una inesperada sorpresa.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657972295-gsz4c8.jpg','read',0,NULL,NULL,'2026-04-08 14:19:32','2026-04-08 18:18:14',104,8,'Rústica','[{"name":"Yoshitoki Oima","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(651,'A Silent Voice #3','A Silent Voice',3,NULL,'978-8-494-40646-1',NULL,'Yoshitoki Oima','Yoshitoki Oima',NULL,NULL,'Milky Way Ediciones',NULL,'2015-06-23',NULL,NULL,replace(replace('&quot;¿Acaso tengo miedo de acercarme a Nishimiya?&quot;\r\nShôya decide seguir viviendo para devolverle a Shôko la felicidad que le arrebató. Por ella, volverá a enfrentarse a un pasado con el que decidió cortar para siempre hace mucho tiempo. Sorprendentemente, la relación entre Shôya y Shôko se transforma por completo.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657973979-53rcgj.jpg','read',0,NULL,NULL,'2026-04-08 14:19:35','2026-04-08 18:18:14',104,8,'Rústica','[{"name":"Yoshitoki Oima","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(652,'A Silent Voice #4','A Silent Voice',4,NULL,'978-8-494-42963-7',NULL,'Yoshitoki Oima','Yoshitoki Oima',NULL,NULL,'Milky Way Ediciones',NULL,'2015-08-25',NULL,NULL,replace(replace('&quot;Quiérete a ti misma&quot;\r\nShôko Nishimiya es una chica sorda que después de varios años se reencuentra con Shôya, un antiguo compañero de clase. Su círculo de amistades se expande cuando Sahara, Ueno, Kawai, Mashiba y Nagatsuka entran en escena. Lo que Shôya desconoce es que sus esfuerzos por devolverle la ilusión a Shôko darán un giro inesperado a su propia vida.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657977610-mlewn5.jpg','read',0,NULL,NULL,'2026-04-08 14:19:38','2026-04-08 18:18:14',104,8,'Rústica','[{"name":"Yoshitoki Oima","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(653,'A Silent Voice #5','A Silent Voice',5,NULL,'978-8-494-45663-3',NULL,'Yoshitoki Oima','Yoshitoki Oima',NULL,NULL,'Milky Way Ediciones',NULL,'2015-10-20',NULL,NULL,replace(replace('&quot;Desde que me reencontré con Nishimiya, mi vida ha cambiado por completo.&quot;\r\nTras retomar el contacto con Nishimiya, Shôya se ha abierto a un mundo de posibilidades. Shôko comienza a colaborar en la película de Nagatsuka y Shôya empieza a vivir el verano más feliz de su vida. No obstante, la preocupación pronto se apodera de él. Una preocupación que, de repente, ocasionará una gran crisis en toda la pandilla.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657980524-wltldh.jpg','read',0,NULL,NULL,'2026-04-08 14:19:41','2026-04-08 18:18:14',104,8,'Rústica','[{"name":"Yoshitoki Oima","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(654,'A Silent Voice #6','A Silent Voice',6,NULL,'978-8-494-49001-9',NULL,'Yoshitoki Oima','Yoshitoki Oima',NULL,NULL,'Milky Way Ediciones',NULL,'2015-12-28',NULL,NULL,replace(replace('&quot;Desde que me reencontré con Nishimiya, mi vida ha cambiado por completo.&quot;\r\nPasado y presente vuelven a verse las caras. Shôya sufre el rechazo de sus compañeros y sus viejos traumas invaden su mundo. Por su parte, Shôko no puede evitar sentirse culpable e intenta suicidarse. El tiempo se ha detenido para ambos, mientras el resto de la pandilla divaga pensativa hasta derrumbarse.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775657997919-cb8hiy.jpg','read',0,NULL,NULL,'2026-04-08 14:19:59','2026-04-08 18:18:14',104,8,'Rústica','[{"name":"Yoshitoki Oima","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(655,'A Silent Voice #7','A Silent Voice',7,NULL,'978-8-494-51103-5',NULL,'Yoshitoki Oima','Yoshitoki Oima',NULL,NULL,'Milky Way Ediciones',NULL,'2016-02-22',NULL,NULL,replace(replace('“Hasta luego, Nishimiya.”\r\nSumido en la desesperación, Shôya decide mirar al frente y esforzarse por subsanar todo el daño que ha causado; a partir de ahora, escuchará las voces de cada uno de sus amigos.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775658000402-3ptwkc.jpg','read',0,NULL,NULL,'2026-04-08 14:20:01','2026-04-08 18:18:14',104,8,'Rústica','[{"name":"Yoshitoki Oima","role":"Guion, Dibujo, Tinta"}]');
