INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(871,'Berserk #3','Berserk',3,NULL,'978-8-499-47305-5',NULL,'Kentaro Miura','Kentaro Miura',NULL,NULL,'Glénat España - Editores de Tebeos / Panini Comics España',NULL,'2011-12-01',NULL,NULL,replace('Un guerrero vestido de negro de pies a cabeza con una gigantesca espada al hombro, Guts, pues ese es su nombre, prosigue sus aventuras junto a su inseparable compañero, el elfo Puck.\rHan llegado a una ciudad donde impera el terror. A base de torturar a sus súbditos, su señor se ha dejado corroer hasta tal punto por la maldad que se ha transformado en un monstruo. Después de tantos años, Guts va a enfrentarse a la Mano de Dios. ¿Por qué los persigue? Para aclarar este misterio, el relato da un giro inesperado que nos devuelve a los orígenes de Guts.','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775731778765-d69hi7.jpg','read',0,NULL,NULL,'2026-04-09 10:49:39','2026-04-09 10:52:46',121,NULL,'Rústica','[{"name":"Kentaro Miura","role":"Guion, Dibujo, Tinta"}]');
