INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(885,'Berserk #17','Berserk',17,NULL,'978-8-499-47552-3',NULL,'Kentaro Miura','Kentaro Miura',NULL,NULL,'Glénat España - Editores de Tebeos / Panini Comics España',NULL,'2012-10-01',NULL,NULL,'Guts es un guerrero vestido de negro de los pies a la cabeza que porta una gigantesca espada más larga que su propia estatura y un robusto brazo ortopédico de hierro... Allá adonde va se forman ríos de sangre y montañas de cadáveres.',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775731812208-85jdl3.jpg','read',0,NULL,NULL,'2026-04-09 10:50:13','2026-04-09 10:52:46',121,NULL,'Rústica','[{"name":"Kentaro Miura","role":"Guion, Dibujo, Tinta"}]');
