INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(887,'Berserk #19','Berserk',19,NULL,'978-8-499-47554-7',NULL,'Kentaro Miura','Kentaro Miura',NULL,NULL,'Glénat España - Editores de Tebeos / Panini Comics España',NULL,'2012-11-01',NULL,NULL,'Han pasado dos años desde el horrible “Eclipse” en el que la banda del Halcón fue, en la práctica, aniquilada. Guts parte de viaje con el objetivo de vengarse de los Mano de Dios, a cuyas filas se ha sumado Griffith después de transmigrarse en la figura de Femto, y sus apóstoles. Una negra sombra empieza a cubrir el mundo entero.',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775731816722-uhomdq.jpg','read',0,NULL,NULL,'2026-04-09 10:50:17','2026-04-09 10:52:46',121,NULL,'Rústica','[{"name":"Kentaro Miura","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(888,'Berserk #20','Berserk',20,NULL,'978-8-499-47555-4',NULL,'Kentaro Miura','Kentaro Miura',NULL,NULL,'Glénat España - Editores de Tebeos / Panini Comics España',NULL,'2012-11-01',NULL,NULL,'Guts, empeñado en rescatar a Kasca, se interna en la “Torre de la Condena”, ¡pero Mozgus y sus verdugos se interponen en su camino! El “apóstol” que orquestaba los diabólicos acontecimientos desde las sombras se muestra y empieza a revelar los apabullantes sucesos que están a punto de tener lugar. En medio de la desesperación de miles de personas, ¡un nuevo “Eclipse” va a producirse!',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775731819311-tjo2r9.jpg','read',0,NULL,NULL,'2026-04-09 10:50:19','2026-04-09 10:52:46',121,NULL,'Rústica','[{"name":"Kentaro Miura","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(889,'Berserk #21','Berserk',21,NULL,'978-8-499-47556-1',NULL,'Kentaro Miura','Kentaro Miura',NULL,NULL,'Glénat España - Editores de Tebeos / Panini Comics España',NULL,'2012-12-01',NULL,NULL,'Han pasado dos años desde el horrible “Eclipse” en el que la banda del Halcón fue, en la práctica, aniquilada. Guts parte de viaje con el objetivo de vengarse de los Mano de Dios, a cuyas filas se ha sumado Griffith después de transmigrarse en la figura de Femto, y sus apóstoles. Una negra sombra empieza a cubrir el mundo entero. Guts se encamina a la “Torre de la condena” en busca de la desaparecida Kasca y, en el camino, se cruza con el Caballero de la Calavera, que le comunica que va a producirse un falso “Eclipse” en tierra santa. En esos momentos, miles de refugiados se agolpan alrededor de la “Torre de la condena” y, en medio de la desesperación más absoluta, se suceden las cazas de brujas y herejes. Precisamente Kasca ha caído en las garras de los herejes, que la encumbran como una verdadera bruja...',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775731820974-ymh6rx.jpg','read',0,NULL,NULL,'2026-04-09 10:50:22','2026-04-09 10:52:46',121,NULL,'Rústica','[{"name":"Kentaro Miura","role":"Guion, Dibujo, Tinta"}]');
