INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(893,'Berserk #25','Berserk',25,NULL,'978-8-499-47655-1',NULL,'Kentaro Miura','Kentaro Miura',NULL,NULL,'Glénat España - Editores de Tebeos / Panini Comics España',NULL,'2013-04-01',NULL,NULL,replace(replace('Kentaro Miura Guts y los suyos se meten de lleno en una batalla contra trols y otras criaturas monstruosas en el pueblo de Enoch. Mientras el guerrero negro desmiembra con su enorme espada a innumerables trols, la bruja Schierke, a la que conocieron en el bosque encantado, activa su “magia” y les rescata a todos del peligro. Guts se queda anonadado al comprobar el efecto de la magia, ¡pero la embestida de los monstruos es tan fuerte que la situación sigue siendo complicada!!\r\n¡Incluye póster desplegable!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775731831929-7i81la.jpg','read',0,NULL,NULL,'2026-04-09 10:50:33','2026-04-09 10:52:46',121,NULL,'Rústica','[{"name":"Kentaro Miura","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(894,'Berserk #26','Berserk',26,NULL,'978-8-499-47656-8',NULL,'Kentaro Miura','Kentaro Miura',NULL,NULL,'Glénat España - Editores de Tebeos / Panini Comics España',NULL,'2013-05-01',NULL,NULL,'Pensando en el bien de Kasca, Guts parte de viaje hacia Elfhelm, la tranquila patria de Puck. En el trayecto se reencuentra con Isidro, Farnese y Serpico, y, tras comprender que él solo jamás podrá proteger a Kasca, permite que les acompañen. De camino hacia la ciudad portuaria de Vritannis, conocen a Schierke, joven discípula de la bruja Flora. Guts acepta el trato que le propone Flora, defender la ciudad de Enoch del ataque de los trols a cambio de una poción mágica que les proteja. Pero en el fragor del combate, ¡Kasca y Farnese desaparecen!',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775731834680-2dpikg.jpg','read',0,NULL,NULL,'2026-04-09 10:50:35','2026-04-09 10:52:46',121,NULL,'Rústica','[{"name":"Kentaro Miura","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(895,'Berserk #27','Berserk',27,NULL,'978-8-499-47657-5',NULL,'Kentaro Miura','Kentaro Miura',NULL,NULL,'Glénat España - Editores de Tebeos / Panini Comics España',NULL,'2013-06-01',NULL,NULL,'Pensando en el bien de Kasca, Guts parte de viaje hacia Elfhelm, la tranquila patria de Puck. En el trayecto se reencuentra con Isidro, Farnese y Serpico, y, tras comprender que él solo jamás podrá proteger a Kasca, permite queles acompañen. De camino hacia la ciudad portuaria de Vritannis, conocen a Schierke, joven discípula de la bruja Flora. Guts acepta el trato que le propone Flora, defender la ciudad de Enoch del ataque de los trols a cambio de una poción mágica que les proteja. Mientras tanto, Zodd y Grunbeld, apóstoles de la Nueva Banda del Halcón, atacan y queman el Árbol de los Espíritus. Guts se pone la armadura de Berserk, una poderosísima arma sagrada que le dota de una gran fuerza, pero, al mismo tiempo, somete a su cuerpo a un terrible desgaste que puede incluso provocarle la muerte.',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775731836501-uwcljx.jpg','read',0,NULL,NULL,'2026-04-09 10:50:37','2026-04-09 10:52:46',121,NULL,'Rústica','[{"name":"Kentaro Miura","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(896,'Berserk #28','Berserk',28,NULL,'978-8-499-47658-2',NULL,'Kentaro Miura','Kentaro Miura',NULL,NULL,'Glénat España - Editores de Tebeos / Panini Comics España',NULL,'2013-07-01',NULL,NULL,replace(replace('Guts acepta defender la ciudad de Enoch del ataque de los trols a cambio de una poción mágica que les proteja. A su vez, Zodd y Grunbeld, apóstoles de la Nueva Banda del Halcón, atacan el Árbol de los Espíritus. Guts se pone la armadura maldita de Berserk, y a pesar de las heridas que esta le provoca, sigue peleando. Mientras tanto Griffith libera a Charlotte, reina de Midland, de las garras del emperador kushano. Por fin, Guts y sus amigos llegan a la costa, al puerto de Vritanis.\r\n¡Incluye póster desplegable!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775731838523-vmoez6.jpg','read',0,NULL,NULL,'2026-04-09 10:50:39','2026-04-09 10:52:46',121,NULL,'Rústica','[{"name":"Kentaro Miura","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(897,'Berserk #29','Berserk',29,NULL,'978-8-499-47659-9',NULL,'Kentaro Miura','Kentaro Miura',NULL,NULL,'Glénat España - Editores de Tebeos / Panini Comics España',NULL,'2013-08-01',NULL,NULL,'Pensando en el bien de Kasca, Guts parte de viaje hacia Elfhelm, la patria de Puck. En el trayecto se reencuentra con Isidro, Farnese y Serpico, y, tras comprender que él solo jamás podrá proteger a Kasca, permite que le acompañen. Y lo mismo sucede con Schierke, la hechicera que ha encontrado en el bosque del Árbol de los Espíritus. Por fin llegan a Vritanis, un puerto amurallado donde se concentran los ejércitos de todos los confines del papado para luchar contra los kushanos y controlar el puerto de embarque a Elfhelm. Se trata también del lugar donde el destino da un giro inesperado porque Schierke se reencuentra con Sonia e Isidro con Mule. ¿Cuáles serán las consecuencias de ese reencuentro?',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775731840637-ckv48z.jpg','read',0,NULL,NULL,'2026-04-09 10:50:41','2026-04-09 10:52:46',121,NULL,'Rústica','[{"name":"Kentaro Miura","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(898,'Berserk #30','Berserk',30,NULL,'978-8-499-47660-5',NULL,'Kentaro Miura','Kentaro Miura',NULL,NULL,'Glénat España - Editores de Tebeos / Panini Comics España',NULL,'2013-10-01',NULL,NULL,'Pensando en el bien de Kasca, Guts parte de viaje hacia Elfhelm, la patria de Puck. En el trayecto se reencuentra con Isidro, Farnese y Serpico, y, tras comprender que él solo jamás podrá proteger a Kasca, permite que le acompañen. Y lo mismo sucede con Schierke, la hechicera que ha encontrado en el bosque del Árbol de los Espíritus. Por fin llegan a Vritanis, un puerto amurallado donde se concentran los ejércitos de todos los confines del papado para luchar contra los kushanos. Por otro lado, una vez ya en Vritanis, Schierke se reencuentra con Sonia e Isidro con Mule, un encuentro de consecuencias inesperadas.',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775731842933-sz9wnj.jpg','read',0,NULL,NULL,'2026-04-09 10:50:43','2026-04-09 10:52:46',121,NULL,'Rústica','[{"name":"Kentaro Miura","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(899,'Berserk #31','Berserk',31,NULL,'978-8-499-47306-2',NULL,'Kentaro Miura','Kentaro Miura',NULL,NULL,'Glénat España - Editores de Tebeos / Panini Comics España',NULL,'2011-10-01',NULL,NULL,replace('En un abrir y cerrar de ojos, Vritannis se torna un mar de sangre por el súbito ataque de las tropas pisaca de Kushan sobre el ejército de la Santa Sede, que se había reunido en la ciudad.\rEn medio del caos, Guts y su grupo se apresuran para llegar al buque de guerra de Eath que les transportará a Elfhelm, pero encuentran el puerto infestado de soldados pisaca. Guts y Schierke intentan abrirse paso entre las hordas enemigas, ¡pero se topan con el general kushano Deva!\r¡¡La exótica magia del lugarteniente aboca sobre Guts y los suyos una serie de ataques inimaginables!!','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775731845333-gu9y7m.jpg','read',0,NULL,NULL,'2026-04-09 10:50:45','2026-04-09 10:52:46',121,NULL,'Rústica','[{"name":"Kentaro Miura","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(900,'Berserk #32','Berserk',32,NULL,'978-8-499-47307-9',NULL,'Kentaro Miura','Kentaro Miura',NULL,NULL,'Glénat España - Editores de Tebeos / Panini Comics España',NULL,'2011-12-01',NULL,NULL,replace('A pesar de llevar la armadura de berserker, Guts nada puede hacer ante los mortíferos relámpagos de Ganishka, el gran emperador de Kushan. Cuando este último le propone someterse a sus órdenes, Guts se percata de que el emperador es un apóstol contrario a los Mano de Dios. Entonces los apóstoles alados de la Nueva Banda del Halcón, liderados por Zodd, se lanzan contra Ganishka, pero no consiguen desestabilizarle. ¡En medio de la refriega, Guts y Zodd toman una sorprendente decisión!\rIncluye un póster desplegable.','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775731848154-3p0vk2.jpg','read',0,NULL,NULL,'2026-04-09 10:50:48','2026-04-09 10:52:46',121,NULL,'Rústica','[{"name":"Kentaro Miura","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(901,'Berserk #33','Berserk',33,NULL,'978-8-499-47383-3',NULL,'Kentaro Miura','Kentaro Miura',NULL,NULL,'Glénat España - Editores de Tebeos / Panini Comics España',NULL,'2012-02-01',NULL,NULL,'Guts y los suyos consiguen por fin levar anclas hacia Elfhelm, pero el fiero guerrero está gravemente herido a resultas de su duelo frontal contra el gran emperador Ganishka. A pesar de notar en las cercanías la presencia de Griffith, Guts decide zarpar de todos modos, por el bien de sus compañeros y el suyo propio. Durante la travesía marítima, todos los miembros del grupo siguen esforzándose por alcanzar sus objetivos a la par que se toman un merecido e inusual respiro. ¡Sin embargo, de golpe y porrazo aparecen en el horizonte unos barcos piratas que pretenden abordarles!',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775731851010-jq3fs3.jpg','unread',0,NULL,NULL,'2026-04-09 10:50:52','2026-04-09 10:50:52',121,NULL,'Rústica','[{"name":"Kentaro Miura","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(902,'Berserk #34','Berserk',34,NULL,'978-8-499-47384-0',NULL,'Kentaro Miura','Kentaro Miura',NULL,NULL,'Glénat España - Editores de Tebeos / Panini Comics España',NULL,'2012-04-01',NULL,NULL,'Ganishka protagoniza una nueva transmigración con el fin de superar a los Mano de Dios y adopta el aspecto de una gigantesca bestia diabólica, tan altaque llega a perforar el mismísimo cielo. El gran emperador avanza aplastan-do a sus propias tropas mientras los hombres de la Nueva Banda del Halcón se convencen de que se encuentran ante “la materialización de todas las ca-lamidades”, es decir, la mismísima “bestia del Apocalipsis”, y depositan su?e en los milagros del “Halcón de la Luz”. ¡¡Empieza una apabullante batallade la Nueva Banda del Halcón de Grifth, sus soldados demoníacos y sustropas humanas!!',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775731853680-l5ijr8.jpg','unread',0,NULL,NULL,'2026-04-09 10:50:54','2026-04-09 10:50:54',121,NULL,'Rústica','[{"name":"Kentaro Miura","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(903,'Berserk #35','Berserk',35,NULL,'978-8-499-47385-7',NULL,'Kentaro Miura','Kentaro Miura',NULL,NULL,'Glénat España - Editores de Tebeos / Panini Comics España',NULL,'2012-06-01',NULL,NULL,'El mundo ha cambiado. Hasta el último rincón del planeta se extiende esta nueva realidad en la que campan a sus anchas monstruos y seres sobrenaturales de todo tipo que, solo unas horas antes, pertenecían al ámbito de la imaginación humana. En el centro de este nuevo mundo se materializa la inmensa e imponente capital del Halcón: “Falconia”. Griffith, que ha visto cumplido su sueño, entra en la ciudad con su Nueva Banda del Halcón y se dispone a gobernar el mundo desde ella. El mundo transmutado enseña también sus colmillos a Guts y sus compañeros, que prosiguen su travesía marítima hasta la isla de Skellig, donde se encuentra Elfhelm. ¡¡Un barco fantasma como el de las leyendas lanza su feroz ataque!!',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775731857765-8od8qr.jpg','unread',0,NULL,NULL,'2026-04-09 10:50:58','2026-04-09 10:50:58',121,NULL,'Rústica','[{"name":"Kentaro Miura","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(904,'Berserk #36','Berserk',36,NULL,'978-8-499-47386-4',NULL,'Kentaro Miura','Kentaro Miura',NULL,NULL,'Glénat España - Editores de Tebeos / Panini Comics España',NULL,'2013-02-01',NULL,NULL,'El devenir de la Banda del Halcón, que había alcanzado la gloria en el reino de Midland, cambió drásticamente en cuestión de horas. Todo empezó al anochecer, cuando Guts abandonó el grupo. Aquella misma noche, Griffith despojó de su virginidad a la princesa Charlotte. Al enterarse el rey de esto último a la mañana siguiente, encarceló a Griffith y envió a su ejército regular a exterminar a la Banda del Halcón.',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775731860685-av7pik.jpg','unread',0,NULL,NULL,'2026-04-09 10:51:01','2026-04-09 10:51:01',121,NULL,'Rústica','[{"name":"Kentaro Miura","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(905,'Berserk #37','Berserk',37,NULL,'978-8-491-67016-2',NULL,'Kentaro Miura','Kentaro Miura',NULL,NULL,'Glénat España - Editores de Tebeos / Panini Comics España',NULL,'2017-06-28',NULL,NULL,'El siguiente capítulo de una de las más aclamadas series manga de todos los tiempos. Un viaje épico y salvaje a un reino de fantasía. Guts es un guerrero vestido de negro de los pies a la cabeza que porta una gigantesca espada más larga que su propia estatura y un robusto brazo ortopédico de hierro.',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775731863378-zzkyz8.jpg','unread',0,NULL,NULL,'2026-04-09 10:51:04','2026-04-09 10:51:04',121,NULL,'Rústica','[{"name":"Kentaro Miura","role":"Guion, Dibujo, Tinta"}]');
