INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(985,'Vagabond #1','Vagabond',1,NULL,'978-8-415-92294-0',NULL,'Takehiko Inoue','Takehiko Inoue',NULL,NULL,'Ivrea',NULL,'2003-05-01',NULL,NULL,'Cuenta la historia del legendario espadachín Musashi Miyamoto, la figura histórica más importante del Japón en lo que se refiere al desarrollo de las técnicas de lucha con espada. Desde su juventud como el violento e iracundo joven llamado Takezo, sobreviviendo (aun estando del lado perdedor) a una de las batallas más sangrientas de la historia: Sekigahara; hasta su decisión de pasar a llamarse Musashi y embarcarse en una búsqueda de autosuperación personal que lo llevará a enfrentarse con los más grandes expertos de las artes marciales del país.',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775818874523-yczlws.jpg','read',0,NULL,NULL,'2026-04-10 11:01:18','2026-04-12 12:16:51',128,8,'Rústica','[{"name":"Takehiko Inoue","role":"Guion, Dibujo, Tinta"}]');
