INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1061,'Shark Panic','Shark Panic',NULL,NULL,'979-1-387-82237-8',NULL,'Tsukasa Saimura',NULL,NULL,NULL,'Arechi Manga',NULL,'2025-08-14',NULL,NULL,'Un grupo de amigos del instituto se reúne después de muchos años en la lancha de uno de ellos, para pasar un día lleno de recuerdos entre rayos de sol y copas de alcohol. Todo vaticina uno de los mejores días del verano... pero la irrupción de un tiburón en las tranquilas aguas que los rodean provocará que entre los antiguos amigos despierte el instinto de supervivencia. Contra el escualo que los ronda, la única solución es matar o morir... ¡y nunca dejarse arrastrar por el pánico hacia los tiburones!',NULL,NULL,352,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775819293793-vz07ql.jpg','unread',0,NULL,NULL,'2026-04-10 11:08:16','2026-04-10 11:08:16',NULL,16,'Rústica','[{"name":"Tsukasa Saimura","role":""}]');
