INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1129,'Happiness','Happiness',NULL,NULL,'978-8-494-49000-2',NULL,'Usamaru Furuya','Usamaru Furuya',NULL,NULL,'Milky Way Ediciones',NULL,'2015-12-28',NULL,NULL,'Happiness reúne la historias más significativas de Furuya para la editorial Shogakukan. Un tomo de más de 270 páginas que se mueve entre personajes poco convencionales y lo políticamente incorrecto. Argumentos que dejan atrás la trivialidad para adentrarse en tramas bien construidas acompañadas de un dibujo realista y evocador, que multiplica el drama de cada historia.',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775851309081-1xwrb5.jpg','unread',0,NULL,NULL,'2026-04-10 20:01:53','2026-04-10 20:01:53',NULL,8.5,'rustica','[{"name":"Usamaru Furuya","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1130,'Nabi','Nabi',NULL,NULL,'978-8-496-96708-3',NULL,'Kim Yeon-Joo',NULL,NULL,NULL,'Ivrea',NULL,'2007-11-01',NULL,NULL,'Historias cortas ambientadas en un ficticio continente asiático. De una estética muy a lo Clamp. El éxito mundial recibido por este tomo ha llevado a la autora a comenzar a trabajar en hacer una serie regular en un futuro cercano.',NULL,NULL,172,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775851327323-7e4x9l.jpg','read',0,NULL,NULL,'2026-04-10 20:02:10','2026-04-12 12:09:34',NULL,8.5,NULL,'[{"name":"Kim Yeon-Joo","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1131,'El gourmet solitario','El gourmet solitario',NULL,NULL,'978-8-492-76968-1',NULL,'Masayuki Kusumi','Jiro Taniguchi',NULL,NULL,'Astiberri',NULL,'2010-08-01',NULL,NULL,replace(replace('Un hombre solitario, con un trabajo que le permite una gran movilidad, recorre las calles de Tokio y otras localidades japonesas para visitar a sus clientes. Cada día es una ocasión para redescubrir un barrio que conoce o para conocer uno nuevo. Pero para este hombre, siempre solitario, el momento de la comida constituye una auténtica aventura, casi un ritual. A lo largo de 19 capítulos «El gourmet solitario» nos presenta otros tantos platos de la cocina tradicional japonesa.\r\nA través de la mirada curiosa de este viajero gastronómico, los autores, Jiro Taniguchi y Masayuki Kusumi, trazan un auténtico retrato sociológico de Japón y su riqueza gastronómica.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775851350086-bkbekh.jpg','read',0,5,NULL,'2026-04-10 20:02:34','2026-04-12 12:09:34',NULL,18,'rustica','[{"name":"Jiro Taniguchi","role":"Dibujo"},{"name":"Masayuki Kusumi","role":"Guion"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1132,'Paseos de un gourmet solitario','Paseos de un gourmet solitario',NULL,NULL,'978-8-416-25164-3',NULL,'Jiro Taniguchi','Jiro Taniguchi',NULL,NULL,'Astiberri',NULL,'2016-03-24',NULL,NULL,replace(replace('Allí donde lo llevan sus pasos o lo conduce la inspiración del momento, Goro Inokashira, el gourmet solitario, come lo que le apetece, cuando le apetece y como le apetece. Se admira con sencillez de cada descubrimiento, a veces se equivoca y sazona su comida con pesadumbre, o transforma un modesto plato de verduras salteadas en un encuentro único.\r\nA través de la mirada curiosa de este viajero, los autores, Jiro Taniguchi y Masayuki Kusumi, trazan un auténtico retrato sociológico de Japón y de su riqueza gastronómica en una sucesión de nuevas historias que dan continuidad, dieciséis años después, a El gourmet solitario (Astiberri, 2010).\r\n“También en el manga hay sitio para la cocina o viceversa. Una suerte de Proust nipón donde el dulce del bizcocho es sustituido por el salado del arroz almidonado, y el té se convierte en salsa de soja, para rendir tributo a los sentidos y entregarse a la pasión gastronómica desde la línea clara del maestro Taniguchi”. Jorge Mola, El País Semanal','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775851366088-oz5eez.jpg','read',0,5,NULL,'2026-04-10 20:02:53','2026-04-12 12:09:34',NULL,14,'Rústica','[{"name":"Jiro Taniguchi","role":"Guion, Dibujo, Tinta"},{"name":"Masayuki Kusumi","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1133,'Antología Osamu Tezuka','Antología Osamu Tezuka',NULL,NULL,'978-8-491-46782-3',NULL,'Osamu Tezuka','Osamu Tezuka',NULL,NULL,'Planeta Cómic',NULL,'2018-04-10',NULL,NULL,'Recopilatorio de cuatro de las mejores obras autoconclusivas en la trayectoria del Dios del Manga. Dentro de nuestra ampliada línea Babel podrás disfrutar de cuatro historias clásicas e indispensables del genio Tezuka. La antología recopila los títulos Metrópolis, Lost World, Next World y la Isla del tesoro. Un tomo único que hará las delicias de los seguidores del genio.',NULL,NULL,936,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775851387503-rvn2d8.jpg','unread',0,NULL,NULL,'2026-04-10 20:03:10','2026-04-10 20:03:10',NULL,12.62,NULL,'[{"name":"Osamu Tezuka","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1134,'The Crow','The Crow',NULL,NULL,'978-8-484-49920-6',NULL,'James O''Barr','James O''Barr',NULL,NULL,'Glénat España - Editores de Tebeos',NULL,'2005-12-01',NULL,NULL,replace(replace('Días antes de su boda, Eric Draven y su novia Shelly son asesinados violentamente por una pandilla. Un años más tarde, un misterioso cuervo guía a Eric en su camino de regreso desde el más allá para comenzar una venganza despiadada.\r\nNacida del dolor experimentado por su creador, J. O','\r',char(13)),'\n',char(10)),NULL,NULL,128,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775851427056-z1pl3t.jpg','unread',0,NULL,NULL,'2026-04-10 20:03:52','2026-04-10 20:03:52',NULL,23.95,'Rústica','[{"name":"James O''Barr","role":"Guion, Dibujo, Tinta"}]');
