INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1155,'Mouse Guard #2','Mouse Guard',2,NULL,'978-8-467-90217-4',NULL,'David Petersen',NULL,NULL,NULL,'Norma Editorial',NULL,'2010-07-01',NULL,NULL,'Un cómic de David Petersen.Publicado por Norma Editorial',NULL,NULL,204,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775983841079-5onyjy.jpg','read',0,NULL,NULL,'2026-04-12 08:50:41','2026-04-12 12:08:58',139,NULL,'Cartoné 204 pp','[{"name":"David Petersen","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1156,'Mouse Guard #3','Mouse Guard',3,NULL,'978-8-467-91441-2',NULL,'David Petersen',NULL,NULL,NULL,'Norma Editorial',NULL,'2014-04-15',NULL,NULL,replace(replace('En 1115, mucho antes de los acontecimientos del invierno de 1152, el guardián Celanawe se embarcó en busca del Hacha Negra.\r\nUna peligrosa aventura que lo llevó, acompañado de su única pariente y de un joven y aguerrido marinero, a atravesar el mar del Norte, conocer al Rey de los hurones y enfrentarse a bestias mucho más grandes que ratones. Ha llegado la hora de contar el origen de Hacha Negra.','\r',char(13)),'\n',char(10)),NULL,NULL,204,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775983843249-egunn1.jpg','read',0,NULL,NULL,'2026-04-12 08:50:44','2026-04-12 12:08:58',139,NULL,'Cartoné 204 pp','[{"name":"David Petersen","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1157,'Pesadilla antes de Navidad de Tim Burton','Pesadilla antes de Navidad de Tim Burton',NULL,NULL,'978-8-467-44849-8',NULL,'Jun Asuka','Jun Asuka',NULL,NULL,'Planeta Cómic',NULL,'2007-10-01',NULL,NULL,'La ciudad de Halloween centra todos sus esfuerzos en la noche del 31 de octubre, el día de los muertos, en el que monstruos, fantasmas, brujas y todo tipo de seres aterradores toman las calles. Desde el alcalde hasta el vampiro más humilde se esfuerzan por crear el mejor Halloween posible... pero Jack Skellington está un poco deprimido. El rey de Halloween, tras siglos haciendo lo mismo año tras año, está aburrido, busca algo nuevo, algo... diferente. Y lo encuentra en la ciudad de la Navidad; ahora Jack tiene un nuevo objetivo, algo que lo anima a ponerse a trabajar: ¡este año, la Navidad la organiza Halloween!',NULL,NULL,184,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775983867949-58ueen.jpg','unread',0,NULL,NULL,'2026-04-12 08:51:11','2026-04-12 08:51:11',NULL,24.95,'Rústica','[{"name":"Jun Asuka","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1158,'Clamp. Art-book #1','Clamp. Art-book',1,NULL,NULL,NULL,'Clamp',NULL,NULL,NULL,'Norma Editorial',NULL,'2006-05-01',NULL,NULL,'CLAMP NORTH SIDE es una recopilación del excelente trabajo del célebre cuarteto de autoras, que comprende el período 1989-2002. Esta joya de 168 páginas a todo color ofrece ilustraciones originales de CLAMP , incluyendo series como CLOVER o MAGIC KNIGHT RAYEARTH , entre otras. También incluye el cómic original de la PRINCESA MOKONA, una entrevista exclusiva a CLAMP y un catálogo completo de todas las imágenes contenidas en el libro con una descripción de cada una.',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775983889281-1un2yj.jpg','read',0,NULL,NULL,'2026-04-12 08:51:31','2026-04-12 12:08:58',140,NULL,NULL,'[{"name":"Clamp","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1159,'Clamp. Art-book #2','Clamp. Art-book',2,NULL,'978-8-498-47020-8',NULL,'Clamp',NULL,NULL,NULL,'Norma Editorial',NULL,'2007-12-01',NULL,NULL,'CLAMP SOUTH SIDE es una muestra del arte del famoso cuarteto de autoras japonesas entre 1989 y 2002. Impreso en papel brillante y con una elegante cubierta mate, este libro nos regala X páginas a todo color donde encontramos material gráfico original no publicado en otros títulos de CLAMP, e ilustraciones de series como El ladrón de las mil caras, Patrulla especial Duklyon, CLAMP Club de detectives, Lawful Drug o El chico que me gusta, así como un catálogo completo de todas las imágenes destacadas con una descripción de cada uno. Destaca una exclusiva sección de cómo dibujar manga.',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775983894018-ni2mms.jpg','read',0,NULL,NULL,'2026-04-12 08:51:34','2026-04-12 12:08:58',140,NULL,NULL,'[{"name":"Clamp","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1160,'Cardcaptor Sakura Art-Book #2','Cardcaptor Sakura Art-Book',2,NULL,'978-8-484-49385-3',NULL,'Clamp',NULL,NULL,NULL,'Glénat España - Editores de Tebeos',NULL,'2003-03-01',NULL,NULL,'Un cómic de Clamp.Publicado por Glénat España - Editores de Tebeos',NULL,NULL,12,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775983929560-1efv8g.jpg','read',0,NULL,NULL,'2026-04-12 08:52:12','2026-04-12 12:08:58',141,11.43,'Rústica','[{"name":"Clamp","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1161,'Preciosa Oscuridad','Preciosa Oscuridad',NULL,NULL,'978-8-416-41701-8',NULL,'Fabien Vehlmann','Kerascoët',NULL,NULL,'Spaceman Books',NULL,'2015-03-25',NULL,NULL,replace(replace('Probablemente el cómic más sorprendente, bonito y cruel que se ha publicado o publicará en muchos años. Un señor de las moscas con personajes de cuento de hadas obligados a sobrevivir en un entorno hostil enfrentándose a los peores rasgos del ser humano.\r\nUna obra exquisita y multipremiada que tarda en olvidarse y que obliga a ser releída para comprobar que de verdad has leído “eso”. Un cómic impresionante y brutal.','\r',char(13)),'\n',char(10)),NULL,NULL,96,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775983961450-ot1hw0.jpg','read',0,4,NULL,'2026-04-12 08:52:43','2026-04-12 12:08:58',NULL,13.96,NULL,'[{"name":"Fabien Vehlmann","role":"Guion"},{"name":"Kerascoët","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1162,'Neogénesis Evangelion Art Book','Neogénesis Evangelion Art Book',NULL,NULL,NULL,NULL,'Yoshiyuki Sadamoto','Khara',NULL,NULL,'Norma Editorial',NULL,'1999-04-01',NULL,NULL,replace(replace('Edición original: Newtype 100% Collection Neon Genesis Evangelion JAP\r\n56 ilustraciones a todo color, 102 fotogramas, 54 archivos, 208 ilustraciones de personajes, más de 1500 diseños de producción, 5000 anotaciones... Los archivos de Nerv por fin desvelados.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984009178-cj2x8c.jpg','read',0,NULL,NULL,'2026-04-12 08:53:30','2026-04-12 12:08:58',NULL,NULL,'rustica','[{"name":"Yoshiyuki Sadamoto","role":""},{"name":"Khara","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1163,'Helen de Wyndhorn','Helen de Wyndhorn',NULL,NULL,'978-8-467-97551-2',NULL,'Tom King','Bilquis Evely',NULL,NULL,'Norma Editorial',NULL,'2025-04-04',NULL,NULL,replace(replace('Contiene: Helen of Wyndhorn #1-6\r\nDEL EQUIPO GANADOR DE UN PREMIO EISNER QUE CREÓ SUPERGIRL: LA MUJER DEL MAÑANA, PRESENTAMOS ESTA ÉPICA HISTORIA GÓTICA DE ESPADA Y BRUJERÍA QUE ES UNA FUSIÓN ENTRE CONAN EL BÁRBARO Y EL MAGO DE OZ\r\nTras la trágica muerte de su padre, C.K. Cole, el apreciado escritor de literatura pulp y creador del popular personaje guerrero Othan, a Helen Cole la llaman de vuelta a la enorme e ilustre finca de su abuelo: la Casa Wyndhorn. \r\nMarcada por la muerte prematura de su padre, y perdida en un nuevo y extraño mundo, una Helen siempre abrazada a una botella de vino siembra el caos al llegar. Sin embargo, sus caóticas costumbres empezarán a suavizarse cuando descubra toda una vida de secretos ocultos en la miríada de salas y pasillos de la enorme mansión. Pues fuera de sus paredes, en el bosque, esperan las legendarias aventuras que antes había hallado en las historias de su padre.\r\nAdemás de una increíble historia de crecimiento, superación de la pérdida y búsqueda de propósito, este volumen incluye un apartado con bocetos del proceso de creación de Bilquis Evely e ilustraciones adicionales de Walt Simonson, Greg Smallwood, Clay Mann, Elsa Charretier, Tula Lotay, Massimo Carnevale, Fábio Moon, Gabriel Hernández Walta y Jill Thompson.','\r',char(13)),'\n',char(10)),NULL,NULL,176,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984058840-fr9gxf.jpg','read',0,3,NULL,'2026-04-12 08:54:20','2026-04-12 08:54:24',NULL,29.5,NULL,'[{"name":"Tom King","role":"Guion"},{"name":"Bilquis Evely","role":"Dibujo, Tinta"},{"name":"Mat Lopes","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1164,'El pájaro y la serpiente','El pájaro y la serpiente',NULL,NULL,'978-8-419-43715-0',NULL,'Borja González','Borja González',NULL,NULL,'Reservoir Books',NULL,'2023-09-21',NULL,NULL,'Llega el esperado y enigmático cierre del ciclo Las Tres Noches, que consagra a Borja González como el autor más sugerente de la novela gráfica en España. En el castillo, las mujeres aguardan a que los hombres lleguen de una larga expedición de caza. La dinastía es antigua y ceremoniosa, la perpetúan los ritos que dan a cada miembro un solemne papel que cumplir. Matilde y su hermana Teresa, a?cionadas a las historias de terror, habían acordado escapar juntas pero algo no sale como planearon. En El pájaro y la serpiente, Borja González cierra Las Tres Noches: un brillante ciclo de novelas grá?cas, compuesto también por The Black Holes y Grito nocturno. Este es un volumen aún más tenebroso y sutil que los anteriores y en el que vibra un oscuro enigma sin palabras.',NULL,NULL,200,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984080331-39lb35.jpg','read',0,NULL,NULL,'2026-04-12 08:54:41','2026-04-12 12:08:58',NULL,23.9,'Rústica','[{"name":"Borja González","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1165,'Bajo los árboles, donde nadie te ve','Bajo los árboles, donde nadie te ve',NULL,NULL,'978-8-410-33229-4',NULL,'Patrick Horvath','Patrick Horvath',NULL,NULL,'Astiberri',NULL,'2025-03-20',NULL,NULL,replace(replace('Samantha Strong, adorable osa parda, ciudadana ejemplar y asesina en serie del pueblo de ensueño Woodbrook solo tiene una norma: “no asesines a tus vecinos”. Al fin y al cabo, hay un montón de posibles víctimas en la ciudad al otro lado del bosque, y cuando te has esforzado tanto como Sam por conseguir una vida acogedora y un negocio próspero, rodeada de amables vecinos animales y del aroma de los cedros y las tartas de manzana, lo último que te interesa es perturbar la paz. Así que, cuando un habitante de Woodbrook es asesinado brutalmente, Sam se ve obligada a hacer todo lo posible para encontrar a su rival antes de que el número de víctimas aumente y el sheriff Patterson empiece a ladrar (literalmente) a quien no debe.\r\nBajo los árboles, donde nadie te ve es el debut del guionista y cineasta Patrick Horvath, nominado al premio Eisner 2024 a Mejor serie nueva. Horvath ha demostrado con esta obra una habilidad admirable para acoplar las escenas más macabras con una estética propia de las fábulas infantiles. El guion, dotado de ironía y sentido del humor, permite profundizar en la esencia de la condición humana a través de sus diferentes capas. Mientras tanto, el dibujo reconforta y se siente como una manta en pleno invierno. En una época en que los cozy crimes están copando las librerías, este es el tipo de cómic que apetece leer junto a la chimenea.','\r',char(13)),'\n',char(10)),NULL,NULL,152,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984097447-6rt1p4.jpg','read',0,4,NULL,'2026-04-12 08:54:58','2026-04-12 08:55:01',NULL,19,'tapa dura','[{"name":"Patrick Horvath","role":"Guion, Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1166,'Mitos Nórdicos #1','Mitos Nórdicos',1,NULL,'978-8-411-12041-8',NULL,'Neil Gaiman','Philip Craig Russell',NULL,NULL,'Planeta Cómic',NULL,'2022-07-06',NULL,NULL,replace(replace('Una nueva adaptación de la fantástica obra de Gaiman.\r\nEl autor más vendido del New York Times, Neil Gaiman, y el legendario autor ganador de varios Premios Eisner P. Craig Russell insuflan vida nueva a los mitos nórdicos a través de la creación de los Nueve Mundos y al narrar las aventuras de Thor, Odín y Loki desde su origen hasta el Ragnarok.\r\nTras American Gods y Sandman, Gaiman y Russell llevan a cabo la adaptación a cómic de la exitosa novela del mismo nombre. Con colaboraciones de dibujantes como Mike Mignola, Jerry Ordway, Jill Thompson o David Rubín.\r\nRecopila:\r\n- Norse Mythology #1 (10-20) - #6 (03-21).','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984117331-7bxzvw.jpg','unread',0,NULL,NULL,'2026-04-12 08:55:21','2026-04-12 08:55:21',142,20,'tapa blanda','[{"name":"Neil Gaiman","role":"Guion"},{"name":"Philip Craig Russell","role":"Guion, Dibujo"},{"name":"Jerry Ordway","role":"Dibujo, Tinta"},{"name":"Mike Mignola","role":"Dibujo, Tinta"},{"name":"Jill Thompson","role":"Dibujo, Tinta, Color"},{"name":"David Rubín","role":"Dibujo, Tinta, Color"},{"name":"Piotr Kowalski","role":"Dibujo, Tinta"},{"name":"Dave Stewart","role":"Color"},{"name":"Lovern Kindzierski","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1167,'Mitos Nórdicos #2','Mitos Nórdicos',2,NULL,'978-8-411-40489-1',NULL,'Neil Gaiman','Philip Craig Russell',NULL,NULL,'Planeta Cómic',NULL,'2023-04-05',NULL,NULL,replace(replace('La adaptación al cómic de las leyendas nórdicas.\r\nEl autor superventas Neil Gaiman y el premiado ilustrador P. Craig Russell insuflan nueva vida a las antiguas historias nórdicas en esta adaptación al cómic de la exitosa novela Mitos nórdicos.\r\nGaiman y Russell vuelven a unirse a unos dibujantes legendarios para ofrecerle al lector más mitos nórdicos, entre ellos el origen de la poesía y un hidromiel por el que muchos morirán, el accidentado viaje de Thor y Loki a la tierra de los gigantes, el lamentable trato de los dioses que podría hacerles perder la vida eterna, y el viaje del querido dios Frey al Valhalla y más allá en busca de algo que echaba en falta en su vida. Ilustrado por Matt Horak, Mark Buckingham, Gabriel Hernández Walta y Sandy Jarrell.\r\nRecopila:\r\n- Norse Mythology II #1 (06-21) - #6 (11-21).','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984125144-id6mbm.jpg','unread',0,NULL,NULL,'2026-04-12 08:55:25','2026-04-12 08:55:25',142,NULL,'Cartoné 144 pp','[{"name":"Neil Gaiman","role":"Guion"},{"name":"Philip Craig Russell","role":"Guion, Dibujo"},{"name":"Matt Horak","role":"Dibujo, Tinta"},{"name":"Lovern Kindzierski","role":"Color"},{"name":"Mark Buckingham","role":"Dibujo, Tinta"},{"name":"Gabriel Hernández Walta","role":"Dibujo, Tinta, Color"},{"name":"Sandy Jarrell","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1168,'Mitos Nórdicos #3','Mitos Nórdicos',3,NULL,'978-8-411-61181-7',NULL,'Neil Gaiman','Philip Craig Russell',NULL,NULL,'Planeta Cómic',NULL,'2024-05-22',NULL,NULL,replace(replace('Continúa la brillante y respetuosa interpretación que hace Neil Gaiman de la vasta colección de estas atemporales historias nórdicas.\r\nEn este tercer volumen, Gaiman y Russell vuelven a unirse a unos dibujantes legendarios para ofrecerle al lector más mitos nórdicos, entre ellos una búsqueda en la que Thor y Tyr se enfrentan a una giganta de múltiples cabezas, serpientes marinas que escupen fuego y más criaturas mitológicas extrañas; el viaje de Odín al fin del mundo y, por último, el Ragnarok, el destino final de los dioses.\r\nEl autor superventas Neil Gaiman y el premiado ilustrador P. Craig Russell insuflan nueva vida a las antiguas historias nórdicas en esta adaptación al cómic de la exitosa novela Mitos nórdicos.\r\nRecopila los números 1 a 6 de Mitos nórdicos III, ilustrados por P. Craig Russell, David Rubín, Colleen Doran y Galen Showman.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984127956-uvtghv.jpg','unread',0,NULL,NULL,'2026-04-12 08:55:29','2026-04-12 08:55:29',142,NULL,'Cartoné 144 pp','[{"name":"Neil Gaiman","role":"Guion"},{"name":"Philip Craig Russell","role":"Guion, Dibujo"},{"name":"David Rubín","role":"Dibujo"},{"name":"Gallen Showman","role":""},{"name":"Colleen Doran","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1169,'Lucifer. Integral #1','Lucifer. Integral',1,NULL,'978-8-417-10608-9',NULL,'Mike Carey','Chris Weston',NULL,NULL,'ECC Ediciones',NULL,'2017-05-23',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: The Sandman presents Lucifer núms. 1-3 USA, Lucifer núms. 1-20 USA\r\nInauguramos el formato integral omnibus con este recopilatorio que recoge la serie limitada Lucifer: La opción Lucero del alba y las primeras veinte entregas de la colección regular protagonizada por Lucifer. ¡Más de 500 páginas de material procedente de uno de los puntos álgidos del sello Vertigo! Tras pedir a Morfeo que le amputara sus alas y custodiara las llaves del infierno, Lucifer disfruta de su retiro terrenal regentando un piano bar en la ciudad de Los Ángeles. Una tranquila existencia interrumpida por Amenadiel emisario del Cielo que solicita su ayuda en una misión crucial.','\r',char(13)),'\n',char(10)),NULL,NULL,680,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984145475-4305x6.jpg','unread',0,NULL,NULL,'2026-04-12 08:55:49','2026-04-12 08:55:49',143,23.95,'Rústica','[{"name":"Mike Carey","role":"Guion"},{"name":"Chris Weston","role":"Dibujo"},{"name":"Dean Ormston","role":"Dibujo"},{"name":"Peter Gross","role":"Dibujo"},{"name":"Ryan Kelly","role":"Dibujo"},{"name":"Scott Hampton","role":"Dibujo"},{"name":"Warren Pleece","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1170,'Lucifer. Integral #2','Lucifer. Integral',2,NULL,'978-8-417-27636-2',NULL,'Mike Carey','Craig Hamilton',NULL,NULL,'ECC Ediciones',NULL,'2017-12-05',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Lucifer núms. 21-49 USA\r\nEn su intento de emular a Dios, Lucifer ha creado un cosmos privado cuyos habitantes tienen el derecho (o la obligación) de ser libres. Pero lo que empieza como un paraíso puede devenir en infierno cuando fuerzas exteriores deciden asaltar ese nuevo territorio. El desenlace culmina con el ingreso de Lucifer en el reino de los muertos, aunque de una forma muy distinta a la que cabría esperar','\r',char(13)),'\n',char(10)),NULL,NULL,680,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984152970-05booy.jpg','unread',0,NULL,NULL,'2026-04-12 08:55:54','2026-04-12 08:55:54',143,NULL,'Rústica','[{"name":"Mike Carey","role":"Guion"},{"name":"Craig Hamilton","role":""},{"name":"David Hahn","role":""},{"name":"Dean Ormston","role":""},{"name":"Peter Gross","role":""},{"name":"Ryan Kelly","role":""},{"name":"Ted Naifeh","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1171,'Lucifer. Integral #3','Lucifer. Integral',3,NULL,'978-8-417-48007-3',NULL,'Mike Carey','Colleen Doran',NULL,NULL,'ECC Ediciones',NULL,'2018-06-05',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Lucifer núms. 50-75 USA, Lucifer: Nirvana USA (one-shot)  696 pp, PVP 54.50 €\r\nARGUMENTO: El Árbol del Cosmos se derrumba y el lobo Fenrir aprovecha la ocasión para tomar el Cielo por asalto. Lucifer intenta detenerlo emprendiendo un viaje cuya primera etapa lo traslada a las puertas del infierno y cuya última escala lo conduce directamente a presencia de Dios. Reunidos en un escenario improbable, Dios y el diablo zanjan al fin sus diferencias y responden a la pregunta de si realmente existe o no el libre albedrío.\r\nEste volumen agrupa los números 50 a 75 de Lucifer, escritos por Mike Carey (Hellblazer) y dibujados por Peter Gross (The Unwritten) y Ryan Kelly (Northlanders), con la participación de artistas de la talla de P. Craig Russell, Marc Hempel, Ronald Wimberly, Colleen Doran, Michael William Kaluta, Dean Ormston y Zander Cannon. Como broche final, el tomo incluye el especial Lucifer: Nirvana, firmado por Carey y el dibujante John J. Muth.','\r',char(13)),'\n',char(10)),NULL,NULL,696,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984155782-6a3tjv.jpg','unread',0,NULL,NULL,'2026-04-12 08:55:56','2026-04-12 08:55:56',143,54.5,'Rústica','[{"name":"Mike Carey","role":"Guion"},{"name":"Colleen Doran","role":"Dibujo"},{"name":"Dean Ormston","role":"Dibujo"},{"name":"Jon J. Muth","role":"Dibujo"},{"name":"Marc Hempel","role":"Dibujo"},{"name":"Philip Craig Russell","role":"Dibujo"},{"name":"Peter Gross","role":"Dibujo"},{"name":"Ronald Wimberly","role":"Dibujo"},{"name":"Ryan Kelly","role":"Dibujo"},{"name":"Zander Cannon","role":"Dibujo"},{"name":"Michael Kaluta","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1172,'Descender #1','Descender',1,NULL,'978-8-416-25142-1',NULL,'Jeff Lemire','Dustin Nguyen',NULL,NULL,'Astiberri',NULL,'2016-02-18',NULL,NULL,replace(replace('TIM-21, un joven androide, despierta de un largo sueño para descubrir que unos extraños robots alienígenas han atacado a la humanidad, al tiempo que se prohíbe la mera existencia de todos los autómatas. TIM-21 puede tener la clave de lo que quieren esos invasores y el porqué de su llegada, lo que le convierte en el robot más buscado.\r\nUna apasionada y profunda odisea cósmica en la que se enfrentan humanos contra máquinas y mundos contra otros mundos.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984170113-ec9plt.jpg','read',0,NULL,NULL,'2026-04-12 08:56:13','2026-04-12 12:08:58',144,17,'cartone','[{"name":"Jeff Lemire","role":""},{"name":"Dustin Nguyen","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1173,'Descender #2','Descender',2,NULL,'978-8-416-25170-4',NULL,'Jeff Lemire','Dustin Nguyen',NULL,NULL,'Astiberri',NULL,'2016-08-25',NULL,NULL,'Hace una década gigantescos robots, conocidos como los Cosechadores, aparecieron en la órbita del grupo de los nueve planetas centrales que forman el Consejo Galáctico Unido (CGU) y dejaron a toda la humanidad devastada antes de desaparecer. El pequeño robot TIM-21 puede tener la clave de lo que quieren esos invasores y el porqué de su llegada. Huyendo de las diversas facciones que tratan de controlarlo y junto con los robots Bandit y Driller, y un grupo de humanos dispuestos a protegerle, van a parar al asteroide donde se esconde la resistencia robótica....',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984180815-lyijzu.jpg','read',0,NULL,NULL,'2026-04-12 08:56:22','2026-04-12 12:08:58',144,17,'cartone','[{"name":"Jeff Lemire","role":""},{"name":"Dustin Nguyen","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1174,'Descender #3','Descender',3,NULL,'978-8-416-88014-0',NULL,'Jeff Lemire','Dustin Nguyen',NULL,NULL,'Astiberri',NULL,'2017-05-25',NULL,NULL,'Jeff Lemire y Dustin Nguyen profundizan en los secretos de los principales personajes con revelaciones que permiten saber más sobre las causas de la guerra entre humanos y androides, y que empujarán al pequeño robot Tim-21 hacia nuevos y peligrosos territorios en este tercer volumen de Descender. Él y sus compañeros de aventura luchan por mantenerse vivos en un universo en el que todos los androides han sido declarados fuera de la ley y los cazarrecompensas acechan en cada planeta.',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984183628-1wafjv.jpg','read',0,NULL,NULL,'2026-04-12 08:56:24','2026-04-12 12:08:58',144,17,'cartone','[{"name":"Jeff Lemire","role":""},{"name":"Dustin Nguyen","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1175,'Descender #4','Descender',4,NULL,'978-8-416-88041-6',NULL,'Jeff Lemire','Dustin Nguyen',NULL,NULL,'Astiberri',NULL,'2017-11-30',NULL,NULL,'Tim-21, Telsa y Quon consiguen escapar de Luna Máquina y comienzan la búsqueda del antiguo robot que puede tener la clave de los Cosechadores. Mientras tanto Andy y su heterogéneo equipo, que se acercan peligrosamente a Tim, se ven sacudidos por las revelaciones de Taladro. Antes de que el primer comic book de la edición en inglés de',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984186501-kbogc7.jpg','read',0,NULL,NULL,'2026-04-12 08:56:27','2026-04-12 12:08:58',144,17,'cartone','[{"name":"Jeff Lemire","role":""},{"name":"Dustin Nguyen","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1176,'Descender #5','Descender',5,NULL,'978-8-416-88063-8',NULL,'Jeff Lemire','Dustin Nguyen',NULL,NULL,'Astiberri',NULL,'2018-07-03',NULL,NULL,'Hace una década gigantescos robots, conocidos como los Cosechadores, aparecieron en la órbita del grupo de los nueve planetas centrales que forman el Consejo Galáctico Unido (CGU) y dejaron a toda la humanidad devastada antes de desaparecer. El pequeño robot TIM-21 puede tener la clave de lo que quieren esos invasores y el porqué de su llegada. En este nuevo episodio de Descender, se desencadena todo lo que se ha ido construyendo hasta ahora. La resistencia de los robots se levanta y tensa su zarpa de hierro sobre el universo cuando los orígenes de los Cosechadores son revelados y la galaxia entra en una guerra abierta.',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984189009-5wygei.jpg','read',0,NULL,NULL,'2026-04-12 08:56:29','2026-04-12 12:08:58',144,17,'cartone','[{"name":"Jeff Lemire","role":""},{"name":"Dustin Nguyen","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1177,'Descender #6','Descender',6,NULL,'978-8-416-88099-7',NULL,'Jeff Lemire','Dustin Nguyen',NULL,NULL,'Astiberri',NULL,'2019-02-14',NULL,NULL,replace(replace('Llega el esperado desenlace de la saga con Descender 6. Máquina de guerra. Hace una década gigantescos robots, conocidos como los Cosechadores, aparecieron en la órbita del grupo de los nueve planetas centrales que forman el Consejo Galáctico Unido (CGU) y dejaron a toda la humanidad devastada antes de desaparecer. El pequeño robot TIM-21 puede tener la clave de lo que quieren esos invasores y el porqué de su llegada.\r\nEn este tomo final, las diversas facciones que han estado persiguiendo a TIM-21 por fin se concentran alrededor del planeta oceánico Mata, mientras los robots emprenden su revolución galáctica. Pero nada puede preparar al joven androide Tim, ni a los lectores, para lo que va a pasar. Jeff Lemire y Dustin Nguyen ponen así fin a la saga Descender con un ritmo frenético y responden a todas las preguntas que los lectores han ido planteándose a lo largo de los cinco volúmenes anteriores. Emotivos y esperados reencuentros, nuevos universos, historias del pasado y lecciones sobre la convivencia para hacer de Descender 6. Máquina de guerra no sólo el fin de una era, sino también la plataforma de despegue de la siguiente','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984191643-29walp.jpg','read',0,NULL,NULL,'2026-04-12 08:56:32','2026-04-12 12:08:58',144,17,'cartone','[{"name":"Jeff Lemire","role":""},{"name":"Dustin Nguyen","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1178,'Gideon Falls #1','Gideon Falls',1,NULL,'978-8-417-57528-1',NULL,'Jeff Lemire','Andrea Sorrentino',NULL,NULL,'Astiberri',NULL,'2019-04-04',NULL,NULL,replace(replace('Contiene: Gideon Falls Vol. 1: The Black Barn (#1-6) USA.\r\nLa leyenda del granero negro habla de un edificio sobrenatural que ha aparecido una y otra vez a lo largo de la historia, sembrando la muerte y la locura a su paso. Ahora, en su misterio se entrelazan las vidas de dos hombres muy diferentes. Uno es un joven ermitaño, obsesionado con encontrar pistas ocultas en la basura urbana. El otro es un cura católico en decadencia, que encuentra su sitio en un pueblecito que esconde oscuros secretos. Ninguno de los dos está preparado para lo que hay dentro del granero negro.\r\nJeff Lemire (Black Hammer, Descender, Un tipo duro...) y Andrea Sorrentino plantean una reflexión sobre la obsesión, la enfermedad mental y la fe anclada en sólidos personajes.','\r',char(13)),'\n',char(10)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984207143-b93cni.jpg','read',0,NULL,NULL,'2026-04-12 08:56:51','2026-04-12 12:08:58',145,24.95,NULL,'[{"name":"Jeff Lemire","role":"Guion"},{"name":"Andrea Sorrentino","role":"Dibujo, Tinta"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1179,'Gideon Falls #2','Gideon Falls',2,NULL,'978-8-417-57554-0',NULL,'Jeff Lemire','Andrea Sorrentino',NULL,NULL,'Astiberri',NULL,'2019-10-31',NULL,NULL,replace(replace('Contiene: Gideon Falls Vol. 2: Original Sins (#7-11) USA.\r\nEl misterio que recae sobre el Granero Negro se acentúa en este segundo volumen de Gideon Falls. A medida que Norton, el joven solitario y atormentado que protagoniza la serie, se obsesiona aún más con la búsqueda de respuestas sobre el legendario Granero Negro, el Padre Fred, un cura católico con problemas de conducta, revela el secreto que hay detrás de una serie de asesinatos espeluznantes.\r\nJeff Lemire (Black Hammer. Descender. Un tipo duro) y Andrea Sorrentino consiguen hacer una obra de terror psicológico compleja, con una atmósfera inquietante, que recuerda a las grandes obras de terror clásico.','\r',char(13)),'\n',char(10)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984214984-udyfmo.jpg','read',0,NULL,NULL,'2026-04-12 08:56:55','2026-04-12 12:08:58',145,NULL,'grapa','[{"name":"Jeff Lemire","role":"Guion"},{"name":"Andrea Sorrentino","role":"Dibujo, Tinta"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1180,'Gideon Falls #3','Gideon Falls',3,NULL,'978-8-418-21500-1',NULL,'Jeff Lemire','Andrea Sorrentino',NULL,NULL,'Astiberri',NULL,'2020-06-23',NULL,NULL,replace(replace('Contiene: Gideon Falls Vol. 3: Stations of the Cross (#12-16) USA.\r\nLa pesadilla surrealista se intensifica al otro lado del espejo y el ritmo se acelera una vez adentrados en el Granero Negro. El Padre Burke sigue a un brutal asesino en el Gideon Falls de 1886. Un asesino que puede viajar por el tiempo y por el espacio. Un asesino llamado... ¿Norton Sinclair?\r\nJeff Lemire (Black Hammer, Ascender, Essex County) y Andrea Sorrentino mantienen la fuerza de esta compleja obra de terror psicológico con una atmósfera inquietante, que se vuelve frenética a medida que avanza la trama iniciando así un viaje salvaje.','\r',char(13)),'\n',char(10)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984217492-u7qz2b.jpg','read',0,NULL,NULL,'2026-04-12 08:56:58','2026-04-12 12:08:58',145,NULL,'Cartoné 160-136 pp','[{"name":"Jeff Lemire","role":"Guion"},{"name":"Andrea Sorrentino","role":"Dibujo, Tinta"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1181,'Gideon Falls #4','Gideon Falls',4,NULL,'978-8-418-21521-6',NULL,'Jeff Lemire','Andrea Sorrentino',NULL,NULL,'Astiberri',NULL,'2020-10-01',NULL,NULL,replace(replace('Contiene: Gideon Falls Vol. 4: The Pentoculus (#17-21) USA.\r\nDespués del viaje a través del tiempo y el espacio del capítulo anterior, Norton y Clara se ven atrapados en el pueblo de Gideon Falls con un psicópata asesino. Mientras tanto, Angie y el padre Fred se ven cara a cara con el obispo en el Gideon Falls de la gran ciudad, donde los secretos de la máquina pentáculo se revelan en todo su delirante esplendor. En medio del caos, ¿qué pasará cuando los Labradores por fin respondan a la llamada del deber?\r\nJeff Lemire (Black Hammer, Descender, Essex County) y Andrea Sorrentino (El viejo Logan, Green Arrow) empiezan a dar respuestas a los misterios de Gideon Falls, ganadora de un premio Eisner a la mejor serie nueva en 2019.','\r',char(13)),'\n',char(10)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984220003-s9zxsk.jpg','read',0,NULL,NULL,'2026-04-12 08:57:01','2026-04-12 12:08:58',145,NULL,'Cartoné 160-136 pp','[{"name":"Jeff Lemire","role":"Guion"},{"name":"Andrea Sorrentino","role":"Dibujo, Tinta"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1182,'Gideon Falls #5','Gideon Falls',5,NULL,'978-8-418-21562-9',NULL,'Jeff Lemire','Andrea Sorrentino',NULL,NULL,'Astiberri',NULL,'2021-05-27',NULL,NULL,replace('Contiene: Gideon Falls Vol. 5: Wicked Worlds (#22-26) USA.\rDespués de la alucinante destrucción del granero negro, los protagonistas se encuentran dispersos por el multiverso de Gideon Falls que estaba contenido en su interior. Mientras Angie intenta sobrevivir en una versión de 1984, Clara está sola en una versión del salvaje Oeste, y el padre Fred es un hombre desubicado en el Gideon Falls ciberpunk. Y cualquiera sabe dónde ha aterrizado Norton. ¡Y, aunque estos mundos parecen separados, el Hombre Que Ríe siempre está más cerca de lo que imaginas!\rJeff Lemire (Black Hammer, Ascender, Essex County) y Andrea Sorrentino (El viejo Logan, Green Arrow) nos proponen en el penúltimo volumen de la serie un salto de fe para salir del horror. El final está cerca de verdad.','\r',char(13)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984222876-wvqutz.jpg','read',0,NULL,NULL,'2026-04-12 08:57:03','2026-04-12 12:08:58',145,NULL,'Cartoné 160-136 pp','[{"name":"Dave Stewart","role":"Color"},{"name":"Jeff Lemire","role":"Guion"},{"name":"Andrea Sorrentino","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1183,'Gideon Falls #6','Gideon Falls',6,NULL,'978-8-418-21584-1',NULL,'Jeff Lemire','Andrea Sorrentino',NULL,NULL,'Astiberri',NULL,'2021-08-19',NULL,NULL,replace(replace('Contiene: Gideon Falls Vol. 6: The End (#27) USA.\r\nAl final cae la noche, las realidades convergen y nuestros héroes de Gideon Falls han llegado al centro del universo para situarse cara a cara con el Hombre Que Ríe y su legión del mal por última vez. El granero negro también ha vuelto, y antes de poder volver a sus realidades, nuestros protagonistas se verán obligados a enfrentarse a sus mayores miedos dentro de sus muros. Y tendrán que hacerlo juntos.\r\nJeff Lemire (Black Hammer, Ascender. Essex County) y Andrea Sorrentino ponen fin con este tomo a la serie que ha definido la actual era del terror en los cómics.','\r',char(13)),'\n',char(10)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984225243-r8p7fw.jpg','read',0,NULL,NULL,'2026-04-12 08:57:06','2026-04-12 12:08:58',145,NULL,'Cartoné 160-136 pp','[{"name":"Dave Stewart","role":"Color"},{"name":"Jeff Lemire","role":"Guion"},{"name":"Andrea Sorrentino","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1184,'I Hate Fairyland #1','I Hate Fairyland',1,NULL,'978-8-410-51275-7',NULL,'Skottie Young','Skottie Young',NULL,NULL,'Panini Comics España',NULL,'2017-11-22',NULL,NULL,replace(replace('Contiene I Hate Fairyland 1-5 USA\r\nSkottie Young, el genio detrás de las versiones bebé de los héroes Marvel y de la serie de Mapache Cohete, vuelve del revés todos los tópicos sobre los cuentos de hadas. Imagina un cruce entre el escenario de Alicia en el País de las Maravillas y la violencia de Masacre. Te presentamos a Gert, una mujer de cuarenta años atrapada en el cuerpo de una niña de seis que no puede escapar de un mundo mágico al que llegó hace tres décadas. Únete a ella y a su gigantesca hacha para averiguar quién sobrevivirá a aquella que odia el Reino de las Hadas.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984240385-329jty.jpg','read',0,NULL,NULL,'2026-04-12 08:57:24','2026-04-12 12:09:17',146,24,'lujo','[{"name":"Skottie Young","role":"Guion, Dibujo, Tinta"},{"name":"Jean-Francois Beaulieu","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1185,'I Hate Fairyland #2','I Hate Fairyland',2,NULL,'978-8-491-67346-0',NULL,'Skottie Young','Skottie Young',NULL,NULL,'Panini Comics España',NULL,'2018-03-22',NULL,NULL,'Contiene I Hate Fairyland 6-10 USA                             Saluda a Gertrude, la nueva reina del País de las Hadas. Después de treinta años perdida en un mundo de magia y atrapada en el cuerpo de una niña, Gert debe afrontar su mayor reto: gobernar el mundo que odia con todas sus fuerzas. ¡No te puedes perder esta hilarante historia!',NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984250126-pmz8wz.jpg','read',0,NULL,NULL,'2026-04-12 08:57:31','2026-04-12 12:09:17',146,NULL,'Cartoné 160-144 pp','[{"name":"Skottie Young","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1186,'I Hate Fairyland #3','I Hate Fairyland',3,NULL,'978-8-491-67482-5',NULL,'Skottie Young','Skottie Young',NULL,NULL,'Panini Comics España',NULL,'2018-07-26',NULL,NULL,'Contiene  I Hate Fairyland 11-15 USA                          Gert ha descubierto que haberse convertido en una psicópata asesina tal vez sea el motivo por el que no ha podido volver a casa en cuatro décadas. Por eso, ha llegado el momento de empezar el camino de la difícil redención. ¿Lo conseguirá?',NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984252572-eyezqf.jpg','read',0,NULL,NULL,'2026-04-12 08:57:33','2026-04-12 12:09:10',146,NULL,'Cartoné 160-144 pp','[{"name":"Skottie Young","role":"Guion, Dibujo, Tinta"},{"name":"Jean-Francois Beaulieu","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1187,'I Hate Fairyland #4','I Hate Fairyland',4,NULL,'978-8-413-34412-6',NULL,'Skottie Young','Skottie Young',NULL,NULL,'Panini Comics España',NULL,'2021-11-25',NULL,NULL,replace(replace('Contiene I Hate Fairyland 16 al 20 USA \r\nLo que comenzó siendo la historia de un niño de los más normal succionado por una tierra mágica para cumplir una misión estúpida ha cambiado el País de las Hadas para siempre. En la continuación de la endulzada sátira de fantasía de SKOTTIE YOUNG, Gertrude cede el centro de atención a Larry, Duncan Dragon y algunos de los otros actores secundarios de Fairyland, inadaptados y amenazas olvidadas.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984255149-xlql1x.jpg','unread',0,NULL,NULL,'2026-04-12 08:57:36','2026-04-12 08:57:36',146,NULL,'Cartoné 160-144 pp','[{"name":"Skottie Young","role":"Guion, Dibujo, Tinta"},{"name":"Jean-Francois Beaulieu","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1188,'Sex Criminals #1','Sex Criminals',1,NULL,'978-8-416-88020-1',NULL,'Matt Fraction','Chip Zdarsky',NULL,NULL,'Astiberri',NULL,'2017-07-05',NULL,NULL,'Suzie y Jon tienen una habilidad particular: cuando tienen un orgasmo, el tiempo se suspende y el mundo a su alrededor se paraliza. De adolescentes, usaban ese don para escapar de una realidad gris y a veces cruel. Al conocerse en una fiesta, se enrollan y descubren que ambos tienen ese poder, y empiezan entonces a jugar juntos a entrar en esa dimensión orgásmica para divertirse y deshacerse de viejos fantasmas de su juventud... hasta que se les ocurre aprovechar ese periodo fuera del tiempo para robar un banco. Fraction y Zdarsky crean un thriller absorbente y adictivo, pero también para hablar de la sexualidad en nuestra sociedad, tanto desde un ángulo pícaro como más pedagógico, con personajes de psicología muy desarrollada, auténticos y veraces.',NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984267655-x7i0te.jpg','read',0,NULL,NULL,'2026-04-12 08:57:51','2026-04-12 12:09:10',147,16,NULL,'[{"name":"Matt Fraction","role":"Guion"},{"name":"Chip Zdarsky","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1189,'Sex Criminals #2','Sex Criminals',2,NULL,'978-8-416-88046-1',NULL,'Matt Fraction','Chip Zdarsky',NULL,NULL,'Astiberri',NULL,'2018-01-10',NULL,NULL,replace(replace('Suzie y Jon tienen un don: cuando alcanzan el orgasmo, el tiempo se congela y entran en otra dimensión donde nadie puede alcanzarlos. O eso creían, cuando aprovechaban para asaltar bancos. Ahora la Policía del Sexo acecha y todo empieza a complicarse... Sin embargo, se dan cuenta de que no son los únicos en tener ese poder sexual, y van a empezar a aliarse con otras personas de la dimensión orgásmica para enfrentarse a sus perseguidores.\r\nEn el segundo volumen de Sex Criminals, los elementos de thriller cobran un peso creciente, sin dejar de lado el humor picante y gamberro de Fraction y Zdarsky, así como reflexiones más profundas sobre la vida en pareja y la sexualidad. Sex Criminals recibió los premios Eisner y Harvey a la mejor serie de cómic en 2014 y fue elegida como el mejor cómic del año por Times Magazine.','\r',char(13)),'\n',char(10)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984276668-o507sb.jpg','read',0,NULL,NULL,'2026-04-12 08:57:57','2026-04-12 12:09:10',147,16,'Cartoné 136 pp','[{"name":"Matt Fraction","role":"Guion"},{"name":"Chip Zdarsky","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1190,'Sex Criminals #3','Sex Criminals',3,NULL,'978-8-416-88058-4',NULL,'Matt Fraction','Chip Zdarsky',NULL,NULL,'Astiberri',NULL,'2018-07-03',NULL,NULL,'Suzie y Jon han robado los archivos de la Policía del Sexo y, junto con Ana, la profesora que también tiene el poder de entrar en otra dimensión cuando llega al orgasmo, rebuscan entre la documentación y dan con un tal Douglas, que debería tener la misma habilidad que ellos. Pero mientras Suzie y Jon salen en su busca hacia Miami, la Policía del Sexo sigue investigando y está dispuesta a todo para dar con Jon... En este tercer volumen de Sex Criminals, la aventura del trío formado por Suzie, Jon y Ana se hace cada vez más trepidante; en él Matt Fraction aprovecha para ahondar en cuestiones que son más tabú o polémicas, como la dominación del binarismo de género, el desconocimiento de la asexualidad o la percepción histórica del clítoris. El guionista afirma: Hay algo intrínsecamente hipócrita en la sociedad norteamericana respecto al sexo. Por un lado les pedimos a las presentadoras de televisión que lleven minifalda y taconazo.Y por otra parte hay ocasiones en las que se prohíbe la aparición de personajes homosexuales en comedias televisivas. Hay multitud de casos de grabaciones filtradas de famosos de contenido sexual, y todo eso ocurre en una sociedad en la que no puedes dar clases sobre sexualidad o control de la natalidad en la escuela primaria',NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984278582-xk9f33.jpg','read',0,NULL,NULL,'2026-04-12 08:57:59','2026-04-12 12:09:10',147,16,'Cartoné 136 pp','[{"name":"Matt Fraction","role":"Guion"},{"name":"Chip Zdarsky","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1191,'Sex Criminals #4','Sex Criminals',4,NULL,'978-8-416-88096-6',NULL,'Matt Fraction','Chip Zdarsky',NULL,NULL,'Astiberri',NULL,'2019-01-31',NULL,NULL,replace(replace('Ahora que Suzie y Jon no están solos en su cruzada contra la Policía del Sexo parece un buen momento para hacer planes juntos. Pero comportarse como una pareja normal cuando detienes el tiempo cada vez que alcanzas un orgasmo y cuentas con un pasado como ladrón de bancos no es tan sencillo.\r\nEn este cuarto volumen de Sex Criminals, Matt Fraction profundiza en las inseguridades de Jon, que chocan frontalmente con las aspiraciones laborales de Suzie. Mientras la relación de los protagonistas se mueve en las farragosas arenas de la normalidad y la sombra de la incertidumbre se cierne sobre ellos, la doctora Kincaid se ve obligada a enfrentarse a su pasado. Y aunque conoceremos a un nuevo personaje con la capacidad de parar el tiempo, si hay alguien que destaca por encima de todos en esta nueva entrega es Myrtle Spurge, también conocida como Carakegel, cabecilla de la Policía del Sexo. Por fin sabremos qué le impulsa a comportarse así, cuál es su modus operandi y, sobre todo, nos plantaremos ante el dilema de si es ella la verdadera villana o no.\r\nSex Criminals recibió los premios Eisner y Harvey a la mejor serie de cómic en 2014 y fue elegida como el mejor cómic del año por Times Magazine. Matt Fraction trabaja actualmente en la adaptación del cómic para una serie de televisión.','\r',char(13)),'\n',char(10)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984285933-7eidem.jpg','read',0,NULL,NULL,'2026-04-12 08:58:06','2026-04-12 12:09:10',147,16,'Cartoné 136 pp','[{"name":"Matt Fraction","role":"Guion"},{"name":"Chip Zdarsky","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1192,'Sex Criminals #5','Sex Criminals',5,NULL,'978-8-417-57570-0',NULL,'Matt Fraction','Chip Zdarsky',NULL,NULL,'Astiberri',NULL,'2020-05-21',NULL,NULL,'Tras su ruptura, Suzie ha vuelto a casa con su madre, quien últimamente folla más que ella, y Jon comparte piso con su nueva “amiga”. Sin embargo, en una ciudad pequeña es inevitable volver a encontrarse. Y más aún cuando cada vez que alcanzas el orgasmo detienes el tiempo. Todo se vuelve más peligroso y complicado. Pero está bien. Todo bien, ¿no?',NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984288592-qq45o4.jpg','read',0,NULL,NULL,'2026-04-12 08:58:09','2026-04-12 12:08:31',147,16,'Cartoné 136 pp','[{"name":"Matt Fraction","role":"Guion"},{"name":"Chip Zdarsky","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1193,'Sex Criminals #6','Sex Criminals',6,NULL,'978-8-418-21585-8',NULL,'Matt Fraction','Chip Zdarsky',NULL,NULL,'Astiberri',NULL,'2021-09-16',NULL,NULL,replace(replace('P.V.P.: 18,00€ II 136 pp.\r\nSuze y Jon volvían a estar juntos. Eran felices, lo habían superado. Para ellos habían acabado el crimen, los primeros días de su relación, su extraño truco de congelar el tiempo y su lucha con BankCorp. Sin embargo, el millonario sociópata que dirige BankCorp no ha terminado con ellos. Suze, Jon y su alegre banda de marginados, dominadoras e inadaptados tienen que terminar la batalla con BankCorp, pero... ¿se puede destruir un banco? Se puede robar una sucursal o quemar un cajero, pero acabar con una corporación es lo más parecido a intentar luchar contra una idea. Así que solo queda arruinar la vida de su creador, la vida de Badal.','\r',char(13)),'\n',char(10)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984291648-bfkqgf.jpg','read',0,NULL,NULL,'2026-04-12 08:58:12','2026-04-12 12:08:31',147,16,'Cartoné 136 pp','[{"name":"Matt Fraction","role":"Guion"},{"name":"Chip Zdarsky","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1194,'Monster #1','Monster',1,NULL,'978-8-467-47661-3',NULL,'Naoki Urasawa','Takashi Nagasaki',NULL,NULL,'Planeta Cómic',NULL,'2009-05-01',NULL,NULL,'Todo el mundo siente desasosiego en su vida diaria. Ni siquiera el prometedor Dr. Kenzo Tenma es una excepción. Pero, ¿cómo podía saber él que el desempeño de su papel como médico para salvar vidas daría lugar al nacimiento de una criatura increíble? En Alemania, un país confundido desde su unificación, han muerto asesinadas varias parejas de mediana edad sin hijos. ¡El asesino en serie era Johan! ¿Por qué atacó a esos matrimonios? Kenzo Tenma se embarca en un viaje para encontrar a la hermana gemela de Johan, que puede tener alguna pista sobre el secreto del «monstruo».',NULL,NULL,480,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984311548-lo2196.jpg','read',0,NULL,NULL,'2026-04-12 08:58:34','2026-04-12 12:08:31',148,16.95,'Rústica','[{"name":"Naoki Urasawa","role":""},{"name":"Takashi Nagasaki","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1195,'Monster #2','Monster',2,NULL,'978-8-467-47662-0',NULL,'Naoki Urasawa','Takashi Nagasaki',NULL,NULL,'Planeta Cómic',NULL,'2009-06-01',NULL,NULL,'Tenma, que cayó en la trampa preparada por Johan, es ahora un supuesto asesino en serie buscado por la policía. Tras eludir por los pelos el cerco policial, persigue a Johan para evitar otro asesinato y demostrar su inocencia. Cavando en su pasado, se acerca cada vez más al monstruo. Nina ha sido capturada por un grupo neonazi. Mientras, Tenma la busca, pues es la única persona que puede decirle quién es Johan, y al hacerlo descubre un dato terrorífico. Los ultraderechistas conspiran para convertir a Johan en el nuevo Hitler.',NULL,NULL,480,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984320120-kdy3du.jpg','read',0,NULL,NULL,'2026-04-12 08:58:40','2026-04-12 12:08:31',148,NULL,'Rústica','[{"name":"Naoki Urasawa","role":""},{"name":"Takashi Nagasaki","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1196,'Monster #3','Monster',3,NULL,'978-8-467-47663-7',NULL,'Naoki Urasawa','Takashi Nagasaki',NULL,NULL,'Planeta Cómic',NULL,'2009-08-01',NULL,NULL,replace(replace('Johan tiene doble personalidad? ¿Es una especie de Jekyll y Hyde? Tenma recurre al Dr. Gillen, toda una autoridad en psicología criminal, para que psicoanalice a Johan. Sin embargo, el Dr. Gillen concluye en secreto que es Tenma y no Johan quien ha cometido los crímenes, e intenta tenderle una trampa para realizar unos experimentos con él.\r\n¡Ahora Tenma está verdaderamente acorralado! Karl, un estudiante de la Universidad de Múnich, visita cada semana a un multimillonario ciego para leerle libros y así poder pagarse sus estudios. Un día, conoce a un joven que hacía su mismo trabajo en casa del multimillonario. Su nombre… ¡Johan! Desde ese momento, a Karl le empiezan a suceder cosas extrañas y… ¿Quién es ese joven llamado Johan? ¿Es el Johan que conocemos?','\r',char(13)),'\n',char(10)),NULL,NULL,480,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984322858-lofgbh.jpg','read',0,NULL,NULL,'2026-04-12 08:58:43','2026-04-12 12:08:31',148,NULL,'Rústica','[{"name":"Naoki Urasawa","role":""},{"name":"Takashi Nagasaki","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1197,'Monster #4','Monster',4,NULL,'978-8-467-47664-4',NULL,'Naoki Urasawa','Takashi Nagasaki',NULL,NULL,'Planeta Cómic',NULL,'2009-10-01',NULL,NULL,'Johan se ha ganado la confianza de Schuwald, la persona más influyente la región de Baviera. Ahora es su mano derecha. ¿Pretende aparecer en el mundo económico germano como una joven promesa? Mientras, Richard, un detective privado, recibe un encargo de Schuwald, y mientras investiga los extraños acontecimientos alrededor del mismo, percibe algo enorme y malvado tras ellos. Entonces, empieza a luchar contra alguien tan espantoso como un monstruo. Al saber que Tenma quiere quitarle la vida, Johan se dedica a llevar una vida tranquila. Sin embargo, de pronto estalla a llorar y pierde el sentido. ¿Qué diablos es ese libro escrito en checo?',NULL,NULL,480,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984325251-x00ak9.jpg','read',0,NULL,NULL,'2026-04-12 08:58:45','2026-04-12 12:08:31',148,NULL,'Rústica','[{"name":"Naoki Urasawa","role":""},{"name":"Takashi Nagasaki","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1198,'Monster #5','Monster',5,NULL,'978-8-467-47665-1',NULL,'Naoki Urasawa','Takashi Nagasaki',NULL,NULL,'Planeta Cómic',NULL,'2009-12-01',NULL,NULL,'Tenma intenta colarse en Chequia para buscar a la madre de Johan. Un policía fronterizo le descubre, pero logra escapar con la ayuda de Grimmer, un periodista autónomo. Los dos hombres parten sin preguntarse uno a otro qué les ha llevado hasta Chequia. De hecho, Grimmer también está muy interesado en el kinderheim 511 de la Alemania del Este. Ahora la historia pasa a tener lugar en Praga.',NULL,NULL,480,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984327261-f3ukjy.jpg','read',0,NULL,NULL,'2026-04-12 08:58:48','2026-04-12 12:08:25',148,NULL,'Rústica','[{"name":"Naoki Urasawa","role":""},{"name":"Takashi Nagasaki","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1199,'Monster #6','Monster',6,NULL,'978-8-467-47666-8',NULL,'Naoki Urasawa','Takashi Nagasaki',NULL,NULL,'Planeta Cómic',NULL,'2010-02-01',NULL,NULL,replace(replace('Mientras, Suk, un joven detective de la policía de Praga, se enamora de una chica guapa que conoció en un bar y cuyo nombre es Anna. Cuando Tenma y Suk se encuentran, les espera un nuevo terror.\r\nAhora, el inspector Lunge está convencido de la participación de Johan en esos asesinatos en serie, y acude a Praga para descubrir quién es Johan en realidad. Ahí, se entera de que El monstruo sin nombre, el extraño cuento que tanto afectó a Johan durante su niñez, fue escrito por un agente de la policía secreta checoslovaca. Lunge consigue localizar la mansión de la rosas rojas, donde se escribió dicho libro. Ahí, en una pared enyesada, encuentra una antigua puerta. Y de ella puede surgir un auténtico horror.','\r',char(13)),'\n',char(10)),NULL,NULL,480,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984329771-5s38sw.jpg','read',0,NULL,NULL,'2026-04-12 08:58:50','2026-04-12 12:08:25',148,NULL,'Rústica','[{"name":"Naoki Urasawa","role":""},{"name":"Takashi Nagasaki","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1200,'Monster #7','Monster',7,NULL,'978-8-467-47667-5',NULL,'Naoki Urasawa','Takashi Nagasaki',NULL,NULL,'Planeta Cómic',NULL,'2010-04-01',NULL,NULL,replace(replace('Es Tenma quien ha destruido mi vida. . . &quot; Eva tiene un odio inconmensurable hacia Tenma. Pero es la única persona que podría testificar para demostrar su inocencia. Se niega a hacerlo, pero luego decide ayudarle tras aceptar recordar lo que vio. ¡EVA VIO A JOHAN! Mientras, la &quot;mano malvada&quot; de Robert, que quiere matar a Eva, se va acercando lentamente a ella. . . La clave para resolver el misterio está en la mansión de las rosas rojas.\r\nTenma, Nina y Johan se dirigen por separado hacia ese lugar. ¿Qué está pasando ahí? ¿Y por qué motivo? ¿Quién es en realidad Franz Bonaparta? ¿Se revelará alguna vez el secreto del nacimiento del monstruo?','\r',char(13)),'\n',char(10)),NULL,NULL,480,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984332576-kjpt9g.jpg','read',0,NULL,NULL,'2026-04-12 08:58:53','2026-04-12 12:08:25',148,NULL,'Rústica','[{"name":"Naoki Urasawa","role":""},{"name":"Takashi Nagasaki","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1201,'Monster #8','Monster',8,NULL,'978-8-467-47668-2',NULL,'Naoki Urasawa','Takashi Nagasaki',NULL,NULL,'Planeta Cómic',NULL,'2010-06-01',NULL,NULL,'La clave del nacimiento de este',NULL,NULL,480,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984334971-4ev45q.jpg','read',0,NULL,NULL,'2026-04-12 08:58:56','2026-04-12 12:08:25',148,NULL,'Rústica','[{"name":"Naoki Urasawa","role":""},{"name":"Takashi Nagasaki","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1202,'Monster #9','Monster',9,NULL,'978-8-467-49181-4',NULL,'Naoki Urasawa','Takashi Nagasaki',NULL,NULL,'Planeta Cómic',NULL,'2010-08-01',NULL,NULL,'Érase una vez un pueblecito en un pequeño valle. La gente vivía en paz. Un monstruo disfrazado vivía entre ellos. Cortó los lazos con la maldad y empezó a ayudar a la gente del pueblo. Pero, un día, llegaron unos mensajeros demoníacos. El pueblo quedó rodeado de un aire viciado y los aldeanos empezaron a matarse unos a otros. El propósito de esos mensajeros demoníacos era capturar al monstruo.',NULL,NULL,480,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984337564-eha5co.jpg','read',0,NULL,NULL,'2026-04-12 08:58:58','2026-04-12 12:08:25',148,NULL,'Rústica','[{"name":"Naoki Urasawa","role":""},{"name":"Takashi Nagasaki","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1203,'Historias cortas de Naoki Urasawa','Historias cortas de Naoki Urasawa',NULL,NULL,'978-8-468-40236-9',NULL,'Naoki Urasawa','Naoki Urasawa',NULL,NULL,'Planeta Cómic',NULL,'2011-04-05',NULL,NULL,'La antología que recopila varios relatos cortos de Naoki Urasawa, uno de los maestros del manga seinen (sobre todo thriller). Es el creador de Monster, Happy, Master Keaton, Pluto y 20th Century Boys, entre otras obras..',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984352115-iec9bb.jpg','unread',0,NULL,NULL,'2026-04-12 08:59:15','2026-04-12 08:59:15',NULL,22,'cartone','[{"name":"Naoki Urasawa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1204,'Planetes - Integral','Planetes - Integral',NULL,NULL,'978-8-413-34622-9',NULL,'Makoto Yukimura','Makoto Yukimura',NULL,NULL,'Panini Comics España',NULL,'2020-10-29',NULL,NULL,'¡El integral del mítico manga de Makoto Yukimura! En un futuro no muy lejano, la humanidad saldrá de su cuna, el planeta Tierra, y empezará a conquistar el espacio. Esta es la historia de Hachimaki, Yuri y Fee, recuperadores de deshechos espaciales que trabajan en la órbita terrestre para limpiarla de basura, mientras la humanidad, ya aposentada en la Luna y Marte, prepara su gran incursión hacia el sistema joviano.',NULL,NULL,1032,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984386990-h3cc6l.jpg','unread',0,NULL,NULL,'2026-04-12 08:59:48','2026-04-12 08:59:48',NULL,45,'Rústica','[{"name":"Makoto Yukimura","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1205,'Capitán Harlock','Capitán Harlock',NULL,NULL,'978-8-467-92447-3',NULL,'Leiji Matsumoto','Leiji Matsumoto',NULL,NULL,'Norma Editorial',NULL,'2016-09-30',NULL,NULL,'EL HÉROE MÁS CARISMÁTICO DEL MANGA REGRESA EN ESTA NUEVA EDICIÓN, QUE RECOPILA TODA LA SERIE ORIGINAL Para muchos, cuando los mares de la Tierra se extinguieron la humanidad estaba acabada. Sin embargo, unos pocos creyeron con inquebrantable fe en un nuevo y brillante futuro para los hombres... Fueron ellos quienes partieron entonces hacia ese nuevo mar infinito: el espacio.',NULL,NULL,1088,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984427652-kf3u7b.jpg','unread',0,NULL,NULL,'2026-04-12 09:00:28','2026-04-12 09:00:28',NULL,39,NULL,'[{"name":"Leiji Matsumoto","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1206,'Record of Lodoss War: La Dama de Faris','Record of Lodoss War: La Dama de Faris',NULL,NULL,NULL,NULL,'Ryo Mizuno','Akihiro Yamada',NULL,NULL,NULL,NULL,'2024-05-12',NULL,NULL,'Planeta Cómic. Edición integral, 2 tomos y un libro de ilustraciones en un cofre.',NULL,NULL,592,NULL,'https://inventario-api.josepec.workers.dev/covers/1775984462777-9lwl26.jpg','read',0,NULL,NULL,'2026-04-12 09:01:04','2026-04-12 12:08:25',149,NULL,'Rústica','[{"name":"Ryo Mizuno","role":"Guion"},{"name":"Akihiro Yamada","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1207,'Dragon Quest: The Adventure of Dai #1','Dragon Quest: The Adventure of Dai',1,NULL,'978-8-491-74706-2',NULL,'Riku Sanjo','Koji Inada',NULL,NULL,'Planeta Cómic',NULL,'2022-11-23',NULL,NULL,'La Isla Dermlin es un islote solitario de los mares del Sur en el que los monstruos viven en paz y concordia. Y allí es también donde vive un muchacho que anhela convertirse en un héroe. ¡¡Su nombre es Dai!',NULL,NULL,336,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984524151-bjlo8o.jpg','unread',0,NULL,NULL,'2026-04-12 09:02:07','2026-04-12 09:02:07',150,14.95,'Rústica','[{"name":"Riku Sanjo","role":"Guion"},{"name":"Koji Inada","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1208,'Dragon Quest: The Adventure of Dai #2','Dragon Quest: The Adventure of Dai',2,NULL,'978-8-491-74707-9',NULL,'Riku Sanjo','Koji Inada',NULL,NULL,'Planeta Cómic',NULL,'2023-02-22',NULL,NULL,'¡¡Persiguiendo la última voluntad de Aván, Dai y Popp comienzan un viaje repleto de aventuras!! Pero en su viaje hacia el reino de Romos, acaban perdidos en el bosque oscuro… donde son rescatados por Maam, una chica que dispara hechizos a través de una misteriosa pistola. Mientras tanto, y tras haber recibido órdenes de Hadler, las malvadas garras de Crocodín, el Rey de las Bestias, les acechan.',NULL,NULL,336,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984531616-ztp3rr.jpg','unread',0,NULL,NULL,'2026-04-12 09:02:12','2026-04-12 09:02:12',150,NULL,'Rústica','[{"name":"Riku Sanjo","role":"Guion"},{"name":"Koji Inada","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1209,'Dragon Quest: The Adventure of Dai #3','Dragon Quest: The Adventure of Dai',3,NULL,'978-8-491-74708-6',NULL,'Riku Sanjo','Koji Inada',NULL,NULL,'Planeta Cómic',NULL,'2023-04-26',NULL,NULL,'Maam se ha unido a sus compañeros, y todos juntos se dirigen hacia Papunica, el lugar donde está Liona… Sin embargo, cuando logran desembarcar, quien da la bienvenida a Dai y los demás es la Legión Inmortal. ¡¡Y además, sale a la luz un hecho aterrador!! Hyunckel, el comandante que lidera a los monstruos de la Legión Inmortal… ¡¡fue en el pasado un discípulo de Aván!!',NULL,NULL,336,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984533892-iyc8ym.jpg','unread',0,NULL,NULL,'2026-04-12 09:02:15','2026-04-12 09:02:15',150,NULL,'Rústica','[{"name":"Riku Sanjo","role":"Guion"},{"name":"Koji Inada","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1210,'Dragon Quest: The Adventure of Dai #4','Dragon Quest: The Adventure of Dai',4,NULL,'978-8-491-74709-3',NULL,'Riku Sanjo','Koji Inada',NULL,NULL,'Planeta Cómic',NULL,'2023-06-14',NULL,NULL,replace(replace('El Reino de Papunica ha quedado completamente devastado por culpa del ataque del Ejército Oscuro. La Princesa Liona y sus compañeros, que escaparon del peligro, se encuentran ocultos, a la espera de una oportunidad para contraatacar cuando, de repente, ¡¡Flazzard, el general pirohielo, hace su aparición llevando a cabo un violento ataque!!\r\n¡Dai se dirige hacia el lugar donde se encuentra una Princesa Liona que está viviendo una desesperada situación de vida o muerte! ¿¡Logrará llegar a tiempo!?','\r',char(13)),'\n',char(10)),NULL,NULL,336,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984536454-lyqs0w.jpg','unread',0,NULL,NULL,'2026-04-12 09:02:17','2026-04-12 09:02:17',150,NULL,'Rústica','[{"name":"Riku Sanjo","role":"Guion"},{"name":"Koji Inada","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1211,'Dragon Quest: The Adventure of Dai #5','Dragon Quest: The Adventure of Dai',5,NULL,'978-8-491-74710-9',NULL,'Riku Sanjo','Koji Inada',NULL,NULL,'Planeta Cómic',NULL,'2023-09-13',NULL,NULL,'¡Junto con la ayuda de Crocodín y Hyunckel, Dai y sus compañeros, los discípulos de Aván, finalmente logran tener a Flazzard completamente rodeado! ¡¡Sin embargo, Flazzard, que no renuncia a la victoria, lanza un asombroso ataque a la desesperada que amenaza su vida!! Es entonces cuando, ahogado por la desesperación de no ver oportunidad alguna de victoria, las enseñanzas de Aván reviven en el interior de Dai…',NULL,NULL,336,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984538916-j7lv0b.jpg','unread',0,NULL,NULL,'2026-04-12 09:02:20','2026-04-12 09:02:20',150,NULL,'Rústica','[{"name":"Riku Sanjo","role":"Guion"},{"name":"Koji Inada","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1212,'¡Yawara! #1','¡Yawara!',1,NULL,'978-8-411-40910-0',NULL,'Naoki Urasawa','Naoki Urasawa',NULL,NULL,'Planeta Cómic',NULL,'2023-11-22',NULL,NULL,'Yawara Inokuma es una talentosa judoka que ha sido entrenada desde muy pequeña por su abuelo Jigorô, campeón mundial de judo. Su abuelo confía plenamente en sus capacidades y pretende convertirla en medalla de oro en los Juegos Olímpicos de Barcelona de 1992. Sin embargo, Yawara lo único que quiere es tener una vida normal y corriente como sus amigas, alejada de entrenos y competiciones… Todo cambia cuando la descubre un periodista llamado Matsuda y la presenta al mundo como la nueva promesa del judo en Japón.',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984555385-yzwl7b.jpg','read',0,NULL,NULL,'2026-04-12 09:02:38','2026-04-12 12:08:16',151,NULL,'rustica','[{"name":"Naoki Urasawa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1213,'¡Yawara! #2','¡Yawara!',2,NULL,'978-8-411-40915-5',NULL,'Naoki Urasawa','Naoki Urasawa',NULL,NULL,'Planeta Cómic',NULL,'2024-01-10',NULL,NULL,'Continúa la historia de Yawara Inokuma, una talentosa joven en el arte del judo, mientras lidia con las expectativas de los demás sobre sus hombros. En este volumen, Yawara participa en su primer combate de exhibición mientras se enfrenta a desafíos aún mayores en su búsqueda por la libertad y la realización personal. Además, su relación con su abuelo se profundiza y nuevos personajes se unen a la historia, aportando giros inesperados.',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984562750-8w8ez8.jpg','read',0,NULL,NULL,'2026-04-12 09:02:43','2026-04-12 12:08:16',151,NULL,'rustica','[{"name":"Naoki Urasawa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1214,'¡Yawara! #3','¡Yawara!',3,NULL,'978-8-411-61191-6',NULL,'Naoki Urasawa','Naoki Urasawa',NULL,NULL,'Planeta Cómic',NULL,'2024-05-15',NULL,NULL,'El primer torneo oficial de Yawara está a punto de empezar. Con los Juegos Olímpicos cada vez más cerca, el resultado podría tener repercusiones inesperadas. Mientras todos esperan ver a la joven estudiante de secundaria en acción, Yawara parece estar más preocupada por el torneo interescolar masculino de sus compañeros del club de judo. Mientras Yawara es objeto de todas las miradas, Sayaka y Yuki están decididas a vengarse y ser las primeras en derrotarla.',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984565234-vcjcpv.jpg','read',0,NULL,NULL,'2026-04-12 09:02:46','2026-04-12 12:08:16',151,NULL,'rustica','[{"name":"Naoki Urasawa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1215,'¡Yawara! #4','¡Yawara!',4,NULL,'978-8-411-61259-3',NULL,'Naoki Urasawa','Naoki Urasawa',NULL,NULL,'Planeta Cómic',NULL,'2024-07-10',NULL,NULL,'Yawara gana un combate tras otro mientras estudia para el examen de acceso a la universidad. ¿¡Podrá compaginar ambas actividades!?',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984567983-g6k4kr.jpg','read',0,NULL,NULL,'2026-04-12 09:02:49','2026-04-12 12:08:16',151,NULL,'rustica','[{"name":"Naoki Urasawa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1216,'¡Yawara! #5','¡Yawara!',5,NULL,'978-8-411-61354-5',NULL,'Naoki Urasawa','Naoki Urasawa',NULL,NULL,'Planeta Cómic',NULL,'2024-11-13',NULL,NULL,'¡Yawara Inokuma es una judoca muy mona y encantadora! Yawara entra en la universidad. ¡Al poco de empezar su nueva vida estudiantil, se hace amiga de una chica llamada Fujiko!',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984570630-fn6nsl.jpg','read',0,NULL,NULL,'2026-04-12 09:02:51','2026-04-12 12:08:16',151,NULL,'rustica','[{"name":"Naoki Urasawa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1217,'¡Yawara! #6','¡Yawara!',6,NULL,'978-8-411-61675-1',NULL,'Naoki Urasawa','Naoki Urasawa',NULL,NULL,'Planeta Cómic',NULL,'2025-01-15',NULL,NULL,replace('Desde muy pequeña, Yawara Inokuma fue entrenada por su abuelo Jigorô Inokuma, campeón de judo, quien ve en ella una futura estrella de la disciplina. Se ha anunciado que los Juegos Olímpicos de Barcelona darán por fin la bienvenida a la disciplina femenina a la competición. Jigorô, por tanto, sueña con convertir a su nieta en la primera campeona olímpica de judo femenino. Pero contrariamente a las expectativas de su abuelo, la joven solo sueña con la moda, el amor, los chicos...\rEn definitiva, solo aspira a una vida adolescente normal, lejos de los entrenamientos y las competiciones. ¡Pero eso sin contar su talento innato para el judo, que su entorno no le permitirá olvidar...!','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984573250-y1jl70.jpg','read',0,NULL,NULL,'2026-04-12 09:02:54','2026-04-12 12:08:16',151,NULL,'rustica','[{"name":"Naoki Urasawa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1218,'¡Yawara! #7','¡Yawara!',7,NULL,'978-8-411-61866-3',NULL,'Naoki Urasawa','Naoki Urasawa',NULL,NULL,'Planeta Cómic',NULL,'2025-05-28',NULL,NULL,'Yawara Inokuma es una talentosa judoka que ha sido entrenada desde muy pequeña por su abuelo Jigorô, campeón mundial de judo. Su abuelo confía plenamente en sus capacidades y se esfuerza diariamente para convertirla en medalla de oro en los Juegos Olímpicos de Seúl de 1988. ¡Después de su victoria, Yawara avanza a la final de judo de los Juegos Olímpicos! ¿¡Conseguirá la medalla de oro!?',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984576372-7ka615.jpg','read',0,NULL,NULL,'2026-04-12 09:02:57','2026-04-12 12:08:16',151,NULL,'rustica','[{"name":"Naoki Urasawa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1219,'¡Yawara! #8','¡Yawara!',8,NULL,'979-1-387-77986-3',NULL,'Naoki Urasawa','Naoki Urasawa',NULL,NULL,'Planeta Cómic',NULL,'2025-10-22',NULL,NULL,replace('¡Yawara quiere abandonar su carrera deportiva y Fujiko forma un club de judo para persuadirla!\rFujiko aprovecha el viaje de Yawara a Canadá para crear su propio equipo de judo. Pero, a pesar de su determinación, conseguir reclutar a cuatro judokas y formarlas en un deporte que ella desconoce resulta más difícil de lo previsto. Para llevar a cabo su misión, tendrá que recurrir a viejos conocidos. Decidida a dejar el judo, la voluntad de Yawara se verá duramente puesta a prueba, tanto por Fujiko como por Jody.','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984578935-bsrkay.jpg','read',0,NULL,NULL,'2026-04-12 09:03:00','2026-04-12 12:08:16',151,NULL,'rustica','[{"name":"Naoki Urasawa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1220,'¡Yawara! #9','¡Yawara!',9,NULL,'979-1-387-78165-1',NULL,'Naoki Urasawa','Naoki Urasawa',NULL,NULL,'Planeta Cómic',NULL,'2026-01-21',NULL,NULL,replace('¡El club de judo liderado por Yawara participa en una competición y Fujiko se convierte en la estrella del equipo!\rYawara Inokuma, una chica normal que sueña con un amor maravilloso, es en realidad una prodigiosa joven del judo entrenada por su abuelo Jigoro. ¿Acaso su destino será alcanzar la medalla de oro olímpica, el Premio Nacional de Honor y convertirse en una superestrella del deporte japonés?','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984581532-hlap8f.jpg','read',0,NULL,NULL,'2026-04-12 09:03:02','2026-04-12 12:08:16',151,NULL,'rustica','[{"name":"Naoki Urasawa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1221,'El caminante','El caminante',NULL,NULL,'978-1-908-00791-9',NULL,'Jiro Taniguchi','Jiro Taniguchi',NULL,NULL,'Ponent Mon',NULL,'2015-03-02',NULL,NULL,'Hoy en día, ¿quién se toma el tiempo de trepar a un árbol para recuperar un juguete extraviado? ¿De quedarse mirando volar a los pájaros, de saltar los charcos después de una lluvia? ¿O de bajar a la playa para devolver una concha? El Caminante nos invita a acompañarle en sus paseos, a menudo tranquilos y solitarios, y disfrutar de los placeres que procuran sus andanzas por su barrio.',NULL,NULL,232,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984608645-bj2n31.jpg','read',0,NULL,NULL,'2026-04-12 09:03:29','2026-04-12 12:08:16',NULL,24,'Rústica','[{"name":"Jiro Taniguchi","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1222,'El almanaque de mi padre','El almanaque de mi padre',NULL,NULL,'978-8-413-41493-5',NULL,'Jiro Taniguchi','Jiro Taniguchi',NULL,NULL,'Planeta Cómic',NULL,'2020-10-06',NULL,NULL,'Al morir su padre, al que hacía años que no veía, Youichi asiste a su funeral con cierta sensación de alejamiento emocional. Su padre es para él un virtual desconocido, por el que nunca ha sentido demasiado afecto y al que ha llegado a considerar como un ser mediocre y oscuro. A través de recuerdos borrosos, de comentarios de allegados de su padre y de fotografías, el protagonista irá recomponiendo una imagen más compleja de su padre a la vez que arrojando nueva luz sobre su relación con él y con su madre.',NULL,NULL,272,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984642619-7j3hn7.jpg','read',0,NULL,NULL,'2026-04-12 09:04:04','2026-04-12 12:08:16',NULL,16.95,'Rústica','[{"name":"Jiro Taniguchi","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1223,'Mermaid Saga #1','Mermaid Saga',1,NULL,'978-8-411-40288-0',NULL,'Rumiko Takahashi','Rumiko Takahashi',NULL,NULL,'Planeta Cómic',NULL,'2023-04-26',NULL,NULL,'Debido a que comió la carne de una sirena, Yuta se volvió inmortal. Durante siglos, ha estado cruzando Japón en busca de una de estas mujeres-pez que finalmente podrá permitirle envejecer. Pero estas hechizantes criaturas son tan bellas como peligrosas y es a través de la sangre y los sacrificios que él las encontrará...',NULL,NULL,264,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984659132-hlhqrr.jpg','unread',0,NULL,NULL,'2026-04-12 09:04:22','2026-04-12 09:04:22',152,12.95,'Rústica','[{"name":"Rumiko Takahashi","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1224,'Mermaid Saga #2','Mermaid Saga',2,NULL,'978-8-411-40289-7',NULL,'Rumiko Takahashi','Rumiko Takahashi',NULL,NULL,'Planeta Cómic',NULL,'2023-05-24',NULL,NULL,'Yûta consiguió la inmortalidad el día que comió carne de sirena, y ahora lleva ya 500 años viviendo. Deambula de un lado para otro con Mana, una jovencita con quien se cruzó en su viaje y que, al igual que él, obtuvo la vida eterna sin pretenderlo. En este tomo, el encuentro entre Yûta y otro inmortal desencadena una nueva tragedia...',NULL,NULL,264,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984666590-6i2gqt.jpg','unread',0,NULL,NULL,'2026-04-12 09:04:27','2026-04-12 09:04:27',152,12.95,'Rústica','[{"name":"Rumiko Takahashi","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1225,'Mermaid Saga #3','Mermaid Saga',3,NULL,'978-8-411-40290-3',NULL,'Rumiko Takahashi','Rumiko Takahashi',NULL,NULL,'Planeta Cómic',NULL,'2023-06-14',NULL,NULL,'Un día de hace cien años, en una imponente mansión, dos hermanos se suicidaron tomándose un misterioso veneno. ¡Pero resulta que ese veneno era nada menos que el que contiene la carne de sirena, capaz de conceder la inmortalidad solo a unos pocos! El hermano pequeño resucitó, pero parece que la pobre hermana mayor no corrió la misma suerte...¡Cuando el pasado de los hermanos sale a la luz, un horror indescriptible se cierne sobre la mansión!',NULL,NULL,264,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984669769-ai4i9a.jpg','unread',0,NULL,NULL,'2026-04-12 09:04:30','2026-04-12 09:04:30',152,12.95,'Rústica','[{"name":"Rumiko Takahashi","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1226,'F. Compo - Complete Edition #1','F. Compo - Complete Edition',1,NULL,'978-8-417-95778-0',NULL,'Hojo Tsukasa','Hojo Tsukasa',NULL,NULL,'Arechi Manga',NULL,'2021-06-10',NULL,NULL,replace(replace('Masahiko Yanagiba queda huérfano poco antes de empezar la universidad, por lo que su tío y su tía lo acogen en su hogar, lo que Masahiko acepta, pues en ello ve la posibilidad de disfrutar por fin de una vida familiar. Lo que no sabe es que los Wakanae esconden un secreto algo particular que pondrá su mundo patas arriba.\r\nF. Compo es, sin duda, una de las obras maestras de Tsukasa Hôjô, una comedia sobre el respeto a la diversidad, sobre el amor a la familia y la necesidad de encajar en un mundo distinto.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984717556-m31hfn.jpg','unread',0,NULL,NULL,'2026-04-12 09:05:20','2026-04-12 09:05:20',153,14.95,'rustica','[{"name":"Hojo Tsukasa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1227,'F. Compo - Complete Edition #2','F. Compo - Complete Edition',2,NULL,'978-8-417-95779-7',NULL,'Hojo Tsukasa','Hojo Tsukasa',NULL,NULL,'Arechi Manga',NULL,'2021-07-22',NULL,NULL,replace(replace('El encuentro con una antigua compañera de instituto pondrá en un brete a Masahiko, pues, aunque la chica afirma que siempre ha estado enamorada de él, también desea convertirse en la ayudante de dibujo del tío de Masahiko.\r\nPero ¿cómo reaccionará Shion al ver a su primo abrazando a otra mujer? F. Compo es, sin duda, una de las obras maestras de Tsukasa Hôjô, una comedia sobre el respeto a la diversidad, sobre el amor a la familia y la necesidad de encajar en un mundo distinto.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984772780-gwpoci.jpg','unread',0,NULL,NULL,'2026-04-12 09:06:13','2026-04-12 09:06:13',153,NULL,'rustica','[{"name":"Hojo Tsukasa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1228,'F. Compo - Complete Edition #3','F. Compo - Complete Edition',3,NULL,'978-8-417-95780-3',NULL,'Hojo Tsukasa','Hojo Tsukasa',NULL,NULL,'Arechi Manga',NULL,'2021-09-02',NULL,NULL,replace(replace('Una llamada de teléfono va a poner el mundo de Masahiko patas arriba… Alguien está preguntando por su hermana mayor. ¿Se refiere a Sora Wakanae, el tío de Masahiko? ¿Qué esconde el pasado de Sora?\r\nF. Compo es, sin duda, una de las obras maestras de Tsukasa Hôjô, una comedia sobre el respeto a la diversidad, sobre el amor a la familia y la necesidad de encajar en un mundo distinto.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984780067-2ae6qn.jpg','unread',0,NULL,NULL,'2026-04-12 09:06:21','2026-04-12 09:06:21',153,NULL,'rustica','[{"name":"Hojo Tsukasa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1229,'F. Compo - Complete Edition #4','F. Compo - Complete Edition',4,NULL,'978-8-417-95781-0',NULL,'Hojo Tsukasa','Hojo Tsukasa',NULL,NULL,'Arechi Manga',NULL,'2021-10-14',NULL,NULL,'Masahiko está pasando los mejores días de su vida en casa de los Wakanae, pero Yoko, su novia, no acaba de comprender el estilo de vida de esa familia y está dispuesta a lanzarle un ultimátum. Mientras, el pasado de la pareja Wakanae empieza a desvelarse...',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984782858-o8nu5k.jpg','unread',0,NULL,NULL,'2026-04-12 09:06:23','2026-04-12 09:06:23',153,NULL,'rustica','[{"name":"Hojo Tsukasa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1230,'F. Compo - Complete Edition #5','F. Compo - Complete Edition',5,NULL,'978-8-417-95782-7',NULL,'Hojo Tsukasa','Hojo Tsukasa',NULL,NULL,'Arechi Manga',NULL,'2021-11-18',NULL,NULL,'Las cosas se complican para la familia Wakanae. El padre de Sora acaba de enfrentar a la familia a un dilema terrible: para que la boda entre Yoriko y Kenji tenga lugar, Mashiko y Shion deben aceptar que el patriarca Kikuchi los adopte. ¿Cuál será su decisión? La obra maestra de Tsukasa Hojo sigue indagando en la aceptación de la diversidad como motor para encontrar la felicidad.',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984795435-fu312n.jpg','unread',0,NULL,NULL,'2026-04-12 09:06:36','2026-04-12 09:06:36',153,NULL,'rustica','[{"name":"Hojo Tsukasa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1231,'F. Compo - Complete Edition #6','F. Compo - Complete Edition',6,NULL,'978-8-417-95783-4',NULL,'Hojo Tsukasa','Hojo Tsukasa',NULL,NULL,'Arechi Manga',NULL,'2021-12-30',NULL,NULL,replace(replace('Kaoru, la hija del yakuza Tatsumi, se ha instalado en casa de los Wakanae. Y esto, claro está, no va a facilitarle para nada la vida a Masahiko, cuya relación con Yoko ya es bastante complicada…\r\nContinúa la divertidísima F. Compo, la serie que nos enseña a amar y comprender la diversidad como forma de conseguir la felicidad.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984798216-jyw62h.jpg','unread',0,NULL,NULL,'2026-04-12 09:06:39','2026-04-12 09:06:39',153,NULL,'rustica','[{"name":"Hojo Tsukasa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1232,'F. Compo - Complete Edition #7','F. Compo - Complete Edition',7,NULL,'978-8-418-77634-2',NULL,'Hojo Tsukasa','Hojo Tsukasa',NULL,NULL,'Arechi Manga',NULL,'2022-02-03',NULL,NULL,'El yakuza Tatsumi está dispuesto a encontrar una nueva madre para su hija, Kaoru, ya que cree que esa será la solución para devolverle toda la feminidad. ¿Qué tienen que ver Masahiko y los Wakanae en sus planes? F. Compo ya ha cruzado el ecuador de su historia, y todas las tramas argumentales empiezan a encontrar una resolución.',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984800763-qkqvxg.jpg','unread',0,NULL,NULL,'2026-04-12 09:06:41','2026-04-12 09:06:41',153,NULL,'rustica','[{"name":"Hojo Tsukasa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1233,'F. Compo - Complete Edition #8','F. Compo - Complete Edition',8,NULL,'978-8-418-77635-9',NULL,'Hojo Tsukasa','Hojo Tsukasa',NULL,NULL,'Arechi Manga',NULL,'2022-02-24',NULL,NULL,'Shion ha decidido ir a la misma universidad que Masahiko. Sería la oportunidad perfecta para que su primo acabe de acercarse a ella... pero Shion pretende asistir a la universidad como hombre, y el misterio acerca de su verdadera naturaleza se hace más profundo. Las tramas argumentales F. Compo poco a poco se van cerrando, llevando a los personajes a nuevas cotas de sensibilidad y ternura.',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984803165-jjwtyf.jpg','unread',0,NULL,NULL,'2026-04-12 09:06:43','2026-04-12 09:06:43',153,NULL,'rustica','[{"name":"Hojo Tsukasa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1234,'F. Compo - Complete Edition #9','F. Compo - Complete Edition',9,NULL,'978-8-418-77636-6',NULL,'Hojo Tsukasa','Hojo Tsukasa',NULL,NULL,'Arechi Manga',NULL,'2022-03-17',NULL,NULL,'Shion ha decidido ir a la misma universidad que Masahiko, pero como pretende asistir a la universidad como hombre, la decisión no acaba de complacer a su familia. ¿Por qué? ¿Qué antiguas heridas puede abrir esa decisión? Además, Shion se va de viaje de final de curso con sus amigas, y Masahiko debe acompañarlas... ¡aunque de incógnito',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984808418-zshpk8.jpg','unread',0,NULL,NULL,'2026-04-12 09:06:49','2026-04-12 09:06:49',153,NULL,'rustica','[{"name":"Hojo Tsukasa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1235,'F. Compo - Complete Edition #10','F. Compo - Complete Edition',10,NULL,'978-8-418-77684-7',NULL,'Hojo Tsukasa','Hojo Tsukasa',NULL,NULL,'Arechi Manga',NULL,'2022-04-28',NULL,NULL,'Un cómic de Hojo Tsukasa.Publicado por Arechi Manga',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984814152-emei9h.jpg','unread',0,NULL,NULL,'2026-04-12 09:06:55','2026-04-12 09:06:55',153,NULL,'rustica','[{"name":"Hojo Tsukasa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1236,'F. Compo - Complete Edition #11','F. Compo - Complete Edition',11,NULL,'978-8-418-77685-4',NULL,'Hojo Tsukasa','Hojo Tsukasa',NULL,NULL,'Arechi Manga',NULL,'2022-05-26',NULL,NULL,'Un cómic de Hojo Tsukasa.Publicado por Arechi Manga',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984818643-w34zfu.jpg','unread',0,NULL,NULL,'2026-04-12 09:06:59','2026-04-12 09:06:59',153,NULL,'rustica','[{"name":"Hojo Tsukasa","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1237,'Cages','Cages',NULL,NULL,'978-8-416-94514-6',NULL,'Dave McKean','Dave McKean',NULL,NULL,'ECC Ediciones',NULL,'2017-01-17',NULL,NULL,replace(replace('Tras ofrecer una sorprendente e irrepetible versión del Hombre Murciélago en Batman: Asilo Arkham, Dave McKean reflexionó sobre las creencias y la fantasía en la ambiciosa y personal Cages, multipremiada obra que recuperamos a través de una edición que conmemora su 25 aniversario, y que cuenta con una introducción a cargo del polifacético Terry Gilliam.\r\nSandman y sus proyectos derivados, Orquídea negra, Casos violentos, Asilo Arkham, Grandes Autores de Vertigo: Dave McKean, Hellblazer...Seguimos integrando en nuestro catálogo títulos firmados por uno de los artistas más influyentes en la historia moderna del noveno arte. Este mes ponemos al fin a vuestra disposición Cages, un monumental y largamente descatalogado trabajo en solitario, que fue galardonado con los premios Harvey, Pantera, Ignatz y Alph-Art.','\r',char(13)),'\n',char(10)),NULL,NULL,504,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984969432-yc4mzo.jpg','unread',0,NULL,NULL,'2026-04-12 09:09:32','2026-04-12 09:09:32',NULL,50,NULL,'[{"name":"Dave McKean","role":"Guion, Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1238,'Sabores únicos','Sabores únicos',NULL,NULL,'979-1-387-91881-1',NULL,'Ram V','Filipe Andrade',NULL,NULL,'Planeta Cómic',NULL,'2026-02-04',NULL,NULL,replace('¡Una obra maestra que aúna lo sobrenatural con la gastronomía india y con el implacable mundo de los chefs convertidos en famosos!\rDescubre el seductor relato de Rubin Baksh, un demoníaco ráksasa con el sueño mundano de ser el próximo Anthony Bourdain. Para conseguirlo, Rubin recluta a Mo, un cineasta en horas bajas que documentará la famosa gastronomía india y a las personas que están detrás de tan maravillosa comida. Sin embargo, Mo ignora que Rubin es más de lo que parece y que los mortales desempeñan un siniestro papel en la historia para el que no están preparados...\rDispón el paladar para el banquete que te ofrecen Ram V (Detective Comics, Blue in Green) y Filipe Andrade (Fantastic Four, Star), el equipo creativo de Las muchas muertes de Laila Starr, el cómic que estuvo nominado a los premios Eisner, Harvey y Ringo.','\r',char(13)),NULL,NULL,168,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775984991737-fmebqy.jpg','read',0,NULL,NULL,'2026-04-12 09:09:54','2026-04-12 12:08:16',NULL,20,NULL,'[{"name":"Ram V","role":""},{"name":"Filipe Andrade","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1239,'El País Libre: Un relato de la cruzada de los niños','El País Libre: Un relato de la cruzada de los niños',NULL,NULL,'978-8-416-58181-8',NULL,'Alisa Kwitney','Chris Bachalo',NULL,NULL,'ECC Ediciones',NULL,'2016-01-28',NULL,NULL,'EDICIÓN ORIGINAL: Free Country: A tale of the Children',NULL,NULL,208,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775985008427-qiptdy.jpg','unread',0,NULL,NULL,'2026-04-12 09:10:10','2026-04-12 09:10:10',NULL,20.5,NULL,'[{"name":"Alisa Kwitney","role":"Guion"},{"name":"Jamie Delano","role":"Guion"},{"name":"Neil Gaiman","role":"Guion"},{"name":"Toby Litt","role":"Guion"},{"name":"Chris Bachalo","role":"Dibujo"},{"name":"Peter Snejbjerg","role":"Dibujo"},{"name":"Peter Gross","role":"Dibujo"},{"name":"Mike Barreiro","role":"Tinta"},{"name":"Rachel Pollack","role":"Guion"},{"name":"Al Davison","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1240,'Step by Bloody Step','Step by Bloody Step',NULL,NULL,'978-8-411-12320-4',NULL,'Simon Spurrier','Matias Bergara',NULL,NULL,'Planeta Cómic',NULL,'2024-05-22',NULL,NULL,replace(replace('Una obra magna de fantasía\r\nHAY UNA NIÑA. No tiene recuerdos ni un nombre. Tan solo tiene un GUARDIÁN. Un gigante acorazado que la protege de depredadores y escollos. Juntos recorren un extraordinario mundo de fantasía. Si se apartan de la senda, el propio aire cobra vida, obligándoles a seguir adelante. ¿Por qué?\r\nLa niña no lo sabe, pero por delante esperan cosas peores que bestias y bandidos. La civilización, con sus tentaciones y traiciones, pondrá a prueba su vínculo hasta más allá de sus límites.\r\nSTEP BY BLOODY STEP es una obra magna de fantasía de los nominados a los premios Eisner responsables de Coda (sélection officielle Angouléme 2021): MATÍAS BERGARA (Hellblazer, THE SCUMBAG) y SI SPURRIER (X-Men Legacy, Hellblazer, The Spire).','\r',char(13)),'\n',char(10)),NULL,NULL,200,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775985041375-5h9h2w.jpg','read',0,NULL,NULL,'2026-04-12 09:10:44','2026-04-12 12:08:16',NULL,20,NULL,'[{"name":"Simon Spurrier","role":"Guion"},{"name":"Matias Bergara","role":"Dibujo, Tinta"},{"name":"Mat Lopes","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1241,'w0rldtr33 #1','w0rldtr33',1,NULL,'978-8-467-97884-1',NULL,'James Tynion IV','Fernando Blanco',NULL,NULL,'Norma Editorial',NULL,'2025-09-19',NULL,NULL,replace(replace('Contiene: W0rldtr33 1-5.\r\nJAMES TYNION IV, GANADOR 3 VECES DEL PREMIO EISNER AL MEJOR GUIONISTA, PRESENTA UN INQUIETANTE THRILLER DIBUJADO POR EL ARTISTA ESPAÑOL FERNANDO BLANCO.\r\nEn 1999, Gabriel y sus amigos descubrieron la Undernet, una arquitectura secreta de Internet. Dejaron constancia de sus exploraciones en un foro llamado W0RLDTR33. Y, entonces, perdieron el control. Alguien se coló en W0RLDTR33, alguien que recibía con los brazos abiertos el control violento que ejercía la Undernet sobre ellos. Pagando un precio muy alto, Gabriel y los demás pensaron que habían sellado para siempre la Undernet. Se equivocaban. Y, ahora, el mundo entero conocerá el significado de PH34R. Aquí empieza la nueva y gran épica de terror en la que el aclamado guionista James Tynion IV, el sobresaliente dibujante Fernando Blanco y la galardonada colorista Jordie Bellaire exploran la vanguardia de la atrocidad.','\r',char(13)),'\n',char(10)),NULL,NULL,168,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775985081096-il9gwg.jpg','unread',0,NULL,NULL,'2026-04-12 09:11:24','2026-04-12 09:11:24',154,24,'rustica','[{"name":"James Tynion IV","role":"Guion"},{"name":"Fernando Blanco","role":"Dibujo, Tinta"},{"name":"Jordie Bellaire","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1242,'w0rldtr33 #2','w0rldtr33',2,NULL,'978-8-467-97983-1',NULL,'James Tynion IV','Fernando Blanco',NULL,NULL,'Norma Editorial',NULL,'2025-11-21',NULL,NULL,replace(replace('Contiene: W0RLDTR33 6-11 \r\nJAMES TYNION IV, GANADOR 3 VECES DEL PREMIO EISNER, PRESENTA UN INQUIETANTE THRILLER DIBUJADO POR FERNANDO BLANCO Y EN ESTE VOLUMEN SUBE EL RITMO POR TODO LO ALTO CON REVELACIONES QUE DESCUBREN NUEVOS MISTERIOS SOBRE EL ORIGEN Y EL OBJETIVO DE LA UNDERNET.\r\nCon solo apretar un botón, Gabriel Winter cambió el mundo. Ahora que ya no está, lo único que les queda a los miembros originales de W0RLDTR33 es su testamento... y una carrera contrarreloj para encontrar a Ellison Lane, el hermano de una de las víctimas de la Undernet, que se ha escondido junto al resto de sus familiares supervivientes. En la otra punta del país, la agente especial Siobhan Silk se esfuerza en comprender cómo se ha desmoronado todo. Su compañero está muerto, su jefa se centra en las piezas equivocadas del rompecabezas, y una asesina despiadada sigue suelta, reclutando a otros para su causa enfermiza. Hay que detener a PH34R, pero... ¿podrá la agente Silk sobrevivir a la revancha?','\r',char(13)),'\n',char(10)),NULL,NULL,168,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775985093401-efnwhv.jpg','unread',0,NULL,NULL,'2026-04-12 09:11:34','2026-04-12 09:11:34',154,NULL,'tapa blanda','[{"name":"James Tynion IV","role":"Guion"},{"name":"Fernando Blanco","role":"Dibujo, Tinta"},{"name":"Jordie Bellaire","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1243,'w0rldtr33 #3','w0rldtr33',3,NULL,'978-8-467-98242-8',NULL,'James Tynion IV','Fernando Blanco',NULL,NULL,'Norma Editorial',NULL,'2026-03-20',NULL,NULL,replace(replace('Contiene w0rldtr33 12-16 \r\nJAMES TYNION IV, GANADOR 3 VECES DEL PREMIO EISNER, PRESENTA UN INQUIETANTE THRILLER DIBUJADO POR FERNANDO BLANCO Y EN ESTE VOLUMEN NOS REVELA LA HISTORIA DE PH34R.\r\nAntes de ser la asesina despiadada de la Undernet, PH34R era una niña llamada Sammi que solo quería saber qué hacían todo el día en internet su hermano mayor y sus amigos hackers... Cincuenta años después, el planeta apenas es habitable. La Undernet ha ganado. Ellison Lane cree que al fin tiene todas las piezas para darle a la humanidad otra oportunidad de tener un futuro. Pero en su camino se interpone un ángel terrible... un ángel con tatuajes por todo el cuerpo y un rencor de décadas contra el grupo w0rldtr33.','\r',char(13)),'\n',char(10)),NULL,NULL,168,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775985095877-bm98gh.jpg','unread',0,NULL,NULL,'2026-04-12 09:11:36','2026-04-12 09:11:36',154,NULL,'Rústica','[{"name":"James Tynion IV","role":"Guion"},{"name":"Fernando Blanco","role":"Dibujo, Tinta"},{"name":"Jordie Bellaire","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1244,'DC Elseworlds #2','DC Elseworlds',2,NULL,'979-1-370-13299-6',NULL,'Andy Diggle','Leandro Fernández',NULL,NULL,'Panini Comics España',NULL,'2025-11-27',NULL,NULL,replace(replace('Contiene: Batman: Gotham by Gaslight - The Kryptonian Age 1-6 \r\nRegresa a la Gotham victoriana con un nuevo capítulo firmado por Andy Diggle (The Losers, Green Arrow: Año Uno) y Leandro Fernández (El Castigador). Después de que un misterioso meteorito se estrelle en los idílicos campos del centro de Estados Unidos, arranca una cadena de acontecimientos que repercutirá en la historia. ¿Cómo reaccionará Batman al nacimiento de superseres en pleno siglo XIX?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775985120092-eun5ed.jpg','unread',0,NULL,NULL,'2026-04-12 09:12:04','2026-04-12 09:12:04',155,27.5,NULL,'[{"name":"Andy Diggle","role":"Guion"},{"name":"Leandro Fernández","role":"Dibujo, Tinta"},{"name":"Matt Hollingsworth","role":"Color"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1245,'DC Elseworlds #1','DC Elseworlds',1,NULL,'979-1-370-13081-7',NULL,'Jay Kristoff','Tirso Cons',NULL,NULL,'Panini Comics España',NULL,'2025-07-24',NULL,NULL,replace(replace('Contiene: Dark Knights of Steel: Allwinter 1-6.\r\nLa saga de los Caballeros Oscuros de Acero continúa reimaginando a los héroes de DC en un reino de fantasía medieval, con una nueva aventura en un mundo nevado en el que la sangre se vuelve negra y el color no es sino un recuerdo lejano. El legendario asesino Deathstroke atraviesa este páramo congelado, matando por un puñado de monedas. El mortífero asesino se verá obligado a asumir el papel de guardián y luchar contra una gélida maldición, antes de que sea consumido por los pecados de su oscuro pasado.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775985134031-gfbk66.jpg','unread',0,NULL,NULL,'2026-04-12 09:12:15','2026-04-12 09:12:15',155,NULL,'Cartoné','[{"name":"Jay Kristoff","role":"Guion"},{"name":"Tirso Cons","role":"Dibujo, Tinta, Color"},{"name":"Tom Taylor","role":"Guion"},{"name":"Riccardo Federici","role":"Dibujo, Tinta"},{"name":"Arif Prianto","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1246,'DC Elseworlds #3','DC Elseworlds',3,NULL,'979-1-370-13446-4',NULL,'Tom Taylor','Yasmine Putri',NULL,NULL,'Panini Comics España',NULL,'2026-01-29',NULL,NULL,replace(replace('Contiene: Dark Knights of Steel 1-12 y Dark Knights of Steel: Tales from the Three Kingdoms.\r\n¡Los héroes de la Liga de la Justicia, en un escenario de fantasía medieval! El galardonado Tom Taylor se une a la artista emergente Yasmine Putri para crear un épico Elseworlds protagonizado por un cruzado oscuro y una guerrera amazona, los héroes de un mundo lejano de acero y magia. La paz entre sus respectivos reinos siempre ha sido frágil, pero el asesinato de un miembro de la familia real de El, para prevenir que se cumpla una oscura profecía, deja la guerra como única respuesta posible. ¡Espadas, magia y sangre se desatan en esta guerra entre reinos!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775985136706-56ca3h.jpg','unread',0,NULL,NULL,'2026-04-12 09:12:17','2026-04-12 09:12:17',155,NULL,'Cartoné','[{"name":"Tom Taylor","role":"Guion"},{"name":"Jay Kristoff","role":"Guion"},{"name":"C.S. Pacat","role":"Guion"},{"name":"Yasmine Putri","role":"Dibujo, Tinta, Color"},{"name":"Caspar Wijngaard","role":"Dibujo, Tinta, Color"},{"name":"Jen Barel Bengal","role":"Dibujo, Tinta, Color"},{"name":"Nathan Gooden","role":"Dibujo, Tinta"},{"name":"Michele Bandini","role":"Dibujo"},{"name":"Bengal","role":"Dibujo, Tinta"},{"name":"Arif Prianto","role":"Color"},{"name":"Antonio Fabela","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1247,'Godzilla: La Guerra del Medio Siglo','Godzilla: La Guerra del Medio Siglo',NULL,NULL,'978-8-418-95566-2',NULL,'James Stokoe','James Stokoe',NULL,NULL,'Moztros',NULL,'2023-04-20',NULL,NULL,replace(replace('Contiene Godzilla, Half–Century War 1 a 5 publicados en USA por IDW Publishing.\r\nGodzilla: La Guerra del Medio siglo, es el viaje de un hombre desde el momento en que comienza el reinado de destrucción de Godzilla y van sucediéndose, una tras otras, las batallas a lo largo de su vida. Es el año 1954 y el teniente Ota Murakami se encuentra, por primera vez, cara a cara con Godzilla mientrAs este se acerca a las costas de Japón. Junto con su amigo Kentaro, y ya sin muchas opciones, Ota hace una apuesta desesperada para salvar vidas durante una cruel batalla en el corazón de Tokio. ¡Es el comienzo de una obsesión contra el Rey de los Monstruos que durará cincuenta años! James Stokoe nos presenta una novela gráfica emocionante en donde se adentrará con una nueva mirada al reinado de destrucción de Godzilla durante la primera mitad de un siglo en una guerra que durará toda una vida.','\r',char(13)),'\n',char(10)),NULL,NULL,128,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775985164587-vmwqqk.jpg','read',0,NULL,NULL,'2026-04-12 09:12:45','2026-04-12 12:06:46',NULL,19.9,'Rústica','[{"name":"James Stokoe","role":"Guion, Dibujo, Tinta, Color"},{"name":"Kyle Higgins","role":""},{"name":"Hendry Prasetya","role":"Dibujo"},{"name":"Jamal Campbell","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1248,'Transformers. Edición Z Deluxe #1','Transformers. Edición Z Deluxe',1,NULL,'979-1-387-95304-1',NULL,'Daniel Warren Johnson','Daniel Warren Johnson',NULL,NULL,'Moztros',NULL,'2025-11-13',NULL,NULL,replace(replace('Contenido: Transformers núms. 1–12 USA\r\n¡LA EDICIÓN DEFINITIVA DE LA SERIE DEL MOMENTO!\r\nOptimus Prime debía conducir a los Autobots hacia la victoria. Pero, en vez de eso, llevó a la Tierra la guerra entre los Autobots y sus temibles enemigos, los Decepticons. Mientras estas fuerzas titánicas retoman su contienda ancestral en un nuevo campo de batalla, si hay algo que queda claro es que el planeta nunca será el mismo. Surgen nuevas alianzas. Las líneas del campo de batalla se redibujan. ¡Y la única esperanza para la supervivencia de la humanidad es Optimus Prime!\r\nDANIEL WARREN JOHNSON (Do a Powerbomb!, Wonder Woman: Tierra muerta) y el showrunner ROBERT KIRKMAN (The Walking Dead, Invencible) reimaginan a los robots más famosos de Hasbro para nuevas generaciones. Una etapa para el recuerdo, galardonada con los Premios Eisner 2024 a la mejor serie regular y al mejor autor completo.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775985183445-jas96a.jpg','unread',0,NULL,NULL,'2026-04-12 09:13:06','2026-04-12 09:13:06',156,NULL,'bolsillo','[{"name":"Daniel Warren Johnson","role":"Guion, Dibujo, Tinta"},{"name":"Mike Spicer","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1249,'Caballero Luna de Jeff Lemire','Caballero Luna de Jeff Lemire',NULL,NULL,'978-8-410-49720-7',NULL,'Jeff Lemire','Greg Smallwood',NULL,NULL,'Panini Comics España',NULL,'2025-05-29',NULL,NULL,replace(replace('Contiene: Moon Knight 1-14.\r\nMarc Spector lleva años luchando contra el crimen... ¿seguro? Después de despertarse en un manicomio, toda su vida es puesta en cuestión. Algo va mal, pero quizás sea el propio Caballero Luna. Jeff Lemire y la nueva estrella Greg Smallwood van a poner en duda todo lo que sabes sobre este héroe, en una etapa que ha alcanzado la categoría de mítica e inspiró en gran medida la teleserie de Disney Plus. Por Jeff Lemire y Greg Smallwood con Francesco Francavilla, James Stokoe y Wilfredo Torres','\r',char(13)),'\n',char(10)),NULL,NULL,320,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775985203913-l0pb1o.jpg','unread',0,NULL,NULL,'2026-04-12 09:13:26','2026-04-12 09:13:26',NULL,1.25,NULL,'[{"name":"Jeff Lemire","role":"Guion"},{"name":"Greg Smallwood","role":"Dibujo, Tinta"},{"name":"Francesco Francavilla","role":"Dibujo, Tinta"},{"name":"James Stokoe","role":"Dibujo, Tinta"},{"name":"Wilfredo Torres","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1250,'Zatanna: Abajo la sala','Zatanna: Abajo la sala',NULL,NULL,'978-8-410-51960-2',NULL,'Mariko Tamaki','Javier Rodríguez',NULL,NULL,'Panini Comics España',NULL,'2025-04-03',NULL,NULL,replace(replace('Contiene: Zatanna: Bring Down the House 1-5.\r\n¡Una historia de Zatanna como ninguna otra, a cargo de Mariko Tamaki (Harley Quinn: Cristales rotos) y el sensacional artista español Javier Rodríguez! Después de que un error fatal la dejase aterrorizada de sus propias habilidades, Zatanna ahora reside en Las Vegas, donde actúa en el casino más cutre con los truquillos más baratos. No es que sea glamuroso, ni heroico, pero ella lo prefiere a volver a tratar con magia real… Hasta que un misterioso desconocido sumerja su mundo en caos, abriendo viejas heridas y grietas interdimensionales.','\r',char(13)),'\n',char(10)),NULL,NULL,184,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775985216956-gvs76m.jpg','read',0,NULL,NULL,'2026-04-12 09:13:38','2026-04-12 12:06:46',NULL,26,'tapa dura','[{"name":"Mariko Tamaki","role":"Guion"},{"name":"Javier Rodríguez","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1251,'Naruto Jump Remix #1','Naruto Jump Remix',1,NULL,'978-8-411-61144-2',NULL,'Masashi Kishimoto','Masashi Kishimoto',NULL,NULL,'Planeta Cómic',NULL,'2024-04-17',NULL,NULL,replace(replace('Contiene Naruto #01-33\r\nEn la Villa Oculta de la Hoja, un chaval de lo más problemático que estudia en la escuela de ninjas, Naruto, se dedica a urdir gamberrada tras gamberrada.\r\nEl sueño de Naruto es el de llegar un día a heredar el nombre de Hokage, reservado a los grandes héroes y de convertirse en el mejor ninja de todos los tiempos.\r\n¡¿Podrá Naruto llegar a cumplir sus anhelos de grandeza?!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775985236389-fgg32c.jpg','unread',0,NULL,NULL,'2026-04-12 09:14:00','2026-04-12 09:14:00',157,NULL,'lujo','[{"name":"Masashi Kishimoto","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1252,'Naruto Jump Remix #2','Naruto Jump Remix',2,NULL,'978-8-411-61209-8',NULL,'Masashi Kishimoto','Masashi Kishimoto',NULL,NULL,'Planeta Cómic',NULL,'2024-06-12',NULL,NULL,replace(replace('Contiene Naruto #34-64\r\n¡¡Se acerca el fin de la saga del País de la Niebla!!\r\n¡¡Sasuke ha protegido a Naruto y pierde el conocimiento!! La tristeza y rabia que experimenta Naruto hacen que se produzca un cambio en su interior. ¿Podrá la furia de Naruto acabar con Haku? ¿Cuál será el resultado del enfrentamiento entre Zabuza y Kakashi?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775985246197-z7uqw6.jpg','unread',0,NULL,NULL,'2026-04-12 09:14:07','2026-04-12 09:14:07',157,NULL,'Rústica','[{"name":"Masashi Kishimoto","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1253,'Naruto Jump Remix #3','Naruto Jump Remix',3,NULL,'978-8-411-61308-8',NULL,'Masashi Kishimoto','Masashi Kishimoto',NULL,NULL,'Planeta Cómic',NULL,'2024-10-09',NULL,NULL,replace(replace('Contiene Naruto #65-90\r\n&quot;Sasuke vendrá a mi&quot;.\r\nCon esas extrañas palabras, Orochimaru desaparece ante los ojos de Narutoy sus compañeros. Pero el sello maléfico de Orochimaru sobre Sasukepotencia de tal modo su poder que los ninjas de la Villa del Sonido se baten en retirada. ¿Qué es lo que busca Orochimaru? ¿Y cómo se desarrollará la prueba para ascender a ninja de grado medio?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775985249212-idepey.jpg','unread',0,NULL,NULL,'2026-04-12 09:14:10','2026-04-12 09:14:10',157,NULL,'Rústica','[{"name":"Masashi Kishimoto","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1254,'Naruto Jump Remix #4','Naruto Jump Remix',4,NULL,'978-8-410-47103-0',NULL,'Masashi Kishimoto','Masashi Kishimoto',NULL,NULL,'Planeta Cómic',NULL,'2025-01-15',NULL,NULL,replace(replace('Contiene Naruto #91-115\r\nPublicado originalmente el 27/11 con errores de impresión. \r\n¡El torneo preliminar de la tercera prueba está que arde! A Gaara, capaz de controlar a su voluntad la arena de su tinaja, le toca enfrentarse a Lee, que se dispone a luchar únicamente con técnicas físicas. ¡La asombrosa fuerza física de Lee tiene a Gaara contra las cuerdas! ¿Qué ocurrirá ahora...?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775985251901-a7ovpp.jpg','unread',0,NULL,NULL,'2026-04-12 09:14:12','2026-04-12 09:14:12',157,NULL,'Rústica','[{"name":"Masashi Kishimoto","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1255,'Naruto Jump Remix #5','Naruto Jump Remix',5,NULL,'978-8-411-61428-3',NULL,'Masashi Kishimoto','Masashi Kishimoto',NULL,NULL,'Planeta Cómic',NULL,'2025-01-15',NULL,NULL,replace(replace('Contiene Naruto #116-145\r\nSasuke por fin ha llegado. Ha hecho su aparición en el estadio en compañía de Kakashi. Comienza su combate contra el temible Gaara, que a duras penas contiene sus instintos asesinos. Sasuke toma la iniciativa atacando a Gaara con gran rapidez. ¿¡Cuál será el resultado!?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775985254288-pd23nn.jpg','unread',0,NULL,NULL,'2026-04-12 09:14:15','2026-04-12 09:14:15',157,NULL,'lujo','[{"name":"Masashi Kishimoto","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1256,'Naruto Jump Remix #6','Naruto Jump Remix',6,NULL,'978-8-411-61432-0',NULL,'Masashi Kishimoto','Masashi Kishimoto',NULL,NULL,'Planeta Cómic',NULL,'2025-03-12',NULL,NULL,replace(replace('Contiene Naruto #146-173\r\n¡¡Culmina la destrucción de la Hoja, pero dos amenazadoras sombras se ciernen ahora sobre la Villa!\r\nNaruto pasa de ser la oveja negra de la Villa a luchar por convertirse en Hokage, el ninja más poderoso de Konoha. Después de enfrentarse a incontables dificultades durante el examen de chûnin, los ninjas de la Arena y del Sonido atacan la Villa, que pasa a convertirse en un campo de batalla. Naruto trata de proteger a Sakura, que ha resultado herida, y a todos sus compañeros en una feroz batalla cara a cara contra Shukaku, el mapache monstruoso en el que se ha transformado Gaara. ¡¡Naruto hace estallar todo su ser en su ataque contra Gaara para salvar a las personas que quiere!! ¡Mientras, la pelea mortal de Orochimaru contra el tercer Hokage llega a su punto álgido...!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775985257033-u12erf.jpg','unread',0,NULL,NULL,'2026-04-12 09:14:18','2026-04-12 09:14:18',157,NULL,'Rústica','[{"name":"Masashi Kishimoto","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1257,'Naruto Jump Remix #7','Naruto Jump Remix',7,NULL,'978-8-411-61435-1',NULL,'Masashi Kishimoto','Masashi Kishimoto',NULL,NULL,'Planeta Cómic',NULL,'2025-05-14',NULL,NULL,replace(replace('Contiene Naruto #174-200\r\nTsunade vuelve a la Villa oculta de la Hoja como quinta Hokage! Nada más investida en su nuevo cargo, Tsunade se encarga de sanar las heridas deKakashi y Sasuke Pero... ¡¿qué ocurre con Lee?!\r\nPor su parte, un apenas recuperado Sasuke desafía a Naruto en combate.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775985259647-j4dbs8.jpg','unread',0,NULL,NULL,'2026-04-12 09:14:20','2026-04-12 09:14:20',157,NULL,'Rústica','[{"name":"Masashi Kishimoto","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1258,'Naruto Jump Remix #8','Naruto Jump Remix',8,NULL,'978-8-411-61450-4',NULL,'Masashi Kishimoto','Masashi Kishimoto',NULL,NULL,'Planeta Cómic',NULL,'2025-07-02',NULL,NULL,replace(replace('Contiene Naruto #201-225\r\nNaruto pasa de ser la oveja negra de su villa a luchar por convertirse en Hokage, el ninja más poderoso de Konoha. Tras el ataque de Orochimaru, su crecimiento como ninja acelera exponencialmente, lo cual irrita y pone nervioso a Sasuke, mientras que Naruto tan solo quiere que lo reconozca como un igual. Los chicos no consiguen llegar a un entendimiento, ¡por lo que comienzan una pelea! ¡Comienzan las batallas a muerte! Sasuke despierta de su estado de muerte aparente. ¡¿Qué ocurrirá cuando Naruto lo alcance?!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775985261910-0n2o8m.jpg','unread',0,NULL,NULL,'2026-04-12 09:14:23','2026-04-12 09:14:23',157,NULL,'Rústica','[{"name":"Masashi Kishimoto","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1259,'Naruto Jump Remix #9','Naruto Jump Remix',9,NULL,'978-8-411-61451-1',NULL,'Masashi Kishimoto','Masashi Kishimoto',NULL,NULL,'Planeta Cómic',NULL,'2025-10-01',NULL,NULL,replace(replace('¡Sigue la nueva edición recopilatoria de Naruto!\r\nEl poder que tanto desea Sasuke es el sharingan definitivo que Itachi empleó para masacrar a su clan: el sharingan caleidoscopio. Parece ser que la única forma de obtenerlo es matando a tus amigos más cercanos, y Sasuke tiene frente a él a la persona que más se acerca a esa descripción\r\n¡La condición para obtener más poder es matar a tus amigos más cercanos! ¡El camino del ninja de Naruto choca con la determinación de Sasuke en el Valle del Final!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775985264281-kgo1e1.jpg','unread',0,NULL,NULL,'2026-04-12 09:14:24','2026-04-12 09:14:24',157,NULL,'Rústica','[{"name":"Masashi Kishimoto","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1260,'Naruto Jump Remix #10','Naruto Jump Remix',10,NULL,'978-8-411-61452-8',NULL,'Masashi Kishimoto','Masashi Kishimoto',NULL,NULL,'Planeta Cómic',NULL,'2025-11-19',NULL,NULL,replace(replace('Han pasado dos años desde que Sasuke se fue de la villa y Naruto ha terminado su viaje para entrenar junto a Jiraiya, por lo que regresa por fin a Konoha. Kakashi le pone a prueba a él y a Sakura en el examen de los cascabeles, donde demuestran su habilidad, restaurando así al grupo 7.\r\n¡Akatsuki ataca! ¡Deidara contra Gaara, el Kazekage!\rJusto antes de su primera misión, la Villa de la Arena manda un mensaje para avisarles sobre la aparición del grupo Akatsuki, por lo que deben acudir al rescate con suma urgencia. Entretanto, Gaara cae en la ingeniosa trampa de Deidara y es capturado.\r¡Akatsuki pasa por fin a la acción! ¡Naruto y el grupo 7 se dirigen hacia la Villa de la Arena para rescatar a Gaara!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775985266240-p4vzbw.jpg','unread',0,NULL,NULL,'2026-04-12 09:14:27','2026-04-12 09:14:27',157,NULL,'Rústica','[{"name":"Masashi Kishimoto","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1261,'Naruto Jump Remix #11','Naruto Jump Remix',11,NULL,'978-8-411-61453-5',NULL,'Masashi Kishimoto','Masashi Kishimoto',NULL,NULL,'Planeta Cómic',NULL,'2026-01-21',NULL,NULL,replace(replace('Después de haber salvado la Villa de la Arena por los pelos, Naruto y los demás vuelven a Konoha.\r\n¡Puede que la información sobre Orochimaru que han conseguido de Sasori les lleve hasta Sasuke, pero antes, el grupo 7 tendrá que enfrentarse a un imprevisto!\r\n¡Con el fin de averiguar más sobre Orochimaru, el nuevo grupo 7 se dirige al Puente del Cielo y la Tierra!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775985268828-ox15kv.jpg','unread',0,NULL,NULL,'2026-04-12 09:14:29','2026-04-12 09:14:29',157,NULL,'Rústica','[{"name":"Masashi Kishimoto","role":"Guion, Dibujo, Tinta"}]');
