INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1336,'Buscadores de cadáveres #1','Buscadores de cadáveres',1,NULL,'978-8-419-98646-7',NULL,'Housui Yamazaki','Housui Yamazaki',NULL,NULL,'Arechi Manga',NULL,'2024-02-08',NULL,NULL,'Un día de verano cualquiera, el jovencito Isshin emprende un viaje con sus amigos del instituto. Su objetivo: encontrar a una compañera desaparecida un par de años atrás. Al parecer, el caso está relacionado con una serie de secuestros infantiles, algo que ha sucedido demasiadas veces en la zona... ¡Una historia de suspense juvenil que te dejará sin uñas!',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775989905216-962z9s.jpg','read',0,NULL,NULL,'2026-04-12 10:31:48','2026-04-12 12:05:57',162,9.95,'rustica','[{"name":"Housui Yamazaki","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1337,'Buscadores de cadáveres #2','Buscadores de cadáveres',2,NULL,'978-8-419-98647-4',NULL,'Housui Yamazaki','Housui Yamazaki',NULL,NULL,'Arechi Manga',NULL,'2024-04-25',NULL,NULL,'Isshin y compañía, de excursión para localizar a Ayano, su compañera desaparecida, llegan a la torre más cercana a su objetivo, pero allí son detenidos. Mientras ellos están retenidos en comisaría, el tengu podría volver a actuar en cualquier momento… Con una serie de secuestros infantiles como telón de fondo, un individuo de pérfidas intenciones amenaza la ciudad. ¡Ha llegado el momento de que los adultos empiecen a barajar hipótesis!',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775989913468-rcxjz5.jpg','read',0,NULL,NULL,'2026-04-12 10:31:54','2026-04-12 12:05:57',162,NULL,'rustica','[{"name":"Housui Yamazaki","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1338,'Buscadores de cadáveres #3','Buscadores de cadáveres',3,NULL,'978-8-410-29479-0',NULL,'Housui Yamazaki','Housui Yamazaki',NULL,NULL,'Arechi Manga',NULL,'2024-09-12',NULL,NULL,'Isshin y sus amigos se adentran cada vez más en la espesura del bosque y avistan por fin la torre clave en la búsqueda de su amiga desaparecida. Sin saberlo, ¡¡el grupo se acerca peligrosamente a la verdad que los adultos tratan de ocultar por todos los medios!! ¡¡La sed de matar del tengu amenaza sin tregua a quienes se acercan al lado oscuro de este escalofriante caso!!',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775989915403-9agc96.jpg','read',0,NULL,NULL,'2026-04-12 10:31:56','2026-04-12 12:05:57',162,NULL,'rustica','[{"name":"Housui Yamazaki","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1339,'Buscadores de cadáveres #4','Buscadores de cadáveres',4,NULL,'978-8-410-29480-6',NULL,'Housui Yamazaki','Housui Yamazaki',NULL,NULL,'Arechi Manga',NULL,'2024-12-05',NULL,NULL,replace(replace('Una trama de una crueldad extrema orquestada durante años al amparo de un rito ancestral. ¡Isshin y sus amigos descubren la verdad tras el caso de los secuestros infantiles que investigan y finalmente llegan a la torre eléctrica que se habían marcado como objetivo desde el principio!\r\n¡¿Lograrán encontrar a Ayano, su amiga desaparecida?! ¡Con el hombre tengu pisándoles los talones, las cosas se pondrán aún más feas para ellos!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775989917426-x1dd0s.jpg','read',0,NULL,NULL,'2026-04-12 10:31:58','2026-04-12 12:05:57',162,NULL,'rustica','[{"name":"Housui Yamazaki","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1340,'Los viajes de Nicola por el Mundo Demoníaco #1','Los viajes de Nicola por el Mundo Demoníaco',1,NULL,'978-8-419-91476-7',NULL,'Asaya Miyanaga',NULL,NULL,NULL,'Milky Way Ediciones',NULL,'2023-12-04',NULL,NULL,replace(replace('La pequeña Nicola se extravía en el Mundo Demoníaco, pero es rescatada por Simon, un mercader ambulante de la raza de los mefistos con el que acabará viajando.\r\n¡Un montón de desafíos le esperan a esta imprudente y glotona niña en un mundo donde la comida es venenosa y los humanos son perseguidos por los demonios!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775989935319-ac76qb.jpg','unread',0,NULL,NULL,'2026-04-12 10:32:19','2026-04-12 10:32:19',163,9,'rustica','[{"name":"Asaya Miyanaga","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1341,'Los viajes de Nicola por el Mundo Demoníaco #2','Los viajes de Nicola por el Mundo Demoníaco',2,NULL,'978-8-410-22300-4',NULL,'Asaya Miyanaga',NULL,NULL,NULL,'Milky Way Ediciones',NULL,'2024-02-28',NULL,NULL,replace(replace('Directa, atrevida, quejica, glotona... ¡y humana! La pequeña Nicola viaja por el Mundo Demoníaco acompañando a Simon, un mercader ambulante de la raza de los mefistos con el que vive muchas aventuras y al que mete en más de un lío.\r\nEn esos viajes, Nicola hace nuevos amigos y también conoce a demonios que forman parte de la vida de Simon. ¡Y, de repente, encuentran una pista que podría llevarlos hasta el paradero de su mamá...!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775989942170-c0eyw7.jpg','unread',0,NULL,NULL,'2026-04-12 10:32:22','2026-04-12 10:32:22',163,NULL,'rustica','[{"name":"Asaya Miyanaga","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1342,'Los viajes de Nicola por el Mundo Demoníaco #3','Los viajes de Nicola por el Mundo Demoníaco',3,NULL,'978-8-410-22326-4',NULL,'Asaya Miyanaga',NULL,NULL,NULL,'Milky Way Ediciones',NULL,'2024-04-29',NULL,NULL,replace(replace('¿Cómo llegó Nicola al Mundo Demoníaco? ¿Y cuál es su destino allí? Las respuestas comienzan a aparecer en Kûllak, la ciudad de los videntes, donde Nicola se entera por una médium de que su madre, que se suponía muerta, ¡podría estar viva!\r\nEn busca de su mamá, Alma, que se encuentra en algún lugar de esas tierras extrañas y mágicas, ¡comienza un nuevo y apasionante viaje de Nicola y Simon por el Mundo Demoníaco!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775989944148-qz177m.jpg','unread',0,NULL,NULL,'2026-04-12 10:32:25','2026-04-12 10:32:25',163,NULL,'rustica','[{"name":"Asaya Miyanaga","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1343,'Los viajes de Nicola por el Mundo Demoníaco #4','Los viajes de Nicola por el Mundo Demoníaco',4,NULL,'978-8-410-22346-2',NULL,'Asaya Miyanaga',NULL,NULL,NULL,'Milky Way Ediciones',NULL,'2024-06-26',NULL,NULL,replace(replace('¡Ya está aquí el último tomo del viaje de Nicola y Simon por el Mundo Demoníaco!\r\nEsta feliz travesía llena de recuerdos bonitos llega a su fin.\r\nNicola continúa buscando a su madre por todas partes en compañía de Simon y Bruno, un pope espadachín. ¡¿Podrá al fin encontrarla?!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775989946319-pb00vl.jpg','unread',0,NULL,NULL,'2026-04-12 10:32:27','2026-04-12 10:32:27',163,NULL,'rustica','[{"name":"Asaya Miyanaga","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1344,'Adabana #1','Adabana',1,NULL,'978-8-419-81907-9',NULL,'Non','Non',NULL,NULL,'Distrito Manga',NULL,'2024-07-04',NULL,NULL,'La sosegada tranquilidad de una pequeña aldea japonesa se ve perturbada cuando hallan cerca de un lago el cuerpo cercenado de una joven estudiante, Mako Igarashi. La gente está inquieta y se siente insegura sabiendo que todavía anda un asesino a sus anchas, pero Mizuki Aikawa, una compañera de clase, ¡se declara culpable del asesinato! Sin embargo, a medida que relata los hechos, la policía se percata de que aún hay cabos sin atar y es posible que Mizuki esté encubriendo a alguien más… Pero, ¿qué motivo tendría para hacerlo?',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775989973608-2xgnj5.jpg','unread',0,NULL,NULL,'2026-04-12 10:32:56','2026-04-12 10:32:56',164,9.95,'rustica','[{"name":"Non","role":"Guion, Dibujo, Tinta"},{"name":"Dai Tezuka","role":"Guion"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1345,'Adabana #2','Adabana',2,NULL,'978-8-419-81908-6',NULL,'Non','Non',NULL,NULL,'Distrito Manga',NULL,'2024-11-07',NULL,NULL,'Nos remontamos a medio año antes de que Mizuki Aikawa se entregue a la policía y confiese que asesinó a su gran amiga Mako Igarashi y a su tío. Mako conoce a Yuuki Akatsuki y cae en una relación tóxica de la que es incapaz de escapar. ¿Cómo acabó Mako muriendo en el periodo de mayor esplendor de su vida, cuando había hecho tan buenas migas con Mizuki? En esta ocasión, la historia se presenta desde el punto de vista de Mako, la víctima... ¿Cuál es la verdad?',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775989979610-edl5dw.jpg','unread',0,NULL,NULL,'2026-04-12 10:33:00','2026-04-12 10:33:00',164,9.95,'rustica','[{"name":"Non","role":"Guion, Dibujo, Tinta"},{"name":"Dai Tezuka","role":"Guion"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1346,'Adabana #3','Adabana',3,NULL,'978-8-419-81909-3',NULL,'Non','Non',NULL,NULL,'Distrito Manga',NULL,'2025-02-06',NULL,NULL,'Se empieza a vislumbrar qué ocurrió realmente en el caso de los asesinatos. Detrás de unos hechos que no acaban de encajar con las declaraciones recogidas hasta el momento, se empieza a ver qué pretende conseguir Mizuki Aikawa. ¡¿A qué conclusión llegan los abogados?! ¡¿Quién asesinó a Mako Igarashi?! Se levanta el telón del juicio decisivo.',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775989981385-6qpuqj.jpg','unread',0,NULL,NULL,'2026-04-12 10:33:02','2026-04-12 10:33:02',164,9.95,'rustica','[{"name":"Non","role":"Guion, Dibujo, Tinta"},{"name":"Dai Tezuka","role":"Guion"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1347,'Reverberación #1','Reverberación',1,NULL,'978-8-467-94109-8',NULL,'Tsutomu Takahashi','Tsutomu Takahashi',NULL,NULL,'Norma Editorial',NULL,'2021-02-05',NULL,NULL,replace(replace('¡EL AUTOR DE NEUN ATERRIZA CON UN NUEVO THRILLER!\r\nAl lado del cuchitril en el que reside Satoru vive Segawa, un anciano exmiembro de la yakuza. Un buen día, su vecino le pide un favor: “Mátame y te daré cinco millones”. Al joven lo corroe la duda y su corazón comienza a ceder ante sus deseos más oscuros. La locura que habita en su interior empieza a aflorar... ¿Qué camino elegirá ahora que es consciente de su verdadera naturaleza?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775990008319-604msn.jpg','unread',0,NULL,NULL,'2026-04-12 10:33:31','2026-04-12 10:33:31',165,9,'rustica','[{"name":"Tsutomu Takahashi","role":"Guion, Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1348,'Reverberación #2','Reverberación',2,NULL,'978-8-467-94495-2',NULL,'Tsutomu Takahashi','Tsutomu Takahashi',NULL,NULL,'Norma Editorial',NULL,'2021-04-09',NULL,NULL,replace(replace('Satoru ha matado a Segawa, un anciano exmiembro de la yakuza que le ha pedido que acabe con su vida. Tras visitar al clan Dôjô para entregar un donativo\r\na los familiares de un hombre que Segawa asesinó hace tiempo, Satoru recibe\r\nuna paliza y acaba encerrado en un zulo. Allí conoce a Daigo, un joven travesti\r\nque lo ayuda a contraatacar acercándole su dinero y su arma. Juntos emprenderán una fuga que los llevará hasta la casa de la hermana de Daigo, una mujer\r\nque se ha convertido en la sombra de lo que era...','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775990014323-us594h.jpg','unread',0,NULL,NULL,'2026-04-12 10:33:34','2026-04-12 16:14:57',165,NULL,'rustica','[{"name":"Tsutomu Takahashi","role":"Guion, Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1349,'Reverberación #3','Reverberación',3,NULL,'978-8-467-94496-9',NULL,'Tsutomu Takahashi','Tsutomu Takahashi',NULL,NULL,'Norma Editorial',NULL,'2021-06-11',NULL,NULL,replace(replace('¡YA LLEGA EL ÚLTIMO TOMO DE REVERBERACIÓN!\r\nEl vínculo entre los tres fugitivos se va estrechando como si de una familia se tratara, pero el jefe del clan Dôjô mata a uno de ellos en la segunda casa a la que acuden para entregar otro donativo. Satoru jura vengarse y se refugia con el niño en Shinjuku, donde tratará de transformarse en una mujer para cobrarse su venganza contra el mafioso. Pasado un tiempo, se entera de que la policía ha emitido una orden de arresto, por lo que ha llegado el momento de dar el paso...','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775990016327-wkyr44.jpg','unread',0,NULL,NULL,'2026-04-12 10:33:37','2026-04-12 16:15:02',165,NULL,'rustica','[{"name":"Tsutomu Takahashi","role":"Guion, Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1350,'Cowa!','Cowa!',NULL,NULL,'843-2-715-02596-2',NULL,'Akira Toriyama','Akira Toriyama',NULL,NULL,'Planeta Cómic',NULL,'1999-01-01',NULL,NULL,'Tras finalizar Dragon Ball, Akira Toriyama deseaba crear una obra que estuviera alejada de la serie que tanto éxito le diera, tanto en los aspectos gráficos como en los puramente temáticos. Prefigurada temáticamente, en «Go! Go! Ackman» (incluída en «Teatro Manga 3»), «Cowa!» estrena un estilo de dibujo muy peculiar de Toriyama para una historia sobre un curioso vampirito realmente hilarante y divertida. El buen aficionado a Toriyama encontrará reminiscencias del humor de «Dr. Slump» y el neófito simplemente pasará un buen rato.',NULL,NULL,208,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775990033913-nh4n5v.jpg','read',0,NULL,NULL,'2026-04-12 10:33:56','2026-04-12 12:05:57',NULL,42.95,'Rústica','[{"name":"Akira Toriyama","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1351,'Kajika','Kajika',NULL,NULL,'978-8-468-47685-8',NULL,'Akira Toriyama','Akira Toriyama',NULL,NULL,'Planeta Cómic',NULL,'1999-01-01',NULL,NULL,'¡Con la intención de librarse de la maldición del zorro, el joven Kajika está inmerso en un viaje en el que tiene que salvar mil vidas! Tras salvar a Haya, una chica a la que los esbirros de Gibachi perseguían, ¡el huevo del último dragón del mundo cae en sus manos...!',NULL,NULL,200,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775990051063-vw563d.jpg','read',0,NULL,NULL,'2026-04-12 10:34:13','2026-04-12 12:05:57',NULL,10.99,'Rústica','[{"name":"Akira Toriyama","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1352,'SandLand','SandLand',NULL,NULL,'8480002105101-00001',NULL,'Akira Toriyama','Akira Toriyama',NULL,NULL,'Planeta Cómic',NULL,'2001-01-01',NULL,NULL,replace(replace('En un mundo desértico en el que tanto humanos como seres demoníacos sufren de carencia crónica de agua, el príncipe de los demonios, Belcebubu, y el alguacil Rao deciden formar un poderoso tándem, ¡¡y salir de viaje para encontrar un nuevo manantial!! ¿¡Qué aventuras les esperan en medio del calor sofocante del desierto!?\r\nUna obra de Akira Toriyama, creador de Dragon Ball, Kajika, Cowa!, Teatro manga y muchas más. Un volumen completo para aquellos que han disfrutado de las anteriores series de este autor cuyo genio no conoce límites.','\r',char(13)),'\n',char(10)),NULL,NULL,216,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775990063040-fus6a6.jpg','read',0,NULL,NULL,'2026-04-12 10:34:24','2026-04-12 12:05:57',NULL,NULL,'Rústica','[{"name":"Akira Toriyama","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1353,'Teatro manga #1','Teatro manga',1,NULL,'84395-55-96-4',NULL,'Akira Toriyama','Akira Toriyama',NULL,NULL,'Planeta Cómic',NULL,'1996-12-01',NULL,NULL,'Wonder Island / Tomato / Pola & Roid / Mad Matic / Chobit',NULL,NULL,208,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775990080954-8e5tkh.jpg','read',0,NULL,NULL,'2026-04-12 10:34:44','2026-04-12 12:05:57',166,42.89,'Rústica','[{"name":"Akira Toriyama","role":"Guion, Dibujo, Tinta"}]');
