INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1358,'Rurouni Kenshin - El guerrero samurai #4','Rurouni Kenshin - El guerrero samurai',4,NULL,'978-8-484-49016-6',NULL,'Nobuhiro Watsuki','Nobuhiro Watsuki',NULL,NULL,'Glénat España - Editores de Tebeos',NULL,'2000-01-01',NULL,NULL,'Un cómic de Nobuhiro Watsuki.Publicado por Glénat España - Editores de Tebeos',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775996947103-m0pjre.jpg','read',0,NULL,NULL,'2026-04-12 12:29:07','2026-04-12 12:29:21',158,NULL,'Rústica con sobrecubierta','[{"name":"Nobuhiro Watsuki","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1359,'Maldad Eterna #1','Maldad Eterna',1,NULL,'978-8-416-07008-4',NULL,'Geoff Johns','David Finch',NULL,NULL,'ECC Ediciones',NULL,'2014-03-01',NULL,NULL,replace(replace('Contiene: Forever Evil nº1 USA\r\nEl Infiltrado, el líder de la Sociedad Secreta, ha manipulado a las tres Ligas de la Justicia para hacerse con la famosa Caja de Pandora. Lejos de tener un origen mágico o mitológico, el artefacto es en realidad el portal al mundo natal del villano, Tierra 3, un lugar donde reinaba el mal encarnado por el Sindicato del Crimen, un grupo formado por versiones retorcidas de los principales héroes de nuestro planeta. Por su parte, debido a sus desavenencias con Batman, Nightwing se marchó de Gotham City, adonde no debería volver...','\r',char(13)),'\n',char(10)),NULL,NULL,240,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775999558497-6ewxds.jpg','read',0,NULL,NULL,'2026-04-12 13:12:42','2026-04-12 16:14:42',167,13.99,'grapa','[{"name":"Geoff Johns","role":"Guion"},{"name":"David Finch","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1360,'Maldad Eterna #2','Maldad Eterna',2,NULL,'978-8-416-07046-6',NULL,'Geoff Johns','David Finch',NULL,NULL,'ECC Ediciones',NULL,'2014-03-31',NULL,NULL,replace('Contiene: Forever Evil nº2 USA\rLex Luthor se ha reinsertado en la sociedad... o eso parece. En todo caso, la muerte de Superman y de los demás miembros de las Ligas de la Justicia hace que sea imposible comprobarlo. Y cuando Ultraman, el líder del Sindicato del Crimen de Tierra 3, provoca un eclipse de sol permanente, Luthor empieza a plantearse un nuevo rumbo. Mientras tanto, dicho Sindicato recluta a todos los villanos del mundo salvo honrosas excepciones poco antes de desvelar ante las cámaras la verdadera identidad de Nightwing, su flamante prisionero.','\r',char(13)),NULL,NULL,240,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775999567714-fmam7j.jpg','read',0,NULL,NULL,'2026-04-12 13:12:48','2026-04-12 16:14:42',167,NULL,'grapa','[{"name":"Geoff Johns","role":"Guion"},{"name":"David Finch","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1361,'Maldad Eterna #3','Maldad Eterna',3,NULL,'978-8-416-07080-0',NULL,'Geoff Johns','David Finch',NULL,NULL,'ECC Ediciones',NULL,'2014-04-30',NULL,NULL,replace('Contiene: Forever Evil nº3 USA\rEl Sindicato del Crimen afianza su control sobre el mundo, y Lex Luthor se ha propuesto evitarlo. Así pues, recurre a un clon de Superman que cultivaba en un laboratorio secreto... pero el duplicado aún no está listo. Sin embargo, el magnate de Metropolis no es el único rebelde. Por ejemplo, Manta Negra no tolera que el Sindicato le privara de matar a Aquaman, y los Villanos no están dispuestos a cometer asesinatos. Y mientras tanto, los primeros supervivientes de las Ligas de la Justicia llegan a Laboratorios S.T.A.R.','\r',char(13)),NULL,NULL,240,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775999572084-0wd7rb.jpg','read',0,NULL,NULL,'2026-04-12 13:12:53','2026-04-12 16:14:42',167,NULL,'grapa','[{"name":"Geoff Johns","role":"Guion"},{"name":"David Finch","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1362,'Maldad Eterna #4','Maldad Eterna',4,NULL,'978-8-416-15211-7',NULL,'Geoff Johns','David Finch',NULL,NULL,'ECC Ediciones',NULL,'2014-05-29',NULL,NULL,replace('Contiene: Forever Evil nº4 USA\rTras enfrentarse con Power Ring y Deathstorm, miembros del Sindicato del Crimen, los Villanos, los enemigos tradicionales de Flash, han huido. La única excepción es el Capitán Frío, que, tras perder sus poderes, se ha quedado atrás. Por suerte, se encuentra con Lex Luthor, que ya ha empezado a urdir un plan para vencer a los conquistadores de Tierra 3 con ayuda del Sujeto B Cero, un clon incompleto de Superman, y otros malhechores ilustres. Por su parte, Batman y Catwoman también tienen un plan.','\r',char(13)),NULL,NULL,240,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775999574441-x0qd4y.jpg','read',0,NULL,NULL,'2026-04-12 13:12:55','2026-04-12 16:14:42',167,NULL,'grapa','[{"name":"Geoff Johns","role":"Guion"},{"name":"David Finch","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1363,'Maldad Eterna #5','Maldad Eterna',5,NULL,'978-8-416-15267-4',NULL,'Geoff Johns','David Finch',NULL,NULL,'ECC Ediciones',NULL,'2014-06-30',NULL,NULL,replace('Contiene: Forever Evil nº5 USA\rEl organismo cibernético conocido como Red ha enviado a Power Ring en busca del Capitán Frío sin decirle que este cuenta con aliados tan poderosos como Black Adam o Bizarro, que se han unido a un grupo de rebeldes organizado por Lex Luthor. Justo cuando estos se enfrentan a Batman y Catwoman, Power Ring irrumpe acompañado por un puñado de villanos de la Sociedad Secreta. Sin embargo, el Caballero Oscuro dispone de un arma secreta: un anillo de los Yellow Lanterns que, al usarlo, llama la atención del mismísimo Sinestro.','\r',char(13)),NULL,NULL,240,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775999576796-w0ofpa.jpg','read',0,NULL,NULL,'2026-04-12 13:12:57','2026-04-12 16:14:42',167,NULL,'grapa','[{"name":"Geoff Johns","role":"Guion"},{"name":"David Finch","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1364,'Maldad Eterna #6','Maldad Eterna',6,NULL,'978-8-416-15297-1',NULL,'Geoff Johns','David Finch',NULL,NULL,'ECC Ediciones',NULL,'2014-07-30',NULL,NULL,replace(replace('Contiene: Forever Evil nº6 USA \r\nCon la esperanza de rescatar al cautivo Nightwing, Batman y Catwoman se han unido al grupo de villanos encabezado por Lex Luthor, que cuenta con otro flamante miembro: Sinestro, el líder de los Yellow Lanterns, que acaba de asesinar a Power Ring. Cuando el anillo de este último se queda sin portador, emprende la búsqueda de un nuevo esclavo y emite una señal que alarma a los demás miembros del Sindicato del Crimen, ya que se convierte en una especie de baliza que alerta al “ser que destruyó su mundo”.','\r',char(13)),'\n',char(10)),NULL,NULL,240,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775999578714-y74bbj.jpg','read',0,NULL,NULL,'2026-04-12 13:12:59','2026-04-12 16:14:42',167,NULL,'grapa','[{"name":"Geoff Johns","role":"Guion"},{"name":"David Finch","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1365,'Maldad Eterna #7','Maldad Eterna',7,NULL,'978-8-416-19444-5',NULL,'Geoff Johns','David Finch',NULL,NULL,'ECC Ediciones',NULL,'2014-09-01',NULL,NULL,replace(replace('Contiene: Forever Evil nº7 USA\r\nTras irrumpir en la base del Sindicato del Crimen, Luthor interviene en la contienda de forma decisiva... aunque despierta la ira de Batman. Mientras, el Capitán Frío y Manta Negra liberan al prisionero encapuchado, que invoca el relámpago oscuro para convertirse en un ser de inmenso poder. Por su parte, Cíborg, Steve Trevor y J’onn J’onzz parecen haber averiguado cómo rescatar a la Liga de la Justicia.','\r',char(13)),'\n',char(10)),NULL,NULL,240,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775999581240-0cht1x.jpg','read',0,NULL,NULL,'2026-04-12 13:13:02','2026-04-12 16:14:42',167,NULL,'grapa','[{"name":"Geoff Johns","role":"Guion"},{"name":"David Finch","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1366,'El Multiverso #1','El Multiverso',1,NULL,'978-8-416-37446-5',NULL,'Grant Morrison','Ivan Reis',NULL,NULL,'ECC Ediciones',NULL,'2015-03-24',NULL,NULL,replace(replace('Incluye The Multiversity #1 USA\r\nSerie de 9 comic-books.\r\n&quot;El Multiverso está formado por 52 universos, algunos de los cuales ya conocemos. Por ejemplo, en Tierra 2 viven las Maravillas que luchan contra Apokolips, y el malvado Sindicato del Crimen procede de Tierra 3. Por otra parte, en Tierra 23, Superman es afroamericano y, además, es el presidente de Estados Unidos. No hace mucho, su peor enemigo, Lex Luthor, creó una formación sinfónica de transmateria mientras estaba drogado. En realidad, era un portal que conducía a otras dimensiones alternativas...&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,480,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775999620795-7npg6d.jpg','read',0,NULL,NULL,'2026-04-12 13:13:44','2026-04-12 16:14:42',168,24.95,'grapa','[{"name":"Grant Morrison","role":"Guion"},{"name":"Ivan Reis","role":"Dibujo"},{"name":"Joe Prado","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1367,'El Multiverso #2','El Multiverso',2,NULL,'978-8-416-37492-2',NULL,'Grant Morrison','Chris Sprouse',NULL,NULL,'ECC Ediciones',NULL,'2015-04-29',NULL,NULL,'Tras la primera e irresistible entrega de El Multiverso (¡y no solo por su precio promocional de 1 €!), Grant Morrison nos ofrece un vistazo a otra de las Tierras que integran el Multiverso, contando esta vez con la ayuda de Chris Sprouse a los lápices. ¡No os perdáis el cómic del momento!',NULL,NULL,480,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775999652011-oi18id.jpg','read',0,NULL,NULL,'2026-04-12 13:14:13','2026-04-12 16:14:42',168,NULL,'grapa','[{"name":"Grant Morrison","role":""},{"name":"Chris Sprouse","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1368,'El Multiverso #3','El Multiverso',3,NULL,'978-8-416-40935-8',NULL,'Grant Morrison','Ben Oliver',NULL,NULL,'ECC Ediciones',NULL,'2015-05-25',NULL,NULL,replace(replace('Corresponde a The Multiversity: The Just #1 USA (octubre/2014)\r\n&quot;Grant Morrison explora un nuevo rincón del Multiverso DC, contando con la colaboración de Ben Oliver (Batman/Superman, Superman: Año cero) para mostrarnos a una nueva generación de héroes tan famosos como acomodados, que tendrá que afrontar una gran amenaza.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,480,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775999656562-en8zck.jpg','read',0,NULL,NULL,'2026-04-12 13:14:17','2026-04-12 16:14:42',168,NULL,'grapa','[{"name":"Grant Morrison","role":"Guion"},{"name":"Ben Oliver","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1369,'El Multiverso #4','El Multiverso',4,NULL,'978-8-416-40985-3',NULL,'Grant Morrison','Frank Quitely',NULL,NULL,'ECC Ediciones',NULL,'2015-07-01',NULL,NULL,replace(replace('Corresponde a The Multiversity: Pax Americana USA\r\n&quot;Cada ocasión en que Grant Morrison y Frank Quitely colaboran en un proyecto, surge algo especial. Y Pax Americana no ha sido la excepción, optando a los Premios Eisner 2015 al mejor número unitario y al mejor dibujante/entintador. Nominaciones que se suman a las cosechadas por El Multiverso en las categorías de mejor guionista y mejor serie limitada. Sin duda, ¡uno de los cómics del año!&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,480,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775999661636-p0cs2g.jpg','read',0,NULL,NULL,'2026-04-12 13:14:22','2026-04-12 16:14:42',168,NULL,'grapa','[{"name":"Grant Morrison","role":"Guion"},{"name":"Frank Quitely","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1370,'El Multiverso #5','El Multiverso',5,NULL,'978-8-416-47522-3',NULL,'Grant Morrison','Cameron Stewart',NULL,NULL,'ECC Ediciones',NULL,'2015-07-28',NULL,NULL,'EDICIÓN ORIGINAL: Multiversity: Thunderworld USA Este mes, Grant Morrison cuenta con la colaboración de Cameron Stewart (Los Siete Soldados de la Victoria, Batman contra Robin) para dar forma a Tierra-5: un mundo en el que Shazam y su ya clásica galería de aliados y enemigos acaparan todo el protagonismo.',NULL,NULL,480,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1775999668607-10stc9.jpg','read',0,NULL,NULL,'2026-04-12 13:14:29','2026-04-12 16:14:42',168,NULL,'grapa','[{"name":"Grant Morrison","role":"Guion"},{"name":"Cameron Stewart","role":"Dibujo"}]');
