INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1427,'El Batman que ríe #1','El Batman que ríe',1,NULL,'978-8-417-87126-0',NULL,'Scott Snyder','Jock',NULL,NULL,'ECC Ediciones',NULL,'2019-05-14',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: The Batman Who Laughs núm. 1 USA\r\n¡Nueva serie limitada! ¡Formato grapa mensual! Durante los eventos de Noches oscuras: Metal, Bruce Wayne y todos los héroes del Universo DC se vieron cara a cara con las malvadas versiones de Batman generadas por el Multiverso Oscuro. Aunque los héroes vencieron, la pesadilla no ha terminado. Batman acaba de descubrir que El Batman que ríe, la versión más peligrosa del Caballero Oscuro, logró sobrevivir y trata de finalizar sus siniestros planes. Parece que la única manera de detener a este loco es acabando con su vida. ¿Violará Batman su más sagrada norma? ¿Se cumplirá su destino y se convertirá realmente en el Batman que ríe? El estelar equipo creativo formado por Scott Snyder y Jock, responsables de Batman: Espejo oscuro, responden a estas y otras preguntas en uno de los proyectos más esperados de 2019.','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000090020-hlsmn7.jpg','read',0,NULL,NULL,'2026-04-12 13:21:32','2026-04-12 16:14:36',178,24.95,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Jock","role":"Dibujo, Tinta"},{"name":"David Baron","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1428,'El Batman que ríe #2','El Batman que ríe',2,NULL,'978-8-417-87194-9',NULL,'Scott Snyder','Jock',NULL,NULL,'ECC Ediciones',NULL,'2019-06-11',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: The Batman Who Laughs núm. 2 USA\r\nTras el impactante desenlace de la primera entrega, el Multiverso se descubre ante Batman. El Caballero Oscuro comienza a ver todas las versiones de su vida, el hombre en el que podría convertirse. Mientras, el Batman que ríe levanta el telón del segundo acto de su plan, irrumpiendo en el Asilo Arkham... ¡y desatando al Caballero Sombrío!','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000097644-xi5abx.jpg','read',0,NULL,NULL,'2026-04-12 13:21:38','2026-04-12 16:14:36',178,NULL,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Jock","role":"Dibujo, Tinta"},{"name":"David Baron","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1429,'El Batman que ríe #3','El Batman que ríe',3,NULL,'978-8-417-90851-5',NULL,'Scott Snyder','Jock',NULL,NULL,'ECC Ediciones',NULL,'2019-07-09',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: The Batman Who Laughs núm. 3 USA\r\nEl Batman que ríe sigue encajando las piezas de su plan, en esta ocasión con alguien muy relacionado con los padres fundadores de Gotham. Mientras, Batman se ve obligado a purgar la toxina del Joker de su cuerpo. Una situación imposible en la que Snyder y Jock recuperan a otro famoso sociópata, salido de las páginas de su clásico moderno Batman: Espejo oscuro...','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000101237-bkvp3b.jpg','read',0,NULL,NULL,'2026-04-12 13:21:42','2026-04-12 16:14:36',178,NULL,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Jock","role":"Dibujo, Tinta"},{"name":"David Baron","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1430,'El Batman que ríe #4','El Batman que ríe',4,NULL,'978-8-417-96001-8',NULL,'Scott Snyder','Eduardo Risso',NULL,NULL,'ECC Ediciones',NULL,'2019-08-13',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: The Batman Who Laughs: The Grim Knight núm. 1 USA (one-shot)\r\nEl Caballero Sombrío, salido de las pesadillas más terribles de Batman, es el vigilante enmascarado más peligroso de su mundo. No tiene miedo de usar cualquier arma. No tiene miedo a emplear cualquier método para detener a aquellos a quienes considera dignos de morir. Entrenado con el mejor arsenal que Industrias Wayne puede comprar, esta entrega de El Batman que ríe recoge el especial centrado en el origen secreto del segundo Caballero Oscuro más mortífero del Multiverso. ¡Con dibujo de Eduardo Risso (100 balas)!','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000103331-ym2div.jpg','read',0,NULL,NULL,'2026-04-12 13:21:43','2026-04-12 16:14:36',178,NULL,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"James Tynion IV","role":"Guion"},{"name":"Eduardo Risso","role":"Dibujo, Tinta"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1431,'El Batman que ríe #5','El Batman que ríe',5,NULL,'978-8-417-96071-1',NULL,'Scott Snyder','Jock',NULL,NULL,'ECC Ediciones',NULL,'2019-09-10',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: The Batman Who Laughs núm. 4 USA \r\n¡A la caza del Caballero Sombrío! Batman persigue desesperadamente a su versión oscura por toda Gotham, pero sufre las consecuencias del suero que él mismo se administró, que lo está convirtiendo poco a poco en el Batman que ríe. La línea entre la venganza y la justicia es muy fina. ¿Apretará el gatillo y reirá el último? ¿Salvará a su ciudad... o la condenará para siempre?','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000105192-pcypx2.jpg','read',0,NULL,NULL,'2026-04-12 13:21:46','2026-04-12 16:14:36',178,NULL,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Jock","role":"Dibujo, Tinta"},{"name":"David Baron","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1432,'El Batman que ríe #6','El Batman que ríe',6,NULL,'978-8-418-02685-0',NULL,'Scott Snyder','Jock',NULL,NULL,'ECC Ediciones',NULL,'2019-10-22',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: The Batman Who Laughs núm. 5 USA.\r\n¡Batalla a muerte contra el Caballero Sombrío! El Cruzado de la Capa se enfrenta a la versión más malvada de sí mismo, pero también a la creciente necesidad de darle la espalda a su código moral, a medida que el suero del Joker se apodera de su cuerpo. El plan del Batman que ríe sigue su curso y, poco a poco, Gotham se convierte en una incubadora del mal.','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000107669-z0v9sm.jpg','read',0,NULL,NULL,'2026-04-12 13:21:48','2026-04-12 16:14:36',178,NULL,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Jock","role":"Dibujo, Tinta"},{"name":"David Baron","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1433,'El Batman que ríe #7','El Batman que ríe',7,NULL,'978-8-418-04366-6',NULL,'Scott Snyder','Jock',NULL,NULL,'ECC Ediciones',NULL,'2019-11-19',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: The Batman Who Laughs núm. 6 USA\r\nEl Batman que Ríe se enfrenta contra el único hombre que se interpone en su camino, el único hombre que podría completar o detener su plan... el último Bruce Wayne. Entre las paredes de la Mansión Wayne, Bruce revive el momento más feliz de su vida, el momento en el que se convirtió en el Batman que Ríe. ¿Sucumbirá el Hombre Murciélago original ante su versión del Multiverso Oscuro?','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000109991-fdcr8g.jpg','read',0,NULL,NULL,'2026-04-12 13:21:50','2026-04-12 16:14:36',178,NULL,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Jock","role":"Dibujo, Tinta"},{"name":"David Baron","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1434,'El Batman que ríe #8','El Batman que ríe',8,NULL,'978-8-418-09424-8',NULL,'Scott Snyder','Jock',NULL,NULL,'ECC Ediciones',NULL,'2019-12-10',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: The Batman Who Laughs núm. 7 USA, Batman/Superman núm. 1 USA (extracto)\r\n¿Pensabas que todo había terminado? Hay algunas pesadillas que están condenadas a atormentarnos una y otra vez. Y es que, ¿cómo derrotar a un enemigo que conoce tus pensamientos y tus movimientos? Es el enfrentamiento definitivo del bien contra el mal, de Bruce Wayne contra Bruce Wayne. ¡Un desenlace que hará temblar los cimientos de Gotham City! Incluye un avance exclusivo de la serie Batman/Superman, que llegará a España en 2020.','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000111868-60h9bm.jpg','read',0,NULL,NULL,'2026-04-12 13:21:52','2026-04-12 16:14:36',178,NULL,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Jock","role":"Dibujo, Tinta"},{"name":"Joshua Williamson","role":"Guion"},{"name":"David Marquez","role":"Dibujo, Tinta"},{"name":"David Baron","role":"Color"},{"name":"Alejandro Sánchez","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1435,'Héroes en Crisis #1','Héroes en Crisis',1,NULL,'978-8-417-78701-1',NULL,'Tom King','Clay Mann',NULL,NULL,'ECC Ediciones',NULL,'2019-02-12',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Heroes in Crisis núm. 1 USA\r\nSantuario es un centro secreto de recuperación destinado a superhéroes traumatizados tras años de lucha contra el crimen y sucesos cósmicos. Es un lugar de reposo y reflexión. Sin embargo, algo ha alterado la paz de Santuario. Cuando un asesinato múltiple tiene lugar en el recinto, dos de sus residentes, Booster Gold y Harley Quinn, se convierten en los principales sospechosos. ¿Podrán descubrir Batman, Superman y Wonder Woman el origen de este brutal crimen? \r\nEn la tradición de Crisis en Tierras Infinitas, Crisis Infinita, Crisis de Identidad o Crisis Final, un nuevo evento reúne a todos los iconos del Universo DC. Todo empieza con una pregunta impactante, con un hecho en el que nadie ha reparado hasta la fecha o que nadie se atrevía verbalizar: ¿cómo afronta un superhéroe el trastorno de estrés postraumático, provocado por tantas situaciones al borde de la muerte? Tom King, antiguo operativo de la CIA, ganador de varios premios Eisner, responsable de Mr. Milagro, El Sheriff de Babilonia, Omega Men y Batman, trata de responder a esta inesperada cuestión, con la colaboración estelar del dibujante Clay Mann (Batman).','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000134089-lozbyk.jpg','read',0,NULL,NULL,'2026-04-12 13:22:17','2026-04-12 16:14:36',179,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Clay Mann","role":"Dibujo, Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1436,'Héroes en Crisis #2','Héroes en Crisis',2,NULL,'978-8-417-78757-8',NULL,'Tom King','Clay Mann',NULL,NULL,'ECC Ediciones',NULL,'2019-03-12',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Heroes in Crisis núm. 2 USA\r\nLos sospechosos de asesinato [SPOILER] y [SPOILER] huyen tras la masacre de Santuario. ¿Quién es el verdadero culpable? Batman encabeza la investigación, pero las pistas llevan por otro camino muy sorprendente a Superman y Wonder Woman. Mientras, [SPOILER] trata de esconderse de la Trinidad y [SPOILER] recurre a un viejo amigo... y se mete en más problemas.','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000143436-k90ldl.jpg','read',0,NULL,NULL,'2026-04-12 13:22:24','2026-04-12 16:14:36',179,NULL,'Grapa','[{"name":"Tom King","role":"Guion"},{"name":"Clay Mann","role":"Dibujo, Tinta"},{"name":"Travis Moore","role":"Dibujo, Tinta"},{"name":"Tomeu Morey","role":"Color"},{"name":"Arif Prianto","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1437,'Héroes en Crisis #3','Héroes en Crisis',3,NULL,'978-8-417-82727-4',NULL,'Tom King','Clay Mann',NULL,NULL,'ECC Ediciones',NULL,'2019-04-02',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Heroes in Crisis núm. 3 USA\r\n¿Qué otros secretos oculta el Santuario? ¿Qué suceso provocó que Batman, Superman y Wonder Woman autorizasen su creación? ¿Cómo fue construido? ¿Quién es realmente el &quot;cerebro&quot; del Santuario? Capas y más capas de misterio se superponen en el nuevo capítulo del evento que reúne a todo el Universo DC, ilustrado en esta ocasión por Lee Weeks (Batman/Elmer Fudd).','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000145782-33gre0.jpg','read',0,NULL,NULL,'2026-04-12 13:22:26','2026-04-12 16:14:36',179,NULL,'Grapa','[{"name":"Tom King","role":"Guion"},{"name":"Clay Mann","role":"Dibujo, Tinta"},{"name":"Lee Weeks","role":"Dibujo, Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1438,'Héroes en Crisis #4','Héroes en Crisis',4,NULL,'978-8-417-87111-6',NULL,'Tom King','Clay Mann',NULL,NULL,'ECC Ediciones',NULL,'2019-05-07',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Heroes in Crisis núm. 4 USA\r\n¡Wonder Woman contra Booster Gold! Parece un combate sencillo para la Mujer Maravilla, pero todos sabemos que Booster guarda muchos ases en la manga, sobre todo cuando está entre la espada y la pared. Mientras, Batman y Flash combinan sus habilidades detectivescas para descubrir un secreto espeluznante sobre el Santuario.','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000148238-02ki91.jpg','read',0,NULL,NULL,'2026-04-12 13:22:29','2026-04-12 16:14:36',179,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Clay Mann","role":"Dibujo, Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1439,'Héroes en Crisis #5','Héroes en Crisis',5,NULL,'978-8-417-87178-9',NULL,'Tom King','Clay Mann',NULL,NULL,'ECC Ediciones',NULL,'2019-06-04',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Heroes in Crisis núm. 5 USA\r\n¡Los secretos del Universo DC están al descubierto! Se suponía que el Santuario no debía guardar ningún registro, pero alguien ha hackeado el sistema y los secretos de los superhéroes se han filtrado. Booster y Harley dejan de lado sus diferencias para enfocarse en el (para ellos) verdadero asesino. Mientras, Batman y Flash prosiguen con la investigación. La respuesta puede estar justo delante de sus narices...','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000150863-jhk0k4.jpg','read',0,NULL,NULL,'2026-04-12 13:22:31','2026-04-12 16:14:36',179,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Clay Mann","role":"Dibujo, Tinta"},{"name":"Travis Moore","role":"Dibujo, Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1440,'Héroes en Crisis #6','Héroes en Crisis',6,NULL,'978-8-417-90841-6',NULL,'Tom King','Clay Mann',NULL,NULL,'ECC Ediciones',NULL,'2019-07-02',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Heroes in Crisis núm. 6 USA\r\n¡Viajamos al corazón del Santuario! Los héroes del Universo DC se enfrentaron durante meses a sus traumas internos, revividos a través de la realidad virtual, buscando una solución para sus maltrechas mentes. ¡Sin embargo, los traumas ganaron la partida y la Crisis estalló! Uno de los héroes llegó al límite y provocó una catástrofe. El equipo creativo de Mr. Milagro, formado por Tom King y Mitch Gerads, regresa para narrar uno de los episodios más oscuros del Universo DC.','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000153168-1b3iqp.jpg','read',0,NULL,NULL,'2026-04-12 13:22:34','2026-04-12 16:14:36',179,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Clay Mann","role":"Dibujo, Tinta"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1441,'Héroes en Crisis #7','Héroes en Crisis',7,NULL,'978-8-417-90887-4',NULL,'Tom King','Clay Mann',NULL,NULL,'ECC Ediciones',NULL,'2019-08-06',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Heroes in Crisis núm. 7 USA\r\nLa Trinidad parece haber descubierto al fin la identidad del asesino responsable de la masacre en el Santuario, ¡pero la inteligencia artificial que dirigía la institución no parece dispuesta a dejar que terminen la investigación! Batman, Superman y Wonder Woman deben enfrentarse a su propia creación. Además, a medida que la verdad sale a la luz, Booster y Harley se convierten en aliados...','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000155868-efum27.jpg','read',0,NULL,NULL,'2026-04-12 13:22:36','2026-04-12 16:14:28',179,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Clay Mann","role":"Dibujo, Tinta"},{"name":"Mitch Gerads","role":"Dibujo, Tinta"},{"name":"Jorge Fornés","role":"Dibujo, Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1442,'Héroes en Crisis #8','Héroes en Crisis',8,NULL,'978-8-417-96061-2',NULL,'Tom King','Mitch Gerads',NULL,NULL,'ECC Ediciones',NULL,'2019-09-03',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Heroes in Crisis núm. 8 USA\r\nHas seguido todas las pistas. Has visto a los testigos. Has escuchado, a escondidas, los confesiones ocultas de los superhéroes más grandes del Universo DC. Ahora, con el asesino al descubierto, es el momento de responder a la gran pregunta: ¿por qué? La tensión se desborda y la Trinidad está en tela de juicio. Su Santuario se ha convertido en algo que nunca habían imaginado. Y la pesadilla todavía no ha terminado.','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000157731-bb47on.jpg','read',0,NULL,NULL,'2026-04-12 13:22:38','2026-04-12 16:14:28',179,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"},{"name":"Travis Moore","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1443,'Héroes en Crisis #9','Héroes en Crisis',9,NULL,'978-8-418-02675-1',NULL,'Tom King','Clay Mann',NULL,NULL,'ECC Ediciones',NULL,'2019-10-15',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Heroes in Crisis núm. 9 USA\r\n¡Uno de los fenómenos del año llega a su impresionante final! El misterio está resuelto. La verdad sobre la identidad de la mente maestra responsable de la masacre ocurrida en el Santuario golpea con fuerza a la comunidad de metahumanos. ¿Cómo continuar tras el trauma? ¿Serán capaces de seguir adelante? El destino de Booster Gold, Harley Quinn y el resto de iconos de DC está en juego.','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000160005-i1s9ji.jpg','read',0,NULL,NULL,'2026-04-12 13:22:40','2026-04-12 16:14:28',179,NULL,'lujo','[{"name":"Tom King","role":"Guion"},{"name":"Clay Mann","role":"Dibujo, Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1444,'DCsos #1','DCsos',1,NULL,'978-8-418-02676-8',NULL,'Tom Taylor','Trevor Hairsine',NULL,NULL,'ECC Ediciones',NULL,'2019-10-15',NULL,NULL,replace(replace('Un misterioso virus ha sido liberado. ¿Las consecuencias? 600 millones de personas infectadas, convertidas instantáneamente en monstruosos y violentos seres que sólo tienen una cosa en la mente: destruir y sembrar el caos. \r\nLos héroes del Universo DC se enfrentan ahora a una pandemia de consecuencias inimaginables, luchando por salvar a sus seres queridos. Pero, ¿qué ocurrirá si ellos también fracasan y son infectados?\r\nEl escritor superventas del','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000200658-1zk484.jpg','read',0,NULL,NULL,'2026-04-12 13:23:24','2026-04-12 16:14:28',180,24.95,'Grapa','[{"name":"Tom Taylor","role":"Guion"},{"name":"Trevor Hairsine","role":"Dibujo"},{"name":"James Harren","role":"Dibujo, Tinta"},{"name":"Stefano Gaudiano","role":"Tinta"},{"name":"Rain Beredo","role":"Color"},{"name":"Greg Capullo","role":"Dibujo, Tinta"},{"name":"FCO Plascencia","role":"Color"}]');
