INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1446,'DCsos #3','DCsos',3,NULL,'978-8-418-09411-8',NULL,'Tom Taylor','Trevor Hairsine',NULL,NULL,'ECC Ediciones',NULL,'2019-12-10',NULL,NULL,'Héroes, villanos y dioses. Todos están a merced del virus. Las ciudades más poderosas han caído. La pandemia se extiende por los océanos, llegando hasta la isla de Themyscira. ¡El destino de la Tierra pende de un hilo! La Liga de la Justicia ya conoce la clave de la infección. ¿Es demasiado tarde o todavía queda alguna esperanza?',NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000212380-5f7sup.jpg','read',0,NULL,NULL,'2026-04-12 13:23:33','2026-04-12 16:14:28',180,NULL,'Grapa','[{"name":"Tom Taylor","role":"Guion"},{"name":"Trevor Hairsine","role":"Dibujo, Tinta"},{"name":"Stefano Gaudiano","role":"Tinta"},{"name":"Rain Beredo","role":"Color"}]');
