INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1455,'DC contra vampiros #6','DC contra vampiros',6,NULL,'978-8-419-51877-4',NULL,'Matthew Rosenberg','Otto Schmidt',NULL,NULL,'ECC Ediciones',NULL,'2022-11-08',NULL,NULL,replace('EDICIÓN ORIGINAL: DC vs. Vampires núm. 6 USA\rBatman ha descubierto a los vampiros infiltrados en la Liga de la Justicia. Pero el momento más impactante del año está a punto de suceder: ¡en este número se desvela la identidad del Rey Vampiro! Llegamos al sangriento ecuador de la miniserie.','\r',char(13)),NULL,NULL,208,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000264558-yywy4d.jpg','read',0,NULL,NULL,'2026-04-12 13:24:25','2026-04-12 16:14:28',181,NULL,'grapa','[{"name":"Matthew Rosenberg","role":"Guion"},{"name":"James Tynion IV","role":"Guion"},{"name":"Otto Schmidt","role":"Dibujo, Tinta, Color"},{"name":"Simone Di Meo","role":"Dibujo, Tinta, Color"},{"name":"Daniele Di Nicuolo","role":"Dibujo, Tinta"},{"name":"Rex Lokus","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1456,'DC contra vampiros #7','DC contra vampiros',7,NULL,'978-8-419-54955-6',NULL,'Matthew Rosenberg','Neil Googe',NULL,NULL,'ECC Ediciones',NULL,'2022-11-29',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: DC vs. Vampires: Hunters núm. 1 USA\r\n¡Un nuevo capítulo de la saga! Después de años de entrenamiento, Damian Wayne, el hijo de Batman, está preparado para cumplir con su destino: la destrucción total de la raza vampírica. ¡Esto es Damian Wayne: Cazavampiros!','\r',char(13)),'\n',char(10)),NULL,NULL,208,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000266935-njt4j6.jpg','read',0,NULL,NULL,'2026-04-12 13:24:28','2026-04-12 16:14:28',181,NULL,'grapa','[{"name":"Matthew Rosenberg","role":"Guion"},{"name":"Neil Googe","role":"Dibujo, Tinta"},{"name":"Antonio Fabela","role":"Color"},{"name":"Jonboy Meyers","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1457,'DC contra vampiros #8','DC contra vampiros',8,NULL,'978-8-419-58631-5',NULL,'Matthew Rosenberg','Mike Bowden',NULL,NULL,'ECC Ediciones',NULL,'2023-01-24',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: DC vs. Vampires: Killers núm. 1 USA\r\nEl nuevo orden mundial vampírico ha tomado las riendas. En el inframundo de esta nueva era de oscuridad, una persona ha sobrevivido por sí misma, ¡y puede que tenga la clave para salvar el mundo! Su nombre es Harleen Quinzel, aunque todo el mundo la conoce como Harley Quinn.','\r',char(13)),'\n',char(10)),NULL,NULL,208,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000269566-616hrf.jpg','read',0,NULL,NULL,'2026-04-12 13:24:30','2026-04-12 16:14:28',181,NULL,'grapa','[{"name":"Matthew Rosenberg","role":"Guion"},{"name":"Mike Bowden","role":"Dibujo, Tinta"},{"name":"Eduardo Mello","role":"Dibujo, Tinta"},{"name":"Le Beau Underwood","role":"Tinta"},{"name":"John Livesay","role":"Tinta"},{"name":"Antonio Fabela","role":"Color"},{"name":"Hicham Habchi","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1458,'DC contra vampiros #9','DC contra vampiros',9,NULL,'978-8-419-62603-5',NULL,'Matthew Rosenberg','Otto Schmidt',NULL,NULL,'ECC Ediciones',NULL,'2023-02-21',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: DC vs. Vampires núm. 7 USA\r\n¡La noche es más oscura antes del amanecer! ¡Aquí empieza el segundo arco de esta pesadilla! El imperio vampírico ha tomado el control de la Tierra. Green Arrow, Batgirl y Supergirl traman un plan desesperado para salvar el mundo... ¡o morir en el intento!','\r',char(13)),'\n',char(10)),NULL,NULL,208,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000271912-1mocu5.jpg','read',0,NULL,NULL,'2026-04-12 13:24:33','2026-04-12 16:14:28',181,NULL,'grapa','[{"name":"Matthew Rosenberg","role":"Guion"},{"name":"James Tynion IV","role":"Guion"},{"name":"Otto Schmidt","role":"Dibujo, Tinta, Color"},{"name":"Guillem March","role":"Dibujo, Tinta, Color"}]');
