INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1460,'DC contra vampiros #11','DC contra vampiros',11,NULL,'978-8-419-67884-3',NULL,'Matthew Rosenberg','Otto Schmidt',NULL,NULL,'ECC Ediciones',NULL,'2023-04-25',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: DC vs. Vampires núm. 9 USA\r\n¡Preparad las maletas! Las Aves de Presa siguen con su perturbador viaje por Gotham mientras que Supergirl puede caer derrotada ante… ¿Mantarraya? Por su parte, Green Arrow planta cara a un viejo amigo. ¡Se vienen curvas!','\r',char(13)),'\n',char(10)),NULL,NULL,208,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000276646-rarkoc.jpg','read',0,NULL,NULL,'2026-04-12 13:24:37','2026-04-12 16:14:28',181,NULL,'grapa','[{"name":"Matthew Rosenberg","role":"Guion"},{"name":"James Tynion IV","role":"Guion"},{"name":"Otto Schmidt","role":"Dibujo, Tinta, Color"},{"name":"Guillem March","role":"Dibujo, Tinta, Color"}]');
