INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1463,'DC contra vampiros #14','DC contra vampiros',14,NULL,'978-8-419-81100-4',NULL,'Matthew Rosenberg','Otto Schmidt',NULL,NULL,'ECC Ediciones',NULL,'2023-07-18',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: DC vs. Vampires núm. 12 USA\r\n¡Último número! ¡El futuro de la humanidad está en juego! Green Arrow libra su última batalla en las minas de sangre de Smallville. ¿Puede Supergirl salir victoriosa de su misión? ¿Quién ganará de la encarnizada pelea entre Nightwing y Batgirl? ¿Estás preparado para este sangriento final?','\r',char(13)),'\n',char(10)),NULL,NULL,208,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000284215-27a3wu.jpg','read',0,NULL,NULL,'2026-04-12 13:24:44','2026-04-12 16:14:28',181,NULL,'grapa','[{"name":"Matthew Rosenberg","role":"Guion"},{"name":"James Tynion IV","role":"Guion"},{"name":"Otto Schmidt","role":"Dibujo, Tinta, Color"},{"name":"Francesco Mortarino","role":"Dibujo, Tinta, Color"},{"name":"Pierluigi Casolino","role":"Dibujo, Tinta, Color"},{"name":"Guillem March","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1464,'Los Caballeros Oscuros de Acero #1','Los Caballeros Oscuros de Acero',1,NULL,'978-8-419-48476-5',NULL,'Tom Taylor','Yasmine Putri',NULL,NULL,'ECC Ediciones',NULL,'2022-10-25',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Dark Knights of Steel núms 1-2 USA\r\nEn la tradición de DCsos, Tom Taylor y Yasmine Putri presentan una versión medieval nunca vista del Universo DC. Esta versión de fantasía del mundo de Batman, Superman y compañía está a punto de cambiar para siempre cuando una nave espacial se estrella contra la superficie. Caerán reyes, se levantarán reinos. ¡Nada es lo que parece!','\r',char(13)),'\n',char(10)),NULL,NULL,56,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000311211-nxno24.jpg','read',0,NULL,NULL,'2026-04-12 13:25:14','2026-04-12 16:14:28',182,24.95,'grapa','[{"name":"Tom Taylor","role":"Guion"},{"name":"Yasmine Putri","role":"Dibujo, Tinta, Color"},{"name":"Arif Prianto","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1465,'Los Caballeros Oscuros de Acero #0','Los Caballeros Oscuros de Acero',0,NULL,'978-8-419-73330-6',NULL,'Tom Taylor','Caspar Wijngaard',NULL,NULL,'ECC Ediciones',NULL,'2023-05-16',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Dark Knights of Steel - Tales from the Three Kingdoms USA\r\n¡El origen de la saga! Durante generaciones, la paz ha reinado gracias a las dinastías Wayne y El. Pero todo puede cambiar en un momento. Para que eso no pase, los herederos del trono todavía tienen que mucho que aprender. ¡Y rápido! ¿Estarán a la altura de su legado?','\r',char(13)),'\n',char(10)),NULL,NULL,56,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000318764-da86dm.jpg','read',0,NULL,NULL,'2026-04-12 13:25:19','2026-04-12 16:14:28',182,NULL,'grapa','[{"name":"Tom Taylor","role":"Guion"},{"name":"Jay Kristoff","role":"Guion"},{"name":"C.S. Pacat","role":"Guion"},{"name":"Caspar Wijngaard","role":"Dibujo, Tinta, Color"},{"name":"Sean Izaakse","role":"Dibujo, Tinta"},{"name":"Michele Bandini","role":"Dibujo, Tinta"},{"name":"Antonio Fabela","role":"Color"},{"name":"Romulo Fajardo Jr.","role":"Color"},{"name":"Wayne Reynolds","role":"Dibujo, Tinta, Color"}]');
