INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1483,'El Día más Brillante #4','El Día más Brillante',4,NULL,'978-8-468-40039-6',NULL,'Geoff Johns','Ivan Reis',NULL,NULL,'Planeta Cómic / ECC Ediciones',NULL,'2011-04-01',NULL,NULL,replace('Edición original: Brightest Day núms. 5 y 6 USA\rFirestorm lucha con la creciente inestabilidad de sus poderes, lo que podría llevar a una catástrofe nuclear. Aquaman y Mera intentan controlar las criaturas del mar negro que han comenzado a atacar a los humanos. Hawkman y Hawkgirl siguen investigando el misterio detrás de su reencarnación, enfrentando a un grupo de guerreros en Hawkworld. Mientras tanto, Deadman sigue su búsqueda, pero la Luz Blanca le da pocas pistas sobre su verdadero propósito.','\r',char(13)),NULL,NULL,48,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000477910-rnr2z5.jpg','read',0,NULL,NULL,'2026-04-12 13:27:58','2026-04-12 16:14:28',185,NULL,'Grapa','[{"name":"Geoff Johns","role":"Guion"},{"name":"Peter J. Tomasi","role":"Guion"},{"name":"Ivan Reis","role":"Dibujo, Tinta"},{"name":"Ardian Syaf","role":"Dibujo"},{"name":"Joe Prado","role":"Dibujo"},{"name":"Patrick Gleason","role":"Dibujo"},{"name":"Scott Clark","role":"Dibujo"},{"name":"Vicente Cifuentes","role":"Tinta"},{"name":"Dave Beaty","role":"Tinta"},{"name":"Mark Irwin","role":"Tinta"},{"name":"Christian Alamy","role":"Tinta"},{"name":"Aspen MLT","role":"Color"},{"name":"Peter Steigerwald","role":"Color"},{"name":"John Starr","role":"Color"},{"name":"Chuck Pires","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1484,'El Día más Brillante #5','El Día más Brillante',5,NULL,'978-8-468-40040-2',NULL,'Geoff Johns','Patrick Gleason',NULL,NULL,'Planeta Cómic / ECC Ediciones',NULL,'2011-05-01',NULL,NULL,replace('Edición original: Brightest Day núms. 7 y 8 USA\rHawkman y Hawkgirl son transportados a Hawkworld, donde enfrentan a sus antiguos enemigos, incluidos los Manhawks, en su búsqueda de la Fuente de la Eternidad, que podría liberarles de su ciclo de reencarnación. Mientras tanto, J','\r',char(13)),NULL,NULL,48,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000479965-1d1115.jpg','read',0,NULL,NULL,'2026-04-12 13:28:00','2026-04-12 16:14:20',185,NULL,'Grapa','[{"name":"Geoff Johns","role":"Guion"},{"name":"Peter J. Tomasi","role":"Guion"},{"name":"Patrick Gleason","role":"Dibujo"},{"name":"Ivan Reis","role":"Dibujo, Tinta"},{"name":"Ardian Syaf","role":"Dibujo"},{"name":"Scott Clark","role":"Dibujo"},{"name":"Joe Prado","role":"Dibujo"},{"name":"Francis Manapul","role":"Dibujo, Tinta"},{"name":"Mark Bagley","role":"Dibujo"},{"name":"Mike Mayhew","role":"Dibujo, Tinta"},{"name":"Aaron Lopresti","role":"Dibujo"},{"name":"Vicente Cifuentes","role":"Tinta"},{"name":"Dave Beaty","role":"Tinta"},{"name":"Mark Irwin","role":"Tinta"},{"name":"Rob Hunter","role":"Tinta"},{"name":"Matthew Ryan","role":"Tinta"},{"name":"Rebecca Buchman","role":"Tinta"},{"name":"Peter Steigerwald","role":"Color"},{"name":"Aspen MLT","role":"Color"},{"name":"John Starr","role":"Color"},{"name":"David Finch","role":"Dibujo"},{"name":"Scott Williams","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1485,'El Día más Brillante #6','El Día más Brillante',6,NULL,'978-8-468-40041-9',NULL,'Geoff Johns','Scott Clark',NULL,NULL,'Planeta Cómic / ECC Ediciones',NULL,'2011-06-01',NULL,NULL,replace(replace('Edición original: Brightest Day núms. 9 y 10 USA\r\nAquaman enfrenta su miedo al agua mientras lucha contra Black Manta, quien sigue siendo una amenaza para él y Mera. Deadman continúa su búsqueda, guiado por la Luz Blanca, y se encuentra con Hawkman y Hawkgirl, quienes están en medio de su propia misión para romper la maldición que los ha perseguido a través de múltiples vidas. Mientras tanto, J','\r',char(13)),'\n',char(10)),NULL,NULL,48,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000481968-oyziza.jpg','read',0,NULL,NULL,'2026-04-12 13:28:03','2026-04-12 16:14:20',185,NULL,'Grapa','[{"name":"Geoff Johns","role":"Guion"},{"name":"Peter J. Tomasi","role":"Guion"},{"name":"Scott Clark","role":"Dibujo"},{"name":"Ivan Reis","role":"Dibujo, Tinta"},{"name":"Joe Prado","role":"Dibujo"},{"name":"Patrick Gleason","role":"Dibujo"},{"name":"Rebecca Buchman","role":"Tinta"},{"name":"Keith Champagne","role":"Tinta"},{"name":"Tom Nguyen","role":"Tinta"},{"name":"Oclair Albert","role":"Tinta"},{"name":"Dave Beaty","role":"Tinta"},{"name":"Aspen MLT","role":"Color"},{"name":"Peter Steigerwald","role":"Color"},{"name":"John Starr","role":"Color"},{"name":"David Finch","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1486,'El Día más Brillante #7','El Día más Brillante',7,NULL,'978-8-468-40042-6',NULL,'Geoff Johns','Scott Clark',NULL,NULL,'Planeta Cómic / ECC Ediciones',NULL,'2011-07-01',NULL,NULL,replace(replace('Edición original: Brightest Day núms. 11 y 12 USA\r\nVarios de los héroes resucitados continúan enfrentando los desafíos impuestos por la Luz Blanca. Deadman y Paloma buscan respuestas sobre su misión, mientras que Aquaman lucha por controlar sus nuevas habilidades y se enfrenta a la difícil relación con Mera. Firestorm descubre un peligro inminente vinculado a su existencia, lo que podría amenazar la estabilidad del universo. J','\r',char(13)),'\n',char(10)),NULL,NULL,48,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000484539-vnbx6c.jpg','read',0,NULL,NULL,'2026-04-12 13:28:05','2026-04-12 16:14:20',185,NULL,'Grapa','[{"name":"Geoff Johns","role":"Guion"},{"name":"Peter J. Tomasi","role":"Guion"},{"name":"Scott Clark","role":"Dibujo"},{"name":"Patrick Gleason","role":"Dibujo, Tinta"},{"name":"Ivan Reis","role":"Dibujo"},{"name":"Joe Prado","role":"Dibujo"},{"name":"Dave Beaty","role":"Tinta"},{"name":"Oclair Albert","role":"Tinta"},{"name":"Keith Champagne","role":"Tinta"},{"name":"Tom Nguyen","role":"Tinta"},{"name":"Mark Irwin","role":"Tinta"},{"name":"Rebecca Buchman","role":"Tinta"},{"name":"Mick Gray","role":"Tinta"},{"name":"Christian Alamy","role":"Tinta"},{"name":"Aspen MLT","role":"Color"},{"name":"Peter Steigerwald","role":"Color"},{"name":"Beth Sotelo","role":"Color"},{"name":"John Starr","role":"Color"},{"name":"David Finch","role":"Dibujo, Tinta, Color"}]');
