INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1493,'El Día Mas Brillante. En busca de La Cosa Del Pantano','El Día Mas Brillante. En busca de La Cosa Del Pantano',NULL,NULL,'978-8-415-52003-0',NULL,'Jonathan Vankin','Marco Castiello',NULL,NULL,'ECC Ediciones',NULL,'2012-02-01',NULL,NULL,'Un cómic de Jonathan Vankin, Marco Castiello, Renato Arlem.Publicado por ECC Ediciones',NULL,NULL,64,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000514250-i8q8r4.jpg','read',0,NULL,NULL,'2026-04-12 13:28:36','2026-04-12 16:14:20',NULL,23.95,'Grapa','[{"name":"Jonathan Vankin","role":""},{"name":"Marco Castiello","role":""},{"name":"Renato Arlem","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1494,'Batman (2012-2024) #1','Batman (2012-2024)',1,NULL,'978-8-415-52057-3',NULL,'Scott Snyder','Greg Capullo',NULL,NULL,'ECC Ediciones',NULL,'2012-05-01',NULL,NULL,replace(replace('Recopila Batman (Volume 2) #1-2 USA \r\n&quot;Barry Allen despertó en un mundo que apenas reconocía: desprovisto de poderes y ante la brutal contienda que enfrentaba a atlantes y amazonas, buscó recuperar su conexión con la Fuerza de la Velocidad. Ya como Flash, en su empeño por restablecer la normalidad contó con la colaboración de Thomas Wayne, superviviente de la noche que dio nombre al Callejón del Crimen de Gotham; fatídico instante en el que asesinaron al joven Bruce y comenzó a perder a su esposa Martha. Convertido en Batman, Thomas contribuyó de forma decisiva a derrotar a Eobard Thawne, empeñado en destrozar la vida de un Barry que, tras asumir un doloroso sacrificio, impulsó la transición hacia una realidad en la que Bruce Wayne vuelve a portar el Manto del Murciélago…&quot;\r\nHistorias:\r\nTruco de cuchillos\r\nConfianza en caída libre','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000644370-kcbv59.jpg','read',0,NULL,NULL,'2026-04-12 13:30:49','2026-04-12 16:14:20',186,24.95,'grapa','[{"name":"Greg Capullo","role":"Dibujo"},{"name":"Scott Snyder","role":"Guion"},{"name":"Jonathan Glapion","role":"Tinta"},{"name":"FCO Plascencia","role":"Color"},{"name":"Jim Lee","role":"Dibujo"},{"name":"Scott Williams","role":"Tinta"},{"name":"Alex Sinclair","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1495,'Batman (2012-2024) #2','Batman (2012-2024)',2,NULL,'978-8-415-52086-3',NULL,'Tony S. Daniel','Tony S. Daniel',NULL,NULL,'ECC Ediciones',NULL,'2012-06-01',NULL,NULL,replace(replace('Recopila Detective Comics #1-2 USA\r\n&quot;Batman persigue por enésima vez al Joker, que parece haber emprendido una oleada de asesinatos especialmente truculentos. La hija de una de sus víctimas, una niña pequeña, se va a convertir en un elemento clave de los primeros episodios de la nueva serie original Detective Comics que ECC Ediciones empieza a publicar este mismo mes en Batman núm. 2. Escrita y dibujada por Tony S. Daniel, que ya lleva cierto tiempo vinculado a la franquicia del Caballero Oscuro, esta aventura va a servir para presentar a un nuevo adversario que seguro que no deja indiferente a nadie. Pero para el protagonista no van a ser solo penas, ya que está a punto de conocer a la periodista Charlotte Rivers, la bella fémina que podría convertirse en su próxima novia.&quot;\r\nHistorias:\r\nBatman en Detective comics\r\nEl final de los juegos','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000678250-rh16u6.jpg','read',0,NULL,NULL,'2026-04-12 13:31:18','2026-04-12 16:14:20',186,NULL,'Grapa','[{"name":"Tony S. Daniel","role":"Guion, Dibujo"},{"name":"Ryan Winn","role":"Tinta"},{"name":"Sandu Florea","role":"Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1496,'Batman (2012-2024) #3','Batman (2012-2024)',3,NULL,'978-8-415-62801-9',NULL,'Tony S. Daniel','Tony S. Daniel',NULL,NULL,'ECC Ediciones',NULL,'2012-07-01',NULL,NULL,replace(replace('Recopila Detective Comics #3-4 USA\r\nNota: Detective Comics #5-12 USA (y Annual #1) se publicaron por ECC en el tomo Batman: Tácticas Intimidatorias.\r\n&quot;Batman detuvo al Joker, pero un nuevo villano, el Muñequero, mantiene en jaque a toda la policía de Gotham. Lo más sorprendente es que, al parecer, fue capaz de infiltrarse en el Psiquiátrico de Arkham y liberar al Joker tras arrancarle literalmente la cara para dejar atrás solo el pellejo de un rostro ensangrentado. Ahora Batman y Gordon deben enfrentarse a sus mortíferos secuaces con la intención de salvar a una niña, Olivia, y todo indica que las cosas no terminarán bien para el comisario...&quot;\r\nHistorias:\r\nSangre fría\r\nEl numero principal','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000680852-jx28w3.jpg','read',0,NULL,NULL,'2026-04-12 13:31:22','2026-04-12 16:14:20',186,NULL,'grapa','[{"name":"Tony S. Daniel","role":"Guion, Dibujo"},{"name":"Sandu Florea","role":"Tinta"},{"name":"Ryan Winn","role":"Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1497,'Batman (2012-2024) #4','Batman (2012-2024)',4,NULL,'978-8-415-62835-4',NULL,'Greg Capullo','Scott Snyder',NULL,NULL,'ECC Ediciones',NULL,'2012-08-01',NULL,NULL,replace(replace('Recopila Batman #3-4 USA\r\n&quot;Tras neutralizar a buena parte de sus enemigos y utilizar sus vastos recursos económicos para –como Bruce Wayne– anunciar un ambicioso plan que revitalice su ciudad, Batman investigó un asesinato aparentemente relacionado con una leyenda de Gotham: el Tribunal de los Búhos. Desechadas las pistas que señalaban a Nightwing como autor del violento crimen, Bruce se reunió en la vieja Torre Wayne con Lincoln March, candidato a la alcaldía; pero dicho encuentro se vio interrumpido por un letal enemigo, demostrando que en ocasiones las leyendas resultan ser aterradoramente reales…&quot;\r\nHistorias:\r\nLa hora numero 13\r\nFrente al tribunal','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000683205-pcstif.jpg','read',0,NULL,NULL,'2026-04-12 13:31:24','2026-04-12 16:14:20',186,NULL,'grapa','[{"name":"Greg Capullo","role":""},{"name":"Scott Snyder","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1498,'Batman (2012-2024) #5','Batman (2012-2024)',5,NULL,'978-8-415-62847-7',NULL,'Greg Capullo','Scott Snyder',NULL,NULL,'ECC Ediciones',NULL,'2012-09-01',NULL,NULL,replace(replace('Recopila Batman #5-6 USA\r\n&quot;Se puede sobrevivir a varios días de cautiverio en un laberinto? Ni siquiera Batman es capaz de soportar semejante tormento, con lo cual no es de extrañar que rememore el momento que marcó su vida para siempre. Es por esto por lo que, en plena vorágine alucinógena, el Caballero Oscuro recuerda a Thomas y Martha Wayne, sus padres, los mismos que murieron asesinados en un callejón delante de él. Ahora, es posible que su recuerdo sea lo único que lo aferre a la vida para poder escapar del Tribunal de los Búhos...&quot;\r\nHistorias:\r\nFrente al tribunal\r\nBajo el cristal','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000685446-s9qadx.jpg','read',0,NULL,NULL,'2026-04-12 13:31:26','2026-04-12 16:14:20',186,NULL,'grapa','[{"name":"Greg Capullo","role":""},{"name":"Scott Snyder","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1499,'Batman (2012-2024) #6','Batman (2012-2024)',6,NULL,'978-8-415-62863-7',NULL,'Scott Snyder','Greg Capullo',NULL,NULL,'ECC Ediciones',NULL,'2012-10-01',NULL,NULL,replace(replace('Recopila Batman #7-8 USA (marzo-abril/2012)\r\nHistorias: &quot;¡Las garras atacan!&quot;, &quot;Asalto a la mansión Wayne&quot;, &quot;La llamada&quot;\r\n&quot;Bruce Wayne logró sobrevivir a una trampa tendida por el Tribunal de los Búhos, para posteriormente explicar a Dick Grayson sus dudas acerca de la existencia de la misteriosa organización, a la que investigó durante su infancia por considerarla de algún modo relacionada con el asesinato de sus padres. Tras argumentar su teoría, Batman siguió una pista que le condujo hasta las alcantarillas de Gotham City, donde fue noqueado por la Garra, que trasladó su cuerpo inconsciente hasta un laberinto…&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000687286-38dt4a.jpg','read',0,NULL,NULL,'2026-04-12 13:31:28','2026-04-12 16:14:20',186,NULL,'grapa','[{"name":"Greg Capullo","role":"Dibujo"},{"name":"Scott Snyder","role":"Guion"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1500,'Batman (2012-2024) #7','Batman (2012-2024)',7,NULL,'978-8-415-62881-1',NULL,'Andy Clarke','Ardian Syaf',NULL,NULL,'ECC Ediciones',NULL,'2012-11-01',NULL,NULL,replace(replace('Recopila Batwing #9, Batgirl #9 y Batman and Robin #9 USA\r\nRecopila tres &quot;tie-in&quot; de la historia que se desarrolla en la serie de Batman. Durante un mes en EEUU, todas las series de la &quot;familia&quot; de Batman se enfrentaron a diferentes Garras enviadas por el Tribunal de los Búhos.\r\nIncluye las historias &quot;En la línea de fuego&quot;, &quot;Robin oye ulular&quot; y  &quot;Se te ha declarado indigno&quot;.\r\nDescripción de la editorial: &quot;El Tribunal de los Búhos decidió abandonar las sombras del anonimato no solo para derrotar al Hombre Murciélago, sino también para reclamar un dominio sobre la ciudad que dicen merecer. Para ello, orquestaron un ataque a la Mansión Wayne, mientras un auténtico ejército de Garras se desplegaba por las calles de Gotham, con la intención de acabar con la vida de hasta 40 individuos que, con su liderazgo y personalidad, dan forma a la ciudad. Una amenaza que requerirá la intervención de los más cercanos colaboradores del Caballero Oscuro…&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000689415-ceyyj6.jpg','read',0,NULL,NULL,'2026-04-12 13:31:30','2026-04-12 16:14:20',186,NULL,'Grapa','[{"name":"Andy Clarke","role":""},{"name":"Ardian Syaf","role":""},{"name":"Lee Garbett","role":""},{"name":"Marcus To","role":""},{"name":"Gail Simone","role":""},{"name":"Judd Winick","role":""},{"name":"Peter J. Tomasi","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1501,'Batman (2012-2024) #8','Batman (2012-2024)',8,NULL,'978-8-415-62898-9',NULL,'Andrés Guinaldo','Kyle Higgins',NULL,NULL,'ECC Ediciones',NULL,'2012-12-01',NULL,NULL,replace(replace('Recopila Birds of prey #9, Nightwing #9 y Detective comics #9 USA.\r\nRecopila tres &quot;tie-in&quot; de la historia que se desarrolla en la serie de Batman. Durante un mes en EEUU, todas las series de la &quot;familia&quot; de Batman se enfrentaron a diferentes Garras enviadas por el Tribunal de los Búhos.\r\nHistorias:\r\nAl estilo de las Bandas\r\nEl hijo gris\r\nLos búhos toman Arkham\r\nEl Tribunal de los búhos desplegó todo su poder sobre Gotham, dirigiendo a casi medio centenar de Garras contra objetivos realmente sensibles: aquellas personalidades que, por su poder, influencia o liderazgo “dan forma a la ciudad”. Ante tal tesitura, Batman optó por pedir ayuda a sus más cercanos colaboradores, de forma que Batwing, Robin y Batgirl neutralizaron la amenaza que representaban tres de los peculiares soldados que integran el ejército de la misteriosa organización. Primeras batallas dentro de la guerra que deberán librar, con la integridad de su ciudad en juego.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000691135-cagdrp.jpg','read',0,NULL,NULL,'2026-04-12 13:31:32','2026-04-12 16:14:20',186,NULL,'grapa','[{"name":"Andrés Guinaldo","role":""},{"name":"Kyle Higgins","role":""},{"name":"Tony S. Daniel","role":""},{"name":"Travel Foreman","role":""},{"name":"Duane Swierczynski","role":""},{"name":"Eddy Barrows","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1502,'Batman (2012-2024) #9','Batman (2012-2024)',9,NULL,'978-8-415-74828-1',NULL,'Greg Capullo','David Finch',NULL,NULL,'ECC Ediciones',NULL,'2013-01-01',NULL,NULL,replace(replace('Recopila Red Hood and the outlaws #9, Batman: The dark knight #9 y Batman #9\r\nConcluye la inclusión de &quot;tie-ins&quot; de &quot;La noche de los búhos&quot; y se retoma la publicación de la serie Batman. \r\nTribunal de los Búhos.\r\nHistorias:\r\n¿Quién eres tu...? ¿...uh? ¿uh?\r\nLa noche de los búhos\r\nYa no puedo permitirme la derrota\r\nUna legión de Garras, asesinos del Tribunal de los Búhos que han despertado de su letargo, se despliega por Gotham para liquidar a las principales personalidades de la ciudad y destruir cuanto Batman representa. Ahora el Hombre Murciélago y sus aliados, tras la llamada de emergencia de Alfred, deben impedirlo. Batwing, Robin, Batgirl, las Aves de Presa y Nightwing ya han logrado detener a algunas de las Garras, pero... ¿lo harán también Capucha Roja y los Forajidos si han de proteger a Mr. Frío?','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000694234-u9ta6h.jpg','read',0,NULL,NULL,'2026-04-12 13:31:34','2026-04-12 16:14:20',186,NULL,'grapa','[{"name":"Greg Capullo","role":""},{"name":"David Finch","role":""},{"name":"Kenneth Rocafort","role":""},{"name":"Judd Winick","role":""},{"name":"Scott Lobdell","role":""},{"name":"Scott Snyder","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1503,'Batman (2012-2024) #10','Batman (2012-2024)',10,NULL,'978-8-415-74852-6',NULL,'Scott Snyder','Greg Capullo',NULL,NULL,'ECC Ediciones',NULL,'2013-02-01',NULL,NULL,replace(replace('Recopila Batman #10 y Batman Annual #1 USA\r\nHistorias:\r\nPrimeras nieves\r\nAsalto al tribunal\r\n&quot;Tras derrotar a un pequeño ejército de Garras que allanó la Mansión Wayne, Batman trató de salvar a Lincoln March: candidato a la alcaldía de Gotham City que, pese a los esfuerzos del Hombre Murciélago, murió a manos de un secuaz del Tribunal de los Búhos. De forma paralela, los Forajidos liderados por Capucha Roja lograron proteger a un Mr. Frío que, pese a haber contribuido de forma decisiva a que los planes de la misteriosa organización llegaran a buen término, también fue señalado como objetivo.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000696084-8apnl7.jpg','read',0,NULL,NULL,'2026-04-12 13:31:36','2026-04-12 16:14:20',186,NULL,'grapa','[{"name":"Greg Capullo","role":"Dibujo"},{"name":"Jason Fabok","role":"Dibujo"},{"name":"Scott Snyder","role":"Guion"},{"name":"James Tynion IV","role":"Guion"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1504,'Batman (2012-2024) #11','Batman (2012-2024)',11,NULL,'978-8-415-74876-2',NULL,'Scott Snyder','Becky Cloonan',NULL,NULL,'ECC Ediciones',NULL,'2013-03-01',NULL,NULL,replace(replace('Recopila Batman #11 y 12 USA (julio-agosto/2012)\r\nEn Batman #11 concluye el largo arco argumental que se ha desarrollado desde el #1, &quot;The court of Owls&quot;. Batman #12 (con Becky Cloonan como dibujante invitada) es un capítulo a modo de epílogo de dicha historia y que enlaza con la siguiente (con el Joker como antagonista).\r\nCon las historias &quot;Guardian de mi hermano&quot; y &quot;El fantasma de la maquina&quot;.\r\nDescripción de la editorial: &quot;Al límite de sus fuerzas y obligado a echar mano de todos sus recursos para neutralizar la amenaza que representaba el Tribunal de los Búhos, Batman se encaminó hacia el Orfanato de Willowwood: institución abandonada donde descubrió un sorprendente misterio. Una revelación que obligará al Hombre Murciélago a conciliar sus recuerdos familiares con la necesidad de sobreponerse para derrotar a su inesperado enemigo...&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000698150-cdkipu.jpg','read',0,NULL,NULL,'2026-04-12 13:31:39','2026-04-12 16:14:20',186,NULL,'grapa','[{"name":"Becky Cloonan","role":"Dibujo"},{"name":"Andy Clarke","role":""},{"name":"James Tynion IV","role":""},{"name":"Scott Snyder","role":"Guion"},{"name":"Greg Capullo","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1505,'Batman (2012-2024) #12','Batman (2012-2024)',12,NULL,'978-8-415-84400-6',NULL,'Scott Snyder','Greg Capullo',NULL,NULL,'ECC Ediciones',NULL,'2013-04-01',NULL,NULL,replace(replace('Recopila Batman #13 y Detective comics #13 USA.\r\nBatman #13 USA es el capítulo 1 (de 5) del arco argumental &quot;Death of the family&quot;. \r\n&quot;Despojado de su rostro a manos del Muñequero, el Joker desapareció de Gotham el tiempo sufi ciente para recuperarse y tramar la que bien podría ser su venganza defi nitiva. Meses más tarde, y cuando Batman apenas ha asimilado la relación existente entre el misterioso Tribunal de los Búhos y su propia familia, tendrá que afrontar el regreso del Príncipe\r\nPayaso del Crimen: el más letal e imprevisible de sus enemigos, dispuesto a poner en jaque al Hombre Murciélago... y a sus aliados más cercanos.&quot;\r\nHistorias:\r\nToc, Toc\r\nBurla\r\nEsquivar y cubrirse\r\nTest de inteligencia','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000700417-2ul45b.jpg','read',0,NULL,NULL,'2026-04-12 13:31:41','2026-04-12 16:14:20',186,NULL,'Grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Greg Capullo","role":"Dibujo"},{"name":"Jonathan Glapion","role":"Tinta"},{"name":"FCO Plascencia","role":"Color"},{"name":"James Tynion IV","role":"Guion"},{"name":"Jock","role":"Dibujo, Tinta, Color"},{"name":"John Layman","role":"Guion"},{"name":"Jason Fabok","role":"Dibujo, Tinta"},{"name":"Jeromy Cox","role":"Color"},{"name":"Andy Clarke","role":"Dibujo, Tinta"},{"name":"Blond","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1506,'Batman (2012-2024) #13','Batman (2012-2024)',13,NULL,'978-8-415-84432-7',NULL,'Scott Snyder','Greg Capullo',NULL,NULL,'ECC Ediciones',NULL,'2013-05-01',NULL,NULL,replace(replace('Recopila Batman #14 y Detective comics #14 USA.\r\nBatman #14 USA es el capítulo 2 (de 5) del arco argumental &quot;Death of the family&quot;. \r\nHistorias:\r\nGracia en los huesos\r\nHombres devotos\r\nSelección natural\r\nSemillas y tierra\r\nAusente desde que se sometió voluntariamente a una de las aterradoras intervenciones del Muñequero, el Joker regresó a Gotham City; no solo con la intención de recuperar su propio rostro, sino también de perpetrar la venganza definitiva contra el Hombre Murciélago.\r\nDe forma paralela, Oswald Cobblepot –más conocido como el Pingüino– intensificó su rivalidad filantrópica con el álter ego de Batman, buscando ganarse la admiración de sus conciudadanos como un paso más en la consecución de sus ambiciones de poder.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000702857-fgosuv.jpg','read',0,NULL,NULL,'2026-04-12 13:31:44','2026-04-12 16:14:20',186,NULL,'Grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Greg Capullo","role":"Dibujo"},{"name":"Jonathan Glapion","role":"Tinta"},{"name":"FCO Plascencia","role":"Color"},{"name":"James Tynion IV","role":"Guion"},{"name":"Jock","role":"Dibujo, Tinta"},{"name":"David Baron","role":"Color"},{"name":"John Layman","role":"Guion"},{"name":"Jason Fabok","role":"Dibujo, Tinta"},{"name":"Jeromy Cox","role":"Color"},{"name":"Andy Clarke","role":"Dibujo, Tinta"},{"name":"Blond","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1507,'Batman (2012-2024) #14','Batman (2012-2024)',14,NULL,'978-8-415-84456-3',NULL,'Scott Snyder','Greg Capullo',NULL,NULL,'ECC Ediciones',NULL,'2013-06-01',NULL,NULL,replace(replace('Recopila Batman #15 y Detective comics #15 USA.\r\nBatman #15 USA es el capítulo 3 (de 5) del arco argumental &quot;Death of the family&quot;. \r\nHistorias:\r\nPero aquí viene lo mas divertido\r\nLuz roja, luz verde\r\nEl cieno eterno\r\nAmor floreciente\r\n&quot;Tras zafarse de la trampa que el Príncipe Payaso del Crimen le tendió en Industrias Químicas ACE, Batman regresó a la Mansión Wayne para descubrir que su letal enemigo había raptado a Alfred. Con James Gordon hospitalizado, y decidido a limitar la implicación de la batfamilia, el Caballero Oscuro se dirigió hacia el siguiente escenario donde el Joker continuó con la macabra reinterpretación de crímenes del pasado. Más desquiciado y vengativo que nunca, el Arlequín del Odio dice ahora conocer el secreto celosamente guardado por el Hombre Murciélago y sus aliados...&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000705197-vyxjg0.jpg','read',0,NULL,NULL,'2026-04-12 13:31:46','2026-04-12 16:14:20',186,NULL,'Grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Greg Capullo","role":"Dibujo"},{"name":"Jonathan Glapion","role":"Tinta"},{"name":"FCO Plascencia","role":"Color"},{"name":"James Tynion IV","role":"Guion"},{"name":"Jock","role":"Dibujo, Tinta"},{"name":"David Baron","role":"Color"},{"name":"John Layman","role":"Guion"},{"name":"Jason Fabok","role":"Dibujo, Tinta"},{"name":"Jeromy Cox","role":"Color"},{"name":"Andy Clarke","role":"Dibujo, Tinta"},{"name":"Blond","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1508,'Batman (2012-2024) #15','Batman (2012-2024)',15,NULL,'978-8-415-84480-8',NULL,'Scott Snyder','Jock',NULL,NULL,'ECC Ediciones',NULL,'2013-07-01',NULL,NULL,replace(replace('Recopila Batman #16 y Detective comics #16 USA.\r\nBatman #16 USA es el capítulo 4 (de 5) del arco argumental &quot;Death of the family&quot;. \r\nHistorias:\r\nCastillo de naipes\r\nJuicio\r\nNada mas que sonrisas\r\nJerarquía\r\n&quot;Tras valerse de la ayuda de sus secuaces para neutralizar un contundente despliegue policial, el Joker logró inocular a Batman una toxina paralizante: eficaz e inesperada artimaña que le permitió huir. Ya en la Mansión Wayne, Bruce confesó a sus colaboradores más cercanos –Nightwing, Red Robin, Capucha Roja, Robin y Batgirl– un episodio del pasado que bien podría estar relacionado con el secuestro de Alfred Pennyworth. Sin tiempo para gestionar las posibles consecuencias de su revelación, el Hombre Murciélago centró todos sus esfuerzos en seguir su única pista que, mediando una expeditiva investigación, le condujo al Hospital Psiquiátrico de Arkham...&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000707508-ikvtkd.jpg','read',0,NULL,NULL,'2026-04-12 13:31:48','2026-04-12 16:14:20',186,NULL,'Grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Greg Capullo","role":"Guion"},{"name":"Jonathan Glapion","role":"Tinta"},{"name":"FCO Plascencia","role":"Color"},{"name":"James Tynion IV","role":"Guion"},{"name":"Jock","role":"Dibujo, Tinta"},{"name":"David Baron","role":"Color"},{"name":"John Layman","role":"Guion"},{"name":"Jason Fabok","role":"Dibujo, Tinta"},{"name":"Jeromy Cox","role":"Color"},{"name":"Andy Clarke","role":"Dibujo, Tinta"},{"name":"Blond","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1509,'Batman (2012-2024) #16','Batman (2012-2024)',16,NULL,'978-8-415-92502-6',NULL,'Scott Snyder','Greg Capullo',NULL,NULL,'ECC Ediciones',NULL,'2013-08-01',NULL,NULL,replace(replace('Recopila Batman #17 y Detective comics #17 USA.\r\nBatman #17 USA es el capítulo 5 (de 5) del arco argumental &quot;Death of the family&quot;. \r\nHistorias:\r\nEl final del chiste\r\nEn busca de la felicidad\r\nOrdenes del medico\r\n&quot;Última entrega de &quot;La muerte de La familia&quot;, con la que Scott Snyder y Greg Capullo finalizan la intensa historia que ha representado el regreso del Joker. ¿hasta qué punto será literal el título de la saga? La respuesta, en las páginas de este cómic...\r\nEl Joker convirtió el Hospital Psiquiátrico de Arkham en una retorcida versión de una corte medieval: espectáculo de dudoso gusto protagonizado por guardias einternos de la institución, partícipes de un macabro recordatorio de anteriores enfrentamientos entre el Hombre Murciélago y el Príncipe Payaso del Crimen. Tras superar diferentes obstáculos, Batman fue obligado a ocupar el trono de tan desquiciado reino de locura: una silla eléctrica desde la que presenciará el resto de la aterradora velada, que bien podría resultar letal para el Caballero Oscuro y sus aliados más cercanos.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000709689-03e6vw.jpg','read',0,NULL,NULL,'2026-04-12 13:31:50','2026-04-12 16:14:20',186,NULL,'Grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Greg Capullo","role":"Dibujo"},{"name":"Jonathan Glapion","role":"Tinta"},{"name":"FCO Plascencia","role":"Color"},{"name":"John Layman","role":"Guion"},{"name":"Jason Fabok","role":"Dibujo, Tinta"},{"name":"Jeromy Cox","role":"Color"},{"name":"Andy Clarke","role":"Dibujo, Tinta"},{"name":"Blond","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1510,'Batman (2012-2024) #17','Batman (2012-2024)',17,NULL,'978-8-415-92524-8',NULL,'Scott Snyder','Andy Kubert',NULL,NULL,'ECC Ediciones',NULL,'2013-09-01',NULL,NULL,replace(replace('Recopila Batman #18 y Detective comics #18 USA\r\nBatman #18 USA es un capítulo con Andy Kubert como dibujante invitado, correspondiente al mes en que diferentes series de la familia de Batman publicaron un capítulo a modo de &quot;Requiem&quot; por la aparente muerte de Damian Wayne en Batman Inc.\r\nHistorias: &quot;Resolución&quot;, &quot;Regreso al hogar&quot; y &quot;Mr. Zsasz en un corte especial&quot;.\r\n&quot;Poco después de suscitar la desconfianza de los miembros de la bat-familia como consecuencia del retorcido plan del Joker, un Bruce Wayne alienado vio cómo se materializó de su peor miedo. Un trágico trance que el Hombre Murciélago afronta entregándose a su cruzada contra el crimen, que retoma desde la violencia y el sentimiento de culpa. En este preocupante contexto, reaparece una testaruda joven, aparentemente destinada a desempeñar un papel decisivo en el futuro de Gotham City...&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000712851-3q802m.jpg','read',0,NULL,NULL,'2026-04-12 13:31:53','2026-04-12 16:14:20',186,NULL,'Grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"James Tynion IV","role":"Guion"},{"name":"Andy Kubert","role":"Dibujo"},{"name":"Alex Maleev","role":"Dibujo, Tinta"},{"name":"Sandra Hope","role":"Tinta"},{"name":"Brad Anderson","role":"Color"},{"name":"Nathan Fairbairn","role":"Color"},{"name":"John Layman","role":"Guion"},{"name":"Jason Fabok","role":"Dibujo, Tinta"},{"name":"Jeromy Cox","role":"Color"},{"name":"Henrik Jonsson","role":"Dibujo"},{"name":"Sandu Florea","role":"Tinta"},{"name":"Blond","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1511,'Batman (2012-2024) #18','Batman (2012-2024)',18,NULL,'978-8-415-92555-2',NULL,'Scott Snyder','Greg Capullo',NULL,NULL,'ECC Ediciones',NULL,'2013-10-01',NULL,NULL,replace(replace('Recopila Batman #19 y Detective comics #19 USA\r\nBatman #19 USA es el capítulo 1 (de 2) de la historia &quot;Nowhere Man&quot;.\r\n&quot;Un Batman apesadumbrado encontró la inesperada ayuda de Harper Row, empeñada en que el héroe se recompusiera para continuar ejerciendo su papel como protector de Gotham. Todavía afectado por la irreparable pérdida sufrida, Batman intercedió en la lucha de poder entre Oswald Cobblepot e Ignatius Ogilvy. Pero sin apenas solución de continuidad, nuevos problemas acechan en el horizonte: la proliferación de Manbats en un barrio de la ciudad, ¿y la comisión del atraco a un banco por parte de Bruce Wayne?&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000715288-z54w25.jpg','read',0,NULL,NULL,'2026-04-12 13:31:56','2026-04-12 16:14:20',186,NULL,'Grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Greg Capullo","role":"Dibujo"},{"name":"Danny Miki","role":"Tinta"},{"name":"FCO Plascencia","role":"Color"},{"name":"James Tynion IV","role":"Guion"},{"name":"Alex Maleev","role":"Dibujo, Tinta"},{"name":"Brad Anderson","role":"Color"},{"name":"John Layman","role":"Guion"},{"name":"Jason Fabok","role":"Dibujo, Tinta"},{"name":"Jeromy Cox","role":"Color"},{"name":"Andy Clarke","role":"Dibujo, Tinta"},{"name":"Blond","role":"Color"},{"name":"Mikel Janin","role":"Dibujo, Tinta"},{"name":"Dave McCaig","role":"Color"},{"name":"Henrik Jonsson","role":"Dibujo"},{"name":"Sandu Florea","role":"Tinta"},{"name":"Juancho Vélez","role":"Color"},{"name":"Jason Masters","role":"Dibujo, Tinta"},{"name":"Brett Smith","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1512,'Batman (2012-2024) #19','Batman (2012-2024)',19,NULL,'978-8-415-92579-8',NULL,'Scott Snyder','Greg Capullo',NULL,NULL,'ECC Ediciones',NULL,'2013-11-01',NULL,NULL,replace(replace('Recopila Batman #20 y Detective comics #20 USA\r\nBatman #20 USA es el capítulo 2 (de 2) de la historia &quot;Nowhere Man&quot;.\r\n&quot;Batman comenzó a investigar el sospechoso suicidio aparentemente cometido por Brian Wade, estrecho colaborador de la Iniciativa por Gotham. Pero sus pesquisas no tardaron en conducirle hacia Basil Karlo, cambiaformas más conocido como Clayface cuyos planes parecen pasar por usurpar la identidad de un prominente ciudadano... ¡el mismísimo Bruce Wayne! Problemática situación, a la que se suma la disputa por los bajos fondos mantenida entre Oswald Cobblepot e Ignatius Ogilvy, autoproclamado Pingüino Emperador.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000717384-rlu252.jpg','read',0,NULL,NULL,'2026-04-12 13:31:58','2026-04-12 16:14:20',186,NULL,'Grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Greg Capullo","role":"Dibujo"},{"name":"Danny Miki","role":"Tinta"},{"name":"FCO Plascencia","role":"Color"},{"name":"James Tynion IV","role":"Guion"},{"name":"Alex Maleev","role":"Dibujo, Tinta"},{"name":"Nathan Fairbairn","role":"Color"},{"name":"John Layman","role":"Guion"},{"name":"Jason Fabok","role":"Dibujo, Tinta"},{"name":"Jeromy Cox","role":"Color"},{"name":"Andy Clarke","role":"Dibujo, Tinta"},{"name":"Blond","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1513,'Batman (2012-2024) #20','Batman (2012-2024)',20,NULL,'978-8-415-99003-1',NULL,'James Tynion IV','John Layman',NULL,NULL,'ECC Ediciones',NULL,'2013-12-01',NULL,NULL,replace(replace('Recopila Batman #21 y Detective comics #21 USA\r\nBatman #21 USA es el capítulo 1 (de 3) del arco argumental &quot;Zero Year: Secret City&quot;. \r\n&quot;El Hombre Murciélago logró derrotar al cambiaformas conocido como Clayface: pseudónimo del actor fracasado Basil Karlo, que a punto estuvo de desvelar la identidad secreta de Batman. Tras poner al peligroso villano en manos de la policía de Gotham City, Bruce Wayne pudo continuar el proceso de luto por el fallecimiento de su más fiel aliado. Momento de triste calma, aparentemente idóneo para remontarse seis años en el tiempo y rememorar el Origen de su carrera como justiciero...&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000718875-vfn8c4.jpg','read',0,NULL,NULL,'2026-04-12 13:31:59','2026-04-12 16:14:20',186,NULL,'Grapa','[{"name":"James Tynion IV","role":""},{"name":"John Layman","role":""},{"name":"Scott Snyder","role":""},{"name":"Andy Clarke","role":""},{"name":"Greg Capullo","role":""},{"name":"Rafael Albuquerque","role":""},{"name":"Scot Eaton","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1514,'Batman (2012-2024) #21','Batman (2012-2024)',21,NULL,'978-8-415-99035-2',NULL,'Scott Snyder','John Layman',NULL,NULL,'ECC Ediciones',NULL,'2013-12-28',NULL,NULL,replace('Recopila Batman #22 y Detective comics #22 USA\rBatman #22 USA es el capítulo 2 (de 3) del arco argumental &quot;Zero Year: Secret City&quot;.\r&quot;Hace seis años, Bruce Wayne regresó a Gotham City para emprender su carrera como justiciero, decidido a evitar que cualquier otro inocente corriera la misma suerte que sus padres, aquella aciaga noche en el Callejón del Crimen. Centrado en el perfeccionamiento de las habilidades que le permitieran desarticular la banda de Capuchas Rojas, no previó cómo afectaría su reaparición a Empresas Wayne: un renovado emporio liderado por su tío Philip, quien se beneficia de los inquietantes consejos de Edward Nygma.&quot;','\r',char(13)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000720990-nz0o6p.jpg','read',0,NULL,NULL,'2026-04-12 13:32:02','2026-04-12 16:14:20',186,NULL,'Grapa','[{"name":"Scott Snyder","role":""},{"name":"John Layman","role":""},{"name":"James Tynion IV","role":""},{"name":"Greg Capullo","role":""},{"name":"Jason Fabok","role":""},{"name":"Rafael Albuquerque","role":""},{"name":"Andy Clarke","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1515,'Batman (2012-2024) #22','Batman (2012-2024)',22,NULL,'978-8-415-99065-9',NULL,'Derlis Santacruz','Greg Capullo',NULL,NULL,'ECC Ediciones',NULL,'2014-01-31',NULL,NULL,replace('Recopila Batman #23 USA y Detective comics Annual #2 USA \rBatman #23 USA es el capítulo 3 (de 3) del arco argumental &quot;Zero Year: Secret City&quot;.\r&quot;Frustrado su intento de derrotar a la Banda de los Capuchas Rojas, y enfrentado con Alfred por el modo de enfocar su guerra contra el crimen, Bruce Wayne se reunió en el Museo de Gotham con su tío, quien preparó una encerrona destinada a hacer público el regreso a la ciudad del heredero de Empresas Wayne. Tras abandonar el evento sorpresa, el álter ego de Batman tuvo un revelador encuentro con Edward Nygma, asesor de Philip Kane; apenas un preludio de la particular fiesta de bienvenida organizada por los enemigos de Bruce...&quot;','\r',char(13)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000723528-91o0q8.jpg','read',0,NULL,NULL,'2026-04-12 13:32:04','2026-04-12 16:14:20',186,NULL,'Grapa','[{"name":"Derlis Santacruz","role":""},{"name":"Greg Capullo","role":""},{"name":"Rafael Albuquerque","role":""},{"name":"Scot Eaton","role":""},{"name":"Szymon Kudranski","role":""},{"name":"James Tynion IV","role":""},{"name":"John Layman","role":""},{"name":"Joshua Williamson","role":""},{"name":"Scott Snyder","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1516,'Batman (2012-2024) #23','Batman (2012-2024)',23,NULL,'978-8-415-99098-7',NULL,'Scott Snyder','Wes Craig',NULL,NULL,'ECC Ediciones',NULL,'2014-02-28',NULL,NULL,replace('Recopila Batman Annual #2 USA\r&quot;Bruce sufrió una emboscada en su base de operaciones, situada en el Callejón del Crimen de Gotham City. Derrotado por la banda de Capuchas Rojas y gravemente herido, logró llegar a la Mansión Wayne, donde recibió las atenciones médicas de Alfred. Todavía convaleciente, experimentó un momento de revelación sobre su cruzada superheroica, reconciliándose con su herencia familiar. Pero ¿es posible que la presencia de Batman pueda causar daños colaterales? Ha llegado el momento de averiguarlo...&quot;','\r',char(13)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000726081-azvb7k.jpg','read',0,NULL,NULL,'2026-04-12 13:32:06','2026-04-12 16:14:20',186,NULL,'Grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Marguerite Bennett","role":"Guion"},{"name":"Wes Craig","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1517,'Batman (2012-2024) #24','Batman (2012-2024)',24,NULL,'978-8-416-07035-0',NULL,'James Tynion IV','Andy Clarke',NULL,NULL,'ECC Ediciones',NULL,'2014-03-31',NULL,NULL,replace(replace('Recopila Batman #24 y Detective Comics #23 USA\r\nBatman #24 USA es el capítulo 1 (de 5) del arco argumental &quot;Zero Year: Dark City&quot;.\r\n&quot;Tras ser derrotado en su propia base de operaciones por los Capuchas Rojas, Bruce logró llegar hasta la Mansión Wayne, donde recibió los cuidados de Alfred Pennyworth. Gravemente herido y albergando no pocas dudas sobre su cruzada contra el crimen, finalmente encontró en su legado familiar la inspiración y las fuerzas necesarias para retomar su misión. Justo a tiempo para intentar truncar los planes de la peligrosa banda criminal y de asistir a la presentación en público de un enigmático villano...&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000728009-on3j81.jpg','read',0,NULL,NULL,'2026-04-12 13:32:09','2026-04-12 16:14:20',186,NULL,'Grapa','[{"name":"James Tynion IV","role":"Guion"},{"name":"John Layman","role":"Guion"},{"name":"Scott Snyder","role":"Guion"},{"name":"Andy Clarke","role":"Dibujo"},{"name":"Greg Capullo","role":"Dibujo"},{"name":"Jason Fabok","role":"Dibujo"},{"name":"Rafael Albuquerque","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1518,'Batman (2012-2024) #25','Batman (2012-2024)',25,NULL,'978-8-416-07066-4',NULL,'Scott Snyder','John Layman',NULL,NULL,'ECC Ediciones',NULL,'2014-04-26',NULL,NULL,replace(replace('Recopila Batman #25, Detective Comics #24 y una historia corta de Batman #24 USA.\r\nBatman #25 USA es el capítulo 2 (de 5) del arco argumental &quot;Zero Year: Dark City&quot;.\r\n&quot;Tras enfrentarse a los Capuchas Rojas en las instalaciones de Industrias Químicas ACE, Batman logró derrotar a la banda de criminales, averiguando la sorprendente identidad de uno de sus miembros. Sin tiempo para asimilar los acontecimientos, el Caballero Oscuro asistió a la presentación en sociedad de Edward Nygma, quien como el Acertijo sumió a Gotham en la oscuridad, amenazando la integridad de una ciudad que requerirá la intervención de su todavía incipiente héroe…&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000731392-6pfnbs.jpg','read',0,NULL,NULL,'2026-04-12 13:32:12','2026-04-12 16:14:20',186,NULL,'Grapa','[{"name":"Scott Snyder","role":""},{"name":"John Layman","role":""},{"name":"James Tynion IV","role":""},{"name":"Greg Capullo","role":""},{"name":"Jason Fabok","role":""},{"name":"Andy Clarke","role":""},{"name":"Rafael Albuquerque","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1519,'Batman (2012-2024) #26','Batman (2012-2024)',26,NULL,'978-8-416-15203-2',NULL,'John Layman','Aaron Lopresti',NULL,NULL,'ECC Ediciones',NULL,'2014-06-01',NULL,NULL,replace(replace('Recopila Batman #26 USA, Detective comics #26 y una historia corta de Detective Comics #25 USA.\r\nBatman #26 USA es el capítulo 3 (de 5) del arco argumental &quot;Zero Year: Dark City&quot;.\r\nNota: Detective Comics #25 USA fue un tie-in con &quot;Zero Year&quot;, que en España se publicó por ECC en el tomo &quot;Batman: Origen - Gotham City&quot;.  Detective Comics #27 USA fue un especial de aniversario que en España se publicó en el tomo &quot;Batman: Especial Detective Comics 27 - 75 Años de Batman&quot;. Parte de Detective Comics #27 y la totalidad de los #28 y 29 fueron publicados por ECC en los tomos &quot;Batman: Gothopía&quot;.\r\n&quot;Con Gotham City sumida en la oscuridad como consecuencia de un plan del Acertijo, Batman comenzó a investigar el extraño asesinato de dos científicos de Empresas Wayne: los Doctores Del Paji y Bill Kelver, víctimas de un compuesto que, ideado por el Doctor Karl Helfern, provoca un crecimiento óseo descontrolado. En este inquietante contexto, quedó de manifiesto la tensión existente entre el Teniente James Gordon y Bruce Wayne, aparentemente relacionada con un episodio del pasado...&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000733701-9vtp2d.jpg','read',0,NULL,NULL,'2026-04-12 13:32:14','2026-04-12 16:14:20',186,NULL,'grapa','[{"name":"John Layman","role":"Guion"},{"name":"Scott Snyder","role":"Guion"},{"name":"Aaron Lopresti","role":"Dibujo"},{"name":"Greg Capullo","role":"Dibujo"},{"name":"Jorge Lucas","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1520,'Batman (2012-2024) #27','Batman (2012-2024)',27,NULL,'978-8-416-15254-4',NULL,'Scott Snyder','Alberto Ponticelli',NULL,NULL,'ECC Ediciones',NULL,'2014-07-05',NULL,NULL,replace(replace('Recopila Batman #27 y Batman: The Dark Knight #26 y 27 USA\r\nBatman #27 USA es el capítulo 4 (de 5) del arco argumental &quot;Zero Year: Dark City&quot;. \r\nNota: Los números anteriores de la serie USA Batman: The Dark Knight fueron publicados por ECC en 5 tomos en cartoné (4 de la etapa New52 y 1 previo al &quot;reseteo&quot;). \r\n&quot;El Hombre Murciélago descubrió la implicación del Dr. Karl Helfern en el asesinato de dos científicos de Empresas Wayne. Desfigurado por el suero que él mismo diseñó, el ahora llamado Dr. Muerte a punto estuvo de matar a Lucius Fox. Pero Bruce Wayne y James Gordon lograron detenerlo, aun a costa de la salud del Caballero Oscuro, herido durante el proceso. Tras recuperarse y recriminar al teniente del Departamento de Policía de Gotham City un suceso acontecido en el pasado, Batman puso rumbo al Centro Newton, donde le esperaba una emboscada.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000736221-sdu377.jpg','read',0,NULL,NULL,'2026-04-12 13:32:17','2026-04-12 16:14:20',186,NULL,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Gregg Hurwitz","role":"Guion"},{"name":"Alberto Ponticelli","role":"Dibujo"},{"name":"Greg Capullo","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1521,'Batman (2012-2024) #28','Batman (2012-2024)',28,NULL,'978-8-416-15288-9',NULL,'Scott Snyder','Dustin Nguyen',NULL,NULL,'ECC Ediciones',NULL,'2014-07-30',NULL,NULL,replace(replace('Recopila Batman #28 USA y Batman: The Dark Knight #28 USA \r\nBatman #28 USA es un &quot;interludio&quot; a modo de flash-forward con la serie &quot;Batman: Eterno&quot;.\r\n&quot;Desde que Harper Row irrumpió en la vida del Caballero Oscuro, se reveló como una joven intrépida y decidida, empeñada en prestar cualquier ayuda posible a Batman. Así, perfeccionó los amplificadores de su red eléctrica privada, le ayudó a derrotar al Tiburón Tigre, le reanimó cuando a duras penas sobrevivió al laberinto del Tribunal de los Búhos y le recordó la necesidad de recomponerse tras el fallecimiento de Robin. Argumentos acreditativos de su valía... y de la aptitud necesaria para desempeñar un papel más activo en la lucha contra el crimen.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000738688-bgsq10.jpg','read',0,NULL,NULL,'2026-04-12 13:32:19','2026-04-12 16:14:20',186,NULL,'Grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"James Tynion IV","role":"Guion"},{"name":"Dustin Nguyen","role":"Dibujo"},{"name":"Derek Fridolfs","role":"Tinta"},{"name":"John Kalisz","role":"Color"},{"name":"Gregg Hurwitz","role":"Guion"},{"name":"Ethan Van Sciver","role":"Dibujo, Tinta"},{"name":"Hi-Fi Desing","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1522,'Batman (2012-2024) #29','Batman (2012-2024)',29,NULL,'978-8-416-19438-4',NULL,'Scott Snyder','Greg Capullo',NULL,NULL,'ECC Ediciones',NULL,'2014-09-04',NULL,NULL,replace(replace('Recopila Batman #29 USA y Batman: The Dark Knight #29 USA\r\nBatman #29 USA es el capítulo 5 (de 5) del arco argumental &quot;Zero Year: Dark City&quot;. \r\nLa serie Batman: The Dark Knight fue cancelada en EEUU con el #29 USA.\r\n&quot;Contando con la inestimable ayuda de James Gordon, el Hombre Murciélago sobrevivió a una emboscada tendida por el Departamento de Policía, alertado por Edward Nigma de que Batman se dirigía hacia el Centro Newton. Tras aclarar sus diferencias con el Teniente, el Caballero Oscuro buscó a Karl Helfern, más conocido como el Dr. Muerte, en las catacumbas de la ciudad. Pero en su lugar, se encontró con la enésima trampa ideada por un Acertijo que plantea sembrar el caos en Gotham.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000741994-ltyh9k.jpg','read',0,NULL,NULL,'2026-04-12 13:32:22','2026-04-12 16:14:20',186,NULL,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Greg Capullo","role":"Dibujo"},{"name":"Gregg Hurwitz","role":""},{"name":"Ethan Van Sciver","role":"Dibujo"},{"name":"Jorge Lucas","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1523,'Batman (2012-2024) #30','Batman (2012-2024)',30,NULL,'978-8-416-19481-0',NULL,'Scott Snyder','Greg Capullo',NULL,NULL,'ECC Ediciones',NULL,'2014-10-01',NULL,NULL,replace(replace('Recopila Batman #30 USA y Detective Comics #30 USA\r\nBatman #30 USA es el capítulo 1 (de 4) del arco argumental &quot;Zero Year: Savage City&quot;.\rDetective Comics #30 es la parte 1 (de 5) del arco argumental &quot;Icarus&quot;, con el que se estrenan en la serie el tándem Buccellato/Manapul (hasta ahora encargados de la serie regular de Flash).\r&quot;Batman se vio obligado a enfrentarse al Dr. Muerte, enzarzándose en un brutal duelo del que salió derrotada la criatura que en su día fue Karl Helfern. Mientras tanto, James Gordon se topó con Edward Nigma cayó en una de sus múltiples trampas. Así pues, ni el teniente del Departamento de Policía ni el Caballero Oscuro consiguieron frustrar los planes del Acertijo, quien no solo logró escapar indemne, sino que además dinamitó los muros de contención de la ciudad, sumiendo a Gotham City en el caos más absoluto.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000744374-qiphfn.jpg','read',0,NULL,NULL,'2026-04-12 13:32:25','2026-04-12 16:14:20',186,NULL,'Grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Greg Capullo","role":"Dibujo"},{"name":"Francis Manapul","role":"Guion, Dibujo"},{"name":"Brian Buccellato","role":"Guion, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1524,'Batman (2012-2024) #31','Batman (2012-2024)',31,NULL,'978-8-416-25515-3',NULL,'Scott Snyder','Greg Capullo',NULL,NULL,'ECC Ediciones',NULL,'2014-10-31',NULL,NULL,replace(replace('Recopila Batman #31 USA y Detective Comics #31 USA\r\nBatman #31 USA es el capítulo 2 (de 4) del arco argumental &quot;Zero Year: Savage City&quot;.\rDetective Comics #31 es la parte 2 (de 5) del arco argumental &quot;Icarus&quot;.\r&quot;Tras llevar a buen término su maquiavélico plan, el Acertijo logró hacerse con el control de Gotham, valiéndose de los conocimientos de Pamela Isley para conferir a las calles de la ciudad un aspecto salvaje. Todavía convaleciente del brutal enfrentamiento contra el Dr. Muerte, Bruce Wayne recibió la asistencia del joven Duke Thomas y su familia, reuniendo las fuerzas necesarias para comenzar a tramar la estrategia con la que derrotar a su enemigo.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000746834-wnv20u.jpg','read',0,NULL,NULL,'2026-04-12 13:32:28','2026-04-12 16:14:20',186,NULL,'Grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Greg Capullo","role":"Dibujo"},{"name":"Brian Buccellato","role":"Guion"},{"name":"Francis Manapul","role":"Guion, Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1525,'Batman (2012-2024) #32','Batman (2012-2024)',32,NULL,'978-8-416-25549-8',NULL,'Brian Buccellato','Francis Manapul',NULL,NULL,'ECC Ediciones',NULL,'2014-11-28',NULL,NULL,replace(replace('Recopila Batman #32 USA y Detective Comics #32 USA\r\nBatman #32 USA es el capítulo 3 (de 4) del arco argumental &quot;Zero Year: Savage City&quot;.\rDetective Comics #32 es la parte 3 (de 5) del arco argumental &quot;Icarus&quot;.\r&quot;Lucius Fox, James Gordon y Batman unieron fuerzas para intentar derrotar al Acertijo, maquiavélico villano responsable de la transformación de Gotham en una ciudad irreconocible y sometida a sus caprichos. Así, el Caballero Oscuro se convirtió en un elemento de distracción: tras retar públicamente a Nigma, afrontó sus letales trampas, intentando ganar el tiempo necesario para que Gordon y Fox ejecutaran un plan que bien podría ser la última esperanza de los gothamitas.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000749295-5oene0.jpg','read',0,NULL,NULL,'2026-04-12 13:32:30','2026-04-12 16:14:20',186,NULL,'Grapa','[{"name":"Brian Buccellato","role":"Guion"},{"name":"Francis Manapul","role":"Guion, Dibujo"},{"name":"Scott Snyder","role":"Guion"},{"name":"Greg Capullo","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1526,'Batman (2012-2024) #33','Batman (2012-2024)',33,NULL,'978-8-416-25590-0',NULL,'Brian Buccellato','Greg Capullo',NULL,NULL,'ECC Ediciones',NULL,'2014-12-31',NULL,NULL,replace(replace('Recopila Batman #33 USA y Detective Comics #33 USA \r\nBatman #33 USA es un número doble (35 pgs de historieta) con el que concluye el arco argumental en 4 partes  &quot;Zero Year: Savage City&quot;.\r\nDetective Comics #33 es la parte 4 (de 5) del arco argumental &quot;Icarus&quot;.\r\n&quot;Con la inestimable colaboración de Lucius Fox y James Gordon, Batman logró superar diferentes trampas urdidas por el Acertijo hasta localizar la guarida del criminal. ¿Ha terminado el macabro juego ideado por Nigma o está a punto de comenzar? Ya en el presente, el Caballero Oscuro prosiguió con la investigación del asesinato de Elena Águila, aparentemente relacionado con una trama tráfico de drogas; y rastreando una pista, llegó al viejo acuario de Gotham City, donde le esperaba un recibimiento poco amistoso.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000751659-o97owb.jpg','read',0,NULL,NULL,'2026-04-12 13:32:32','2026-04-12 16:14:13',186,NULL,'Grapa','[{"name":"Brian Buccellato","role":"Guion"},{"name":"Francis Manapul","role":"Guion"},{"name":"Scott Snyder","role":"Guion"},{"name":"Greg Capullo","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1527,'Batman (2012-2024) #34','Batman (2012-2024)',34,NULL,'978-8-416-30332-8',NULL,'Brian Buccellato','Jorge Fornés',NULL,NULL,'ECC Ediciones',NULL,'2015-02-06',NULL,NULL,replace(replace('Corresponde a Detective Comics Annual #3 USA\r\n&quot;Gotham pudo dejar atrás su particular Año cero: todo un bautismo de fuego para su justiciero, quien demostró estar preparado para afrontar cualquier desafío. Ya en el presente, Batman siguió investigando el asesinato de Elena Águila: un complejo caso que obligó al álter ego de Bruce Wayne a intervenir en la guerra de bandas callejeras librada por el Calamar y los Reyes del Sol.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000754131-h5yiw5.jpg','read',0,NULL,NULL,'2026-04-12 13:32:35','2026-04-12 16:14:13',186,NULL,'Grapa','[{"name":"Brian Buccellato","role":"Guion"},{"name":"Francis Manapul","role":"Guion"},{"name":"Jorge Fornés","role":"Dibujo, Tinta"},{"name":"Scott Hepburn","role":"Dibujo, Tinta"},{"name":"Werther Dell''Edera","role":"Dibujo, Tinta"},{"name":"John Kalisz","role":"Color"},{"name":"Lee Loughridge","role":"Color"},{"name":"Jon Proctor","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1528,'Batman (2012-2024) #35','Batman (2012-2024)',35,NULL,'978-8-416-30385-4',NULL,'Brian Buccellato','Francis Manapul',NULL,NULL,'ECC Ediciones',NULL,'2015-03-04',NULL,NULL,replace(replace('Incluye Batman #34 USA  y  Detective Comics #34 USA.\r\nBatman #34 es un capítulo autoconclusivo (&quot;El Manso&quot;) con dos autores invitados: Gerry Duggan al guión (con Snyder acreditado como co-argumentista) y Matteo Scalera (Ciencia Oscura) al dibujo.\r\nDetective Comics #34 es la parte 5 (de 5) del arco argumental &quot;Icarus&quot;.\r\n&quot;El Caballero Oscuro redobló sus esfuerzos para investigar el robo de un cargamento de armas propiedad del Departamento de Policía. Suceso que, sumado a la presencia en las calles de la droga denominada Ícaro, determinó un clima de tensión entre las diferentes bandas criminales de Gotham. En ese contexto, Batman recurrió a su identidad de “Cerillas” Malone para moverse por los bajos fondos de la ciudad; no solo con vistas a localizar el cargamento perdido, sino también con la intención de tomar represalias contra el matón Julian Day por los daños infligidos a una víctima indefensa.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000756627-v7b860.jpg','read',0,NULL,NULL,'2026-04-12 13:32:37','2026-04-12 16:14:13',186,NULL,'Grapa','[{"name":"Brian Buccellato","role":"Guion"},{"name":"Francis Manapul","role":"Guion, Dibujo"},{"name":"Gerry Duggan","role":"Guion"},{"name":"Scott Snyder","role":"Guion"},{"name":"Matteo Scalera","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1529,'Batman (2012-2024) #36','Batman (2012-2024)',36,NULL,'978-8-416-37428-1',NULL,'Benjamin Percy','Greg Capullo',NULL,NULL,'ECC Ediciones',NULL,'2015-03-29',NULL,NULL,replace(replace('Incluye Batman núm. 35 USA, Detective Comics núm. 35 USA \r\n&quot;Batman tuvo que hacer uso de todas sus habilidades detectivescas para tratar de detener a un eficaz asesino en serie con base de operaciones en Gotham City. Criminal que, a diferencia de buena parte de sus enemi- gos, operaba con sigilo y discreción, sacando provecho del anonimato. A su vez, el Caballero Oscuro cerró el caso relacionado con la droga Ícaro, interviniendo en la dramática sucesión de acontecimientos que a buen seguro condicionará el futuro de Annie Águila.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000759304-7u34io.jpg','read',0,NULL,NULL,'2026-04-12 13:32:40','2026-04-12 16:14:13',186,NULL,'Grapa','[{"name":"Benjamin Percy","role":"Guion"},{"name":"James Tynion IV","role":"Guion"},{"name":"Scott Snyder","role":"Guion"},{"name":"Greg Capullo","role":"Dibujo"},{"name":"John Paul Leon","role":"Dibujo"},{"name":"Kelley Jones","role":"Dibujo"}]');
