INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1535,'Batman (2012-2024) #42','Batman (2012-2024)',42,NULL,'978-8-416-47581-0',NULL,'Brenden Fletcher','Bengal',NULL,NULL,'ECC Ediciones',NULL,'2015-09-30',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Arkham Manor: Endgame núm. 1 USA, Detective Comics: Endgame núm. 1 USA, Batgirl: Endgame núm. 1 USA \r\nA punto de concluir el arco argumental Final del juego, con el que Scott Snyder y Greg Capullo han recuperado a la versión más letal del Joker, este mes os ofrecemos una entrega triple que contiene tie-ins de la saga, originalmente publicados en Arkham Manor, Detective Comics y Batgirl.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000772903-kcr6pn.jpg','read',0,NULL,NULL,'2026-04-12 13:32:53','2026-04-12 16:14:13',186,NULL,'Grapa','[{"name":"Brenden Fletcher","role":"Guion"},{"name":"Brian Buccellato","role":"Guion"},{"name":"Cameron Stewart","role":"Guion"},{"name":"Frank Tieri","role":"Guion"},{"name":"Bengal","role":"Dibujo"},{"name":"Félix Ruiz","role":"Dibujo"},{"name":"Roberto Viacava","role":"Dibujo"},{"name":"Roge Antonio","role":"Dibujo"},{"name":"Ronan Cliquet","role":"Dibujo"}]');
