INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1540,'Batman (2012-2024) #47','Batman (2012-2024)',47,NULL,'978-8-416-66000-1',NULL,'Brian Azzarello','Jock',NULL,NULL,'ECC Ediciones',NULL,'2016-02-29',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núm. 44 USA, Batman annual núm. 4 USA     \r\nEntrega especial de la colección, en la que Scott Snyder echa un vistazo al pasado para revelar el origen de Mr. Bloom, ¡con Jock (Green Arrow: Año uno) como dibujante invitado! Además, el cuarto anual de la colección indaga en las implicaciones del misterio que recientemente ha revolucionado esta cabecera.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000785006-faue9l.jpg','read',0,NULL,NULL,'2026-04-12 13:33:05','2026-04-12 16:14:13',186,NULL,'Grapa','[{"name":"Brian Azzarello","role":"Guion"},{"name":"James Tynion IV","role":"Guion"},{"name":"Scott Snyder","role":"Guion"},{"name":"Jock","role":"Dibujo"},{"name":"Roge Antonio","role":"Dibujo"}]');
