INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1547,'Batman (2012-2024) #54','Batman (2012-2024)',54,NULL,'978-8-416-84074-8',NULL,'Scott Snyder','Greg Capullo',NULL,NULL,'ECC Ediciones',NULL,'2016-09-30',NULL,NULL,replace(replace('Contiene Batman #51 USA y Detective Comics #51 USA\r\n&quot;Scott Snyder y Greg Capullo concluyen su estancia en la serie regular del Caballero Oscuro. La etapa iniciada hace cinco años, con el nacimiento del nuevo Universo DC, llega a su ﬁn con un bello relato que homenajea a los aﬁcionados de siempre y prepara el escenario para un nuevo capítulo en la vida del personaje.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000820298-6lycrj.jpg','read',0,NULL,NULL,'2026-04-12 13:33:41','2026-04-12 16:14:13',186,NULL,'Grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Peter J. Tomasi","role":"Guion"},{"name":"Greg Capullo","role":"Dibujo"},{"name":"Fernando Pasarín","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1548,'Batman (2012-2024) #55','Batman (2012-2024)',55,NULL,'978-8-416-90125-8',NULL,'James Tynion IV','Riley Rossmo',NULL,NULL,'ECC Ediciones',NULL,'2016-10-28',NULL,NULL,replace(replace('CONTENIDO USA: Batman núm. 52, Detective Comics núm. 52 \r\nARGUMENTO: James Tynion IV y Riley Rossmo, el equipo creativo responsable de Constantine: The Hellblazer, narra la última historia del Caballero Oscuro dentro del nuevo Universo DC. Un relato en el que el pasado y el futuro de Gotham confluyen en un inolvidable repaso por la relación entre Bruce Wayne y Alfred.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000822246-x1hvpo.jpg','read',0,NULL,NULL,'2026-04-12 13:33:43','2026-04-12 16:14:13',186,NULL,'Grapa','[{"name":"James Tynion IV","role":"Guion"},{"name":"Peter J. Tomasi","role":"Guion"},{"name":"Riley Rossmo","role":"Dibujo"},{"name":"Fernando Pasarín","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1549,'Batman (2012-2024) #56/1','Batman (2012-2024) #56/1',56,NULL,'978-8-416-90180-7',NULL,'Scott Snyder','Mikel Janin',NULL,NULL,'ECC Ediciones',NULL,'2016-11-30',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman: Rebirth núm. 1 USA (one-shot), Batman núm. 1 USA\r\nARGUMENTO: ¡El guionista estrella Scott Snyder cede el battestigo a Tom King (Grayson)! ¡Primera entrega de la nueva etapa de la serie! Muchos lo han intentado, pero nadie ha puesto en jaque la cruzada del Hombre Murciélago. Ni el Joker. Ni Dos Caras. Ni siquiera otros héroes. Así pues...¿Qué sucederá cuando un nuevo vigilante quiera proteger Gotham de la presencia del Caballero Oscuro?\r\nLa llegada de Tom King a la serie regular del álter ego de Bruce Wayne ofrece a todos los lectores un refrescante punto de partida para engancharse a la serie regular de Batman, pero sin perder de vista a los aficionados más veteranos y a la mitología que ha convertido al personaje en un icono cultural. El equipo creativo se completa con Mikel Janín, artista revelación de Grayson, y con el regreso de David Finch (Maldad Eterna), que vuelve a dibujar a Batman tras su paso por las páginas de Wonder Woman.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000824613-8mlzwo.jpg','read',0,NULL,NULL,'2026-04-12 13:33:45','2026-04-12 16:14:13',186,NULL,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Tom King","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo, Tinta"},{"name":"June Chung","role":"Color"},{"name":"David Finch","role":"Dibujo"},{"name":"Matt Banning","role":"Tinta"},{"name":"Jordie Bellaire","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1550,'Batman (2012-2024) #57/2','Batman (2012-2024) #57/2',57,NULL,'978-8-416-94530-6',NULL,'Tom King','David Finch',NULL,NULL,'ECC Ediciones',NULL,'2016-12-19',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 2 a 3 USA\r\n¡Sigue adelante la etapa de Tom King (Grayson) al frente de Batman! Tras un explosivo primer encuentro, el Hombre Murciélago afronta la llegada de un nuevo e idealista héroe. ¿Es este testarudo aliado todo lo que Gotham necesita? ¿Su aparición supone el fin de la carrera del Caballero Oscuro? Mientras, un mal crece en el corazón de la ciudad, acechando a ambos vigilantes y poniendo en peligro a toda la población.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000846251-s4u5ej.jpg','read',0,NULL,NULL,'2026-04-12 13:34:07','2026-04-12 16:14:13',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"David Finch","role":"Dibujo"},{"name":"Matt Banning","role":"Tinta"},{"name":"Danny Miki","role":"Tinta"},{"name":"Jordie Bellaire","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1551,'Batman (2012-2024) #58/3','Batman (2012-2024) #58/3',58,NULL,'978-8-416-94572-6',NULL,'Tom King','David Finch',NULL,NULL,'ECC Ediciones',NULL,'2017-01-31',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 4 a 5 USA\r\n¡El desenlace de Yo soy Gotham, el primer arco argumental de Tom King en la nueva etapa de la serie! Cuando la ciudad está a punto de caer bajo las garras del verdadero mal, llega el momento de responder a la gran pregunta: ¿De qué lado estarán Gotham y Gotham Girl? ¿Abandonarán a su suerte al Caballero Oscuro? La fina línea que separa a amigos de enemigos se difumina mientras tiene lugar el enfrentamiento definitivo que decidirá el futuro de Gotham.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000848956-v32kot.jpg','read',0,NULL,NULL,'2026-04-12 13:34:10','2026-04-12 16:14:13',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"David Finch","role":"Dibujo, Tinta"},{"name":"Sandra Hope","role":"Tinta"},{"name":"Matt Banning","role":"Tinta"},{"name":"Jordie Bellaire","role":"Color"},{"name":"Scott Hanna","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1552,'Batman (2012-2024) #59/4','Batman (2012-2024) #59/4',59,NULL,'978-8-416-99827-2',NULL,'Tom King','Ivan Reis',NULL,NULL,'ECC Ediciones',NULL,'2017-02-27',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 6 USA Yo soy Gotham #6          \r\nARGUMENTO: El epílogo de Yo soy Gotham. En esta historia independiente, dibujada por Ivan Reis, Batman busca la redención mientras trata de mantener a Gotham Girl alejada de una vida llena de peligros. Pero... ¿puede el Caballero Oscuro salvar a alguien que no quiere que le salven? ¡Última entrega antes del primer Batcrossover de la era Renacimiento, que publicaremos en abril bajo el título Batman: La noche de los hombres monstruo!','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000851606-e6aygp.jpg','read',0,NULL,NULL,'2026-04-12 13:34:12','2026-04-12 16:14:13',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Ivan Reis","role":"Dibujo"},{"name":"Joe Prado","role":"Tinta"},{"name":"Oclair Albert","role":"Tinta"},{"name":"Scott Hanna","role":"Tinta"},{"name":"Marcelo Maiolo","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1553,'Batman (2012-2024) #60/5','Batman (2012-2024) #60/5',60,NULL,'978-8-417-06349-8',NULL,'Tom King','Mikel Janin',NULL,NULL,'ECC Ediciones',NULL,'2017-03-28',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núm. 9 USA\r\n¡Primer capítulo de Yo soy suicida! Tras los acontecimientos de Batman: La noche de los hombres monstruo y de Yo soy Gotham, el arco argumental inaugural de la etapa de Tom King, llegamos a otro importante punto de inflexión. Para detener al Psicopirata, Batman debe aliarse con la mismísima Amanda Waller, la mujer que, en secreto, dirige al grupo conocido como el Escuadrón Suicida. ¡La siguiente gran historia del Caballero Oscuro comienza aquí! ¡El equipo creativo se completa este mes con el regreso del español Mikel Janín (Superman, Grayson)!','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000853602-22nh81.jpg','read',0,NULL,NULL,'2026-04-12 13:34:14','2026-04-12 16:14:13',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo, Tinta"},{"name":"June Chung","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1554,'Batman (2012-2024) #61/6','Batman (2012-2024) #61/6',61,NULL,'978-8-417-07118-9',NULL,'Tom King','Mikel Janin',NULL,NULL,'ECC Ediciones',NULL,'2017-05-02',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núm. 10-11 USA \r\nARGUMENTO: Con la segunda parte de Yo soy suicida. Batman ha reclutado a un equipo, pero ¿están listos estos aliados para la misión más peligrosa de sus vidas? A medida que el Caballero Oscuro prepara a su escuadrón para infiltrarse en Santa Prisca, toma conciencia de que depende de sí mismo para enfrentarse a Bane. Muy pronto, sumergidos en el vientre de la bestia, el Caballero Oscuro se dará cuenta de que no todos podrán salir con vida.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000856017-79crwt.jpg','read',0,NULL,NULL,'2026-04-12 13:34:17','2026-04-12 16:14:13',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo, Tinta"},{"name":"June Chung","role":"Color"},{"name":"Hugo Petrus","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1555,'Batman (2012-2024) #62/7','Batman (2012-2024) #62/7',62,NULL,'978-8-417-07180-6',NULL,'Tom King','Mikel Janin',NULL,NULL,'ECC Ediciones',NULL,'2017-05-23',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núm. 12-13 USA\r\nARGUMENTO: ¡Descubre el trepidante desenlace de Yo soy suicida! En Santa Prisca, Bane y el Psico-Pirata han golpeado duramente al equipo de Batman, y ahora el Caballero Oscuro debe decidir lo lejos que quiere llegar y los sacrificios que está dispuesto a hacer para detener a este implacable enemigo. ¿Es esta realmente una misión suicida?','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000858544-vgw15s.jpg','read',0,NULL,NULL,'2026-04-12 13:34:19','2026-04-12 16:14:13',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo, Tinta"},{"name":"Hugo Petrus","role":"Tinta"},{"name":"June Chung","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1556,'Batman (2012-2024) #63/8','Batman (2012-2024) #63/8',63,NULL,'978-8-417-10686-7',NULL,'Tom King','Mitch Gerads',NULL,NULL,'ECC Ediciones',NULL,'2017-06-27',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 14-15 USA    \r\nARGUMENTO:   La misión suicida en Santa Prisca ha terminado. De vuelta a Gotham, el Hombre Murciélago y Catwoman se enfrentan a su pasado. Lo que decidan sobre su futuro puede cambiar las vidas de ambos y el destino de la ciudad para siempre. Mientras, un viejo aliado llega desde los pantanos del sur del país con una misteriosa petición y un único objetivo: hacer frente a una amenaza que sólo puede detener con la ayuda de Batman. El equipo creativo se completa este mes con Mitch Gerads, colaborador del guionista en El Sheriff de Babilonia, el multipremiado proyecto del sello Vertigo.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000861024-qvsrar.jpg','read',0,NULL,NULL,'2026-04-12 13:34:22','2026-04-12 16:14:13',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1557,'Batman (2012-2024) #64/9','Batman (2012-2024) #64/9',64,NULL,'978-8-417-14763-1',NULL,'Tom King','David Finch',NULL,NULL,'ECC Ediciones',NULL,'2017-07-18',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 16-17 USA\r\nARGUMENTO: Yo soy Bane, primera parte. Tras la misión en Santa Prisca, un rabioso Bane viaja a Gotham. ¿El objetivo? La vida de Gotham Girl y de todos los seres queridos de Batman. Esta vez, Bane no se detendrá ante nada. Nadie está a salvo, ni siquiera tras los muros de Akrham.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000863225-c8ps41.jpg','read',0,NULL,NULL,'2026-04-12 13:34:24','2026-04-12 16:14:13',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"David Finch","role":"Dibujo, Tinta"},{"name":"Jordie Bellaire","role":"Color"},{"name":"Danny Miki","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1558,'Batman (2012-2024) #65/10','Batman (2012-2024) #65/10',65,NULL,'978-8-417-17636-5',NULL,'Tom King','David Finch',NULL,NULL,'ECC Ediciones',NULL,'2017-08-22',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 18-19 USA       \r\nARGUMENTO: Yo soy Bane, segunda parte. ¡Bane rompió al Murciélago hace años, pero ahora está dispuesto a acabar también con todos sus aliados! Bane ya está aquí... ¡y nadie está a salvo! A punto de ser derrotado, Batman está dispuesto a emplear un arma secreta e inesperada, que puede eliminar para siempre a tan imparable enemigo.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000866633-1rrj9s.jpg','read',0,NULL,NULL,'2026-04-12 13:34:27','2026-04-12 16:14:13',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"David Finch","role":"Dibujo"},{"name":"Danny Miki","role":"Tinta"},{"name":"Jordie Bellaire","role":"Color"},{"name":"Trevor Scott","role":"Tinta"},{"name":"Sandra Hope","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1559,'Batman (2012-2024) #66/11','Batman (2012-2024) #66/11',66,NULL,'978-8-417-17698-3',NULL,'Tom King','David Finch',NULL,NULL,'ECC Ediciones',NULL,'2017-09-15',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núm. 20 USA \r\nARGUMENTO: En el épico final, no hay vuelta atrás. No hay más trucos. No hay más aliados. Sólo Batman. Y Bane. Y cuando la sangre se derrame... nada volverá a ser igual para el Caballero Oscuro.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000869182-854yjv.jpg','read',0,NULL,NULL,'2026-04-12 13:34:30','2026-04-12 16:14:13',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"David Finch","role":"Dibujo"},{"name":"Danny Miki","role":"Tinta"},{"name":"Trevor Scott","role":"Tinta"},{"name":"Jordie Bellaire","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1560,'Batman (2012-2024) #67/12','Batman (2012-2024) #67/12',67,NULL,'978-8-417-20670-3',NULL,'Tom King','Mitch Gerads',NULL,NULL,'ECC Ediciones',NULL,'2017-10-10',NULL,NULL,replace(replace('EDICIÓN ORIGINAL Batman núm. 23 USA\r\nARGUMENTO: Tom King y Mitch Gerads, aclamados autores de El Sheriff de Babilonia, se reencuentran en esta sorprendente aventura autoconclusiva del Caballero Oscuro. ¡El antiguo aliado de Batman, La Cosa del Pantano, llega a Gotham con una misteriosa petición! ¿Podrán compensar el tiempo perdido y trabajar juntos para hacer frente a una creciente amenaza que sólo ellos pueden detener?','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000871546-0k73g9.jpg','read',0,NULL,NULL,'2026-04-12 13:34:32','2026-04-12 16:14:13',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1561,'Batman (2012-2024) #68/13','Batman (2012-2024) #68/13',68,NULL,'978-8-417-24347-0',NULL,'Tom King','David Finch',NULL,NULL,'ECC Ediciones',NULL,'2017-11-07',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núm. 24 y 25 USA\r\nARGUMENTO: Los habitantes de Gotham duermen tranquilos por primera vez en mucho tiempo, sin saber que dos de los enemigos más mortales del Caballero Oscuro se preparan para un enfrentamiento nunca visto. Atormentado por los errores del pasado y por los descubrimientos realizados en el transcurso de Batman/Flash: La chapa, Batman pronuncia unas trascendentales palabras que cambiarán para siempre su mundo y el de sus aliados.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000874021-lq7n1l.jpg','read',0,NULL,NULL,'2026-04-12 13:34:35','2026-04-12 16:14:13',186,NULL,'lujo','[{"name":"Tom King","role":"Guion"},{"name":"David Finch","role":"Dibujo"},{"name":"Clay Mann","role":"Dibujo, Tinta"},{"name":"Seth Mann","role":"Dibujo, Tinta"},{"name":"Danny Miki","role":"Tinta"},{"name":"Jordie Bellaire","role":"Color"},{"name":"Mikel Janin","role":"Dibujo, Tinta"},{"name":"June Chung","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1562,'Batman (2012-2024) #69/14','Batman (2012-2024) #69/14',69,NULL,'978-8-417-27637-9',NULL,'Tom King','Mikel Janin',NULL,NULL,'ECC Ediciones',NULL,'2017-12-05',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 26-27 USA        \r\nARGUMENTO: Sigue La guerra de bromas y acertijos. En medio del conflicto entre el Joker y El Acertijo, los villanos de Gotham se ven obligados a elegir un bando... ¡o a verse atrapados en el fuego cruzado! Batman, al límite, trata de mantener a los ciudadanos inocentes fuera de peligro.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000879865-ar5652.jpg','read',0,NULL,NULL,'2026-04-12 13:34:40','2026-04-12 16:14:13',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo, Tinta"},{"name":"June Chung","role":"Color"},{"name":"Clay Mann","role":"Dibujo, Tinta"},{"name":"Danny Miki","role":"Tinta"},{"name":"John Livesay","role":"Tinta"},{"name":"Gabe Eltaeb","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1563,'Batman (2012-2024) #70/15','Batman (2012-2024) #70/15',70,NULL,'978-8-494-77619-9',NULL,'Tom King','Mikel Janin',NULL,NULL,'ECC Ediciones',NULL,'2018-01-09',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 28-29 USA         \r\nARGUMENTO: La guerra es el infierno. Y si hablamos de La guerra de bromas y acertijos, en Gotham City, la situación es todavía peor. El Joker y El Acertijo siguen adelante con su escalada de caos y violencia. Batman ha hecho todo lo imaginable para mantener la paz, pero cuando ninguno de los contendientes retrocede, es el momento de elegir un bando, el menor de los males. ¿Elegirá la anarquía asesina del Joker o el sangriento totalitarismo de Edward Nigma? En cualquier caso, el Caballero Oscuro pierde.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000881943-0qc949.jpg','read',0,NULL,NULL,'2026-04-12 13:34:43','2026-04-12 16:14:13',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo, Tinta"},{"name":"June Chung","role":"Color"},{"name":"Hugo Petrus","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1564,'Batman (2012-2024) #71/16','Batman (2012-2024) #71/16',71,NULL,'978-8-417-35403-9',NULL,'Tom King','Clay Mann',NULL,NULL,'ECC Ediciones',NULL,'2018-01-30',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 30-31 USA  : La batalla del Hombre Cometa.      \r\n¡Concluye el interludio de La guerra de bromas y acertijos, La batalla del Hombre Cometa! Pero el conflicto entre las némesis del Caballero Oscuro no se detiene... derrotar al Joker y al Acertijo en su propio campo de juegos es una tarea titánica. Toda la ciudad de Gotham está en la cuerda floja y Batman se enfrenta, en medio del caos, a la decisión crítica: ¿son mejores los rompecabezas o las carcarjadas? Y tú, ¿qué eligirías?','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000893766-amvi6a.jpg','read',0,NULL,NULL,'2026-04-12 13:34:55','2026-04-12 16:14:13',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Clay Mann","role":"Dibujo"},{"name":"Seth Mann","role":"Tinta"},{"name":"Jordie Bellaire","role":"Color"},{"name":"Mikel Janin","role":"Dibujo, Tinta"},{"name":"June Chung","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1565,'Batman (2012-2024) #72/17','Batman (2012-2024) #72/17',72,NULL,'978-8-417-35488-6',NULL,'Tom King','Mikel Janin',NULL,NULL,'ECC Ediciones',NULL,'2018-03-06',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 32-33 USA    \r\nARGUMENTO: ¡El desenlace de La guerra de bromas y acertijos! Un final del que se hablará largo y tendido durante los próximos meses. Joker y Edward Nigma luchan desesperadamente por el control de Gotham. Para detenerlos, Batman ha tenido que llegar más lejos que nunca. Ahora, con los pecados del pasado al descubierto... ¿cuál será la respuesta definitiva de Catwoman? ¿Aceptará Selina la propuesta de matrimonio del Caballero Oscuro? El futuro de Bruce Wayne y de la propia Batfamilia está en juego.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000896213-l6xb93.jpg','read',0,NULL,NULL,'2026-04-12 13:34:57','2026-04-12 16:14:13',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo, Tinta"},{"name":"June Chung","role":"Color"},{"name":"Joelle Jones","role":"Dibujo, Tinta"},{"name":"Jordie Bellaire","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1566,'Batman (2012-2024) #73/18','Batman (2012-2024) #73/18',73,NULL,'978-8-417-40157-3',NULL,'Tom King','Joelle Jones',NULL,NULL,'ECC Ediciones',NULL,'2018-04-04',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 34-35 USA, Batman Annual núm. 2 USA (one-shot)                       \r\nARGUMENTO: Los amigos y aliados de Batman piensan que se ha vuelto loco, embarcado en una misión que está, más que nunca, fuera de la ley. Lejos de Gotham, en medio de la nada, encontrará a un viejo enemigo... y a un montón de antiguos demonios. ¿Preparados para un duelo a muerte entre dos personajes históricos de la serie? Este ejemplar se completa con el segundo Anual de Batman. Lee Weeks (Batman/Elmer Fudd) colabora una vez más con Tom King para mostrarnos la primera cita de Bruce y Selina. Rivalidad. Romance. Rivalidad. ¡Amor de juventud con capas y capuchas! Y... sí, lo has adivinado: también hay un poco de lucha contra el crimen.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000898594-odghqc.jpg','read',0,NULL,NULL,'2026-04-12 13:34:59','2026-04-12 16:14:13',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Joelle Jones","role":"Dibujo, Tinta"},{"name":"Jordie Bellaire","role":"Color"},{"name":"Lee Weeks","role":"Dibujo, Tinta"},{"name":"Michael Lark","role":"Dibujo, Tinta"},{"name":"Elizabeth Breitweiser","role":"Color"},{"name":"June Chung","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1567,'Batman (2012-2024) #74/19','Batman (2012-2024) #74/19',74,NULL,'978-8-417-44134-0',NULL,'Tom King','Clay Mann',NULL,NULL,'ECC Ediciones',NULL,'2018-05-03',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 36-37 USA.            \r\nARGUMENTO: ¡Superamigos! Batman y Superman. Ya los conoces. Durante años han luchado juntos, en defensa de la justicia. A veces, incluso han peleado entre sí. Ahora, ha llegado el momento de redefinir la relación entre estos dos héroes, de regresar al ¿perdido? camino de la confianza y de la amistad. Sin la ayuda del otro, sus vidas se derrumbarán. Uno sigue siendo un rico niño mimado, y el otro un granjero ingenuo. Dos hombres. Dos mundos. ¿Habrá esperanza detrás de toda esta locura de capas y máscaras? Un punto ideal para engancharse a la colección del héroe de Gotham.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000901579-4p1q3g.jpg','read',0,NULL,NULL,'2026-04-12 13:35:02','2026-04-12 16:14:13',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Clay Mann","role":"Dibujo, Tinta"},{"name":"Seth Mann","role":"Tinta"},{"name":"Jordie Bellaire","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1568,'Batman (2012-2024) #75/20','Batman (2012-2024) #75/20',75,NULL,'978-8-417-44197-5',NULL,'Tom King','Travis Moore',NULL,NULL,'ECC Ediciones',NULL,'2018-06-05',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 38-39 USA         \r\nARGUMENTO: La impactante continuación de Superamigos. Tras su cita doble con Clark y Lois, es la relación entre Batman y Wonder Woman la que está ahora en peligro. Además, Tom King (El Sheriff de Babilonia) y Travis Moore (Fábulas: El lobo entre nosotros) reviven la tragedia de Bruce Wayne... en el presente. La búsqueda de un asesino enfrenta al Caballero Oscuro con una extraña y distorsionada versión de su propio pasado.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000904645-1lnoka.jpg','read',0,NULL,NULL,'2026-04-12 13:35:05','2026-04-12 16:14:05',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Travis Moore","role":"Dibujo, Tinta"},{"name":"Giulia Brusco","role":"Color"},{"name":"Joelle Jones","role":"Dibujo, Tinta"},{"name":"Jordie Bellaire","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1569,'Batman (2012-2024) #76/21','Batman (2012-2024) #76/21',76,NULL,'978-8-417-50917-0',NULL,'Tom King','Joelle Jones',NULL,NULL,'ECC Ediciones',NULL,'2018-07-03',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 40-41 USA         \r\nLa amistad entre Batman y Wonder Woman, parte fundamental de corazón del Universo DC, se desmorona. ¡La conclusión de Superamigos! Este ejemplar marca también el épico regreso del español Mikel Janín (Grayson) a los lápices, con la primera parte de Todo el mundo ama a Hiedra. La influencia de Pamela Isley, capaz de dominar a su antojo cualquier tipo de vegetación, puede extenderse por doquier, poniendo al mundo a sus pies. ¿Serán capaces Batman y Catwoman de defenderse ante un planeta dominado por Hiedra Venenosa?','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000907161-42d8w8.jpg','read',0,NULL,NULL,'2026-04-12 13:35:08','2026-04-12 16:14:05',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Joelle Jones","role":"Dibujo, Tinta"},{"name":"Jordie Bellaire","role":"Color"},{"name":"Mikel Janin","role":"Dibujo, Tinta"},{"name":"June Chung","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1570,'Batman (2012-2024) #77/22','Batman (2012-2024) #77/22',77,NULL,'978-8-417-53179-9',NULL,'Tom King','Mikel Janin',NULL,NULL,'ECC Ediciones',NULL,'2018-08-07',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 42-43 USA\r\n¡Tom King y Mikel Janin, los aclamados autores de La guerra de bromas y acertijos, presentan el desenlace de Todo el mundo ama a Hiedra! Hiedra Venenosa ha tomado el control de todos los hombres, mujeres y niños del planeta, y solo la pareja formada por Batman y Catwoman ha logrado escapar de su influencia. ¡Asiste al épico enfrentamiento entre el Cruzado de la Capa y uno de sus enemigos más populares!','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000909988-mj59ki.jpg','read',0,NULL,NULL,'2026-04-12 13:35:11','2026-04-12 16:14:05',186,NULL,'Grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo, Tinta"},{"name":"June Chung","role":"Color"},{"name":"Hugo Petrus","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1571,'Batman (2012-2024) #78/23','Batman (2012-2024) #78/23',78,NULL,'978-8-417-54937-4',NULL,'Tom King','Mikel Janin',NULL,NULL,'ECC Ediciones',NULL,'2018-09-04',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 44-45 USA\r\n¡El camino hacia La Boda! Los preparativos para la ceremonia más esperada del año han comenzado. ¡Descubrimos uno de los secretos mejor guardados, el vestido que lucirá Selina! Mientras, Bruce toma algunas decisiones cruciales para su futura vida en común. Pero esto es Gotham. Y nada sale nunca como se espera. ¿Has oído hablar de un tal Booster Gold? ¡Arranca El regalo, un trepidante arco argumental espacio-temporal, ilustrado por el aclamado Tony S. Daniel (Batman R.I.P.)','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000912709-23feqv.jpg','read',0,NULL,NULL,'2026-04-12 13:35:13','2026-04-12 16:14:05',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo, Tinta"},{"name":"Joelle Jones","role":"Dibujo, Tinta, Color"},{"name":"June Chung","role":"Color"},{"name":"Tony S. Daniel","role":"Dibujo, Tinta"},{"name":"John Livesay","role":"Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1572,'Batman (2012-2024) #79/24','Batman (2012-2024) #79/24',79,NULL,'978-8-417-61296-2',NULL,'Tom King','Tony S. Daniel',NULL,NULL,'ECC Ediciones',NULL,'2018-10-09',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 46-47 USA\r\nSi alguna vez Booster Gold decide darte un regalo de boda... ¡es mejor que te lo pienses dos veces antes de aceptar! El regalo de Booster ha arruinado el pasado de Batman y producido un montón de cambios en el presente. Ahora, con el Caballero Oscuro negándose a volver a trabajar en equipo, la única forma de que Booster arregle este desastre es poner a Catwoman de su parte. Solo hay un problema: si Batman no está haciendo lo que hace Batman, Gotham se vuelve más peligrosa que nunca... puede que hasta demasiado peligrosa para nuestro querido viajero temporal.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000916606-wphsvc.jpg','read',0,NULL,NULL,'2026-04-12 13:35:17','2026-04-12 16:14:05',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Tony S. Daniel","role":"Dibujo, Tinta"},{"name":"Sandu Florea","role":"Tinta"},{"name":"Tomeu Morey","role":"Color"},{"name":"Danny Miki","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1573,'Batman (2012-2024) #80/25','Batman (2012-2024) #80/25',80,NULL,'978-8-417-64466-6',NULL,'Tom King','Mikel Janin',NULL,NULL,'ECC Ediciones',NULL,'2018-11-06',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 48-49 USA\r\n¡El arco argumental que sirve de preludio a la Batboda, El Padrino! Ha ocurrido lo inevitable: el Joker ha descubierto que Batman y Catwoman van a casarse. ¿Acudirá con una oferta que no podrán rechazar? El enemigo más temible del Caballero Oscuro se dispone a interrumpir una fiesta a la que no ha sido invitado, y le toca a la propia Catwoman salvar el día.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000919966-643251.jpg','read',0,NULL,NULL,'2026-04-12 13:35:21','2026-04-12 16:14:05',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo, Tinta"},{"name":"June Chung","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1574,'Batman (2012-2024) #81/26','Batman (2012-2024) #81/26',81,NULL,'978-8-417-66521-0',NULL,'Tom King','Mikel Janin',NULL,NULL,'ECC Ediciones',NULL,'2018-12-04',NULL,NULL,replace(replace('Contiene Batman núm. 50 USA.\r\nHa llegado el día. ¡La boda que nunca pensaste que tendría lugar! La Batboda es real, y Bruce Wayne y Selina Kyle están preparados para pasar por el altar en un número especial conmemorativo, que cambiará para siempre el universo del Caballero Oscuro. ¿Invitados? ¡Todos sus amigos y unos pocos enemigos! Tom King, el guionista estrella de Mr. Milagro y El Sheriff de Babilonia, oficia las nupcias, acompañado de una alineación estelar de dibujantes de todas las épocas del personaje, liderada por el español Mikel Janín (Grayson).\r\nTambién disponible en edición especial limitada.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000923207-p3dw9y.jpg','read',0,NULL,NULL,'2026-04-12 13:35:24','2026-04-12 16:14:05',186,NULL,'Grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo, Tinta"},{"name":"José Luis García-López","role":"Dibujo, Tinta"},{"name":"Becky Cloonan","role":"Dibujo, Tinta, Color"},{"name":"Jason Fabok","role":"Dibujo, Tinta"},{"name":"Frank Miller","role":"Dibujo, Tinta"},{"name":"Lee Bermejo","role":"Dibujo, Tinta, Color"},{"name":"Neal Adams","role":"Dibujo, Tinta"},{"name":"Tony S. Daniel","role":"Dibujo, Tinta"},{"name":"Amanda Conner","role":"Dibujo, Tinta"},{"name":"Rafael Albuquerque","role":"Dibujo, Tinta, Color"},{"name":"Andy Kubert","role":"Dibujo, Tinta"},{"name":"Tim Sale","role":"Dibujo, Tinta"},{"name":"Paul Pope","role":"Dibujo, Tinta"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"},{"name":"Clay Mann","role":"Dibujo, Tinta"},{"name":"Ty Templeton","role":"Dibujo, Tinta"},{"name":"Joelle Jones","role":"Dibujo, Tinta"},{"name":"David Finch","role":"Dibujo, Tinta"},{"name":"Jim Lee","role":"Dibujo"},{"name":"Greg Capullo","role":"Dibujo, Tinta"},{"name":"Lee Weeks","role":"Dibujo, Tinta, Color"},{"name":"Scott Williams","role":"Tinta"},{"name":"June Chung","role":"Color"},{"name":"Patricia Mulvihill","role":"Color"},{"name":"Brad Anderson","role":"Color"},{"name":"Alex Sinclair","role":"Color"},{"name":"Hi-Fi Desing","role":"Color"},{"name":"Tomeu Morey","role":"Color"},{"name":"Paul Mounts","role":"Color"},{"name":"José Villarrubia","role":"Color"},{"name":"Jordie Bellaire","role":"Color"},{"name":"Keiren Smith","role":"Color"},{"name":"FCO Plascencia","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1575,'Batman (2012-2024) #82/27','Batman (2012-2024) #82/27',82,NULL,'978-8-417-66595-1',NULL,'Tom King','Lee Weeks',NULL,NULL,'ECC Ediciones',NULL,'2019-01-04',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núm. 51 a 53 USA\r\nEntrega especial, con el arco argumental Días fríos, que reúne al aclamado equipo creativo formado por Tom King y Lee Weeks, responsables de Batman/Elmer Fudd. Tras los impactantes sucesos de La Boda, el invierno ha llegado a Gotham. Bruce Wayne ha sido seleccionado para formar parte del jurado de un caso que involucra a uno de los mayores enemigos de Batman, Mr. Frío. ¡Para averiguar la verdad, Bruce tendrá que revisar la participación del Caballero Oscuro en los hechos! Mientras, alguien patrulla la ciudad disfrazado de Batman...','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000925809-vg31k1.jpg','read',0,NULL,NULL,'2026-04-12 13:35:26','2026-04-12 16:14:05',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Lee Weeks","role":"Dibujo, Tinta"},{"name":"Elizabeth Breitweiser","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1576,'Batman (2012-2024) #83/28','Batman (2012-2024) #83/28',83,NULL,'978-8-417-72286-9',NULL,'Tom King','Matt Wagner',NULL,NULL,'ECC Ediciones',NULL,'2019-02-05',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núm. 54 a 55 USA\r\n¡Regresa el Dúo Dinámico original! Dick Grayson, el primer Robin, ahora conocido como Nightwing, forma equipo con su mentor, Bruce Wayne, por primera vez tras Batman: La Boda. Bienvenidos a un paseo por el muchas veces tortuoso camino de los recuerdos, ilustrado por el legendario Matt Wagner (Batman: Rostros). Además, el asesino ruso conocido como la KGBestia ha regresado. ¡Todo parece indicar que su visita a Gotham tiene que ver con el famoso caso de Mr. Frío (Batman núm. 82/ 27)!','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000940529-1554nr.jpg','read',0,NULL,NULL,'2026-04-12 13:35:41','2026-04-12 16:14:05',186,NULL,'Grapa','[{"name":"Tom King","role":"Guion"},{"name":"Matt Wagner","role":"Dibujo, Tinta"},{"name":"Tomeu Morey","role":"Color"},{"name":"Tony S. Daniel","role":"Dibujo, Tinta"},{"name":"Danny Miki","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1577,'Batman (2012-2024) #110/55','Batman (2012-2024) #110/55',110,NULL,'978-8-418-66034-4',NULL,'James Tynion IV','Guillem March',NULL,NULL,'ECC Ediciones',NULL,'2021-05-11',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman: The Joker War Zone núm. 1 USA y Batman núm. 100 USA\r\n¡La guerra del Joker! La conclusión de una batalla que lleva librándose en tiempo real más de 80 años: Batman contra el Joker. El resultado no solo cambiará la vida de Batman, también la de todos los ciudadanos de Gotham. Este número incluye varias historias cortas centradas en la batalla callejera contra el Caballero Oscuro y sus aliados, protagonizadas por Cassandra Cain, Stephanie Brown y Luke Fox, junto a la presentación de un nuevo villano y un nuevo antihéroe que darán mucho que hablar en los próximos meses. ¡Entra en escena el Clownhunter!','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000975308-aqag0u.jpg','read',0,NULL,NULL,'2026-04-12 13:36:16','2026-04-12 16:14:05',186,NULL,'grapa','[{"name":"James Tynion IV","role":"Guion"},{"name":"John Ridley","role":"Guion"},{"name":"Joshua Williamson","role":"Guion"},{"name":"Sam Johns","role":"Guion"},{"name":"Guillem March","role":"Dibujo, Tinta"},{"name":"Olivier Coipel","role":"Dibujo, Tinta"},{"name":"David Lafuente","role":"Dibujo, Tinta"},{"name":"Laura Braga","role":"Dibujo, Tinta"},{"name":"James Stokoe","role":"Dibujo, Tinta, Color"},{"name":"Jorge Jiménez","role":"Dibujo, Tinta"},{"name":"Tomeu Morey","role":"Color"},{"name":"Matt Hollingsworth","role":"Color"},{"name":"Hi-Fi Desing","role":"Color"},{"name":"Antonio Fabela","role":"Color"},{"name":"Carlo Pagulayan","role":"Dibujo"},{"name":"Danny Miki","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1578,'Batman (2012-2024) #84/29','Batman (2012-2024) #84/29',84,NULL,'978-8-417-78742-4',NULL,'Tom King','Tony S. Daniel',NULL,NULL,'ECC Ediciones',NULL,'2019-03-05',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núm. 56 a 57 USA\r\nIncluso para una ciudad como Gotham, la violencia que ha desplegado la KGBestia ha superado el límite tolerable. El caos se adueña del hogar de Batman en una guerra fría que esconde un secreto todavía más brutal que la verdad sobre el juicio de Mr. Frío.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000982343-2yjypq.jpg','read',0,NULL,NULL,'2026-04-12 13:36:23','2026-04-12 16:14:05',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Tony S. Daniel","role":"Dibujo, Tinta"},{"name":"Danny Miki","role":"Tinta"},{"name":"Tomeu Morey","role":"Color"},{"name":"Mark Buckingham","role":"Dibujo"},{"name":"Andrew Pepoy","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1579,'Batman (2012-2024) #85/30','Batman (2012-2024) #85/30',85,NULL,'978-8-417-82723-6',NULL,'Tom King','Mikel Janin',NULL,NULL,'ECC Ediciones',NULL,'2019-04-02',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núm. 58 a 59 USA, Batman: Secret Files núm. 1 USA (extracto)\r\nUn número marcado por el regreso del dibujante Mikel Janín (Grayson), que además incluye una historia corta procedente del especial Batman: Secret Files núm. 1 USA (2018), dibujada por el propio Janín. Un oscuro enemigo se interpone entre Batman y el Pingüino. Es el momento de que Oswald tome una decisión: o se pone del lado del Caballero Oscuro, o termina muerto. La vida, o la cárcel. La elección parece obvia...','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000985134-qb7bdc.jpg','read',0,NULL,NULL,'2026-04-12 13:36:25','2026-04-12 16:14:05',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo, Tinta"},{"name":"Jordie Bellaire","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1580,'Batman (2012-2024) #86/31','Batman (2012-2024) #86/31',86,NULL,'978-8-417-87109-3',NULL,'Tom King','Mikel Janin',NULL,NULL,'ECC Ediciones',NULL,'2019-05-07',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núm. 60 USA, Batman Annual núm. 3 USA\r\nEl Pingüino está en el punto de mira de otros villanos. ¿La solución? ¡Aliarse con Batman! El delincuente emplumado recurre a su estimado enemigo para protegerse. Este ejemplar incluye también el tercer Anual de la serie, escrito por Tom Taylor (Injustice: Gods among us) y dibujado por Otto Schmidt (Green Arrow). ¡Llega el momento de echar un vistazo a la cruzada del Caballero Oscuro desde el punto de vista de su más fiel aliado, Alfred!','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000987576-m9sqtf.jpg','read',0,NULL,NULL,'2026-04-12 13:36:28','2026-04-12 16:14:05',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo, Tinta"},{"name":"Jorge Fornés","role":"Dibujo, Tinta"},{"name":"Jordie Bellaire","role":"Color"},{"name":"Tom Taylor","role":"Guion"},{"name":"Otto Schmidt","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1581,'Batman (2012-2024) #87/32','Batman (2012-2024) #87/32',87,NULL,'978-8-417-87173-4',NULL,'Tom King','Mikel Janin',NULL,NULL,'ECC Ediciones',NULL,'2019-06-04',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 61-63 USA\r\n¡Número especial con tres ejemplares USA! ¡Los ganadores del premio Eisner por Mr. Milagro vuelven a la carga! Mitch Gerads forma equipo con Tom King, ¡y trae consigo al despiadado Profesor Pyg! ¡Eso significa que las cosas están a punto de ponerse muy raras y sangrientas! Los extraños acontecimientos que asolan Gotham llevarán al Caballero Oscuro a colaborar con un mermado John Constantine... Además,Travis Moore también vuelve a la serie para cerrar la historia iniciada en Batman núm. 75/ 20.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000989580-wgwj0l.jpg','read',0,NULL,NULL,'2026-04-12 13:36:30','2026-04-12 16:14:05',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo"},{"name":"Mitch Gerads","role":"Dibujo"},{"name":"Travis Moore","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1582,'Batman (2012-2024) #88/33','Batman (2012-2024) #88/33',88,NULL,'978-8-417-90839-3',NULL,'Joshua Williamson','Guillem March',NULL,NULL,'ECC Ediciones',NULL,'2019-07-02',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núm. 64 USA y The Flash núm. 64 USA \r\n¡La primera parte de Batman/Flash: El precio! Tom King, el guionista del evento DC del año, embarca a Batman y Flash en un crossover paralelo a Héroes en Crisis. Escrito por Joshua Williamsom (Deathbed), con la colaboración estelar de los dibujantes españoles Guillem March, Rafa Sandoval y Jordi Tarragona, los dos mejores detectives del Universo DC afrontan una investigación que los llevará ante sus demonios interiores y a descubrir los secretos más oscuros de la Liga de la Justicia. ¿Y qué papel juega Gotham Girl en todo esto? La historia finaliza este mes en las páginas de Flash núm. 47/ 33.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000992140-42f677.jpg','read',0,NULL,NULL,'2026-04-12 13:36:33','2026-04-12 16:14:05',186,NULL,'grapa','[{"name":"Joshua Williamson","role":"Guion"},{"name":"Guillem March","role":"Dibujo"},{"name":"Jordi Tarragona","role":"Dibujo"},{"name":"Rafa Sandoval","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1583,'Batman (2012-2024) #89/34','Batman (2012-2024) #89/34',89,NULL,'978-8-417-90884-3',NULL,'Tom King','Jorge Fornés',NULL,NULL,'ECC Ediciones',NULL,'2019-08-06',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 66 a 67 USA\r\n¡Las Pesadillas continúan! Algo o alguien está obligando a Batman a vivir sus miedos más profundos, amplificando la ansiedad del Caballero Oscuro y recreando sus peores traumas. Ahora que Batman ha descubierto la verdad, debe encontrar la fuente de estas pesadillas. ¡Y su mejor opción es hacer las preguntas correctas! ¡Question entra en escena! Pero, ¿es Vic Sage real o es un producto más de su imaginación? Jorge Fornés (Doctor Extraño) y Lee Weeks (Batman/Elmer Fudd) regresan a la serie en una carrera imposible por los tejados, por los callejones y por la mente del protector de Gotham.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000994588-flpvxr.jpg','read',0,NULL,NULL,'2026-04-12 13:36:35','2026-04-12 16:14:05',186,NULL,'Grapa','[{"name":"Tom King","role":"Guion"},{"name":"Jorge Fornés","role":"Dibujo, Tinta"},{"name":"Dave Stewart","role":"Color"},{"name":"Lee Weeks","role":"Dibujo, Tinta"},{"name":"Lovern Kindzierski","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1584,'Batman (2012-2024) #90/35','Batman (2012-2024) #90/35',90,NULL,'978-8-417-96058-2',NULL,'Tom King','Amanda Conner',NULL,NULL,'ECC Ediciones',NULL,'2019-09-03',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 68 a 69 USA\r\nEl desenlace de Pesadillas. Última parada: una fiesta que nunca fue. Una vez más, el corazón del Cruzado de la Capa se encoge al asomarnos a la que pudo ser la fiesta de despedida de soltera de Catwoman. Y después... el último baile y el futuro de Batman. Con la participación estelar de los dibujantes Amanda Conner (Harley Quinn), Dan Panosian (Flash), John Timms (Una cita con Harley), Mikel Janín (Grayson) y Yanick Paquette (Wonder Woman: Tierra uno).','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776000997057-dvvavs.jpg','read',0,NULL,NULL,'2026-04-12 13:36:38','2026-04-12 16:14:05',186,NULL,'Grapa','[{"name":"Tom King","role":"Guion"},{"name":"Amanda Conner","role":"Dibujo"},{"name":"Dan Panosian","role":"Dibujo"},{"name":"John Timms","role":"Dibujo, Color"},{"name":"Mikel Janin","role":"Dibujo"},{"name":"Paul Mounts","role":"Color"},{"name":"Jordie Bellaire","role":"Color"},{"name":"Yanick Paquette","role":"Dibujo"},{"name":"Nathan Fairbairn","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1585,'Batman (2012-2024) #91/36','Batman (2012-2024) #91/36',91,NULL,'978-8-418-02672-0',NULL,'Tom King','Mikel Janin',NULL,NULL,'ECC Ediciones',NULL,'2019-10-15',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 70 a 71 USA\r\nLas pesadillas han dejado paso a la verdad: ¡la mayor conspiración jamás orquestada en contra del Caballero Oscuro está al descubierto! ¿Quién maneja los hilos? Y, lo más intrigante, ¿qué hace su padre de otro universo en las fuerzas enemigas? Es el momento de profundizar en el misterio del regreso de Thomas Wayne, más conocido como el Caballero de la Venganza, el Batman de Flashpoint. ¡El camino hacia el siguiente gran evento del Hombre Murciélago empieza aquí!','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001003575-781wz5.jpg','read',0,NULL,NULL,'2026-04-12 13:36:44','2026-04-12 16:14:05',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo, Tinta"},{"name":"Jorge Fornés","role":"Dibujo, Tinta"},{"name":"Jordie Bellaire","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1586,'Batman (2012-2024) #92/37','Batman (2012-2024) #92/37',92,NULL,'978-8-418-04349-9',NULL,'Tom King','Mikel Janin',NULL,NULL,'ECC Ediciones',NULL,'2019-11-12',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 72 a 73 USA\r\nLa boda fallida. El intento de asesinato de Nigthwing. Las Pesadillas del Caballero Oscuro. El odio de Bane nos ha llevado hasta aquí. Con el Hombre Murciélago contra las cuerdas, sólo un hombre parece tener la llave de los secretos. Un Batman de otro mundo. Un Caballero de la Venganza. Thomas Wayne.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001006392-lgu2qs.jpg','read',0,NULL,NULL,'2026-04-12 13:36:47','2026-04-12 16:14:05',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo, Tinta"},{"name":"Jorge Fornés","role":"Dibujo, Tinta"},{"name":"Jordie Bellaire","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1587,'Batman (2012-2024) #93/38','Batman (2012-2024) #93/38',93,NULL,'978-8-418-09409-5',NULL,'Tom King','Mikel Janin',NULL,NULL,'ECC Ediciones',NULL,'2019-12-10',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 74 a 75 USA\r\n¡El principio del fin de la etapa del guionista Tom King empieza aquí! Tras el encuentro entre padre e hijo, Bane y sus secuaces han tomado el control de Gotham y gobiernan la ciudad con puño de hierro. ¿Dónde está Batman? Sin el Caballero Oscuro, parece que la verdadera Gotham ha sido reemplazada por una versión retorcida de sí misma... ¡bienvenidos a la Ciudad de Bane!','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001009524-bopefm.jpg','read',0,NULL,NULL,'2026-04-12 13:36:50','2026-04-12 16:14:05',186,NULL,'Grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo, Tinta"},{"name":"Tony S. Daniel","role":"Dibujo, Tinta"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"},{"name":"Jordie Bellaire","role":"Color"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1588,'Batman (2012-2024) #94/39','Batman (2012-2024) #94/39',94,NULL,'978-8-418-09490-3',NULL,'Tom King','Mikel Janin',NULL,NULL,'ECC Ediciones',NULL,'2020-01-09',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 76 a 77 USA\r\nRECTA FINAL DE LA ETAPA DE TOM KING. Sigue La ciudad de Bane. ¡Bane se ha apoderado de Gotham y Batman ha desaparecido! O, al menos, el Batman que todos conocemos. En su ausencia, otro Hombre Murciélago patrulla las calles e impone su violenta justicia: Thomas Wayne, el Batman de Flashpoint. Sin embargo, no todo está saliendo como Bane había planeado. Hay algunos villanos que todavía no se han sometido a la nueva ley. Una rebelión crece y un héroe está a punto de hacer su reentrada.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001012428-k5dl9j.jpg','read',0,NULL,NULL,'2026-04-12 13:36:53','2026-04-12 16:14:05',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo"},{"name":"Tony S. Daniel","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1589,'Batman (2012-2024) #95/40','Batman (2012-2024) #95/40',95,NULL,'978-8-418-12040-4',NULL,'Tom King','Clay Mann',NULL,NULL,'ECC Ediciones',NULL,'2020-02-04',NULL,NULL,replace(replace('EDICIÓN ORIGINAL:  Batman 78 al 79 USA\r\nSigue La ciudad de Bane. ¡Interludio! Batman recibe ayuda de una aliada inesperada: ¡Catwoman está de vuelta! Con el apoyo de Selina, el Caballero Oscuro se recupera de las heridas infringidas por Bane y por su padre de otro universo, Thomas Wayne, el Caballero de la Venganza. ¿Es el inicio del fin del reinado del terror de Bane? ¿Serán felices al fin la Gata y el Murciélago?','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001015031-kzguep.jpg','read',0,NULL,NULL,'2026-04-12 13:36:56','2026-04-12 16:14:05',186,NULL,'Grapa','[{"name":"Tom King","role":"Guion"},{"name":"Clay Mann","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1590,'Batman (2012-2024) #96/41','Batman (2012-2024) #96/41',96,NULL,'978-8-418-18033-0',NULL,'Tom King','John Romita Jr.',NULL,NULL,'ECC Ediciones',NULL,'2020-03-03',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 80 a 81 USA\r\n¡Nos acercamos al desenlace de La ciudad de Bane! Los villanos pensaban que, liderados por Bane, Gotham sería suya para siempre. Pero se equivocaban. El verdadero Batman está de vuelta, dispuesto a recordarles qué ocurre cuando la justicia te golpea directamente en el rostro. Con Catwoman a su lado, es la hora del gran enfrentamiento. ¿Está listo el Caballero Oscuro para enfrentarse al hombre que lo rompió? ¿Qué sucede cuando antiguas aliadas como Gotham Girl también se interponen en su camino? Con dibujo de los maestros John Romita Jr. (Superman) y Klaus Janson (Batman: Caballero Oscuro III: La raza superior).','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001017824-p7l2wy.jpg','read',0,NULL,NULL,'2026-04-12 13:36:58','2026-04-12 16:14:05',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"John Romita Jr.","role":"Dibujo"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"},{"name":"Klaus Janson","role":"Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1591,'Batman (2012-2024) #97/42','Batman (2012-2024) #97/42',97,NULL,'978-8-418-22506-2',NULL,'Tom King','Mikel Janin',NULL,NULL,'ECC Ediciones',NULL,'2020-06-03',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 82 a 83 USA\r\nGuerra en La ciudad de Bane! Batman y sus aliados se enfrentan al ejército de Bane, pero un giro inesperado hará que todo el plan se derrumbe. ¿Habrá otra muerte en la familia? ¿Qué fuerzas operan en las sombras? Es el momento de tomar una decisión crucial: ¡dejar que Bane permanezca en el poder y garantizar el futuro de Gotham, o arriesgar todo por la libertad!','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001020255-azx2v2.jpg','read',0,NULL,NULL,'2026-04-12 13:37:01','2026-04-12 16:14:05',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1592,'Batman (2012-2024) #98/43','Batman (2012-2024) #98/43',98,NULL,'978-8-418-22575-8',NULL,'Tom King','Jorge Fornés',NULL,NULL,'ECC Ediciones',NULL,'2020-06-30',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 84-85 USA\r\nLa extraordinaria conclusión de La ciudad de Bane y de la etapa de Tom King como guionista de la serie mensual del Caballero Oscuro. Es la batalla final por Gotham City y por el derecho a portar la capucha del Murciélago. ¿Qué será de Gotham Girl? ¿Cómo se las arreglará la Batfamilia sin Alfred? ¿Batman volverá a ser Batman? Un camino completamente nuevo se abre para el Mejor Detective del Mundo. ¡Todo conduce a la futura miniserie Batman/Catwoman!','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001022883-xzhgmr.jpg','read',0,NULL,NULL,'2026-04-12 13:37:04','2026-04-12 16:14:05',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Jorge Fornés","role":"Dibujo, Tinta"},{"name":"Mikel Janin","role":"Dibujo, Tinta"},{"name":"Hugo Petrus","role":"Dibujo, Tinta"},{"name":"Jordie Bellaire","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1593,'Batman (2012-2024) #99/44','Batman (2012-2024) #99/44',99,NULL,'978-8-418-29341-2',NULL,'James Tynion IV','Tony S. Daniel',NULL,NULL,'ECC Ediciones',NULL,'2020-07-28',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 86-87 USA\r\nAmanece un nuevo día en Gotham. Con Bane derrotado y Alfred fallecido, el Caballero Oscuro afronta la reconstrucción de la ciudad, ¡y la de su propia cruzada! Bruce tiene un nuevo plan, pero no es el único. Deathstroke también está de vuelta, con un contrato bajo el brazo que podría cambiarlo todo. ¡Es la nueva etapa del Hombre Murciélago, con el guionista James Tynion IV (Batman: Detective Comics) y los dibujantes Tony S. Daniel (Batman: La batalla por la capucha) y Guillem March (Musas de Gotham)!','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001025238-bf4xgd.jpg','read',0,NULL,NULL,'2026-04-12 13:37:06','2026-04-12 16:14:05',186,NULL,'Grapa','[{"name":"James Tynion IV","role":"Guion"},{"name":"Tony S. Daniel","role":"Dibujo"},{"name":"Danny Miki","role":"Tinta"},{"name":"Tomeu Morey","role":"Color"},{"name":"Guillem March","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1594,'Batman (2012-2024) #100/45','Batman (2012-2024) #100/45',100,NULL,'978-8-418-29320-7',NULL,'Tom King','Jorge Fornés',NULL,NULL,'ECC Ediciones',NULL,'2020-08-11',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman Annual núm. 4 USA, Batman: Pennyworth R.I.P. núm. 1 USA\r\nEspecial aniversario con motivo de las 100 entregas de Batman publicadas por ECC Ediciones. La muerte de Alfred a manos de Bane ha dejado a Batman en una encrucijada similar a la tragedia familiar que provocó su origen. Alfred era el pegamento que mantenía unida a la Batfamilia. ¿Qué pasará ahora? ¿Colgar la capa o continuar la lucha? Además, el último Anual de Tom King (Mr. Milagro) responde a la pregunta que te has hecho siempre: ¿cómo es ser Batman día a día?','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001027793-9kd5d2.jpg','read',0,NULL,NULL,'2026-04-12 13:37:08','2026-04-12 16:14:05',186,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"James Tynion IV","role":"Guion"},{"name":"Peter J. Tomasi","role":"Guion"},{"name":"Jorge Fornés","role":"Dibujo, Tinta"},{"name":"Mike Norton","role":"Dibujo, Tinta"},{"name":"Eddy Barrows","role":"Dibujo"},{"name":"Chris Burnham","role":"Dibujo"},{"name":"Marcio Takara","role":"Dibujo"},{"name":"Diógenes Neves","role":"Dibujo"},{"name":"David Lafuente","role":"Dibujo"},{"name":"Sumit Kumar","role":"Dibujo"},{"name":"Eber Ferreira","role":"Dibujo"},{"name":"Dave Stewart","role":"Color"},{"name":"Nathan Fairbairn","role":"Color"},{"name":"Rex Lokus","role":"Color"},{"name":"Adriano Lucas","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1595,'Batman (2012-2024) #101/46','Batman (2012-2024) #101/46',101,NULL,'978-8-418-32672-1',NULL,'James Tynion IV','Guillem March',NULL,NULL,'ECC Ediciones',NULL,'2020-09-16',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núm. 88 USA\r\n¡El Caballero Oscuro visita el Asilo Arkham en busca de respuestas! Allí le espera el Pingüino y una nueva etapa de la conspiración que está a punto de sacudir su mundo. ¿Qué oscuro secreto comparte Oswald Cobblepot con el Joker, el Acertijo... y Catwoman? Los problemas se acumulan cuando Deathstroke entra escena. Y no está solo...','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001030366-szdloj.jpg','read',0,NULL,NULL,'2026-04-12 13:37:11','2026-04-12 16:14:05',186,NULL,'grapa','[{"name":"James Tynion IV","role":"Guion"},{"name":"Guillem March","role":"Dibujo, Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1596,'Batman (2012-2024) #102/47','Batman (2012-2024) #102/47',102,NULL,'978-8-418-38208-6',NULL,'James Tynion IV','Guillem March',NULL,NULL,'ECC Ediciones',NULL,'2020-10-06',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núm. 89 USA\r\nMisión: ¡detener a Deathstroke antes de que mate al alcalde de Gotham City! ¿Quién ha ordenado el asesinato? Si los cuatro sospechosos principales no confiesan, ¿eso significa que hay un quinto culpable, todavía más siniestro, preparando el golpe de gracia? Quienquiera que sea, una víctima está a punto de caer en sus garras...','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001033378-wctz0c.jpg','read',0,NULL,NULL,'2026-04-12 13:37:14','2026-04-12 16:14:05',186,NULL,'grapa','[{"name":"James Tynion IV","role":"Guion"},{"name":"Guillem March","role":"Dibujo"},{"name":"Carlo Pagulayan","role":"Dibujo"},{"name":"Danny Miki","role":"Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1597,'Batman (2012-2024) #103/48','Batman (2012-2024) #103/48',103,NULL,'978-8-418-38238-3',NULL,'James Tynion IV','Guillem March',NULL,NULL,'ECC Ediciones',NULL,'2020-10-27',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núm. 90 USA\r\n¡Con dibujo de la estrella española de DC Comics, Jorge Jiménez (Superhijos, Liga de la Justicia)! Una mente maestra ha reunido a lo peor de Gotham City para llevar a cabo el crimen perfecto, ¡y las consecuencias se están dejando notar por toda la ciudad! Batman hará todo lo posible por sacar a la luz su verdadero propósito, pero parece que es Catwoman la que esconde todas las respuestas...','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001035748-gs8e3l.jpg','read',0,NULL,NULL,'2026-04-12 13:37:16','2026-04-12 16:14:05',186,NULL,'grapa','[{"name":"James Tynion IV","role":"Guion"},{"name":"Guillem March","role":"Dibujo"},{"name":"Carlo Pagulayan","role":"Dibujo"},{"name":"Danny Miki","role":"Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1598,'Batman (2012-2024) #104/49','Batman (2012-2024) #104/49',104,NULL,'978-8-418-38275-8',NULL,'James Tynion IV','Rafael Albuquerque',NULL,NULL,'ECC Ediciones',NULL,'2020-11-17',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núm. 91 USA\r\nHay una forma de salvar Gotham City, ¡pero para hacerlo, Catwoman tendrá que llevar a cabo el mayor atraco en la historia de la ciudad! Todos persiguen a la Gata: los maestros del crimen... y el hombre al que trata de ayudar, Batman. Y en medio del caos... ¡Harley Quinn!','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001038187-as0t1a.jpg','read',0,NULL,NULL,'2026-04-12 13:37:18','2026-04-12 16:14:05',186,NULL,'Grapa','[{"name":"James Tynion IV","role":"Guion"},{"name":"Rafael Albuquerque","role":"Dibujo, Tinta"},{"name":"Jorge Jiménez","role":"Dibujo, Tinta"},{"name":"Carlo Pagulayan","role":"Dibujo, Tinta"},{"name":"Danny Miki","role":"Dibujo, Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1599,'Batman (2012-2024) #105/50','Batman (2012-2024) #105/50',105,NULL,'978-8-418-47514-6',NULL,'James Tynion IV','Guillem March',NULL,NULL,'ECC Ediciones',NULL,'2020-12-16',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núm. 92 USA\r\nEl Designador ha orquestado el mayor atraco de la historia de Gotham City. Batman tiene todos los detalles del plan y está preparado para detener el complot, ¡pero primero debe escapar de la trampa más ingeniosa jamás pergeñada por el Acertijo!','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001040033-x61msr.jpg','read',0,NULL,NULL,'2026-04-12 13:37:21','2026-04-12 16:14:05',186,NULL,'grapa','[{"name":"James Tynion IV","role":"Guion"},{"name":"Guillem March","role":"Dibujo, Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1600,'Batman (2012-2024) #106/51','Batman (2012-2024) #106/51',106,NULL,'978-8-418-47546-7',NULL,'James Tynion IV','Guillem March',NULL,NULL,'ECC Ediciones',NULL,'2021-01-12',NULL,NULL,replace('EDICIÓN ORIGINAL: Batman núms. 93-94 USA\rBatman contra el Designador. En el último año, el Caballero Oscuro ha sufrido varias pérdidas inimaginables que han cambiado el curso de su vida. ¿Puede haber algo peor en el horizonte? Los tambores de la batalla suenan en el horizonte. La guerra del Joker está a punto de estallar y Gotham City nunca volverá a ser igual. Batman se enfrenta en solitario a uno de los mayores retos de su carrera.','\r',char(13)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001042663-psaphz.jpg','read',0,NULL,NULL,'2026-04-12 13:37:23','2026-04-12 16:14:05',186,NULL,'grapa','[{"name":"James Tynion IV","role":"Guion"},{"name":"Guillem March","role":"Dibujo, Tinta"},{"name":"Javi Fernández","role":"Dibujo, Tinta"},{"name":"Tomeu Morey","role":"Color"},{"name":"David Baron","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1601,'Batman (2012-2024) #107/52','Batman (2012-2024) #107/52',107,NULL,'978-8-418-56912-8',NULL,'Vita Ayala','Andie Tong',NULL,NULL,'ECC Ediciones',NULL,'2021-02-09',NULL,NULL,replace(replace('EDICIÓN ORIGINAL:  Batman Secret Files núm. 3 USA y Batman núm. 95 USA\r\n¡La guerra del Joker comienza aquí! Sabíamos que llegaría este día. El Príncipe Payaso del Crimen y el Caballero Oscuro se enfrentan por última vez. Durante años, el Joker avivó el enfrentamiento, alargando el sufrimiento del héroe de Gotham. Pero ahora su motivación ha cambiado. Ha decidido que, de una manera u otra, este será el último capítulo de su historia personal. Incluye varias historias cortas en las que el Caballero Oscuro hace frente a algunos de los asesinos más letales del Universo DC.','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001045160-08limu.jpg','read',0,NULL,NULL,'2026-04-12 13:37:26','2026-04-12 16:14:05',186,NULL,'grapa','[{"name":"Vita Ayala","role":"Guion"},{"name":"Phillip Kennedy","role":"Guion"},{"name":"Mariko Tamaki","role":"Guion"},{"name":"Dan Watters","role":"Guion"},{"name":"James Tynion IV","role":"Guion"},{"name":"Andie Tong","role":"Dibujo, Tinta"},{"name":"Victor Ibañez","role":"Dibujo, Tinta"},{"name":"Riley Rossmo","role":"Dibujo, Tinta"},{"name":"John Paul Leon","role":"Dibujo, Tinta, Color"},{"name":"Sumit Kumar","role":"Dibujo, Tinta"},{"name":"Jorge Jiménez","role":"Dibujo, Tinta"},{"name":"Alejandro Sánchez","role":"Color"},{"name":"Jordie Bellaire","role":"Color"},{"name":"Ivan Plascencia","role":"Color"},{"name":"FCO Plascencia","role":"Color"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1602,'Batman (2012-2024) #108/53','Batman (2012-2024) #108/53',108,NULL,'978-8-418-56973-9',NULL,'James Tynion IV','Jorge Jiménez',NULL,NULL,'ECC Ediciones',NULL,'2021-03-09',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 96-97 USA y Harley Quinn núm. 75 USA (Extracto)\r\n¡La guerra del Joker! El plan del Príncipe Payaso del Crimen sigue adelante. Batman debe mantener intacta su cordura si quiere recuperar su vida y su ciudad. Pero, ¿cómo puede librarse de los fantasmas del pasado, que acechan en el presente? ¿Quién puede proporcionarle la ayuda que necesita? Mientras, Catwoman y el resto de villanos de Gotham entran en acción. Este número incluye una historia corta ilustrada por Riley Rossmo (The Hellblazer): ¡Harley Quinn contra Punchline!','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001047619-sn3ow2.jpg','read',0,NULL,NULL,'2026-04-12 13:37:28','2026-04-12 16:14:05',186,NULL,'grapa','[{"name":"James Tynion IV","role":"Guion"},{"name":"Sam Humphries","role":"Guion"},{"name":"Jorge Jiménez","role":"Dibujo, Tinta"},{"name":"Riley Rossmo","role":"Dibujo, Tinta"},{"name":"Tomeu Morey","role":"Color"},{"name":"Ivan Plascencia","role":"Color"},{"name":"Guillem March","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1603,'Batman (2012-2024) #109/54','Batman (2012-2024) #109/54',109,NULL,'978-8-418-65858-7',NULL,'James Tynion IV','Jorge Jiménez',NULL,NULL,'ECC Ediciones',NULL,'2021-04-14',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman núms. 98-99 USA y Nightwing núm. 74 USA\r\n¡La guerra del Joker! Batman ha recibido una dosis casi letal de la nueva toxina del Joker. ¡Es el momento de buscar nuevas alianzas! El Caballero Oscuro no puede ganar esta guerra solo. ¿Quién acudirá a la llamada? ¿De qué lado estará el hombre antes conocido como Dick Grayson?','\r',char(13)),'\n',char(10)),NULL,NULL,360,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001050256-qjrhhd.jpg','read',0,NULL,NULL,'2026-04-12 13:37:31','2026-04-12 16:14:05',186,NULL,'grapa','[{"name":"James Tynion IV","role":"Guion"},{"name":"Dan Jurgens","role":"Guion"},{"name":"Jorge Jiménez","role":"Dibujo, Tinta"},{"name":"Ryan Benjamin","role":"Dibujo"},{"name":"Richard Friend","role":"Tinta"},{"name":"Tomeu Morey","role":"Color"},{"name":"Rain Beredo","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1604,'Superman (2012-2024) #1','Superman (2012-2024)',1,NULL,'978-8-415-52064-1',NULL,'Grant Morrison','Rags Morales',NULL,NULL,'ECC Ediciones',NULL,'2012-05-01',NULL,NULL,replace(replace('Contiene: Action Comics v2 #1 - 2 USA \r\nLa historia hasta aquí:\r\nEl velocista Barry Allen despertó en un mundo que apenas reconocía: desprovisto de poderes y ante la brutal contienda que enfrentaba a atlantes y amazonas, buscó recuperar su conexión con la Fuerza de la Velocidad. Ya como Flash, en su empeño por restablecer la normalidad contó con la colaboración del Sujeto Uno: un Superman mermado debido al confinamiento en instalaciones militares, sufrido desde que aterrizó en la Tierra procedente de Krypton. Debilitado y confuso, logró sobreponerse para derrotar a una desquiciada Encantadora. Finalmente, tras la asunción de un doloroso sacrificio personal por parte de Barry, se restauró una realidad ligeramente diferente a la que todos conocíamos, en la que un joven Clark Kent da sus primeros pasos como Superman, héroe de Metropolis.','\r',char(13)),'\n',char(10)),NULL,NULL,256,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001060818-q926ze.jpg','read',0,NULL,NULL,'2026-04-12 13:37:44','2026-04-12 16:14:05',187,NULL,'Grapa','[{"name":"Grant Morrison","role":"Guion"},{"name":"Rags Morales","role":"Dibujo"},{"name":"Rick Bryant","role":"Tinta"},{"name":"Brent Eric Anderson","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1605,'Superman (2012-2024) #17','Superman (2012-2024)',17,NULL,'978-8-415-92529-3',NULL,'Grant Morrison','Brad Walker',NULL,NULL,'ECC Ediciones',NULL,'2013-09-01',NULL,NULL,replace(replace('EDICION ORIGINAL: Action Comics v2 #18 USA \r\nARGUMENTO: La historia de la señora Nyxly, la casera de Clark Kent, dio un giro de 180º cuando confesó ser una princesa de Zrfff, mundo de la 5a Dimensión, cuyo amor por el joven mago llamado Mxyzptlk fue truncado por el malvado Vyndktvx, otro poderoso ser de su mundo que, en el pasado, habría acabado también con el planeta Krypton si no hubiera sido derrotado por Jor-El. Ahora, Vyndktvx se está vengando de Superman atacándolo en todos los momentos de su historia al mismo tiempo simultáneamente con la ayuda de diferentes villanos que ha reclutado, y en este número el Hombre de Acero está a punto de librar que ha reclutadola batalla definitiva en la que se decidirá su propia existencia.','\r',char(13)),'\n',char(10)),NULL,NULL,256,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001071325-4to65y.jpg','read',0,NULL,NULL,'2026-04-12 13:37:52','2026-04-12 16:14:05',187,NULL,'Grapa','[{"name":"Grant Morrison","role":""},{"name":"Brad Walker","role":""},{"name":"Rags Morales","role":""},{"name":"Andrew Hennessy","role":""},{"name":"Cam Smith","role":""},{"name":"Sholly Fisch","role":""},{"name":"Chris Sprouse","role":""},{"name":"Karl Story","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1606,'Superman (2012-2024) #2','Superman (2012-2024)',2,NULL,'978-8-415-52087-0',NULL,'Grant Morrison','Brad Walker',NULL,NULL,'ECC Ediciones',NULL,'2012-06-01',NULL,NULL,replace(replace('Contiene: Action Comics v2 #3 - 4 USA \r\nLa historia hasta aquí:\r\nEl primer enemigo con superpoderes del Hombre de Acero: ¡John Corben! Pero ¿actúa este fiel soldado por voluntad propia o es una mera marioneta de alguna amenaza mucho más poderosa?','\r',char(13)),'\n',char(10)),NULL,NULL,256,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001074699-3psnr2.jpg','read',0,NULL,NULL,'2026-04-12 13:37:55','2026-04-12 16:14:05',187,NULL,'grapa','[{"name":"Grant Morrison","role":""},{"name":"Brad Walker","role":""},{"name":"Gene Ha","role":""},{"name":"Rags Morales","role":""},{"name":"Rick Bryant","role":""},{"name":"Sean Parsons","role":""},{"name":"Sholly Fisch","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1607,'Superman (2012-2024) #3','Superman (2012-2024)',3,NULL,'978-8-415-62812-5',NULL,'Grant Morrison','Sholly Fisch',NULL,NULL,'ECC Ediciones',NULL,'2012-07-01',NULL,NULL,replace(replace('Contiene: Action Comics v2 #7 - 8 USA\r\nLa historia hasta aquí:\r\nAbrumado por pesadillas relacionadas con Krypton y sorprendido por la actitud de ciudadanos de Metrópolis temerosos de su naturaleza alienígena, Clark comenzó a dudar acerca de su incipiente carrera superheroica. Sin apenas tiempo para reaccionar, siguió las indicaciones de un misterioso informante, acudiendo como reportero a una fabrica; allí se desencadenó un ataque perpetrado por los Terminautas, a quienes se sumó un irreconocible John Corben. Superman encontró ayuda en Steel, pero su esfuerzo no pudo evitar la desaparición de parte de Metrópolis…','\r',char(13)),'\n',char(10)),NULL,NULL,256,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001076939-23qmvp.jpg','read',0,NULL,NULL,'2026-04-12 13:37:58','2026-04-12 16:14:05',187,NULL,'Grapa','[{"name":"Grant Morrison","role":""},{"name":"Sholly Fisch","role":""},{"name":"Brad Walker","role":""},{"name":"Rags Morales","role":""},{"name":"Rick Bryant","role":""},{"name":"Bob McLeod","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1608,'Superman (2012-2024) #4','Superman (2012-2024)',4,NULL,'978-8-415-62838-5',NULL,'Grant Morrison','Sholly Fisch',NULL,NULL,'ECC Ediciones',NULL,'2012-08-01',NULL,NULL,replace(replace('Contiene: Action Comics v2 #5 - 6 USA \r\nLa historia hasta aquí:\r\nDurante su primera gran aventura, Superman logró desbaratar los planes de Brainiac: en su afán por completar la macabra colección que atesora, la  inteligencia artificial alienígena utilizó no solo a Lex Luthor, sino también a los letales Terminautas y a un John Corben dispuesto a todo con tal de llamar la atención de Lois Lane. Pero finalmente Clark derrotó a su enemigo, ganándose el respeto y agradecimiento de los ciudadanos de Metrópolis y convenciendo a la Señora Nyxly de que no revelara su identidad secreta.','\r',char(13)),'\n',char(10)),NULL,NULL,256,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001079636-4yjxzj.jpg','read',0,NULL,NULL,'2026-04-12 13:38:00','2026-04-12 16:14:05',187,NULL,'Grapa','[{"name":"Grant Morrison","role":""},{"name":"Sholly Fisch","role":""},{"name":"Andy Kubert","role":""},{"name":"Chris Cross","role":""},{"name":"Jesse Delperdang","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1609,'Superman (2012-2024) #5','Superman (2012-2024)',5,NULL,'978-8-415-62850-7',NULL,'George Perez','Jesús Merino',NULL,NULL,'ECC Ediciones',NULL,'2012-09-01',NULL,NULL,replace(replace('Contiene: Superman 1 - 2 USA \r\nLa historia hasta aquí: \r\nEn la ciudad de Metropolis, ningún desaprensivo estaba a salvo de injusticia. Pero, aunque perseguido por la policía y el ejército, y con todos obsesionados con su naturaleza extraterrestre y sus enormes poderes. Superman demostró ser un auténtico héroe defendiendo la ciudad del ataque de Brainiac. Tras encontrar un traje kryptoniano en la nave del alienígena, el Hombre de Acero libró la batalla definitiva y consiguió devolver Metropolis a su tamaño, ganándose por fin el respeto de sus ciudadanos. Y además, Clark Kent recibió también una oferta para entrar a trabajar en el Daily Planet...','\r',char(13)),'\n',char(10)),NULL,NULL,256,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001090009-gixlaz.jpg','read',0,NULL,NULL,'2026-04-12 13:38:11','2026-04-12 16:14:05',187,NULL,'Grapa','[{"name":"George Perez","role":""},{"name":"Jesús Merino","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1610,'Superman (2012-2024) #6','Superman (2012-2024)',6,NULL,'978-8-415-62866-8',NULL,'George Perez','Jesús Merino',NULL,NULL,'ECC Ediciones',NULL,'2012-10-01',NULL,NULL,replace(replace('Contiene: Superman núms. 3-4 USA\r\nHistorias: Cuando el infierno se congele / Mente disponible\r\nLa historia hasta aquí: \r\nLa plantilla del viejo Daily Planet –ahora demolido– ha pasado a formar parte del imperio de la comunicación Grupo Internacional Planet, del millonario Morgan Edge. Mientras que la mayoría de sus antiguos empleados disfrutan de nuevos puestos en consonancia con la nueva era, Clark Kent no se siente nada cómodo con la situación, lo cual sumado a su doble vida como Superman le está alejando de sus amigos y de su trabajo. Y por si fuera poco, varios alienígenas ya han atacado al Hombre de Acero y otras tantas personas están poseídas por una inteligencia extraterrestre en lo que parece un plan orquestado alrededor de Superman…','\r',char(13)),'\n',char(10)),NULL,NULL,256,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001092512-881ocj.jpg','read',0,NULL,NULL,'2026-04-12 13:38:13','2026-04-12 16:14:01',187,NULL,'grapa','[{"name":"George Perez","role":""},{"name":"Jesús Merino","role":""},{"name":"Nicola Scott","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1611,'Superman (2012-2024) #7','Superman (2012-2024)',7,NULL,'978-8-415-62884-2',NULL,'Dan Jurgens','George Perez',NULL,NULL,'ECC Ediciones',NULL,'2012-11-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Superman núms. 5-6 USA \r\nARGUMENTO: Tras los ataques de tres alienígenas (uno de fuego, otro de hielo y otro con poder de invisibilidad) contra la ciudad de Metropolis, la prensa ha extendido el temor de que el propio Superman sea el catalizador de la reciente oleada de destrucción. Además, los alienígenas atacantes (que ocupan los cuerpos de tres personas, una de ellas la compañera de trabajo de Clark, Heather Kelley) están conectados entre ellos y han preparado una trampa para el Hombre de Acero que comienza transportándolo a un extraño lugar donde le dicen que él es su creador…','\r',char(13)),'\n',char(10)),NULL,NULL,256,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001094478-vrxwsz.jpg','read',0,NULL,NULL,'2026-04-12 13:38:15','2026-04-12 16:14:01',187,NULL,'Grapa','[{"name":"Dan Jurgens","role":""},{"name":"George Perez","role":""},{"name":"Keith Giffen","role":""},{"name":"Jesús Merino","role":""},{"name":"Nicola Scott","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1612,'Superman (2012-2024) #8','Superman (2012-2024)',8,NULL,'978-8-415-74804-5',NULL,'Grant Morrison','Sholly Fisch',NULL,NULL,'ECC Ediciones',NULL,'2012-12-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Action Comics v2 #9-10 USA \r\nARGUMENTO: La lucha de Superman contra Brainiac iba a decidir no solo el destino de la miniaturizada Metropolis, sino la supervivencia de toda la Tierra. El Hombre de Acero, vistiendo ya su uniforme kryptoniano (que halló en la nave de Brainiac) luchó a brazo partido contra el coleccionista de mundos y Metallo hasta conseguir detenerlos, devolver Metropolis a su tamaño y salvar el planeta. Y al final, Superman fue finalmente aceptado como héroe por su ciudad –la misma que, hasta entonces, lo había considerado una amenaza–, al tiempo que Clark Kent recibió una atractiva oferta para cambiar de trabajo y pasarse… al Daily Planet.','\r',char(13)),'\n',char(10)),NULL,NULL,256,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001096336-pw1p8n.jpg','read',0,NULL,NULL,'2026-04-12 13:38:17','2026-04-12 16:14:01',187,NULL,'grapa','[{"name":"Grant Morrison","role":""},{"name":"Sholly Fisch","role":""},{"name":"Cully Hamner","role":""},{"name":"Gene Ha","role":""},{"name":"Rags Morales","role":""},{"name":"Rick Bryant","role":""},{"name":"Carlos Urbano","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1613,'Superman (2012-2024) #9','Superman (2012-2024)',9,NULL,'978-8-415-74832-8',NULL,'Grant Morrison','Sholly Fisch',NULL,NULL,'ECC Ediciones',NULL,'2013-01-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Action Comics v2 #11-12 USA \r\nARGUMENTO: En un pequeño receso de la trama principal conocimos Tierra 23, un mundo alternativo en el que Superman es afroamericano, Presidente de los EEUU en su identidad humana y un férreo azote para los gobiernos dictatoriales contra los que lucha bajo su identidad superheroica. Y en el escenario habitual de las aventuras de Superman, mientras que el cazador Nimrod trataba de asesinar a Clark Kent, el joven periodista era dado por muerto durante un atentado suicida en el Daily Star. Oficialmente, Clark Kent estaba muerto… y el Hombre de Acero observaba desde las azoteas cómo los amigos de Clark lamentaban su pérdida.','\r',char(13)),'\n',char(10)),NULL,NULL,256,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001099738-r7rz0b.jpg','read',0,NULL,NULL,'2026-04-12 13:38:20','2026-04-12 16:14:01',187,NULL,'Grapa','[{"name":"Grant Morrison","role":""},{"name":"Sholly Fisch","role":""},{"name":"Brad Walker","role":""},{"name":"Rags Morales","role":""},{"name":"Carlos Urbano","role":""},{"name":"Rick Bryant","role":""},{"name":"Bob McLeod","role":""},{"name":"Andrew Hennessy","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1614,'Superman (2012-2024) #10','Superman (2012-2024)',10,NULL,'978-8-415-74856-4',NULL,'Dan Jurgens','Keith Giffen',NULL,NULL,'ECC Ediciones',NULL,'2013-02-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Superman 7-8 USA\r\nARGUMENTO: El mes pasado Superman hizo frente a la amenaza robótica conocida como Metalek, mientras que bajo su nueva identidad humana del bombero Johnny Kent –que se creó tras la aparente muerte de Clark Kent en la explosión del Daily Star–, continuaba salvando vidas sin descanso. Pero durante la lucha de Superman contra el Neo Sapiens Blake –que llegó a Metropolis en busca de otra de su especie y que no resultó ser sino la sobrina de Lois Lane–, Johnny Kent fue dado por muerto por sus compañeros y Superman, con ayuda de un deseo mágico de su casera de la Quinta Dimensión, volvió a recuperar su identidad de Clark Kent.','\r',char(13)),'\n',char(10)),NULL,NULL,256,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001102109-p7qx1m.jpg','read',0,NULL,NULL,'2026-04-12 13:38:23','2026-04-12 16:14:01',187,NULL,'Grapa','[{"name":"Dan Jurgens","role":""},{"name":"Keith Giffen","role":""},{"name":"Jesús Merino","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1615,'Superman (2012-2024) #11','Superman (2012-2024)',11,NULL,'978-8-415-74881-6',NULL,'Dan Jurgens','Keith Giffen',NULL,NULL,'ECC Ediciones',NULL,'2013-03-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Superman 9-10 USA\r\nARGUMENTO: Superman se las vio al fin cara a cara con Helspont, un daemonita con deseos de dominar la Tierra y que había elegido al Hombre de Acero para que le ayudara en su conquista. La negativa de Superman a colaborar con Helspont desembocó en una batalla cuerpo a cuerpo entre los dos, tras la cual Helspont desapareció sin dejar rastro. Superman regresó entonces a Metropolis, donde su vida como Clark Kent tampoco estaba en su mejor momento después de haber dejado plantada a Lucy (la hermana de Lois) y a Jimmy. Y ahora, una nueva villana y hasta un falso “Superman” van a complicar todavía más la vida del Hombre de Acero…','\r',char(13)),'\n',char(10)),NULL,NULL,256,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001104819-3hobvw.jpg','read',0,NULL,NULL,'2026-04-12 13:38:25','2026-04-12 16:14:01',187,NULL,'Grapa','[{"name":"Dan Jurgens","role":""},{"name":"Keith Giffen","role":""},{"name":"Jesús Merino","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1616,'Superman (2012-2024) #12','Superman (2012-2024)',12,NULL,'978-8-415-84402-0',NULL,'Dan Jurgens','Jesús Merino',NULL,NULL,'ECC Ediciones',NULL,'2013-04-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Superman 11-12 USA\r\nARGUMENTO: Mientras Clark trataba de buscar el modo de enmendar el plantón quele dio a la hermana de Lois –por estar luchando contra Helspont–, se lepresentó otro nuevo problema: un periodista bloguero llamado Barnesque, convencido de que Superman tenía una doble identidad, acusóa un corriente padre de familia llamado Spence de ser el Hombre deAcero. El verdadero Superman tuvo que defender a Spence del ataquevengativo de Angustia (a quien Superman le rompió durante uno desus encuentros su preciado relicario) y demostrar de paso que el pobreSpence no tenía nada de súper. Y mientras, en Rusia, algo está dejandoun río de cadáveres y va a captar la atención de Superman…','\r',char(13)),'\n',char(10)),NULL,NULL,256,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001107141-5qogcl.jpg','read',0,NULL,NULL,'2026-04-12 13:38:28','2026-04-12 16:14:01',187,NULL,'Grapa','[{"name":"Dan Jurgens","role":""},{"name":"Jesús Merino","role":""},{"name":"Vicente Cifuentes","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1617,'Superman (2012-2024) #13','Superman (2012-2024)',13,NULL,'978-8-415-84435-8',NULL,'Fabian Nicieza','Scott Lobdell',NULL,NULL,'ECC Ediciones',NULL,'2013-05-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Superman Annual 1, Superman Family Adventures 1 USA\r\nARGUMENTO: Superman se enfrentó contra un cazador alienígena traído a la fuerza a la Tierra por los rusos, y que estaba sembrando un reguero de muerte y destrucción a su paso. Tras una dura batalla en la que los rusos también los atacaron, el Hombre de Acero permitió que el cazador regresara a su planeta a través de un portal. Después de esto, Superman tomó la determinación de prestarle más atención a su descuidada vida como Clark Kent y a las personas de su entorno, a las que constantemente estaba dando plantón. Pero no contaba con que un viejo enemigo está a punto de regresar para ajustar cuentas con él…','\r',char(13)),'\n',char(10)),NULL,NULL,256,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001109641-skpscn.jpg','read',0,NULL,NULL,'2026-04-12 13:38:30','2026-04-12 16:14:01',187,NULL,'Grapa','[{"name":"Fabian Nicieza","role":""},{"name":"Scott Lobdell","role":""},{"name":"Marco Rudy","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1618,'Superman (2012-2024) #14','Superman (2012-2024)',14,NULL,'978-8-415-84459-4',NULL,'Grant Morrison','Sholly Fisch',NULL,NULL,'ECC Ediciones',NULL,'2013-06-01',NULL,NULL,replace(replace('EDICION ORIGINAL: Action Comics v2 #13-14 USA \r\nARGUMENTO: Después del atentado suicida contra el Daily Star que destruyó el edificio,a Clark Kent se le dio por muerto, y él aprovechó para crearse una nuevaidentidad humana –la del bombero Johnny Clark– con la que poder ayudara las personas incluso cuando no iba de Superman. Pronto tuvo que contener el ataque del Neo Sapiens Blake, que vino buscando a una niña de su especie y que no era otra que Susie, la sobrina de Lois Lane. Durantela lucha, Lois terminó gravemente herida y fue el propio Superman quienle salvó la vida aprendiendo cirugía con sus poderes y su inteligencia. Finalmente, Superman recuperó su identidad gracias a las artes mágicas desu casera, que se desveló como un ser de la Quinta Dimensión que quiereprotegerlo.','\r',char(13)),'\n',char(10)),NULL,NULL,256,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001111888-y785dg.jpg','read',0,NULL,NULL,'2026-04-12 13:38:32','2026-04-12 16:14:01',187,NULL,'Grapa','[{"name":"Grant Morrison","role":""},{"name":"Sholly Fisch","role":""},{"name":"Brad Walker","role":""},{"name":"Rags Morales","role":""},{"name":"Travel Foreman","role":""},{"name":"Brad Anderson","role":""},{"name":"Andrew Hennessy","role":""},{"name":"Mark Propst","role":""},{"name":"Chris Sprouse","role":""},{"name":"Karl Story","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1619,'Superman (2012-2024) #15','Superman (2012-2024)',15,NULL,'978-8-415-84486-0',NULL,'Grant Morrison','Sholly Fisch',NULL,NULL,'ECC Ediciones',NULL,'2013-07-01',NULL,NULL,replace(replace('EDICION ORIGINAL: Action Comics v2 #15-16 USA \r\nARGUMENTO: Tras ser encerrado en la zona fantasma por Xa-Du (un kryptoniano enviado a esa prisión 20 años antes de la destrucción de Krypton), Superman tuvo que encontrar el modo de escapar y devolver al villano a su confinamiento. Finalmente lo logró con la ayuda de su perro Krypto, que también estaba atrapado en la prisión fantasma. Y además, Kal-El consiguió regresar también con Krypto, recuperando así a uno de sus más fieles amigos. Poco después, Superman tuvo que combatir en Marte contra la amenaza de Metalek y el ataque inesperado de Vyndktvx e intentar salvar a un equipo de expedicionarios en el planeta rojo. Pero, para desgracia y estupor de Superman… no logró impedir que toda la expedición muriera de forma horrible.','\r',char(13)),'\n',char(10)),NULL,NULL,256,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001114161-g5d3yf.jpg','read',0,NULL,NULL,'2026-04-12 13:38:34','2026-04-12 16:14:01',187,NULL,'Grapa','[{"name":"Grant Morrison","role":""},{"name":"Sholly Fisch","role":""},{"name":"Brad Walker","role":""},{"name":"Rags Morales","role":""},{"name":"Andrew Hennessy","role":""},{"name":"Mark Propst","role":""},{"name":"Chris Sprouse","role":""},{"name":"Karl Story","role":""}]');
