INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1622,'Ultimate Spider-Man (2024-) #1','Ultimate Spider-Man (2024-)',1,NULL,'9772938609006-00001',NULL,'Jonathan Hickman','Marco Checchetto',NULL,NULL,'Panini Comics España',NULL,'2024-05-02',NULL,NULL,replace(replace('Contiene Ultimate Spider-Man vol. 3 #1 USA || P.V.P.: 2,50 €\r\nJonathan Hickman y Marco Checchetto traen una nueva visión de Spider-Man, en el título que supone el arranque de la nueva Línea Ultimate. Después de los eventos de Ultimate Invasion, el mundo necesita un nuevo héroe. ¿Quién asumirá la responsabilidad? Te presentamos a Peter Parker. Esposo. Padre. ¿Superhéroe?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001727051-5i7o7w.jpg','read',0,NULL,NULL,'2026-04-12 13:48:49','2026-04-12 16:14:01',189,NULL,'grapa','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"Marco Checchetto","role":"Dibujo, Tinta"},{"name":"Matt Wilson","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1623,'Ultimate Spider-Man (2024-) #2','Ultimate Spider-Man (2024-)',2,NULL,'9772938609006-00002',NULL,'Jonathan Hickman','Marco Checchetto',NULL,NULL,'Panini Comics España',NULL,'2024-06-06',NULL,NULL,replace(replace('Contiene Ultimate Spider-Man vol. 3 #2 USA\r\n¡Spider-Man se enfrenta a su primer enemigo! J. Jonah Jameson ha emprendido una investigación para descubrir quién mueve los hilos del nuevo Universo Ultimate, lo que conduce a una sorprendente revelación. Nueva York saluda a su nuevo héroe: ¡El Duende Verde!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001736877-64zkic.jpg','read',0,NULL,NULL,'2026-04-12 13:48:57','2026-04-12 16:14:01',189,NULL,'bolsillo','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"Marco Checchetto","role":"Dibujo, Tinta"},{"name":"Matt Wilson","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1624,'Ultimate Spider-Man (2024-) #3','Ultimate Spider-Man (2024-)',3,NULL,'9772938609006-00003',NULL,'Jonathan Hickman','Marco Checchetto',NULL,NULL,'Panini Comics España',NULL,'2024-07-04',NULL,NULL,replace(replace('Contiene Ultimate Spider-Man vol. 3 #3 USA\r\n¡La nueva vida de Peter Parker se complica todavía más cuando Spiderman conoce al nuevo héroe de la ciudad, El Duende Verde! Mientras se unen para luchar contra un supervillano, salen a la luz los secretos sobre las corporaciones que dirigen Norteamérica... y no imaginas quién ha descubierto la identidad secreta del trepamuros.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001738990-8kq9n1.jpg','read',0,NULL,NULL,'2026-04-12 13:49:00','2026-04-12 16:14:01',189,NULL,'grapa','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"Marco Checchetto","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1625,'Ultimate Spider-Man (2024-) #4','Ultimate Spider-Man (2024-)',4,NULL,'9772938609006-00004',NULL,'Jonathan Hickman','David Messina',NULL,NULL,'Panini Comics España',NULL,'2024-08-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL Ultimate Spider-Man vol. 3 #4 USA\r\nLos secretos de Peter Parker comienzan a afectar a su vida privada. La búsqueda de la verdad por parte de J. Jonah Jameson y Ben Parker provoca una conmoción mundial. Y ahora que Spider-Man tal vez no tenga que operar en solitario, comienza la reconstrucción del mundo criminal.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001741529-5ymel7.jpg','read',0,NULL,NULL,'2026-04-12 13:49:02','2026-04-12 16:14:01',189,NULL,'grapa','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"David Messina","role":"Dibujo, Tinta"},{"name":"Matthew Wilson","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1626,'Ultimate Spider-Man (2024-) #5','Ultimate Spider-Man (2024-)',5,NULL,'9772938609006-00005',NULL,'Jonathan Hickman','David Messina',NULL,NULL,'Panini Comics España',NULL,'2024-09-05',NULL,NULL,replace('Contiene Ultimate Spider-Man vol. 3 #5 USA\rLa historia secreta de Harry Osborn. ¿Cómo el heredero del imperio Osborn llegó a convertirse en un vigilante enmascarado? ¿Qué sabe El Duende Verde sobre el verdadero estatus del mundo en el que vive? Todo esto y mucho más será revelado.','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001743520-illui3.jpg','read',0,NULL,NULL,'2026-04-12 13:49:04','2026-04-12 16:14:01',189,NULL,'grapa','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"David Messina","role":"Dibujo, Tinta"},{"name":"Matt Wilson","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1627,'Ultimate Spider-Man (2024-) #6','Ultimate Spider-Man (2024-)',6,NULL,'9772938609006-00006',NULL,'Jonathan Hickman','Marco Checchetto',NULL,NULL,'Panini Comics España',NULL,'2024-10-03',NULL,NULL,replace('Contiene Ultimate Spider-Man vol. 3 #6 USA\rLa conclusión del primer arco argumental. Spider-Man por fin se enfrenta a Kingpin. El propietario del Daily Bugle ha estado trabajando con el consejo de El Hacedor para mantener el control de la información. ¡Es la primera pieza de dominó que tiene que caer para derribar su régimen!','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001745265-21o4ry.jpg','read',0,NULL,NULL,'2026-04-12 13:49:06','2026-04-12 16:14:01',189,NULL,'grapa','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"Marco Checchetto","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1628,'Ultimate Spider-Man (2024-) #7','Ultimate Spider-Man (2024-)',7,NULL,'9772938609006-00007',NULL,'Jonathan Hickman','Marco Checchetto',NULL,NULL,'Panini Comics España',NULL,'2024-11-07',NULL,NULL,replace(replace('Contiene Ultimate Spider-Man vol. 2 #7 USA\r\nEl regreso de los Ultimates. Tras su batalla contra Kingpin, Spider-Man y El Duende Verde han comprendido que no están tan preparados para rehacer el mundo como ellos habían esperado. Peter y Harry tienen mucho trabajo por delante, pero también Ben y Jonah. Los problemas de la resistencia empiezan después de que regresen los Ultimates.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001748037-6mnwyi.jpg','read',0,NULL,NULL,'2026-04-12 13:49:08','2026-04-12 16:14:01',189,NULL,'grapa','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"Marco Checchetto","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1629,'Ultimate Spider-Man (2024-) #8','Ultimate Spider-Man (2024-)',8,NULL,'9772938609006-00008',NULL,'Jonathan Hickman','Marco Checchetto',NULL,NULL,'Panini Comics España',NULL,'2024-12-05',NULL,NULL,replace('Contiene Ultimate Spider-Man vol. 3 #8 USA\rCon Los Seis Siniestros de Kingpin. Wilson Fisk ha reunido un equipo para enfrentarse al problema de los vigilantes enmascarados. Pero un grupo de villanos no es el único problema que Spidey afrontara. Mientras tanto, El Duende Verde se une a... ¿el Doctor Octopus?','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001750376-mq6sw1.jpg','read',0,NULL,NULL,'2026-04-12 13:49:11','2026-04-12 16:14:01',189,NULL,'GRAPA','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"Marco Checchetto","role":"Dibujo, Tinta"},{"name":"Matt Wilson","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1630,'Ultimate Spider-Man (2024-) #9','Ultimate Spider-Man (2024-)',9,NULL,'9772938609006-00009',NULL,'Jonathan Hickman','Marco Checchetto',NULL,NULL,'Panini Comics España',NULL,'2025-01-02',NULL,NULL,replace('Contiene Ultimate Spider-Man vol. 3 #9 USA\r¡El ataque de Los Seis Siniestros! Pero ¿quiénes son sus integrantes? El primero de ellos se lanza contra Spidey y El Duende Verde en este número lleno de acción. Además, el regreso de Tony Stark y Peter explora los límites de su nuevo traje.','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001753076-re7h13.jpg','read',0,NULL,NULL,'2026-04-12 13:49:13','2026-04-12 16:14:01',189,NULL,'grapa','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"Marco Checchetto","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1631,'Ultimate Spider-Man (2024-) #10','Ultimate Spider-Man (2024-)',10,NULL,'9772938609006-00010',NULL,'Jonathan Hickman','David Messina',NULL,NULL,'Panini Comics España',NULL,'2025-02-06',NULL,NULL,replace('Contiene Ultimate Spider-Man vol. 3 #10 USA\rBen Parker y J. Jonah Jameson, el dúo favorito de los lectores, pasan a primer plano en este número dedicado a la investigación de un misterio. Pero, en un mundo de sombras, cada piedra a la que se le da la vuelta conduce al peligro. Pronto tendrán que decidir si deben descubrir esos secretos o mantenerlos.','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001756118-ezady7.jpg','read',0,NULL,NULL,'2026-04-12 13:49:16','2026-04-12 16:14:01',189,NULL,'Grapa','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"David Messina","role":"Dibujo, Tinta"},{"name":"Matt Wilson","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1632,'Ultimate Spider-Man (2024-) #11','Ultimate Spider-Man (2024-)',11,NULL,'9772938609006-00011',NULL,'Jonathan Hickman','David Messina',NULL,NULL,'Panini Comics España',NULL,'2025-03-06',NULL,NULL,replace(replace('Contiene Ultimate Spider-Man vol. 3 #11 USA\r\n¿Quién es La Gata Negra del Universo Ultimate? Las tensiones se incrementan entre Spiderman y El Duende Verde mientras una nueva villana entra en escena. ¿Cuál es su conexión con El Gato Negro, el villano que pertenece a Los Seis Siniestros de Kingpin?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001758308-uakzkm.jpg','read',0,NULL,NULL,'2026-04-12 13:49:19','2026-04-12 16:14:01',189,NULL,'grapa','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"David Messina","role":"Dibujo, Tinta"},{"name":"Matt Wilson","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1633,'Ultimate Spider-Man (2024-) #12','Ultimate Spider-Man (2024-)',12,NULL,'9772938609006-00012',NULL,'Jonathan Hickman','Marco Checchetto',NULL,NULL,'Panini Comics España',NULL,'2025-04-03',NULL,NULL,replace('Contiene Ultimate Spider-Man vol. 3 #12 USA\r¿Una feliz Navidad arácnida? La familia Parker está disfrutando las fiestas de invierno. ¿Por qué Peter está actuando de forma tan extraña durante una época del año tan encantadora? ¿Por qué está Gwen tan preocupada? No te pierdas la conclusión del primer año de Ultimate Spider-Man.','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001760793-5mt7su.jpg','read',0,NULL,NULL,'2026-04-12 13:49:21','2026-04-12 16:14:01',189,NULL,'Grapa','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"Marco Checchetto","role":"Dibujo, Tinta, Color"},{"name":"Matt Wilson","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1634,'Ultimate Spider-Man (2024-) #13','Ultimate Spider-Man (2024-)',13,NULL,'9772938609006-00013',NULL,'Jonathan Hickman','Marco Checchetto',NULL,NULL,'Panini Comics España',NULL,'2025-05-15',NULL,NULL,replace(replace('Contiene: Ultimate Spider-Man 13\r\nEl juego más peligroso de Kraven. Los Seis Siniestros han estado persiguiendo a Spiderman y El Duende Verde por órdenes de Kingpin. Ahora, Kraven pasa a primer plano, en la carta de amor de Jonathan Hickman y Marco Checchetto a &quot;La última cacería de Kraven&quot;.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001764475-4m1f8q.jpg','read',0,NULL,NULL,'2026-04-12 13:49:25','2026-04-12 16:14:01',189,NULL,'grapa','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"Marco Checchetto","role":"Dibujo, Tinta, Color"},{"name":"Matt Wilson","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1635,'Ultimate Spider-Man (2024-) #14','Ultimate Spider-Man (2024-)',14,NULL,'9772938609006-00014',NULL,'Jonathan Hickman','Marco Checchetto',NULL,NULL,'Panini Comics España',NULL,'2025-06-12',NULL,NULL,replace('Contiene Ultimate Spider-Man vol. 3 #14 USA\r¡Contra Kraven el Cazador! Después de los horrores que sufrieron Peter y Harry durante la caza de Kraven, Spider-Man y El Duende Verde han decidido convertir al cazador en el cazado. ¿Pero seguirán siendo ellos mismos la presa en el juego de otra persona?','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001766922-laprfg.jpg','read',0,NULL,NULL,'2026-04-12 13:49:27','2026-04-12 16:14:01',189,NULL,'grapa','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"Marco Checchetto","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1636,'Ultimate Spider-Man (2024-) #15','Ultimate Spider-Man (2024-)',15,NULL,'9772938609006-00015',NULL,'Jonathan Hickman','David Messina',NULL,NULL,'Panini Comics España',NULL,'2025-07-10',NULL,NULL,replace(replace('Contiene Ultimate Spider-Man vol. 3 #15 USA\r\n¡El Hombre de Arena ataca! Mientras se asienta el polvo de los eventos de los últimos acontecimientos, Peter y familia se van de vacaciones... pero ningún lugar, por remoto que sea, será un lugar seguro para Spiderman.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001769209-mxfj3i.jpg','read',0,NULL,NULL,'2026-04-12 13:49:30','2026-04-12 16:14:01',189,NULL,'Grapa','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"David Messina","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1637,'Ultimate Spider-Man (2024-) #16','Ultimate Spider-Man (2024-)',16,NULL,'9772938609006-00016',NULL,'Jonathan Hickman','Marco Checchetto',NULL,NULL,'Panini Comics España',NULL,'2025-08-14',NULL,NULL,replace(replace('Contiene Ultimate Spider-Man vol. 3 #16 USA\r\nEl origen secreto de Mysterio, uno de los integrantes más singulares de Los Seis Siniestros. Ni siquiera Kingpin sabe gran cosa sobre el criminal de la pecera humeante. Ahora Spiderman está a punto de descubrir más de lo que quizás pueda afrontar.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001771691-3le9j0.jpg','read',0,NULL,NULL,'2026-04-12 13:49:32','2026-04-12 16:14:01',189,NULL,'grapa','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"Marco Checchetto","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1638,'Ultimate Spider-Man (2024-) #17','Ultimate Spider-Man (2024-)',17,NULL,'9772938609006-00017',NULL,'Jonathan Hickman','David Messina',NULL,NULL,'Panini Comics España',NULL,'2025-09-11',NULL,NULL,replace(replace('Contiene Ultimate Spider-Man vol. 3  #17 USA\r\nEl momento de la guerra total entre los dos trepamuros y Los Seis Siniestros ha llegado. Nueva York sufrirá las consecuencias. Por suerte, Peter Parker no está solo frente a sus peores enemigos. Le acompaña su hijo, Richard Parker, con el traje arácnido negro.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001774355-buv3zx.jpg','read',0,NULL,NULL,'2026-04-12 13:49:35','2026-04-12 16:14:01',189,NULL,'Grapa','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"David Messina","role":"Dibujo, Tinta"},{"name":"Matt Wilson","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1639,'Ultimate Spider-Man (2024-) #18','Ultimate Spider-Man (2024-)',18,NULL,'9772938609006-00018',NULL,'Jonathan Hickman','Marco Checchetto',NULL,NULL,'Panini Comics España',NULL,'2025-10-09',NULL,NULL,replace('Contiene Ultimate Spider-Man vol. 3 #18 USA\rLa Gata Negra se hace con la ayuda de Richard Parker, el hijo de Peter, en su guerra contra Los Seis Siniestros. Mientras tanto, Spider-Man se ha hecho con el más inesperado de los aliados.','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001776609-uwscgt.jpg','read',0,NULL,NULL,'2026-04-12 13:49:37','2026-04-12 16:14:01',189,NULL,'grapa','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"Marco Checchetto","role":"Dibujo, Tinta, Color"},{"name":"Matt Wilson","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1640,'Ultimate Spider-Man (2024-) #19','Ultimate Spider-Man (2024-)',19,NULL,'9772938609006-00019',NULL,'Jonathan Hickman','Marco Checchetto',NULL,NULL,'Panini Comics España',NULL,'2025-11-13',NULL,NULL,replace(replace('Contiene Ultimate Spider-Man vol. 3 #19 USA\r\n¡Un baile a tres bandas! ¡Una guerra total! Wilson Fisk contra el Sr. Negativo contra Mysterio, con Spiderman y sus aliados en medio. ¿Llegarán Los Seis Siniestros a destruir Nueva York antes de destruirse unos a otros?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001778381-8v24is.jpg','read',0,NULL,NULL,'2026-04-12 13:49:39','2026-04-12 16:14:01',189,NULL,'Grapa','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"Marco Checchetto","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1641,'Ultimate Spider-Man (2024-) #20','Ultimate Spider-Man (2024-)',20,NULL,'9772938609006-00020',NULL,'Jonathan Hickman','David Messina',NULL,NULL,'Panini Comics España',NULL,'2025-12-11',NULL,NULL,replace(replace('Contiene Ultimate Spider-Man vol. 3 #20 USA\r\n¡Mi cena con Harry! Al contrario de lo que pensaba Peter Parker, su gran amigo Harry Osborn consiguió sobrevivir a la trampa mortal tendida por Kingpin y los suyos en la Tierra Salvaje. Ha pasado mucho tiempo desde aquella primera cita de parejas. Ha llegado el momento de que Peter y Mary Jane queden una vez más con Harry y Gwen.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001780478-hbxjll.jpg','read',0,NULL,NULL,'2026-04-12 13:49:41','2026-04-12 16:14:01',189,NULL,'grapa','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"David Messina","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1642,'Ultimate Spider-Man (2024-) #21','Ultimate Spider-Man (2024-)',21,NULL,'9772938609006-00021',NULL,'Jonathan Hickman','David Messina',NULL,NULL,'Panini Comics España',NULL,'2026-01-15',NULL,NULL,replace(replace('Contiene Ultimate Spider-Man vol. 3 #21 USA\r\nEl último encuentro de Los Seis Siniestros. La sangre de estos peligrosos villanos hierve. Han empezado a destruirse los unos a los otros, en un acto de destrucción mutua asegurada. Pero quizás algo los lleve a detener el golpe: la posibilidad de unirse una vez más contra su común enemigo, Spiderman','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001784431-fcivlq.jpg','read',0,NULL,NULL,'2026-04-12 13:49:45','2026-04-12 16:14:01',189,NULL,'grapa','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"David Messina","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1643,'Ultimate Spider-Man (2024-) #22','Ultimate Spider-Man (2024-)',22,NULL,'9772938609006-00022',NULL,'Jonathan Hickman','Marco Checchetto',NULL,NULL,'Panini Comics España',NULL,'2026-02-12',NULL,NULL,replace(replace('Contiene Ultimate Spider-Man vol. 3 #22 USA\r\nLa serie más destacada de los últimos años se aproxima a su final, y si hasta ahora cualquier cosa podía ocurrir en sus páginas, imagínate ahora, tan cerca de la conclusión. Este episodio es una buena muestra. En su interior te descubrimos la última voluntad y testamento de... CENSURADO.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001786718-t6xpr8.jpg','read',0,NULL,NULL,'2026-04-12 13:49:47','2026-04-12 16:14:01',189,NULL,'grapa','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"Marco Checchetto","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1644,'Ultimate Spider-Man (2024-) #23','Ultimate Spider-Man (2024-)',23,NULL,'9772938609006-00023',NULL,'Jonathan Hickman','Marco Checchetto',NULL,NULL,'Panini Comics España',NULL,'2026-03-12',NULL,NULL,replace(replace('Contiene: Ultimate Spider-Man 23\r\nEstamos en el penúltimo número de Ultimate Spider-Man. ¿De verdad crees que te vamos a contar lo que ocurre en su interior? ¡Sería un auténtico festival de spoilers! Basta con que sepas que este episodio contribuye a construir un final que no querrás perderte.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001789306-8blwi4.jpg','read',0,NULL,NULL,'2026-04-12 13:49:49','2026-04-12 16:14:01',189,NULL,'grapa','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"Marco Checchetto","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1646,'Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-) #26','Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-)',26,NULL,'9770005444000-00026',NULL,'Jason Aaron','Esad Ribic',NULL,NULL,'Panini Comics España',NULL,'2013-06-01',NULL,NULL,replace(replace('Contiene Thor: God Of Thunder 1 y 2 USA\r\nUn cómic enmarcado dentro de Marvel Now! ¡Un nuevo comienzo! Jason Aaron (Lobezno) y Esad Ribic (Ultimates) se ponen al frente del destino de Thor. A lo largo de los siglos, los dioses del Universo Marvel han estado desapareciendo, lo que condena al caos a sus adoradores. Ahora, el Poderoso Thor sigue el rastro de sangre que amenaza con consumir su pasado, presente y futuro. ¡La única esperanza que le queda es desvelar el misterio alrededor del Carnicero de Dioses!','\r',char(13)),'\n',char(10)),NULL,NULL,40,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001922348-s3hrp7.jpg','read',0,NULL,NULL,'2026-04-12 13:52:05','2026-04-12 16:14:01',191,NULL,'grapa','[{"name":"Jason Aaron","role":"Guion"},{"name":"Esad Ribic","role":"Dibujo"},{"name":"Dean White","role":"Color"},{"name":"Ive Svorcina","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1647,'Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-) #27','Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-)',27,NULL,'9770005444000-00027',NULL,'Jason Aaron','Esad Ribic',NULL,NULL,'Panini Comics España',NULL,'2013-07-01',NULL,NULL,replace(replace('Contiene Thor: God Of Thunder 3 y 4 USA\r\nUna serie que forma parte de Marvel Now! La estela sangrienta de los dioses asesinados lleva a Thor a través de las profundidades del espacio. Miles de años en el futuro, el último rey de una Asgard en ruinas tendrá que luchar contra el carnicero. Pero incluso un rey dios puede caer. Incluso el rey Thor.','\r',char(13)),'\n',char(10)),NULL,NULL,40,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001930734-598x6u.jpg','read',0,NULL,NULL,'2026-04-12 13:52:11','2026-04-12 16:14:01',191,NULL,'grapa','[{"name":"Jason Aaron","role":"Guion"},{"name":"Esad Ribic","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1648,'Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-) #46','Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-)',46,NULL,'9770005444000-00046',NULL,'Jason Aaron','Russell Dauterman',NULL,NULL,'Panini Comics España',NULL,'2015-02-06',NULL,NULL,replace(replace('Contiene Thor V3, 1 y 2 USA \r\n¡Nueva etapa! ¡Un momento perfecto para subirse a la serie! Prepárate para contemplar a Thor como nunca has visto antes. Descubre a la nueva Thor en acción por primera vez. Con un ejército de Gigantes de Hielo invadiendo la Tierra, ella es la única esperanza.','\r',char(13)),'\n',char(10)),NULL,NULL,40,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001936128-sqto0c.jpg','read',0,NULL,NULL,'2026-04-12 13:52:16','2026-04-12 16:14:01',191,NULL,'grapa','[{"name":"Jason Aaron","role":"Guion"},{"name":"Russell Dauterman","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1649,'Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-) #28','Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-)',28,NULL,'9770005444000-00028',NULL,'Jason Aaron','Esad Ribic',NULL,NULL,'Panini Comics España',NULL,'2013-08-01',NULL,NULL,replace(replace('Contiene Thor: God Of Thunder 5 y 6 USA \r\nUna serie perteneciente a Marvel Now! El sorprendente final del primer arco argumental de la nueva andadura de Thor. Mientras los Dioses del Trueno de tres épocas diferentes se apresuran a detener al carnicero de dioses, su escalofriante plan sale a la luz. Además, un interludio hacia el segundo arco argumental, en el que descubrimos el origen oscuro de Gorr.','\r',char(13)),'\n',char(10)),NULL,NULL,40,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001940758-nghhek.jpg','read',0,NULL,NULL,'2026-04-12 13:52:21','2026-04-12 16:14:01',191,NULL,'grapa','[{"name":"Jason Aaron","role":"Guion"},{"name":"Esad Ribic","role":"Dibujo"},{"name":"Jackson Guice","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1650,'Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-) #29','Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-)',29,NULL,'9770005444000-00029',NULL,'Jason Aaron','Esad Ribic',NULL,NULL,'Panini Comics España',NULL,'2013-09-01',NULL,NULL,replace(replace('Contiene Thor: God Of Thunder 7 y 8 USA \r\nUn título que está encuadrado dentro de Marvel Now! Las dos primeras partes de un nuevo arco argumental. En algún lugar en el fin de los tiempos, todos los dioses del Universo están esclavizados, trabajando en la construcción de una máquina que cambiará el rostro de la creación. ¿Qué es? ¿Y qué puede hacer Thor, el último dios libre, por evitarlo?','\r',char(13)),'\n',char(10)),NULL,NULL,40,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001942852-bk27ob.jpg','read',0,NULL,NULL,'2026-04-12 13:52:23','2026-04-12 16:14:01',191,NULL,'grapa','[{"name":"Jason Aaron","role":"Guion"},{"name":"Esad Ribic","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1651,'Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-) #30','Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-)',30,NULL,'9770005444000-00030',NULL,'Jason Aaron','Esad Ribic',NULL,NULL,'Panini Comics España',NULL,'2013-10-01',NULL,NULL,replace(replace('Contiene Thor: God Of Thunder 9 y 10 USA \r\n¡Una colección que se enmarca en Marvel Now! ¡Tres encarnaciones de Thor, codo con codo al fin, unidas en batalla! Pero, ¿será suficiente para detener el gran plan de Gorr, el Carnicero de Dioses, ahora que sus poderes son más grandes que nada que se haya visto antes? Sea como fuera, ha llegado el momento de la batalla final contra él.','\r',char(13)),'\n',char(10)),NULL,NULL,40,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001944776-p161nr.jpg','read',0,NULL,NULL,'2026-04-12 13:52:25','2026-04-12 16:14:01',191,NULL,'grapa','[{"name":"Jason Aaron","role":"Guion"},{"name":"Esad Ribic","role":"Dibujo"},{"name":"Ive Svorcina","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1652,'Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-) #31','Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-)',31,NULL,'9770005444000-00031',NULL,'Jason Aaron','Esad Ribic',NULL,NULL,'Panini Comics España',NULL,'2013-11-02',NULL,NULL,replace(replace('Contiene Thor: God Of Thunder 11 y 12 USA \r\nUna colección encuadrada dentro de Marvel Now! El gran final a la saga del Carnicero de Dioses, con la que arrancó esta etapa. ¿Cuántos dioses saldrán vivos del choque final? Además: el regreso de Thor a Midgard. ¿Qué significa para un dios caminar sobre la Tierra? ¿A dónde va Thor cuando no está salvando el mundo con Los Vengadores? Y también: el regreso de Jane Foster.','\r',char(13)),'\n',char(10)),NULL,NULL,40,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001946646-iufw64.jpg','read',0,NULL,NULL,'2026-04-12 13:52:27','2026-04-12 16:14:01',191,NULL,'grapa','[{"name":"Jason Aaron","role":""},{"name":"Esad Ribic","role":""},{"name":"Nic Klein","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1653,'Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-) #32','Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-)',32,NULL,'9770005444000-00032',NULL,'Jason Aaron','Ron Garney',NULL,NULL,'Panini Comics España',NULL,'2013-12-02',NULL,NULL,replace(replace('Contiene Thor: God Of Thunder 13 USA \r\nEl comienzo de un nuevo arco argumental coincide con el regreso de uno de los grandes villanos creados por Walter Simonson durante su alucinante etapa, y que también aparecerá en la nueva película de Thor: ¡Malekith! El que fuera el señor de los Elfos Oscuros ha escapado de su prisión y está buscando venganza a lo largo y ancho de los Nueve Mundos.','\r',char(13)),'\n',char(10)),NULL,NULL,40,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001948969-utaqvy.jpg','read',0,NULL,NULL,'2026-04-12 13:52:30','2026-04-12 16:13:53',191,NULL,'grapa','[{"name":"Jason Aaron","role":""},{"name":"Ron Garney","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1654,'Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-) #33','Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-)',33,NULL,'9770005444000-00033',NULL,'Jason Aaron','Ron Garney',NULL,NULL,'Panini Comics España',NULL,'2014-01-02',NULL,NULL,replace(replace('Contiene Thor: God Of Thunder 14 USA \r\nCon el segundo capítulo de la aventura en la que Malekith, el villano de la segunda película de Thor, regresa a las páginas de su cómic. La caza salvaje ha empezado. Malekith está dejando un rastro de sangre por los Nueve Mundos mientras Thor encuentra nuevos aliados con los que perseguirle.','\r',char(13)),'\n',char(10)),NULL,NULL,40,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001951768-kvv09r.jpg','read',0,NULL,NULL,'2026-04-12 13:52:32','2026-04-12 16:13:53',191,NULL,'grapa','[{"name":"Jason Aaron","role":""},{"name":"Ron Garney","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1655,'Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-) #34','Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-)',34,NULL,'9770005444000-00034',NULL,'Jason Aaron','Ron Garney',NULL,NULL,'Panini Comics España',NULL,'2014-02-06',NULL,NULL,replace(replace('Contiene Thor: God Of Thunder 15 USA\r\nContinúa la búsqueda de Malekith El Maldito. Thor y sus nuevos compatriotas persiguen a los secuaces del Elfo Oscuro a lo largo y ancho de los Nueve Reinos. De los exóticos jardines encantados de Alfheim a las montañas heladas Jotunheim.','\r',char(13)),'\n',char(10)),NULL,NULL,40,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001954112-epyuxg.jpg','read',0,NULL,NULL,'2026-04-12 13:52:34','2026-04-12 16:13:53',191,NULL,'grapa','[{"name":"Jason Aaron","role":""},{"name":"Ron Garney","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1656,'Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-) #35','Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-)',35,NULL,'9770005444000-00035',NULL,'Jason Aaron','Ron Garney',NULL,NULL,'Panini Comics España',NULL,'2014-03-06',NULL,NULL,replace(replace('Contiene Thor: God Of Thunder 16 USA\r\nEl penúltimo capítulo de &quot;El maldito&quot;. La muerte visita las montañas de Jotunheim. Hay un traidor en las filas de la recién formada Liga de los Reinos. Thor se prepara para ejecutar a uno de sus camaradas. Malekith planea llevar su siguiente matanza hasta la Tierra...','\r',char(13)),'\n',char(10)),NULL,NULL,40,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001956151-ndn7f0.jpg','read',0,NULL,NULL,'2026-04-12 13:52:36','2026-04-12 16:13:53',191,NULL,'grapa','[{"name":"Jason Aaron","role":""},{"name":"Ron Garney","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1657,'Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-) #36','Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-)',36,NULL,'9770005444000-00036',NULL,'Jason Aaron','Ron Garney',NULL,NULL,'Panini Comics España',NULL,'2014-04-01',NULL,NULL,replace(replace('Contiene Thor: God Of Thunder 17 y 18 USA\r\n¡El gran final de la saga de Malekith, el maldito! El viaje de Thor por los Nueve Reinos le lleva hasta Midgard, la Tierra, donde tendrá lugar la batalla contra Malekith y sus oscuras fuerzas. Pero, ¿qué ha sido de la comunidad de aliados de Thor? ¿Y quién de ellos se mostrará como un traidor? Además, un nuevo relato protagonizado por el joven Thor en la era de los vikingos','\r',char(13)),'\n',char(10)),NULL,NULL,40,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001958188-bja8ns.jpg','read',0,NULL,NULL,'2026-04-12 13:52:39','2026-04-12 16:13:53',191,NULL,'grapa','[{"name":"Jason Aaron","role":""},{"name":"Ron Garney","role":""},{"name":"Emanuela Lupacchino","role":""},{"name":"Julio Das Pastoras","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1658,'Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-) #37','Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-)',37,NULL,'9770005444000-00037',NULL,'Jason Aaron','Esad Ribic',NULL,NULL,'Panini Comics España',NULL,'2014-05-01',NULL,NULL,replace(replace('Contiene Thor: God Of Thunder 19 USA\r\nLos últimos días de Midgard comienzan aquí. Thor siempre ha luchado por salvar su planeta adoptivo, pero... ¿qué puede hacer cuando es el planeta el que está muriendo? Mientras tanto, miles de años en el futuro, el Dios del Trueno se enfrenta contra Galactus.','\r',char(13)),'\n',char(10)),NULL,NULL,40,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001961054-ororeg.jpg','read',0,NULL,NULL,'2026-04-12 13:52:42','2026-04-12 16:13:53',191,NULL,'grapa','[{"name":"Jason Aaron","role":"Guion"},{"name":"Esad Ribic","role":"Dibujo, Tinta, Color"},{"name":"Ive Svorcina","role":"Color"},{"name":"Clay Mann","role":"Dibujo, Tinta, Color"},{"name":"Simone Bianchi","role":"Dibujo, Tinta, Color"},{"name":"Jenny Parks","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1659,'Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-) #38','Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-)',38,NULL,'9770005444000-00038',NULL,'Jason Aaron','Esad Ribic',NULL,NULL,'Panini Comics España',NULL,'2014-06-04',NULL,NULL,replace(replace('Contiene Thor: God Of Thunder 20 USA\r\nCon el segundo capítulo de &quot;Los últimos días de Midgard&quot;. Thor lucha por salvar la Tierra en dos frentes. En el presente, se enfrenta a Roxxon, la más poderosa y malvada empresa del planeta. En el lejano futuro, el rey Thor es todo lo que queda entre nuestro mundo y el Viejo Galactus.','\r',char(13)),'\n',char(10)),NULL,NULL,40,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001963527-cozsz9.jpg','read',0,NULL,NULL,'2026-04-12 13:52:44','2026-04-12 16:13:53',191,NULL,'grapa','[{"name":"Jason Aaron","role":"Guion"},{"name":"Esad Ribic","role":"Dibujo, Tinta, Color"},{"name":"Ive Svorcina","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1660,'Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-) #39','Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-)',39,NULL,'9770005444000-00039',NULL,'Jason Aaron','Esad Ribic',NULL,NULL,'Panini Comics España',NULL,'2014-07-03',NULL,NULL,replace(replace('Contiene Thor: God Of Thunder 21 USA \r\nLa tercera parte de &quot;Los últimos días de Midgard&quot;. Roxxon contraataca. Broxton está en estado de sitio. El Minotauro estrecha la mano del rey de los trolls. En el futuro lejano, el rey Thor se siente abrumado por la furia de Galactus.','\r',char(13)),'\n',char(10)),NULL,NULL,40,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001965566-tdrllk.jpg','read',0,NULL,NULL,'2026-04-12 13:52:46','2026-04-12 16:13:53',191,NULL,'grapa','[{"name":"Jason Aaron","role":"Guion"},{"name":"Esad Ribic","role":"Dibujo, Tinta, Color"},{"name":"Ive Svorcina","role":"Color"},{"name":"Ron Garney","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1661,'Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-) #40','Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-)',40,NULL,'9770005444000-00040',NULL,'Jason Aaron','Esad Ribic',NULL,NULL,'Panini Comics España',NULL,'2014-07-31',NULL,NULL,replace(replace('Contiene Thor: God Of Thunder 22 USA \r\nCon la parte cuarta de &quot;Los últimos días de Midgard&quot;. Thor y la agente Roz Solomon contra Ulik el troll. Roxxon contra Broxton. Y, en un futuro lejano, las Diosas del Trueno se enfrentan a Galactus. Espera, ¿dónde está el Rey Thor?','\r',char(13)),'\n',char(10)),NULL,NULL,40,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001968141-r1nagb.jpg','read',0,NULL,NULL,'2026-04-12 13:52:49','2026-04-12 16:13:53',191,NULL,'grapa','[{"name":"Jason Aaron","role":"Guion"},{"name":"Esad Ribic","role":"Dibujo"},{"name":"Ive Svorcina","role":"Color"},{"name":"Jee-Hyung","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1662,'Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-) #41','Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-)',41,NULL,'9770005444000-00041',NULL,'Jason Aaron','Esad Ribic',NULL,NULL,'Panini Comics España',NULL,'2014-09-05',NULL,NULL,replace(replace('Contiene Thor: God Of Thunder 23 USA \r\nCon la quinta entrega de &quot;Los últimos días de Midgard&quot;. La guerra de Thor por salvar a la Tierra llega a su épica conclusión. En un futuro lejano, el Rey Thor toma una terrible decisión para conseguir sus objetivos, mientras que en el presente se enfrenta con Roxxon... ¡Pero ni siquiera un dios puede mantener a todos a salvo!','\r',char(13)),'\n',char(10)),NULL,NULL,40,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001971394-cjpbac.jpg','read',0,NULL,NULL,'2026-04-12 13:52:52','2026-04-12 16:13:53',191,NULL,'grapa','[{"name":"Jason Aaron","role":"Guion"},{"name":"Esad Ribic","role":"Dibujo"},{"name":"Ive Svorcina","role":"Color"},{"name":"Agustin Alessio","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1663,'Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-) #42','Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-)',42,NULL,'9770005444000-00042',NULL,'Jason Aaron','Agustin Alessio',NULL,NULL,'Panini Comics España',NULL,'2014-10-03',NULL,NULL,replace(replace('Contiene Thor: God Of Thunder 24 USA \r\nEpílogo de &quot;Los últimos días de Midgard&quot;. La guerra de Thor contra Roxxon ha tenido ramificaciones para Asgard, pero también para Jane Foster. Mientras, en el futuro, ¿qué destino aguarda para Galactus a manos del Rey Thor?','\r',char(13)),'\n',char(10)),NULL,NULL,40,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001973739-9avi88.jpg','read',0,NULL,NULL,'2026-04-12 13:52:54','2026-04-12 16:13:53',191,NULL,'grapa','[{"name":"Jason Aaron","role":"Guion"},{"name":"Agustin Alessio","role":"Dibujo"},{"name":"Esad Ribic","role":"Dibujo"},{"name":"Ive Svorcina","role":"Color"},{"name":"Pascal Campion","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1664,'Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-) #43','Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-)',43,NULL,'9770005444000-00043',NULL,'Jason Aaron','Simone Bianchi',NULL,NULL,'Panini Comics España',NULL,'2014-11-07',NULL,NULL,replace(replace('Contiene Original Sin 5.1 y 5.2 USA \r\nComienza el cruce con &quot;Pecado original&quot;. ¡Descubre el Décimo Reino! Los secretos más oscuros de los otros nueve han salido a la luz pública. Ahora Thor sabe que tiene una hermana. Junto a Loki se embarcará en una búsqueda a través de este extraño mundo.','\r',char(13)),'\n',char(10)),NULL,NULL,40,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001976374-brdpdz.jpg','read',0,NULL,NULL,'2026-04-12 13:52:57','2026-04-12 16:13:53',191,NULL,'grapa','[{"name":"Jason Aaron","role":"Guion"},{"name":"Al Ewing","role":"Guion"},{"name":"Simone Bianchi","role":"Dibujo"},{"name":"Lee Garbett","role":"Dibujo"},{"name":"Nolan Woodard","role":"Color"},{"name":"Dale Keown","role":"Dibujo, Tinta, Color"},{"name":"Jason Keith","role":"Dibujo, Tinta, Color"},{"name":"Adriano Dell''Alpi","role":"Color"},{"name":"Ive Svorcina","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1665,'Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-) #44','Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-)',44,NULL,'9770005444000-00044',NULL,'Jason Aaron','Lee Garbett',NULL,NULL,'Panini Comics España',NULL,'2014-12-05',NULL,NULL,replace(replace('Contiene Original Sin 5.3, 5.4 y 5.5 USA \r\nConcluye el cruce con &quot;Pecado original&quot;. ¡Descubre el Décimo Reino! Los secretos más oscuros de los otros nueve han salido a la luz pública. Ahora Thor sabe que tiene una hermana. Junto a Loki se ha encontrado cara a cara con ella... ¡Y su nombre es Angela!','\r',char(13)),'\n',char(10)),NULL,NULL,40,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001978935-7zpcyq.jpg','read',0,NULL,NULL,'2026-04-12 13:52:59','2026-04-12 16:13:53',191,NULL,'grapa','[{"name":"Jason Aaron","role":"Guion"},{"name":"Al Ewing","role":"Guion"},{"name":"Lee Garbett","role":"Dibujo, Tinta, Color"},{"name":"Nolan Woodard","role":"Dibujo, Color"},{"name":"Simone Bianchi","role":"Dibujo, Tinta, Color"},{"name":"Adriano Dell''Alpi","role":"Dibujo, Color"},{"name":"Simone Peruzzi","role":"Dibujo, Color"},{"name":"Szymon Kudranski","role":"Dibujo"},{"name":"Marco Checchetto","role":"Dibujo"},{"name":"Ricardo Pieruccini","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1666,'Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-) #45','Thor / El Poderoso Thor / Thor - Dios del Trueno / Thor - Diosa del Trueno / El Indigno Thor / El inmortal Thor (2011-)',45,NULL,'9770005444000-00045',NULL,'Jason Aaron','Esad Ribic',NULL,NULL,'Panini Comics España',NULL,'2015-01-02',NULL,NULL,replace(replace('Contiene Thor: God Of Thunder 25 USA\r\nHemos hecho este número especial con la intención de redefinir el adjetivo &quot;épico&quot;. ¡Sólo Esad Ribic, Simon Bisley (Lobo) y R. M. Guerá (Scalped) podrían haberlo hecho. El Rey Thor y sus nietas descubren un capítulo secreto de la historia del Dios del Trueno, mientras nuestro Thor afronta la verdad revelada en &quot;Pecado original&quot;.','\r',char(13)),'\n',char(10)),NULL,NULL,40,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776001981253-dink8v.jpg','read',0,NULL,NULL,'2026-04-12 13:53:02','2026-04-12 16:13:53',191,NULL,'grapa','[{"name":"Jason Aaron","role":"Guion"},{"name":"Esad Ribic","role":"Dibujo"},{"name":"Simon Bisley","role":"Dibujo"},{"name":"R. M. Guéra","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1667,'Mapache Cohete / Groot (2014-2018) #1','Mapache Cohete / Groot (2014-2018)',1,NULL,'9770005485003-00001',NULL,'Skottie Young','Skottie Young',NULL,NULL,'Panini Comics España',NULL,'2014-10-02',NULL,NULL,replace(replace('Contiene RocketRaccoonFCBD y v2, 1 USA\r\nEs el campeón de los oprimidos, protector de los inocentes, ídolo de mujeres de cualquier especie galáctica y ahora... ¿un mapache a la fuga? ¡Perdón, experto en los Guardianes de la Galaxia: Mapache Cohete no es un mapache! Es mucho más, y ahora podrá demostrarlo en su propia serie, con guión y dibujo de nada menos que Skottie Young, el alucinante artista de las &quot;babyvariants&quot; de Marvel y de la adaptación al cómic de El mago de Oz. ¿Te imaginas un mejor autor para las andanzas de Mapache Cohete? ¿Te imaginas una mejor nueva serie que añadir a tus favoritas? ¡No la dejes escapar!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002009751-a619hx.jpg','read',0,NULL,NULL,'2026-04-12 13:53:31','2026-04-12 16:13:53',192,NULL,'grapa','[{"name":"Skottie Young","role":"Guion, Dibujo, Tinta, Color"},{"name":"Jean-Francois Beaulieu","role":"Color"},{"name":"Joe Caramagna","role":"Guion"},{"name":"Adam Archer","role":"Dibujo"},{"name":"John Rauch","role":"Color"},{"name":"Koz!k","role":"Dibujo, Tinta, Color"},{"name":"Leonel Castellani","role":"Dibujo, Tinta, Color"},{"name":"David Peterson","role":"Dibujo, Tinta, Color"},{"name":"J. Scott Campbell","role":"Dibujo, Tinta, Color"},{"name":"Nei Ruffino","role":"Dibujo, Tinta, Color"},{"name":"Dale Keown","role":"Dibujo, Tinta, Color"},{"name":"Jason Keith","role":"Dibujo, Tinta, Color"},{"name":"Sara Pichelli","role":"Dibujo, Tinta, Color"},{"name":"Justin Ponsor","role":"Dibujo, Tinta, Color"},{"name":"Jeff Smith","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1668,'Mapache Cohete / Groot (2014-2018) #2','Mapache Cohete / Groot (2014-2018)',2,NULL,'9770005485003-00002',NULL,'Skottie Young','Skottie Young',NULL,NULL,'Panini Comics España',NULL,'2014-11-06',NULL,NULL,replace(replace('Contiene Rocket Raccon v2, 2 USA\r\n¿Quién engañó a Mapache Cohete? El más importante mapache de la galaxia ha sido arrestado y acusado de un asesinato que no ha cometido. ¿El auténtico asesino? Un impostor que parece ir un paso por delante de nuestro héroe. Ahora, debería ir al Planeta X en busca de la verdad.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002030516-xcbzvo.jpg','read',0,NULL,NULL,'2026-04-12 13:53:51','2026-04-12 16:13:53',192,NULL,'grapa','[{"name":"Skottie Young","role":"Guion, Dibujo, Tinta"},{"name":"Jean-Francois Beaulieu","role":"Color"},{"name":"Pascal Campion","role":"Dibujo, Tinta, Color"},{"name":"Stan Sakai","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1669,'Mapache Cohete / Groot (2014-2018) #3','Mapache Cohete / Groot (2014-2018)',3,NULL,'9770005485003-00003',NULL,'Skottie Young','Skottie Young',NULL,NULL,'Panini Comics España',NULL,'2014-12-05',NULL,NULL,replace(replace('Contiene Rocket Raccon v2, 3 USA \r\nTu nuevo personaje favorito por fin se encuentra cara a cara con el impostor que ha estado haciéndose pasar por él. ¡Es un choque como pocas veces has visto, y como sólo podría narrar Skottie Young, el alucinante artista de esta alucinante serie!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002032736-1grakb.jpg','read',0,NULL,NULL,'2026-04-12 13:53:53','2026-04-12 16:13:53',192,NULL,'grapa','[{"name":"Skottie Young","role":"Guion, Dibujo, Tinta, Color"},{"name":"Jean-Francois Beaulieu","role":"Color"},{"name":"Pascal Campion","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1670,'Mapache Cohete / Groot (2014-2018) #4','Mapache Cohete / Groot (2014-2018)',4,NULL,'9770005485003-00004',NULL,'Skottie Young','Skottie Young',NULL,NULL,'Panini Comics España',NULL,'2015-01-02',NULL,NULL,replace(replace('Contiene Rocket Raccoon v2, 4 USA\r\nMapache Cohete y su malvado y peligroso doble por fin se encuentran cara a cara. Atrapado entre una especie de roedores terrestres, nuestro pequeño héroe tendrá que enfrentarse con algunos amigos que quieren acabar con él. ¿Conseguirá salir a salvo mientras limpia su nombre? ¡Descúbrelo con Skottie Young!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002035307-fbfyq0.jpg','read',0,NULL,NULL,'2026-04-12 13:53:55','2026-04-12 16:13:53',192,NULL,'grapa','[{"name":"Skottie Young","role":"Guion, Dibujo, Tinta, Color"},{"name":"Jean-Francois Beaulieu","role":"Color"},{"name":"Pascal Campion","role":"Dibujo, Tinta, Color"},{"name":"Alex Kropinak","role":"Dibujo, Tinta, Color"},{"name":"Kalman Andrasofszky","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1671,'Mapache Cohete / Groot (2014-2018) #5','Mapache Cohete / Groot (2014-2018)',5,NULL,'9770005485003-00005',NULL,'Skottie Young','Jake Parker',NULL,NULL,'Panini Comics España',NULL,'2015-02-05',NULL,NULL,replace(replace('Contiene Rocket Raccoon v2, 5 USA \r\n¡Mapache Cohete y Groot, la pareja que ha tomado los cines en todo el mundo están de vuelta! Sus aventuras espaciales continúan. Descubre cómo la criatura más peligrosa del cosmos llega hasta los chicos malos. Basta dos buenos amigos: pistolas y Groot.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002037421-abm7sn.jpg','read',0,NULL,NULL,'2026-04-12 13:53:58','2026-04-12 16:13:53',192,NULL,'grapa','[{"name":"Skottie Young","role":"Guion"},{"name":"Jean-Francois Beaulieu","role":"Color"},{"name":"Jake Parker","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1672,'Mapache Cohete / Groot (2014-2018) #6','Mapache Cohete / Groot (2014-2018)',6,NULL,'9770005485003-00006',NULL,'Skottie Young','Jake Parker',NULL,NULL,'Panini Comics España',NULL,'2015-03-05',NULL,NULL,replace(replace('Contiene Rocket Raccoon v2, 6 USA \r\nMapache Cohete y Groot son los dos mejores amigos que nadie pudiera imaginar. Pero también son la más asombrosa máquina de matar que se te pueda pasar por la cabeza. De verdad: son muy buenos matando gente con grandes armas. Aquí podrás comprobarlo.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002039663-49oazd.jpg','read',0,NULL,NULL,'2026-04-12 13:54:00','2026-04-12 16:13:53',192,NULL,'grapa','[{"name":"Skottie Young","role":"Guion"},{"name":"Jake Parker","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1673,'Mapache Cohete / Groot (2014-2018) #7','Mapache Cohete / Groot (2014-2018)',7,NULL,'9770005485003-00007',NULL,'Skottie Young','Filipe Andrade',NULL,NULL,'Panini Comics España',NULL,'2015-04-01',NULL,NULL,replace(replace('Contiene Rocket Raccoon v2, 7 USA \r\nMapache Cohete está tratando de arreglar su pasado. Como habrás podido deducir, las consecuencias no pueden ser más calamitosas para toda la galaxia. Además, descubre un planeta donde es invierno todo el año. El peor planeta que te puedas imaginar.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002041646-xg3iot.jpg','read',0,NULL,NULL,'2026-04-12 13:54:02','2026-04-12 16:13:53',192,NULL,'grapa','[{"name":"Skottie Young","role":"Guion"},{"name":"Filipe Andrade","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1674,'Mapache Cohete / Groot (2014-2018) #8','Mapache Cohete / Groot (2014-2018)',8,NULL,'9770005485003-00008',NULL,'Skottie Young','Filipe Andrade',NULL,NULL,'Panini Comics España',NULL,'2015-05-07',NULL,NULL,replace(replace('Contiene Rocket Raccoon v2, 8 USA\r\nEl más duro, ingenioso, fuerte y peludo miembro de los Guardianes de la Galaxia acaba de estrenar el arma más grande que jamás haya tenido. ¿El motivo...? Bueno, no podemos decírtelo, tendrás que averiguarlo en esta aventura de Skottie Young y Filipe Andrede que rompe las reglas (incluidas las de la gramática).','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002043796-abcox1.jpg','read',0,NULL,NULL,'2026-04-12 13:54:04','2026-04-12 16:13:53',192,NULL,'grapa','[{"name":"Skottie Young","role":"Guion"},{"name":"Filipe Andrade","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1675,'Mapache Cohete / Groot (2014-2018) #9','Mapache Cohete / Groot (2014-2018)',9,NULL,'9770005485003-00009',NULL,'Skottie Young','Jacob Parker',NULL,NULL,'Panini Comics España',NULL,'2015-06-05',NULL,NULL,replace(replace('Contiene Rocket Raccoon v2, 9 USA \r\nEn un futuro no demasiado lejano, ¿qué ocurre cuando riegas a Groot en exceso? Grootzilla ha llegado, y está muy enfadado. ¡Es más rápido que un Mapache Cohete, más poderoso que un Drax el destructor y es capaz de zamparse edificios de un mordisco!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002045849-pwq6ur.jpg','read',0,NULL,NULL,'2026-04-12 13:54:06','2026-04-12 16:13:53',192,NULL,'grapa','[{"name":"Skottie Young","role":"Guion"},{"name":"Jacob Parker","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1676,'El Invencible Iron Man Vol. 2 / Iron Man (2011-) #27','El Invencible Iron Man Vol. 2 / Iron Man (2011-)',27,NULL,'9770005443003-00027',NULL,'Kieron Gillen','Greg Land',NULL,NULL,'Panini Comics España',NULL,'2013-04-01',NULL,NULL,replace(replace('Contiene Iron Man v4, 1 y 2 USA\r\n¡El Vengador Dorado llega a Marvel Now! Tony Stark, el hombre conocido como Iron Man... Visionario de la tecnología, playboy millonario, ingeniero sin parangón, fundador de Los Vengadores. Ahora, su mayor invento se transforma en su mayor error. Iron Man debe actuar con rapidez... ¡Y Tony Stark debe darse todavía más prisa en construir su siguiente armadura! El virus Extremis ha vuelto, pero esta vez no ha infectado al Hombre de Hierro, sino que ha escapado a todo control. Sólo Iron Man puede contenerlo. Kieron Gillen y Greg Land, los autores de La Imposible Patrulla-X, arrancan su etapa en la colección.','\r',char(13)),'\n',char(10)),NULL,NULL,280,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002069455-e9ldbw.jpg','read',0,NULL,NULL,'2026-04-12 13:54:31','2026-04-12 16:13:53',193,NULL,'Grapa','[{"name":"Kieron Gillen","role":"Guion"},{"name":"Greg Land","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1677,'El Invencible Iron Man Vol. 2 / Iron Man (2011-) #41','El Invencible Iron Man Vol. 2 / Iron Man (2011-)',41,NULL,'9770005443003-00041',NULL,'Kieron Gillen','Joe Bennett',NULL,NULL,'Panini Comics España',NULL,'2014-06-05',NULL,NULL,replace(replace('Contiene Iron Man v4, 22 y Annual v4, 1 USA \r\nLa conclusión de &quot;Iron Metropolitan&quot;. La ciudad del Mandarín está en llamas. Troya está en ruinas. ¿Quién ayudará a Tony Stark cuando más lo necesita? ¿Qué está dispuesto a hacer por su ciudad? ¿Quién está buscando a aquellos que llevan los anillos del Mandarín?','\r',char(13)),'\n',char(10)),NULL,NULL,280,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002079709-00bxu0.jpg','read',0,NULL,NULL,'2026-04-12 13:54:40','2026-04-12 16:13:53',193,NULL,'Grapa','[{"name":"Kieron Gillen","role":"Guion"},{"name":"Joe Bennett","role":"Dibujo"},{"name":"Scott Hanna","role":"Tinta"},{"name":"Guru-eFX","role":"Color"},{"name":"Alvaro Martinez Bueno","role":"Dibujo"},{"name":"Raúl Fernandez","role":"Tinta"},{"name":"Chris Sotomayor","role":"Color"},{"name":"Agustín Padilla","role":"Dibujo"},{"name":"Val Staples","role":"Color"},{"name":"Marcos Marz","role":"Dibujo, Tinta"},{"name":"Esther Sanz","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1678,'El Invencible Iron Man Vol. 2 / Iron Man (2011-) #28','El Invencible Iron Man Vol. 2 / Iron Man (2011-)',28,NULL,'9770005443003-00028',NULL,'Kieron Gillen','Greg Land',NULL,NULL,'Panini Comics España',NULL,'2013-05-01',NULL,NULL,replace(replace('Contiene Iron Man v4, 3 y 4 USA\r\nUn cómic enmarcado dentro de Marvel Now! Con el debut de la nueva armadura de infiltración de Iron Man. En lo más profundo de Colombia, la hija de uno de los más peligrosos cárteles de la droga ha sido modificada por Extremis. ¿Conseguirán algunos de los peores enemigos de Iron Man impedir que éste haga lo que debe para salvar al mundo de este peligroso nano-virus?','\r',char(13)),'\n',char(10)),NULL,NULL,280,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002083840-p57i77.jpg','read',0,NULL,NULL,'2026-04-12 13:54:44','2026-04-12 16:13:53',193,NULL,'Grapa','[{"name":"Kieron Gillen","role":"Guion"},{"name":"Greg Land","role":"Dibujo"},{"name":"Jay Leisten","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1679,'El Invencible Iron Man Vol. 2 / Iron Man (2011-) #29','El Invencible Iron Man Vol. 2 / Iron Man (2011-)',29,NULL,'9770005443003-00029',NULL,'Kieron Gillen','Greg Land',NULL,NULL,'Panini Comics España',NULL,'2013-06-01',NULL,NULL,replace('Contiene Iron Man v4, 5 y 6 USA \rUn cómic enmarcado dentro de Marvel Now!, complementario de Los Guardianes de la Galaxia. El Extremis ha llegado a la última frontera, y eso sólo puede significar la condenación universal. ¿Será Tony capaz de traicionar a un viejo amigo? Descúbrelo en el cómic en que presentamos la nueva armadura espacial de Iron Man y el comienzo del segundo arco argumental de Marvel Now! ¿Qué te encontrarás? A Tony en el espacio. En un bar. Con chicas. ¿Qué puede ir mal?','\r',char(13)),NULL,NULL,280,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002088411-s8j2a5.jpg','read',0,NULL,NULL,'2026-04-12 13:54:49','2026-04-12 16:13:53',193,NULL,'Grapa','[{"name":"Kieron Gillen","role":""},{"name":"Greg Land","role":""},{"name":"Jay Leisten","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1680,'El Invencible Iron Man Vol. 2 / Iron Man (2011-) #30','El Invencible Iron Man Vol. 2 / Iron Man (2011-)',30,NULL,'9770005443003-00030',NULL,'Kieron Gillen','Greg Land',NULL,NULL,'Panini Comics España',NULL,'2013-07-01',NULL,NULL,replace(replace('Contiene Iron Man v4, 7 y 8 USA\r\nUna serie que forma parte de Marvel Now! Las secuelas de la guerra entre Los Vengadores y La Patrulla-X todavía se hacen sentir. Los Shi','\r',char(13)),'\n',char(10)),NULL,NULL,280,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002092742-96w7pw.jpg','read',0,NULL,NULL,'2026-04-12 13:54:53','2026-04-12 16:13:53',193,NULL,'Grapa','[{"name":"Kieron Gillen","role":"Guion"},{"name":"Greg Land","role":"Dibujo"},{"name":"Jay Leisten","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1681,'El Invencible Iron Man Vol. 2 / Iron Man (2011-) #31','El Invencible Iron Man Vol. 2 / Iron Man (2011-)',31,NULL,'9770005443003-00031',NULL,'Kieron Gillen','Dale Eaglesham',NULL,NULL,'Panini Comics España',NULL,'2013-08-01',NULL,NULL,replace(replace('Contiene Iron Man v4, 9 y 10 USA\r\nUna serie perteneciente a Marvel Now! Comienza el arco argumental del que todo el mundo va a hablar: &quot;El origen secreto de Tony Stark&quot;. Cabeza de Muerte y Iron Man buscan a un genocida. Sin problema. Un puñado de badoons muertos. Sin problema. ¿Qué descubrirá Tony en las profundidades de una nave espacial? El problema. El gran problema.','\r',char(13)),'\n',char(10)),NULL,NULL,280,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002096159-re13y5.jpg','read',0,NULL,NULL,'2026-04-12 13:54:56','2026-04-12 16:13:53',193,NULL,'Grapa','[{"name":"Kieron Gillen","role":"Guion"},{"name":"Dale Eaglesham","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1682,'El Invencible Iron Man Vol. 2 / Iron Man (2011-) #32','El Invencible Iron Man Vol. 2 / Iron Man (2011-)',32,NULL,'9770005443003-00032',NULL,'Kieron Gillen','Dale Eaglesham',NULL,NULL,'Panini Comics España',NULL,'2013-09-01',NULL,NULL,replace(replace('Contiene Iron Man v4, 11 USA\r\n¡Un título que está encuadrado dentro de Marvel Now! “El origen secreto de Tony Stark&quot; continúa. En este número lo descubrirás todo. El precio. El acuerdo. Las consecuencias. Es la historia que cambiará para siempre al Hombre de Hierro.','\r',char(13)),'\n',char(10)),NULL,NULL,280,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002097892-t6l0p8.jpg','read',0,NULL,NULL,'2026-04-12 13:54:58','2026-04-12 16:13:53',193,NULL,'Grapa','[{"name":"Kieron Gillen","role":"Guion"},{"name":"Dale Eaglesham","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1683,'El Invencible Iron Man Vol. 2 / Iron Man (2011-) #33','El Invencible Iron Man Vol. 2 / Iron Man (2011-)',33,NULL,'9770005443003-00033',NULL,'Kieron Gillen','Greg Land',NULL,NULL,'Panini Comics España',NULL,'2013-10-01',NULL,NULL,replace(replace('Contiene Iron Man v4, 12 y 13 USA\r\n¡Una colección que se enmarca en Marvel Now! Continúa &quot;El origen secreto de Tony Stark&quot;. Asiste al verdadero nacimiento de nuestro héroe y descubre los motivos ulteriores de 451. Son importantes, más de lo que puedas imaginar.','\r',char(13)),'\n',char(10)),NULL,NULL,280,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002100088-byc0gz.jpg','read',0,NULL,NULL,'2026-04-12 13:55:00','2026-04-12 16:13:53',193,NULL,'Grapa','[{"name":"Greg Land","role":"Dibujo"},{"name":"Kieron Gillen","role":"Guion"},{"name":"Dale Eaglesham","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1684,'El Invencible Iron Man Vol. 2 / Iron Man (2011-) #34','El Invencible Iron Man Vol. 2 / Iron Man (2011-)',34,NULL,'9770005443003-00034',NULL,'Kieron Gillen','Greg Land',NULL,NULL,'Panini Comics España',NULL,'2013-11-01',NULL,NULL,replace(replace('Contiene Iron Man v4, 14 USA\r\nUna colección encuadrada dentro de Marvel Now! &quot;El origen secreto de Tony Stark&quot; continua, con más sorprendentes revelaciones. Libre al fin, Iron Man tendrá que luchar contra un robot que puede controlar su armadura siempre que quiera. Una decisión imposible decidirá el destino de dos mundos. ¿Quién vivirá? ¿Quién morirá? ¿Podrá Tony Stark evitar su destino?','\r',char(13)),'\n',char(10)),NULL,NULL,280,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002102269-qeg9dq.jpg','read',0,NULL,NULL,'2026-04-12 13:55:03','2026-04-12 16:13:53',193,NULL,'Grapa','[{"name":"Kieron Gillen","role":"Guion"},{"name":"Greg Land","role":"Dibujo"},{"name":"Guru-eFX","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1685,'El Invencible Iron Man Vol. 2 / Iron Man (2011-) #35','El Invencible Iron Man Vol. 2 / Iron Man (2011-)',35,NULL,'9770005443003-00035',NULL,'Kieron Gillen','Carlo Pagulayan',NULL,NULL,'Panini Comics España',NULL,'2013-12-01',NULL,NULL,replace('Contiene Iron Man v4, 15 y 16 USA\rContinúa &quot;El origen secreto de Tony Stark&quot;, mientras nuevas revelaciones explosivas salen a la luz, aquí llega la batalla final: Tony contra 451. Y también tenemos la alianza definitiva y una huída de la escena del crimen. Además, ¿quieres saber cómo está engañando Tony a los Guardianes de la Galaxia? Aquí descubrirás lo que les oculta.','\r',char(13)),NULL,NULL,280,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002104797-v4ixsk.jpg','read',0,NULL,NULL,'2026-04-12 13:55:05','2026-04-12 16:13:53',193,NULL,'Grapa','[{"name":"Kieron Gillen","role":"Guion"},{"name":"Carlo Pagulayan","role":"Dibujo"},{"name":"Guru-eFX","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1686,'El Invencible Iron Man Vol. 2 / Iron Man (2011-) #36','El Invencible Iron Man Vol. 2 / Iron Man (2011-)',36,NULL,'9770005443003-00036',NULL,'Kieron Gillen','Carlo Pagulayan',NULL,NULL,'Panini Comics España',NULL,'2014-01-01',NULL,NULL,replace(replace('Contiene Iron Man v4, 17\r\nMás revelaciones alucinantes, en el último capítulo de &quot;El origen secreto de Tony Stark&quot;. En este último capítulo, lo que 451 no sabía. Lo que Tony no sabía. Y lo que cambiará las cosas para siempre. ¿No te lo crees? Aquí lo comprobarás.','\r',char(13)),'\n',char(10)),NULL,NULL,280,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002107134-xfws5a.jpg','read',0,NULL,NULL,'2026-04-12 13:55:08','2026-04-12 16:13:53',193,NULL,'Grapa','[{"name":"Kieron Gillen","role":"Guion"},{"name":"Carlo Pagulayan","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1687,'El Invencible Iron Man Vol. 2 / Iron Man (2011-) #37','El Invencible Iron Man Vol. 2 / Iron Man (2011-)',37,NULL,'9770005443003-00037',NULL,'Kieron Gillen','Joe Bennett',NULL,NULL,'Panini Comics España',NULL,'2014-02-01',NULL,NULL,replace(replace('Contiene Iron Man v4, 18 USA \r\nComienza un nuevo arco argumental, &quot;Iron Metropolitan&quot;. Tony Stark ha vuelto a casa de su viaje por el espacio, con una visión de un mundo mejor. ¿Quién es su aliado secreto? ¿Cuál es su fuente secreta para conseguir sus propósitos? ¿Quién en la Tierra se atreverá a detenerle? El Mandarín murió al final de la etapa pasada. Si lo mencionamos, será por algo.','\r',char(13)),'\n',char(10)),NULL,NULL,280,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002109484-ozg4ve.jpg','read',0,NULL,NULL,'2026-04-12 13:55:10','2026-04-12 16:13:53',193,NULL,'Grapa','[{"name":"Kieron Gillen","role":"Guion"},{"name":"Joe Bennett","role":"Dibujo"},{"name":"Scott Hanna","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1688,'El Invencible Iron Man Vol. 2 / Iron Man (2011-) #38','El Invencible Iron Man Vol. 2 / Iron Man (2011-)',38,NULL,'9770005443003-00038',NULL,'Kieron Gillen','Joe Bennett',NULL,NULL,'Panini Comics España',NULL,'2014-03-01',NULL,NULL,replace(replace('Contiene Iron Man v4, 19 USA \r\nCon la segunda parte de &quot;Iron Metropolitan&quot;. Pepper descubre la existencia de PEPPER. ¿Cómo crees que se lo tomará? ¿Cómo te lo tomarías tú? Además, una visita a la ciudad del Mandarín. ¿Qué es lo que puede ir mal? Obviamente, todo puede ir mal.','\r',char(13)),'\n',char(10)),NULL,NULL,280,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002111870-wyxmqx.jpg','read',0,NULL,NULL,'2026-04-12 13:55:12','2026-04-12 16:13:53',193,NULL,'Grapa','[{"name":"Kieron Gillen","role":"Guion"},{"name":"Joe Bennett","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1689,'El Invencible Iron Man Vol. 2 / Iron Man (2011-) #39','El Invencible Iron Man Vol. 2 / Iron Man (2011-)',39,NULL,'9770005443003-00039',NULL,'Kieron Gillen','Joe Bennett',NULL,NULL,'Panini Comics España',NULL,'2014-04-03',NULL,NULL,replace(replace('Contiene Iron Man v4, 20 USA \r\nCon la tercera parte de &quot;Iron Metropolitan&quot;. Alguien está investigando el nuevo juguete favorito de Tony Stark... ¡Y debajo de la tecnología encontrará la verdad acerca de la ciudad creada por Iron Man!','\r',char(13)),'\n',char(10)),NULL,NULL,280,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002115675-ml7h7x.jpg','read',0,NULL,NULL,'2026-04-12 13:55:16','2026-04-12 16:13:53',193,NULL,'Grapa','[{"name":"Kieron Gillen","role":"Guion"},{"name":"Joe Bennett","role":"Dibujo"},{"name":"Scott Hanna","role":"Tinta"},{"name":"Guru-eFX","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1690,'El Invencible Iron Man Vol. 2 / Iron Man (2011-) #40','El Invencible Iron Man Vol. 2 / Iron Man (2011-)',40,NULL,'9770005443003-00040',NULL,'Kieron Gillen','Joe Bennett',NULL,NULL,'Panini Comics España',NULL,'2014-04-30',NULL,NULL,replace(replace('Contiene Iron Man v4, 20.INH y 21 USA \r\nUn episodio ligado a &quot;Inhumano&quot;. ¿Quién será el nuevo Mandarín? ¿Y en qué influirá la explosión de la Bomba Terrígena en los planes de Tony y Arno Stark para construir la ciudad del mañana? ¡Descúbrelo aquí! Además, el último día de Arno Stark en el pulmón de acero.','\r',char(13)),'\n',char(10)),NULL,NULL,280,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002118067-rxan7g.jpg','read',0,NULL,NULL,'2026-04-12 13:55:19','2026-04-12 16:13:53',193,NULL,'Grapa','[{"name":"Kieron Gillen","role":"Guion"},{"name":"Joe Bennett","role":"Dibujo"},{"name":"Agustín Padilla","role":"Dibujo"},{"name":"Scott Hanna","role":"Tinta"},{"name":"Guru-eFX","role":"Color"},{"name":"Paul Rivoche","role":"Dibujo, Tinta, Color"}]');
