INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1695,'Spider-Man / Miles Morales: Spider-Man (2016-) #1','Spider-Man / Miles Morales: Spider-Man (2016-)',1,NULL,'9770005502007-00001',NULL,'Brian Michael Bendis','Sara Pichelli',NULL,NULL,'Panini Comics España',NULL,'2016-06-02',NULL,NULL,replace(replace('Contiene Spider-Man v2, 1 USA \r\nLas Guerras Secretas han terminado y ahora Miles Morales vive en el Nuevo Universo Marvel, es miembro de Los Vengadores y cuenta con el apoyo de Peter Parker, el Hombre Araña original, pero no todo va a ser fácil para el trepamuros.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002249459-echvvy.jpg','read',0,NULL,NULL,'2026-04-12 13:57:32','2026-04-12 16:13:48',195,NULL,'grapa','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Sara Pichelli","role":"Dibujo"},{"name":"Gaetano Carlucci","role":"Tinta"},{"name":"Justin Ponsor","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1696,'Spider-Man / Miles Morales: Spider-Man (2016-) #2','Spider-Man / Miles Morales: Spider-Man (2016-)',2,NULL,'9770005502007-00002',NULL,'Brian Michael Bendis','Sara Pichelli',NULL,NULL,'Panini Comics España',NULL,'2016-07-01',NULL,NULL,replace(replace('Contiene Spider-Man v2, 2 USA \r\nLos Vengadores han sido derrotados y Miles Morales es el único de ellos que permanece en pie frente a un villano con el poder de destruir el Universo. Pero lo peor de todo es que mientras pelea con él, sus notas se van por el retrete.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002258166-c4r98z.jpg','read',0,NULL,NULL,'2026-04-12 13:57:38','2026-04-12 16:13:48',195,NULL,'grapa','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Sara Pichelli","role":"Dibujo"},{"name":"Gaetano Carlucci","role":"Tinta"},{"name":"Justin Ponsor","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1697,'Spider-Man / Miles Morales: Spider-Man (2016-) #3','Spider-Man / Miles Morales: Spider-Man (2016-)',3,NULL,'9770005502007-00003',NULL,'Brian Michael Bendis','Sara Pichelli',NULL,NULL,'Panini Comics España',NULL,'2016-08-04',NULL,NULL,replace(replace('Contiene Spider-Man vol. 2, 3 USA\r\nMiles se encuentra cara a cara con su peor enemigo hasta la fecha... ¡Su abuela! Y además, descubre la manera en la que una tarde de estudio con Ms. Marvel (¿o es más bien una cita?) puede estropearse por completo.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002259787-0c3e16.jpg','read',0,NULL,NULL,'2026-04-12 13:57:40','2026-04-12 16:13:48',195,NULL,'grapa','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Sara Pichelli","role":"Dibujo"},{"name":"Gaetano Carlucci","role":"Tinta"},{"name":"Justin Ponsor","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1698,'Spider-Man / Miles Morales: Spider-Man (2016-) #4','Spider-Man / Miles Morales: Spider-Man (2016-)',4,NULL,'9770005502007-00004',NULL,'Brian Michael Bendis','Sara Pichelli',NULL,NULL,'Panini Comics España',NULL,'2016-09-01',NULL,NULL,replace(replace('Contiene Spider-Man v2, 4 USA\r\nLos medios han descubierto el color de la piel de la nueva sensación arácnida, mientras Miles debe hacer frente a la nueva reina del crimen de Nueva York... ¡La Gata Negra! Felicia ha puesto sus ojos en Spidey y no va a olvidarse de él fácilmente.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002261520-utz0n4.jpg','read',0,NULL,NULL,'2026-04-12 13:57:42','2026-04-12 16:13:48',195,NULL,'grapa','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Sara Pichelli","role":"Dibujo"},{"name":"Gaetano Carlucci","role":"Tinta"},{"name":"Justin Ponsor","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1699,'Spider-Man / Miles Morales: Spider-Man (2016-) #5','Spider-Man / Miles Morales: Spider-Man (2016-)',5,NULL,'9770005502007-00005',NULL,'Brian Michael Bendis','Sara Pichelli',NULL,NULL,'Panini Comics España',NULL,'2016-10-06',NULL,NULL,replace(replace('Contiene Spider-Man v2, 5 USA\r\nPor si no tuviera bastantes problemas en casa, con una abuela que vigila cada paso que da, Ahora Miles Morales tiene que enfrentarse a la nueva enemiga que se ha ganado, así como a los aliados de ésta. ¡Cuidado con la Gata Negra!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002263670-e4oe22.jpg','read',0,NULL,NULL,'2026-04-12 13:57:44','2026-04-12 16:13:48',195,NULL,'grapa','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Sara Pichelli","role":"Dibujo"},{"name":"Gaetano Carlucci","role":"Tinta"},{"name":"Justin Ponsor","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1700,'Spider-Man / Miles Morales: Spider-Man (2016-) #6','Spider-Man / Miles Morales: Spider-Man (2016-)',6,NULL,'9770005502007-00006',NULL,'Brian Michael Bendis','Nico León',NULL,NULL,'Panini Comics España',NULL,'2016-11-03',NULL,NULL,replace(replace('Contiene Spider-Man v2, 6 USA\r\nCruce con “Civil War II”. Miles Morales sólo lleva unas semanas en el Universo Marvel, y ya se encuentra a sí mismo en medio de una guerra. ¿Cuál será el bando que elija el Hombre Araña?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002265955-4qh54d.jpg','read',0,NULL,NULL,'2026-04-12 13:57:46','2026-04-12 16:13:48',195,NULL,'grapa','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Nico León","role":"Dibujo"},{"name":"Marte Gracia","role":"Color"}]');
