INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1704,'Spider-Man / Miles Morales: Spider-Man (2016-) #10','Spider-Man / Miles Morales: Spider-Man (2016-)',10,NULL,'9770005502007-00010',NULL,'Brian Michael Bendis','Nico León',NULL,NULL,'Panini Comics España',NULL,'2017-03-01',NULL,NULL,replace(replace('Contiene Spider-Man v2, 10 USA\r\nEl día después de “Civil War II”. Los acontecimientos de la Segunda Guerra Civil Superheroica han convertido a Miles Morales en un objetivo de las autoridades. El Universo Marvel nunca lo volverá a mirar de la misma manera.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002275040-hpxnbm.jpg','read',0,NULL,NULL,'2026-04-12 13:57:56','2026-04-12 16:13:48',195,NULL,'grapa','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Nico León","role":"Dibujo"},{"name":"Marte Gracia","role":"Color"},{"name":"Rachelle Rosenberg","role":"Color"}]');
