INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1709,'Hambre. Los Vengadores: La era de Ultron (2013) #1','Hambre. Los Vengadores: La era de Ultron (2013)',1,NULL,'9770005477008-00001',NULL,'Joshua Fialkov','Leonard Kirk',NULL,NULL,'Panini Comics España',NULL,'2013-11-01',NULL,NULL,replace(replace('Contiene Hunger 1 y 2 USA\r\nUna colección encuadrada dentro de Marvel Now! La conclusión de La Era de Ultrón ha dejado abierta una peligrosa grieta en las fibras de la realidad. Prepárate para un hambre tan fuerte que ningún Universo está a salvo. ¿Es el principio del fin? Joshua Hale Fialkov (Yo Vampiro) y Leonard Kirk (X-Factor) te ofrecerán la respuesta.','\r',char(13)),'\n',char(10)),NULL,NULL,48,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002311730-le17m1.jpg','read',0,NULL,NULL,'2026-04-12 13:58:33','2026-04-12 16:13:48',196,NULL,'Grapa','[{"name":"Joshua Fialkov","role":"Guion"},{"name":"Leonard Kirk","role":"Dibujo"},{"name":"Jesús Aburtov","role":"Color"},{"name":"Neal Adams","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1710,'Hambre. Los Vengadores: La era de Ultron (2013) #2','Hambre. Los Vengadores: La era de Ultron (2013)',2,NULL,'9770005477008-00002',NULL,'Joshua Fialkov','Leonard Kirk',NULL,NULL,'Panini Comics España',NULL,'2013-12-01',NULL,NULL,replace(replace('Contiene Hunger 3 y 4 USA\r\nUn evento ligado a Marvel Now! Continúa la saga que está rompiendo universos. Con sus nuevos heraldos, Galactus es imparable. Ha destruido ya el Imperio Chitauri y ha aniquilado a los Kree. Mientras tanto, ¿qué ha sido del Capitán Marvel? ¡Las consecuencias de &quot;La Era de Ultrón&quot; continúan!','\r',char(13)),'\n',char(10)),NULL,NULL,48,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002317086-h98r1b.jpg','read',0,NULL,NULL,'2026-04-12 13:58:37','2026-04-12 16:13:48',196,NULL,'Grapa','[{"name":"Joshua Fialkov","role":"Guion"},{"name":"Leonard Kirk","role":"Dibujo"},{"name":"Jesús Aburtov","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1711,'Infinito (2013-2014) #1','Infinito (2013-2014)',1,NULL,'977-0-005-47800-5',NULL,'Jonathan Hickman','Jim Cheung',NULL,NULL,'Panini Comics España',NULL,'2013-11-01',NULL,NULL,replace(replace('Contiene Infinity 1 USA \r\nUn evento que se encuadrada dentro de Marvel Now! Llega la gran saga cósmica de este invierno, realizada por Jonathan Hickman, el actual arquitecto de Los Vengadores, y el extraordinario dibujante Jim Cheung (Los Vengadores: La cruzada de los niños). ¡Contempla el estremecedor regreso de Thanos, el amante de la muerte! La guerra ha estallado, y lo ha hecho en dos frentes: la Tierra y el espacio, con nuestros héroes divididos entre ambos lugares.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002332896-jngrlj.jpg','read',0,NULL,NULL,'2026-04-12 13:58:55','2026-04-12 16:13:48',197,166.8,'grapa','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"Jim Cheung","role":"Dibujo, Tinta"},{"name":"Mark Morales","role":"Tinta"},{"name":"John Livesay","role":"Tinta"},{"name":"Dave Meikis","role":"Tinta"},{"name":"Justin Ponsor","role":"Color"},{"name":"Scott Edelman","role":"Guion"},{"name":"Michael Zeck","role":"Dibujo"},{"name":"Petra Goldberg","role":"Color"},{"name":"Laura Martin","role":"Dibujo, Tinta, Color"},{"name":"Adam Kubert","role":"Dibujo, Tinta, Color"},{"name":"Marko Djurdjevic","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1712,'Infinito (2013-2014) #2','Infinito (2013-2014)',2,NULL,'9770005478005-00002',NULL,'Jonathan Hickman','Jerome Opeña',NULL,NULL,'Panini Comics España',NULL,'2013-12-01',NULL,NULL,replace(replace('Contiene Infinity 2 y 3 USA\r\nContinúa la primera gran saga alrededor de Los Vengadores de Jonathan Hickman. En esta entrega doble, Los Inhumanos pagan su tributo. Victoria en el espacio profundo. Los secretos de Thanos. Huída de prisión. Robar a un asesino de mundos. La caída de Attilan.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002340132-bwurmc.jpg','read',0,NULL,NULL,'2026-04-12 13:59:00','2026-04-12 16:13:48',197,NULL,'grapa','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"Jerome Opeña","role":"Dibujo"},{"name":"Dustin Weaver","role":"Dibujo"},{"name":"Justin Ponsor","role":"Color"},{"name":"Adam Kubert","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1713,'Infinito (2013-2014) #3','Infinito (2013-2014)',3,NULL,'9770005478005-00003',NULL,'Jonathan Hickman','Dustin Weaver',NULL,NULL,'Panini Comics España',NULL,'2014-01-01',NULL,NULL,replace(replace('Contiene Infinity 4 y 5\r\nEl cuarto y quinto capítulo del evento del mundo. Negociando la rendición de los mundos. Los Illuminati contra Galactus. Thor, Dios de la Guerra. Un universo de vengadores. Los héroes de la Tierra, unidos para derrotar a Thanos. La guerra por la Tierra ha comenzado.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002342012-ciojwm.jpg','read',0,NULL,NULL,'2026-04-12 13:59:02','2026-04-12 16:13:48',197,NULL,'grapa','[{"name":"Dustin Weaver","role":"Dibujo"},{"name":"Jerome Opeña","role":"Dibujo"},{"name":"Justin Ponsor","role":"Color"},{"name":"Adam Kubert","role":"Dibujo, Tinta, Color"},{"name":"Laura Martin","role":"Dibujo, Tinta, Color"},{"name":"In-Hyuk Lee","role":"Dibujo, Tinta, Color"},{"name":"Ryan Stegman","role":"Dibujo, Tinta, Color"},{"name":"Sara Pichelli","role":"Dibujo, Tinta, Color"},{"name":"Jonathan Hickman","role":"Guion, Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1714,'Infinito (2013-2014) #4','Infinito (2013-2014)',4,NULL,'9770005478005-00004',NULL,'Jonathan Hickman','Jim Cheung',NULL,NULL,'Panini Comics España',NULL,'2014-02-06',NULL,NULL,replace(replace('Contiene Infinity 6 USA\r\n¡Aquí tienes la conclusión del evento cósmico más importante desde Aniquilación! Todos los caminos recorridos llevan hasta aquí. Todos los héroes de la Tierra contra las fuerzas de Thanos y su Orden Negra, en una batalla que te dejará impresionado para siempre.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002344167-742gm3.jpg','read',0,NULL,NULL,'2026-04-12 13:59:05','2026-04-12 16:13:48',197,NULL,'grapa','[{"name":"Jonathan Hickman","role":"Guion"},{"name":"Jim Cheung","role":"Dibujo, Tinta"},{"name":"Dustin Weaver","role":"Dibujo, Tinta"},{"name":"Mark Morales","role":"Tinta"},{"name":"Guillermo Ortego","role":"Tinta"},{"name":"Dave Meikis","role":"Tinta"},{"name":"John Livesay","role":"Tinta"},{"name":"Justin Ponsor","role":"Color"},{"name":"Ive Svorcina","role":"Color"},{"name":"Adam Kubert","role":"Dibujo, Tinta, Color"},{"name":"Laura Martin","role":"Dibujo, Tinta, Color"},{"name":"Terry Dodson","role":"Dibujo, Tinta, Color"},{"name":"Jerome Opeña","role":"Dibujo, Tinta, Color"},{"name":"Skottie Young","role":"Dibujo, Tinta, Color"},{"name":"Leonel Castellani","role":"Dibujo, Tinta, Color"},{"name":"In-Hyuk Lee","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1715,'Spidermen (2012-2013) #1','Spidermen (2012-2013)',1,NULL,'9770005465005-00001',NULL,'Brian Michael Bendis','Sara Pichelli',NULL,NULL,'Panini Comics España',NULL,'2012-09-01',NULL,NULL,replace(replace('Contiene Spider-Men 1 USA \r\nMarvel Comics se enorgullece en presentar una de las mayores aventuras jamás contadas en el cómic mundial. Coincidiendo con el cincuenta aniversario del nacimiento de Spiderman, llega el encuentro entre Peter Parker, el asombroso Hombre Araña con el que empezó todo, y Miles Morales, el Spiderman Definitivo. ¡Un cruce entre universos como nunca antes has visto! Mientras sigue el rastro de uno de sus peores enemigos, Spidey se encuentra en un mundo donde la versión más joven de sí mismo ha muerto... ¡Y hay un nuevo Spiderman en la ciudad! Brian Michael Bendis, el escritor más relevante del siglo XXI, y Sara Pichelli (Ultimate Spiderman) narran una historia destinada a hacer historia.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002374735-vrpksu.jpg','read',0,NULL,NULL,'2026-04-12 13:59:36','2026-04-12 16:13:48',198,NULL,'grapa','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Sara Pichelli","role":"Dibujo"},{"name":"Justin Ponsor","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1716,'Spidermen (2012-2013) #2','Spidermen (2012-2013)',2,NULL,'9770005465005-00002',NULL,'Brian Michael Bendis','Sara Pichelli',NULL,NULL,'Panini Comics España',NULL,'2012-10-01',NULL,NULL,replace(replace('Contiene Spider-Men 2 USA \r\nEl segundo episodio de una de las mayores aventuras jamás contadas en el cómic mundial: el encuentro entre Peter Parker, el asombroso Hombre Araña con el que empezó todo, y Miles Morales, el Spiderman Definitivo. ¡Un cruce entre universos como nunca antes has visto! Mientras sigue el rastro de uno de sus peores enemigos, Spidey se encuentra en un mundo donde la versión más joven de sí mismo ha muerto... ¡Y hay un nuevo Spiderman en la ciudad! Brian Michael Bendis, el escritor más relevante del siglo XXI, y Sara Pichelli (Ultimate Spiderman) narran una historia destinada a hacer historia.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002380169-npr5qd.jpg','read',0,NULL,NULL,'2026-04-12 13:59:40','2026-04-12 16:13:48',198,NULL,'grapa','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Sara Pichelli","role":"Dibujo"},{"name":"Justin Ponsor","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1717,'Spidermen (2012-2013) #3','Spidermen (2012-2013)',3,NULL,'9770005465005-00003',NULL,'Brian Michael Bendis','Sara Pichelli',NULL,NULL,'Panini Comics España',NULL,'2012-11-01',NULL,NULL,replace(replace('Contiene Ultimate Spider-Men 3 USA \r\nEl siguiente capítulo en la miniserie que presenta el encuentro de los Hombres Araña de dos mundos: Peter Parker, el Spiderman que conocemos desde siempre, y Miles Morales, el nuevo Spiderman del Universo Ultimate, un chaval hispano-afroamericano que acaba de comenzar su carrera como superhéroe. Ahora que por fin se han encontrado ambos, ¿podrán trabajar juntos contra sus enemigos o tendrán que recurrir a la ayuda de Nick Furia y sus Ultimates? Bendis y Pichelli siguen adelante con un relato muy especial, en conmemoración del cincuenta aniversario del nacimiento de Spidey.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002389120-5gvt0r.jpg','read',0,NULL,NULL,'2026-04-12 13:59:50','2026-04-12 16:13:48',198,NULL,'grapa','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Sara Pichelli","role":"Dibujo"},{"name":"Justin Ponsor","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1718,'Spidermen (2012-2013) #4','Spidermen (2012-2013)',4,NULL,'9770005465005-00004',NULL,'Brian Michael Bendis','Sara Pichelli',NULL,NULL,'Panini Comics España',NULL,'2012-12-01',NULL,NULL,replace(replace('Contiene Ultimate Spider-Men 4 USA \r\nLos dos Hombres Araña ya están trabajando juntos. Ahora, ¿serán capaces de detener la amenaza de Mysterio? ¿Y qué ocurrirá cuando el Peter Parker del Universo Marvel descubra a la familia que nunca tuvo? En el cincuenta aniversario de Spiderman, no hay ninguna saga con la trascendencia que tiene ésta, en la que se une el trepamuros que nació hace medio siglo y el que apenas ha echado a andar. Brian Michael Bendis y Sara Pichelli realizan uno de los más aclamados tebeos del año.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002396968-zs0v1g.jpg','read',0,NULL,NULL,'2026-04-12 13:59:57','2026-04-12 16:13:48',198,NULL,'grapa','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Sara Pichelli","role":"Dibujo"},{"name":"Justin Ponsor","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1719,'Spidermen (2012-2013) #5','Spidermen (2012-2013)',5,NULL,'9770005465005-00005',NULL,'Brian Michael Bendis','Sara Pichelli',NULL,NULL,'Panini Comics España',NULL,'2013-01-01',NULL,NULL,replace(replace('Contiene Spider-Men 5 USA \r\n¡Último número! ¡Llega la conclusión del encuentro entre los Hombres Araña de dos mundos! Peter Parker, Miles Morales y los Ultimates se lanzan a la búsqueda de Mysterio. Pero, aunque consiguieran derrotarle, ¿cómo podrá Peter regresar a casa? ¿Qué harán él y Miles, ahora que saben que no están solos en el universo? Y, la más importante cuestión de todas: ¿Peter dará la aprobación a su equivalente del Universo Definitivo? Bendis y Pichelli concluyen la más alucinante historia de cruces de mundos que hayas leído jamás!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002398964-cuas9c.jpg','read',0,NULL,NULL,'2026-04-12 13:59:59','2026-04-12 16:13:48',198,NULL,'grapa','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Sara Pichelli","role":"Dibujo"},{"name":"Justin Ponsor","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1720,'Canario Negro: La mejor de lo mejor #1','Canario Negro: La mejor de lo mejor',1,NULL,'9773081330007-00001',NULL,'Tom King','Ryan Sook',NULL,NULL,'Panini Comics España',NULL,'2025-05-08',NULL,NULL,replace(replace('Contiene Black Canary: Best of the Best vol. 1 #1 USA (01/2025)\r\n¡El combate del milenio! A un lado del ring tenemos a Canario Negro y, al otro lado, Lady Shiva, listas para determinar de una vez por todas quién es la mejor. ¿Quién se alzará con el título? Acompaña a dos pesos pesados, Tom King y Ryan Sook, a lo largo de seis asaltos en los que veremos si nuestra heroína tiene lo que hace falta para ser… la mejor de lo mejor.','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002628318-ww0j7s.jpg','read',0,NULL,NULL,'2026-04-12 14:03:51','2026-04-12 16:13:48',199,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Ryan Sook","role":"Dibujo, Tinta, Color"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1721,'Canario Negro: La mejor de lo mejor #2','Canario Negro: La mejor de lo mejor',2,NULL,'9773081330007-00002',NULL,'Tom King','Ryan Sook',NULL,NULL,'Panini Comics España',NULL,'2025-06-05',NULL,NULL,replace('Black Canary: Best of the Best vol. 1 #2 USA (02/2025)\rDespués de un primer asalto desastroso, Canario Negro se reúne con su entrenador. ¿Cómo podría prepararse para un combate contra Lady Shiva? La respuesta es simple... acudir a su madre. La Canario Negro original está de regreso y lista para entrenar a su hija.','\r',char(13)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002634476-i71e13.jpg','read',0,NULL,NULL,'2026-04-12 14:03:55','2026-04-12 16:13:48',199,NULL,'Grapa','[{"name":"Tom King","role":"Guion"},{"name":"Ryan Sook","role":"Dibujo, Tinta, Color"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1722,'Canario Negro: La mejor de lo mejor #3','Canario Negro: La mejor de lo mejor',3,NULL,'9773081330007-00003',NULL,'Tom King','Ryan Sook',NULL,NULL,'Panini Comics España',NULL,'2025-07-03',NULL,NULL,replace(replace('Contiene Black Canary: Best of the Best vol. 1 #3 USA (03/2025)\r\nLa victoria parece asegurada para la cruel Lady Shiva. ¿Acaso hay algo que pueda cambiar las tornas del combate? Además, Batman visita por sorpresa a Canario Negro, para tratar de convencerla de que abandone la lucha.','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002636595-ler36p.jpg','read',0,NULL,NULL,'2026-04-12 14:03:57','2026-04-12 16:13:48',199,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Ryan Sook","role":"Dibujo, Tinta, Color"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1723,'Canario Negro: La mejor de lo mejor #4','Canario Negro: La mejor de lo mejor',4,NULL,'9773081330007-00004',NULL,'Tom King','Ryan Sook',NULL,NULL,'Panini Comics España',NULL,'2025-08-07',NULL,NULL,replace(replace('Black Canary: Best of the Best vol. 1 #4 USA (04/2025)\r\n¡El canario trina! Canario Negro sobrevive y está preparada para luchar contra su oponente. Quizás la derrota de Ted Grant, también conocido como Wildcat y el pilar en la esquina de Dinah, sea suficiente para traerla de vuelta a la lucha.','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002639485-ntu353.jpg','read',0,NULL,NULL,'2026-04-12 14:04:00','2026-04-12 16:13:48',199,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Ryan Sook","role":"Dibujo, Tinta, Color"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1724,'Canario Negro: La mejor de lo mejor #5','Canario Negro: La mejor de lo mejor',5,NULL,'9773081330007-00005',NULL,'Tom King','Ryan Sook',NULL,NULL,'Panini Comics España',NULL,'2025-09-04',NULL,NULL,replace(replace('Black Canary: Best of the Best vol. 1 #5 USA (05/2025)\r\nUn trato con un demonio inmortal rara vez es la respuesta a todos tus problemas. Shiva y Canario Negro siguen enfrentadas, sin ninguna ventaja especial en puntos, y cabe la posibilidad de que la batalla acabe con la muerte de una de las contendientes.','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002641970-j5i1qu.jpg','read',0,NULL,NULL,'2026-04-12 14:04:03','2026-04-12 16:13:48',199,NULL,'Grapa','[{"name":"Tom King","role":"Guion"},{"name":"Ryan Sook","role":"Dibujo, Tinta, Color"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1725,'Canario Negro: La mejor de lo mejor #6','Canario Negro: La mejor de lo mejor',6,NULL,'9773081330007-00006',NULL,'Tom King','Ryan Sook',NULL,NULL,'Panini Comics España',NULL,'2025-10-02',NULL,NULL,replace(replace('Black Canary: Best of the Best vol. 1 #6 USA (06/2025)\r\n¡Último número! Llega el último round. Con ambas combatientes contra las cuerdas e incapaces de rendirse, este final parece tan cercano como el pasado de Canario Negro. ¿Puede encontrar la manera de que su madre se sienta orgullosa y al mismo tiempo salvarse de la derrota definitiva?','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002644478-p5pn4l.jpg','read',0,NULL,NULL,'2026-04-12 14:04:05','2026-04-12 16:13:48',199,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Ryan Sook","role":"Dibujo, Tinta, Color"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1726,'Calle Peligro #1','Calle Peligro',1,NULL,'978-8-419-67873-7',NULL,'Tom King','Jorge Fornés',NULL,NULL,'ECC Ediciones',NULL,'2023-04-18',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Danger Street núm. 1 USA\r\n¡Nueva serie! Vuelve el aclamado equipo detrás de Rorschach: Tom King y Jorge Fornés. Starman, Metamorfo y Warlord invocan al mismísimo Darkseid para impresionar a los héroes. Spoiler: sale mal. ¿Podrán los personajes más raros de DC salvar el día?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002659825-3ylbd1.jpg','read',0,NULL,NULL,'2026-04-12 14:04:24','2026-04-12 16:13:48',200,24.95,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Jorge Fornés","role":"Dibujo, Tinta, Color"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1727,'Calle Peligro #2','Calle Peligro',2,NULL,'978-8-419-76034-0',NULL,'Tom King','Jorge Fornés',NULL,NULL,'ECC Ediciones',NULL,'2023-06-13',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Danger Street núm. 2 USA\r\n¡Warlord y Starman huyen de su destino! Tras causar todo un desastre en su intento de ser miembros de la Liga de la Justicia, se han puesto en contra de las fuerzas del orden del Cuarto Mundo y de la Tierra… Pero, por encima de eso, Lady Cop se encarga del caso. ¿Puede detener a los culpables?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002667604-h69185.jpg','read',0,NULL,NULL,'2026-04-12 14:04:28','2026-04-12 16:13:48',200,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Jorge Fornés","role":"Dibujo, Tinta, Color"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1728,'Calle Peligro #3','Calle Peligro',3,NULL,'978-8-419-81105-9',NULL,'Tom King','Jorge Fornés',NULL,NULL,'ECC Ediciones',NULL,'2023-07-11',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Danger Street núm. 3 USA\r\n¡Las cosas se complican! Las consecuencias del asesinato de [SPOILER] todavía están por ver. Todo el multiverso tiene un gran problema. Mientras tanto, la investigación de Lady Cop la lleva a Los Angeles, donde alguien trata de solucionarlo todo con un trato con el diablo… ¡Aunque puede que sea tarde!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002669684-adn27i.jpg','read',0,NULL,NULL,'2026-04-12 14:04:30','2026-04-12 16:13:48',200,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Jorge Fornés","role":"Dibujo, Tinta, Color"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1729,'Calle Peligro #4','Calle Peligro',4,NULL,'978-8-419-81162-2',NULL,'Tom King','Jorge Fornés',NULL,NULL,'ECC Ediciones',NULL,'2023-08-29',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Danger Street núm. 4 USA\r\n¡Lady Cop descubre al verdadero asesino! La policía se prepara para lo imposible: enfrentarse a un superhéroe. El equipo verde encuentra aliados inesperados en su causa por el poder. Y… ¡Aparece Creeper! Descubre una conspiración que tiene que ver con… ¡¿The Outsiders?! Se vienen curvas.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002671661-fhx8t8.jpg','read',0,NULL,NULL,'2026-04-12 14:04:32','2026-04-12 16:13:48',200,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Jorge Fornés","role":"Dibujo, Tinta, Color"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1730,'Calle Peligro #5','Calle Peligro',5,NULL,'978-8-419-86616-5',NULL,'Tom King','Jorge Fornés',NULL,NULL,'ECC Ediciones',NULL,'2023-09-13',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Danger Street núm. 5 USA\r\n¡Misterios y venganzas! Lady Cop sigue investigando mientras tiene que responder una difícil pregunta: ¿Qué une un asesinato en un pueblo con la inmensidad del Multiverso? Los dioses tratan de protegerse, mientras los Dingbats buscan una venganza. ¡El Multiverso está en juego!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002673488-o2e4xn.jpg','read',0,NULL,NULL,'2026-04-12 14:04:34','2026-04-12 16:13:48',200,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Jorge Fornés","role":"Dibujo, Tinta, Color"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1731,'Calle Peligro #6','Calle Peligro',6,NULL,'978-8-419-86697-4',NULL,'Tom King','Jorge Fornés',NULL,NULL,'ECC Ediciones',NULL,'2023-10-10',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Danger Street núm. 6 USA\r\n¡Giros inesperados! ¿El equipo verde tiene que actuar en solitario? ¿Los Outsiders van a revelar sus planes? Y lo que es más importante… ¡¿Highfather y Darkseid pactan para salvar sus mundos?! ¡Lo nunca visto!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002675881-tyeg8x.jpg','read',0,NULL,NULL,'2026-04-12 14:04:36','2026-04-12 16:13:48',200,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Jorge Fornés","role":"Dibujo, Tinta, Color"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1732,'Calle Peligro #7','Calle Peligro',7,NULL,'978-8-419-92050-8',NULL,'Tom King','Jorge Fornés',NULL,NULL,'ECC Ediciones',NULL,'2023-11-14',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Danger Street núm. 7 USA\r\n¡Lady Cop está a punto de resolver el misterio! La investigadora se adentra en la guarida de los villanos. ¿Quién acudirá en su ayuda? Desde luego, Creeper no va a ser. Mientras tanto, Warlord forja alianzas y se prepara para la batalla de su vida. ¡El universo está en peligro!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002677573-r56f1o.jpg','read',0,NULL,NULL,'2026-04-12 14:04:38','2026-04-12 16:13:48',200,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Jorge Fornés","role":"Dibujo, Tinta, Color"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1733,'Calle Peligro #8','Calle Peligro',8,NULL,'978-8-419-97207-1',NULL,'Tom King','Jorge Fornés',NULL,NULL,'ECC Ediciones',NULL,'2023-12-14',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Danger Street núm. 8 USA\r\n¡El origen del Equipo Verde y de los Outsiders! Comodoro consuma su venganza ordenando acabar con la vida de Manhunter. Mientras tanto, el mundo no puede contar con los héroes ¡Los Dingbats están solos y deben impedir la destrucción del universo! Más vale que estén a la altura.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002679634-jljcza.jpg','read',0,NULL,NULL,'2026-04-12 14:04:40','2026-04-12 16:13:48',200,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Jorge Fornés","role":"Dibujo, Tinta, Color"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1734,'Calle Peligro #9','Calle Peligro',9,NULL,'978-8-419-97274-3',NULL,'Tom King','Jorge Fornés',NULL,NULL,'ECC Ediciones',NULL,'2024-01-17',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Danger Street núm. 9 USA\r\n¡Hagan sus apuestas! A un lado del ring, Manhunter. Al otro, ni más ni menos que Codename: Assassin. Ambos están a punto de enfrentarse en un duelo que nada tiene que envidiar a los del lejano oeste. Es el desafío de sus vidas. ¡El destino del universo lo decidirá el ganador!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002682343-g044cc.jpg','read',0,NULL,NULL,'2026-04-12 14:04:43','2026-04-12 16:13:48',200,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Jorge Fornés","role":"Dibujo, Tinta, Color"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1735,'Calle Peligro #10','Calle Peligro',10,NULL,'978-8-410-10823-3',NULL,'Tom King','Jorge Fornés',NULL,NULL,'ECC Ediciones',NULL,'2024-02-14',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Danger Street núm. 10 USA\r\n¡Se presenta el nuevo caballero del Comodoro! Nada más y nada menos que… ¡Creeper! Y llega justo a tiempo porque los Outsiders están asediando su castillo. ¿Las murallas pueden aguantar? Mientras tanto, Lady Cop sigue investigando, los Dingbats planean resucitar a uno de los suyos. ¡Cueste lo que cueste!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002684392-3ai25j.jpg','read',0,NULL,NULL,'2026-04-12 14:04:45','2026-04-12 16:13:48',200,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Jorge Fornés","role":"Dibujo, Tinta, Color"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1736,'Calle Peligro #11','Calle Peligro',11,NULL,'978-8-410-10876-9',NULL,'Tom King','Jorge Fornés',NULL,NULL,'ECC Ediciones',NULL,'2024-03-13',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Danger Street núm. 11 USA\r\n¡Se acerca la batalla final! Héroes y villanos luchan por controlar el destino del Multiverso. Casi nada… ¿Morirán algunos en el intento? Lady Cop busca ayuda donde menos te lo esperas. Pero puede que haya esperanza: ¿Podrán los Dingbats salvar el día?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002686565-8slnie.jpg','read',0,NULL,NULL,'2026-04-12 14:04:47','2026-04-12 16:13:48',200,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Jorge Fornés","role":"Dibujo, Tinta, Color"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1737,'Calle Peligro #12','Calle Peligro',12,NULL,'978-8-410-13423-2',NULL,'Tom King','Jorge Fornés',NULL,NULL,'ECC Ediciones',NULL,'2024-04-10',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Danger Street núm. 12 USA\r\n¡Último número! ¡El sorprendente final! Lady Cop cierra definitivamente su investigación. Pero, más importante, ¿Conseguirán los Outsiders integrarse en la sociedad? ¿Quién es el verdadero héroe de la historia? Y… ¡Se cae el cielo! ¡¿Es que nadie lo va a parar?!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002688483-agzcpq.jpg','read',0,NULL,NULL,'2026-04-12 14:04:49','2026-04-12 16:13:40',200,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Jorge Fornés","role":"Dibujo, Tinta"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1738,'Strange Adventures #1','Strange Adventures',1,NULL,'978-8-418-32667-7',NULL,'Tom King','Mitch Gerads',NULL,NULL,'ECC Ediciones',NULL,'2020-09-29',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Strange Adventures vol. 5 núm. 1 USA\r\n2019 fue el año de Mr. Milagro. ¡Y en 2020 llega el momento de Strange Adventures! Los premiados Tom King y Mitch Gerads unen fuerzas con el dibujante Evan &quot;Doc&quot; Shaner para dar forma a una historia épica que se une a la tradición de grandes clásicos de DC Comics: una historia de sangre, guerra y amor protagonizada por Adam Strange, el héroe de Rann. Tras una gran guerra planetaria, Adam y su esposa viven retirados en la Tierra. Pero no todo es felicidad y alegría. Los pecados del pasado y las decisiones que Adam tomó durante la guerra vuelven para atormentar a su familia y amenazar a todo el Universo DC.','\r',char(13)),'\n',char(10)),NULL,NULL,376,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002704256-7qlc3g.jpg','read',0,NULL,NULL,'2026-04-12 14:05:07','2026-04-12 16:13:40',201,29.99,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"},{"name":"Evan Shaner","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1739,'Strange Adventures #2','Strange Adventures',2,NULL,'978-8-418-38241-3',NULL,'Tom King','Mitch Gerads',NULL,NULL,'ECC Ediciones',NULL,'2020-10-27',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Strange Adventures núm. 2 USA\r\n¿Cuál es la verdad sobre Adam Strange? Cuando un activista que lo acusó de crímenes de guerra termina muerto, la ciudadanía empieza a dudar de las historias protagonizadas por Strange en el planeta Rann, ¡incluso el propio Adam duda de sí mismo! La reputación y la vida del héroe penden de un hilo. Es el momento de recurrir a un investigador especializado.','\r',char(13)),'\n',char(10)),NULL,NULL,376,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002710181-0iokxv.jpg','read',0,NULL,NULL,'2026-04-12 14:05:11','2026-04-12 16:13:40',201,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mitch Gerads","role":"Dibujo, Tinta"},{"name":"Evan Shaner","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1740,'Strange Adventures #3','Strange Adventures',3,NULL,'978-8-418-38299-4',NULL,'Tom King','Mitch Gerads',NULL,NULL,'ECC Ediciones',NULL,'2020-12-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Strange Adventures núm. 3 USA\r\nAdam Strange ha sido acusado de asesinato y todo su historial como soldado está ahora en entredicho. Para limpiar su nombre, ha recurrido a dos de los mejores investigadores del Universo DC: Batman y Mr. Terrific. Pese a todos sus esfuerzos, la vida del héroe de Rann está a punto de cambiar para siempre. ¡La aventura entre dos mundos sigue adelante, con Mitch Gerads (El Sheriff de Babilonia) dibujando las escenas de la Tierra y Evan &quot;Doc&quot; Shaner (Los Terrifics) mostrándonos las batallas de Strange en el espacio exterior!','\r',char(13)),'\n',char(10)),NULL,NULL,376,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002712330-ohgluh.jpg','read',0,NULL,NULL,'2026-04-12 14:05:12','2026-04-12 16:13:40',201,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"},{"name":"Evan Shaner","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1741,'Strange Adventures #4','Strange Adventures',4,NULL,'978-8-418-47548-1',NULL,'Tom King','Mitch Gerads',NULL,NULL,'ECC Ediciones',NULL,'2020-12-30',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Strange Adventures núm. 4 USA\r\n¡Bienvenido al planeta Rann, Mr. Terrific! La investigación sigue su curso y es el momento de conocer de primera mano los crímenes de los que se acusa a Adam Strange. Sin embargo, al otro lado del universo, Mr. Terrific no va a encontrar mucha colaboración o testigos amistosos. Adam Strange es su héroe. Adam Strange es su campeón.','\r',char(13)),'\n',char(10)),NULL,NULL,376,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002714413-ho5c2a.jpg','read',0,NULL,NULL,'2026-04-12 14:05:15','2026-04-12 16:13:40',201,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"},{"name":"Evan Shaner","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1742,'Strange Adventures #5','Strange Adventures',5,NULL,'978-8-418-56900-5',NULL,'Tom King','Mitch Gerads',NULL,NULL,'ECC Ediciones',NULL,'2021-02-02',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Strange Adventures núm. 5 USA\r\nMr. Terrific ha regresado a la Tierra y las cosas no pintan bien ni para él ni para Adam Strange. ¿Cómo evitar que el caso se vuelva un asunto personal? Además, a medida que somos testigos de más aventuras de Adam en el espacio exterior, ¿coincidirá su versión con los hechos reales?','\r',char(13)),'\n',char(10)),NULL,NULL,376,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002716303-gpr5vp.jpg','read',0,NULL,NULL,'2026-04-12 14:05:17','2026-04-12 16:13:40',201,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"},{"name":"Evan Shaner","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1743,'Strange Adventures #6','Strange Adventures',6,NULL,'978-8-418-56960-9',NULL,'Tom King','Mitch Gerads',NULL,NULL,'ECC Ediciones',NULL,'2021-03-02',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Strange Adventures núm. 6 USA\r\nAdam Strange es un héroe que puede salvar a la Tierra de una invasión alienígena, y ¿quién es Mr. Terrific para afirmar lo contrario? Las sospechas aumentan y el mundo se vuelve en contra del investigador. Adam y su esposa ya derrotaron una vez a los pykktos, y la clave para vencerlos de nuevo está en el pasado. ¡Sigue uno de los cómics del año!','\r',char(13)),'\n',char(10)),NULL,NULL,376,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002718867-c4nr6s.jpg','read',0,NULL,NULL,'2026-04-12 14:05:19','2026-04-12 16:13:40',201,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"},{"name":"Evan Shaner","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1744,'Strange Adventures #7','Strange Adventures',7,NULL,'978-8-418-65846-4',NULL,'Tom King','Mitch Gerads',NULL,NULL,'ECC Ediciones',NULL,'2021-03-30',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Strange Adventures núm. 7 USA\r\n¡Adam Strange tenía razón! Los pykktos han llegado a la Tierra y planean su conquista. Los héroes se han enfrentado antes a invasiones alienígenas, pero nunca han combatido a una fuerza tan formidable, tan decidida y tan mortífera. El único que conoce lo necesario para vencer es Adam Strange, ¡pero la última vez que lo logró casi pierde la cordura en el proceso! Ahora, si la humanidad quiere sobrevivir, Mr. Terrific tendrá que descubrir el secreto mejor guardado de la familia Strange.','\r',char(13)),'\n',char(10)),NULL,NULL,376,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002720749-30p0iw.jpg','read',0,NULL,NULL,'2026-04-12 14:05:21','2026-04-12 16:13:40',201,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"},{"name":"Evan Shaner","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1745,'Strange Adventures #8','Strange Adventures',8,NULL,'978-8-418-66016-0',NULL,'Tom King','Mitch Gerads',NULL,NULL,'ECC Ediciones',NULL,'2021-05-04',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Strange Adventures núm. 8 USA\r\n¡La batalla contra los pykktos continúa! La Liga de la Justicia, incluyendo a Green Lantern, el Doctor Destino, Batman, Flash, Superman y Wonder Woman, han hecho retroceder a los invasores. Incluso Mr. Terrific se ha tomado un descanso en su investigación para arrear a un par de alienígenas. Pero Adam Strange ha tomado ya una decisión: salvar a Rann a cualquier precio, ¡incluso si eso supone la destrucción de la Tierra!','\r',char(13)),'\n',char(10)),NULL,NULL,376,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002723124-6bnvvp.jpg','read',0,NULL,NULL,'2026-04-12 14:05:23','2026-04-12 16:13:40',201,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"},{"name":"Evan Shaner","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1746,'Strange Adventures #9','Strange Adventures',9,NULL,'978-8-418-78412-5',NULL,'Tom King','Mitch Gerads',NULL,NULL,'ECC Ediciones',NULL,'2021-07-27',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Strange Adventures núm. 9 USA\r\nAdam Strange lidera a los héroes más poderosos del planeta en una guerra total contra los pykktos. Al mismo tiempo, aumentan las pruebas que afirman que Adam no ha contado toda la verdad sobre su primera victoria sobre los invasores. Incluso Batman ha empezado a cuestionarse todo. ¿Quién responderá por el héroe? Alanna Strange, por supuesto. Es hora de que la princesa de Rann deje las cosas claras.','\r',char(13)),'\n',char(10)),NULL,NULL,376,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002725529-4qjnp6.jpg','read',0,NULL,NULL,'2026-04-12 14:05:26','2026-04-12 16:13:40',201,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"},{"name":"Evan Shaner","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1747,'Strange Adventures #10','Strange Adventures',10,NULL,'978-8-418-86245-8',NULL,'Tom King','Mitch Gerads',NULL,NULL,'ECC Ediciones',NULL,'2021-09-29',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Strange Adventures núm. 10 USA\r\nHabía una vez un planeta llamado Rann. En este remoto planeta, un hombre Adam Strange hizo un trato para impedir el avance de los invasores pykktos. Ahora, en la Tierra, Strange trata de repetir la jugada: que todos los héroes se unan para evitar que los merodeadores le hagan a su planeta de origen lo mismo que ya hicieron a su planeta de adopción. Pero el trato original fue un trato con el diablo, y Alanna Strange ha recibido una carta misteriosa al respecto. Si quiere mantener a salvo a su marido, es hora de atacar.','\r',char(13)),'\n',char(10)),NULL,NULL,376,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002727888-eltv4p.jpg','read',0,NULL,NULL,'2026-04-12 14:05:28','2026-04-12 16:13:40',201,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"},{"name":"Evan Shaner","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1748,'Strange Adventures #11','Strange Adventures',11,NULL,'978-8-418-93140-6',NULL,'Tom King','Mitch Gerads',NULL,NULL,'ECC Ediciones',NULL,'2021-11-03',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Strange Adventures núm. 11 USA\r\nAdam Strange puede salvar al mundo. Pero, ¿podrá salvar su matrimonio? Hay cosas que sucedieron en la guerra original contra los pykktos que Adam nunca contó a su esposa, Alanna, ¡y ahora ella quiere respuestas! ¿Cuál fue el precio de la victoria? ¿Hay algo de verdad en el relato del héroe? En este número encontrarás muchas respuestas, justo antes de la colisión de las dos líneas temporales.','\r',char(13)),'\n',char(10)),NULL,NULL,376,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002729716-jdec5j.jpg','read',0,NULL,NULL,'2026-04-12 14:05:30','2026-04-12 16:13:40',201,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"},{"name":"Evan Shaner","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1749,'Strange Adventures #12','Strange Adventures',12,NULL,'978-8-419-02158-8',NULL,'Tom King','Mitch Gerads',NULL,NULL,'ECC Ediciones',NULL,'2022-02-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Strange Adventures núm. 12 USA\r\nMister Terrific ha expuesto los secretos más profundos y oscuros de Adam Strange. Si Adam cometió crímenes de guerra, debe ser castigado. Pero, ¿cómo sacar a un héroe del campo de batalla cuando está evitando una invasión alienígena que solo él puede detener? ¿Y si Terrific está equivocado? La única que tiene todas las respuestas es Alanna Strange. ¡Aquí termina una de las miniseries del año!','\r',char(13)),'\n',char(10)),NULL,NULL,376,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002731762-9hnte5.jpg','read',0,NULL,NULL,'2026-04-12 14:05:32','2026-04-12 16:13:40',201,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"},{"name":"Evan Shaner","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1750,'Superman: El hombre de acero (2013-2015) #1','Superman: El hombre de acero (2013-2015)',1,NULL,'978-8-415-92586-6',NULL,'Scott Snyder','Jim Lee',NULL,NULL,'ECC Ediciones',NULL,'2013-11-01',NULL,NULL,replace(replace('Enviado a la Tierra para que sobreviviera a la explosión de Krypton, su planeta natal, el pequeño Kal-El se crio en la pacífica Smallville como Clark Kent. Ya adulto, se mudó a Metropolis, donde ejerció como periodista en el Daily Star y el Daily Planet, publicación que abandonó debido a diferencias con su actual directiva. Y además, es Superman, el hombre más poderoso y respetado del mundo. No obstante, durante sus inicios como superhéroe, tuvo que huir del ejército de EE.UU. y, sobre todo, del general Sam Lane.\r\nEDICIÓN ORIGINAL: Superman Unchained núm. 1 USA\r\nFORMATO: Grapa, 32 págs. A color.\r\nPVP: 2,50€','\r',char(13)),'\n',char(10)),NULL,NULL,352,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002755257-pz9nib.jpg','read',0,NULL,NULL,'2026-04-12 14:05:58','2026-04-12 16:13:40',202,24.95,'Grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Jim Lee","role":"Dibujo"},{"name":"Dustin Nguyen","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1751,'Superman: El hombre de acero (2013-2015) #2','Superman: El hombre de acero (2013-2015)',2,NULL,'978-8-415-99012-3',NULL,'Scott Snyder','Jim Lee',NULL,NULL,'ECC Ediciones',NULL,'2013-12-01',NULL,NULL,replace(replace('Superman Unchained núm. 2 USA\rAlguien ha estado lanzando satélites e incluso una estación espacial contra la Tierra, y Superman sospecha de Lex Luthor aunque también exista la posibilidad de que haya sido un grupo ciberterrorista conocido como Ascensión. Mientras tanto, unos pescadores recogen en alta mar a un hombre que busca desesperadamente a Lois Lane por algún motivo desconocido. Por su parte, el padre de la periodista, general del ejército de Estados Unidos, desvela que guarda una baza importante: el “auténtico Superman”.\rEDICIÓN ORIGINAL:\r\nSuperman Unchained núm. 2 USA\rFORMATO:\r\nGrapa, 32 págs. A color.\rPVP: 2,50€','\r',char(13)),'\n',char(10)),NULL,NULL,352,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002761371-lbd1bl.jpg','read',0,NULL,NULL,'2026-04-12 14:06:02','2026-04-12 16:13:40',202,NULL,'Grapa','[{"name":"Scott Snyder","role":""},{"name":"Jim Lee","role":""},{"name":"Dustin Nguyen","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1752,'Superman: El hombre de acero (2013-2015) #3','Superman: El hombre de acero (2013-2015)',3,NULL,'978-8-415-99044-4',NULL,'Scott Snyder','Jim Lee',NULL,NULL,'ECC Ediciones',NULL,'2014-01-03',NULL,NULL,replace(replace('Lois Lane se dirige a Canadá para reunirse con un miembro de Ascensión, un grupo ciberterrorista que ha desatado el caos en las calles de Dubái por medio de un monstruo mecánico que Superman consigue detener con más esfuerzo del habitual. Poco después, el héroe descubre una base secreta del ejército de Estados Unidos donde el General Lane alberga a un ser de inmenso poder que parece tener cuentas pendientes con el Hombre de Acero. Mientras tanto, Lex Luthor se fuga del Buche para “salvar el mundo”.\r\nEDICIÓN ORIGINAL: Superman Unchained núm. 3 USA\r\nFORMATO: Grapa, 32 págs. A color.\r\nPVP: 2,50€','\r',char(13)),'\n',char(10)),NULL,NULL,352,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002763975-8ib8hk.jpg','read',0,NULL,NULL,'2026-04-12 14:06:04','2026-04-12 16:13:40',202,NULL,'Grapa','[{"name":"Scott Snyder","role":""},{"name":"Jim Lee","role":""},{"name":"Dustin Nguyen","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1753,'Superman: El hombre de acero (2013-2015) #4','Superman: El hombre de acero (2013-2015)',4,NULL,'978-8-415-99072-7',NULL,'Scott Snyder','Jim Lee',NULL,NULL,'ECC Ediciones',NULL,'2014-01-31',NULL,NULL,'Superman ha descubierto la existencia del Espíritu, un alienígena que ha sido el arma secreta del ejército estadounidense desde 1938 y con el que ahora debe colaborar para impedir que Ascensión arrase Tokio. Es precisamente un miembro de esta organización ciberterrorista quien ha hecho ir a Lois Lane a Nueva Escocia con un objetivo no demasiado claro. Por su parte, tras protagonizar una sonada fuga de una prisión de máxima seguridad, Lex Luthor ha ido a buscar a su próximo objetivo: ¡Jimmy Olsen!',NULL,NULL,352,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002766214-2ui152.jpg','read',0,NULL,NULL,'2026-04-12 14:06:07','2026-04-12 16:13:40',202,NULL,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Jim Lee","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1754,'Superman: El hombre de acero (2013-2015) #5','Superman: El hombre de acero (2013-2015)',5,NULL,'978-8-416-07043-5',NULL,'Scott Snyder','Jim Lee',NULL,NULL,'ECC Ediciones',NULL,'2014-03-31',NULL,NULL,'Superman y Espíritu, el alienígena que ha sido arma secreta del ejército estadounidense desde 1938, salvan Tokio del ataque de Ascensión, un grupo ciberterrorista. Precisamente, un antiguo miembro de la organización se reune con Lois Lane, cuyo avión se ha estrellado de camino a Nueva Escocia, para entregarle una misteriosa esquirla que, según él, es la clave de todo. Poco después, Ascensión rapta a la periodista y le proporciona una información inquietante: el creador del grupo fue el mismísimo General Lane.',NULL,NULL,352,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002773082-u7jn3h.jpg','read',0,NULL,NULL,'2026-04-12 14:06:13','2026-04-12 16:13:40',202,NULL,'grapa','[{"name":"Scott Snyder","role":""},{"name":"Jim Lee","role":""},{"name":"Dustin Nguyen","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1755,'Superman: El hombre de acero (2013-2015) #6','Superman: El hombre de acero (2013-2015)',6,NULL,'978-8-416-15210-0',NULL,'Scott Snyder','Jim Lee',NULL,NULL,'ECC Ediciones',NULL,'2014-05-30',NULL,NULL,'Mientras le enseña nuevos poderes, Espíritu, el arma secreta del ejército estadounidense, acompaña a Superman a buscar a Lois Lane, cuyo avión se ha estrellado. En realidad, la periodista está presa de Ascensión, un grupo terrorista que ha inventado el cristal terrestre, una tecnología con la que pretende que la humanidad empiece de cero y evolucione sin ayuda alienígena. Por su parte, Batman y Wonder Woman han detectado un hecho insólito: alguien ha lanzado todos los misiles nucleares de la Tierra.',NULL,NULL,352,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002775863-zw503h.jpg','read',0,NULL,NULL,'2026-04-12 14:06:17','2026-04-12 16:13:40',202,NULL,'grapa','[{"name":"Scott Snyder","role":""},{"name":"Jim Lee","role":""},{"name":"Dustin Nguyen","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1756,'Superman: El hombre de acero (2013-2015) #7','Superman: El hombre de acero (2013-2015)',7,NULL,'978-8-416-15296-4',NULL,'Scott Snyder','Jim Lee',NULL,NULL,'ECC Ediciones',NULL,'2014-10-01',NULL,NULL,'Superman ha logrado salvar a Lois Lane de Ascensión. La periodista se ha llevado el Cristal Terrestre, el artefacto creado por estos terroristas que, según Espíritu, debe estar en manos del ejercito para realizar el debido estudio. Comienza así una batalla entre los dos super seres que termina cuando Superman utiliza un anillo inventado por Batman que neutraliza los poderes de Espíritu. No obstante, el General Lane no duda en asediar la Fortaleza de la Soledad mientras Espíritu acude a la batcueva...',NULL,NULL,352,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002778668-zi8g9l.jpg','read',0,NULL,NULL,'2026-04-12 14:06:20','2026-04-12 16:13:40',202,NULL,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Jim Lee","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1757,'Superman: El hombre de acero (2013-2015) #8','Superman: El hombre de acero (2013-2015)',8,NULL,'978-8-416-25557-3',NULL,'Scott Snyder','Jim Lee',NULL,NULL,'ECC Ediciones',NULL,'2014-12-01',NULL,NULL,'Tras una batalla contra Espíritu, Superman se retira a la Fortaleza de la Soledad con Lois Lane y el cristal terrestre que entregó a esta un agente de la Ascensión. Mientras investigan, el General Sam Lane aparece en el Ártico para reivindicarlo, y lo acompaña un numeroso ejército al que el Hombre de Acero deberá hacer frente en solitario. Pero Kal-El no tardará en acudir a uno de sus más fieles aliados, mientras Jimmy Olsen sigue en paradero desconocido',NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002784821-0gd1iw.jpg','read',0,NULL,NULL,'2026-04-12 14:06:25','2026-04-12 16:13:40',202,NULL,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Jim Lee","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1758,'Superman: El hombre de acero (2013-2015) #9','Superman: El hombre de acero (2013-2015)',9,NULL,'978-8-416-25597-9',NULL,'Scott Snyder','Jim Lee',NULL,NULL,'ECC Ediciones',NULL,'2015-01-28',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Superman: Unchained núm. 9 USA\r\nSuperman libra la batalla final contra Espíritu, el alienígena que ha sido el arma secreta del ejército de Estados Unidos desde poco antes del inicio de la Segunda Guerra Mundial. Tras dejarlo atrapado en el interior de la Tierra, el Hombre de Acero regresa a la Fortaleza de la Soledad, donde le aguarda una ingrata sorpresa. Y es que, tras liberar a Jimmy Olasen, Lex Luthor le comunica que una flota alienígena se dispone a invadir nuestro planeta...','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002787388-b2gadf.jpg','read',0,NULL,NULL,'2026-04-12 14:06:28','2026-04-12 16:13:40',202,NULL,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Jim Lee","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1759,'Supergirl: La mujer del mañana #1','Supergirl: La mujer del mañana',1,NULL,'978-8-419-02198-4',NULL,'Tom King','Bilquis Evely',NULL,NULL,'ECC Ediciones',NULL,'2022-02-08',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Supergirl: Woman of Tomorrow núm. 1 USA\r\nUna joven que sufrió la destrucción de su mundo natal y que fue enviada a la Tierra para proteger a un primo que no la necesitaba. Kara Zor-El ha vivido algunas aventuras épicas a lo largo de los últimos años, pero ahora su vida no tiene ni sentido ni propósito. Es el momento de emprender un viaje que cambiará para siempre a Supergirl, escrito por el premiado Tom King y dibujado por la artista revelación Bilquis Evely.','\r',char(13)),'\n',char(10)),NULL,NULL,224,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002853821-45ifyh.jpg','read',0,NULL,NULL,'2026-04-12 14:07:37','2026-04-12 16:13:40',203,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Bilquis Evely","role":"Dibujo, Tinta"},{"name":"Mat Lopes","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1760,'Supergirl: La mujer del mañana #2','Supergirl: La mujer del mañana',2,NULL,'978-8-419-18681-2',NULL,'Tom King','Bilquis Evely',NULL,NULL,'ECC Ediciones',NULL,'2022-03-08',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Supergirl: Woman of Tomorrow núm. 2 USA\r\nTras la impactante conclusión del primer número, Supergirl y su nueva amiga Ruthye están varadas en medio del espacio. ¿La solución? ¡Un autobús cósmico! ¿Podrá Kara Zor-El pasar desapercibida?','\r',char(13)),'\n',char(10)),NULL,NULL,224,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002861520-xhhp5e.jpg','read',0,NULL,NULL,'2026-04-12 14:07:42','2026-04-12 16:13:40',203,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Bilquis Evely","role":"Dibujo, Tinta"},{"name":"Mat Lopes","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1761,'Supergirl: La mujer del mañana #3','Supergirl: La mujer del mañana',3,NULL,'978-8-419-21058-6',NULL,'Tom King','Bilquis Evely',NULL,NULL,'ECC Ediciones',NULL,'2022-04-12',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Supergirl: Woman of Tomorrow núm. 3 USA\r\n¡El viaje de Supergirl a través del cosmos sigue aquí! La búsqueda del asesino la conduce a un pequeño planeta en el borde exterior de la galaxia. La fría bienvenida hace sospechar a la Mujer de Acero. ¿Qué secretos ocultan? ¿Lograrán escapar con vida Ruthye y ella?','\r',char(13)),'\n',char(10)),NULL,NULL,224,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002863335-ywb4ot.jpg','read',0,NULL,NULL,'2026-04-12 14:07:44','2026-04-12 16:13:40',203,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Bilquis Evely","role":"Dibujo, Tinta"},{"name":"Mat Lopes","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1762,'Supergirl: La mujer del mañana #4','Supergirl: La mujer del mañana',4,NULL,'978-8-419-27905-7',NULL,'Tom King','Bilquis Evely',NULL,NULL,'ECC Ediciones',NULL,'2022-05-10',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Supergirl: Woman of Tomorrow núm. 4 USA\r\nSupergirl se topa con los Bandoleros, un grupo de cobardes nómadas empeñados en sembrar el caos allá por donde pasan. Kara Zor-El debe seguir el reguero de destrucción para encontrar al fugitivo al que están ayudando a esconder y que provocó este viaje intergaláctico...','\r',char(13)),'\n',char(10)),NULL,NULL,224,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002866998-ia9ri9.jpg','read',0,NULL,NULL,'2026-04-12 14:07:47','2026-04-12 16:13:40',203,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Bilquis Evely","role":"Dibujo, Tinta"},{"name":"Mat Lopes","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1763,'Supergirl: La mujer del mañana #5','Supergirl: La mujer del mañana',5,NULL,'978-8-419-27985-9',NULL,'Tom King','Bilquis Evely',NULL,NULL,'ECC Ediciones',NULL,'2022-06-08',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Superman: Woman of Tomorrow núm. 5 USA\r\nSupergirl cae en una trampa y ahora tanto ella como Ruthye están atrapadas en un planeta de noche casi perpetua. En un ambiente hostil, la Mujer de Acero deberá esforzarse al máximo para acabar con los monstruos que moran en la superficie.','\r',char(13)),'\n',char(10)),NULL,NULL,224,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002869208-3ay2r0.jpg','read',0,NULL,NULL,'2026-04-12 14:07:50','2026-04-12 16:13:40',203,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Bilquis Evely","role":"Dibujo, Tinta"},{"name":"Mat Lopes","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1764,'Supergirl: La mujer del mañana #6','Supergirl: La mujer del mañana',6,NULL,'978-8-419-32566-2',NULL,'Tom King','Bilquis Evely',NULL,NULL,'ECC Ediciones',NULL,'2022-07-05',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Supergirl: Woman of Tomorrow núm. 6 USA\r\n¡Los secretos más traumáticos de Supergirl salen a la luz! Krem, el asesino del padre de la joven Ruthye, planea utilizar su nueva arma para deshacerse de Kara para siempre.','\r',char(13)),'\n',char(10)),NULL,NULL,224,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002871114-6k0tft.jpg','read',0,NULL,NULL,'2026-04-12 14:07:51','2026-04-12 16:13:40',203,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Bilquis Evely","role":"Dibujo, Tinta"},{"name":"Mat Lopes","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1765,'Supergirl: La mujer del mañana #7','Supergirl: La mujer del mañana',7,NULL,'978-8-419-35136-4',NULL,'Tom King','Bilquis Evely',NULL,NULL,'ECC Ediciones',NULL,'2022-08-02',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Supergirl: Woman of Tomorrow núm. 7 USA\r\nEs el momento que estabais esperando... ¡La captura de Krem! Con el fugitivo bajo custodia, Supergirl debe ahora lidiar con sus aliados, los Bandoleros. Para detenerlos de una vez por todas, deberá dejar a Ruthye con el hombre que mató a su amado padre. ¿Puede confiar en la joven?','\r',char(13)),'\n',char(10)),NULL,NULL,224,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002873262-akvnbr.jpg','read',0,NULL,NULL,'2026-04-12 14:07:54','2026-04-12 16:13:40',203,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Bilquis Evely","role":"Dibujo, Tinta"},{"name":"Mat Lopes","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1766,'Supergirl: La mujer del mañana #8','Supergirl: La mujer del mañana',8,NULL,'978-8-419-42829-5',NULL,'Tom King','Bilquis Evely',NULL,NULL,'ECC Ediciones',NULL,'2022-09-06',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Supergirl: Woman of Tomorrow núm. 8 USA\r\n¡La emocionante conclusión de la aclamada miniserie que ha cambiado a Kara Zor-El para siempre! ¿Qué destino le espera a Krem? Mientras Supergirl continúa su batalla contra los Bandidos, Ruthye se enfrenta al villano. ¿Se hará justicia?','\r',char(13)),'\n',char(10)),NULL,NULL,224,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002876087-l0b7te.jpg','read',0,NULL,NULL,'2026-04-12 14:07:57','2026-04-12 16:13:40',203,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Bilquis Evely","role":"Dibujo, Tinta"},{"name":"Mat Lopes","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1767,'All-Star Batman. Renacimiento #1','All-Star Batman. Renacimiento',1,NULL,'978-8-416-94531-3',NULL,'Scott Snyder','John Romita Jr.',NULL,NULL,'ECC Ediciones',NULL,'2016-12-20',NULL,NULL,replace('EDICIÓN ORIGINAL: All-Star Batman núm. 1 USA\rARGUMENTO: Batman debe trasladar a Dos Caras a un lugar fuera de la ciudad de Gotham, pero el villano tiene un par de ases bajo la manga. Todo asesino, cazarrecompensas y ciudadano ordinario con algo que esconder les pisa los talones con un solo objetivo: ¡matar a Batman!','\r',char(13)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002918641-6ofyvo.jpg','read',0,NULL,NULL,'2026-04-12 14:08:42','2026-04-12 16:13:40',169,24.95,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"John Romita Jr.","role":"Dibujo"},{"name":"Danny Miki","role":"Tinta"},{"name":"Dean White","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1768,'All-Star Batman. Renacimiento #2','All-Star Batman. Renacimiento',2,NULL,'978-8-416-94573-3',NULL,'Scott Snyder','John Romita Jr.',NULL,NULL,'ECC Ediciones',NULL,'2017-01-31',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: All-Star Batman núm. 2 USA, All-Star Batman núm. 1 USA (historia de complemento) \r\nARGUMENTO: ¡Todos a bordo del tren del infierno! El Hombre Murciélago y Dos Caras continúan su viaje hacia la supuesta curación de Harvey Dent, a través de un paraje repleto de enemigos. Pero... ¿será capaz Batman de seguir adelante cuando el propio Dos Caras se convierta en su gran oponente? Además, esta entrega incluye las historias de complemento de los dos primeros ejemplares de la edición americana de la serie.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002926217-79aqja.jpg','read',0,NULL,NULL,'2026-04-12 14:08:47','2026-04-12 16:13:40',169,NULL,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"John Romita Jr.","role":"Dibujo"},{"name":"Declan Shalvey","role":"Dibujo, Tinta"},{"name":"Danny Miki","role":"Tinta"},{"name":"Dean White","role":"Color"},{"name":"Jordie Bellaire","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1769,'All-Star Batman. Renacimiento #3','All-Star Batman. Renacimiento',3,NULL,'978-8-416-99828-9',NULL,'Scott Snyder','John Romita Jr.',NULL,NULL,'ECC Ediciones',NULL,'2017-02-28',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: All-Star Batman núm. 3 USA   \r\nARGUMENTO: Batman y un conocido aliado deben encontrar un lugar seguro en el que esconderse junto a Dos Caras antes de continuar con su viaje, entre cazadores de recompensas y policías. En medio de todo ello, el Caballero Oscuro podría ver cumplida su peor pesadilla: Dos Caras ha ganado su arriesgada apuesta... y ningún lugar es ya seguro.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002928379-eawxe7.jpg','read',0,NULL,NULL,'2026-04-12 14:08:49','2026-04-12 16:13:40',169,NULL,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"John Romita Jr.","role":"Dibujo"},{"name":"Declan Shalvey","role":"Dibujo, Tinta"},{"name":"Danny Miki","role":"Tinta"},{"name":"Dean White","role":"Color"},{"name":"Jordie Bellaire","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1770,'All-Star Batman. Renacimiento #4','All-Star Batman. Renacimiento',4,NULL,'978-8-417-06350-4',NULL,'Scott Snyder','John Romita Jr.',NULL,NULL,'ECC Ediciones',NULL,'2017-03-28',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: All-Star Batman núm. 4 USA \r\nARGUMENTO: Tan cerca y tan lejos de su objetivo, Batman debe ahora enfrentarse a Dos Caras en un sorprendente e inesperado escenario flotante, antes de que ambos se precipiten a una muerte segura. El Caballero Oscuro tendrá poner todo de su parte si quiere salir con vida del juego de azar más peligroso al que se ha enfrentado en toda su trayectoria.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002930411-ryr0w0.jpg','read',0,NULL,NULL,'2026-04-12 14:08:51','2026-04-12 16:13:40',169,NULL,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"John Romita Jr.","role":"Dibujo"},{"name":"Declan Shalvey","role":"Dibujo, Tinta"},{"name":"Jordie Bellaire","role":"Color"},{"name":"Danny Miki","role":"Tinta"},{"name":"Dean White","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1771,'All-Star Batman. Renacimiento #5','All-Star Batman. Renacimiento',5,NULL,'978-8-417-07152-3',NULL,'Scott Snyder','John Romita Jr.',NULL,NULL,'ECC Ediciones',NULL,'2017-05-09',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: All-Star Batman núm. 5 USA   \r\nARGUMENTO: ¡La conclusión de Yo, mi peor enemigo y la despedida de John Romita Jr.! ¡Batman, Duke y Dos Caras luchan sin cuartel por el destino del alma de Harvey Dent! Con sus incansables perseguidores cada vez más cerca del lugar de la batalla, el Hombre Murciélago descubrirá que incluso sus más fieles aliados pueden elegir el mal sobre el bien.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002932690-552lhg.jpg','read',0,NULL,NULL,'2026-04-12 14:08:53','2026-04-12 16:13:40',169,NULL,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"John Romita Jr.","role":"Dibujo"},{"name":"Danny Miki","role":"Tinta"},{"name":"Tom Palmer","role":"Tinta"},{"name":"Sandra Hope","role":"Tinta"},{"name":"Richard Friend","role":"Tinta"},{"name":"Dean White","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1772,'Batman / Superman. Nuevo Universo DC #1','Batman / Superman. Nuevo Universo DC',1,NULL,'978-8-415-92582-8',NULL,'Greg Pak','Jae Lee',NULL,NULL,'ECC Ediciones',NULL,'2013-11-01',NULL,NULL,replace(replace('USA: Batman / Superman Vol. 1 nº 01 y complementos de Batman Vol. 2 nº 19 y 20\r\nHistoria: \r\nEncrucijada de Mundos / Luces fantasmales\r\nAntes de que el planeta Krypton explotara, el pequeño Kal-El fue enviado a la Tierra en una nave y llegó a Smallville (Kansas), donde los Kent le adoptarían y sus extraordinarios poderes le permitirían asumir la identidad del Hombre de Acero. En Gotham City, un niño llamado Bruce Wayne perdería trágicamente a sus padres en un atraco callejero y consagraría su vida a evitar todo crimen parecido con su cruzada personal como el Caballero Oscuro. Juntos son los mejores del mundo: Superman y Batman.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002949486-u4nzen.jpg','read',0,NULL,NULL,'2026-04-12 14:09:12','2026-04-12 16:13:40',204,24.95,'grapa','[{"name":"Greg Pak","role":"Guion"},{"name":"James Tynion IV","role":"Guion"},{"name":"Jae Lee","role":"Dibujo"},{"name":"Ben Oliver","role":"Dibujo"},{"name":"Alex Maleev","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1773,'Batman / Superman. Nuevo Universo DC #2','Batman / Superman. Nuevo Universo DC',2,NULL,'978-8-415-99006-2',NULL,'Greg Pak','Jeff Parker',NULL,NULL,'ECC Ediciones',NULL,'2013-12-01',NULL,NULL,replace('USA: Batman/Superman Vol. 1 nº 02, Adventures of Superman Vol. 2 nº 01\rHistoria:\rDoble Jornada / Mentes violentas\rTras encontrarse por primera vez en Gotham City, bajo sus identidades civiles de Bruce Wayne y Clark Kent, Batman y Superman emprenden una aventura conjunta como adversarios en Metropolis... Pero enton- ces una misteriosa enemiga común parece desplazarles a otro planeta, Tierra 2, donde el joven Hombre de Acero se enfrentará en Smallville a una versión alternativa del Caballero Oscuro. Y el combate contará con un testigo de excepción... Jonathan Kent, el padre de Clark, que sigue vivo en ese mundo.','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002991733-8hwc76.jpg','read',0,NULL,NULL,'2026-04-12 14:09:52','2026-04-12 16:13:40',204,NULL,'grapa','[{"name":"Greg Pak","role":""},{"name":"Jeff Parker","role":""},{"name":"Jae Lee","role":""},{"name":"Chris Samnee","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1774,'Batman / Superman. Nuevo Universo DC #3','Batman / Superman. Nuevo Universo DC',3,NULL,'978-8-415-99036-9',NULL,'Greg Pak','Jeff Lemire',NULL,NULL,'ECC Ediciones',NULL,'2013-12-31',NULL,NULL,replace(replace('USA: Batman/Superman Vol. 1 nº 03, Adventures of Superman Vol. 2 nº 01\rHistoria:\rPantalla partida / Fortaleza\rAtrapados en Tierra 2 por una misteriosa enemiga, Batman y Superman se enfrentan a sus contrapartidas de ese planeta y terminan aliándose con ellas. Allí los padres de Clark siguen vivos y la tecnología de Bruce ha mejorado la sociedad mundial, el Psiquiátrico de Arkham es un parque de atracciones y Lois Lane, la cónyuge del Hombre de Acero. Pero... ¿podrá la Wonder Woman de Tierra 2, con su Lazo de la Verdad, lograr que la adversaria de los héroes revele su identidad y quizá sus auténticos planes?\rFORMATO:\r\nGrapa, 32 págs. A color.\r\nPVP: 2,50€','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002993984-6hbylq.jpg','read',0,NULL,NULL,'2026-04-12 14:09:55','2026-04-12 16:13:40',204,NULL,'Grapa','[{"name":"Greg Pak","role":""},{"name":"Jeff Lemire","role":""},{"name":"Jae Lee","role":""},{"name":"Yildiray Cinar","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1775,'Batman / Superman. Nuevo Universo DC #4','Batman / Superman. Nuevo Universo DC',4,NULL,'978841599066',NULL,'Greg Pak','Justin Jordan',NULL,NULL,'ECC Ediciones',NULL,'2014-01-31',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman/Superman núm. 4 USA y Adventures of Superman núm. 1 USA\rKaiyo, la Portadora del Caos, atrajo a Batman y Superman hasta Tierra 2, donde se aliaron con sus veteranos homólogos de aquel planeta. Sin embargo, en ese mundo alternativo parecía esconderse un arma muy poderosa: un fragmento cristalino capaz de hacer realidad los deseos. Así, cuando el cuarteto de héroes se encuentra ante el cristal, Kaiyo afirma que cada dúo de Hombre de Acero y Caballero Oscuro deberá luchar contra el otro si quiere que su Tierra prevalezca ante Darkseid. Pero... ¿lo harán?\r\n-EDICIÓN ORIGINAL: Batman/Superman núm. 4 USA y Adventures of Superman núm. 1 USA (historia de complemento)\r\n-FORMATO: Grapa, 32 págs. A color.\r\n-PVP: 2,50€','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776002996221-tgn5p3.jpg','read',0,NULL,NULL,'2026-04-12 14:09:56','2026-04-12 16:13:40',204,NULL,'Grapa','[{"name":"Greg Pak","role":""},{"name":"Justin Jordan","role":""},{"name":"Jae Lee","role":""},{"name":"Riley Rossmo","role":""}]');
