INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1777,'Batman / Superman. Nuevo Universo DC #6','Batman / Superman. Nuevo Universo DC',6,NULL,'978-8-416-07036-7',NULL,'Greg Pak','Tom Taylor',NULL,NULL,'ECC Ediciones',NULL,'2014-03-31',NULL,NULL,replace('EDICIÓN ORIGINAL: Justice League núm. 23.1 USA y Legends of the Dark Knight núm. 1 USA \rBatman y Superman regresaron de Tierra 2 sin recordar lo ocurrido “gracias” a la malévola Kaiyo. Y si el anterior número de esta colección nos presentaba a Juicio Final como una criatura de naturaleza casi legendaria, arraigada en el pasado del planeta Krypton y vinculada a la Casa de El, en este podremos conocer la génesis de otro de los mayores antagonistas de la comunidad superheroica: Darkseid, Señor de Apokolips. En estas páginas, además de su origen, quedará revelado lo que le une a Kaiyo...','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003000202-us11pc.jpg','read',0,NULL,NULL,'2026-04-12 14:10:01','2026-04-12 16:13:40',204,NULL,'grapa','[{"name":"Greg Pak","role":""},{"name":"Tom Taylor","role":""},{"name":"Paulo Siqueira","role":""},{"name":"Nicola Scott","role":""}]');
