INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1780,'Batman / Superman. Nuevo Universo DC #9','Batman / Superman. Nuevo Universo DC',9,NULL,'978-8-416-15255-1',NULL,'Greg Pak','Brett Booth',NULL,NULL,'ECC Ediciones',NULL,'2014-07-01',NULL,NULL,replace(replace('Batman/Superman núm. 7 USA, Batman/Superman annual núm. 1	 USA\r\nUn videojuego online auspiciado por el Maestro Juguetero termina siendo una amenaza nada virtual cuando Mongul ataca la Tierra y revela que ese sistema informático y un extraño polen alienígena propiciarán su conquista del planeta. Batman parecía asesinado por el tirano, pero tan solo se ha convertido en su potente instrumento contra Superman... Falta una hora para que la Tierra caiga ante Mundo Guerra y los mayores héroes de la humanidad están enfrentados. ¿Lograrán dejar de estarlo y salvarla?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003007017-d8ttqj.jpg','read',0,NULL,NULL,'2026-04-12 14:10:07','2026-04-12 16:13:29',204,NULL,'grapa','[{"name":"Greg Pak","role":"Guion"},{"name":"Brett Booth","role":"Dibujo"},{"name":"Jae Lee","role":"Dibujo"},{"name":"Kenneth Rocafort","role":"Dibujo"}]');
