INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1793,'Mr. Milagro #1','Mr. Milagro',1,NULL,'978-8-417-31619-8',NULL,'Tom King','Mitch Gerads',NULL,NULL,'ECC Ediciones',NULL,'2018-01-15',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Mister Miracle Vol.4 #1 (October, 2017), de la edición USA.\r\nScott Free es el mejor escapista que jamás haya existido. Tan habilidoso, que escapó del espantoso orfanato de la Abuelita Bondad y de los peligros del planeta Apokolips para viajar a través del universo y establecerse en la Tierra, iniciando una nueva vida con su esposa, la mujer conocida como Big Barda. Empleando el nombre de Mister Milagro, Scott ha triunfado mostrando sus técnicas acrobáticas, ¡incluso forjó amistad con los componentes de la Liga de la Justicia! Se podría decir que Scott Free lo tiene todo... pero no es suficiente. Mister Milagro domina todos los trucos, excepto uno: evitar a la muerte. ¿Será capaz de lograrlo? Nuestro héroe tendrá que suicidarse si quiere descubrirlo...\r\n¡El equipo creativo que triunfó con El Sheriff de Babilonia da forma a una visión actualizada de uno de los personajes más queridos de Jack Kirby! Tom King (Batman) y Mitch Gerads (The Punisher) te muestran a un Mister Milagro muy diferente a cualquier versión del personaje de El Cuarto Mundo que hayas leído antes. ¡Y ECC Ediciones te lo trae en formato grapa mensual! ¡No te pierdas el nuevo proyecto de los autores del momento!','\r',char(13)),'\n',char(10)),NULL,NULL,24,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003080327-9rpc58.jpg','read',0,NULL,NULL,'2026-04-12 14:11:23','2026-04-12 16:13:29',206,24.95,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1794,'Mr. Milagro #2','Mr. Milagro',2,NULL,'978-8-417-35435-0',NULL,'Tom King','Mitch Gerads',NULL,NULL,'ECC Ediciones',NULL,'2018-02-12',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Mister Miracle Vol.4 #2 (Noviembre, 2017), de la edición USA.\r\nARGUMENTO: ¿Qué hacer cuando en tu carrera como escapista ya has superado todos los retos? ¡Pues te marchas a la guerra, por supuesto! Scott Free y su esposa, Big Barda, protagonizan un nuevo episodio de su viaje al más allá. ¡Un episodio que incluye un épico enfrentamiento contra las hordas de Apokolips! Sin embargo, hay algo que está fuera de lugar en todo esto... ¿por qué decíais que peleaban?','\r',char(13)),'\n',char(10)),NULL,NULL,24,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003089206-5t4024.jpg','read',0,NULL,NULL,'2026-04-12 14:11:30','2026-04-12 16:13:29',206,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1795,'Mr. Milagro #3','Mr. Milagro',3,NULL,'978-8-417-40120-7',NULL,'Tom King','Mitch Gerads',NULL,NULL,'ECC Ediciones',NULL,'2018-03-19',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Mister Miracle Vol.4 #3 (Diciembre de 2017), de la edición USA.\r\nARGUMENTO: Tercer capítulo de la innovadora nueva serie de los creadores de El Sheriff de Babilonia y Batman núm. 63/8. La locura de la guerra es la locura de Mr. Milagro. Darkseid y las fuerzas de Orion se enfrentan a las puertas de Nueva Génesis. Sangre. Gloria. Los Nuevos Dioses luchan sin descanso, hacia la victoria... y hacia una trampa mortal para Scott Free y Big Barda. Hagan lo que hagan, la derrota parece la única conclusión posible.','\r',char(13)),'\n',char(10)),NULL,NULL,24,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003091728-ug5uxd.jpg','read',0,NULL,NULL,'2026-04-12 14:11:32','2026-04-12 16:13:29',206,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1796,'Mr. Milagro #4','Mr. Milagro',4,NULL,'978-8-417-40165-8',NULL,'Tom King','Mitch Gerads',NULL,NULL,'ECC Ediciones',NULL,'2018-04-04',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Mister Miracle Vol.4 #4 (Enero de 2018), de la edición USA.\r\n¡El juicio de Mr. Milagro! Orión y Lightray están convencidos de que Scott está infectado con la ecuación de la Antivida y trabaja para acabar con Nueva Génesis. ¿Sucumbirá el famoso escapista al más duro de los interrogatorios? Y lo más importante, ¿cómo se consigue que personas que no quieren creer acepten la realidad tal y como es?','\r',char(13)),'\n',char(10)),NULL,NULL,24,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003095369-g1h729.jpg','read',0,NULL,NULL,'2026-04-12 14:11:36','2026-04-12 16:13:29',206,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1797,'Mr. Milagro #5','Mr. Milagro',5,NULL,'978-8-417-44176-0',NULL,'Tom King','Mitch Gerads',NULL,NULL,'ECC Ediciones',NULL,'2018-05-22',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Mister Miracle Vol.4 #5 (Febrero de 2018), de la edición USA.\r\nARGUMENTO: Condenado a muerte, debe regresar a Nueva Génesis para su ejecución. Pero antes de cumplir con su destino, Scott viaja a la Tierra para disfrutar de una última cita con la mujer que ama, Big Barda. De todas formas, no hay nada de qué preocuparse: si realmente está infectado por el poder de Darkseid, podéis apostar lo que queráis a que alguna fuerza oscura intervendrá. O quizás no, y aquí termina todo, antes de lo que pensábamos. Sea como sea, tendrás que leerlo para averiguarlo.','\r',char(13)),'\n',char(10)),NULL,NULL,24,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003100002-ng1rxg.jpg','read',0,NULL,NULL,'2026-04-12 14:11:40','2026-04-12 16:13:29',206,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1798,'Mr. Milagro #6','Mr. Milagro',6,NULL,'978-8-417-48036-3',NULL,'Tom King','Mitch Gerads',NULL,NULL,'ECC Ediciones',NULL,'2018-06-19',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Mister Miracle Vol.4 #6 (Marzo de 2018), de la edición USA.\r\n¡La conclusión del primer arco argumental de la exitosa serie limitada! Scott Free regresa a Nueva Génesis para enfrentarse a su castigo final. Pero lo que allí encuentra es muy diferente al mundo que recordaba. Mister Milagro y Big Barda pronto serán conscientes de que la guerra contra Darkseid ha tomado rumbo sangriento. No hay vuelta atrás.','\r',char(13)),'\n',char(10)),NULL,NULL,24,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003101847-vvcafq.jpg','read',0,NULL,NULL,'2026-04-12 14:11:42','2026-04-12 16:13:29',206,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1799,'Mr. Milagro #7','Mr. Milagro',7,NULL,'978-8-417-50948-4',NULL,'Tom King','Mitch Gerads',NULL,NULL,'ECC Ediciones',NULL,'2018-07-17',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Mister Miracle Vol.4 #7 (Mayo de 2018), de la edición USA.\r\nScott Free y Big Barda están en medio de un auténtico ataque de pánico. La guerra con Apokolips no está yendo muy bien. Para colmo de males, el pasado de Barda regresa a la actualidad, cuando las Furias Femeninas aparecen en escena.','\r',char(13)),'\n',char(10)),NULL,NULL,24,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003103844-28etk0.jpg','read',0,NULL,NULL,'2026-04-12 14:11:44','2026-04-12 16:13:29',206,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1800,'Mr. Milagro #8','Mr. Milagro',8,NULL,'978-8-417-54909-1',NULL,'Tom King','Mitch Gerads',NULL,NULL,'ECC Ediciones',NULL,'2018-08-21',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Mister Miracle Vol.4 #8 (Junio de 2018), de la edición USA.\r\nRegreso a la guerra, regreso a Apokolips. Scott Free está inmerso en una sangrienta batalla contra las fuerzas de Darkseid, esta vez sin el apoyo de Big Barda, que tiene que ocuparse de sus propios asuntos... domésticos. Con su atención dividida, ¿será capaz Mr. Milagro de defenderse contra los secuaces del mal?','\r',char(13)),'\n',char(10)),NULL,NULL,24,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003105950-yetjse.jpg','read',0,NULL,NULL,'2026-04-12 14:11:46','2026-04-12 16:13:29',206,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1801,'Mr. Milagro #9','Mr. Milagro',9,NULL,'978-8-417-54977-0',NULL,'Tom King','Mitch Gerads',NULL,NULL,'ECC Ediciones',NULL,'2018-09-19',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Mister Miracle Vol.4 #9 (Agosto de 2018), de la edición USA.\r\n¡La paz después de la guerra! Tras las sangrientas batallas que han tenido lugar en Nueva Génesis y Apokolips, Mister Milagro y Kalibak discuten una tregua. ¿Podrá confiar Scott en los secuaces de Darkseid? Ya sabemos que no, pero a veces un líder debe correr riesgos, por el bien común. Sin embargo, la pregunta más interesante quizás sea otra: ¿Big Barda será capaz de no acabar con la vida de Kanto durante las negociaciones?','\r',char(13)),'\n',char(10)),NULL,NULL,24,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003107951-iqtf9x.jpg','read',0,NULL,NULL,'2026-04-12 14:11:49','2026-04-12 16:13:29',206,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1802,'Mr. Milagro #10','Mr. Milagro',10,NULL,'978-8-417-64403-1',NULL,'Tom King','Mitch Gerads',NULL,NULL,'ECC Ediciones',NULL,'2018-10-09',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Mister Miracle Vol.4 #10 (Octubre de 2018), de la edición USA.\r\nDarkseid ha hecho una oferta que no se puede rechazar, algo que podría terminar con la guerra entre Nueva Génesis y Apokolips de una vez por todas. Ahora, Scott debe tomar una decisión que puede cambiar la nueva vida que ha estado construyendo, ¡y a todo el universo!','\r',char(13)),'\n',char(10)),NULL,NULL,24,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003110134-6u9616.jpg','read',0,NULL,NULL,'2026-04-12 14:11:51','2026-04-12 16:13:29',206,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1803,'Mr. Milagro #11','Mr. Milagro',11,NULL,'978-8-417-64473-4',NULL,'Tom King','Mitch Gerads',NULL,NULL,'ECC Ediciones',NULL,'2018-11-06',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Mister Miracle Vol.4 #11 (Noviembre de 2018), de la edición USA.\r\n¿Qué hemos aprendido después de leer cómics, devorar libros y ver películas durante todos estos años? Que nunca debemos pactar con el diablo. Y sin embargo, Mr. Milagro está dispuesto a escuchar a Darkseid. ¿Desde cuando el señor de Apokolips ha sido conocido por su honestidad? Sería un milagro (je, je) si esto no estalla en la cara de Scott...','\r',char(13)),'\n',char(10)),NULL,NULL,24,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003112572-h72lod.jpg','read',0,NULL,NULL,'2026-04-12 14:11:53','2026-04-12 16:13:29',206,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1804,'Mr. Milagro #12','Mr. Milagro',12,NULL,'978-8-417-66537-1',NULL,'Tom King','Mitch Gerads',NULL,NULL,'ECC Ediciones',NULL,'2019-01-22',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Mister Miracle Vol.4 #12 (Enero de 2019), de la edición USA.\r\nEl final. El milagro (je, je) será que logres llegar a las últimas páginas con tu cordura intacta.','\r',char(13)),'\n',char(10)),NULL,NULL,24,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003114989-9zf3du.jpg','read',0,NULL,NULL,'2026-04-12 14:11:55','2026-04-12 16:13:29',206,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Mitch Gerads","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1805,'Batman/Catwoman #1','Batman/Catwoman',1,NULL,'978-8-418-78410-1',NULL,'Tom King','Clay Mann',NULL,NULL,'ECC Ediciones',NULL,'2021-07-27',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman/Catwoman núm. 1 USA\r\n¡La espera ha terminado! El guionista Tom King (Rorschach) y el dibujante Clay Mann (Héroes en Crisis) retoman la saga romántica de Batman y Catwoman en una de las miniseries más esperadas del año. Tras los sucesos de la etapa de King en la serie Batman, este nuevo capítulo se desarrolla a lo largo de tres líneas temporales diferentes. El pasado, el presente y el futuro de la pareja se entremezcla en una trama en la que participan tres invitados de excepción: Helena, Wayne, la Batwoman del futuro; el Joker y Andrea Beaumont, un antiguo amor de Bruce Wayne, más conocida como el Fantasma.','\r',char(13)),'\n',char(10)),NULL,NULL,424,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003135774-khciqj.jpg','read',0,NULL,NULL,'2026-04-12 14:12:19','2026-04-12 16:13:29',207,24.95,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Clay Mann","role":"Dibujo, Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1806,'Batman/Catwoman #2','Batman/Catwoman',2,NULL,'978-8-418-78483-5',NULL,'Tom King','Clay Mann',NULL,NULL,'ECC Ediciones',NULL,'2021-08-31',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman/Catwoman núm. 2 USA\r\n¡El Fantasma está en Gotham City! Andrea Beaumont, antigua amante de Bruce Wayne, está buscando a su hijo perdido, ¡y está bastante segura de que el Joker está involucrado de alguna manera en su desaparición! Andrea está dispuesta a aliarse con Batman, pero para llegar al Hombre Murciélago, antes tendrá que encontrar a Catwoman, quien también tiene algunas cuentas pendientes con el Príncipe Payaso del Crimen. El pasado, el presente y el futuro se entremezclan en una historia de consecuencias mortales.','\r',char(13)),'\n',char(10)),NULL,NULL,424,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003149859-7ejnev.jpg','read',0,NULL,NULL,'2026-04-12 14:12:30','2026-04-12 16:13:29',207,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Clay Mann","role":"Dibujo, Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1807,'Batman/Catwoman #3','Batman/Catwoman',3,NULL,'978-8-418-86242-7',NULL,'Tom King','Clay Mann',NULL,NULL,'ECC Ediciones',NULL,'2021-09-29',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman/Catwoman núm. 3 USA\r\nEl Joker. Siempre ha sido el Joker. Selina Kyle lo sabe. Al principio de su carrera como Catwoman, él ya estaba allí para arruinarlo todo. Lo mismo ocurrió más tarde, cuando Batman y ella volvieron a estar juntos. Una y otra vez. El tiempo parece reiniciarse en cada ocasión, pero el Príncipe Payaso del Crimen siempre ríe el último. Y ahora está el Fantasma, que también tiene la mirada puesta en Catwoman... y en el Joker. ¿Quién perseguirá a quién?','\r',char(13)),'\n',char(10)),NULL,NULL,424,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003151817-4h9rti.jpg','read',0,NULL,NULL,'2026-04-12 14:12:32','2026-04-12 16:13:29',207,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Clay Mann","role":"Dibujo, Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1808,'Batman/Catwoman #4','Batman/Catwoman',4,NULL,'978-8-418-93139-0',NULL,'Tom King','Clay Mann',NULL,NULL,'ECC Ediciones',NULL,'2021-11-03',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman/Catwoman núm. 4 USA\r\nEl Joker ha escondido una bomba en Gotham. Mientras, Batman se enfrenta a una explosión mucho mayor: un peligroso secreto que amenaza con destruir su relación con Catwoman y cambiar todo lo que creía saber sobre la ladrona felina. En el presente, la revelación afectará al camino que han tomado Selina y Andrea Beaumont, más conocida como el Fantasma, que busca venganza. Una concatenación de eventos que llevará al futuro asesinato del Príncipe Payaso del Crimen. Una madre que no puede ocultar más secretos a su hija. Un villano clásico que también está de vuelta.','\r',char(13)),'\n',char(10)),NULL,NULL,424,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003153851-m28vmt.jpg','read',0,NULL,NULL,'2026-04-12 14:12:34','2026-04-12 16:13:29',207,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Clay Mann","role":"Dibujo, Tinta, Color"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1809,'Batman/Catwoman #5','Batman/Catwoman',5,NULL,'978-8-418-97404-5',NULL,'Tom King','Clay Mann',NULL,NULL,'ECC Ediciones',NULL,'2021-11-30',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman/Catwoman núm. 5 USA\r\nLos dos amores de Batman forman equipo. El resultado podría ser peligroso para el Caballero Oscuro, ¡pero también para el Joker! Para demostrar que su cruzada está justificada, el Fantasma, a espaldas de Batman, lleva a Catwoman frente a uno de los responsables de la desaparición de su hijo. En el futuro, Harley Quinn está lista para la venganza.','\r',char(13)),'\n',char(10)),NULL,NULL,424,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003156368-bf4a88.jpg','read',0,NULL,NULL,'2026-04-12 14:12:37','2026-04-12 16:13:29',207,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Clay Mann","role":"Dibujo, Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1810,'Batman/Catwoman #6','Batman/Catwoman',6,NULL,'978-8-418-97486-1',NULL,'Tom King','Clay Mann',NULL,NULL,'ECC Ediciones',NULL,'2021-12-30',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman/Catwoman núm. 6 USA\r\nMisterios y resentimientos. A lo largo de su vida, las acciones de Catwoman han provocado que muchas personas dudaran de sus motivaciones. Bruce Wayne, el Fantasma y ahora su hija han tenido sospechas sobre sus tratos con el Joker. ¡Grandes revelaciones en el ecuador de la miniserie de Tom King y Clay Mann!','\r',char(13)),'\n',char(10)),NULL,NULL,424,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003159205-cqjq6v.jpg','read',0,NULL,NULL,'2026-04-12 14:12:40','2026-04-12 16:13:29',207,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Clay Mann","role":"Dibujo, Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1811,'Batman/Catwoman #7','Batman/Catwoman',7,NULL,'978-8-419-02157-1',NULL,'Tom King','Liam Sharp',NULL,NULL,'ECC Ediciones',NULL,'2022-02-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman/Catwoman núm. 7 USA\r\nLos problemas en las calles de Gotham crecen cuando Batman comienza a dudar de la lealtad de Catwoman. ¿A quién apoya Selina? A veces es mejor dejar algunas preguntas sin responder, Bats.','\r',char(13)),'\n',char(10)),NULL,NULL,424,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003161880-7uxt0p.jpg','read',0,NULL,NULL,'2026-04-12 14:12:42','2026-04-12 16:13:29',207,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Liam Sharp","role":"Dibujo, Tinta, Color"},{"name":"Clay Mann","role":"Dibujo, Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1812,'Batman/Catwoman #8','Batman/Catwoman',8,NULL,'978-8-419-02191-5',NULL,'Tom King','Liam Sharp',NULL,NULL,'ECC Ediciones',NULL,'2022-03-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman/Catwoman núm. 8 USA\r\nBatman y Catwoman han establecido nuevas reglas en su relación, algo que ha conducido a conflictos internos... y externos, en las calles de Gotham. Los oportunistas, como el Pingüino, esperan a la vuelta de la esquina. ¡El Hombre Murciélago es más vulnerable que nunca! Mientras, el Fantasma localiza a su objetivo: ¡el Joker!','\r',char(13)),'\n',char(10)),NULL,NULL,424,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003164089-aib1gy.jpg','read',0,NULL,NULL,'2026-04-12 14:12:45','2026-04-12 16:13:29',207,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Liam Sharp","role":"Dibujo, Tinta, Color"},{"name":"Clay Mann","role":"Dibujo, Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1813,'Batman/Catwoman #9','Batman/Catwoman',9,NULL,'978-8-419-21048-7',NULL,'Tom King','Liam Sharp',NULL,NULL,'ECC Ediciones',NULL,'2022-05-03',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman/Catwoman núm. 9 USA\r\nBatman y Catwoman vuelven a estar juntos, ¡pero el Joker está a punto de complicar las cosas! Y no es el único truco que tiene bajo la manga. El Príncipe Payaso del Crimen también guarda un secreto que afecta al Fantasma. Mientras, Batwoman persigue a su propia madre.','\r',char(13)),'\n',char(10)),NULL,NULL,424,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003166903-x8ylw1.jpg','read',0,NULL,NULL,'2026-04-12 14:12:47','2026-04-12 16:13:29',207,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Liam Sharp","role":"Dibujo, Tinta, Color"},{"name":"Clay Mann","role":"Dibujo, Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1814,'Batman/Catwoman #10','Batman/Catwoman',10,NULL,'978-8-419-27977-4',NULL,'Tom King','Clay Mann',NULL,NULL,'ECC Ediciones',NULL,'2022-06-29',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman/Catwoman núm. 10 USA\r\nPuede que Batman y Catwoman vuelvan a estar juntos, pero el Joker está listo para complicar las cosas a la pareja, al pedir a Selina un favor que podría conducir a la muerte del Cruzado de la Capa. Y no es el único truco que guarda bajo la manga... Además, Batwoman persigue a su propia madre.','\r',char(13)),'\n',char(10)),NULL,NULL,424,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003168908-qcj997.jpg','read',0,NULL,NULL,'2026-04-12 14:12:49','2026-04-12 16:13:29',207,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Clay Mann","role":"Dibujo, Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1815,'Batman/Catwoman #11','Batman/Catwoman',11,NULL,'978-8-419-32557-0',NULL,'Tom King','Clay Mann',NULL,NULL,'ECC Ediciones',NULL,'2022-07-05',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman/Catwoman núm. 11 USA\r\nSelina está en una encrucijada: seguir por el camino criminal o arriesgarse a ser un héroe como Batman. Solo tiene que tomar una decisión: prometer que no matará al Joker. Pero, ¿qué le lleva a romper esa sagrada promesa tantos años después?','\r',char(13)),'\n',char(10)),NULL,NULL,424,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003170740-oqlyt8.jpg','read',0,NULL,NULL,'2026-04-12 14:12:51','2026-04-12 16:13:29',207,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Clay Mann","role":"Dibujo, Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1816,'Batman/Catwoman #12','Batman/Catwoman',12,NULL,'978-8-419-48461-1',NULL,'Tom King','Clay Mann',NULL,NULL,'ECC Ediciones',NULL,'2022-10-04',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman/Catwoman núm. 12 USA\r\n¡Campanas de boda! La historia termina aquí, con Batman y Catwoman preparados para dar el paso definitivo. ¡No querréis perderos el capítulo final del Batman de Tom King! La Batboda se celebra aquí y, conociendo a Bruce y Selina, la ceremonia va a ser de todo menos convencional.\r\nÚltimo tomo.','\r',char(13)),'\n',char(10)),NULL,NULL,424,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003173308-suvd1x.jpg','read',0,NULL,NULL,'2026-04-12 14:12:54','2026-04-12 16:13:29',207,NULL,'grapa','[{"name":"Tom King","role":"Guion"},{"name":"Clay Mann","role":"Dibujo, Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1817,'Batman: Reptil #1','Batman: Reptil',1,NULL,'978-8-418-93191-8',NULL,'Garth Ennis','Liam Sharp',NULL,NULL,'ECC Ediciones',NULL,'2021-11-23',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman: Reptilian núm. 1 USA\r\nAlgo está infundiendo miedo en aquellos que han aterrorizado a la ciudad de Gotham durante años. Algo está cazando a los villanos. Todas las miradas apuntaban a Batman, pero la verdad es mucho más aterradora que un simple hombre que acecha entre las sombras. Ha surgido un monstruo que persigue a otros monstruos. Una historia oscura y escalofriante realizada por las leyendas del cómic Garth Ennis y Liam Sharp.','\r',char(13)),'\n',char(10)),NULL,NULL,160,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003854451-y84t6n.jpg','read',0,NULL,NULL,'2026-04-12 14:24:18','2026-04-12 16:13:29',208,23.95,'grapa','[{"name":"Garth Ennis","role":"Guion"},{"name":"Liam Sharp","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1818,'Batman: Reptil #2','Batman: Reptil',2,NULL,'978-8-418-97470-0',NULL,'Garth Ennis','Liam Sharp',NULL,NULL,'ECC Ediciones',NULL,'2021-12-21',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman: Reptilian núm. 2 USA\r\nBatman ha salido en busca de la criatura que aterroriza el inframundo de Gotham City. La primera parada es la guarida del Pingüino, pero Oswald Cobblepot no está en condiciones de ofrecer demasiadas respuestas. La visita dejará al Caballero Oscuro cada ve más cerca de la oscuridad...','\r',char(13)),'\n',char(10)),NULL,NULL,160,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003862248-hduu59.jpg','read',0,NULL,NULL,'2026-04-12 14:24:23','2026-04-12 16:13:29',208,NULL,'grapa','[{"name":"Garth Ennis","role":"Guion"},{"name":"Liam Sharp","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1819,'Batman: Reptil #3','Batman: Reptil',3,NULL,'978-8-419-02142-7',NULL,'Garth Ennis','Liam Sharp',NULL,NULL,'ECC Ediciones',NULL,'2022-01-25',NULL,NULL,replace('EDICIÓN ORIGINAL: Batman: The Reptilian núm. 3 USA\rEl Acertijo, el Pingüino, Deadshot, Hugo Strange, Dos Caras, Tweedledee y Tweedledum. Todos han caído en sus garras. Una matanza a través del inframundo de Gotham City. ¿Quién es el culpable? Las pistas conducen al Caballero Oscuro hasta el Joker.','\r',char(13)),NULL,NULL,160,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003865133-5sh97d.jpg','read',0,NULL,NULL,'2026-04-12 14:24:25','2026-04-12 16:13:29',208,NULL,'grapa','[{"name":"Garth Ennis","role":"Guion"},{"name":"Liam Sharp","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1820,'Batman: Reptil #4','Batman: Reptil',4,NULL,'978-8-412-47096-3',NULL,'Garth Ennis','Liam Sharp',NULL,NULL,'ECC Ediciones',NULL,'2022-02-22',NULL,NULL,replace('EDICIÓN ORIGINAL: Batman: Reptilian núm. 4 USA\r¡El monstruo revelado! Batman patrulla las calles en busca de respuestas, ¡pero solo encuentra más preguntas! El Caballero Oscuro lleva la búsqueda bajo tierra, a las alcantarillas, esperando detener a Killer Croc. Sin embargo, pronto se dará cuenta de que no todo es lo que parece...','\r',char(13)),NULL,NULL,160,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776003866860-1ap4xk.jpg','read',0,NULL,NULL,'2026-04-12 14:24:27','2026-04-12 16:13:29',208,NULL,'grapa','[{"name":"Garth Ennis","role":"Guion"},{"name":"Liam Sharp","role":"Dibujo, Tinta, Color"}]');
