INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1881,'Antes de Watchmen: Dr. Manhattan #3','Antes de Watchmen: Dr. Manhattan',3,NULL,'978-8-415-84419-8',NULL,'Joe Michael Straczynski','Adam Hughes',NULL,NULL,'ECC Ediciones',NULL,'2013-04-04',NULL,NULL,replace(replace('Cover Art by Adam Hugues\r\nContiene EDICIÓN ORIGINAL: Before Watchmen: Dr. Manhattan Vol.1 #3 (/2012) USA. DC Comics\r\nDe la mano de los mejores artistas de la industria del cómic, llega a nosotros Antes de Watchmen, una genial colección de series limitadas y números especiales que indagan en el mundo de Watchmen y sus personajes, con un respeto absoluto hacia la obra original. Un universo profundo y realista donde no existen los verdaderos superpoderes... excepto en un hombre, si es que aún se le puede llamar así, poderoso como un dios: el Dr. Manhattan. Una espectacular serie obra de dos maestros: J. Michael Straczynski y Adam Hughes. \r\nIncluye reproducción de las portadas alternativas originales USA Textless Before Watchmen: Dr. Manhattan Vol.1 #3 obra de:\r- Adam Hugues\r- Neal Adams\r\nIncluye Póster Central Dr. Manhattan obra de Adam Hugues','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776004150018-a4hedx.jpg','read',0,NULL,NULL,'2026-04-12 14:29:11','2026-04-12 16:13:17',215,NULL,'Grapa','[{"name":"Joe Michael Straczynski","role":"Guion"},{"name":"Adam Hughes","role":"Dibujo, Tinta, Color"},{"name":"Laura Martin","role":"Color"},{"name":"John Higgins","role":"Guion, Dibujo, Tinta, Color"}]');
