INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1883,'Antes de Watchmen: Rorschach #1','Antes de Watchmen: Rorschach',1,NULL,'978-8-415-74871-7',NULL,'Brian Azzarello','Lee Bermejo',NULL,NULL,'ECC Ediciones',NULL,'2013-02-01',NULL,NULL,replace(replace('Cover Art by Lee Bermejo\r\nContiene Before Watchmen: Rorschach Vol.1 #1 (/2012) USA. DC Comics \r\n&quot;Azzarello y Bermejo en “Antes de Watchmen: Rorschach” se cuidan muy mucho de incorporar elementos originales que desdigan la opera prima de Moore y Gibbons que provocasen el rechazo furibundo de los fans y apuestan por realizar un homenaje digno a la obra maestra en la que se inspiran sin caer en el error de intentar ponerse a su altura, con un acercamiento asumidamente menor y tributario que se alimenta de la brillantez y actualidad “Watchmen”, obteniendo de esta forma como resultado una obra sencilla pero que, en mi opinión, supera las expectativas generadas inicialmente.\r\nIncluye  reproducción cubiertas alternativas Textless USA. Before Watchmen: Rorschach Vol.1 #1 (/2012) Obra de:\r\n- Lee Bermejo\r\n- Jim Steranko\r\n- Jim Lee & Scott Williams & Alex Sinclair\r\nIncluye la Historia: la Maldición del Corserio Carmesí.','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776004185016-8q0mwm.jpg','read',0,NULL,NULL,'2026-04-12 14:29:48','2026-04-12 16:13:17',216,13.99,'Grapa','[{"name":"Brian Azzarello","role":"Guion"},{"name":"Lee Bermejo","role":"Dibujo, Tinta"},{"name":"Bárbara Ciardo","role":"Color"},{"name":"John Higgins","role":"Guion, Dibujo, Tinta"}]');
