INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1889,'Antes de Watchmen: Dollar Bill','Antes de Watchmen: Dollar Bill',NULL,NULL,'978-8-415-84449-5',NULL,'Len Wein','Steve Rude',NULL,NULL,'ECC Ediciones',NULL,'2013-05-01',NULL,NULL,'De la mano de los mejores artistas de la industria del cómic, llega a nosotros Antes de Watchmen, una genial colección de series limitadas y números especiales que indagan en el mundo de Watchmen y sus personajes, con un respeto absoluto hacia la obra original. En Dollar Bill, Len Wein y Steve Rude, dos leyendas vivientes del cómic, nos ofrecen un especial donde asistiremos a una agridulce historia plagada de capitalismo y american way of life, y donde, como no podía ser de otro modo, no es oro todo lo que reluce...',NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776004238454-70ogr5.jpg','read',0,NULL,NULL,'2026-04-12 14:30:41','2026-04-12 16:13:17',NULL,1.25,'Grapa','[{"name":"Len Wein","role":""},{"name":"Steve Rude","role":""}]');
