INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1964,'Liga de la Justicia (2012-2022) #53','Liga de la Justicia (2012-2022)',53,NULL,'978-8-416-84028-1',NULL,'Geoff Johns','Jason Fabok',NULL,NULL,'ECC Ediciones',NULL,'2016-08-30',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núm. 50 USA\r\n¡Último capítulo de La Guerra de Darkseid!\r\nConcluye la saga más ambiciosa del popular supergrupo, ¡con el destino de la Liga de la Justicia y el propio universo en juego! Una entrega doble en la que los acontecimientos se precipitan, cambiando para siempre las vidas de Batman, Superman y Wonder Woman. ¡El escenario está preparado para la nueva gran etapa del Universo DC!','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005291331-yw55pd.jpg','read',0,NULL,NULL,'2026-04-12 14:48:12','2026-04-12 16:13:01',222,NULL,'Grapa','[{"name":"Geoff Johns","role":""},{"name":"Jason Fabok","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1965,'Liga de la Justicia (2012-2022) #54','Liga de la Justicia (2012-2022)',54,NULL,'978-8-416-84087-8',NULL,'Dan Abnett','Paul Pelletier',NULL,NULL,'ECC Ediciones',NULL,'2016-09-28',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núm. 51 USA \r\nARGUMENTO: Dan Abnett (Batman/Superman) recoge el testigo de Geoff Johns en la primera entrega de la serie tras los devastadores acontecimientos de La Guerra de Darkseid. El mayor grupo de superhéroes del Universo DC se recompone.','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005293616-ady5r1.jpg','read',0,NULL,NULL,'2026-04-12 14:48:14','2026-04-12 16:13:01',222,NULL,'Grapa','[{"name":"Dan Abnett","role":"Guion"},{"name":"Paul Pelletier","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1966,'Liga de la Justicia (2012-2022) #55','Liga de la Justicia (2012-2022)',55,NULL,'978-8-416-90135-7',NULL,'Dan Jurgens','Tom Grummett',NULL,NULL,'ECC Ediciones',NULL,'2016-10-26',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núm. 52 USA \r\nARGUMENTO: Los sucesos de La Guerra de Darkseid, Los últimos días de Superman y Superman: Lois y Clark - La llegada se dan de la mano en este ejemplar, que pone el foco de atención en Lex Luthor, y nos muestra una panorámica perfecta del momento actual del último hijo de Krypton y su relación con el mayor grupo de superhéroes del mundo.','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005295617-ocb37j.jpg','read',0,NULL,NULL,'2026-04-12 14:48:16','2026-04-12 16:13:01',222,NULL,'Grapa','[{"name":"Dan Jurgens","role":"Guion"},{"name":"Tom Grummett","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1967,'Liga de la Justicia (2012-2022) #56 / 1','Liga de la Justicia (2012-2022) #56 / 1',56,NULL,'978-8-416-90190-6',NULL,'Bryan Hitch','Bryan Hitch',NULL,NULL,'ECC Ediciones',NULL,'2016-11-29',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League: Rebirth núm. 1 USA \r\nARGUMENTO: ¡Amanece un nuevo día para los mayores héroes de la Tierra! Tras los sucesos de Universo DC: Renacimiento... ¡damos la bienvenida a tres nuevos miembros! Un momento...¿Uno de ellos no es Superman? ¿Quién es este extraño visitante de un universo desaparecido? ¿Podrá ganarse la confianza de la Liga de la Justicia? Batman y Wonder Woman no parecen muy convencidos...\r\nAdemás de poder seguir sus aventuras en solitario a través de sus propias series regulares, los principales superhéroes se reúnen cada mes en esta cabecera que el guionista Geoff Johns inaguró hace cinco años. Durante ese tiempo, el aclamado responsable de imprescindibles etapas de Green Lantern, Flash o Aquaman relató las historias más trepidantes y espectaculares del Universo DC, acompañado de otros grandes profesionales de la industria.\r\nLa Guerra de Darkseid y el especial Universo DC: Renacimiento han puesto patas arriba el mundo de la Liga de la Justicia. Tras demostrar su talento como autor completo en las páginas de JLA: Liga de la Justicia de América, Bryan Hitch se hace cargo del título principal del equipo, en una nueva etapa que se inicia con un ejemplar de 24 páginas...¡por tan solo 1 €!','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005297802-0aeg2t.jpg','read',0,NULL,NULL,'2026-04-12 14:48:18','2026-04-12 16:13:01',222,NULL,'Grapa','[{"name":"Bryan Hitch","role":"Guion, Dibujo"},{"name":"Alex Sinclair","role":"Color"},{"name":"Daniel Henriques","role":"Tinta"},{"name":"Scott Hanna","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1968,'Liga de la Justicia (2012-2022) #57 / 2','Liga de la Justicia (2012-2022) #57 / 2',57,NULL,'978-8-416-94540-5',NULL,'Bryan Hitch','Tony S. Daniel',NULL,NULL,'ECC Ediciones',NULL,'2016-12-19',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núm. 1 USA\r\nARGUMENTO: El océano se alza. La tierra se mueve. Un poder antiguo regresa del olvido para reclamar no sólo el mundo, sino el universo entero, y ni siquiera el poder combinado de la Liga de la Justicia parece suficiente para detenerlo. ¡Bienvenidos a una nueva era del mayor grupo de héroes! ¡Con guión de Bryan Hitch (JLA: Liga de la Justicia de América) y arte de Tony S. Daniel (Deathstroke)!','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005300120-nq9tn5.jpg','read',0,NULL,NULL,'2026-04-12 14:48:21','2026-04-12 16:13:01',222,NULL,'Grapa','[{"name":"Bryan Hitch","role":"Guion"},{"name":"Tony S. Daniel","role":"Dibujo"},{"name":"Sandu Florea","role":"Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1969,'Liga de la Justicia (2012-2022) #58 / 3','Liga de la Justicia (2012-2022) #58 / 3',58,NULL,'978-8-416-94587-0',NULL,'Bryan Hitch','Tony S. Daniel',NULL,NULL,'ECC Ediciones',NULL,'2017-01-31',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núm. 2-3 USA\r\nARGUMENTO: Catastróficos terremotos asolan las principales ciudades, mientras una ancestral entidad toma el control de la población de la Tierra, obligando a todo el planeta a ponerse en contra de los metahumanos y de la mismísima Liga de la Justicia. Incapaz de luchar en dos frentes, Batman recurre a la ayuda de un aliado inesperado, en el que nunca ha podido confiar...','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005302978-hpg7qw.jpg','read',0,NULL,NULL,'2026-04-12 14:48:23','2026-04-12 16:13:01',222,NULL,'Grapa','[{"name":"Bryan Hitch","role":"Guion"},{"name":"Tony S. Daniel","role":"Dibujo"},{"name":"Sandu Florea","role":"Tinta"},{"name":"Tomeu Morey","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1970,'Liga de la Justicia (2012-2022) #59 / 4','Liga de la Justicia (2012-2022) #59 / 4',59,NULL,'978-8-416-99836-4',NULL,'Bryan Hitch','Jesús Merino',NULL,NULL,'ECC Ediciones',NULL,'2017-02-27',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núm. 4-5 USA\r\nARGUMENTO: ¡El desenlace de Las máquinas de la extinción! Superman se enfrenta en el núcleo de la Tierra a tres artefactos que pueden provocar la destrucción del planeta, mientras los nuevos Green Lanterns descubren la verdad sobre El Parentesco y sus planes, conectados directamente con la creación de la humanidad. ¿Estamos ante la batalla final entre la Liga de la Justicia y este peligroso enemigo... o realmente es el origen de algo mucho peor?','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005304741-3i77to.jpg','read',0,NULL,NULL,'2026-04-12 14:48:25','2026-04-12 16:13:01',222,NULL,'Grapa','[{"name":"Bryan Hitch","role":"Guion"},{"name":"Jesús Merino","role":"Dibujo, Tinta"},{"name":"Tony S. Daniel","role":"Dibujo"},{"name":"Andy Owens","role":"Tinta"},{"name":"Tomeu Morey","role":"Color"},{"name":"Sandu Florea","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1971,'Liga de la Justicia (2012-2022) #60 / 5','Liga de la Justicia (2012-2022) #60 / 5',60,NULL,'978-8-417-06361-0',NULL,'Bryan Hitch','Jesús Merino',NULL,NULL,'ECC Ediciones',NULL,'2017-03-28',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núm. 6-7 USA \r\nARGUMENTO: Después de una terrible batalla, Jessica Cruz, flamante Green Lantern, decide relajarse asumiendo otro desafío increíble: superar su ansiedad e invitar a salir a uno de los héroes más conocidos del Universo DC. Lo que Jessica no sabe es que un nuevo villano está manipulando los temores de los componentes de la Liga de la Justicia, provocando un enfrentamiento entre héroes...','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005306550-z2gh8z.jpg','read',0,NULL,NULL,'2026-04-12 14:48:27','2026-04-12 16:13:01',222,NULL,'Grapa','[{"name":"Bryan Hitch","role":"Guion"},{"name":"Jesús Merino","role":"Dibujo"},{"name":"Matthew Clark","role":"Dibujo"},{"name":"Tom Derenick","role":"Dibujo"},{"name":"Sean Parsons","role":"Tinta"},{"name":"Trevor Scott","role":"Tinta"},{"name":"Adriano Lucas","role":"Color"},{"name":"Andy Owens","role":"Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1972,'Liga de la Justicia (2012-2022) #61 / 6','Liga de la Justicia (2012-2022) #61 / 6',61,NULL,'978-8-417-07127-1',NULL,'Bryan Hitch','Neil Edwards',NULL,NULL,'ECC Ediciones',NULL,'2017-05-02',NULL,NULL,replace('Recopila Justice League #8-9 USA (noviembre/2016, &quot;Outbreak&quot;, partes 1 y 2 de 4)\r&quot;Un enemigo invisible, ansioso de venganza contra los héroes más grandes de la Tierra, ha pirateado los ordenadores de la Liga de la Justicia, haciendo que las armas de la Batcueva y los sistemas de seguridad se vuelvan contra Batman y provocando la caída en picado de la Atalaya...¡con Cíborg atrapado en su interior! La Liga de la Justicia está bajo asedio. Y esta vez ni siquiera el poder combinado de los Green Lanterns parece suficiente para salvar el día...&quot;','\r',char(13)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005309347-hexmon.jpg','read',0,NULL,NULL,'2026-04-12 14:48:29','2026-04-12 16:13:01',222,NULL,'Grapa','[{"name":"Bryan Hitch","role":"Guion"},{"name":"Neil Edwards","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1973,'Liga de la Justicia (2012-2022) #62 / 7','Liga de la Justicia (2012-2022) #62 / 7',62,NULL,'978-8-417-07194-3',NULL,'Bryan Hitch','Neil Edwards',NULL,NULL,'ECC Ediciones',NULL,'2017-05-23',NULL,NULL,replace(replace('Recopila Justice League #10-11 USA (diciembre/2016, &quot;Outbreak&quot;, partes 3 y 4 de 4)\r\n&quot;La identidad del misterioso nuevo villano que ha pirateado a la Liga de la Justicia queda al descubierto cuando el grupo descubre una impactante conexión con los sucesos de Las máquinas de la extinción, el primer arco argumental de esta nueva etapa. La Liga se enfrenta a la aniquilación completa cuando multitud de mortales villanos son liberados de cárceles de todo el mundo, como parte de un intrincado plan de venganza contra los héroes...&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005311109-yxfpqt.jpg','read',0,NULL,NULL,'2026-04-12 14:48:31','2026-04-12 16:13:01',222,NULL,'Grapa','[{"name":"Bryan Hitch","role":"Guion"},{"name":"Neil Edwards","role":"Dibujo"},{"name":"Daniel Henriques","role":"Tinta"},{"name":"Adriano Lucas","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1974,'Liga de la Justicia (2012-2022) #63/8','Liga de la Justicia (2012-2022) #63/8',63,NULL,'978-8-417-10699-7',NULL,'Tim Seeley','Christian Duce',NULL,NULL,'ECC Ediciones',NULL,'2017-06-26',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núm. 12-13 USA    ¡Cruce con Liga de la Justicia contra Escuadrón Suicida!\r\nARGUMENTO: ¡No te lo puedes perder! ¡He aquí el Renacimiento de uno de los mayores villanos del Universo DC! ¡El personaje conocido como [SPOILER]! Bienvenidos a un día que nadie supo predecir: ¡el día en el que Harley Quinn se encuentra a sí misma como la protectora de Gotham, haciendo frente al brutal poder de [SPOILER]!','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005313181-kk60w7.jpg','read',0,NULL,NULL,'2026-04-12 14:48:33','2026-04-12 16:13:01',222,NULL,'Grapa','[{"name":"Tim Seeley","role":"Guion"},{"name":"Christian Duce","role":"Dibujo"},{"name":"Scot Eaton","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1975,'Liga de la Justicia (2012-2022) #64/9','Liga de la Justicia (2012-2022) #64/9',64,NULL,'978-8-417-14775-4',NULL,'Bryan Hitch','Bryan Hitch',NULL,NULL,'ECC Ediciones',NULL,'2017-07-18',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núms. 14-15 USA   \r\nARGUMENTO: ¡Bryan Hitch regresa para narrar el reagrupamiento de la Liga de la Justicia! Las tensiones entre los miembros del grupo, esquivadas durante meses, salen a la luz justo antes de una decisiva misión. Tras ello, arranca un nuevo arco argumental: ¡la Liga de la Justicia se ve obligada a participar en una cósmica carrera contra el tiempo, que les llevará a diferentes puntos de la historia de la Tierra!','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005315198-rxallw.jpg','read',0,NULL,NULL,'2026-04-12 14:48:36','2026-04-12 16:13:01',222,NULL,'Grapa','[{"name":"Bryan Hitch","role":"Guion, Dibujo"},{"name":"Fernando Pasarín","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1976,'Liga de la Justicia (2012-2022) #65/10','Liga de la Justicia (2012-2022) #65/10',65,NULL,'978-8-417-17641-9',NULL,'Bryan Hitch','Fernando Pasarín',NULL,NULL,'ECC Ediciones',NULL,'2017-08-22',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núms. 16-17 USA   \r\nARGUMENTO: ¡Bryan Hitch forma equipo con Fernando Pasarín (Liga de la Justicia contra Escuadrón Suicida) para narrar la más trepidante aventura espacio-temporal de la Liga de la Justicia! Cada miembro del equipo, perdido en algún lugar de la historia, lucha por regresar al presente y detener un plan que puede conllevar su eliminación absoluta. Una épica confrontación en la que Superman tiene que tomar una elección imposible.','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005319997-5labtc.jpg','read',0,NULL,NULL,'2026-04-12 14:48:40','2026-04-12 16:13:01',222,NULL,'Grapa','[{"name":"Bryan Hitch","role":"Guion"},{"name":"Fernando Pasarín","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1977,'Liga de la Justicia (2012-2022) #66/11','Liga de la Justicia (2012-2022) #66/11',66,NULL,'978-8-417-20613-0',NULL,'Bryan Hitch','Fernando Pasarín',NULL,NULL,'ECC Ediciones',NULL,'2017-09-14',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League nº 18-19 USA   \r\nARGUMENTO: Separados por siglos de distancia, los componentes de la Liga de la Justicia continúan su lucha contra los seres que están reescribiendo la historia. ¡Todos salvo Batman, que toma la decisión de llevar a cabo una misión en solitario para salvar la vida de Superman! ¡La verdad queda al descubierto en el increíble final de Intemporales!','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005322022-le2pom.jpg','read',0,NULL,NULL,'2026-04-12 14:48:43','2026-04-12 16:13:01',222,NULL,'Grapa','[{"name":"Bryan Hitch","role":"Guion"},{"name":"Fernando Pasarín","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1978,'Liga de la Justicia (2012-2022) #67/12','Liga de la Justicia (2012-2022) #67/12',67,NULL,'978-8-417-20673-4',NULL,'Bryan Hitch','Bryan Hitch',NULL,NULL,'ECC Ediciones',NULL,'2017-10-09',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núms. 20 a 21 USA                                                                              \r\nARGUMENTO: ¡Incluye un arco argumental completo! ¡Celebra con nosotros el estreno de Liga de la Justicia! La Liga está atrapada en un bucle temporal, enfrentados a un individuo que porta una misteriosa arma alienígena. ¿El resultado? ¡Un héroe ha caído y muchos civiles se han convertido en víctimas colaterales! El grupo debe dar la vuelta a la situación y detener a su atacante antes de que el rencor de un único hombre acabe con los héroes más poderosos del Universo DC.','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005324713-p0czqc.jpg','read',0,NULL,NULL,'2026-04-12 14:48:45','2026-04-12 16:13:01',222,NULL,'Grapa','[{"name":"Bryan Hitch","role":"Guion, Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1979,'Liga de la Justicia (2012-2022) #68/13','Liga de la Justicia (2012-2022) #68/13',68,NULL,'978-8-417-24351-7',NULL,'Shea Fontana','Philippe Briones',NULL,NULL,'ECC Ediciones',NULL,'2017-11-06',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núms. 22 a 23 USA                                                                              \r\nARGUMENTO: ¡Un número dedicado por entero a Jessica Cruz! Apoyada en su compañero Simon Baz, la novata Green Lantern ha albergado numerosas dudas sobre su pertenencia a la Liga de la Justicia. ¡Ahora llega el momento de superar los miedos y demostrar que es digna de pertenecer al equipo más poderoso del Universo DC!  Los guionistas Shea Fontana (DC Super Hero Girls) y Tom DeFalco (Nightwing) llevan a los Green Lanterns a un nuevo nivel.','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005326928-tsmouo.jpg','read',0,NULL,NULL,'2026-04-12 14:48:48','2026-04-12 16:13:01',222,NULL,'Grapa','[{"name":"Shea Fontana","role":"Guion"},{"name":"Tom DeFalco","role":"Guion"},{"name":"Philippe Briones","role":"Dibujo"},{"name":"Tom Derenick","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1980,'Liga de la Justicia (2012-2022) #69/14','Liga de la Justicia (2012-2022) #69/14',69,NULL,'978-8-417-27642-3',NULL,'Bryan Hitch','Ian Churchill',NULL,NULL,'ECC Ediciones',NULL,'2017-12-04',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núms. 24-25 USA                                                                               \r\nARGUMENTO: La misión de nuestros héroes en el reino de los muertos se complica todavía más cuando la Liga se ve atrapada entre los fantasmas de los héroes caídos, los villanos muertos y los civiles inocentes, atormentados y torturados, cuyas vidas no pudieron salvar. Con los héroes más poderosos fuera de la realidad, el cerebro detrás del ataque hace su jugada en el mundo de los vivos.','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005329679-z7nj7a.jpg','read',0,NULL,NULL,'2026-04-12 14:48:50','2026-04-12 16:13:01',222,NULL,'grapa','[{"name":"Bryan Hitch","role":"Guion"},{"name":"Dan Abnett","role":"Guion"},{"name":"Ian Churchill","role":"Dibujo"},{"name":"Tom Derenick","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1981,'Liga de la Justicia (2012-2022) #70/15','Liga de la Justicia (2012-2022) #70/15',70,NULL,'978-8-417-31602-0',NULL,'Bryan Hitch','Fernando Pasarín',NULL,NULL,'ECC Ediciones',NULL,'2018-01-08',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núms. 26-27 USA\r\nARGUMENTO: Fernando Pasarín (Green Lantern) vuelve a formar equipo creativo con Bryan Hitch para dar forma a un nuevo arco argumental: ¡Legado! Un grupo de héroes procedentes de un futuro postapocalíptico huyen al pasado para evitar que su mundo se haga realidad. En su misión, necesitarán la ayuda de la Liga de la Justicia... o lo que es lo mismo: ¡la ayuda de sus propios padres! ¡Descubre a la siguiente generación de héroes de DC Comics!','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005331891-xg5mlw.jpg','read',0,NULL,NULL,'2026-04-12 14:48:52','2026-04-12 16:13:01',222,NULL,'grapa','[{"name":"Bryan Hitch","role":"Guion"},{"name":"Fernando Pasarín","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1982,'Liga de la Justicia (2012-2022) #71/16','Liga de la Justicia (2012-2022) #71/16',71,NULL,'978-8-417-35406-0',NULL,'Bryan Hitch','Fernando Pasarín',NULL,NULL,'ECC Ediciones',NULL,'2018-01-29',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núms. 28-29 USA \r\nARGUMENTO: Legado, partes tres y cuatro. Un poderoso enemigo ha seguido a la siguiente generación de la Liga de la Justicia hasta el presente, con el único propósito de destruirlos. ¡Su nombre es Aquaman, y no se detendrá hasta que todos los héroes estén muertos! Nada es lo que parece.','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005333790-odsocw.jpg','read',0,NULL,NULL,'2026-04-12 14:48:54','2026-04-12 16:13:01',222,NULL,'Grapa','[{"name":"Bryan Hitch","role":"Guion"},{"name":"Fernando Pasarín","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1983,'Liga de la Justicia (2012-2022) #72/17','Liga de la Justicia (2012-2022) #72/17',72,NULL,'978-8-417-35495-4',NULL,'Bryan Hitch','Fernando Pasarín',NULL,NULL,'ECC Ediciones',NULL,'2018-03-06',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núms. 30-31 USA\r\nARGUMENTO: ¡Concluye la etapa de Bryan Hitch! Con gran parte de la Liga de la Justicia desaparecida, Batman y Wonder Woman tendrán que dejar de lado sus diferencias con los jóvenes héroes del futuro si quieren salvar la realidad. La verdadera identidad de Soberana queda al descubierto, sorprendiendo a los iconos del Universo DC. Si no triunfan sobre la Gran Oscuridad, será el fin de todo... ¡y de todos!','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005336162-jdcfy7.jpg','read',0,NULL,NULL,'2026-04-12 14:48:57','2026-04-12 16:13:01',222,NULL,'Grapa','[{"name":"Bryan Hitch","role":"Guion"},{"name":"Fernando Pasarín","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1984,'Liga de la Justicia (2012-2022) #73/18','Liga de la Justicia (2012-2022) #73/18',73,NULL,'978-8-417-40162-7',NULL,'Robert Venditti','Ethan Van Sciver',NULL,NULL,'ECC Ediciones',NULL,'2018-04-04',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núm. 32 USA, Hal Jordan and the Green Lantern Corps núm. 32 USA\r\n¡Los sucesos de Noches oscuras: Metal llegan a la serie del mayor grupo del Universo DC! Tras Flash núm. 31/ 17, Murciélagos en el infierno sigue aquí. ¿Cómo reaccionarán nuestros héroes favoritos ante los horrores del Multiverso Oscuro? ¡Las peores pesadillas de la Liga de la Justicia se hacen realidad! El cruce termina en Green Lantern núm. 73/ 18.','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005338434-l4zrx1.jpg','read',0,NULL,NULL,'2026-04-12 14:48:59','2026-04-12 16:13:01',222,NULL,'Grapa','[{"name":"Robert Venditti","role":"Guion"},{"name":"Ethan Van Sciver","role":"Dibujo"},{"name":"Liam Sharp","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1985,'Liga de la Justicia (2012-2022) #74/19','Liga de la Justicia (2012-2022) #74/19',74,NULL,'978-8-417-44140-1',NULL,'Christopher Priest','Pete Woods',NULL,NULL,'ECC Ediciones',NULL,'2018-05-03',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núms. 34-35 USA \r\n¡Nueva etapa! ¡Únete a la Liga! Cuando la Liga de la Justicia se enfrenta a tres amenazas simultáneas, un agotado Batman comete un error crucial que provoca una tragedia imperdonable. Christopher Priest, el guionista nominado al premio Eisner por su trabajo en Deathstroke, forma equipo con el artista Pete Woods (Action Comics) para narrar la historia más sorprendente del mayor grupo del Universo DC: ¡El juicio de la Liga de la Justicia!','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005340423-xklft8.jpg','read',0,NULL,NULL,'2026-04-12 14:49:01','2026-04-12 16:13:01',222,NULL,'grapa','[{"name":"Christopher Priest","role":"Guion"},{"name":"Pete Woods","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1986,'Liga de la Justicia (2012-2022) #75/20','Liga de la Justicia (2012-2022) #75/20',75,NULL,'978-8-417-48002-8',NULL,'Christopher Priest','Pete Woods',NULL,NULL,'ECC Ediciones',NULL,'2018-06-05',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núms. 36-37 USA                                                                              \r\nARGUMENTO: Sigue El juicio de la Liga de la Justicia. El fracaso de la Liga se ha vuelto viral, provocando una investigación por parte del Congreso de los Estados Unidos. El mayor grupo de héroes está en el centro de todas las miradas, con la confianza por los suelos, y con un Batman más cuestionado que nunca por sus expeditivos métodos. La tensión en el equipo es cada vez mayor, y la cosa está a punto de ponerse todavía peor para los novatos como Simon Baz...','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005342382-vjfjif.jpg','read',0,NULL,NULL,'2026-04-12 14:49:03','2026-04-12 16:13:01',222,NULL,'Grapa','[{"name":"Christopher Priest","role":"Guion"},{"name":"Pete Woods","role":"Dibujo"},{"name":"Philippe Briones","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1987,'Liga de la Justicia (2012-2022) #76/21','Liga de la Justicia (2012-2022) #76/21',76,NULL,'978-8-417-50922-4',NULL,'Christopher Priest','Ian Churchill',NULL,NULL,'ECC Ediciones',NULL,'2018-07-03',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núms. 38-39 USA\r\nARGUMENTO: ¡La sorprendente conclusión de El juicio de la Liga de la Justicia! El liderazgo de la Liga está en juego, y los recientes acontecimientos han dividido al mayor grupo del Universo DC en dos equipos, con Batman todavía al frente de uno de los bandos. Mientras, Flash y los Green Lanterns tienen sus propios problemas, en el espacio exterior. ¡El camino hacia la siguiente gran etapa de la Liga comienza aquí!','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005345415-cep50s.jpg','read',0,NULL,NULL,'2026-04-12 14:49:05','2026-04-12 16:13:01',222,NULL,'Grapa','[{"name":"Christopher Priest","role":"Guion"},{"name":"Ian Churchill","role":"Dibujo"},{"name":"Marco Santucci","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1988,'Liga de la Justicia (2012-2022) #77/22','Liga de la Justicia (2012-2022) #77/22',77,NULL,'978-8-417-53182-9',NULL,'Christopher Priest','Pete Woods',NULL,NULL,'ECC Ediciones',NULL,'2018-08-04',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núms. 40-41 USA \r\n¡La Liga de la Justicia contra la Liga de la Justicia de América! El liderazgo del mayor grupo del Universo DC está en el aire, en una abarrotada sala de la Atalaya. ¿Qué significa la justicia en un mundo sin ley? Mientras los héroes se enfrentan entre ellos, un antiguo enemigo de Deathstroke siembra el caos en el corazón de África.','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005347401-ox9go7.jpg','read',0,NULL,NULL,'2026-04-12 14:49:08','2026-04-12 16:13:01',222,NULL,'Grapa','[{"name":"Christopher Priest","role":"Guion"},{"name":"Pete Woods","role":"Dibujo"},{"name":"Philippe Briones","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1989,'Liga de la Justicia (2012-2022) #78/23','Liga de la Justicia (2012-2022) #78/23',78,NULL,'978-8-417-54942-8',NULL,'Christopher Priest','Pete Woods',NULL,NULL,'ECC Ediciones',NULL,'2018-09-04',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núms. 42-43 USA\r\n¡Última entrega de la actual etapa! ¡El desenlace de Justicia Perdida! En la despedida de Christopher Priest como guionista de Liga de la Justicia, el mayor grupo de héroes del Universo DC se enfrenta a una decisión crucial que podría tener consecuencias nefastas para uno de sus miembros. El papel de la Liga está en duda, y las capacidades de sus miembros están al límite, justo cuando Deathstroke entra en escena. Cuando el polvo se asiente, ¿las viejas alianzas seguirán en pie?','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005349837-pox72a.jpg','unread',0,NULL,NULL,'2026-04-12 14:49:10','2026-04-12 14:49:10',222,NULL,'Grapa','[{"name":"Christopher Priest","role":"Guion"},{"name":"Pete Woods","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1990,'Liga de la Justicia (2012-2022) #79/1','Liga de la Justicia (2012-2022) #79/1',79,NULL,'978-8-417-64485-7',NULL,'Scott Snyder','Jim Cheung',NULL,NULL,'ECC Ediciones',NULL,'2018-11-13',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núms. 1 a 2 USA\r\n¡Una nueva era de grandeza para la Liga de la Justicia! ¡Ideal para nuevos lectores! \r\nLas leyendas del cómic Scott Snyder (Batman), Jorge Jiménez (Superhijos) y Jim Cheung (Jóvenes Vengadores) relanzan a la Liga de la Justicia en una saga centrada en un gran misterio que sacudirá al Universo DC. Los principales villanos están a punto de volver a primera plana... ¡de una forma que ningún héroe podría imaginar! Mientras, un antiguo conocido aparece de entre las sombras, y el Detective Marciano trata de proteger al grupo de un enemigo que parece destinado a destruir el mundo tal y como lo conocemos. \rTras los acontecimientos de Noches oscuras: Metal y de la serie limitada Liga de la Justicia: Sin Justicia, Scott Snyder (Batman), Jim Cheung (Jóvenes Vengadores) y Jorge Jiménez (Superhijos) toman las riendas del mayor grupo del Universo DC. Los últimos eventos han transformado el mundo de nuestros iconos favoritos de forma aterradora... y maravillosa. En este contexto, es el mismísimo Batman el que ha decidido dar un paso más. Ha llegado el momento de reinventar a la Liga, de adaptarla a los nuevos tiempos. ¡Solo la Liga de la Justicia puede aglutinar suficiente poder como para derrotar a las amenazas que están por llegar!','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005351403-odhlzc.jpg','unread',0,NULL,NULL,'2026-04-12 14:49:12','2026-04-12 14:49:12',222,NULL,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Jim Cheung","role":""},{"name":"Jorge Jiménez","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1991,'Liga de la Justicia (2012-2022) #80/2','Liga de la Justicia (2012-2022) #80/2',80,NULL,'978-8-417-66535-7',NULL,'Scott Snyder','Jorge Jiménez',NULL,NULL,'ECC Ediciones',NULL,'2018-12-11',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núms. 3 a 4 USA\r\nJohn Stewart... ¿Ultraviolet Lantern? ¿No te lo crees? ¡Pues Flash, Wonder Woman y Aquaman van a comprobar en este número el alcance de los nuevos (y violentos) poderes de su compañero! Mientras, el resto de la Liga investiga la caída de parte del Muro de la Fuente. ¡Los secretos del universo no son nada comparados con los secretos que los mayores iconos del Universo DC han ocultado desde hace años!','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005353297-3mun30.jpg','unread',0,NULL,NULL,'2026-04-12 14:49:14','2026-04-12 14:49:14',222,NULL,'Grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Jorge Jiménez","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1992,'Liga de la Justicia (2012-2022) #81/3','Liga de la Justicia (2012-2022) #81/3',81,NULL,'978-8-417-66598-2',NULL,'Scott Snyder','Jorge Jiménez',NULL,NULL,'ECC Ediciones',NULL,'2019-01-04',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núms. 5 a 6 USA \r\nLex Luthor regresa por todo lo alto a la primera plana del Universo DC. ¿Lo hará como amigo o como enemigo de la nueva Liga de la Justicia? Lo que tenemos claro es que la Legión de la Condena está volviendo a reunirse, y que nuestros héroes favoritos van a sufrir. Mucho.','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005355912-48dpg9.jpg','unread',0,NULL,NULL,'2026-04-12 14:49:16','2026-04-12 14:49:16',222,NULL,'grapa','[{"name":"Scott Snyder","role":""},{"name":"Jorge Jiménez","role":""},{"name":"James Tynion IV","role":""},{"name":"Doug Mahnke","role":""},{"name":"Alejandro Sánchez","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1993,'Liga de la Justicia (2012-2022) #82/4','Liga de la Justicia (2012-2022) #82/4',82,NULL,'978-8-417-72288-3',NULL,'James Tynion IV','Scott Snyder',NULL,NULL,'ECC Ediciones',NULL,'2019-02-05',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núms. 7 a 8 USA\r\n¡Con dibujo de Jim Cheung (Jóvenes Vengadores) y Mikel Janín (Batman: La Boda)! Es la Liga de la Justicia contra la Legión de la Condena. Además, la segunda parte de la historia de reclutamiento protagonizada por Lex Luthor. El magnate de Metropolis todavía guarda un as en la manga, relacionado con los sucesos de Noches oscuras: Metal...','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005357835-80or1h.jpg','unread',0,NULL,NULL,'2026-04-12 14:49:18','2026-04-12 14:49:18',222,NULL,'grapa','[{"name":"James Tynion IV","role":"Guion"},{"name":"Scott Snyder","role":"Guion"},{"name":"Jim Cheung","role":""},{"name":"Mikel Janin","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1994,'Liga de la Justicia (2012-2022) #83/5','Liga de la Justicia (2012-2022) #83/5',83,NULL,'978-8-417-78756-1',NULL,'Scott Snyder','Alejandro Sánchez',NULL,NULL,'ECC Ediciones',NULL,'2019-03-12',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núms. 9-10 USA \r\n¡El preludio del crossover Tierra Sumergida! Mientras los héroes tratan de arreglar los desastres ocurridos en los últimos números (¿volverá la Luna a su sitio?), Aquaman inicia la búsqueda de Poseidón, despertando la ira de una entidad que representa a los dioses antiguos del océano. ¿Quiénes son estas nuevas amenazas? Peces muy grandes. ¿Y sabéis lo que hacen los peces grandes? ¡Se comen a los pequeños, como Aquaman y sus compañeros de la Liga de la Justicia! La historia sigue este mes en Liga de la Justicia núm. 84/ 6.','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005360067-whuyuw.jpg','unread',0,NULL,NULL,'2026-04-12 14:49:20','2026-04-12 14:49:20',222,NULL,'grapa','[{"name":"Scott Snyder","role":"Guion"},{"name":"Alejandro Sánchez","role":"Dibujo"},{"name":"Francis Manapul","role":"Dibujo"},{"name":"Jorge Jiménez","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1995,'Liga de la Justicia (2012-2022) #84/6','Liga de la Justicia (2012-2022) #84/6',84,NULL,'978-8-417-82707-6',NULL,'Dan Abnett','Clayton Henry',NULL,NULL,'ECC Ediciones',NULL,'2019-03-26',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Aquaman núm. 41 USA, Titans núm. 28 USA \r\n¡El primer capítulo del crossover Tierra sumergida! La historia viene de Liga de la Justicia núm. 83/ 5. Aquaman ha desaparecido, ¡y el mundo va directo al desastre! La reina Mera está al frente de la defensa de la Tierra. Es el momento de enfrentarse a una marejada cósmica que ya ha desatado horrores inimaginables. Mientras, los Titanes reciben la visita de un viejo conocido... La historia sigue el mes que viene en Liga de la Justicia núm. 85/ 7.','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005361837-o3ayre.jpg','unread',0,NULL,NULL,'2026-04-12 14:49:22','2026-04-12 14:49:22',222,NULL,'Grapa','[{"name":"Dan Abnett","role":"Guion"},{"name":"Clayton Henry","role":"Dibujo"},{"name":"Lan Medina","role":"Dibujo"},{"name":"Vicente Cifuentes","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1996,'Liga de la Justicia (2012-2022) #85/7','Liga de la Justicia (2012-2022) #85/7',85,NULL,'978-8-417-82725-0',NULL,'James Tynion IV','Howard Porter',NULL,NULL,'ECC Ediciones',NULL,'2019-04-02',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League/Aquaman: Drowned Earth núm. 1 USA (one-shot)\r\nLa historia viene de Liga de la Justicia núm. 84/ 6. Segunda parte de Tierra sumergida. Un ejército alienígena inunda el mundo, con el objetivo fijado en Aquaman y Wonder Woman. Mientras, Batman, Superman y Flash tratan de impedir que las aguas turbulentas conviertan a toda la población en monstruos acuáticos, Mera busca el consejo de un viejo enemigo, y Arthur se enfrenta a Manta Negra. La historia sigue este mes en Liga de la Justicia núm. 86/ 8.','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005363719-4ggdkh.jpg','unread',0,NULL,NULL,'2026-04-12 14:49:24','2026-04-12 14:49:24',222,NULL,'Grapa','[{"name":"James Tynion IV","role":"Guion"},{"name":"Howard Porter","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1997,'Liga de la Justicia (2012-2022) #86/8','Liga de la Justicia (2012-2022) #86/8',86,NULL,'978-8-417-82777-9',NULL,'Dan Abnett','Francis Manapul',NULL,NULL,'ECC Ediciones',NULL,'2019-04-16',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núm. 11 USA, Aquaman núm. 42 USA\r\nLa historia viene de Liga de la Justicia núm. 85/ 7. Tercera parte de Tierra sumergida. La Liga de la Justicia se ha dispersado por los Siete Mares, perseguida por los Amos del Océano y su ejército. Su única esperanza radica en Aquaman. Arthur está a punto de llevar a cabo un plan que puede desatar un poder todavía más destructivo que el de los Amos. Mientras, Batman aguarda en el Salón de la Justicia... La historia termina este mes en Liga de la Justicia núm. 87/ 9.','\r',char(13)),'\n',char(10)),NULL,NULL,384,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005365857-bhg8j2.jpg','unread',0,NULL,NULL,'2026-04-12 14:49:27','2026-04-12 14:49:27',222,NULL,'Grapa','[{"name":"Dan Abnett","role":"Guion"},{"name":"Scott Snyder","role":"Guion"},{"name":"Francis Manapul","role":"Dibujo"},{"name":"Lan Medina","role":"Dibujo"},{"name":"Vicente Cifuentes","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1998,'Liga de la Justicia de América #1','Liga de la Justicia de América',1,NULL,'978-8-415-92517-0',NULL,'Geoff Johns','David Finch',NULL,NULL,'ECC Ediciones',NULL,'2013-07-01',NULL,NULL,replace('Comic USA: Justice League of America Vol. 4 nº 01\rHistoria: \rLos mas peligrosos del mundo (parte 1)\rLa imagen pública de la Liga de la Justicia se deterioró considerablemente durante la batalla contra David Graves, un antiguo escritor que estuvo a punto de matar al coronel Steve Trevor, el enlace del grupo con ARGUS, la agencia gubernamental que, entre otras cosas, vigila de cerca las andanzas del grupo. Destituido y sustituido por la implacable Amanda Waller, Trevor se ha reunido recientemente con su aliado Green Arrow, que ha encontrado pruebas de que algo gordo se está cociendo en los bajos fondos.','\r',char(13)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005386367-0786vh.jpg','unread',0,NULL,NULL,'2026-04-12 14:49:49','2026-04-12 14:49:49',223,24.95,'Grapa','[{"name":"Geoff Johns","role":""},{"name":"David Finch","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(1999,'Liga de la Justicia de América #2','Liga de la Justicia de América',2,NULL,'978-8-415-92536-1',NULL,'Geoff Johns','David Finch',NULL,NULL,'ECC Ediciones',NULL,'2013-08-01',NULL,NULL,replace('Comic USA: Justice League of America  Vol. 4 nº 02\rHistoria: \rLos mas peligrosos del mundo (parte 2)\rPersonal de Seguridad\rTras el fiasco de David Graves y la guerra contra Atlantis, el gobierno de Estados Unidos ha decidido poner en marcha un plan para tener controlada a la Liga de la Justicia en caso de necesidad. La relación entre Superman y Wonder Woman inquieta especialmente a Amanda Waller, la encargada de poner en marcha un grupo llamado Liga de la Justicia de América. Mientras tanto, en connivencia con Steve Trevor, Green Arrow ha descubierto a costa de su salud que se ha puesto en marcha algo llamado “Sociedad Secreta”.','\r',char(13)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005393995-2zlfyr.jpg','unread',0,NULL,NULL,'2026-04-12 14:49:54','2026-04-12 14:49:54',223,NULL,'Grapa','[{"name":"Geoff Johns","role":""},{"name":"David Finch","role":""},{"name":"Scott Clark","role":""},{"name":"Matt Kindt","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2000,'Liga de la Justicia de América #3','Liga de la Justicia de América',3,NULL,'978-8-415-92570-5',NULL,'Geoff Johns','Matt Kindt',NULL,NULL,'ECC Ediciones',NULL,'2013-10-01',NULL,NULL,replace('Comic USA: Justice League of America Vol. 4 nº 3\rHistoria:\rLos más peligrosos del mundo (parte 3): El bosque y los árboles\rTrozos que faltan\rCourtney Whitmore está de moda. Tiene una estrella en el Paseo de la Fama de Los Ángeles, la quiere toda la opinión pública y, encima, porta una Vara Cósmica que le confiere asombrosos poderes. Por si fuera poco, Stargirl es miembro de la Liga de la Justicia de América, algo que le hace mucha ilusión aunque, como está a punto de averiguar, sea un arma de doble filo. No en vano, Amanda Waller le tiene reservado un puesto en el grupo que, si bien es importante, no es exactamente lo que la joven esperaba.','\r',char(13)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005396060-in7lp4.jpg','unread',0,NULL,NULL,'2026-04-12 14:49:57','2026-04-12 14:49:57',223,NULL,'Grapa','[{"name":"Geoff Johns","role":""},{"name":"Matt Kindt","role":""},{"name":"David Finch","role":""},{"name":"Manuel García","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2001,'Liga de la Justicia de América #4','Liga de la Justicia de América',4,NULL,'978-8-415-92591-0',NULL,'Geoff Johns','Matt Kindt',NULL,NULL,'ECC Ediciones',NULL,'2013-11-01',NULL,NULL,replace(replace('Comic USA: Catwoman Vol. 4 nº 19 y Justice League of America Vol. 4 nº 04\r\nHistoria: \r\nSlam\r\nLos más peligrosos del mundo (parte 4): El bueno, el malo y el peludo.\r\nLa flamante Liga de la Justicia de América se ha enfrentado a unos androides que replicaban a Superman, Batman y Wonder Woman y que, al parecer, eran obra del Profesor Ivo, un antiguo colega de Silas Stone. Steve Trevor orquesta un plan para que Catwoman, el as que se guarda en la manga, se infiltre en la organización de supervillanos descubierta por Green Arrow; sin embargo, en vez de acogerla en sus filas, los mal- hechores la raptan y la atan. Por su parte, Stargirl no está de acuerdo con el papel que desempeña en la Liga...','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005398379-fxevz1.jpg','unread',0,NULL,NULL,'2026-04-12 14:49:58','2026-04-12 14:49:58',223,NULL,'Grapa','[{"name":"Geoff Johns","role":""},{"name":"Matt Kindt","role":""},{"name":"Ann Nocenti","role":""},{"name":"Brett Booth","role":""},{"name":"Andrés Guinaldo","role":""},{"name":"Rafa Sandoval","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2002,'Liga de la Justicia de América #5','Liga de la Justicia de América',5,NULL,'978-8-415-99021-5',NULL,'Geoff Johns','Matt Kindt',NULL,NULL,'ECC Ediciones',NULL,'2013-11-27',NULL,NULL,replace('Comic USA: Justice League of America Vol. 4 nº 05\rHistoria: Los más peligrosos del mundo (parte 5) / El Detective Marciano\rLa Sociedad Secreta, cuyo lema parece ser la críptica frase aeternus malum, ha raptado a Catwoman. Incapaces de dar con su paradero, Amanda Waller y Steve Trevor recurren a Arthur Light, un especialista en rastrear energías superhumanas que acompaña a la Liga de la Justicia de América en una arriesgada misión de rescate en la que también participa Stargirl sin que Waller lo sepa. Pero la Felina Fatal, que ha logrado liberarse sola, mete las narices donde no le llaman y se encuentra cara a cara con el misterioso líder de la Sociedad...','\r',char(13)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005400263-ynceht.jpg','unread',0,NULL,NULL,'2026-04-12 14:50:01','2026-04-12 14:50:01',223,NULL,'Grapa','[{"name":"Geoff Johns","role":""},{"name":"Matt Kindt","role":""},{"name":"Brett Booth","role":""},{"name":"Manuel García","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2003,'Liga de la Justicia de América #6','Liga de la Justicia de América',6,NULL,'978-8-415-99046-8',NULL,'Geoff Johns','Jeff Lemire',NULL,NULL,'ECC Ediciones',NULL,'2013-12-31',NULL,NULL,replace(replace('Recopila Justice League of America #6, Justice League Dark #22 y Constantine #5 (capítulos 2 y 3 del crossover &quot;La guerra de la Trinidad&quot; y un &quot;tie-in&quot; respectivamente)\r\nBilly Batson, el niño que se transforma en el poderoso superhéroe Shazam, quería depositar las cenizas de su archienemigo Black Adam en Kahndaq, el país natal de este. No obstante, la incursión ha llamado la atención de la Liga de la Justicia y la Liga de la Justicia de América, que están a punto de enfrentarse por fin. El detonante es el asesinato del Dr. Luz... y el responsable es Superman. Lo que Trevor y compañía no saben es que el Hombre de Acero ha estado en contacto con la Caja de Pandora y que las consecuencias son imprevisibles.','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005402817-3caer8.jpg','unread',0,NULL,NULL,'2026-04-12 14:50:03','2026-04-12 14:50:03',223,NULL,'Grapa','[{"name":"Geoff Johns","role":""},{"name":"Jeff Lemire","role":""},{"name":"Ray Fawkes","role":""},{"name":"Doug Mahnke","role":""},{"name":"Renato Guedes","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2004,'Liga de la Justicia de América #7','Liga de la Justicia de América',7,NULL,'978-8-415-99076-5',NULL,'Geoff Johns','Jeff Lemire',NULL,NULL,'ECC Ediciones',NULL,'2014-01-31',NULL,NULL,replace(replace('Recopila Justice League of America #7 USA (capítulo 4 de &quot;La guerra de la Trinidad&quot;), Trinity Of Sin: The Phantom Stranger #11 USA y Trinity of Sin: Pandora #2 USA (dos &quot;tie-in&quot; con el crossover).\r\n&quot;Poseído por la Caja de Pandora, Superman ha cometido un asesinato, lo cual desata una batalla entre la Liga de la Justicia y la Liga de la Justicia de América. El Hombre de Acero se entrega, pero no tarda en liberarlo un misterioso visitante. Por su parte, Wonder Woman busca información sobre la Caja y su dueña, de ahí que recurra a la experiencia mágica de la Liga de la Justicia Oscura. Madame Xanadú, miembro de dicho grupo y prisionera de la Sociedad Secreta, averigua que en las otras Ligas hay un topo.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005404602-59s90d.jpg','unread',0,NULL,NULL,'2026-04-12 14:50:05','2026-04-12 14:50:05',223,NULL,'Grapa','[{"name":"Geoff Johns","role":""},{"name":"Jeff Lemire","role":""},{"name":"Ray Fawkes","role":""},{"name":"J.M. DeMatteis","role":""},{"name":"Doug Mahnke","role":""},{"name":"Daniel Sampere","role":""},{"name":"Fernando Blanco","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2005,'Liga de la Justicia de América #8','Liga de la Justicia de América',8,NULL,'978-8-416-07010-7',NULL,'Geoff Johns','Edgar Salazar',NULL,NULL,'ECC Ediciones',NULL,'2014-03-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League of America núm. 7.4 USA\r\nTras pasar muchos atrapados por las fechorías cometidas en el pasado, Black Adam regresó al mundo de los vivos de la mano del Dr. Sivana, que estaba obsesionado con la magia. El antiguo campeón de la Roca Eternidad se propuso liberar al mundo de los tiranos que lo esclavizaban, y para ello necesitaba el poder de Billy Batson, el flamante héroe conocido como Shazam. Tras una cruenta batalla, Adam quedó reducido a unas cenizas que su adversario depositó en Kahndaq, el país natal del villano.','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005406374-hxqiqa.jpg','unread',0,NULL,NULL,'2026-04-12 14:50:07','2026-04-12 14:50:07',223,NULL,'Grapa','[{"name":"Geoff Johns","role":"Guion"},{"name":"Sterling Gates","role":"Guion"},{"name":"Edgar Salazar","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2006,'Liga de la Justicia de América #9','Liga de la Justicia de América',9,NULL,'978-8-416-07048-0',NULL,'Matt Kindt','Tom Derenick',NULL,NULL,'ECC Ediciones',NULL,'2014-04-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League of America núm. 8 USA\r\nLa Caja de Pandora resultó ser un portal a Tierra 3 que el Infiltrado utilizó para traer a nuestro mundo al Sindicato del Crimen, un grupo formado por homólogos malvados de la Liga de la Justicia. Poco se sabe de la batalla que se produjo a continuación, pero los villanos han proclamado a los cuatro vientos que han matado a los héroes y que han conquistado el mundo. Su siguiente paso ha sido reclutar a todos los malhechores locales, pero ¿de verdad no hubo supervivientes que puedan arreglar la situación?','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005408415-fnwsgs.jpg','unread',0,NULL,NULL,'2026-04-12 14:50:09','2026-04-12 14:50:09',223,NULL,'Grapa','[{"name":"Matt Kindt","role":"Guion"},{"name":"Tom Derenick","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2007,'Liga de la Justicia de América #10','Liga de la Justicia de América',10,NULL,'978-8-416-07082-4',NULL,'Matt Kindt','Tom Derenick',NULL,NULL,'ECC Ediciones',NULL,'2014-04-30',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League of America núm. 9 USA\r\nEl Sindicato del Crimen dice que ha matado a las Ligas de la Justicia, pero sabemos que no es cierto. Batman, Catwoman y Ciborg escaparon de los villanos para buscar refugio en Laboratorios S.T.A.R., y el Detective Marciano y Stargirl han descubierto que se encuentran en una especie de cárcel psíquica. Mientras J’onn J’onzz y Jason Rusch buscan a los demás héroes, que están atrapados en realidades que reproducen sus peores miedos, Stargirl parece haber encontrado una salida a un mundo aún más terrorífico.','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005410673-8b5dje.jpg','unread',0,NULL,NULL,'2026-04-12 14:50:11','2026-04-12 14:50:11',223,NULL,'Grapa','[{"name":"Matt Kindt","role":"Guion"},{"name":"Tom Derenick","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2008,'Liga de la Justicia de América #11','Liga de la Justicia de América',11,NULL,'978-8-416-15213-1',NULL,'Matt Kindt','Eddy Barrows',NULL,NULL,'ECC Ediciones',NULL,'2014-05-30',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League of America núm. 10 USA\r\nEl Detective Marciano y Stargirl son los únicos miembros de la Liga de la Justicia de América que son conscientes de estar atrapados en una especie de cárcel psíquica. La joven Courtney, que obtuvo sus poderes tras registrar las pertenencias de su padrastro y se convirtió en toda una estrella mediática, logra dar con J’onn y, tras confirmarle que todo es una ilusión, se lo lleva a lo que parece el mundo real. No obstante, Stargirl no tarda en hallarse “sola” ante un nutrido grupo de supervillanos...','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005412581-06podi.jpg','unread',0,NULL,NULL,'2026-04-12 14:50:13','2026-04-12 14:50:13',223,NULL,'Grapa','[{"name":"Matt Kindt","role":"Guion"},{"name":"Eddy Barrows","role":"Dibujo"},{"name":"Tom Derenick","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2009,'Liga de la Justicia de América #12','Liga de la Justicia de América',12,NULL,'978-8-416-15269-8',NULL,'Matt Kindt','Eddy Barrows',NULL,NULL,'ECC Ediciones',NULL,'2014-06-30',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League of America núm. 11 USA\r\nTras escapar de la prisión donde la había encerrado el Sindicato del Crimen, Stargirl se enfrenta a la Sociedad Secreta mientras recuerda su reciente origen como superheroína y los problemas con su padrastro, a quien robó el arma que la hace tan poderosa. Por su parte, el Detective Marciano ha averiguado que casi todos los miembros de las Ligas de la Justicia están atrapados en la matriz de Firestorm, y debe deducir cómo liberarlos y también por qué Courtney y él son los únicos que han logrado huir.','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005414296-ummjxa.jpg','unread',0,NULL,NULL,'2026-04-12 14:50:14','2026-04-12 14:50:14',223,NULL,'Grapa','[{"name":"Matt Kindt","role":"Guion"},{"name":"Eddy Barrows","role":"Dibujo"},{"name":"Tom Derenick","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2010,'Liga de la Justicia de América #13','Liga de la Justicia de América',13,NULL,'978-8-416-15299-5',NULL,'Matt Kindt','Eddy Barrows',NULL,NULL,'ECC Ediciones',NULL,'2014-07-30',NULL,NULL,replace(replace('Justice League of America núm. 12 USA\r\nEl Detective Marciano y Stargirl se enfrentan a Clayface en Gotham City, pero no tardan en verse obligados a viajar al Oeste durante varios días, concretamente a Los Ángeles. No en vano, J’onn ha detectado que la Sociedad Secreta y el Sindicato del Crimen han trasladado a Firestorm, en cuya psique están encerrados los miembros de las Ligas de la Justicia. Y el Hombre Nuclear está a punto de estallar. No obstante, los aventureros se van a topar con un buen obstáculo en su camino: el mismísimo Despero.','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005415842-q2jtj7.jpg','unread',0,NULL,NULL,'2026-04-12 14:50:16','2026-04-12 14:50:16',223,NULL,'Grapa','[{"name":"Matt Kindt","role":"Guion"},{"name":"Eddy Barrows","role":"Dibujo"},{"name":"Tom Derenick","role":"Dibujo"},{"name":"R. B. Silva","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2011,'Liga de la Justicia de América #14','Liga de la Justicia de América',14,NULL,'978-8-416-19446-9',NULL,'Matt Kindt','Eddy Barrows',NULL,NULL,'ECC Ediciones',NULL,'2014-09-01',NULL,NULL,replace(replace('Justice League of America núm. 13 USA\r\nMientras Stargirl rememora su primera batalla con un supervillano y una irreparable tragedia personal, el Detective Marciano se enfrenta a Despero, que tiene cuentas que ajustar con él. Un ataque brutal que parece interponerse en la misión de ambos héroes: evitar la inminente fusión de Firestorm.','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005417836-rdcoi3.jpg','unread',0,NULL,NULL,'2026-04-12 14:50:19','2026-04-12 14:50:19',223,NULL,'Grapa','[{"name":"Matt Kindt","role":"Guion"},{"name":"Eddy Barrows","role":"Dibujo"},{"name":"Tom Derenick","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2012,'Liga de la Justicia de América #15','Liga de la Justicia de América',15,NULL,'978-8-416-19490-2',NULL,'Matt Kindt','Eddy Barrows',NULL,NULL,'ECC Ediciones',NULL,'2014-10-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League of America núm. 14 USA \r\nÚLTIMO NÚMERO. La serie fue sustituida en EEUU por Justice League United.\r\n&quot;Como consecuencia de Maldad Eterna, esta cabecera da por finalizada su andadura a través de un epílogo idóneo para despedirse de los lectores… e invitarles a seguir una nueva colección: Justice League United, que a partir de este mes comienza a publicarse en las páginas de Liga de la Justicia.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005420427-bcswex.jpg','unread',0,NULL,NULL,'2026-04-12 14:50:21','2026-04-12 14:50:21',223,NULL,'Grapa','[{"name":"Matt Kindt","role":"Guion"},{"name":"Eddy Barrows","role":"Dibujo"},{"name":"Tom Derenick","role":"Dibujo"},{"name":"Diógenes Neves","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2013,'JLA. Liga de la Justicia de América #1','JLA. Liga de la Justicia de América',1,NULL,'978-8-416-51883-8',NULL,'Bryan Hitch','Bryan Hitch',NULL,NULL,'ECC Ediciones',NULL,'2015-12-01',NULL,NULL,replace(replace('Incluye Justice League of America #1 USA (junio/2015)\r\n&quot;El intento de invasión de Darkseid y las huestes de Apokolips forzó la reunión de los superhéroes que el mundo empezaba a conocer: Superman, el defensor de los desfavorecidos; Batman, el protector de Gotham City; Wonder Woman, la princesa de las amazonas; Hal Jordan, el Green Lantern de la Tierra; Flash, el hombre más rápido del mundo; Aquaman, legítimo rey de los siete mares; y Cíborg, un prometedor deportista que estuvo a punto de morir durante la invasión. Ahora, conforman la Liga de la Justicia, el grupo más poderoso de la Tierra.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005447225-hrh2iw.jpg','unread',0,NULL,NULL,'2026-04-12 14:50:50','2026-04-12 14:50:50',224,24.95,'Grapa','[{"name":"Bryan Hitch","role":"Guion, Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2014,'JLA. Liga de la Justicia de América #2','JLA. Liga de la Justicia de América',2,NULL,'978-8-416-58125-2',NULL,'Bryan Hitch','Bryan Hitch',NULL,NULL,'ECC Ediciones',NULL,'2015-12-21',NULL,NULL,replace(replace('Incluye Justice League of America #2 USA (julio/2015)\r\n&quot;Tras el espectacular debut de esta colección, los integrantes del supergrupo por excelencia del Universo DC se enfrentan a nuevas amenazas, ideadas por Bryan Hitch, talentoso dibujante que en esta colección ejerce como autor completo.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005459130-zwjj8x.jpg','unread',0,NULL,NULL,'2026-04-12 14:50:59','2026-04-12 14:50:59',224,NULL,'Grapa','[{"name":"Bryan Hitch","role":"Guion, Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2015,'JLA. Liga de la Justicia de América #3','JLA. Liga de la Justicia de América',3,NULL,'978-8-416-58163-4',NULL,'Bryan Hitch','Bryan Hitch',NULL,NULL,'ECC Ediciones',NULL,'2016-01-28',NULL,NULL,'Bryan Hitch sigue desarrollando su etapa como autor completo al frente de esta nueva colección. Con el dios Rao empeñado en convertir la Tierra en una utopía, ¿cómo reaccionará el supergrupo?',NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005460531-qvjtjr.jpg','unread',0,NULL,NULL,'2026-04-12 14:51:01','2026-04-12 14:51:01',224,NULL,'Grapa','[{"name":"Bryan Hitch","role":"Guion, Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2016,'JLA. Liga de la Justicia de América #4','JLA. Liga de la Justicia de América',4,NULL,'978-8-416-66011-7',NULL,'Bryan Hitch','Bryan Hitch',NULL,NULL,'ECC Ediciones',NULL,'2016-02-29',NULL,NULL,replace(replace('Incluye Justice League of America #4 USA. &quot;Power and glory&quot;, parte 4.\r\n&quot;Poco a poco, Bryan Hitch va revelando las claves argumentales de esta nueva colección, en las que ejerce como autor completo. ¿Será capaz la Liga de la Justicia de América de derrotar al dios Rao?&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005462409-1csjd0.jpg','unread',0,NULL,NULL,'2026-04-12 14:51:03','2026-04-12 14:51:03',224,NULL,'grapa','[{"name":"Bryan Hitch","role":"Guion, Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2017,'JLA. Liga de la Justicia de América #5','JLA. Liga de la Justicia de América',5,NULL,'978-8-416-66071-1',NULL,'Matt Kindt','Phillip Tan',NULL,NULL,'ECC Ediciones',NULL,'2016-03-28',NULL,NULL,replace(replace('Incluye Justice League of America #5 USA. Este capítulo es un fill-in con autores invitados.\r\n&quot;La cabecera orquestada por Bryan Hitch centra su atención en el Detective Marciano, Y no es el único invitado que resultará familiar a nuestros lectores, ya que este mes Matt Kindt (Liga de la Justicia de América), Rob Williams (Batman/Superman/Wonder Woman: Crónicas de la Trinidad) y Philip Tan (Batman y Robin) ejercerán como equipo creativo.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005467796-tox7s4.jpg','unread',0,NULL,NULL,'2026-04-12 14:51:08','2026-04-12 14:51:08',224,NULL,'Grapa','[{"name":"Matt Kindt","role":"Guion"},{"name":"Rob Williams","role":"Guion"},{"name":"Phillip Tan","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2018,'JLA. Liga de la Justicia de América #6','JLA. Liga de la Justicia de América',6,NULL,'978-8-416-71126-0',NULL,'Bryan Hitch','Bryan Hitch',NULL,NULL,'ECC Ediciones',NULL,'2016-04-22',NULL,NULL,replace(replace('Incluye Justice League of America #6 USA (diciembre/2015). &quot;Power and glory&quot;, parte 5.\r\n&quot;Bryan Hitch sigue poniendo a prueba a la Liga de la Justicia de América en un número repleto de acción donde el supergrupo continúa su enfrentamiento contra las fuerzas de Rao.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005470049-kc278u.jpg','unread',0,NULL,NULL,'2026-04-12 14:51:10','2026-04-12 14:51:10',224,NULL,'Grapa','[{"name":"Bryan Hitch","role":"Guion, Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2019,'JLA. Liga de la Justicia de América #7','JLA. Liga de la Justicia de América',7,NULL,'978-8-416-74603-3',NULL,'Bryan Hitch','Bryan Hitch',NULL,NULL,'ECC Ediciones',NULL,'2016-05-26',NULL,NULL,replace(replace('Incluye Justice League of America #7 USA (enero/2016). &quot;Power and glory&quot;, parte 6.\r\n&quot;Bryan Hitch (JLA: Escalera al cielo) sigue ejerciendo como autor completo de la colección para ofrecernos un nuevo capítulo del enfrentamiento de la Liga de la Justicia de América contra el poderoso Rao.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005471775-wswwps.jpg','unread',0,NULL,NULL,'2026-04-12 14:51:12','2026-04-12 14:51:12',224,NULL,'Grapa','[{"name":"Bryan Hitch","role":"Guion, Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2020,'JLA. Liga de la Justicia de América #8','JLA. Liga de la Justicia de América',8,NULL,'978-8-416-74667-5',NULL,'Bryan Hitch','Bryan Hitch',NULL,NULL,'ECC Ediciones',NULL,'2016-06-28',NULL,NULL,replace(replace('Incluye Justice League of America #8 USA (marzo/2016). &quot;Power and glory&quot;, parte 7.\r\n(Nota: La serie acumula retrasos en EEUU, y a 3 de junio de 2016, Justice League of America #9 no se ha publicado todavía. DC y Hitch han informado en junio que la salida de los #9-12 y Annual #1, en los que finalizaría la trama, se ha cancelado temporalmente y se anunciará una nueva fecha próximamente).\r\n&quot;La deidad conocida como Rao está llevando al límite a la Liga de la Justicia, ¡y la Tierra está sufriendo los daños colaterales de la contienda! ¿Lograrán detener a la entidad kryptoniana?&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005474278-hca1as.jpg','unread',0,NULL,NULL,'2026-04-12 14:51:15','2026-04-12 14:51:15',224,NULL,'Grapa','[{"name":"Bryan Hitch","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2021,'JLA. Liga de la Justicia de América #9','JLA. Liga de la Justicia de América',9,NULL,'978-8-416-90191-3',NULL,'Bryan Hitch','Bryan Hitch',NULL,NULL,'ECC Ediciones',NULL,'2016-11-29',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League of America núm. 9 USA\r\nARGUMENTO: Tras un pequeño parón, producido por las dilaciones en la edición original americana, retomamos la publicación de este título. ¡La deidad de Krypton conocida como Rao tiene a la Liga de la Justicia contra las cuerdas, y la Tierra sufre los daños colaterales de la batalla! Se necesitaría un milagro para derrotarlo. Lo bueno es que la Liga hace que los milagros se hagan realidad...\r\nDesde hace casi dos décadas, Bryan Hitch (JLA: Escalera al cielo) pone su espectacular trazo al servicio de historias trepidantes y llenas de acción, gracias a las cuales se ha convertido en todo un referente en la industria del cómic.','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005478879-47zhga.jpg','unread',0,NULL,NULL,'2026-04-12 14:51:19','2026-04-12 14:51:19',224,NULL,'Grapa','[{"name":"Bryan Hitch","role":"Guion, Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2022,'JLA. Liga de la Justicia de América #10','JLA. Liga de la Justicia de América',10,NULL,'978-8-416-99837-1',NULL,'Bryan Hitch','Bryan Hitch',NULL,NULL,'ECC Ediciones',NULL,'2017-02-27',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League of America núm. 10 USA   \r\nARGUMENTO: ¡Última entrega! Un acto desesperado de Wonder Woman reanima a Superman justo a tiempo de que la Liga de la Justicia se entere de cuál es el auténtico plan de su poderoso adversario, Rao, el dios del antiguo Krypton. Con el grupo atónito antes de los acontecimientos, el único héroe capaz de resolver la situación parece ser Green Lantern, que ha estado atrapado en la Argo City de hace siglos mientras sus amigos luchaban en el presente.','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005481261-fsut40.jpg','unread',0,NULL,NULL,'2026-04-12 14:51:21','2026-04-12 14:51:21',224,NULL,'Grapa','[{"name":"Bryan Hitch","role":"Guion, Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2023,'Liga de la Justicia: Sin justicia #1','Liga de la Justicia: Sin justicia',1,NULL,'978-8-417-61299-3',NULL,'James Tynion IV','Francis Manapul',NULL,NULL,'ECC Ediciones',NULL,'2018-10-09',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League: No Justice núm. 1 USA\r\nNoches oscuras: Metal ha transformado al Universo DC, de forma aterradora... y maravillosa. En este contexto, ha llegado el momento de adaptar a la Liga a los nuevos tiempos. ¡Solo la Liga de la Justicia puede aglutinar suficiente poder como para derrotar a las amenazas que están por llegar! ¿O no? Cuatro devoradores de planetas, alimentados por las energías ancestrales que han dado forma al universo, están a punto de poner a prueba a nuestros héroes. Su única esperanza reside en olvidar las viejas tradiciones y formar nuevas alianzas, ¡y eso incluye a villanos como Brainiac! \r\nLa nueva etapa de la Liga de la Justicia, orquestada por las estrellas Scott Snyder (Batman), Jim Cheung (Jóvenes Vengadores) y Jorge Jiménez (Superhijos), está a punto de comenzar. Pero antes de iniciar una nueva era de grandeza para el mayor grupo del Universo DC, es el momento de colocar las piezas sobre el tablero, y reimaginar a nuestros héroes favoritos. Tres de los principales arquitectos de la actual DC Comics, Scott Snyder, James Tynion IV (Batman: Detective Comics), y Joshua Williamson (Flash), acompañados de Francis Manapul (Trinidad) al dibujo, presentan uno de los eventos más esperados del año, Liga de la Justicia: Sin justicia. ¡Un viaje inesperado por los mayores peligros del Multiverso!','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005493735-dklcen.jpg','unread',0,NULL,NULL,'2026-04-12 14:51:37','2026-04-12 14:51:37',225,24.95,'Grapa','[{"name":"James Tynion IV","role":"Guion"},{"name":"Joshua Williamson","role":"Guion"},{"name":"Scott Snyder","role":"Guion"},{"name":"Francis Manapul","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2024,'Liga de la Justicia: Sin justicia #2','Liga de la Justicia: Sin justicia',2,NULL,'978-8-417-64416-1',NULL,'James Tynion IV','Francis Manapul',NULL,NULL,'ECC Ediciones',NULL,'2018-10-09',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League: No Justice núm. 2 USA\r\nLos equipos de la Liga de la Justicia llegan al mundo de origen de Brainiac, ¡un mundo dominado por el caos! El grupo debe dividirse y encontrar la salvación del planeta en los cuatro árboles cósmicos de Colu. ¡Lo que les espera pondrá a prueba la verdadera valía de las nuevas alianzas!','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005500183-fk9k62.jpg','unread',0,NULL,NULL,'2026-04-12 14:51:40','2026-04-12 14:51:40',225,NULL,'Grapa','[{"name":"James Tynion IV","role":"Guion"},{"name":"Joshua Williamson","role":"Guion"},{"name":"Scott Snyder","role":"Guion"},{"name":"Francis Manapul","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2025,'Liga de la Justicia: Sin justicia #3','Liga de la Justicia: Sin justicia',3,NULL,'978-8-417-64427-7',NULL,'James Tynion IV','Francis Manapul',NULL,NULL,'ECC Ediciones',NULL,'2018-10-16',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League: No Justice núm. 3 USA\r\nStarfire realiza un descubrimiento clave, Chico Bestia se encuentra cara a cara con una impactante traición, Cíborg y Wonder Woman se ven obligados a tomar decisiones que tendrán consecuencias devastadoras para los cuatro equipos de la Liga... y para todos aquellos que se quedaron en la Tierra.','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005505476-i8js3f.jpg','unread',0,NULL,NULL,'2026-04-12 14:51:46','2026-04-12 14:51:46',225,NULL,'Grapa','[{"name":"James Tynion IV","role":"Guion"},{"name":"Joshua Williamson","role":"Guion"},{"name":"Scott Snyder","role":"Guion"},{"name":"Francis Manapul","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2026,'Liga de la Justicia: Sin justicia #4','Liga de la Justicia: Sin justicia',4,NULL,'978-8-417-64439-0',NULL,'James Tynion IV','Francis Manapul',NULL,NULL,'ECC Ediciones',NULL,'2018-10-23',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League: No Justice núm. 4 USA\r\n¡El épico desenlace del que todo el mundo hablará en los próximos meses! Lo inimaginable ha ocurrido, y ahora el Universo DC debe estar más unido que nunca, para defender a la Tierra de la aniquilación. Antes del final, se forjarán nuevas alianzas... ¡y algunos héroes desaparecerán para siempre! Este número da pie a la siguiente era de grandeza de la Liga, que podréis disfrutar a partir del mes que viene, en las páginas de Liga de la Justicia núm. 79/ 01.','\r',char(13)),'\n',char(10)),NULL,NULL,32,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005507872-jdiaoe.jpg','unread',0,NULL,NULL,'2026-04-12 14:51:48','2026-04-12 14:51:48',225,NULL,'Grapa','[{"name":"James Tynion IV","role":"Guion"},{"name":"Joshua Williamson","role":"Guion"},{"name":"Scott Snyder","role":"Guion"},{"name":"Francis Manapul","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2027,'All In Detective Comics #1','All In Detective Comics',1,NULL,'9773081292008-00001',NULL,'Tom Taylor','Mikel Janin',NULL,NULL,'Panini Comics España',NULL,'2025-04-03',NULL,NULL,replace(replace('Contiene Detective Comics 1090\r\nTiempo atrás, los asesinatos de Thomas y Martha Wayne cambiaron Gotham para siempre. Algo de su origen ha permanecido oculto al Caballero Oscuro, esperando para atacarle desde aquella trágica noche en el Callejón del Crimen. Y es ahora cuando este fantasma del pasado de Gotham va a salir a la luz en una historia firmada por dos superestrellas, Tom Taylor y Mikel Janín, que sacudirá los pilares del héroe.','\r',char(13)),'\n',char(10)),NULL,NULL,24,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005615189-11e0gf.jpg','unread',0,NULL,NULL,'2026-04-12 14:53:37','2026-04-12 14:53:37',226,1.5,'Grapa','[{"name":"Tom Taylor","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2028,'All In Detective Comics #2','All In Detective Comics',2,NULL,'9773081292008-00002',NULL,'Tom Taylor','Mikel Janin',NULL,NULL,'Panini Comics España',NULL,'2025-05-15',NULL,NULL,replace(replace('Contiene Detective Comics 1091\r\nBruce Wayne recibe una oferta demasiado tentadora. Un misterioso suero promete rejuvenecerle en cuerpo y mente, y le hará tan fuerte y ágil como antaño. ¿Será capaz de aceptarla? Mientras, la siniestra figura de Asema acecha en las sombras, cazando a villanos de poca monta con una precisión milimétrica y un propósito desconocido.','\r',char(13)),'\n',char(10)),NULL,NULL,24,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005622232-xyw9y8.jpg','read',0,NULL,NULL,'2026-04-12 14:53:42','2026-04-12 16:12:45',226,1.5,'grapa','[{"name":"Tom Taylor","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2029,'All In Detective Comics #3','All In Detective Comics',3,NULL,'9773081292008-00003',NULL,'Tom Taylor','Mikel Janin',NULL,NULL,'Panini Comics España',NULL,'2025-06-12',NULL,NULL,replace(replace('Contiene Detective Comics vol. 1 #1092 USA\r\nLas calles de Gotham se tiñen de rojo, como la sangre que tanto interesa a la misteriosa y dañina entidad conocida como Asema. Esta criatura con bisturís por dedos anda recolectando el plasma de hombres jóvenes… ¿Cuáles son sus motivos? ¿Y qué relación tiene con Bruce Wayne?','\r',char(13)),'\n',char(10)),NULL,NULL,24,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005624569-i7k9cn.jpg','read',0,NULL,NULL,'2026-04-12 14:53:45','2026-04-12 16:12:45',226,1.5,'grapa','[{"name":"Tom Taylor","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2030,'All In Detective Comics #4','All In Detective Comics',4,NULL,'9773081292008-00004',NULL,'Tom Taylor','Mikel Janin',NULL,NULL,'Panini Comics España',NULL,'2025-07-10',NULL,NULL,replace(replace('Contiene: Detective Comics 1093\r\nEl enfrentamiento contra Asema hace que Batman lo cuestione todo. ¿Quién es, cómo le conoce y qué pretende? Todas esas respuestas han de hallarse entre las tinieblas de su ciudad y de su psique. Los cimientos que sostienen al Caballero Oscuro comienzan a agrietarse, y deberá resolver el misterio antes de que todo se derrumbe.','\r',char(13)),'\n',char(10)),NULL,NULL,24,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005626626-3hfm17.jpg','read',0,NULL,NULL,'2026-04-12 14:53:47','2026-04-12 16:12:45',226,1.5,'lujo','[{"name":"Tom Taylor","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2031,'All In Detective Comics #5','All In Detective Comics',5,NULL,'9773081292008-00005',NULL,'Tom Taylor','Mikel Janin',NULL,NULL,'Panini Comics España',NULL,'2025-08-14',NULL,NULL,replace(replace('Contiene: Detective Comics 1094\r\nLas sombras se extienden sobre Gotham, en el puño de Asema. A Batman le cuesta mantener su ciudad a salvo y sospecha que quizás haya descubierto la identidad de su amenaza, sedienta de sangre... Puede que sea alguien muy cercano a él.','\r',char(13)),'\n',char(10)),NULL,NULL,24,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005628767-g76t8i.jpg','read',0,NULL,NULL,'2026-04-12 14:53:49','2026-04-12 16:12:45',226,1.5,'grapa','[{"name":"Tom Taylor","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2032,'All In Detective Comics #6','All In Detective Comics',6,NULL,'9773081292008-00006',NULL,'Tom Taylor','Mikel Janin',NULL,NULL,'Panini Comics España',NULL,'2025-09-11',NULL,NULL,replace(replace('Contiene: Detective Comics 1095\r\nBatman pone a la Batfamilia a trabajar a fondo para revelar la verdad tras los asesinatos que continúan arrasando Gotham, pero incluso sus mayores aliados fallan y no siempre son capaces de salvar a las jóvenes víctimas de Asema. El misterio se revela y la respuesta no será del agrado de nadie.','\r',char(13)),'\n',char(10)),NULL,NULL,24,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005630897-m9s7qr.jpg','read',0,NULL,NULL,'2026-04-12 14:53:51','2026-04-12 16:12:45',226,1.5,'Grapa','[{"name":"Tom Taylor","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2033,'All In Detective Comics #7','All In Detective Comics',7,NULL,'9773081292008-00007',NULL,'Tom Taylor','Mikel Janin',NULL,NULL,'Panini Comics España',NULL,'2025-10-09',NULL,NULL,replace(replace('Contiene: Detective Comics 1096 USA\r\nMantén a tus amigos cerca y a tus enemigos aún más cerca. Batman nunca ha sido partidario de ese adagio. O, al menos, él no pensaba que lo fuera. Ahora, mientras su último caso sobre Batman se acerca más a Bruce Wayne, teme haberse mantenido muy, muy cerca de su enemigo.','\r',char(13)),'\n',char(10)),NULL,NULL,24,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005632626-1pjw4y.jpg','read',0,NULL,NULL,'2026-04-12 14:53:53','2026-04-12 16:12:45',226,1.5,'Grapa','[{"name":"Tom Taylor","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2034,'All In Detective Comics #8','All In Detective Comics',8,NULL,'9773081292008-00008',NULL,'Fico Ossio','Stefano Raffaele',NULL,NULL,'Panini Comics España',NULL,'2025-11-13',NULL,NULL,replace(replace('Contiene: Detective Comics 2025 Annual\r\nUn mensaje, escrito en sangre junto a un cadáver, pide a Batman que no resuelva el asesinato. Sin apenas pistas, salvo por un libro titulado Cómo acabar con el universo, el héroe partirá a Inglaterra para resolver el crimen contra los deseos del fallecido. Además, Joshua Hale Fialkov y Mike Norton crean otro misterio para Batman que le reunirá con una de las mentes más brillantes de todo Gotham: un chaval de séptimo curso.','\r',char(13)),'\n',char(10)),NULL,NULL,24,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005635256-6v3971.jpg','read',0,NULL,NULL,'2026-04-12 14:53:56','2026-04-12 16:12:45',226,1.5,'Grapa','[{"name":"Fico Ossio","role":""},{"name":"Stefano Raffaele","role":""},{"name":"Joshua Fialkov","role":""},{"name":"Al Ewing","role":""},{"name":"John McCrea","role":""},{"name":"Mike Norton","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2035,'Absolute Martian Manhunter #1','Absolute Martian Manhunter',1,NULL,'9773081600001-00001',NULL,'Deniz Camp','Javier Rodríguez',NULL,NULL,'Panini Comics España',NULL,'2025-09-04',NULL,NULL,replace(replace('Contiene: Absolute Martian Manhunter 1\r\nLlega la nueva serie que reinventa a uno de los iconos clásicos de DC. Deniz Camp y Javier Rodríguez te arrastran a una locura como nunca has visto en el Universo Absolute... o en cualquier otro: Más allá de Marte, más allá de la forma física, más allá de la comprensión humana... todo lo que queda es el alien definitivo, ¡Absolute Martian Manhunter!\r\nPor Deniz Camp y Javier Rodríguez','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005711859-1nwqau.jpg','read',0,NULL,NULL,'2026-04-12 14:55:14','2026-04-12 16:12:45',227,NULL,'tapa dura','[{"name":"Deniz Camp","role":"Guion"},{"name":"Javier Rodríguez","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2036,'Absolute Martian Manhunter #2','Absolute Martian Manhunter',2,NULL,'9773081600001-00002',NULL,'Deniz Camp','Javier Rodríguez',NULL,NULL,'Panini Comics España',NULL,'2025-10-02',NULL,NULL,replace(replace('Contiene: Absolute Martian Manhunter 2.\r\nLa consciencia alienígena de otra dimensión que se hace llamar a sí misma Detective Marciano continúa con su invasión y transformación de la mente de John Jones. El rígido agente del FBI se ha visto arrastrado a una guerra cósmica que le hará cuestionarse la naturaleza misma de la realidad y sus creencias sobre el bien, el mal y el libre albedrío.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005718024-2ou2jb.jpg','read',0,NULL,NULL,'2026-04-12 14:55:19','2026-04-12 16:12:45',227,NULL,'grapa','[{"name":"Deniz Camp","role":"Guion"},{"name":"Javier Rodríguez","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2037,'Absolute Martian Manhunter #3','Absolute Martian Manhunter',3,NULL,'9773081600001-00003',NULL,'Deniz Camp','Javier Rodríguez',NULL,NULL,'Panini Comics España',NULL,'2025-11-06',NULL,NULL,replace(replace('Contiene: Absolute Martian Manhunter 3\r\nJohn Jones y el Marciano, nuevos compañeros, se embarcan en un viaje por la psicosfera de Middleton siguiendo el rastro de quien sea, o lo que sea, que ha provocado el comportamiento destructivo de los ciudadanos... y del resto del mundo.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005720318-r4j625.jpg','read',0,NULL,NULL,'2026-04-12 14:55:21','2026-04-12 16:12:45',227,NULL,'Grapa','[{"name":"Deniz Camp","role":"Guion"},{"name":"Javier Rodríguez","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2038,'Absolute Martian Manhunter #4','Absolute Martian Manhunter',4,NULL,'9773081600001-00004',NULL,'Deniz Camp','Javier Rodríguez',NULL,NULL,'Panini Comics España',NULL,'2025-12-04',NULL,NULL,replace(replace('Contiene Absolute Martian Manhunter 4\r\nUna ola de calor cae sobre Middleton. Con la temperatura elevando los problemas y agriando los ánimos, es normal que surjan conflictos entre vecinos... ¡pero no lo es tanto que estos se vuelvan mortales! ¿Podrán John Jones y el Marciano enfriar las cosas antes de que Middleton caiga presa del caos?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005722142-1efhdx.jpg','read',0,NULL,NULL,'2026-04-12 14:55:22','2026-04-12 16:12:45',227,NULL,'grapa','[{"name":"Deniz Camp","role":"Guion"},{"name":"Javier Rodríguez","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2039,'Absolute Martian Manhunter #5','Absolute Martian Manhunter',5,NULL,'9773081600001-00005',NULL,'Deniz Camp','Javier Rodríguez',NULL,NULL,'Panini Comics España',NULL,'2026-01-08',NULL,NULL,replace(replace('Contiene: Absolute Martian Manhunter 5\r\n¡Apagón en la ciudad! Tras un ataque a las estaciones eléctricas de Middleton, la ciudad está a oscuras. Y, cuando cae la noche, la oscuridad se vuelve más intensa. John Jones y el Marciano se las tendrán que ver contra una urbe llena de psicópatas... y contra quien se encuentra detrás.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005723948-h8wbc3.jpg','read',0,NULL,NULL,'2026-04-12 14:55:24','2026-04-12 16:12:45',227,NULL,'Grapa','[{"name":"Deniz Camp","role":"Guion"},{"name":"Javier Rodríguez","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2040,'Absolute Martian Manhunter #6','Absolute Martian Manhunter',6,NULL,'9773081600001-00006',NULL,'Deniz Camp','Javier Rodríguez',NULL,NULL,'Panini Comics España',NULL,'2026-02-05',NULL,NULL,replace(replace('Contiene: Absolute Martian Manhunter 6 USA.\r\nComo bombas atómicas, las ideas explotan fundiendo cada mente viviente y los colores chocan en la oscuridad tras los ojos de cada persona del planeta. Se trata del enfrentamiento entre el Marciano verde y el blanco, y entre John Jones y la mismísima locura, mientras lucha por salvar a su familia y al mundo.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005725947-amc0w3.jpg','read',0,NULL,NULL,'2026-04-12 14:55:26','2026-04-12 16:12:45',227,NULL,'grapa','[{"name":"Deniz Camp","role":"Guion"},{"name":"Javier Rodríguez","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2041,'Masacre/Batman','Masacre/Batman',NULL,NULL,'979-1-370-13342-9',NULL,'Zeb Wells','Greg Capullo',NULL,NULL,'Panini Comics España',NULL,'2025-10-09',NULL,NULL,replace(replace('Contiene: Deadpool/Batman One-Shot USA.\r\nEl crossover que estabas deseando leer pero que dabas por imposible. Masacre se enfrenta a Batman al tiempo que Marvel y DC se unen por primera vez después de varias décadas. Wade Wilson ha sido contratado para un trabajo en Gotham City. ¿Contará con la ayuda de Batman o éste le señalará como un nuevo enemigo? Zeb Wells y Greg Capullo tienen la respuesta. ¡Y esto es sólo el comienzo! A continuación, el Capitán América y Wonder Woman se encuentran, cortesía de Chip Zdarsky y Terry Dodson; Jeff y Krypto comparten juegos, con Kelly Thompson y Gurihiru; Kevin Smith, acompañado de Adam Kubert, reúne a sus dos personajes fetiche, Daredevil y Green Arrow, y otros formidables equipos presentan los más sorprendentes cruces entre ambas compañías. ¡Un acontecimiento que no puedes perderte!','\r',char(13)),'\n',char(10)),NULL,NULL,64,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005749904-9jgnbu.jpg','read',0,NULL,NULL,'2026-04-12 14:55:50','2026-04-12 16:12:45',NULL,6,'Grapa','[{"name":"Zeb Wells","role":"Guion"},{"name":"Greg Capullo","role":"Dibujo"},{"name":"Tim Townsend","role":"Tinta"},{"name":"Alex Sinclair","role":"Color"},{"name":"Chip Zdarsky","role":"Guion"},{"name":"Terry Dodson","role":"Dibujo, Color"},{"name":"Rachel Dodson","role":"Tinta"},{"name":"Kelly Thompson","role":"Guion"},{"name":"Gurihiru Studios","role":"Dibujo, Tinta, Color"},{"name":"Kevin Smith","role":"Guion"},{"name":"Adam Kubert","role":"Dibujo, Tinta"},{"name":"Frank Martin","role":"Color"},{"name":"Al Ewing","role":"Guion"},{"name":"Dike Ruan","role":"Dibujo, Tinta"},{"name":"Moreno Dinisio","role":"Color"},{"name":"Frank Miller","role":"Guion, Dibujo, Tinta"},{"name":"Ryan North","role":"Guion"},{"name":"Ryan Stegman","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2042,'Batman/Masacre','Batman/Masacre',NULL,NULL,'979-1-370-13343-6',NULL,'Grant Morrison','Dan Mora',NULL,NULL,'Panini Comics España',NULL,'2026-01-08',NULL,NULL,replace(replace('Contiene: Batman/Deadpool One-Shot USA.\r\n¡El Caballero Oscuro y el Mercenario Bocazas unen fuerzas en una aventura tan alucinante que pensarás que estás soñando!\r\nEn esta entrega no solo chocarán dos superhéroes tan dispares como Batman y Masacre, sino también dos filosofías diferentes en lo que a narrativa se refiere, así como dos arquetipos: oscuridad vs. caos, trauma vs. comedia, en una consecución de situaciones que in crescendo, forzando los límites de la realidad… y de la cuarta pared.\r\n¡Y no te pierdas estas increíbles historias extra!:\r\nScott Snyder, James Tynion IV y Joshua Williamson se alían con Hayden Sherman para un mágico relato de John Constantine y el Doctor Extraño.\r\nTom Taylor y Bruno Redondo presentan una épica historia de Nightwing/Dick Grayson y Laura Kinney/Lobezna.\r\nMariko Tamaki y Amanda Conner hacen chocar a Harley Quinn y Hulk.\r\nG. Willow Wilson y Denys Cowan cuentan un electrizante relato de Static y Ms. Marvel.','\r',char(13)),'\n',char(10)),NULL,NULL,64,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005762984-g79pa2.jpg','read',0,NULL,NULL,'2026-04-12 14:56:04','2026-04-12 16:12:45',NULL,6,'Grapa','[{"name":"Grant Morrison","role":"Guion"},{"name":"Dan Mora","role":"Dibujo, Tinta"},{"name":"Alejandro Sánchez","role":"Color"},{"name":"Scott Snyder","role":"Guion"},{"name":"James Tynion IV","role":"Guion"},{"name":"Joshua Williamson","role":"Guion"},{"name":"Hayden Sherman","role":"Dibujo, Tinta"},{"name":"Mike Spicer","role":"Color"},{"name":"Tom Taylor","role":"Guion"},{"name":"Bruno Redondo","role":"Dibujo, Tinta"},{"name":"Adriano Lucas","role":"Color"},{"name":"Mariko Tamaki","role":"Guion"},{"name":"Amanda Conner","role":"Dibujo, Tinta"},{"name":"Tamra Bonvillain","role":"Color"},{"name":"G. Willow Wilson","role":"Guion"},{"name":"Denys Cowan","role":"Dibujo"},{"name":"Klaus Janson","role":"Tinta"},{"name":"Francesco Segala","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2043,'Green Lantern (2012-2022) #1','Green Lantern (2012-2022)',1,NULL,'978-8-415-52069-6',NULL,'Geoff Johns','Doug Mahnke',NULL,NULL,'ECC Ediciones',NULL,'2012-05-01',NULL,NULL,replace(replace('USA: Green Lantern Vol. 5 nº 01, Green Lantern: New Guardians Vol. 1 nº 01\r\nHistorias: Sinestro (parte 1) / Nuevos Guardianes (parte 1)\r\nHace unos años, un temerario piloto de pruebas llamado Hal Jordan se convirtió en el primer miembro terrícola del Cuerpo de Green Lanterns, una organización policial interestelar fundada por los Guardianes del Universo. Allí, conoció a su mentor, Sinestro, el mismo que terminaría corrompiéndose y convirtiéndose en su peor enemigo. Tras enfrentarse en numerosas ocasiones, estos viejos adversarios formaron equipo para derrotar a Krona, un Guardián renegado a quien Jordan asesinó. Y mientras el terrícola era expulsado de la organización por semejante acto, Sinestro recuperaba sin quererlo su puesto en el Cuerpo.Hoy en día, hay más Green Lanterns nacidos en la Tierra. Kyle Rayner, el más reciente, ha vuelto a su planeta sin sospechar lo que le espera...','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005807941-uylwqn.jpg','read',0,NULL,NULL,'2026-04-12 14:56:51','2026-04-12 16:12:45',228,23.95,'Grapa','[{"name":"Geoff Johns","role":"Guion"},{"name":"Tony Bedard","role":"Guion"},{"name":"Doug Mahnke","role":"Dibujo"},{"name":"Tyler Kirkham","role":"Dibujo"},{"name":"Christian Alamy","role":"Tinta"},{"name":"Tom Nguyen","role":"Tinta"},{"name":"David Baron","role":"Color"},{"name":"Matt Banning","role":"Tinta"},{"name":"Nei Ruffino","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2044,'Green Lantern (2012-2022) #24','Green Lantern (2012-2022)',24,NULL,'978-8-416-07049-7',NULL,'Charles Soule','Alberto Ponticelli',NULL,NULL,'ECC Ediciones',NULL,'2014-03-31',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Green Lantern núms. 23.3 y 23.4 USA \r\nMano Negra terminó atrapado en la Zona Muerta durante el ataque del Primer Lantern, y su cuerpo se convirtió en polvo cuando Hal Jordan se quedó con su anillo, la única forma que tenía de escapar de aquel extraño lugar. Más o menos al mismo tiempo, Sinestro asistía atónito a la destrucción de Korugar, su planeta natal, a manos de Volthoom, el mencionado Primer Lantern. Fue entonces cuando abandonó definitivamente el anillo verde para retomar su antiguo puesto como principal representante del miedo amarillo.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005841576-bw8qm9.jpg','read',0,NULL,NULL,'2026-04-12 14:57:22','2026-04-12 16:12:45',228,NULL,'Grapa','[{"name":"Charles Soule","role":"Guion"},{"name":"Matt Kindt","role":"Guion"},{"name":"Alberto Ponticelli","role":"Dibujo"},{"name":"Dale Eaglesham","role":"Dibujo, Tinta"},{"name":"Stefano Landini","role":"Tinta"},{"name":"Daniel Vozzo","role":"Color"},{"name":"Billy Tan","role":"Dibujo, Tinta"},{"name":"Alex Sinclair","role":"Color"},{"name":"Andrew Dalhouse","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2045,'Green Lantern (2012-2022) #2','Green Lantern (2012-2022)',2,NULL,'978-8-415-52089-4',NULL,'Geoff Johns','Doug Mahnke',NULL,NULL,'ECC Ediciones',NULL,'2012-06-01',NULL,NULL,replace('USA: Green Lantern Vol. 5 nº 02, Green Lantern New Guardians Vol. 1 nº 02\rHistorias: Sinestro (parte 2) / Nuevos Guardianes (parte 2)\rPor su parte, Sinestro se ve obligado a pedir ayuda a su odiado Hal Jordan en Green Lantern núm. 2, donde Geoff Johns (Flashpoint) y Doug Mahnke (Crisis Final) narran una alianza que hasta hace poco parecía muy poco probable y que tiene un solo objetivo: la reconquista de Korugar.','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005845178-zyhxki.jpg','read',0,NULL,NULL,'2026-04-12 14:57:25','2026-04-12 16:12:45',228,NULL,'Grapa','[{"name":"Geoff Johns","role":""},{"name":"Doug Mahnke","role":""},{"name":"Tony Bedard","role":""},{"name":"Tyler Kirkham","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2046,'Green Lantern (2012-2022) #3','Green Lantern (2012-2022)',3,NULL,'978-8-415-62814-9',NULL,'Geoff Johns','Tony Bedard',NULL,NULL,'ECC Ediciones',NULL,'2012-07-01',NULL,NULL,replace('USA: Green Lantern Vol. 5 nº 03, Green Lantern New Guardians Vol. 1 nº 03\rHistorias: Sinestro (parte 3) / Nuevos Guardianes (parte 3)\rSinestro ha entregado un duplicado de su anillo a Hal Jordan y, juntos, se han enfrentado a un miembro de los Sinestro Corps que ha llegado a la Tierra para capturar a su antiguo líder. Una vez derrotado el agresor, el korugariano pide al terrícola que le ayude a liberar su planeta del ejército que él mismo creó. Por su parte, Kyle Rayner ha llevado los anillos de colores que lo asedian a Oa, donde, antes de ponérselos todos sin querer, se ha enterado de que los Guardianes han privado a Ganthet de sus emociones.','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005846855-yn308k.jpg','read',0,NULL,NULL,'2026-04-12 14:57:27','2026-04-12 16:12:45',228,NULL,'Grapa','[{"name":"Geoff Johns","role":""},{"name":"Tony Bedard","role":""},{"name":"Doug Mahnke","role":""},{"name":"Tyler Kirkham","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2047,'Green Lantern (2012-2022) #4','Green Lantern (2012-2022)',4,NULL,'978-8-415-62840-8',NULL,'Geoff Johns','Tony Bedard',NULL,NULL,'ECC Ediciones',NULL,'2012-08-01',NULL,NULL,replace('USA: Green Lantern Vol. 5 nº 04, Green Lantern New Guardians Vol. 1 nº 04\rHistorias: Sinestro (parte 4) / Nuevos Guardianes (parte 4)\rSinestro y Hal Jordan se marchan al planeta Korugar para liberarlo de los Sinestro Corps, que están causando estragos. El dúo traza un plan, pero la situación se les va de las manos y el terrícola termina metido en la batería amarilla, tras lo cual parece desintegrarse. Por su parte, Kyle Rayner ha llegado a Oa, donde utiliza los anillos de todos los colores para enfrentarse a los Guardianes del Universo, que han suprimido las emociones de Ganthet. Durante la batalla, Larfleeze hace por fin acto de presencia.','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005856879-ts27pc.jpg','read',0,NULL,NULL,'2026-04-12 14:57:37','2026-04-12 16:12:45',228,NULL,'Grapa','[{"name":"Geoff Johns","role":""},{"name":"Tony Bedard","role":""},{"name":"Doug Mahnke","role":""},{"name":"Tyler Kirkham","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2048,'Green Lantern (2012-2022) #5','Green Lantern (2012-2022)',5,NULL,'978-8-415-62853-8',NULL,'Geoff Johns','Tony Bedard',NULL,NULL,'ECC Ediciones',NULL,'2012-09-01',NULL,NULL,replace(replace('USA: Green Lantern Vol. 5 nº 05, Green Lantern New Guardians Vol. 1 nº 05\r\nHistorias: Sinestro (parte 5) / El Planetario\r\nNo hace tanto que Bleez fue la bella princesa de un planeta remoto poblado por seres capaces de volar con unas alas que extendían al viento. Pero los Sinestro Corps pusieron fin a aquella vida regalada que dio paso a una existencia miserable plagada de torturas de todo tipo. Hoy, Bleez es una de las componentes más reconocibles de los Red Lanterns y, como tal, está poseída por la energía roja que le nubla la mente. Pero eso va a cambiar gracias a su líder, Atrocitus... que tal vez se arrepienta de lo que hará próximamente.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005859350-l4pg3o.jpg','read',0,NULL,NULL,'2026-04-12 14:57:40','2026-04-12 16:12:45',228,NULL,'Grapa','[{"name":"Geoff Johns","role":""},{"name":"Tony Bedard","role":""},{"name":"Doug Mahnke","role":""},{"name":"Tyler Kirkham","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2049,'Green Lantern (2012-2022) #6','Green Lantern (2012-2022)',6,NULL,'978-8-415-62868-2',NULL,'Geoff Johns','Tony Bedard',NULL,NULL,'ECC Ediciones',NULL,'2012-10-01',NULL,NULL,replace('USA: Green Lantern Vol. 5 nº 06, Green Lantern New Guardians Vol. 1 nº 06\rHistorias: El Otro Héroe / La rabia de los ángeles\rHal Jordan y Sinestro, apoyados por el pueblo de Korugar, logran destruir la Gran Batería amarilla y derrotar así a los antiguos acólitos del segundo, a los que llevan a Oa. Allí, los Guardianes se proponen liberar al primer Green Lantern, el que encabezará lo que ellos llaman “tercer ejército”. Por su parte, Kyle Rayner, Fatalidad y compañía se adentran en el Planetario en busca del villano que Larfleeze les ha enviado a buscar. El problema es que, allí, al Orange Lantern lo consideran una especie de demonio...','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005861395-o6otb0.jpg','read',0,NULL,NULL,'2026-04-12 14:57:41','2026-04-12 16:12:45',228,NULL,'Grapa','[{"name":"Geoff Johns","role":""},{"name":"Tony Bedard","role":""},{"name":"Mike Choi","role":""},{"name":"Tyler Kirkham","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2050,'Green Lantern (2012-2022) #7','Green Lantern (2012-2022)',7,NULL,'978-8-415-62888-0',NULL,'Geoff Johns','Tony Bedard',NULL,NULL,'ECC Ediciones',NULL,'2012-11-01',NULL,NULL,replace('USA: Green Lantern Vol. 5 nº 07, Green Lantern New Guardians Vol. 1 nº 07\rHistorias: El secreto de la Tribu Índigo / Invictus\rHal Jordan ha vuelto a la Tierra tras ayudar a Sinestro a derrotar a sus antiguos acólitos, y ha decidido que quiere llevar una vida normal al lado de Carol Ferris. Mientras, el korugariano se enfrenta a la temible Lyssa Drak, cuyo libro le revela, entre otras cosas, que terminará siendo esclavo de la Tribu Índigo. Por su parte, Kyle Rayner y los demás agentes de los diversos Cuerpos que se encuentran en el Planetario se enfrentan sin éxito a Invictus, que según Larfleeze está detrás de los últimos acontecimientos.','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005863405-mmqy1u.jpg','read',0,NULL,NULL,'2026-04-12 14:57:44','2026-04-12 16:12:45',228,NULL,'Grapa','[{"name":"Geoff Johns","role":""},{"name":"Tony Bedard","role":""},{"name":"Doug Mahnke","role":""},{"name":"Tyler Kirkham","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2051,'Green Lantern (2012-2022) #8','Green Lantern (2012-2022)',8,NULL,'978-8-415-74807-6',NULL,'Geoff Johns','Tony Bedard',NULL,NULL,'ECC Ediciones',NULL,'2012-11-01',NULL,NULL,replace('USA: Green Lantern Vol. 5 nº 08, Green Lantern New Guardians Vol. 1 nº 08\rHistorias: El secreto de la Tribu Índigo (parte 2) / ¡... Arkillo triunfante!\rSinestro ha vuelto a la Tierra para avisar a Hal Jordan de que los Guardianes han decidido sustituir al Cuerpo de Green Lanterns por otro ejército. Aunque el terrícola no tiene intención de ayudar a su eterno enemigo, ambos se ven envueltos en una nueva aventura cuando la Tribu Índigo los secuestra. Mientras tanto, en el Planetario, Kyle Rayner ha averiguado que Larfleeze los ha manipulado a sus aliados y a él, ya que el “arcángel” llamado Invictus no es más que una víctima de la avaricia del Orange Lantern.','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005865432-77hzs1.jpg','read',0,NULL,NULL,'2026-04-12 14:57:46','2026-04-12 16:12:45',228,NULL,'Grapa','[{"name":"Geoff Johns","role":""},{"name":"Tony Bedard","role":""},{"name":"Doug Mahnke","role":""},{"name":"Tyler Kirkham","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2052,'Green Lantern (2012-2022) #9','Green Lantern (2012-2022)',9,NULL,'978-8-415-74834-2',NULL,'Geoff Johns','Tony Bedard',NULL,NULL,'ECC Ediciones',NULL,'2013-01-01',NULL,NULL,replace('USA: Green Lantern Vol. 5 nº 09, Green Lantern New Guardians Vol. 1 nº 09\rHistorias: El secreto de la Tribu Índigo (parte 3) / Más allá de la esperanza.\rLa Tribu Índigo intenta convertir a Sinestro mientras Hal Jordan escapa tras manipular a Mano Negra para recargar su anillo. Una vez se da a la fuga, el terrícola encuentra una estatua gigantesca de Abin Sur, que, al parecer, fue quien creó la Tribu. Por su parte, Invictus ha dejado libres a Kyle Rayner y a sus aliados con una condición: que maten a Larfleeze, su archienemigo. Pero los miembros del grupo se dispersan para atender otros asuntos como, en el caso de Arkillo, la posible desaparición de los Sinestro Corps.','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005867482-xdo779.jpg','read',0,NULL,NULL,'2026-04-12 14:57:48','2026-04-12 16:12:45',228,NULL,'Grapa','[{"name":"Geoff Johns","role":""},{"name":"Tony Bedard","role":""},{"name":"Doug Mahnke","role":""},{"name":"Tyler Kirkham","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2053,'Green Lantern (2012-2022) #10','Green Lantern (2012-2022)',10,NULL,'978-8-415-74859-5',NULL,'Geoff Johns','Tony Bedard',NULL,NULL,'ECC Ediciones',NULL,'2013-02-01',NULL,NULL,replace('USA: Green Lantern Vol. 5 nº 10, Green Lantern New Guardians Vol. 1 nº 10\rHistorias: El secreto de la Tribu Índigo (conclusión) / Más allá de la esperanza (conclusión)\rLa Tribu Índigo ha sometido a Sinestro, que rememora la muerte de la única mujer que ha amado. Mientras, Hal Jordan conoce a Natromo, el guardián de la luz de la compasión, que le cuenta que Abin Sur y él fundaron la Tribu utilizando como agentes a delincuentes que necesitaban redimirse. Por su parte, el Alcance ha invadido el planeta Odym, la sede de los Blue Lanterns, y Saint Walker y sus compañeros poco pueden hacer para evitarlo hasta que llegue algún Green Lantern. Por suerte, Kyle Rayne ya está de camino.','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005869475-5bsug1.jpg','read',0,NULL,NULL,'2026-04-12 14:57:50','2026-04-12 16:12:45',228,NULL,'Grapa','[{"name":"Geoff Johns","role":""},{"name":"Tony Bedard","role":""},{"name":"Doug Mahnke","role":""},{"name":"Tomas Giorello","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2054,'Green Lantern (2012-2022) #11','Green Lantern (2012-2022)',11,NULL,'978-8-415-74884-7',NULL,'Geoff Johns','Tony Bedard',NULL,NULL,'ECC Ediciones',NULL,'2013-03-01',NULL,NULL,replace('Contiene Green Lantern vol.5 #11, Green Lantern: New Guardians #11 USA\rHistorias: La venganza de Mano Negra (parte 1) / Operación Agente Orange\rLa destrucción de la Batería Central de la Tribu Índigo ha dejado libre a Mano Negra. Y cuando Natromo la reconstruye, el villano prefiere suicidarse a que el anillo violeta vuelva a apoderarse de su mente. Sin embargo, minutos después de morir, el terrícola regresa convertido en un Black Lantern que tiene muchas ganas de volver a su planeta natal. Por su parte, Saint Walker ha llegado a la conclusión de que Larfleeze animó al Alcance a atacar la base de los Blue Lanterns, y decide hacerle pagar por sus fechorías.','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005871826-gu6yxv.jpg','read',0,NULL,NULL,'2026-04-12 14:57:52','2026-04-12 16:12:45',228,NULL,'Grapa','[{"name":"Geoff Johns","role":""},{"name":"Tony Bedard","role":""},{"name":"Doug Mahnke","role":""},{"name":"Tyler Kirkham","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2055,'Green Lantern (2012-2022) #12','Green Lantern (2012-2022)',12,NULL,'978-8-415-84406-8',NULL,'Geoff Johns','Tony Bedard',NULL,NULL,'ECC Ediciones',NULL,'2013-04-01',NULL,NULL,replace(replace('Contiene Green Lantern vol.5 #12, Green Lantern Vol. 5 Annual nº 1, Green Lantern: New Guardians #12 USA\r\nHistorias: La venganza de Mano Negra (parte 2) / La Ascensión del Tercer Ejército (prólogo) / En nombre del amor.\r\nYa libre de la Tribu Índigo, Sinestro lleva a Hal Jordan a Korugar, donde tiene guardado el Libro Oscuro. El antiguo villano sabe que los Guardianes pretenden sustituir al Cuerpo de Green Lanterns por un Tercer Ejército; sin embargo, cuando buscan información en dicho volumen, ambos se transportan a la Tierra, donde se topan con Mano Negra, que ha “resucitado” a su difunta familia. Mientras tanto, Kyle Rayner y sus aliados se enfrentan por fi n a Larfl eeze, que mata a Glomulus por traidor justo antes de la llegada de Invictus.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005873870-wubnwl.jpg','read',0,NULL,NULL,'2026-04-12 14:57:54','2026-04-12 16:12:45',228,NULL,'Grapa','[{"name":"Geoff Johns","role":""},{"name":"Tony Bedard","role":""},{"name":"Ethan Van Sciver","role":""},{"name":"Tyler Kirkham","role":""},{"name":"Renato Guedes","role":""},{"name":"Jim Calafiore","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2056,'Green Lantern (2012-2022) #13','Green Lantern (2012-2022)',13,NULL,'978-8-415-84438-9',NULL,'Geoff Johns','Tony Bedard',NULL,NULL,'ECC Ediciones',NULL,'2013-05-01',NULL,NULL,replace('USA: Green Lantern vol.5 nº 13, Green Lantern: New Guardians Vol. 1 nº 13\rHistorias: Acciones y reacciones / Toda la rabia.\rLos Guardianes del Universo han creado un Tercer Ejército sin libre albedrío que pueden controlar a su antojo. Pero para que su plan tenga éxito, deben quitarse de encima a los Green Lanterns que consideran más peligrosos. Los primeros han sido Hal Jordan y Sinestro, a los que han hecho desaparecer con ayuda de Mano Negra. Mientras, en Detroit, a un joven musulmán llamado Simon Baz lo acusan de terrorismo debido a una confusión. En pleno interrogatorio, un anillo de poder lo convierte en el nuevo Green Lantern de la Tierra.','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005875719-opy3ea.jpg','read',0,NULL,NULL,'2026-04-12 14:57:56','2026-04-12 16:12:45',228,NULL,'Grapa','[{"name":"Geoff Johns","role":""},{"name":"Tony Bedard","role":""},{"name":"Andrei Bressan","role":""},{"name":"Doug Mahnke","role":""},{"name":"Amilcar Pinna","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2057,'Green Lantern (2012-2022) #14','Green Lantern (2012-2022)',14,NULL,'978-8-415-84464-8',NULL,'Geoff Johns','Tony Bedard',NULL,NULL,'ECC Ediciones',NULL,'2013-05-01',NULL,NULL,replace('USA: Green Lantern vol.5 nº 14, Green Lantern: New Guardians Vol. 1 nº 14\rHistorias: Coraje / Factor Miedo\rLos Guardianes del Universo se han propuesto dominar el cosmos por medio del Tercer Ejército, unos soldados sin voluntad propia que han llegado a la Tierra justo cuando nuestro planeta cuenta con un Green Lantern novato llamado Simon Baz que huye del gobierno de Estados Unidos. Por su parte, Kyle Rayner y Carol Ferris deciden derrotar a los Guardianes para liberar a Ganthet y a Hal Jordan. La única forma de lograrlo es que Kyle aprenda a canalizar todos los colores del espectro emocional, lo cual no va a resultar sencillo.','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005877353-jazi10.jpg','read',0,NULL,NULL,'2026-04-12 14:57:57','2026-04-12 16:12:45',228,NULL,'Grapa','[{"name":"Geoff Johns","role":""},{"name":"Tony Bedard","role":""},{"name":"Andrei Bressan","role":""},{"name":"Doug Mahnke","role":""},{"name":"Amilcar Pinna","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2058,'Green Lantern (2012-2022) #15','Green Lantern (2012-2022)',15,NULL,'978-8-415-84491-4',NULL,'Geoff Johns','Tony Bedard',NULL,NULL,'ECC Ediciones',NULL,'2013-06-01',NULL,NULL,replace('USA: Green Lantern vol.5 nº 15, Green Lantern: New Guardians Vol. 1 nº 15\rHistorias: Vidas Inocentes / Necesidad de codicia\rLas acusaciones de terrorismo que pesan sobre Simon Baz, el nuevo Green Lantern de la Tierra, llevan a la Liga de la Justicia a pedirle explicaciones. La discusión culmina en una batalla de la que el novato se zafa como puede. Mientras tanto, Mano Negra aparece en la Cámara de las Sombras, donde queda encerrado junto a los Guardianes cautivos. Por su parte, Kyle Rayner y Carol Ferris reclutan a Arkillo para su causa. Ahora, Kyle debe aprender a dominar la luz naranja de la avaricia... si Larfleeze no lo impide.','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005879199-0ovl4n.jpg','read',0,NULL,NULL,'2026-04-12 14:57:59','2026-04-12 16:12:45',228,NULL,'Grapa','[{"name":"Geoff Johns","role":""},{"name":"Tony Bedard","role":""},{"name":"Doug Mahnke","role":""},{"name":"Aaron Kuder","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2059,'Green Lantern (2012-2022) #16','Green Lantern (2012-2022)',16,NULL,'978-8-415-92511-8',NULL,'Geoff Johns','Tony Bedard',NULL,NULL,'ECC Ediciones',NULL,'2013-07-01',NULL,NULL,replace('USA: Green Lantern vol.5 nº 16, Green Lantern: New Guardians Vol. 1 nº 16\rHistorias: Prueba de fuego / Que reine el amor.\rMientras un aliado encapuchado comunica a Hal Jordan y Sinestro que están muertos, Simon Baz encuentra al responsable de los hechos que condujeron a su detención por terrorismo, una revelación que coincide con el ataque del Tercer Ejército y con la llegada de B’dg, el Green Lantern con cuerpo de ardilla. Por su parte, Kyle Rayner ha aprendido a dominar la luz naranja de la avaricia y está más cerca de lograr su objetivo, pero lo entretienen los nuevos siervos de los Guardianes, cuyo ataque culmina con la muerte de Sayd.','\r',char(13)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005880799-7470cs.jpg','read',0,NULL,NULL,'2026-04-12 14:58:01','2026-04-12 16:12:45',228,NULL,'Grapa','[{"name":"Geoff Johns","role":""},{"name":"Tony Bedard","role":""},{"name":"Doug Mahnke","role":""},{"name":"Aaron Kuder","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2060,'Green Lantern (2012-2022) #17','Green Lantern (2012-2022)',17,NULL,'978-8-415-92532-3',NULL,'Geoff Johns','Peter J. Tomasi',NULL,NULL,'ECC Ediciones',NULL,'2013-08-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Green Lantern vol.5 núm. 17 USA, Green Lantern Corps vol.3 núm. 17 USA, Green Lantern: New Guardians núm. 17 USA, Red Lanterns núm. 17 USA\r\nUna vez descubierto su plan de erradicar el libre albedrío con ayuda del Tercer Ejército, los Guardianes del Universo deben enfrentarse a sus antiguos pupilos. Entre ellos se encuentra Kyle Rayner, recientemente convertido en White Lantern tras aprender a controlar todos los colores del espectro emocional. Abrumados por su poder, los Guardianes deciden utilizar todo el poder que queda en Volthoom, el Primer Lantern, pero este aprovecha la ocasión para liberarse por fin... y ahora pretende conquistar el universo.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005883093-cc5rx7.jpg','read',0,NULL,NULL,'2026-04-12 14:58:03','2026-04-12 16:12:45',228,NULL,'Grapa','[{"name":"Geoff Johns","role":""},{"name":"Peter J. Tomasi","role":""},{"name":"Peter Milligan","role":""},{"name":"Tony Bedard","role":""},{"name":"Dan Jurgens","role":""},{"name":"Doug Mahnke","role":""},{"name":"Fernando Pasarín","role":""},{"name":"Miguel Ángel Sepúlveda","role":""},{"name":"Phil Jimenez","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2061,'Green Lantern (2012-2022) #18','Green Lantern (2012-2022)',18,NULL,'978-8-415-92566-8',NULL,'Geoff Johns','Hendry Prasetya',NULL,NULL,'ECC Ediciones',NULL,'2013-10-01',NULL,NULL,replace(replace('Contiene Green Lantern vol.5 #18 USA, Green Lantern Corps vol.3 #18 USA, Green Lantern: New Guardians #18 USA y Red Lanterns #18 USA \r\nCon la intención de recuperar sus poderes emocionales, Volthoom, también conocido como el Primer Lantern, está torturando a los miembros de los diversos cuerpos obligándoles a experimentar versiones alternativas de sus vidas. Por ahora, sus víctimas son Kyle Rayner y Guy Gardner, pero pronto habrá muchas más. Mientras tanto, la intervención de Mano Negra lleva a Simon Baz al reino oscuro donde están encerrados Hal Jordan y Sinestro. ¿Será el principio del regreso de nuestros protagonistas?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005884871-124ymc.jpg','read',0,NULL,NULL,'2026-04-12 14:58:05','2026-04-12 16:12:45',228,NULL,'Grapa','[{"name":"Geoff Johns","role":""},{"name":"Peter J. Tomasi","role":""},{"name":"Tony Bedard","role":""},{"name":"Peter Milligan","role":""},{"name":"Szymon Kudranski","role":""},{"name":"Ardian Syaf","role":""},{"name":"Chris Cross","role":""},{"name":"Jim Calafiore","role":""},{"name":"Javier Pulido","role":""},{"name":"Miguel Ángel Sepúlveda","role":""},{"name":"Hendry Prasetya","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2062,'Green Lantern (2012-2022) #19','Green Lantern (2012-2022)',19,NULL,'978-8-415-92589-7',NULL,'Geoff Johns','Tony Bedard',NULL,NULL,'ECC Ediciones',NULL,'2013-11-01',NULL,NULL,replace(replace('Contiene Green Lantern vol.5 #19 USA, Green Lantern Corps vol.3 #19 USA, Green Lantern: New Guardians #19 USA, Red Lanterns #19 USA\r\nSimon Baz ha llegado a la Zona Muerta para advertir a Hal Jordan de los planes de Volthoom, que ha atormentado a John Stewart, Carol Ferris, Atrocitus y otros representantes del espectro emocional. No obstante, Sinestro se las arregla para quitarles el anillo y regresar al mundo de los vivos. Ahora, Jordan se enfrenta a una difícil decisión. La única vez que alguien ha conseguido escapar de la Zona Muerta fue durante la noche más oscura. Así pues, si quiere escapar, solo puede hacer una cosa.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005886451-xpdgdf.jpg','read',0,NULL,NULL,'2026-04-12 14:58:06','2026-04-12 16:12:45',228,NULL,'Grapa','[{"name":"Geoff Johns","role":""},{"name":"Tony Bedard","role":""},{"name":"Peter J. Tomasi","role":""},{"name":"Peter Milligan","role":""},{"name":"Ardian Syaf","role":""},{"name":"Szymon Kudranski","role":""},{"name":"Fernando Pasarín","role":""},{"name":"Andrés Guinaldo","role":""},{"name":"Will Conrad","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2063,'Green Lantern (2012-2022) #20','Green Lantern (2012-2022)',20,NULL,'978-8-415-99016-1',NULL,'Justin Jordan','Rafael Albuquerque',NULL,NULL,'ECC Ediciones',NULL,'2013-11-28',NULL,NULL,replace(replace('Contiene: Green Lantern núm. 21 USA y Green Lantern: New Guardians núm. 21 USA.\r\nVolthoom, también conocido como el Primer Lantern, puso en jaque a los Guardianes del Universo, a los Green Lanterns y al resto de cuerpos del espectro emocional. Sin embargo, la intervención de Sinestro, que ha recuperado el poder amarillo del miedo, y también de un Hal Jordan convertido temporalmente en Black Lantern, culminó en la derrota del villano y en un cúmulo de cambios en el Cuerpo de Green Lanterns. Y es que, ahora que los Guardianes ya no están, ha llegado el momento de emprender una nueva etapa.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005887956-v6flon.jpg','read',0,NULL,NULL,'2026-04-12 14:58:08','2026-04-12 16:12:45',228,NULL,'Grapa','[{"name":"Justin Jordan","role":""},{"name":"Robert Venditti","role":""},{"name":"Billy Tan","role":""},{"name":"Brad Walker","role":""},{"name":"Rafael Albuquerque","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2064,'Green Lantern (2012-2022) #21','Green Lantern (2012-2022)',21,NULL,'978-8-415-99047-5',NULL,'Justin Jordan','Rafael Albuquerque',NULL,NULL,'ECC Ediciones',NULL,'2013-12-01',NULL,NULL,replace(replace('Mientras una negra sombra se cierne sobre Oa, los Guardianes Templarios confían a Hal Jordan la reconstrucción del Cuerpo de Green Lanterns, un cargo con el que no se siente demasiado cómodo. Una de sus primeras decisiones es encomendar a Kyle Rayner, que ahora domina todas las energías del espectro emocional, que acompañe a esos nuevos Guardianes en un viaje a la Anomalía. Se trata de un vestigio de un universo anterior del que, tras un lamentable incidente, surge un ser que no debe de tener muy buenas intenciones.\r\nContiene: Green Lantern núm. 22 USA y Green Lantern: New Guardians núm. 22 USA.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005889822-kqs9iv.jpg','read',0,NULL,NULL,'2026-04-12 14:58:10','2026-04-12 16:12:45',228,NULL,'Grapa','[{"name":"Justin Jordan","role":""},{"name":"Robert Venditti","role":""},{"name":"Billy Tan","role":""},{"name":"Brad Walker","role":""},{"name":"Rafael Albuquerque","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2065,'Green Lantern (2012-2022) #22','Green Lantern (2012-2022)',22,NULL,'978-8-415-99077-2',NULL,'Robert Venditti','Billy Tan',NULL,NULL,'ECC Ediciones',NULL,'2014-01-31',NULL,NULL,replace(replace('Mientras Hal Jordan y sus nuevos reclutas se ocupaban de frenar el ataque de Larfleeze, algo ocurrió en las celdas científicas. La peligrosa reclusa Nol-Anj escapó tras engañar a uno de los guardias haciéndole creer que estaba enamorada de él... e incluso contó con la ayuda de un anillo de las Zafiros Estelares. Mientras tanto, Kyle Rayner sobrevivió al primer encuentro con Relic, un gigante espacial cuyo objetivo ya se conoce: destruir los anillos de poder. Pero ¿cuál será su siguiente paso?\r\nContiene: Green Lantern núm. 23 USA y Green Lantern: New Guardians núm. 23 USA','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005891808-w3gz14.jpg','read',0,NULL,NULL,'2026-04-12 14:58:12','2026-04-12 16:12:45',228,NULL,'Grapa','[{"name":"Robert Venditti","role":""},{"name":"Billy Tan","role":"Dibujo"},{"name":"Brad Walker","role":""},{"name":"Rafael Albuquerque","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2066,'Green Lantern (2012-2022) #23','Green Lantern (2012-2022)',23,NULL,'978-8-416-07011-4',NULL,'Robert Venditti','Rags Morales',NULL,NULL,'ECC Ediciones',NULL,'2014-03-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Green Lantern núms. 23.1 y 23.2 USA \r\nLos Guardianes Templarios se llevaron a Kyle Rayner, que actualmente ostenta la luz de todos los colores del espectro emocional, a investigar un objeto situado en los confines del espacio. Allí conocieron a Relic, un gigante de inmenso poder que se ha propuesto suprimir a todos los ejércitos de portadores del anillo. Sus primeras víctimas han sido Saint Walker y los Blue Lanterns, y la guerra ya se ha convertido en inevitable. Y ahora ha llegado el momento de conocer el origen del implacable villano.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776005894300-yyf6u8.jpg','read',0,NULL,NULL,'2026-04-12 14:58:15','2026-04-12 16:12:45',228,NULL,'Grapa','[{"name":"Robert Venditti","role":"Guion"},{"name":"Jim Starlin","role":"Guion"},{"name":"Rags Morales","role":"Dibujo, Tinta"},{"name":"Howard Porter","role":"Dibujo, Tinta"},{"name":"Cam Smith","role":"Tinta"},{"name":"Andrew Dalhouse","role":"Color"},{"name":"Billy Tan","role":"Dibujo, Tinta"},{"name":"Alex Sinclair","role":"Color"},{"name":"Hi-Fi Desing","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2067,'Wonder Woman Saga #5','Wonder Woman Saga',5,NULL,'978-8-418-47572-6',NULL,'Tim Seeley','Christian Duce',NULL,NULL,'ECC Ediciones',NULL,'2021-01-19',NULL,NULL,replace('EDICIÓN ORIGINAL: Wonder Woman núms. 26-37 USA, Wonder Woman: Steve Trevor núm. 1 USA (one-shot)\rEs la mejor guerrera de la historia del mundo, una guardiana de la paz y la justicia que ostenta el poder de una diosa. Pero incluso Diana de Themyscira, más conocida como Wonder Woman, tiene derecho a un pequeño descanso... solo que cuando asiste a una boda en compañía de Etta Candy, su mejor amiga, se arma un buen lío. Una chiflada causa estragos en el banquete y provoca una guerra abierta en busca del recurso más valioso que Diana posee: su ADN de amazona, que podría ser una cura milagrosa o un arma apocalíptica.\rPor si fuera poco, hace poco, se enteró de que tenía un hermano gemelo, expulsado de Themyscira al amparo de la noche. El misterioso Jason, el único varón nacido en la isla, ha estado escondido de humanos y de dioses, pero su vida y la de Wonder Woman están a punto de cruzarse de forma terrorífica.\rAntes de desentrañar ese secreto, Diana afronta el regreso de Grail, que está buscando a los medio hermanos de nuestra heroína, es decir, a los descendientes de Zeus. Cuando muere cada semidiós, su energía se transmite al padre y amo de Grail, que no es otro que un renacido Darkseid, el letal señor de Apokolips. Ante semejante amenaza, ¿luchará Jason al lado de su hermana? ¿O será leal al otro bando?','\r',char(13)),NULL,NULL,168,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006273726-9093jp.jpg','unread',0,NULL,NULL,'2026-04-12 15:04:36','2026-04-12 15:04:36',229,NULL,NULL,'[{"name":"Tim Seeley","role":"Guion"},{"name":"Shea Fontana","role":"Guion"},{"name":"James Robinson","role":"Guion"},{"name":"Christian Duce","role":"Dibujo, Tinta"},{"name":"Mirka Andolfo","role":"Dibujo, Tinta"},{"name":"David Messina","role":"Dibujo, Tinta"},{"name":"Iñaki Miranda","role":"Dibujo, Tinta"},{"name":"Carlo Pagulayan","role":"Dibujo"},{"name":"Sergio Dávila","role":"Dibujo"},{"name":"Emanuela Lupacchino","role":"Dibujo"},{"name":"Stephen Segovia","role":"Dibujo"},{"name":"Sean Parsons","role":"Tinta"},{"name":"Jason Paz","role":"Tinta"},{"name":"Scott Hanna","role":"Tinta"},{"name":"Mark Morales","role":"Tinta"},{"name":"Ray McCarthy","role":"Tinta"},{"name":"Mick Gray","role":"Tinta"},{"name":"Eber Ferreira","role":"Tinta"},{"name":"Art Thibert","role":"Tinta"},{"name":"Raúl Fernandez","role":"Tinta"},{"name":"Allen Passalaqua","role":"Color"},{"name":"Romulo Fajardo Jr.","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2068,'Wonder Woman Saga #7','Wonder Woman Saga',7,NULL,'978-8-418-93176-5',NULL,'James Robinson','Stephen Segovia',NULL,NULL,'ECC Ediciones',NULL,'2021-11-09',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Wonder Woman núms. 46-50, Wonder Woman Annual núm. 2 USA\r\nSe acerca una nueva horda de deidades letales que están dejando un sendero de perdición y destrucción por todo el cosmos. Son los dioses forjados en los fuegos del Multiverso Oscuro y se dirigen a la Tierra, donde no nos quedará más remedio que postrarnos... o morir.\r\nPero Wonder Woman, si lo puede evitar, no piensa hacer eso.\r\nA fin de derrotar a estos terroríficos intrusos, Diana no se detendrá ante nada. Recurrirá a los dioses griegos que le concedieron sus increíbles poderes y se marchará al espacio, donde blandirá la luz violeta de las Zafiros Estelares contra sus enemigos.\r\nMientras tanto, en la Tierra, los principales héroes están cayendo de uno en uno, y solo queda Jason, el hermano de Diana, para hacer frente a la horda. ¿Conseguirán la princesa de las amazonas y este poderoso joven truncar el reinado del terror de los Dioses Oscuros? ¿O habrá llegado la hora de que Wonder Woman se suma en las tinieblas?\r\nAverígualo en Wonder Woman: Los dioses oscuros de la mano del guionista James Robinson y dibujantes de la talla de Stephen Segovia o Jesús Merino en una historia surgida del éxito de Noches oscuras: Metal. Recopila Wonder Woman núms. del 46 al 50 y Wonder Woman Annual núm. 2.','\r',char(13)),'\n',char(10)),NULL,NULL,168,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006299193-jua3gb.jpg','unread',0,NULL,NULL,'2026-04-12 15:05:00','2026-04-12 15:05:00',229,NULL,'Cartoné 168 pp','[{"name":"James Robinson","role":"Guion"},{"name":"Stephen Segovia","role":"Dibujo, Tinta"},{"name":"Rick Leonardi","role":"Dibujo"},{"name":"Jesús Merino","role":"Dibujo, Tinta"},{"name":"Frazer Irving","role":"Color"},{"name":"Emanuela Lupacchino","role":"Dibujo"},{"name":"Marc Laming","role":"Dibujo, Tinta"},{"name":"Jim Calafiore","role":"Dibujo, Tinta"},{"name":"Andy Owens","role":"Tinta"},{"name":"Ray McCarthy","role":"Tinta"},{"name":"Romulo Fajardo Jr.","role":"Color"},{"name":"David Baron","role":"Color"},{"name":"Allen Passalaqua","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2069,'Wonder Woman Saga #8','Wonder Woman Saga',8,NULL,'978-8-412-47092-5',NULL,'Brenden Fletcher','Fabio Moon',NULL,NULL,'ECC Ediciones',NULL,'2022-02-08',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Wonder Woman núms. 51-55, Wonder Woman 75Th Anniversary Special, Justice League Giant núms. 1-2 USA\r\nWonder Woman y Artemisa nunca se han llevado bien. Estas eternas rivales, las máximas representantes de las amazonas de Themyscira y las de Bana-Mighdall, ahora deben unir fuerzas con Aztek para rescatar a una hermana desaparecida y enfrentarse a una divinidad enfurecida. Y lo peor es que, una vez pasado el peligro, el regreso a Bana-Mighdall será de todo excepto pacífico...\r\nEl guionista Steve Orlando y el dibujante ACO se encargan de la historia central de este volumen, que también incluye el contenido del especial que conmemora el 75 aniversario de Diana. En él, rinden homenaje a la heroína autores tan destacados como Rafael Albuquerque, Liam Sharp o Karl Kerschl, y la mismísima Lois Lane entrevista a nuestra protagonista para que la conozcamos mejor. Y además, dos relatos inéditos que se publicaron originalmente en Justice League Giant núms. 1 y 2, escritos por Tim Seeley (Grayson) y dibujados por Rick Leonardi y Felipe Watanabe.','\r',char(13)),'\n',char(10)),NULL,NULL,168,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006302372-h22ox9.jpg','unread',0,NULL,NULL,'2026-04-12 15:05:03','2026-04-12 15:05:03',229,NULL,'Cartoné 168 pp','[{"name":"Brenden Fletcher","role":"Guion"},{"name":"Fabio Moon","role":"Guion, Dibujo"},{"name":"Gail Simone","role":"Guion"},{"name":"Greg Rucka","role":"Guion"},{"name":"Hope Larson","role":"Guion"},{"name":"Jill Thompson","role":"Guion, Dibujo"},{"name":"Karl Kerschl","role":"Guion, Dibujo"},{"name":"Liam Sharp","role":"Guion, Dibujo"},{"name":"Mairghread Scott","role":"Guion"},{"name":"Marguerite Bennett","role":"Guion, Dibujo"},{"name":"Rafael Albuquerque","role":"Guion, Dibujo"},{"name":"Rafael Scavone","role":"Guion"},{"name":"Renae De Liz","role":"Guion, Dibujo"},{"name":"Steve Orlando","role":"Guion"},{"name":"Tim Seeley","role":"Guion"},{"name":"Aco","role":"Dibujo"},{"name":"Colleen Doran","role":"Dibujo"},{"name":"Felipe Watanabe","role":"Dibujo"},{"name":"Laura Braga","role":"Dibujo"},{"name":"Patricia Martin","role":"Dibujo"},{"name":"Ramón F. Bachs","role":"Dibujo"},{"name":"Rick Leonardi","role":"Dibujo"},{"name":"Riley Rossmo","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2070,'Wonder Woman Saga #6','Wonder Woman Saga',6,NULL,'978-8-418-74224-8',NULL,'James Robinson','Emanuela Lupacchino',NULL,NULL,'ECC Ediciones',NULL,'2021-06-01',NULL,NULL,replace(replace('EDICION ORIGINAL: Wonder Woman núms. 38-45 USA y Dog Days of Summer núm. 1 USA (extracto Barbecue season)\r\nDarkseid está decidido a recuperar el trono de Apokolips, pero necesita el poder que alberga Themyscira, que ha quedado completamente aislada de la Tierra. Y ya sabemos que Darkseid siempre se sale con la suya. Así pues, las Furias Femeninas y Grail, la hija del tirano, se han repartido por el mundo a fin de encontrar unos artefactos capaces de abrir los puertas de Isla Paraíso. Sin embargo, dichos objetos están en manos de Wonder Woman y de Jason, el misterioso hermano cuya existencia desconocía hasta hace poco.\r\nPor si fuera poco, andan sueltas unas deidades oscuras que están sembrando el caos y la destrucción. Se trata de los Dioses Oscuros forjados en las fraguas del Multiverso Oscuro. Su próximo destino es la Tierra, que deberá postrarse o perecer.\r\nA menos que Wonder Woman consiga evitarlo.\r\nY Diana no se detendrá ante nada con tal de vencer a tan terroríficos intrusos. Recurrirá a los dioses griegos que le otorgaron sus increíbles habilidades... e incluso se lanzará al espacio para blandir la luz violeta de los Zafiros Estelares contra sus enemigos.','\r',char(13)),'\n',char(10)),NULL,NULL,168,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006309713-ytyvxv.jpg','unread',0,NULL,NULL,'2026-04-12 15:05:10','2026-04-12 15:05:10',229,NULL,'Cartoné 168 pp','[{"name":"James Robinson","role":"Guion"},{"name":"G. Willow Wilson","role":"Guion"},{"name":"Emanuela Lupacchino","role":"Dibujo"},{"name":"Carmen Carnero","role":"Dibujo, Tinta"},{"name":"Stephen Segovia","role":"Dibujo, Tinta"},{"name":"Jesús Merino","role":"Dibujo, Tinta"},{"name":"Marco Santucci","role":"Dibujo, Tinta"},{"name":"Stjepan Šejić","role":"Dibujo, Tinta, Color"},{"name":"Ray McCarthy","role":"Tinta"},{"name":"Romulo Fajardo Jr.","role":"Color"},{"name":"Hi-Fi Desing","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2071,'Grandes Autores de Liga de la Justicia: Keith Giffen, J.M. Dematteis y Kevin Maguire - JLI #1','Grandes Autores de Liga de la Justicia: Keith Giffen, J.M. Dematteis y Kevin Maguire - JLI',1,NULL,'978-8-417-20640-6',NULL,'J.M. DeMatteis','Kevin Maguire',NULL,NULL,'ECC Ediciones',NULL,'2017-10-03',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Justice League núms. 1-6 USA (1987), Justice League International núm. 7 USA\r\nARGUMENTO: Justo después de una crisis internacional, cobra protagonismo una generación nueva de los Mejores Superhéroes del Mundo. ¡Pero es el equipo más improbable que quepa imaginar! ¡Batman, Blue Beetle, el Detective Marciano, Guy Gardner, Canario Negro, Mr. Milagro, el Dr. Destino, Booster Gold, la Dra. Luz y el poder de Shazam! ¿Podrá este grupo tan heterogéneo funcionar como una sola unidad para detener a unos terroristas en Naciones Unidas, a una brigada de Rocket Reds, a la Royal Flush Gang, al misterioso Hombre Gris y a más amenazas… o sucumbirá a las peleas internas y los chistes malos?','\r',char(13)),'\n',char(10)),NULL,NULL,200,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006335390-d4on5u.jpg','unread',0,NULL,NULL,'2026-04-12 15:05:38','2026-04-12 15:05:38',230,20.5,NULL,'[{"name":"J.M. DeMatteis","role":"Guion"},{"name":"Keith Giffen","role":"Guion"},{"name":"Kevin Maguire","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2072,'Grandes Autores de Liga de la Justicia: Keith Giffen, J.M. Dematteis y Kevin Maguire - JLI #2','Grandes Autores de Liga de la Justicia: Keith Giffen, J.M. Dematteis y Kevin Maguire - JLI',2,NULL,'978-8-417-72201-2',NULL,'J.M. DeMatteis','Keith Giffen',NULL,NULL,'ECC Ediciones',NULL,'2019-01-04',NULL,NULL,replace(replace('Contiene Justice League núms. 8-13 USA, Suicide Squad núm. 13 USA, Justice League Annual núm. 1 USA (one-shot).\r\n¡Los Mejores Superhéroes del Mundo, la Liga de la Justicia, han renunciado a la coletilla “de América” en su nombre y ahora gozan de estatus internacional! ¡Pero es el grupo de superhéroes más inesperado que jamás veréis! Batman, Blue Beetle, el Detective Marciano, Canario Negro, Guy Gardner, Mr. Milagro y Booster Gold ven unirse a sus filas al representante de los EE.UU., el Capitán Átomo, y al de la URSS, Rocket Red. Pero... ¿puede esta tropa funcionar como un equipo eficaz e impedir un incidente internacional mientras detiene las amenazas robóticas de los Manhunters y el Constructo? ¿Y cuál es el impactante secreto de su misterioso benefactor, Maxwell Lord?\r\n¡Continuamos acompañando a estos maestros del arte de contar historias, Keith Giffen, J.M. DeMatteis y Kevin Maguire, en su apreciada etapa de aventuras hilarantes y llenas de acción, que redefinió el concepto de grupo superheroico! ¡Este segundo volumen, además, cuenta con el talento de Bill Willingham, John Ostrander y Luke McDonnell.','\r',char(13)),'\n',char(10)),NULL,NULL,200,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006342725-zzqasf.jpg','unread',0,NULL,NULL,'2026-04-12 15:05:44','2026-04-12 15:05:44',230,20.5,'Cartoné 200 pp','[{"name":"J.M. DeMatteis","role":"Guion"},{"name":"John Ostrander","role":"Guion"},{"name":"Keith Giffen","role":"Guion, Dibujo"},{"name":"Bill Willingham","role":"Dibujo"},{"name":"Kevin Maguire","role":"Dibujo"},{"name":"Luke McDonnell","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2073,'Batman: Más oscuro que la muerte','Batman: Más oscuro que la muerte',NULL,NULL,'978-8-415-84458-7',NULL,'Bruce Jones','Ariel Olivetti',NULL,NULL,'ECC Ediciones',NULL,'2013-05-01',NULL,NULL,replace(replace('USA: Batman: Legends of the Dark Knight Vol. 1 nº 207 - 211\r\nCuando está a punto de contraer matrimonio con un miembro de la adinerada familia Billingsworth, secuestran a la joven Janie Rutledge,y sus captores exigen el desembolso de un millón de dólares en concepto de rescate. El caso, aparentemente sencillo deresolver para el Hombre Murciélago, adquiere una nueva dimensión cuando este incumple una de susmáximas: no implicarse emocionalmente...\r\nOriginalmente serializada en la cabecera Batman: Legends of the DarkKnight, Batman: Más oscuro que la muerte sirve a Bruce Jones y Ariel Olivetti para retomar temas clásicos en la mitología del personaje, centrándose en su naturaleza dual, la dificultad de mantener el equilibrio entre las dos facetas de su vida y la tentación de buscar la felicidad endetrimento de su cruzada contra el crimen.','\r',char(13)),'\n',char(10)),NULL,NULL,128,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006365300-j3r5b6.jpg','unread',0,NULL,NULL,'2026-04-12 15:06:07','2026-04-12 15:06:07',NULL,11.99,'lujo','[{"name":"Bruce Jones","role":"Guion"},{"name":"Ariel Olivetti","role":"Dibujo, Tinta, Color"},{"name":"Mauro Cascioli","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2074,'Batman: Espiral interminable','Batman: Espiral interminable',NULL,NULL,'978-8-416-71198-7',NULL,'Kevin Smith','Walter Flanagan',NULL,NULL,'ECC Ediciones',NULL,'2016-05-27',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman: The Widening Gyre #1-6 USA.\r\nEl aclamado equipo creativo formado por el director y guionista Kevin Smith (Green Arrow de Kevin Smith) y el dibujante Walter Flanagan examinan en profundidad del mayor héroe de Gotham, quien afronta grandes cambios en su vida: la irrupción de un posible aliado en la lucha contra el crimen, y el regreso de su gran amor','\r',char(13)),'\n',char(10)),NULL,NULL,200,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006379909-68wthb.jpg','unread',0,NULL,NULL,'2026-04-12 15:06:20','2026-04-12 15:06:20',NULL,19.95,NULL,'[{"name":"Kevin Smith","role":"Guion"},{"name":"Walter Flanagan","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2075,'Superman Saga de Brian Michael Bendis #2','Superman Saga de Brian Michael Bendis',2,NULL,'978-8-412-47091-8',NULL,'Brian Michael Bendis','Ivan Reis',NULL,NULL,'ECC Ediciones',NULL,'2022-02-08',NULL,NULL,replace(replace('EDICION ORIGINAL: Superman 1-6 USA .\r\nSuperman se siente solo. Lois y Jon se han marchado al espacio en una compañía no muy recomendable, y ahora nuestro héroe debe refugiarse en su trabajo. Por suerte o por desgracia, no le faltarán quebraderos de cabeza cuando la propia Tierra termine metida en la Zona Fantasma, la extraña dimensión donde Krypton encerraba a sus delincuentes cuando dicho planeta aún existía. Con semejante panorama, ¿podrán Superman, la Liga de la Justicia y Adam Strange solucionar un problema potencialmente catastrófico?','\r',char(13)),'\n',char(10)),NULL,NULL,248,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006415192-waa6e2.jpg','unread',0,NULL,NULL,'2026-04-12 15:06:58','2026-04-12 15:06:58',231,19.95,'cartone','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Ivan Reis","role":"Dibujo"},{"name":"Joe Prado","role":"Tinta"},{"name":"Oclair Albert","role":"Tinta"},{"name":"Alex Sinclair","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2076,'Superman Saga de Brian Michael Bendis #1','Superman Saga de Brian Michael Bendis',1,NULL,'978-8-418-93175-8',NULL,'Brian Michael Bendis','Jim Lee',NULL,NULL,'ECC Ediciones',NULL,'2021-11-09',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: The Man of Steel núms. 1-6 USA, Action Comics núm. 1000 USA (Extracto El Hombre de Acero), DC Nation núm. 0 USA (extracto El Hombre de Acero)\r\nHa llegado a la Tierra un monstruo de inmenso poder. Se llama Rogol Zaar y se ha propuesto terminar una misión que emprendió hace años. Y para eso, necesita matar tanto a Superman como a Supergirl, los últimos kryptonianos que quedan vivos. Este nuevo enemigo no podría llegar en peor momento, ya que el Hombre de Acero está inquieto por un asunto personal. Su padre, el científico Jor-El, dado por muerto durante décadas, regresó recientemente de entre los muertos. Y ahora, ha pedido a Superboy que lo acompañe a un viaje por el universo... y la respuesta del pequeño Jon no podría haber sido más entusiasta.\r\nBrian Michael Bendis, uno de los guionistas más influyentes del cómic estadounidense del siglo XXI, llegó a DC Comics hace unos años para ocuparse de las aventuras de Superman empezando por una saga inaugural titulada El Hombre de Acero en la que contó con dibujantes de la talla de Jim Lee, Ivan Reis, Kevin Maguire, Adam Hughes o el legendario José Luis García-López.','\r',char(13)),'\n',char(10)),NULL,NULL,248,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006421960-ed4yar.jpg','unread',0,NULL,NULL,'2026-04-12 15:07:02','2026-04-12 15:07:02',231,NULL,'cartone','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Jim Lee","role":"Dibujo"},{"name":"José Luis García-López","role":"Dibujo"},{"name":"Ivan Reis","role":"Dibujo"},{"name":"Jason Fabok","role":"Dibujo"},{"name":"Evan Shaner","role":"Dibujo"},{"name":"Steve Rude","role":"Dibujo"},{"name":"Ryan Sook","role":"Dibujo"},{"name":"Kevin Maguire","role":"Dibujo"},{"name":"Adam Hughes","role":"Dibujo, Color"},{"name":"Scott Williams","role":"Tinta"},{"name":"Dexter Vines","role":"Tinta"},{"name":"Joe Prado","role":"Tinta"},{"name":"Wade Von Grawbadger","role":"Tinta"},{"name":"Alex Sinclair","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2077,'Superman: Action Comics Saga Renacimiento #1','Superman: Action Comics Saga Renacimiento',1,NULL,'978-8-417-90868-3',NULL,'Dan Jurgens','Patrick Zircher',NULL,NULL,'ECC Ediciones',NULL,'2019-07-16',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Action Comics núms. 957-966 y Justice League núm. 52 USA\r\nFue el principal héroe del mundo. Y entonces, el mundo que conocía quedó borrado de la existencia. Superman escapó junto a su esposa y su hijo a una versión nueva y extraña de la Tierra donde operó en secreto mientras observaba cómo defendía el planeta un Hombre de Acero distinto, joven y menos experimentado. Aquel héroe joven murió, y ahora el Hombre de Acero original está preparado para dar un paso adelante y sustituirlo. Pero no está listo para lo que va a suceder.\r\nAprovechando la oportunidad de su vida, Lex Luthor se ha puesto una armadura de un poder increíble y se ha declarado el nuevo Superman. Además, acaba de aparecer en Metropolis un hombre que afirma ser Clark Kent. Y en medio de este caos, aterriza el peor enemigo al que Superman se haya enfrentado: Juicio Final.\r\nA fin de salvar Metropolis y a su familia de tan monstruosa amenaza, Superman debe unir fuerzas con Luthor, Wonder Woman y todos los aliados que encuentre... porque la amarga experiencia le dice cómo terminan las batallas contra Juicio Final. \r\nSendero de perdición recopila los números del 957 al 962 de la serie original Action Comics y reúne al legendario guionista Dan Jurgens con los dibujantes Patch Zircher, Tyler Kirkham, Stephen Segovia y Art Thibert para lanzar una nueva era del Hombre del Mañana.','\r',char(13)),'\n',char(10)),NULL,NULL,368,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006437621-xv5gc3.jpg','unread',0,NULL,NULL,'2026-04-12 15:07:22','2026-04-12 15:07:22',232,27,'Rústica','[{"name":"Dan Jurgens","role":"Guion"},{"name":"Patrick Zircher","role":"Dibujo, Tinta"},{"name":"Tyler Kirkham","role":"Dibujo, Tinta"},{"name":"Stephen Segovia","role":"Dibujo"},{"name":"Tom Grummett","role":"Dibujo"},{"name":"Art Thibert","role":"Tinta"},{"name":"Danny Miki","role":"Tinta"},{"name":"Mark Morales","role":"Tinta"},{"name":"Scott Hanna","role":"Tinta"},{"name":"Gabe Eltaeb","role":"Color"},{"name":"Tomeu Morey","role":"Color"},{"name":"Ulises Arreola","role":"Color"},{"name":"Arif Prianto","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2078,'Spawn / Batman','Spawn / Batman',NULL,NULL,'978-8-419-67835-5',NULL,'Frank Miller','Todd McFarlane',NULL,NULL,'ECC Ediciones',NULL,'2023-03-28',NULL,NULL,replace(replace('Contiene: Spawn/Batman USA (1994).\r\nUn nuevo peligro ha llegado a las calles de Gotham City, pero Batman no tarda en descubrir que esos robots que acaban de atacarlo ocultan un secreto bastante macabro. Decidido a investigar el caso, viaja a Nueva York, donde opera otro justiciero, un antiguo soldado y agente de la CIA que, tras morir, hizo un pacto con un demonio para regresar a la vida transformado en un ser llamado Spawn. Ahora, los dos hombres están condenados a entenderse aunque tengan formas muy distintas de entender la misión que se han encomendado a sí mismos.\r\nNo te pierdas esta aventura conjunta del Caballero Oscuro y Spawn que cuenta con un equipo creativo excepcional compuesto por nada menos que Frank Miller y Todd McFarlane.','\r',char(13)),'\n',char(10)),NULL,NULL,64,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006480679-cfxfi8.jpg','unread',0,NULL,NULL,'2026-04-12 15:08:01','2026-04-12 15:08:01',NULL,20,'grapa','[{"name":"Frank Miller","role":"Guion"},{"name":"Todd McFarlane","role":"Dibujo, Tinta"},{"name":"Steve Oliff","role":"Color"},{"name":"Olyoptics","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2079,'Batman / Spawn','Batman / Spawn',NULL,NULL,'978-8-419-67837-9',NULL,'Todd McFarlane','Greg Capullo',NULL,NULL,'ECC Ediciones',NULL,'2023-03-28',NULL,NULL,replace('Contiene: Batman/Spawn USA (2023).\rCuando Al Simmons regresó a la vida convertido en un enviado del Infierno, lo hizo con un sueño: volver a ver a su esposa. Ahora, ha llegado a Gotham City con la intención de buscar al hombre que posee el alma de Wanda, que no es otro que... ¿¡Batman!? Es evidente que alguien está manipulando a Spawn, pero ¿a quién beneficia que estos dos justicieros se enfrenten?','\r',char(13)),NULL,NULL,64,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006495504-w3gqax.jpg','unread',0,NULL,NULL,'2026-04-12 15:08:16','2026-04-12 15:08:16',NULL,20,'grapa','[{"name":"Todd McFarlane","role":"Guion"},{"name":"Greg Capullo","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2080,'Batman / Spawn. Guerra diabólica','Batman / Spawn. Guerra diabólica',NULL,NULL,'978-8-419-67836-2',NULL,'Alan Grant','Klaus Janson',NULL,NULL,'ECC Ediciones',NULL,'2023-03-28',NULL,NULL,replace(replace('Contiene: Batman/Spawn: War Devil USA (1994).\rBruce Wayne presenció el asesinato de sus padres cuando era niño y, con el objetivo de que nadie sufriera tanto como él, entrenó cuerpo y mente para convertirse en Batman, el defensor de Gotham City. Por su parte, Al Simmons fue un agente de la CIA asesinado en horribles circunstancias que ha regresado a la vida convertido en un ser casi demoníaco que va recuperando fragmentos de su memoria. Es así como recuerda a un hombre que, en teoría, mató hace años... y al que Batman también conoce.\r\nEl camino de estos dos referentes del cómic estadounidense se cruza en Guerra diabólica, un cómic escrito por Doug Moench, Alan Grant y Chuck Dixon que cuenta con dibujo del legendario Klaus Janson.','\r',char(13)),'\n',char(10)),NULL,NULL,56,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006508401-3hl1h8.jpg','unread',0,NULL,NULL,'2026-04-12 15:08:29','2026-04-12 15:08:29',NULL,20,NULL,'[{"name":"Alan Grant","role":"Guion"},{"name":"Chuck Dixon","role":"Guion"},{"name":"Doug Moench","role":"Guion"},{"name":"Klaus Janson","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2081,'Superman contra Depredador','Superman contra Depredador',NULL,NULL,'978-8-417-82712-0',NULL,'David Michelinie','Alex Maleev',NULL,NULL,'ECC Ediciones',NULL,'2019-03-26',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Superman vs. Predator núms. 1-3 USA, JLA versus Predator USA\r\nUna expedición científica de S.T.A.R. descubre una astronave en una jungla centroamericana sin sospechar que un Depredador acecha... Pero los peligros no terminan ahí, y un Hombre de Acero muy enfermo, casi privado de sus poderes, deberá sobrevivir en este entorno hostil, donde cada paso puede implicar una muerte segura.\r\n¿Y qué ocurrirá cuando varios Metadepredadores, con los mismos poderes de la JLA, ataquen a los mejores héroes del mundo?\r\nTras Batman contra Depredador, este volumen recopila todos los enfrentamientos de Superman contra Depredador gracias a David Michelinie (The Amazing Spider-Man), John Ostrander (Escuadrón Suicida), Alex Maleev (Daredevil) y Graham Nolan (Batman: Legado).','\r',char(13)),'\n',char(10)),NULL,NULL,200,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006527830-i5royc.jpg','unread',0,NULL,NULL,'2026-04-12 15:08:49','2026-04-12 15:08:49',NULL,20.5,NULL,'[{"name":"David Michelinie","role":"Guion"},{"name":"John Ostrander","role":"Guion"},{"name":"Alex Maleev","role":"Dibujo"},{"name":"Graham Nolan","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2082,'DC Comics/Dark Horse Comics: Aliens','DC Comics/Dark Horse Comics: Aliens',NULL,NULL,'978-8-417-20625-3',NULL,'Ian Edginton','Mark Schultz',NULL,NULL,'ECC Ediciones',NULL,'2017-09-21',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman/Aliens núms. 1-2 USA, Batman/Aliens II núms. 1-3 USA, Superman/Batman vs. Aliens/Predator núms. 1-2 USA, WildC.A.T.S./Aliens núm. 1 USA                                   Siguiendo la pista de la desaparición de un ciudadano de Gotham, Batman viaja hasta la jungla amazónica, donde descubrirá el horror de los aliens... pero ¿podrá detenerlos el Caballero Oscuro? \r\nUnos años después, en unas obras de Gotham se descubre un alien... ¡que provocará el caos en el Asilo Arkham! Convencido de que la aterradora amenaza ha desaparecido, Batman descubre una colonia de esas máquinas de matar implacables, además de la raza imparable de cazadores llamados “depredadores”, que han estado ocultándose en la Tierra durante siglos. ¡Solo el Caballero Oscuro y Superman podrán detener a esas amenazas extraterrestres que están punto de apoderarse del mundo!\r\nPor último, los temibles aliens están a bordo de la estación espacial de Stormwatch, y la tarea de los WildC.A.T.S será salvar a los supervivientes. Pero ¿podrán los WildC.A.T.S vencer en una batalla contra los aliens cuando Stormwatch ya ha caído?\r\nHace más de 30 años, la película Aliens de James Cameron presentó al mundo una nueva clase de terror. ¡Ahora, algunas de las historias que llevaron a los aliens al Universo DC quedan recopiladas en este tomo espeluznante, que incluye las miniseries Batman/Aliens, Batman/Aliens II, Superman and Batman vs. Aliens and Predator y WildC.A.T.S/Aliens.','\r',char(13)),'\n',char(10)),NULL,NULL,400,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006558952-nn628p.jpg','unread',0,NULL,NULL,'2026-04-12 15:09:20','2026-04-12 15:09:20',NULL,35.5,NULL,'[{"name":"Ian Edginton","role":"Guion"},{"name":"Mark Schultz","role":"Guion"},{"name":"Ron Marz","role":"Guion"},{"name":"Warren Ellis","role":"Guion"},{"name":"Ariel Olivetti","role":""},{"name":"Bernie Wrightson","role":""},{"name":"Chris Sprouse","role":""},{"name":"Staz Johnson","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2085,'La Cosa del Pantano de Alan Moore #1','La Cosa del Pantano de Alan Moore',1,NULL,'978-8-467-49753-3',NULL,'Alan Moore','Dan Day',NULL,NULL,'Planeta Cómic / ECC Ediciones',NULL,'2011-01-01',NULL,NULL,replace(replace('EDICION ORIGINAL: The Saga of the Swamp Thing #20-34 y Swamp Thing Vol. 2 Annual #2 USA.\r\nARGUMENTO: De 1983 a 1987, un joven autor británico llamado Alan Moore revolucionó el cómic estadounidense. Su rompedora etapa en La Cosa del Pantano de DC Comics sentó nuevas bases para la narrativa gráfica y desató una revolución en el medio que llega hasta nuestros días. Moore añadió al terror gótico característico de la serie un estilo narrativo asombrosamente intuitivo y una caracterización profunda y sin precedentes que plasmó el dibujo hermoso y cautivador de colaboradores como Stephen Bissette, John Totleben, Shawn McManus o Rick Veitch. El resultado fue una de las obras maestras más perdurables del mundo del cómic. Ahora, por primera vez, toda la etapa de Moore se recopila en una edición en tapa dura.','\r',char(13)),'\n',char(10)),NULL,NULL,432,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006656298-05kjfn.jpg','unread',0,NULL,NULL,'2026-04-12 15:11:00','2026-04-12 15:11:00',234,11.99,'tapa dura','[{"name":"Alan Moore","role":""},{"name":"Dan Day","role":""},{"name":"John Totleben","role":""},{"name":"Rick Veitch","role":""},{"name":"Ron Randall","role":""},{"name":"Shawn McManus","role":""},{"name":"Stephen Bissette","role":""},{"name":"Tatjana Wood","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2086,'La Cosa del Pantano de Alan Moore #2','La Cosa del Pantano de Alan Moore',2,NULL,'978-8-468-40266-6',NULL,'Alan Moore','Rick Veitch',NULL,NULL,'Planeta Cómic / ECC Ediciones',NULL,'2011-08-01',NULL,NULL,replace(replace('EDICION ORGINAL:  The Saga of the Swamp Thing VOL. 2 #35-50 USA.\r\nARGUMENTO: &quot;NO SE PUEDE ENTERRAR NI OLVIDAR EL DOLOR. EL DOLOR NO SE QUEDA EN EL PASADO NI SE OCULTA BAJO TIERRA. LO QUE SE ENTIERRA NO DESAPARECE. LO QUE SE PLANTA CRECE.De 1983 a 1987, un joven autor británico llamado Alan Moore revolucionó el cómic estadounidense. Su rompedora etapa en La Cosa del Pantano de DC Comics sentó nuevas b ases para la narrativa gráfica y desató una revolución en el medio que llega hasta nuestros días. Moore añadió al terror gótico característico de la serie un estilo narrativo asombrosamente intuitivo y una caracterización profunda y sin precedentes que plasmó el dibujo hermoso y cautivador de colaboradores como Stephen Bissette, John Totleben, Shawn McManus o Rick Veitch. El resultado fue una de las obras maestras más perdurables del mundo del cómic. Ahora, por primera vez, toda la etapa de Moore se recopila en una edición tapa dura. &quot;','\r',char(13)),'\n',char(10)),NULL,NULL,432,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006665010-ghheav.jpg','unread',0,NULL,NULL,'2026-04-12 15:11:05','2026-04-12 15:11:05',234,NULL,'tapa dura','[{"name":"Alan Moore","role":""},{"name":"Rick Veitch","role":""},{"name":"Stan Woch","role":""},{"name":"Stephen Bissette","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2087,'La Cosa del Pantano de Alan Moore #3','La Cosa del Pantano de Alan Moore',3,NULL,'978-8-415-62830-9',NULL,'Alan Moore','Alfredo Alcalá',NULL,NULL,'Planeta Cómic / ECC Ediciones',NULL,'2012-08-01',NULL,NULL,'EDICION ORIGINAL:  The Saga of the Swamp Thing VOL. 2 #51-64 USA (1986-1987).',NULL,NULL,432,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006666836-ld6mt3.jpg','unread',0,NULL,NULL,'2026-04-12 15:11:07','2026-04-12 15:11:07',234,NULL,'Cartoné 368-432 pp','[{"name":"Alan Moore","role":""},{"name":"Alfredo Alcalá","role":""},{"name":"John Totleben","role":""},{"name":"Rick Veitch","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2088,'Lobo: Autopista al Infierno','Lobo: Autopista al Infierno',NULL,NULL,'978-8-416-30310-6',NULL,'Scott Ian','Sam Kieth',NULL,NULL,'ECC Ediciones',NULL,'2014-12-31',NULL,NULL,replace(replace('Contiene: Lobo: Highway to Hell #1-2 USA (2009)\r\n&quot;Bueno, ¿qué tal Satán? ¿El mismísimo Diablo? ¿Lucifer? ¿Belcebú? ¿El Príncipe de la Oscuridad? Le llames como le llames, aquel que gobierna el Infierno con mano de hierro lleva mucho tiempo albergando un profundo rencor contra el último czarniano, y no está dispuesto a dejar ese resentimiento sin resolver. Y por supuesto, no está en la naturaleza del Hombre rechazar una buena pelea. Así que Lobo se va al infierno (más pronto de lo esperado, aunque hubiera terminado allí de todos modos) y empieza a destripar gente a diestro y siniestro. Pero además de estar pavimentada con buenas intenciones, botellas de cerveza y los destrozados y aullantes cuerpos de los condenados, la Autopista al Infierno da algunos giros y vueltas a lo largo del camino... ¡y le proporciona a Lobo algunas sorpresas desagradables!\r\nEl escritor e icono del trash metal Scott Ian, miembro del grupo Anthrax, forma equipo con el brillante creador de The Maxx, Sam Kieth, para mostrarnos a un Lobo desencadenado y salvaje como jamás se había visto antes. En serio. Espera a llegar a la parte de la abeja. Es una locura.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006691800-icf2tt.jpg','read',0,NULL,NULL,'2026-04-12 15:11:32','2026-04-12 16:12:15',NULL,19.95,NULL,'[{"name":"Scott Ian","role":"Guion"},{"name":"Sam Kieth","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2089,'Superman: Red and Blue','Superman: Red and Blue',NULL,NULL,'978-8-419-27916-3',NULL,'Brandon Easton','Dan Panosian',NULL,NULL,'ECC Ediciones',NULL,'2022-05-31',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Superman Red and Blue núms. 1-6 USA \r\nA lo largo de sus más de ocho décadas de su vida, Superman se ha confirmado como el héroe definitivo, no solo por las amenazas a las que ha hecho frente sino también por los férreos valores de los que se ha convertido en estandarte. En este volumen, asistimos a una antología de relatos que se ambientan en diferentes épocas de su vida e incluso a alguno protagonizado por una variante suya, como Val-Zod, el Hombre de Acero de Tierra 2.\r\nSiguiendo la estela de Batman: Black and White, este volumen cuenta con historias realizadas por los mejores autores del cómic estadounidense, incluidos Mark Waid, Francis Manapul, Steven T. Seagle, Wes Craig, G. Willow Wilson o Valentine de Landro, entre muchos más.','\r',char(13)),'\n',char(10)),NULL,NULL,272,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006708793-s18u2c.jpg','read',0,4,NULL,'2026-04-12 15:11:49','2026-04-12 15:11:53',NULL,29,NULL,'[{"name":"Brandon Easton","role":"Guion"},{"name":"Brandon Thomas","role":"Guion"},{"name":"Chuck Brown","role":"Guion"},{"name":"Dan Panosian","role":"Guion, Dibujo"},{"name":"Dan Watters","role":"Guion"},{"name":"Daniel Warren Johnson","role":"Guion, Dibujo"},{"name":"Darcie Little Badger","role":"Guion"},{"name":"Francis Manapul","role":"Guion, Dibujo"},{"name":"G. Willow Wilson","role":"Guion"},{"name":"James Stokoe","role":"Guion, Dibujo"},{"name":"Jason Howard","role":"Guion, Dibujo"},{"name":"Jesse J. Holland","role":"Guion"},{"name":"John Ridley","role":"Guion"},{"name":"Joshua Williamson","role":"Guion"},{"name":"Judd Winick","role":"Guion"},{"name":"Marguerite Bennett","role":"Guion"},{"name":"Mark Buckingham","role":"Guion, Dibujo"},{"name":"Mark Waid","role":"Guion"},{"name":"Matt Wagner","role":"Guion, Dibujo"},{"name":"Michael Conrad","role":"Guion"},{"name":"Michael Fiffe","role":"Guion"},{"name":"Nick Spencer","role":"Guion"},{"name":"Rex Ogle","role":"Guion"},{"name":"Rich Douek","role":"Guion"},{"name":"Robert Venditti","role":"Guion"},{"name":"Sophie Campbell","role":"Guion, Dibujo"},{"name":"Stephanie Phillips","role":"Guion"},{"name":"Steven T. Seagle","role":"Guion"},{"name":"Tom King","role":"Guion"},{"name":"Wes Craig","role":"Guion, Dibujo"},{"name":"Alitha Martínez","role":"Dibujo"},{"name":"Audrey Mok","role":"Dibujo"},{"name":"Berat Pekmezci","role":"Dibujo"},{"name":"Chris Sprouse","role":"Dibujo"},{"name":"Christian Ward","role":"Dibujo"},{"name":"Clayton Henry","role":"Dibujo"},{"name":"Cully Hamner","role":"Dibujo"},{"name":"Denys Cowan","role":"Dibujo"},{"name":"Duncan Rouleau","role":"Dibujo"},{"name":"Ibrahim Moustafa","role":"Dibujo"},{"name":"Jill Thompson","role":"Dibujo"},{"name":"Joe Quinones","role":"Dibujo"},{"name":"Laura Braga","role":"Dibujo"},{"name":"Marley Zarcone","role":"Dibujo"},{"name":"Michel Fiffe","role":"Dibujo"},{"name":"Mike Norton","role":"Dibujo"},{"name":"Paolo Rivera","role":"Dibujo"},{"name":"Steve Lieber","role":"Dibujo"},{"name":"Steve Pugh","role":"Dibujo"},{"name":"Valentine De Landro","role":"Dibujo"},{"name":"Dani","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2091,'Batman: Black and White #1','Batman: Black and White',1,NULL,'978-8-416-37479-3',NULL,'Walter Simonson','Walter Simonson',NULL,NULL,'ECC Ediciones',NULL,'2015-04-29',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman Black and White núms. 1 a 4 USA \r\nCon la reedición del primer volumen de Batman: Black and White, recuperamos una de las antologías más celebradas del cómic americano, con la que desde 1997 los mejores historietistas rinden tributo al Caballero Oscuro a través de historias cortas que explotan toda la crudeza y elegancia del blanco y negro.\r\nJoe Kubert, Neil Gaiman, Richard Corben, Neal Adams, Mike Allred, Frank Miller, Katsuhiro Otomo, Alex Ross, Bill Sienkiewicz, Alex Toth, José Muñoz… ¿Hace falta decir más? Averigua por qué esta obra se alzó con el Premio Eisner 1997 a la mejor antología y el Harvey 1998 al mejor volumen recopilatorio, entre otros galardones.','\r',char(13)),'\n',char(10)),NULL,NULL,312,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006767279-xh5aux.jpg','read',0,NULL,NULL,'2026-04-12 15:12:50','2026-04-12 16:12:15',235,23.95,'Cartone','[{"name":"Walter Simonson","role":"Guion, Dibujo"},{"name":"Andrew Helfer","role":"Guion"},{"name":"Archie Goodwin","role":"Guion"},{"name":"Bill Sienkiewicz","role":"Guion, Dibujo"},{"name":"Brian Bolland","role":"Guion, Dibujo"},{"name":"Bruce Timm","role":"Guion, Dibujo"},{"name":"Chuck Dixon","role":"Guion"},{"name":"Howard Chaykin","role":"Guion, Dibujo"},{"name":"Jan Strnad","role":"Guion"},{"name":"Joe Kubert","role":"Guion, Dibujo"},{"name":"Katsuhiro Otomo","role":"Guion, Dibujo"},{"name":"Kent Williams","role":"Guion, Dibujo"},{"name":"Kevin Nowlan","role":"Guion, Dibujo"},{"name":"Klaus Janson","role":"Guion, Dibujo"},{"name":"Matt Wagner","role":"Guion, Dibujo"},{"name":"Neil Gaiman","role":"Guion"},{"name":"Ted McKeever","role":"Guion, Dibujo"},{"name":"Brian Stelfreeze","role":"Dibujo"},{"name":"Gary Gianni","role":"Dibujo"},{"name":"Jorge Zaffino","role":"Dibujo"},{"name":"José Muñoz","role":"Dibujo"},{"name":"Richard Corben","role":"Dibujo"},{"name":"Simon Bisley","role":"Dibujo"},{"name":"Tanino Liberatore","role":"Dibujo"},{"name":"Teddy H. Kristiansen","role":"Dibujo"},{"name":"Dennis O''Neil","role":"Guion"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2092,'Batman: Black and White #2','Batman: Black and White',2,NULL,'978-8-416-66005-6',NULL,'Chris Claremont','Gene Colan',NULL,NULL,'ECC Ediciones',NULL,'2016-02-29',NULL,NULL,replace(replace('Contiene: Batman Black and White Vol. 2 USA (Material from Batman Gotham Knights #1-16).\r\nSegunda entrega del compendio de historia cortas autoconclusivas en la que los mejores autores del medio homenajean al Hombre Murciélago, sacando todo el partido a la crudeza y elegancia del blanco y negro.\r\nGene Colan, Chris Claremont, José Luis García-López, Harlan Ellison, Dave Gibbons, Jim Lee, Paul Pope, Brian Azzarello, Eduardo Risso, Alex Ross, Tim Sale, Jordi Bernet, Daniel Torres… ¿Hace falta decir más? ¡Averigua por qué esta obra se alzó con el Premio Eisner 2003 al mejor álbum (reedición)!','\r',char(13)),'\n',char(10)),NULL,NULL,312,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006774580-6hkd9u.jpg','read',0,NULL,NULL,'2026-04-12 15:12:55','2026-04-12 16:12:15',235,NULL,'Cartone','[{"name":"Gene Colan","role":"Dibujo"},{"name":"Chris Claremont","role":"Guion"},{"name":"José Luis García-López","role":"Dibujo"},{"name":"Harlan Ellison","role":"Guion"},{"name":"Dave Gibbons","role":"Guion, Dibujo"},{"name":"Jim Lee","role":"Dibujo"},{"name":"Paul Pope","role":"Guion, Dibujo"},{"name":"Brian Azzarello","role":"Guion"},{"name":"Eduardo Risso","role":"Dibujo"},{"name":"Alex Ross","role":"Dibujo"},{"name":"Tim Sale","role":"Dibujo"},{"name":"Jordi Bernet","role":"Dibujo"},{"name":"Daniel Torres","role":"Dibujo"},{"name":"Warren Ellis","role":"Guion"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2093,'Marvels','Marvels',NULL,NULL,'978-8-439-50206-7',NULL,'Kurt Busiek','Alex Ross',NULL,NULL,'Planeta DeAgostini Cómics - Forum',NULL,'2003-06-01',NULL,NULL,replace(replace('Contiene: Marvels #0-4 y Marvel Hardcover\r\nMarvels ha sido, sin duda, una de las obras más importantes realizadas en el cómic de superhéroes en la década de los noventa, y la que lanzó al estrellato a dos grandes autores como Kurt Busiek y Alex Ross. \r\nEn este tomo podréis ver los orígenes del Universo Marvel y como este evoluciona hasta llegar a un punto clave que lo cambiará para siempre, todo ello narrado desde el punto de vista de un ser humano corriente que experimenta las hazañas de los &quot;prodigios&quot;.','\r',char(13)),'\n',char(10)),NULL,NULL,256,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006808703-r2puay.jpg','read',0,NULL,NULL,'2026-04-12 15:13:31','2026-04-12 16:11:44',NULL,12.99,'Rústica','[{"name":"Kurt Busiek","role":"Guion"},{"name":"Alex Ross","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2094,'Spiderman. Coleccionable Spider-Man #1','Spiderman. Coleccionable Spider-Man',1,NULL,'978-8-490-24695-5',NULL,'Todd McFarlane','Todd McFarlane',NULL,NULL,'Panini Comics España',NULL,'2014-04-09',NULL,NULL,replace(replace('Contiene Spider-Man 1-5 USA\r\n¡Primer tomo de seis! Comienza la recopilación del Spiderman de Todd McFarlane como autor completo de las aventuras del trepamuros. En 1990, después de haberse alzado como el más comercial artista arácnido de la década, Todd McFarlane dio un paso adelante en su carrera al conseguir que Marvel le concediera una nueva colección en la que también sería el autor de las historias: relatos oscuros y siniestros, diferentes al espíritu tradicional del trepamuros. Esta serie de seis volúmenes ofrece tanto la etapa de McFarlane como la de su sucesor, Erik Larsen, así como los episodios de la misma cabecera que realizara Ann Nocenti. En este primer volumen... ¡El Lagarto! ¡Las consecuencias de &quot;La última cacería de Kraven&quot;! Es la peor noche en la historia de Spiderman...','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006838527-6enat1.jpg','unread',0,NULL,NULL,'2026-04-12 15:14:02','2026-04-12 15:14:02',236,24.95,'cartone','[{"name":"Todd McFarlane","role":"Guion, Dibujo, Tinta, Color"},{"name":"Bob Sharen","role":"Color"},{"name":"Gregory Wright","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2095,'Spiderman. Coleccionable Spider-Man #2','Spiderman. Coleccionable Spider-Man',2,NULL,'978-8-490-24696-2',NULL,'Todd McFarlane','Todd McFarlane',NULL,NULL,'Panini Comics España',NULL,'2014-04-23',NULL,NULL,replace(replace('Contiene Spider-Man 6-12 USA\r\nSegundo de los seis volúmenes de los que consta la recopilación del Spiderman de Todd McFarlane! &quot;Percepciones&quot; se abre con una pequeña aventura en la que el trepamuros se encuentra con el Motorista Fantasma y ambos afrontan la amenaza del Duende. Y a continuación: una ola de asesinatos brutales azota los bosques canadienses. Peter Parker viaja hasta allí para investigar lo que está ocurriendo... ¡Para cruzarse en el camino de Lobezno y del Wendigo!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006846546-2mizx7.jpg','unread',0,NULL,NULL,'2026-04-12 15:14:07','2026-04-12 15:14:07',236,NULL,'cartone','[{"name":"Todd McFarlane","role":"Guion, Dibujo, Tinta"},{"name":"Rick Magyar","role":"Tinta"},{"name":"Scott Williams","role":"Tinta"},{"name":"Rob Liefeld","role":"Tinta"},{"name":"Jim Lee","role":"Tinta"},{"name":"Gregory Wright","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2096,'Spiderman. Coleccionable Spider-Man #3','Spiderman. Coleccionable Spider-Man',3,NULL,'978-8-490-24748-8',NULL,'Todd McFarlane','Todd McFarlane',NULL,NULL,'Panini Comics España',NULL,'2014-05-03',NULL,NULL,replace(replace('Contiene Spider-Man 13-17 y X-Force 4 USA\r\nTercer tomo del coleccionable que recopila la serie que Todd McFarlane convirtiera en un superventas. Spidey recupera su traje negro y se sumerge en las cloacas de Manhattan para enfrentarse contra Morbius, el Vampiro Viviente; A continuación, Erik Larsen irrumpe en la serie, con un episodio en el que Spiderman se cruza en el camino de La Bestia. Y acto seguido, llega el cruce del trepamuros con X-Force.. ¡Contra Juggernaut! Además, Spiderman contra Thanos, en una historia diferente, realizada por un equipo creativo excepcional, el compuesto por Ann Nocenti y Rick Leonardi.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006849197-abulau.jpg','unread',0,NULL,NULL,'2026-04-12 15:14:09','2026-04-12 15:14:09',236,NULL,'cartone','[{"name":"Todd McFarlane","role":"Guion, Dibujo, Tinta"},{"name":"Erik Larsen","role":"Guion, Dibujo, Tinta"},{"name":"Fabian Nicieza","role":"Guion"},{"name":"Rob Liefeld","role":"Guion, Dibujo, Tinta"},{"name":"Ann Nocenti","role":"Guion"},{"name":"Rick Leonardi","role":"Dibujo"},{"name":"Al Williamson","role":"Tinta"},{"name":"Gregory Wright","role":"Color"},{"name":"Brian Murray","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2097,'Spiderman. Coleccionable Spider-Man #4','Spiderman. Coleccionable Spider-Man',4,NULL,'978-8-490-24749-5',NULL,'Erik Larsen','Erik Larsen',NULL,NULL,'Panini Comics España',NULL,'2014-05-21',NULL,NULL,replace(replace('Contiene Spider-Man 18-23 USA\r\n¡Erik Larsen, uno de los más espectaculares autores de los noventa, se hace con las riendas de la colección que creara Todd McFarlane para ofrecer una de las más espectaculares historias jamás realizadas con Los Seis Siniestros como enemigos! El lanzarredes se une al Motorista Fantasma, Hulk, Nova, Deathlok y muchos más para hacer frente al grupo liderado por el Doctor Octopus. ¿Conseguirá Pete derrotar a sus enemigos a tiempo para su cumpleaños!','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006851279-9n5xgz.jpg','unread',0,NULL,NULL,'2026-04-12 15:14:12','2026-04-12 15:14:12',236,NULL,'cartone','[{"name":"Erik Larsen","role":"Guion, Dibujo, Tinta"},{"name":"Terry Kavanagh","role":"Guion"},{"name":"Scott McDaniel","role":"Dibujo"},{"name":"Keith Williams","role":"Tinta"},{"name":"Gregory Wright","role":"Color"},{"name":"Renée Witterstaetter","role":"Color"},{"name":"Joe Rosas","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2098,'Spiderman. Coleccionable Spider-Man #5','Spiderman. Coleccionable Spider-Man',5,NULL,'978-8-490-24767-9',NULL,'Howard Mackie','Larry Alexander',NULL,NULL,'Panini Comics España',NULL,'2014-06-04',NULL,NULL,replace(replace('Contiene Spider-Man 24-28 USA\r\n¡La celebración del treinta aniversario del nacimiento de Spiderman, con dos de sus más destacados autores de los años ochenta, Tom DeFalco y Ron Frenz! Juntos rememoran el origen del trepamuros mientras presentan un nuevo villano. Y además, el cruce de Spiderman con &quot;La guerra del Infinito&quot;, un encuentro con Excalibur y una aventura muy especial, realizada por los míticos autores Don McGregor (Pantera Negra) y Marshall Rogers (Batman), acerca de la violencia y la posesión de armas en los colegios estadounidenses.\r\n&quot;Una gran responsabilidad&quot; contiene los episodios de la colección titulada simplemente Spider-man se publicaron tras la marcha de Todd McFarlane y Erik Larsen, quiénes habían sido hasta entonces los máximos artífices de la cabecera. Marvel buscaba una nueva razón de ser para este título al tiempo que se avecinaban grandes cambios para el personaje protagonista.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006853693-bqziix.jpg','unread',0,NULL,NULL,'2026-04-12 15:14:14','2026-04-12 15:14:14',236,NULL,'cartone','[{"name":"Howard Mackie","role":"Guion"},{"name":"Larry Alexander","role":"Dibujo"},{"name":"Andrew Pepoy","role":"Tinta"},{"name":"Gregory Wright","role":"Color"},{"name":"Terry Kavanagh","role":"Guion"},{"name":"Chris Marrinan","role":"Dibujo"},{"name":"Mark Stegbauer","role":"Tinta"},{"name":"Kevin Tinsley","role":"Color"},{"name":"Tom DeFalco","role":"Guion"},{"name":"Ron Frenz","role":"Dibujo"},{"name":"Mark Bagley","role":"Dibujo"},{"name":"Klaus Janson","role":"Tinta"},{"name":"Al Milgrom","role":"Tinta"},{"name":"Keith Williams","role":"Tinta"},{"name":"Mark Texeira","role":"Tinta"},{"name":"Tom Palmer","role":"Tinta"},{"name":"Joe Rubinstein","role":"Tinta"},{"name":"Renée Witterstaetter","role":"Color"},{"name":"Sam de la Rosa","role":"Tinta"},{"name":"Don McGregor","role":"Guion"},{"name":"Marshall Rogers","role":"Dibujo"},{"name":"Sarra Mossoff","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2099,'Spiderman. Coleccionable Spider-Man #6','Spiderman. Coleccionable Spider-Man',6,NULL,'978-8-490-24768-6',NULL,'Ann Nocenti','Cindy Martin',NULL,NULL,'Panini Comics España',NULL,'2014-06-20',NULL,NULL,replace(replace('Contiene Web Of Spider-Man 33, Amazing Spider-Man 295, Peter Parker, The Spectacular Spider-Man 133 y Spider-Man 29-34 USA\r\nEn 1987, la aclamada escritora Ann Nocenti, irrumpió en las colecciones de Spiderman para narrar la aventura que nadie imaginaba: ¿Qué ocurre después de que Peter Parker sea internado en un sanatorio psiquiátrico? ¿Acaso el amistoso superhéroe de Nueva York ha perdido la cordura? Cinco años después, en 1992, Nocenti volvió sobre aquel relato para ofrecer una inesperada segunda parte. Este volumen recopila ambas historias.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006856153-6ggjm9.jpg','unread',0,NULL,NULL,'2026-04-12 15:14:16','2026-04-12 15:14:16',236,NULL,'cartone','[{"name":"Ann Nocenti","role":"Guion"},{"name":"Steven Grant","role":"Guion"},{"name":"Cindy Martin","role":"Dibujo"},{"name":"Chris Marrinan","role":"Dibujo"},{"name":"Bob McLeod","role":"Dibujo, Tinta"},{"name":"Lee Weeks","role":"Dibujo"},{"name":"Steve Leialoha","role":"Tinta"},{"name":"Kyle Baker","role":"Tinta"},{"name":"Joe Rubinstein","role":"Tinta"},{"name":"Sam de la Rosa","role":"Tinta"},{"name":"Janet Jackson","role":"Color"},{"name":"Marie Javins","role":"Color"},{"name":"Kevin Tinsley","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2100,'Coleccionable Ultimate (2012-2016) #79','Coleccionable Ultimate (2012-2016)',79,NULL,'978-8-490-94094-5',NULL,'Brian Michael Bendis','Sara Pichelli',NULL,NULL,'Panini Comics España',NULL,'2015-03-16',NULL,NULL,replace(replace('Contiene Ultimate Spider-Man vol. 2, 1-5 USA \r\n¡El relato más comentada de la historia del Hombre Araña definitivo! Tras la muerte de Peter Parker, Miles Morales es el nuevo Spiderman. ¿Cuáles son los secretos detrás de sus poderes y cómo conseguirá dominarlos? ¿Qué nuevos enemigos y qué antiguos villanos del trepamuros original tratarán de desafiarles? ¿Y conseguirá Miles cargar con el legado de Peter? La respuesta está aquí.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006902168-jb6t75.jpg','unread',0,NULL,NULL,'2026-04-12 15:15:06','2026-04-12 15:15:06',237,24.95,'cartone','[{"name":"Sara Pichelli","role":"Dibujo"},{"name":"Brian Michael Bendis","role":"Guion"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2101,'Coleccionable Ultimate (2012-2016) #85','Coleccionable Ultimate (2012-2016)',85,NULL,'978-8-490-94173-7',NULL,'Brian Michael Bendis','Sara Pichelli',NULL,NULL,'Panini Comics España',NULL,'2015-06-06',NULL,NULL,replace(replace('Contiene Spider-Men 1-5 USA \r\nMarvel Comics se enorgullece en presentar una de las mayores aventuras jamás contadas. Llega el encuentro entre Peter Parker, el asombroso Hombre Araña con el que empezó todo, y Miles Morales, el Spiderman Definitivo. ¡Un cruce entre universos como nunca antes has visto! Mientras sigue el rastro de uno de sus peores enemigos, Spidey se encuentra en un mundo donde la versión más joven de sí mismo ha muerto... ¡Y hay un nuevo Spiderman en la ciudad! Brian Michael Bendis, el escritor más relevante del siglo XXI, y Sara Pichelli (Ultimate Spiderman) narran una historia destinada a hacer historia.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006933915-69ow7o.jpg','unread',0,NULL,NULL,'2026-04-12 15:15:35','2026-04-12 15:15:35',237,NULL,'cartone','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Sara Pichelli","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2102,'Coleccionable Ultimate (2012-2016) #82','Coleccionable Ultimate (2012-2016)',82,NULL,'978-8-490-94128-7',NULL,'Brian Michael Bendis','Chris Samnee',NULL,NULL,'Panini Comics España',NULL,'2015-04-29',NULL,NULL,replace(replace('Contiene Ultimate Comics. All-New Spider-Man 6-12 USA \r\nUn nuevo capítulo en la saga de Miles Morales, el nuevo Spiderman definitivo. Contempla la llegada del Escorpión. Con Miles todavía descubriendo los límites de sus poderes, debe aprender cómo ser un superhéroe con la ayuda de... ¿Peter Parker? Además, ¿qué ocurrirá cuando tía May y Mary Jane descubran que hay un nuevo trepamuros en la ciudad?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006943550-luxgdr.jpg','unread',0,NULL,NULL,'2026-04-12 15:15:44','2026-04-12 15:15:44',237,NULL,'cartone','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Chris Samnee","role":"Dibujo"},{"name":"David Marquez","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2103,'Coleccionable Ultimate (2012-2016) #87','Coleccionable Ultimate (2012-2016)',87,NULL,'978-8-490-94200-0',NULL,'Brian Michael Bendis','David Marquez',NULL,NULL,'Panini Comics España',NULL,'2015-07-10',NULL,NULL,replace(replace('Contiene Ultimate Comics. Spider-Man 13-18 USA\r\n¡Miles Morales se mete de lleno en la nueva guerra civil que asuela Estados Unidos! El nuevo Spiderman se cruza en el camino del Capitán América... ¡Poco imagina que el joven trepamuros quiere formar parte de los Ultimates y además se hará un lugar en el grupo pese a la oposición del Centinela de la Libertad! Pero jugar en las grandes ligas significa enfrentarse a peligros mil veces mayores que aquellos contra los que Miles ha luchado hasta el momento. ¿Estará a la altura de las circunstancias?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006964921-kdd4ct.jpg','unread',0,NULL,NULL,'2026-04-12 15:16:05','2026-04-12 15:16:05',237,NULL,'cartone','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"David Marquez","role":"Dibujo"},{"name":"Pepe Larraz","role":"Dibujo"},{"name":"Sara Pichelli","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2104,'Coleccionable Ultimate (2012-2016) #91','Coleccionable Ultimate (2012-2016)',91,NULL,'978-8-490-94257-4',NULL,'Brian Michael Bendis','Sara Pichelli',NULL,NULL,'Panini Comics España',NULL,'2015-09-03',NULL,NULL,replace(replace('Contiene Ultimate Comics. Spider-Man v2, 16.1, 19-22 USA\r\nLa aventura que cambió para siempre la saga del nuevo Hombre Araña Definitivo. Miles Morales por fin tiene su traje y sus lanzarredes y ahora le toca enfrentarse con uno de los principales enemigos de su predecesor. Hay un nuevo Veneno en la ciudad y está hambriento. ¿Qué sabe sobre él? Sólo una persona puede ayudarle: Gwen Stacy.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006969485-0rxz9b.jpg','unread',0,NULL,NULL,'2026-04-12 15:16:10','2026-04-12 15:16:10',237,NULL,'cartone','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Sara Pichelli","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2105,'Coleccionable Ultimate (2012-2016) #94','Coleccionable Ultimate (2012-2016)',94,NULL,'978-8-490-94287-1',NULL,'Brian Michael Bendis','David Marquez',NULL,NULL,'Panini Comics España',NULL,'2015-10-14',NULL,NULL,replace(replace('Contiene Ultimate Comics. All-New Spider-Man 23-28 USA \r\nDespués de que la tragedia golpeara a Miles Morales como nunca lo había hecho, el nuevo Spiderman decidió abandonar su carrera como superhéroe. Un año después, otros héroes han tomado su lugar, pero quizás ninguno de ellos sea suficiente para la amenaza que aguarda en la sombra. ¿Quién convencerá a Miles de que regrese a la acción?','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006974314-e6kkr5.jpg','unread',0,NULL,NULL,'2026-04-12 15:16:14','2026-04-12 15:16:14',237,NULL,'cartone','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"David Marquez","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2106,'Coleccionable Ultimate (2012-2016) #98','Coleccionable Ultimate (2012-2016)',98,NULL,'978-8-490-94357-1',NULL,'Brian Michael Bendis','Mark Bagley',NULL,NULL,'Panini Comics España',NULL,'2015-12-16',NULL,NULL,replace(replace('Contiene Ultimate Spider-Man 200 y Miles Morales: The Ultimate Spider-Man 1-7 USA \r\nDespués del &quot;Cataclismo&quot;, llega el nuevo comienzo del Universo Ultimate, con una celebración especial que reúne al guionista y a todos los dibujantes con los que ha contado el Spiderman Definitivo. El mundo llora el aniversario de la muerte de Peter Parker. Una reunión de amigos y enemigos de Spidey sacará a la luz sorprendentes revelaciones acerca de éste y su mundo. Y a continuación: Miles vuelve a la acción con un nuevo statu quo y una nueva forma de mirar al mundo.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006978910-pgf7xf.jpg','unread',0,NULL,NULL,'2026-04-12 15:16:19','2026-04-12 15:16:19',237,NULL,'cartone','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Mark Bagley","role":"Dibujo"},{"name":"Mark Brooks","role":"Dibujo"},{"name":"Stuart Immonen","role":"Dibujo"},{"name":"David Lafuente","role":"Dibujo"},{"name":"Sara Pichelli","role":"Dibujo"},{"name":"David Marquez","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2107,'Coleccionable Ultimate (2012-2016) #102','Coleccionable Ultimate (2012-2016)',102,NULL,'978-8-490-94497-4',NULL,'Brian Michael Bendis','David Marquez',NULL,NULL,'Panini Comics España',NULL,'2016-04-24',NULL,NULL,replace(replace('Contiene Miles Morales: The Ultimate Spider-Man 8-12 y Ultimate End 1-5 USA \r\n¡Último tomo! El Coleccionable del Universo Ultimate llega a su fin... ¡Y el propio Universo Ultimate también! Miles Morales y el resto de los personajes que conforman este mundo se enfrentan a la extinción final. Una vez que el fin de su mundo se ha vuelto inevitable, ¿qué importarán los últimos sacrificios que hagan los héroes? Brian Michael Bendis y Mark Bagley, el equipo creativo que lo empezó todo, serán también quiénes le pongan punto y final a todo un Universo. Y esta vez no habrá ningún relanzamiento posterior. Quince años de cómics llegan a su fin','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776006986115-c4a0p7.jpg','unread',0,NULL,NULL,'2026-04-12 15:16:26','2026-04-12 15:16:26',237,NULL,'cartone','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"David Marquez","role":"Dibujo"},{"name":"Mark Bagley","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2108,'Marvel Zombies. Hambre Insaciable. Marvel Deluxe','Marvel Zombies. Hambre Insaciable. Marvel Deluxe',NULL,NULL,'978-8-498-85515-9',NULL,'Robert Kirkman','Sean Phillips',NULL,NULL,'Panini Comics España',NULL,'2010-10-21',NULL,NULL,replace(replace('Contiene Marvel Zombies: Dead Days, Ultimate Fantastic Four 21-23 y Marvel Zombies 1-5 USA\r\n¡La más brutal, desacralizadora, divertida y terrorí­fica versión del Universo Marvel jamás producida! Un virus convirtió a los héroes de la tierra en devoradores de carne humana. Acompaña a los muertos vivientes en los que se han transformado los iconos Marvel en su búsqueda de alimento, con un gigantesco volumen que recoge su origen, su primera aparición y la visionaria miniserie que revolucionó la industria del cómic.','\r',char(13)),'\n',char(10)),NULL,NULL,256,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007106677-4eusi1.jpg','read',0,NULL,NULL,'2026-04-12 15:18:29','2026-04-12 16:11:44',NULL,23.95,NULL,'[{"name":"Robert Kirkman","role":"Guion"},{"name":"Sean Phillips","role":"Dibujo, Tinta"},{"name":"Arthur Suydam","role":"Dibujo"},{"name":"Mark Millar","role":"Guion"},{"name":"Greg Land","role":"Dibujo"},{"name":"Matt Ryan","role":"Tinta"},{"name":"June Chung","role":"Color"},{"name":"Justin Ponsor","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2109,'Batman: Caballero maldito - DC Black Label','Batman: Caballero maldito - DC Black Label',NULL,NULL,'978-8-417-87172-7',NULL,'Jeph Loeb','Tim Sale',NULL,NULL,'ECC Ediciones',NULL,'2019-07-16',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman: Legends of the Dark Knight Halloween Special núm. 1 USA, Batman: Madness - A Legends of the dark Knight Halloween Special USA y Batman: Ghosts - A Legends of the Dark Knight Halloween Special USA\r\nGotham City, hogar del Caballero Oscuro… pero también de sus perturbados enemigos: criminales como el Espantapájaros, el Sombrerero Loco, el Pingüino, el Joker o Hiedra Venenosa, que durante la noche de Halloween ponen a prueba a Batman y obligan a Bruce Wayne a enfrentarse a sus más profundos miedos.\r\nBatman: Caballero Maldito recopila tres especiales conmemorativos de la tétrica festividad norteamericana que, apadrinados por el editor Archie Goodwin, representan las primeras incursiones conjuntas de Jeph Loeb y Tim Sale (Batman: El largo Halloween, Batman: Victoria Oscura, Catwoman: Si vas a Roma...) en el universo de ficción del Hombre Murciélago.','\r',char(13)),'\n',char(10)),NULL,NULL,192,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007144173-wpijmq.jpg','unread',0,NULL,NULL,'2026-04-12 15:19:05','2026-04-12 15:19:05',NULL,21.5,'lujo','[{"name":"Jeph Loeb","role":"Guion"},{"name":"Tim Sale","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2110,'Batman: El largo Halloween - DC Black Label','Batman: El largo Halloween - DC Black Label',NULL,NULL,'978-8-417-78761-5',NULL,'Jeph Loeb','Tim Sale',NULL,NULL,'ECC Ediciones',NULL,'2019-03-26',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman: The Long Halloween núms. 1-13 USA\r\nEn los albores de su cruzada contra el crimen, el Caballero Oscuro trata de descubrir la identidad de Festivo: misterioso homicida que, aprovechando fechas señaladas del calendario, está perpetrando una serie de asesinatos. Con las familias criminales de Gotham en pie de guerra, Batman tan solo contará con la ayuda de James Gordon y Harvey Dent para resolver este caso...\r\nTras los especiales de Halloween recopilados en Batman: Caballero Maldito (próximamente en DC Black Label), Jeph Loeb (Batman: Silencio) y Tim Sale (Superman: Las cuatro estaciones) se embarcaron en un ambicioso proyecto, punto de inflexión de sus respectivas carreras: la aclamada serie limitada Batman: El largo Halloween, todo un clásico moderno.','\r',char(13)),'\n',char(10)),NULL,NULL,400,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007171728-zqglax.jpg','read',0,NULL,NULL,'2026-04-12 15:19:33','2026-04-12 16:11:44',NULL,35.5,'Rústica','[{"name":"Jeph Loeb","role":"Guion"},{"name":"Tim Sale","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2111,'Grandes Autores de Batman: Grant Morrison #1','Grandes Autores de Batman: Grant Morrison',1,NULL,'978-8-416-15208-7',NULL,'Grant Morrison','Dave McKean',NULL,NULL,'ECC Ediciones',NULL,'2014-06-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman: Artkham Asylum USA \r\nDurante un aciago 1 de abril, los internos de Arkham logran hacerse con el control del hospital psiquiátrico, secuestrando a los trabajadores del centro. Liderados por el Joker, los criminales más despiadados e inestables de Gotham City -Dos Caras, Killer Croc o el Sombrerero Loco, entre otros- exigen una única condición para liberar a los rehenes: que Batman les acompañe en tan siniestra morada.\r\nEn 1989, Grant Morrison (All-Star Superman, Los Invisibles) y Dave McKean (Sandman, Cages) desarrollaron Asilo Arkham, una de las obras más exitosas de la historia del cómic, ahora recuperada a través de una edición repleta de extras: abundante material gráfico y el guion original anotado, que permiten apreciar toda la complejidad de esta inolvidable novela gráfica en la que el Hombre Murciélago se ve obligado a enfrentarse a sus enemigos más letales… y a sus miedos más profundos.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007200670-td29li.jpg','unread',0,NULL,NULL,'2026-04-12 15:20:04','2026-04-12 15:20:04',238,23.95,NULL,'[{"name":"Grant Morrison","role":"Guion"},{"name":"Dave McKean","role":"Dibujo, Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2112,'Grandes Autores de Batman: Frank Miller #3','Grandes Autores de Batman: Frank Miller',3,NULL,'978-8-415-52037-5',NULL,'Frank Miller','Frank Miller',NULL,NULL,'ECC Ediciones',NULL,'2012-06-01',NULL,NULL,replace(replace('Frank Miller siguen narrando el ocaso del Caballero Oscuro en esta secuela directa de la magistral El regreso del Caballero Oscuro, historia con la que Miller revolucionó la industria del cómic norteamericano en los años ochenta.\r\nEl genial autor, otra vez apoyado por la colorista Lynn Varley, nos ofrece el último capítulo de un envejecido Bruce Wayne obligado a contraatacar de nuevo para traer un poco de esperanza a un mundo al borde del abismo.','\r',char(13)),'\n',char(10)),NULL,NULL,100,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007219857-q3a4ss.jpg','read',0,NULL,NULL,'2026-04-12 15:20:23','2026-04-12 16:11:44',239,19.97,'cartone','[{"name":"Frank Miller","role":"Guion, Dibujo, Tinta"},{"name":"Lynn Varley","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2113,'Grandes Autores de Batman: Frank Miller #1','Grandes Autores de Batman: Frank Miller',1,NULL,'978-8-415-52035-1',NULL,'Frank Miller','David Mazzucchelli',NULL,NULL,'ECC Ediciones',NULL,'2012-03-01',NULL,NULL,replace(replace('Coincidiendo con la celebración del 75 aniversario de DC Comics, la editorial buscaba simplificar la continuidad de su universo ficcional, justificando su decisión mediante la maxiserie Crisis en Tierras infinitas, de Marv Wolfman y George Pérez. La oportunidad perfecta para, haciendo tabla rasa, relatar de nuevo el origen de sus personajes más populares; aunque en el caso de Batman, los editores de turno eran plenamente conscientes de que, más que una reformulación radical, procedía limitarse a pulir la versión original, todavía icónica, poderosa y evocadora. \r\nMiller se vio arropado por un equipo de colaboradores que merecían toda su confianza: Dennis O','\r',char(13)),'\n',char(10)),NULL,NULL,100,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007247703-gle114.jpg','read',0,NULL,NULL,'2026-04-12 15:20:50','2026-04-12 16:11:44',239,24.95,'cartone','[{"name":"Frank Miller","role":"Guion"},{"name":"David Mazzucchelli","role":"Dibujo, Tinta"},{"name":"Richmond Lewis","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2114,'Grandes Autores de Batman: Frank Miller #2','Grandes Autores de Batman: Frank Miller',2,NULL,'978-8-415-52036-8',NULL,'Frank Miller','Frank Miller',NULL,NULL,'ECC Ediciones',NULL,'2012-05-01',NULL,NULL,replace(replace('USA: Batman: The Dark Knight Vol. 1 nº 1 - 4\r\nUn Bruce Wayne viejo y cansado, quien hace ya 10 años se ha retirado de su vida de superhéroe, decide volver a usar la máscara del murciélago una vez más cuando los últimos eventos en Gotham City lo hacen recapitular su decisión de abandonar su papel de vigilante de las calles.','\r',char(13)),'\n',char(10)),NULL,NULL,100,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007275357-im16um.jpg','read',0,NULL,NULL,'2026-04-12 15:21:18','2026-04-12 16:11:44',239,24.95,'cartone','[{"name":"Frank Miller","role":"Guion, Dibujo, Tinta"},{"name":"Klaus Janson","role":"Tinta"},{"name":"Lynn Varley","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2115,'Grandes Autores de Batman: Frank Miller #4','Grandes Autores de Batman: Frank Miller',4,NULL,'978-8-415-52038-2',NULL,'Frank Miller','Jim Lee',NULL,NULL,'ECC Ediciones',NULL,'2012-07-01',NULL,NULL,replace(replace('CONTENIDO ORIGINAL USA:\r\nAll Star Batman & Robin, The Boy Wonder núms. 1 al 10 (IX/2005-VIII/2008)\r\nSINOPSIS:\r\n&quot;Frank Miller regresa al Caballero Oscuro para relatar de nuevo el momento en que Batman acogió a Dick Grayson después de la muerte de sus padres, convirtiéndole en su socio Robin. \r\nQuizás habéis leído esta historia en más de una ocasión, pero no como la cuenta Miller. \r\nY lo hace acompañado por el dibujante estrella Jim Lee (Superman: Por el mañana, Batman: Silencio), con lo que podemos asegurar que nos encontramos ante un éxito seguro.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,100,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007303872-vsiqwj.jpg','read',0,NULL,NULL,'2026-04-12 15:21:47','2026-04-12 16:11:44',239,19.97,'cartone','[{"name":"Frank Miller","role":"Guion"},{"name":"Jim Lee","role":"Dibujo"},{"name":"Scott Williams","role":"Tinta"},{"name":"James Sinclair","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2116,'Crisis en Tierras Infinitas','Crisis en Tierras Infinitas',NULL,NULL,'978-8-416-07057-2',NULL,'Marv Wolfman','George Perez',NULL,NULL,'ECC Ediciones',NULL,'2014-04-01',NULL,NULL,replace(replace('¡Mundos vivirán, mundos morirán y el Universo DC no volverá a ser el mismo! Una oleada de antimateria está arrasando el multiverso, y solo el misterioso Monitor parece conocer la causa y, lo que es más importante, la solución: reclutar a los héroes más poderosos de todas las tierras para hacer frente al enemigo más peligroso que jamás hayan conocido. ¿Bastará el empeño de Superman, el Capitán Marvel, Flash, Supergirl, los Nuevos Titanes y compañía para evitar la destrucción de los pocos mundos que quedan en pie?\r\nEn 1985, El guionista Marv Wolfman y el dibujante George Pérez celebraron los 50 años de historia de DC Comics con Crisis en tierras infinitas, un acontecimiento sin parangón protagonizado por todos los héroes y villanos de la casa que limpió cinco décadas de continuidad y allanó el terreno de cara a la llegada de nuevos lectores.\r\nEDICIÓN ORIGINAL: \r\n«Crisis on Infinite Earths» #1-12. DC Cómics.','\r',char(13)),'\n',char(10)),NULL,NULL,368,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007322151-93fu8f.jpg','unread',0,NULL,NULL,'2026-04-12 15:22:04','2026-04-12 15:22:04',NULL,47,'Grapa','[{"name":"Marv Wolfman","role":"Guion"},{"name":"George Perez","role":"Dibujo"},{"name":"Dick Giordano","role":"Tinta"},{"name":"Mike DeCarlo","role":"Tinta"},{"name":"Jerry Ordway","role":"Tinta"},{"name":"Anthony Tollin","role":"Color"},{"name":"Tom Ziuko","role":"Color"},{"name":"Carl Gafford","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2118,'Superman: Tierra Uno #1','Superman: Tierra Uno',1,NULL,'978-8-415-84429-7',NULL,'Joe Michael Straczynski','Shane Davis',NULL,NULL,'ECC Ediciones',NULL,'2013-05-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Superman Earth One vol. 1 USA\r\nUn Hombre de Acero para una nueva generación.\r\nTan solo creíais conocer su historia\r\nClark Kent es alguien diferente. Puede volar. Puede ver a través de las paredes. Quemar cosas con su mirada. Es un dios entre mortales. Pero es también alguien solo y sin ningún propósito. Como muchos jóvenes de 20 años, no sabe qué hacer con su vida. Podría elegir cualquier ámbito: deportes, ciencias, economía o periodismo. El cielo es el límite... siempre que oculte ante el mundo sus poderes y su verdadera identidad. Pero cuando los cielos se oscurecen con naves de planetas remotos, y la propia existencia de la Tierra se ve amenazada, Clark debe tomar la decisión más importante de su vida: revelar su presencia al mundo y sacrificar así toda esperanza de llevar una vida normal... o dejar que el mundo muera a su alrededor.','\r',char(13)),'\n',char(10)),NULL,NULL,136,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007377467-bgx826.jpg','read',0,NULL,NULL,'2026-04-12 15:23:01','2026-04-12 16:11:44',241,15.5,NULL,'[{"name":"Joe Michael Straczynski","role":"Guion"},{"name":"Shane Davis","role":"Dibujo"},{"name":"Sandra Hope","role":"Tinta"},{"name":"Bárbara Ciardo","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2119,'Batman: Tierra Uno #1','Batman: Tierra Uno',1,NULL,'978-8-415-62883-5',NULL,'Geoff Johns','Gary Frank',NULL,NULL,'ECC Ediciones',NULL,'2012-11-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman: Earth one USA \r\nAprovechando la total libertad implícita en la línea Tierra uno, Geoff Johns y Gary Frank ofrecen una nueva visión de los primeros años de Bruce Wayne como portador del manto de Batman, siendo esenciales a su mitología… ¡sin por ello dejar de sorprender al lector!','\r',char(13)),'\n',char(10)),NULL,NULL,160,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007407826-xw47tb.jpg','read',0,NULL,NULL,'2026-04-12 15:23:31','2026-04-12 16:11:44',240,15.96,NULL,'[{"name":"Geoff Johns","role":"Guion"},{"name":"Gary Frank","role":"Dibujo"},{"name":"Jonathan Sibal","role":"Tinta"},{"name":"Brad Anderson","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2120,'Wonder Woman. Tierra uno #1','Wonder Woman. Tierra uno',1,NULL,'978-8-416-79672-4',NULL,'Grant Morrison','Yanick Paquette',NULL,NULL,'ECC Ediciones',NULL,'2016-08-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Wonder Woman: Earth one USA\r\nDe las mentes magistrales de Grant Morrison (Crisis Final, El Multiverso) y Yanick Paquette (La Cosa del Pantano, Batman Inc.) llega el origen más provocador de Wonder Woman que hayas leído. Un relato único que rinde homenaje a su rica trayectoria.\r\nTras Batman, Superman y los Jóvenes Titanes, llega el momento de que los mejores autores aborden el mito de Wonder Woman desde una nueva óptica. Provocadora pero respetuosa, completamente moderna pero atemporal, esta nueva incorporación a la serie de novelas gráficas Tierra Uno de DC nos presenta el poder y el valor de Wonder Woman, la campeona de Isla Paraíso.','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007436062-9dtg2g.jpg','read',0,NULL,NULL,'2026-04-12 15:24:00','2026-04-12 16:11:44',242,15.95,NULL,'[{"name":"Grant Morrison","role":"Guion"},{"name":"Yanick Paquette","role":"Dibujo, Tinta"},{"name":"Nathan Fairbairn","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2121,'Wonder Woman. Tierra uno #2','Wonder Woman. Tierra uno',2,NULL,'978-8-417-78718-9',NULL,'Grant Morrison','Yanick Paquette',NULL,NULL,'ECC Ediciones',NULL,'2019-02-19',NULL,NULL,replace('EDICIÓN ORIGINAL: Wonder Woman: Earth One vol. 02 USA\rLa esperada secuela de la novela gráfica original que triunfó en The New York Times llega con Wonder Woman: Tierra Uno vol. 2, realizada por el aclamado equipo creativo que conforman Grant Morrison, Yanick Paquette y Nathan Fairbairn.\rDiana de Isla Paraíso se pasó años anhelando dejar atrás el único hogar que conocía para buscar aventuras más allá de sus costas. Ahora, tras un profético encuentro con Steve Trevor, piloto del ejército estadounidense, la guerrera amazona ha llegado al Mundo del Hombre, y está lista para lo que este le depare.\rPero ¿está preparado el mundo para Wonder Woman? El gobierno de Estados Unidos, un nido de disensión y conflictos ajenos a Diana, la considera un peligro para la sociedad. ¿Cómo llevará a cabo su misión de paz y amor en un mundo que se estorba a sí mismo? Claro está, siempre que no haya fuerzas insidiosas acechando...','\r',char(13)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007443758-j28wbw.jpg','read',0,NULL,NULL,'2026-04-12 15:24:05','2026-04-12 16:11:44',242,NULL,'Cartoné 144 pp','[{"name":"Grant Morrison","role":"Guion"},{"name":"Yanick Paquette","role":"Dibujo, Tinta"},{"name":"Nathan Fairbairn","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2122,'Green Lantern: Tierra Uno #1','Green Lantern: Tierra Uno',1,NULL,'978-8-417-53187-4',NULL,'Corinna Sara Bechko','Gabriel Hardman',NULL,NULL,'ECC Ediciones',NULL,'2019-01-15',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Green Lantern: Earth One Vol 1 1 (March 14, 2018) USA\r\nHal Jordan anhela descubrir el espacio, pero los días en que ser astronauta era sinónimo de vivir aventuras pasaron hace mucho tiempo. Efectuar prospecciones en asteroides para Ferris Galactic no le llena... pero por lo menos, no está en la Tierra, donde la tecnología y la cultura se han estancado. Cuando encuentra un poderoso anillo, Jordan también halla un destino que cumplir. Hay muchos mundos aparte del suyo que nunca había imaginado, pero esa revelación tiene un precio: el Cuerpo de Green Lanterns ha muerto, arrasado por unas máquinas de matar implacables llamadas Manhunters. Las posibilidades de restaurar el Cuerpo son casi nulas... ¡pero a Jordan lo entrenaron precisamente para conseguir lo imposible!','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007458844-qqsjke.jpg','read',0,NULL,NULL,'2026-04-12 15:24:22','2026-04-12 16:11:44',243,13.99,NULL,'[{"name":"Corinna Sara Bechko","role":"Guion"},{"name":"Gabriel Hardman","role":"Dibujo, Tinta"},{"name":"Jordan Boyd","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2123,'Green Lantern: Tierra Uno #2','Green Lantern: Tierra Uno',2,NULL,'978-8-418-56940-1',NULL,'Corinna Sara Bechko','Gabriel Hardman',NULL,NULL,'ECC Ediciones',NULL,'2021-02-23',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Green Lantern: Earth One Vol 1 2 (June 11, 2020) USA \r\nLa Tierra ya no está a solas en la galaxia, pero no todo el mundo está listo para tener compañía.\r\nCuando acusan al Centro de Mando Terrestre de haber atacado a una astronave llarana, Hal Jordan hace cuanto puede por enmendar los daños... y salvar a los científicos y diplomáticos tomados como rehenes. No obstante, se enfrenta a una fuerza todavía más mortífera: un nuevo enemigo dotado de tecnología poderosa aunque extrañamente familiar. Estos nuevos Yellow Lanterns combaten ahora a la misma amenaza Manhunter que los aliados de Hal en los Green Lantern Corps, pero... ¿qué quieren en realidad?\r\nAl renunciar sus compañeros Green Lanterns a ser miembros de los Corps en beneficio de los nuevos y más poderosos anillos creados por el Guardián, Hal se muestra escéptico. Y cuando los Yellow Lanterns atacan, las lealtades se dividen justo en el momento en que más deberían importar.\r\n¡Gabriel Hardman y Corinna Bechko (Invisible Republic, Star Wars: Legacy) presentan nuevas amenazas para el Cuerpo de Green Lanterns mientras Hal Jordan se ve puesto a prueba como nunca!','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007464825-gytiqq.jpg','read',0,NULL,NULL,'2026-04-12 15:24:25','2026-04-12 16:11:44',243,NULL,'Cartoné 144 pp','[{"name":"Corinna Sara Bechko","role":"Guion"},{"name":"Gabriel Hardman","role":"Guion, Dibujo"},{"name":"Jordan Boyd","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2124,'John Constantine. Hellblazer #10','John Constantine. Hellblazer',10,NULL,'978-8-416-40997-6',NULL,'Brian Azzarello','Dave Taylor',NULL,NULL,'ECC Ediciones',NULL,'2015-07-01',NULL,NULL,replace('696 pp  EDICIÓN ORIGINAL: Hellblazer núms. 146 a 174 y 250 USA, Secret Files: Hellblazer USA  \rEntre 2000 y 2002, Brian Azzarello (100 balas, Joker, Wonder Woman) ejerció como guionista regular de Hellblazer, embarcando a John Constantine en un viaje por la geografía norteamericana. Acompañado de dibujantes como Steve Dillon, Guy Davis o Richard Corben, firmó una etapa irrepetible, que ahora recopilamos en este tomo.','\r',char(13)),NULL,NULL,696,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007484419-otj29u.jpg','read',0,NULL,NULL,'2026-04-12 15:24:47','2026-04-12 16:11:44',244,NULL,'cartone','[{"name":"Dave Taylor","role":"Dibujo"},{"name":"Giuseppe Camuncoli","role":"Dibujo"},{"name":"Guy Davis","role":"Dibujo"},{"name":"Marcelo Frusin","role":"Dibujo"},{"name":"Rafael Grampá","role":"Dibujo"},{"name":"Richard Corben","role":"Dibujo"},{"name":"Steve Dillon","role":"Dibujo"},{"name":"Brian Azzarello","role":"Guion"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2125,'John Constantine. Hellblazer #11','John Constantine. Hellblazer',11,NULL,'978-8-416-74684-2',NULL,'Mike Carey','Chris Brunner',NULL,NULL,'ECC Ediciones',NULL,'2016-06-28',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Hellblazer núms. 175 a 199, Vertigo Secret Files: Hellblazer USA  \r\nEn septiembre de 2002, el guionista Mike Carey (Lucifer) se hizo cargo de Hellblazer iniciando una brillante etapa. Aliado con dibujantes de la talla de Marcelo Frusin, Leonardo Manco, Lee Bermejo y Steve Dillon, firmó casi medio centenar de episodios que recuperaremos a través de dos tomos imprescindibles.','\r',char(13)),'\n',char(10)),NULL,NULL,696,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007498086-1d418v.jpg','read',0,NULL,NULL,'2026-04-12 15:24:58','2026-04-12 16:11:44',244,NULL,'cartone','[{"name":"Mike Carey","role":"Guion"},{"name":"Chris Brunner","role":"Dibujo"},{"name":"Doug Alexander Gregory","role":"Dibujo"},{"name":"Jock","role":"Dibujo"},{"name":"Lee Bermejo","role":"Dibujo"},{"name":"Leonardo Manco","role":"Dibujo"},{"name":"Marcelo Frusin","role":"Dibujo"},{"name":"Steve Dillon","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2126,'John Constantine. Hellblazer #12','John Constantine. Hellblazer',12,NULL,'978-8-416-90153-1',NULL,'Mike Carey','Frazer Irving',NULL,NULL,'ECC Ediciones',NULL,'2016-10-28',NULL,NULL,'EDICIÓN ORIGINAL: Hellblazer núms. 200 a 215 y 229 USA, 9-11 - The World',NULL,NULL,696,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007499927-13ue2g.jpg','read',0,NULL,NULL,'2026-04-12 15:25:00','2026-04-12 16:11:44',244,NULL,'cartone','[{"name":"Mike Carey","role":"Guion"},{"name":"Frazer Irving","role":""},{"name":"Giuseppe Camuncoli","role":""},{"name":"John Paul Leon","role":""},{"name":"Leonardo Manco","role":""},{"name":"Marcelo Frusin","role":""},{"name":"Steve Dillon","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2127,'John Constantine. Hellblazer #4','John Constantine. Hellblazer',4,NULL,'978-8-416-30318-2',NULL,'Garth Ennis','Will Simpson',NULL,NULL,'ECC Ediciones',NULL,'2014-12-31',NULL,NULL,replace(replace('Contiene Hellblazer #41-55 USA\r\n392 páginas\r\nEn mayo de 1991, el guionista irlandés Garth Ennis irrumpe en las páginas de Hellblazer dejando al protagonista, literalmente, sin aliento. John Constantine contrae un cáncer terminal y está dispuesto a todo Con tal de salvarse: suplicar, arrastrarse e incluso pactar con el diablo. Pero, aunque logre sobrevivir a la enfermedad, el destino le tiene reservados nuevos desafíos. Por un lado, vampiros, fantasmas y posesiones infernales. por otro, la aparición en su vida del mayor de todos los retos: el amor.','\r',char(13)),'\n',char(10)),NULL,NULL,696,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007510992-uct4eo.jpg','read',0,NULL,NULL,'2026-04-12 15:25:11','2026-04-12 16:11:16',244,NULL,'cartone','[{"name":"Garth Ennis","role":"Guion"},{"name":"Will Simpson","role":"Dibujo, Tinta"},{"name":"Mark Pennington","role":"Tinta"},{"name":"Tom Ziuko","role":"Color"},{"name":"Malcolm Jones Iii","role":"Tinta"},{"name":"Tom Sutton","role":"Tinta"},{"name":"Stan Woch","role":"Tinta"},{"name":"Mike Hoffman","role":"Dibujo"},{"name":"Steve Dillon","role":"Dibujo, Tinta"},{"name":"Sean Phillips","role":"Dibujo"}]');
