INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2129,'John Constantine. Hellblazer #6','John Constantine. Hellblazer',6,NULL,'978-8-416-47565-0',NULL,'Garth Ennis','John Higgins',NULL,NULL,'ECC Ediciones',NULL,'2015-08-25',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Hellblazer núms. 72 a 83 y 129 a 133 USA, Heartland USA   \r\nEste volumen pone punto final a la etapa de Garth Ennis al frente de Hellblazer recopilando los episodios del 72 al 83 y del 129 al 133, además del especial Heartland. En ellos, el guionista irlandés contó con un soberbio equipo artístico compuesto por Steve Dillon (Predicador), Will Simpson (Batman: Enloquecidos), Peter Snejbjerg (JSA de Geoff Johns) y John Higgins (Watchmen).','\r',char(13)),'\n',char(10)),NULL,NULL,696,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007515052-2v9vgr.jpg','read',0,NULL,NULL,'2026-04-12 15:25:16','2026-04-12 16:11:16',244,NULL,'cartone','[{"name":"Garth Ennis","role":"Guion"},{"name":"John Higgins","role":"Dibujo"},{"name":"Peter Snejbjerg","role":"Dibujo"},{"name":"Steve Dillon","role":"Dibujo"},{"name":"Will Simpson","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2130,'Grandes Autores de Batman: Doug Moench y Kelley Jones #2','Grandes Autores de Batman: Doug Moench y Kelley Jones',2,NULL,'978-8-416-25555-9',NULL,'Doug Moench','Kelley Jones',NULL,NULL,'ECC Ediciones',NULL,'2014-11-28',NULL,NULL,replace(replace('Contiene Batman #525, 527 a 528, 530 a 532 y 535 USA\r\nGracias a un pacto con el demonio Nerón, Mr. Frío acumula más poder que nunca. Dos Caras huye del Asilo Arkham para imponer su particular noción de justicia. Y un hombre desfigurado y su simio infunden el terror entre la comunidad científica. Extraños casos que centran la atención de Batman, quien contando con la colaboración de Deadman, también tendrá que investigar una serie de crímenes relacionados con reliquias incas.\r\nTras la publicación de Fundido en negro, la línea Grandes autores de Batman sigue reivindicando la aportación de Doug Moench y Kelley Jones a la mitología del Caballero Oscuro. Una etapa para el recuerdo, tan misteriosa como estremecedora, inspirada en los clásicos de terror y del género negro.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007544555-hqqpg8.jpg','read',0,NULL,NULL,'2026-04-12 15:25:47','2026-04-12 16:11:16',245,15.96,'cartone','[{"name":"Doug Moench","role":"Guion"},{"name":"Kelley Jones","role":"Dibujo"},{"name":"Scott Beatty","role":"Tinta"},{"name":"Gregory Wright","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2131,'Superman: La muerte de Superman','Superman: La muerte de Superman',NULL,NULL,'978-8-416-74642-2',NULL,'Dan Jurgens','Dan Jurgens',NULL,NULL,'ECC Ediciones',NULL,'2015-07-28',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Superman: The Man of Steel núms. 17,18 y 19, Superman núms. 73, 74 y 75, Adventures of Superman núms. 496 y 497, Action Comics núms. 683 y 684 USA, Justice League of America núm. 69 USA\r\nEn 1992, el mundo se vistió de luto. Superman, el primer superhéroe de la historia, moría a manos de Juicio Final en lo que acabó siendo uno de los cómics más vendidos de la historia. Millones de ejemplares en un solo día confirmaron el interés mediático que levantó esta historia, perteneciente a una campaña de marketing impresionante por parte de DC Comics.','\r',char(13)),'\n',char(10)),NULL,NULL,168,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007567044-w92p8n.jpg','read',0,NULL,NULL,'2026-04-12 15:26:08','2026-04-12 16:11:16',NULL,17.5,'Rústica','[{"name":"Dan Jurgens","role":"Guion, Dibujo"},{"name":"Jerry Ordway","role":"Guion"},{"name":"Louise Jones Simonson","role":"Guion"},{"name":"Roger Stern","role":"Guion"},{"name":"Jackson Guice","role":"Dibujo"},{"name":"Jon Bogdanove","role":"Dibujo"},{"name":"Tom Grummett","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2132,'Batman. Gritos en la noche','Batman. Gritos en la noche',NULL,NULL,'978-8-416-15258-2',NULL,'Archie Goodwin','Scott Hampton',NULL,NULL,'ECC Ediciones',NULL,'2014-07-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Batman: Night Cries USA.\r\nEn los albores de su cruzada contra el crimen, el Hombre Murciélago investiga una serie de asesinatos cuya brutalidad ha alarmado a los ciudadanos de Gotham City. Atípico caso en manos de un James Gordon recién nombrado comisario del Departamento de Policía, que tendrá que lidiar con la responsabilidad inherente a su nuevo cargo... y con la dificultad de superar traumas del pasado.\r\nEn 1992, Archie Goodwin —Batman: Black and White— y Scott Hampton —Lucifer— crearon Batman: Gritos en la noche, aclamada novela gráfica que no solo sorprendió por su estilo pictórico, sino también por la cruda reflexión que plantea sobre los efectos de la exposición a la violencia.','\r',char(13)),'\n',char(10)),NULL,NULL,96,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007585482-jvqhgu.jpg','unread',0,NULL,NULL,'2026-04-12 15:26:28','2026-04-12 15:26:28',NULL,23.95,NULL,'[{"name":"Archie Goodwin","role":"Guion"},{"name":"Scott Hampton","role":"Dibujo"}]');
