INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2135,'Grandes Autores de Vertigo #1','Grandes Autores de Vertigo',1,NULL,'978-8-416-47533-9',NULL,'Neil Gaiman','Dave McKean',NULL,NULL,'ECC Ediciones',NULL,'2015-07-29',NULL,NULL,replace(replace('Recopila seis historias publicadas originalmente en Hellblazer #27 y 40 USA, Sandman #46 USA, Fast Forward #1 USA, Sandman Dust Covers y Dream State: The collected Dreaming covers.\r\n&quot;Este primer volumen de la línea Grandes autores de Vertigo, recopila una selección de trabajos del influyente artista Dave McKean: A Glass of Water, colaboración con Grant Morrison largamente descatalogada; Hold me y The Magus, con guiones de Neil Gaiman y Jamie Delano; y tres inolvidables historias de Sandman: Death Talks about Life, The Last Sandman Story y la hasta ahora inédita Fish out of Water.&quot;','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007658085-r0387k.jpg','read',0,NULL,NULL,'2026-04-12 15:27:41','2026-04-12 16:11:16',246,13.95,'cartone','[{"name":"Dave McKean","role":"Dibujo, Tinta"},{"name":"Neil Gaiman","role":"Guion"},{"name":"Grant Morrison","role":"Guion"},{"name":"Jamie Delano","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2136,'Grandes Autores de Vertigo #2','Grandes Autores de Vertigo',2,NULL,'978-8-416-51899-9',NULL,'Bill Willingham','Richard Corben',NULL,NULL,'ECC Ediciones',NULL,'2015-12-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Weird War Tales 1, Gangland 2, Heartthrobs 3, Strange Adventures 3, Just Imagine Stan Lee With Walter Simonson Creating Sandman, Swamp Thing 7, 8 y 20, MASKS Too hot For TV!, SOLO núm. 2 USA, American Splendor núm. 2 USA, House of Mystery núm. 16 USA, Men of War núm. 6 USA , Flinch núm. 1 USA \r\nDesde 1997, el artista Richard Corben ha creado un puñado de joyas para el sello Vertigo que ECC recopila ahora en una antología indispensable. Este volumen incluye el cómic monográfico Solo, sus episodios como artista invitado en la serie Swamp Thing y sus páginas en revistas tan heterogéneas como House of Mistery, American Splendor, Strange Adventures o Weird War Tales. Con la energía que caracteriza su trabajo, Corben imprime en cada imagen el sello inconfundible de un creador magistral.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007668825-s6st5j.jpg','read',0,NULL,NULL,'2026-04-12 15:27:50','2026-04-12 16:11:16',246,13.95,'cartone','[{"name":"Bill Willingham","role":"Guion"},{"name":"Bruce Jones","role":"Guion"},{"name":"Harvey Pekar","role":"Guion"},{"name":"Joe R. Lansdale","role":"Guion"},{"name":"John Arcudi","role":"Guion"},{"name":"Joshua Dysart","role":"Guion"},{"name":"Marc Andreyko","role":"Guion"},{"name":"Michael Uslan","role":"Guion"},{"name":"Simon Revelstroke","role":"Guion"},{"name":"Will Pfeifer","role":"Guion"},{"name":"Richard Corben","role":"Guion, Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2137,'Grandes Autores de Vertigo #3','Grandes Autores de Vertigo',3,NULL,'978-8-416-66088-9',NULL,'Bruce Jones','Frank Quitely',NULL,NULL,'ECC Ediciones',NULL,'2016-03-30',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: The Big Book of... Weirdos, Death, Conspiracies, Freaks, Little Criminals, Hoaxes, Losers y Martyrs USA, Weird War Tales núm. 3 USA, Gangland núm. 1 USA, Heartthrobs núm. 2 USA, Strange Adventures núm. 1 USA, Flinch núms. 1 y 12 USA, Sandman: Endless Nights USA \r\nDurante la década de los noventa, Frank Quitely firmó un puñado de historietas cortas para los sellos Vertigo y Paradox Press en en compañía de guionistas de la talla de Grant Morrison o Bruce Jones. Hoy, ECC reúne en un solo volumen esas joyas dispersas incluyendo, además, una historia de Destino escrita por Neil Gaiman.','\r',char(13)),'\n',char(10)),NULL,NULL,NULL,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007671568-g6eh5i.jpg','read',0,NULL,NULL,'2026-04-12 15:27:52','2026-04-12 16:11:16',246,13.95,'cartone','[{"name":"Frank Quitely","role":"Dibujo"},{"name":"Bruce Jones","role":"Guion"},{"name":"Carl Posey","role":"Guion"},{"name":"Bronwyn Carlton","role":"Guion"},{"name":"Doug Moench","role":"Guion"},{"name":"Gahan Wilson","role":"Guion"},{"name":"George Hagenauer","role":"Guion"},{"name":"Paul M. Yellovich","role":"Guion"},{"name":"Paul Kirchner","role":"Guion"},{"name":"John Wagner","role":"Guion"},{"name":"Grant Morrison","role":"Guion"},{"name":"Doselle Young","role":"Guion"},{"name":"Ilya","role":"Guion"},{"name":"Robert Rodi","role":"Guion"},{"name":"Jen Van Meter","role":"Guion"},{"name":"Neil Gaiman","role":"Guion"},{"name":"Matt Hollingsworth","role":"Color"},{"name":"Daniel Vozzo","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2138,'Grandes Autores de Vertigo #4','Grandes Autores de Vertigo',4,NULL,'978-8-416-71168-0',NULL,'Brian Azzarello','Danijel Zezelj',NULL,NULL,'ECC Ediciones',NULL,'2016-04-28',NULL,NULL,'64 pp. PVP 8,95€   EDICIÓN ORIGINAL: Weird War Tales núm. 1 USA, Gangland núm. 1 USA, Flinch núms. 10 y 13 USA, Strange Adventures núm. 4 USA, Heartthrobs núm. 2 USA  En 1997, Brian Azzarello (100 balas, Joker, Caballero Oscuro III: La raza superior) colaboró por primera vez con el sello Vertigo sentando las bases de una carrera meteórica. Este volumen recoge una selección de historietas publicadas originalmente en cabeceras tan dispares como Flinch, Gangland, Hearttrobs o Strange Adventures, incluyendo su primera historieta para Vertigo',NULL,NULL,64,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007673714-ogxd2w.jpg','read',0,NULL,NULL,'2026-04-12 15:27:54','2026-04-12 16:11:16',246,8.95,'cartone','[{"name":"Brian Azzarello","role":"Guion"},{"name":"Danijel Zezelj","role":"Dibujo"},{"name":"Esad Ribic","role":"Dibujo"},{"name":"James Romberger","role":"Dibujo"},{"name":"Javier Pulido","role":"Dibujo"},{"name":"Tim Bradstreet","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2139,'Batman. Pingüino: Dolor y prejuicio','Batman. Pingüino: Dolor y prejuicio',NULL,NULL,'978-8-415-62864-4',NULL,'Gregg Hurwitz','Szymon Kudranski',NULL,NULL,'ECC Ediciones',NULL,'2012-10-01',NULL,NULL,replace(replace('Edición original: Penguin: Pain & Prejudice USA\r\nEsta es la historia de Cassandra, una joven invidente que acaba de encontrar al hombre de su vida. Lástima que su príncipe azul sea un monstruo degenerado. Cassandra se ha enamorado del criminal que todos conocemos por el nombre de Pingüino. ¿Descubrirá ella la verdad a tiempo o sucumbirá ante la maldad de su amado? \r\nEl aclamado novelista Gregg Hurwitz y el espectacular artista Szymon Kudranski actualizan el origen del clásico villano de Batman en un relato que no ha dejado indiferente a nadie.\r\nHISTORIAS: Mundo frio / Niño precioso / Amor ciego / Ejercicio práctico / Toque mortal','\r',char(13)),'\n',char(10)),NULL,NULL,120,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007692473-e1f6j5.jpg','read',0,NULL,NULL,'2026-04-12 15:28:13','2026-04-12 16:11:16',NULL,13.95,NULL,'[{"name":"Gregg Hurwitz","role":"Guion"},{"name":"Szymon Kudranski","role":"Dibujo, Tinta"},{"name":"John Kalisz","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2140,'Batman: Noel','Batman: Noel',NULL,NULL,'978-8-415-74803-8',NULL,'Lee Bermejo','Lee Bermejo',NULL,NULL,'ECC Ediciones',NULL,'2012-11-01',NULL,NULL,replace(replace('Contiene: Batman: Nöel USA.\r\nMientras el Caballero Oscuro persigue a su más odiado enemigo a través del gélido paisaje de Gotham City, una extraña serie de acontecimientos amenaza con arrebatarle el alma... para siempre.\r\nEscrita y dibujada por la estrella del cómic Lee Bermejo, &quot;Batman: Noel&quot; relata un cuento de Navidad muy distinto a los habituales.','\r',char(13)),'\n',char(10)),NULL,NULL,112,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007707251-zk12wd.jpg','read',0,NULL,NULL,'2026-04-12 15:28:29','2026-04-12 16:11:16',NULL,19.97,NULL,'[{"name":"Lee Bermejo","role":"Guion, Dibujo, Tinta"},{"name":"Bárbara Ciardo","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2141,'Lex Luthor','Lex Luthor',NULL,NULL,'978-8-415-99073-4',NULL,'Brian Azzarello','Lee Bermejo',NULL,NULL,'ECC Ediciones',NULL,'2014-01-31',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Lex Luthor: Man of Steel núms. 1 a 5 USA, Absolute Luthor/Joker USA (material extra\r\nInfluyente y poderoso magnate poseedor de una mente privilegiada, Lex Luthor está dispuesto a emplear los inagotables recursos a su alcance para compartir con la opinión pública su certeza: que lejos de ser el proclamado defensor de “la verdad, la justicia y el modo de vida americano”, el alienígena conocido como Superman representa una amenaza para la existencia de la raza humana.\r\nCon la obra recopilada en el presente tomo, publicada originalmente en forma de miniserie de cinco entregas, Brian Azzarello y Lee Bermejo —Batman: Fuego cruzado, Joker, Antes de Watchmen: Rorschach— exploraron la psique del archienemigo del Hombre de Acero. Una oportunidad única para comprender las motivaciones y la perspectiva de este carismático megalómano, por méritos propios convertido en uno de los grandes antagonistas del mundo del cómic','\r',char(13)),'\n',char(10)),NULL,NULL,144,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007730686-r37bgq.jpg','read',0,NULL,NULL,'2026-04-12 15:28:51','2026-04-12 16:11:16',NULL,15.95,NULL,'[{"name":"Brian Azzarello","role":""},{"name":"Lee Bermejo","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2142,'Joker','Joker',NULL,NULL,'978-8-467-47743-6',NULL,'Brian Azzarello','Lee Bermejo',NULL,NULL,'Planeta Cómic',NULL,'2009-05-01',NULL,NULL,'Empeñado en labrarse una reputación dentro del crimen organizado de Gotham City, Jonny Frost se presenta voluntario para recoger al Joker, a punto de concluir su internamiento en el Hospital Psiquiátrico de Arkham. Rencoroso, vengativo y desbocado, el Príncipe Payaso del Crimen desata una oleada de violencia y destrucción orientada a un único objetivo: recuperar el trono usurpado durante su ausencia. A través de los ojos de un secuaz del tres al cuarto, Brian Azzarello y Lee Bermejo —Batman: Fuego cruzado, Lex Luthor, Antes de Watchmen: Rorschach— aprovechan las páginas de la novela gráfica Joker para retratar los bajos fondos gothamitas y reinterpretar de forma tan sorprendente como perturbadora al enemigo por excelencia del Hombre Murciélago.',NULL,NULL,128,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007752397-76s6ds.jpg','read',0,NULL,NULL,'2026-04-12 15:29:14','2026-04-12 16:11:16',NULL,11.43,NULL,'[{"name":"Brian Azzarello","role":"Guion"},{"name":"Mick Gray","role":"Tinta"},{"name":"Patricia Mulvihill","role":"Color"},{"name":"Lee Bermejo","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2143,'Corazón de Arlequín','Corazón de Arlequín',NULL,NULL,'978-8-416-58186-3',NULL,'Neil Gaiman','John Bolton',NULL,NULL,'ECC Ediciones',NULL,'2016-01-27',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Harlequin Valentine USA          Quienes han pasado a solas el día de San Valentín son conscientes de que esa fría festividad de febrero puede ser muy difícil de soportar. Los galardonados autores Neil Gaiman (Sandman) y John Bolton (Books of Magic) quieren que sepáis que lo único que hace falta es un cuchillo para cortar carne, un tenedor y un frasco de kétchup de buena calidad...\r\nEn esta revisión contemporánea de un mito clásico de la Commedia dell’arte, repleto de payasadas y de amor tan servil como inútil, Gaiman y Bolton actualizan el relato de Arlequín y Colombina. Arlequín, un mágico bufón que debe asumir la carga de un corazón que pesa demasiado, persigue a su sensible e inconsciente Colombina por las calles de la ciudad, tras haberle entregado su corazón por voluntad propia. Consumido por el amor, el impulsivo payaso verá su corazón arrastrado por todo el municipio, con una fascinante sorpresa final que dota de un giro moderno al relato.','\r',char(13)),'\n',char(10)),NULL,NULL,40,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007773786-fvk0uv.jpg','unread',0,NULL,NULL,'2026-04-12 15:29:37','2026-04-12 15:29:37',NULL,24.95,NULL,'[{"name":"Neil Gaiman","role":"Guion"},{"name":"John Bolton","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2144,'Criaturas de la Noche','Criaturas de la Noche',NULL,NULL,'978-8-416-74621-7',NULL,'Neil Gaiman','Michael Zulli',NULL,NULL,'ECC Ediciones',NULL,'2016-05-27',NULL,NULL,'EDICIÓN ORIGINAL: Creatures of the night USA   Magia y misterio aguardan tras las páginas de esta obra maestra de Neil Gaiman (Sandman). Adaptada al cómic por el veterano pintor Michael Zulli (La verdad sobre el caso de la desaparición de la Srta. Finch), este tomo contiene dos bellos e inquietantes relatos de animales enigmáticos y su sobrenatural influencia en el mundo de los humanos.',NULL,NULL,48,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007795482-yw89x5.jpg','unread',0,NULL,NULL,'2026-04-12 15:29:58','2026-04-12 15:29:58',NULL,9,NULL,'[{"name":"Neil Gaiman","role":"Guion"},{"name":"Michael Zulli","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2145,'La verdad sobre el caso de la desaparición de la Srta. Finch','La verdad sobre el caso de la desaparición de la Srta. Finch',NULL,NULL,'978-8-416-79686-1',NULL,'Neil Gaiman','Michael Zulli',NULL,NULL,'ECC Ediciones',NULL,'2016-07-29',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: The Facts in the Case of the Departure of Miss Finch USA\r\nÚnete a un grupo de amigos, con la severa Srta. Finch a remolque, y adéntrate en las húmedas cavernas para contemplar un espectáculo subterráneo de un circo imposible. ¡Entra, resguárdate de la incesante lluvia, y sé testigo de este extraño mundo de vampiros, maestros de ceremonias, ilusiones y el Gabinete de los Deseos Cumplidos!\r\nCon títulos como Misterios de un asesinato, Criaturas de la noche y Corazón de arlequín ya en nuestro catálogo, recuperamos esta adaptación del relato homónimo de Neil Gaiman. Publicado originalmente en la antología Humo y espejos, es ahora adaptado por Michael Zulli y Todd Klein, aprehendiendo toda la magia del creador de Sandman.','\r',char(13)),'\n',char(10)),NULL,NULL,56,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007815825-h1di7l.jpg','unread',0,NULL,NULL,'2026-04-12 15:30:19','2026-04-12 15:30:19',NULL,24.95,'tapa dura','[{"name":"Neil Gaiman","role":"Guion"},{"name":"Michael Zulli","role":"Dibujo"},{"name":"Todd Klein","role":"Guion"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2146,'El libro de cuentos de los pequeños Eternos','El libro de cuentos de los pequeños Eternos',NULL,NULL,'978-8-416-99815-9',NULL,'Neil Gaiman','Jill Thompson',NULL,NULL,'ECC Ediciones',NULL,'2017-02-14',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: The Little Endless Storybook USA     \r\nARGUMENTO: Tras la primera aparición de los pequeños Eternos, en las páginas de Sandman núm. 40 USA (Sandman núm. 6: Fábulas y reflejos), lectores de todo el mundo esperaban con ganas nuevas aventuras de estas sorprendentes versiones de Sueño y su familia. ¡Una petición que se cumplió al fin en 2001, en un especial que recuperamos ahora en formato cartoné! La multipremiada artista Jill Thompson narra desde un punto de vista único una aventura centrada en la mascota de la pequeña Delirio.\r\nSandman es, con razón, una de las obras más aplaudidas de la historia del cómic, presentada por ECC Ediciones a través de una cuidada edición de 10 tomos encuadernados en cartoné. Una rica combinación de mitos modernos y fantasía oscura donde la ficción contemporánea, el drama histórico y la leyenda se entrelazan a la perfección gracias a los elegantes guiones de Neil Gaiman y al trabajo de un variado y talentoso elenco de dibujantes. Para completar el trabajo de Gaiman en la serie, en nuestro catálogo podéis encontrar otros especiales de la talla de Sandman: Noches eternas, Sandman: Muerte o Sandman: Cazadores de sueños, a los que ahora se une la reinterpretación más divertida de los Eternos.','\r',char(13)),'\n',char(10)),NULL,NULL,64,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007835218-9828fn.jpg','read',0,NULL,NULL,'2026-04-12 15:30:37','2026-04-12 16:11:16',NULL,8.95,NULL,'[{"name":"Neil Gaiman","role":"Guion"},{"name":"Jill Thompson","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2147,'Batman. El regreso del Caballero Oscuro: La última cruzada','Batman. El regreso del Caballero Oscuro: La última cruzada',NULL,NULL,'978-8-416-84023-6',NULL,'Frank Miller','John Romita Jr.',NULL,NULL,'ECC Ediciones',NULL,'2016-08-29',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: The Dark Knight Returns: The Last Crusade USA\r\nFalta una década para que transcurran los hechos de El regreso del Caballero Oscuro, la obra cumbre del Batman de los años ochenta… y el héroe de Gotham, que aún no se ha retirado, va a vivir uno de los acontecimientos más dramáticos de su carrera, uno relacionado con el Joker y Robin.\r\nFrank Miller retoma su particular visión de la mitología del Caballero Oscuro en un especial que complementa a la perfección la flamante serie limitada Caballero Oscuro III: La raza superior, donde también forma equipo con el guionista Brian Azzarello (100 balas). En este volumen, el encargado de dibujar la historia no es otro que John Romita Jr. (Superman), que se encarga por primera vez de un cómic protagonizado en solitario por Batman.','\r',char(13)),'\n',char(10)),NULL,NULL,64,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007857462-bym3xd.jpg','unread',0,NULL,NULL,'2026-04-12 15:31:00','2026-04-12 15:31:00',NULL,24.95,'tapa dura','[{"name":"Frank Miller","role":"Guion"},{"name":"Brian Azzarello","role":"Guion"},{"name":"John Romita Jr.","role":"Dibujo"},{"name":"Peter Steigerwald","role":"Tinta, Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2148,'Nieve, Cristal, Manzanas','Nieve, Cristal, Manzanas',NULL,NULL,'978-8-413-41794-3',NULL,'Neil Gaiman','Colleen Doran',NULL,NULL,'Planeta Cómic',NULL,'2021-11-10',NULL,NULL,replace(replace('Una reina no tan malvada siente miedo de su monstruosa hijastra y está decidida a ahuyentar a esta criatura y a salvar su reino de un mundo donde no existen los finales felices.\r\nUNA ESCALOFRIANTE ADAPTACIÓN DEL CUENTO DE «BLANCANIEVES» EN CLAVE DE FANTASÍA POR LOS AUTORES SUPERVENTAS NEIL GAIMAN Y COLLEEN DORAN.\r\nColleen Doran (El puente del troll) adapta al cómic la obra de Neil Gaiman (American Gods), el escritor superventas ganador de los premios Hugo, Bram Stoker, Locus, World Fantasy y Nebula.\r\n«Al igual que Ray Bradbury antes que él, [Neil Gaiman] escribe encantadoras historias de miedo, cuentos de hadas e historias fantásticas que resultan familiares y fabulosas, historias que nunca son exactamente lo que el lector se espera... En Nieve, cristal, manzanas explora las escalofriantes posibilidades de darle la vuelta al mito de &quot;Blancanieves&quot;». —THE A.V. CLUB','\r',char(13)),'\n',char(10)),NULL,NULL,56,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007871375-5rf2k3.jpg','unread',0,NULL,NULL,'2026-04-12 15:31:12','2026-04-12 15:31:12',NULL,16.95,NULL,'[{"name":"Neil Gaiman","role":"Guion"},{"name":"Colleen Doran","role":"Guion, Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2149,'Universo Sandman - DC Black Label','Universo Sandman - DC Black Label',NULL,NULL,'978-8-418-04303-1',NULL,'Kat Howard','Nalo Hopkinson',NULL,NULL,'ECC Ediciones',NULL,'2019-10-29',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: The Sandman Universe núm. 1 USA \r\nEl sueño continúa...\r\nAlgo extraño sucede en el Sueño, donde se ha abierto una grieta que amenaza la estabilidad del reino. Un fenómeno preocupante, al que se suman cambios, transformaciones y desapariciones inesperadas.\r\nAnte tal situación, Lucien requiere la presencia del cuervo Matthew, a quien encomienda la importante misión de encontrar al sucesor de Morfeo: Daniel, ausente de su reino por razones personales.\r\nEn su viaje, que le llevará del Sueño al mundo despierto, Matthew se topa con personajes llamados a desempeñar un papel fundamental en historias incipientes y apasionantes: la misteriosa Dora, quien todavía recuerda una promesa incumplida por Morfeo; el joven Tim Hunter, que bien podría convertirse en el mago más poderoso del mundo… o en su más temible villano; Latoya, Maggie, Lumi y Habibi, cuyos caminos parecen destinados a cruzarse con el de Erzulie, responsable de la Casa de los susurros; y el mismísimo Lucifer, quien se dispone a emprender su propia búsqueda.\r\n¿Conseguirá Matthew encontrar a Daniel? De la respuesta a esta pregunta depende el futuro del Sueño…\r\nEl aclamado Neil Gaiman (American Gods, Buenos presagios) lidera un equipo creativo integrado por los guionistas Dan Watters, Kat Howard, Nalo Hopkinson y Simon Spurrier, y los dibujantes Bilquis Evely, Sebastian Fiumara, Max Fiumara, Tom Fowler y Domonike “Domo” Stanton. Juntos, dan forma a este especial en el que tienen cabida sueños, pesadillas y maravillosos personajes que habitan un universo compartido. Universo Sandman es la fascinante carta de presentación de cuatro series llamadas a continuar y enriquecer el legado el legado de Sandman: El Sueño, Lucifer, Los libros de la magia y La Casa de los Susurros.','\r',char(13)),'\n',char(10)),NULL,NULL,56,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007905827-u35uai.jpg','read',0,NULL,NULL,'2026-04-12 15:31:47','2026-04-12 16:11:16',NULL,10.95,'grapa','[{"name":"Kat Howard","role":"Guion"},{"name":"Nalo Hopkinson","role":"Guion"},{"name":"Neil Gaiman","role":"Guion"},{"name":"Simon Spurrier","role":"Guion"},{"name":"Bilquis Evely","role":""},{"name":"Dominike Stanton","role":""},{"name":"Mat Lopes","role":""},{"name":"Max Fiumara","role":""},{"name":"Sebastian Fiumara","role":""},{"name":"Tom Fowler","role":""},{"name":"Dan Watters","role":""}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2150,'Orquídea Negra','Orquídea Negra',NULL,NULL,'978-8-416-84044-1',NULL,'Neil Gaiman','Dave McKean',NULL,NULL,'ECC Ediciones',NULL,'2016-08-29',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Black Orchid USA                  En una sala de juntas anónima, una superheroína recibe un disparo en la cabeza. Las llamas consumen su cuerpo, y su asesino queda libre. \r\nAsí comienza Orquídea Negra, de Neil Gaiman y Dave McKean, una de las creaciones más notables y transformadoras del cómic. Esta historia, que deconstruye y resucita todo un género, narra las asombrosas vidas de Susan Linden y encarna la nueva madurez en la narración gráfica que revolucionó el medio. Ahora, por primera vez, esta obra fundamental queda recopilada en una edición que incluye una profunda introducción del periodista Mikal Gilmore, así como una sección especial con bocetos inéditos y textos preliminares de Neil Gaiman.','\r',char(13)),'\n',char(10)),NULL,NULL,176,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007935348-an1j8a.jpg','unread',0,NULL,NULL,'2026-04-12 15:32:16','2026-04-12 15:32:16',NULL,17.95,'Cartone','[{"name":"Neil Gaiman","role":"Guion"},{"name":"Dave McKean","role":"Dibujo"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2151,'Misterios de un asesinato','Misterios de un asesinato',NULL,NULL,'978-8-416-47534-6',NULL,'Neil Gaiman','Philip Craig Russell',NULL,NULL,'ECC Ediciones',NULL,'2015-07-29',NULL,NULL,replace(replace('Edición original: Murder Mysteries USA\r\nUn solitario hombre que se encuentra de paso en la ciudad californiana de Los Ángeles está a punto de escuchar una misteriosa historia… ¡sobre el primer asesinato cometido en el paraíso!\r\nPocos autores como P. Craig Russell han sabido plasmar sobre el papel de dibujo el imaginario de Neil Gaiman. Tras participar en la multipremiada Sandman, a lo largo de los años ha tenido ocasión de adaptar diferentes historias en prosa del popular guionista y escritor, siendo uno de los títulos más representativos Misterios de un asesinato','\r',char(13)),'\n',char(10)),NULL,NULL,112,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007953105-xyu1jb.jpg','unread',0,NULL,NULL,'2026-04-12 15:32:34','2026-04-12 15:32:34',NULL,13.5,NULL,'[{"name":"Neil Gaiman","role":"Guion"},{"name":"Philip Craig Russell","role":"Dibujo, Tinta"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2152,'Batman: Especial Detective Comics 27 - 75 Años de Batman','Batman: Especial Detective Comics 27 - 75 Años de Batman',NULL,NULL,'978-8-416-07073-2',NULL,'Bill Finger','Bryan Hitch',NULL,NULL,'ECC Ediciones',NULL,'2014-05-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Detective Comics núm. 27 USA (1939), Detective Comics núm. 27 USA (2014)\r\n¿Qué tiene de especial Batman para haber fascinado a generaciones de historietistas y lectores? Con motivo del 75 aniversario del Caballero Oscuro, los mejores autores de la industria del cómic rinden su particular homenaje a un personaje convertido en icono de la cultura popular, analizando su naturaleza y evolución a través del tiempo.\r\nAlgunos de los artistas más conocidos del mundo del cómic se unen para —en palabras del editor Mike Marts— participar en “una celebración del Hombre Murciélago, una retrospectiva de las grandes historias del pasado, y un adelanto de lo que el futuro le deparará”.Tributo que se completa con una galería de ilustraciones y portadas conmemorativas en la que participa el mismísimo Frank Miller, y con la inclusión de El caso de los magnates de la química (1939), aventura con la que Bob Kane inició la leyenda.','\r',char(13)),'\n',char(10)),NULL,NULL,96,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776007971685-m6y2to.jpg','read',0,NULL,NULL,'2026-04-12 15:32:54','2026-04-12 16:11:16',NULL,12.99,NULL,'[{"name":"Bill Finger","role":"Guion"},{"name":"Bob Kane","role":"Guion"},{"name":"Brad Meltzer","role":"Guion"},{"name":"Francesco Francavilla","role":"Guion"},{"name":"Gregg Hurwitz","role":"Guion"},{"name":"Mike W. Barr","role":"Guion"},{"name":"Peter J. Tomasi","role":"Guion"},{"name":"Scott Snyder","role":"Guion"},{"name":"Bryan Hitch","role":"Dibujo"},{"name":"Guillem March","role":"Dibujo"},{"name":"Ian Bertram","role":"Dibujo"},{"name":"Neal Adams","role":"Dibujo"}]');
