INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2154,'Especial More Fun Comics (1941-2015): 75 años de Green Arrow','Especial More Fun Comics (1941-2015): 75 años de Green Arrow',NULL,NULL,'978-8-416-58172-6',NULL,'Alan Moore','Dick Dillin',NULL,NULL,'ECC Ediciones',NULL,'2016-03-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: More Fun Comics núm. 73 USA, Adventure Comics núm. 250 USA, Justice League Of America núm. 75 USA, Detective Comics núms. 549-550 USA, Green Lantern núms. 85-86 USA, Green Arrow núm. 75 USA, Green Arrow núm. 33 USA \r\nMort Weisinger, Bill Finger, Denny O','\r',char(13)),'\n',char(10)),NULL,NULL,176,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776008012043-lpwq3a.jpg','read',0,NULL,NULL,'2026-04-12 15:33:34','2026-04-12 16:11:16',NULL,12.99,NULL,'[{"name":"Alan Moore","role":"Guion"},{"name":"Bill Finger","role":"Guion"},{"name":"Mike Grell","role":"Guion"},{"name":"Mort Weisinger","role":"Guion"},{"name":"Scott Beatty","role":"Guion"},{"name":"Dick Dillin","role":"Dibujo"},{"name":"George Papp","role":"Dibujo"},{"name":"Jack Kirby","role":"Dibujo"},{"name":"Klaus Janson","role":"Dibujo"},{"name":"Neal Adams","role":"Dibujo"},{"name":"Shawn Martinbrough","role":"Dibujo"},{"name":"Rick Hoberg","role":"Dibujo"},{"name":"Dennis O''Neil","role":"Guion"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2155,'Flash de Brian Buccellato y Francis Manapul #1','Flash de Brian Buccellato y Francis Manapul',1,NULL,'84167-11-38-0',NULL,'Francis Manapul','Francis Manapul',NULL,NULL,'ECC Ediciones',NULL,'2016-04-29',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: The Flash núms. 1 a 8 USA\r\nCon un guion atrevido y un dibujo sobrecogedor a cargo de Francis Manapul y Brian Buccellato, Flash: Avanzar recopila los números del 1 al 8 de la serie regular surgida a raíz del nacimiento del nuevo Universo DC. Una ocasión idónea para descubrir o volver a disfrutar de esta brillante etapa del Velocista Escarlata.','\r',char(13)),'\n',char(10)),NULL,NULL,176,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776008031831-y62x05.jpg','read',0,NULL,NULL,'2026-04-12 15:33:55','2026-04-12 16:11:16',247,23.95,'Rústica','[{"name":"Francis Manapul","role":"Guion, Dibujo, Tinta"},{"name":"Brian Buccellato","role":"Guion, Color"},{"name":"Ian Herring","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2156,'Flash de Brian Buccellato y Francis Manapul #2','Flash de Brian Buccellato y Francis Manapul',2,NULL,'978-8-416-99848-7',NULL,'Francis Manapul','Francis Manapul',NULL,NULL,'ECC Ediciones',NULL,'2017-02-28',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: The Flash núms. 9 a 12 USA, 0, The Flash Annual núm. 1 USA\r\nARGUMENTO: El Capitán Frío. Ola de Calor. El Amo de los Espejos. El Hechicero del Clima. Patinadora. Trickster. El Flautista. Estos malhechores se hacían llamar los Villanos, y siempre han cumplido tres reglas muy sencillas: no matar a nadie, no consumir drogas y mantenerse centrados en el botín. Pero entonces, algo cambió. Ahora, las increíbles habilidades de los Villanos son una maldición más que una bendición. Sus poderes se han convertido en una cárcel que ha destruido su vida y la de quienes los rodean. Y todo por culpa del Capitán Frío.\r\nEl aplaudido equipo creativo formado por Francis Manapul y Brian Buccellato recibe a Marcus To (Huntress), Scott Kolins (JSA) y otros autores en Flash: La revolución de los villanos, protagonizado por el hombre más rápido del mundo y todos sus enemigos. Este volumen, secuela del recopilatorio Flash: Avanzar, agrupa los números del 9 al 12 y 0 de la serie original, así como el primer especial anual.','\r',char(13)),'\n',char(10)),NULL,NULL,176,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776008040593-9f7rp0.jpg','read',0,NULL,NULL,'2026-04-12 15:34:01','2026-04-12 16:11:16',247,NULL,'Rústica','[{"name":"Francis Manapul","role":"Guion, Dibujo, Tinta"},{"name":"Brian Buccellato","role":"Guion, Color"},{"name":"Marcus To","role":"Dibujo, Tinta"},{"name":"Ray McCarthy","role":"Tinta"},{"name":"Ian Herring","role":"Color"},{"name":"Scott Kolins","role":"Dibujo, Tinta"},{"name":"Michael Atiyeh","role":"Color"},{"name":"Diógenes Neves","role":"Dibujo"},{"name":"Oclair Albert","role":"Tinta"},{"name":"Marcio Takara","role":"Dibujo, Tinta"},{"name":"Wes Craig","role":"Dibujo, Tinta"},{"name":"Hi-Fi Desing","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2157,'Flash de Brian Buccellato y Francis Manapul #3','Flash de Brian Buccellato y Francis Manapul',3,NULL,'978-8-417-14788-4',NULL,'Francis Manapul','Francis Manapul',NULL,NULL,'ECC Ediciones',NULL,'2017-07-18',NULL,NULL,replace(replace('Contiene: The Flash Vol.4 #13 al 19\r\nCuando el implacable Rey Grodd y su ejército de gorilas inteligentes invaden Central City para capturar a Flash, el Velocista Escarlata y los Villanos deben formar una alianza improbable para salvar su ciudad de la aniquilación. ¿Durará lo suficiente este pacto incómodo para evitar la conquista? ¿O caerán las Ciudades Gemelas cuando Grodd desentrañe los secretos de la Fuerza de la Velocidad y se apropie de ellos?','\r',char(13)),'\n',char(10)),NULL,NULL,176,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776008043292-g6nzct.jpg','read',0,NULL,NULL,'2026-04-12 15:34:04','2026-04-12 16:11:16',247,NULL,'Rústica','[{"name":"Francis Manapul","role":"Guion, Dibujo, Tinta"},{"name":"Brian Buccellato","role":"Guion, Color"},{"name":"Marcus To","role":"Dibujo"},{"name":"Marcio Takara","role":"Dibujo, Tinta"},{"name":"Ryan Winn","role":"Tinta"},{"name":"Ian Herring","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2158,'Flash de Brian Buccellato y Francis Manapul #4','Flash de Brian Buccellato y Francis Manapul',4,NULL,'978-8-417-27620-1',NULL,'Francis Manapul','Francis Manapul',NULL,NULL,'ECC Ediciones',NULL,'2017-11-28',NULL,NULL,replace(replace('Contiene: The Flash Vol.4 #20 a 25 y The Flash Vol.4 #23.1\r\nBarry Allen apenas empieza a comprender el pleno potencial de la Fuente de la Velocidad, la misteriosa fuente de sus superpoderes. Dicha energía y la conexión que Flash mantiene con ella hacen que el tiempo siga avanzando, pero hay una persona que ha obtenido la capacidad de manipularla en sentido contrario. Este doble siniestro de Flash está acumulando poder suficiente para atrasar los relojes y reescribir varios años de historia. ¿Podrá nuestro héroe proteger el presente antes de que el Flash Reverso le robe sus habilidades?','\r',char(13)),'\n',char(10)),NULL,NULL,176,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776008045995-v3kp97.jpg','read',0,NULL,NULL,'2026-04-12 15:34:06','2026-04-12 16:11:16',247,NULL,'Rústica','[{"name":"Francis Manapul","role":"Guion, Dibujo, Tinta"},{"name":"Brian Buccellato","role":"Guion, Color"},{"name":"Chris Batista","role":"Dibujo"},{"name":"Chris Sprouse","role":"Dibujo"},{"name":"Tom Nguyen","role":"Tinta"},{"name":"Karl Story","role":"Tinta"},{"name":"Keith Champagne","role":"Tinta"},{"name":"Ian Herring","role":"Color"},{"name":"Wes Dzioba","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2159,'Green Arrow de Jeff Lemire y Andrea Sorrentino','Green Arrow de Jeff Lemire y Andrea Sorrentino',NULL,NULL,'978-8-416-84037-3',NULL,'Jeff Lemire','Andrea Sorrentino',NULL,NULL,'ECC Ediciones',NULL,'2016-08-31',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Green Arrow 17-34, 23.1 USA; Secret Origins 4 USA, Futures End: Green Arrow 1 USA\r\nHace seis años, Oliver Queen naufragó en una isla misteriosa. Allí murió el hombre que era… y empezó su vida como Green Arrow. Pero como Oliver pronto sabrá, aquel periplo no fue ningún accidente…\r\nLa llegada de una nueva arquera a Seattle conducirá a Oliver a seguir un rastro de pistas por el mundo entero y también a regresar a la isla donde todo empezó.\r\nHay fuerzas poderosas que creen que el destino de Oliver sigue estando en la isla, y quieren que regrese para reclamarla. Pero si surge la ocasión, ¿aceptará el papel que escogieron para él o regresará a la vida que él mismo ha construido?\r\nEl origen de Green Arrow queda patas arriba en esta celebrada trama realizada por un equipo creativo de primera, el formado por el guionista Jeff Lemire (Trillium) y el dibujante Andrea Sorrentino (Yo, Vampiro) .','\r',char(13)),'\n',char(10)),NULL,NULL,480,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776008063900-xzk3ei.jpg','read',0,NULL,NULL,'2026-04-12 15:34:25','2026-04-12 16:11:16',NULL,37,'lujo','[{"name":"Jeff Lemire","role":"Guion"},{"name":"Andrea Sorrentino","role":"Dibujo, Tinta, Color"},{"name":"Denys Cowan","role":"Dibujo"},{"name":"Bill Sienkiewicz","role":"Tinta"},{"name":"Marcelo Maiolo","role":"Color"},{"name":"Matt Hollingsworth","role":"Color"},{"name":"Hi-Fi Desing","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2160,'Orígenes secretos #1','Orígenes secretos',1,NULL,'978-8-416-25531-3',NULL,'Greg Pak','Lee Weeks',NULL,NULL,'ECC Ediciones',NULL,'2014-10-29',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Secret Origins vol. 3 #1-3 USA\r\n&quot;El Nuevo Universo DC está repleto de incógnitas que afectan tanto a sus personajes más icónicos como a los más recónditos. Para aclararlas nace esta colección, Orígenes secretos, que recupera una cabecera clásica y arroja mucha luz sobre lo relatado en las actuales series. En este volumen inicial, que recopila los tres primeros números americanos, presenciamos los singulares comienzos de Superman, el primer Robin, Supergirl, Batman, Aquaman, Starfire, Green Lantern, Batwoman y Red Robin. &quot;','\r',char(13)),'\n',char(10)),NULL,NULL,128,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776008084952-4jz89y.jpg','read',0,NULL,NULL,'2026-04-12 15:34:49','2026-04-12 16:11:16',248,23.95,NULL,'[{"name":"Greg Pak","role":"Guion"},{"name":"Lee Weeks","role":"Dibujo, Tinta"},{"name":"Sandra Hope","role":"Tinta"},{"name":"Dave McCaig","role":"Color"},{"name":"Kyle Higgins","role":"Guion"},{"name":"Doug Mahnke","role":"Dibujo"},{"name":"Keith Champagne","role":"Tinta"},{"name":"Christian Alamy","role":"Tinta"},{"name":"John Kalisz","role":"Color"},{"name":"Tony Bedard","role":"Guion"},{"name":"Paulo Siqueira","role":"Dibujo, Tinta"},{"name":"Hi-Fi Desing","role":"Tinta, Color"},{"name":"Ray Fawkes","role":"Guion"},{"name":"Dustin Nguyen","role":"Dibujo"},{"name":"Derek Fridolfs","role":"Tinta"},{"name":"Jeff Parker","role":"Guion"},{"name":"Paul Pelletier","rol