INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2161,'Orígenes secretos #3','Orígenes secretos',3,NULL,'978-8-416-40988-4',NULL,'Robert Venditti','Miguel Ángel Sepúlveda',NULL,NULL,'ECC Ediciones',NULL,'2015-07-01',NULL,NULL,replace(replace('EDICIÓN ORIGINAL: Secret Origins vol. 3 #7-9 USA \r\nBatman, Superman, Green Lantern, Wonder Woman… Gracias a esta serie de tomos, hemos conocido nuevos detalles sobre el origen de los principales héroes del Universo DC. Y ahora es el turno del Velocista Escarlata, el antiguo portador del manto de Nightwing y el campeón de El Verde. \r\n(Pagina web de ECC)','\r',char(13)),'\n',char(10)),NULL,NULL,128,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776008120337-jdo70k.jpg','read',0,NULL,NULL,'2026-04-12 15:35:21','2026-04-12 16:11:16',248,NULL,'Cartoné 112-128 pp','[{"name":"Robert Venditti","role":"Guion"},{"name":"Van Jensen","role":"Guion"},{"name":"Miguel Ángel Sepúlveda","role":"Dibujo"},{"name":"Scott Hanna","role":"Tinta"},{"name":"Andrew Dalhouse","role":"Color"},{"name":"Paul Levitz","role":"Guion"},{"name":"Jonboy Meyers","role":"Dibujo, Tinta"},{"name":"Matt Yackey","role":"Color"},{"name":"Frank J. Barbiere","role":"Guion"},{"name":"Robson Rocha","role":"Dibujo"},{"name":"Oclair Albert","role":"Tinta"},{"name":"Michael Atiyeh","role":"Color"},{"name":"Tim Seeley","role":"Guion"},{"name":"Tom King","role":"Guion"},{"name":"Stephen Mooney","role":"Dibujo, Tinta"},{"name":"Jeromy Cox","role":"Color"},{"name":"Jeff Lemire","role":"Guion"},{"name":"Duffy Boudreau","role":"Guion"},{"name":"Travel Foreman","role":"Dibujo, Tinta"},{"name":"Lovern Kindzierski","role":"Color"},{"name":"