INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2205,'Ultimate Spiderman Vol. 1 (2002-2006) #33','Ultimate Spiderman Vol. 1 (2002-2006)',33,NULL,'9770005310008-00033',NULL,'Brian Michael Bendis','Mark Bagley',NULL,NULL,'Planeta DeAgostini Cómics - Forum / Panini Comics España',NULL,'2005-01-01',NULL,NULL,replace(replace('Contiene Ultimate Spider-Man 47 y Ultimate Six 2 USA\r\n¡Nuevo arco argumental! La derrota de Kingpin fue también la primera gran victoria del joven Peter Parker. Ahora el Rey del Crimen ha vuelto, y sólo tiene una obsesión en mente: averiguar quién se oculta bajo la máscara de Spiderman. Además, no pierdas de vista la maléfica reunión de todos los enemigos del Hombre Araña ante los impotentes ojos del supergrupo de elite del gobierno norteamericano: ¡Los Ultimates!','\r',char(13)),'\n',char(10)),NULL,NULL,48,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776008845897-je5u71.jpg','read',0,NULL,NULL,'2026-04-12 15:47:26','2026-04-12 16:10:34',251,NULL,'Grapa','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Mark Bagley","role":"Dibujo"},{"name":"Art Thibert","role":"Tinta"},{"name":"Transparency Digital","role":"Color"},{"name":"Trevor Hairsine","role":"Dibujo"},{"name":"Danny Miki","role":"Tinta"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2206,'Ultimate Spiderman Vol. 1 (2002-2006) #34','Ultimate Spiderman Vol. 1 (2002-2006)',34,NULL,'9770005310008-00034',NULL,'Brian Michael Bendis','Mark Bagley',NULL,NULL,'Planeta DeAgostini Cómics - Forum / Panini Comics España',NULL,'2005-02-01',NULL,NULL,replace(replace('Contiene Ultimate Spider-Man 48 y Ultimate Six 3 USA\r\n¡Kingpin ha vuelto! Y Spiderman no puede hacer nada para impedir que el villano camine libre por los pasillos del poder. Por si fuera poco, las cosas no dejan de complicarse para Peter Parker después de ser despedido del Daily Bugle. Además, contempla la huida de prisión de los más mortales villanos a los que se haya enfrentado jamás el Hombre Araña en la tercera parte de la miniserie que cruza el destino de Spidey con el de los Ultimates. ¿O deberíamos decir contra?','\r',char(13)),'\n',char(10)),NULL,NULL,48,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776008848165-jura85.jpg','read',0,NULL,NULL,'2026-04-12 15:47:29','2026-04-12 16:10:34',251,NULL,'Grapa','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Mark Bagley","role":"Dibujo"},{"name":"Art Thibert","role":"Tinta"},{"name":"Transparency Digital","role":"Color"},{"name":"Trevor Hairsine","role":"Dibujo"},{"name":"Danny Miki","role":"Tinta"},{"name":"Dave Stewart","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2207,'Ultimate Spiderman Vol. 1 (2002-2006) #35','Ultimate Spiderman Vol. 1 (2002-2006)',35,NULL,'9770005310008-00035',NULL,'Brian Michael Bendis','Mark Bagley',NULL,NULL,'Planeta DeAgostini Cómics - Forum / Panini Comics España',NULL,'2005-03-01',NULL,NULL,replace(replace('Contiene Ultimate Spider-Man 49 y Ultimate Six 4 USA\r\nDespedido del Daily Bugle y perseguido por los Forzadores tras su regreso a New York, Spidey se prepara para destapar el apoyo de Kingpin a Sam Bullit, el candidato a la alcaldía de la ciudad, aunque para ello tenga que asociarse con Jonah Jameson. ¡Además, asiste a la reunión definitiva de los villanos arácnidos, liderados por Norman Osborn y a la búsqueda de un último miembro para completar su asociación impía! Invitados especiales: ¡Los Ultimates!','\r',char(13)),'\n',char(10)),NULL,NULL,48,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776008851318-lj9yjs.jpg','read',0,NULL,NULL,'2026-04-12 15:47:32','2026-04-12 16:10:34',251,NULL,'Grapa','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Mark Bagley","role":"Dibujo"},{"name":"Art Thibert","role":"Tinta"},{"name":"Transparency Digital","role":"Color"},{"name":"Trevor Hairsine","role":"Dibujo"},{"name":"Danny Miki","role":"Tinta"},{"name":"Ian Hannin","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2208,'Ultimate Spiderman Vol. 1 (2002-2006) #36','Ultimate Spiderman Vol. 1 (2002-2006)',36,NULL,'9770005310008-00036',NULL,'Brian Michael Bendis','Trevor Hairsine',NULL,NULL,'Planeta DeAgostini Cómics - Forum / Panini Comics España',NULL,'2005-04-01',NULL,NULL,replace(replace('Contiene Ultimate Six 5 y 6 USA\r\nEs el momento que estabas esperando: ¡Spiderman, cara a cara, con los fugados del Triskelion! Norman Osborn quiere que Peter Parker sea el sexto miembro de su equipo de supervillanos… ¡Y no aceptará un “no” por respuesta! Con sus seres queridos en peligro, ¿será capaz el Hombre Araña de aliarse con sus peores enemigos para luchar contra los Ultimates en el jardín de la Casa Blanca? Además, presencia el combate que nunca hubieras imaginado: ¡La tía May contra los agentes de SHIELD!','\r',char(13)),'\n',char(10)),NULL,NULL,48,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776008854107-xfkmx9.jpg','read',0,NULL,NULL,'2026-04-12 15:47:34','2026-04-12 16:10:34',251,NULL,'Grapa','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Trevor Hairsine","role":"Dibujo"},{"name":"Danny Miki","role":"Tinta"},{"name":"Avalon Studios","role":"Color"},{"name":"Ian Hannin","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2209,'Ultimate Spiderman Vol. 1 (2002-2006) #37','Ultimate Spiderman Vol. 1 (2002-2006)',37,NULL,'9770005310008-00037',NULL,'Brian Michael Bendis','Mark Bagley',NULL,NULL,'Planeta DeAgostini Cómics - Forum / Panini Comics España',NULL,'2005-05-01',NULL,NULL,replace(replace('Contiene Ultimate Spider-Man 50 y Ultimate Six 7 \r\n¡El Spiderman definitivo cumple cincuenta entregas! Acompáñanos en esta celebración y únete a la fiesta en un número especialmente preparado para la llegada de nuevos lectores, con el debut de una seductora ladrona de joyas que va a complicar la vida aventurera del Hombre Araña y las relaciones amorosas de Peter Parker. Ella es encantadora, escultura, luce pelo platino, ropa ajustadísima y responde al nombre de Felicia Hardy…. ¡Aunque ella prefiere que la llamen Gata Negra!','\r',char(13)),'\n',char(10)),NULL,NULL,48,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776008856806-p835g8.jpg','read',0,NULL,NULL,'2026-04-12 15:47:37','2026-04-12 16:10:34',251,NULL,'Grapa','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Mark Bagley","role":"Dibujo"},{"name":"Art Thibert","role":"Tinta"},{"name":"J.D. Smith","role":"Color"},{"name":"Trevor Hairsine","role":"Dibujo"},{"name":"Danny Miki","role":"Tinta"},{"name":"Ian Hannin","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2210,'Ultimate Spiderman Vol. 1 (2002-2006) #38','Ultimate Spiderman Vol. 1 (2002-2006)',38,NULL,'9770005310008-00038',NULL,'Brian Michael Bendis','Mark Bagley',NULL,NULL,'Planeta DeAgostini Cómics - Forum / Panini Comics España',NULL,'2005-06-01',NULL,NULL,replace(replace('Contiene Ultimate Spider-Man 51 y 52 USA \r\n¡Continúa la presentación en el Universo Ultimate del personaje arácnido más esperado! Peter Parker sabe que es una ladrona, sabe que está en un bando diferente, sabe que los medios de comunicación acusan a Spiderman de trabajar junto a ella… Pero no puede apartar de su mente a la Gata Negra. ¿Estás preparado para contemplar la primera cita del Hombre Araña y esta escultural ladrona en los tejados de New York? Quien no piensa perdérselo es Elektra, dispuesta a recuperar la tablilla robada por la Gata a Kingpin.','\r',char(13)),'\n',char(10)),NULL,NULL,48,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776008859408-dubuio.jpg','read',0,NULL,NULL,'2026-04-12 15:47:40','2026-04-12 16:10:34',251,NULL,'Grapa','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Mark Bagley","role":"Dibujo"},{"name":"Art Thibert","role":"Tinta"},{"name":"J.D. Smith","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2211,'Ultimate Spiderman Vol. 1 (2002-2006) #39','Ultimate Spiderman Vol. 1 (2002-2006)',39,NULL,'9770005310008-00039',NULL,'Brian Michael Bendis','Mark Bagley',NULL,NULL,'Planeta DeAgostini Cómics - Forum / Panini Comics España',NULL,'2005-07-01',NULL,NULL,replace(replace('Contiene Ultimate Spider-Man 53 y 54 USA \r\n¡Termina la saga de presentación de la Gata Negra del Universo Ultimate! Peter averigua toda la verdad sobre la escultural ladrona, pero… ¿será capaz de salvarla de su destino? Además, comienza una nueva aventura, Hollywood, en la que Spiderman descubre que un gran estudio cinematográfico está rodando una película sobre él mismo sin pedirle permiso ni pagarle un dólar. Con los cameos especiales del actor Tobey Maguire, el director Sam Raimi y el productor Avi Arad… ¡y el regreso del Doctor Octopus!','\r',char(13)),'\n',char(10)),NULL,NULL,48,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776008862477-uk4l3n.jpg','read',0,NULL,NULL,'2026-04-12 15:47:43','2026-04-12 16:10:34',251,NULL,'Grapa','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Mark Bagley","role":"Dibujo"},{"name":"Art Thibert","role":"Tinta"},{"name":"J.D. Smith","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2212,'Ultimate Spiderman Vol. 1 (2002-2006) #40','Ultimate Spiderman Vol. 1 (2002-2006)',40,NULL,'9770005310008-00040',NULL,'Brian Michael Bendis','Mark Bagley',NULL,NULL,'Planeta DeAgostini Cómics - Forum / Panini Comics España',NULL,'2005-08-01',NULL,NULL,replace(replace('Contiene Ultimate Spider-Man 55 y 56 USA \r\nSegunda y tercera parte de Hollywood, la saga que nos traslada hasta la meca del cine... ¡Sin movernos de New York! El Doctor Octopus ha conseguido escapar de prisión, y es más peligroso y maquiavélico que nunca. Mientras tanto, Kong ha conseguido un papel en la película que están rodando sobre Spiderman sin el permiso de éste, y Gwen Stacy atraviesa la peor crisis desde la muerte de su padre... ¿Qué hará Peter? Además, el debut de la versión definitiva de uno de los villanos arácnidos clásicos: ¡Mysterio!','\r',char(13)),'\n',char(10)),NULL,NULL,48,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776008865302-ukez8d.jpg','read',0,NULL,NULL,'2026-04-12 15:47:46','2026-04-12 16:09:57',251,NULL,'Grapa','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Mark Bagley","role":"Dibujo"},{"name":"Art Thibert","role":"Tinta"},{"name":"J.D. Smith","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2213,'Ultimate Spiderman Vol. 1 (2002-2006) #41','Ultimate Spiderman Vol. 1 (2002-2006)',41,NULL,'9770005310008-00041',NULL,'Brian Michael Bendis','Mark Bagley',NULL,NULL,'Planeta DeAgostini Cómics - Forum / Panini Comics España',NULL,'2005-09-01',NULL,NULL,replace(replace('Contiene Ultimate Spider-Man 57 y 58 USA \r\nCuarta y quinta parte de Hollywood. El Doctor Octopus ha conseguido al fin vencer a Spiderman. Con el trepamuros prisionero, este mortífero villano tentacular se dirige rumbo a lo desconocido a bordo de un avión mientras disfruta de su venganza contra el Hombre Araña. Por su parte, Gwen Stacy descubre un terrible secreto que cambiará para siempre su vida y su relación con Peter Parker. Ajena a todo, tía May disfruta de unas tranquilas vacaciones... ¿O tendrá algún buen motivo para regresar antes a casa?','\r',char(13)),'\n',char(10)),NULL,NULL,48,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776008867509-59a5y9.jpg','read',0,NULL,NULL,'2026-04-12 15:47:48','2026-04-12 16:09:57',251,NULL,'Grapa','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Mark Bagley","role":"Dibujo"},{"name":"Scott Hanna","role":"Tinta"},{"name":"J.D. Smith","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2214,'Ultimate Spiderman Vol. 1 (2002-2006) #42','Ultimate Spiderman Vol. 1 (2002-2006)',42,NULL,'9770005310008-00042',NULL,'Brian Michael Bendis','Mark Bagley',NULL,NULL,'Planeta DeAgostini Cómics - Forum / Panini Comics España',NULL,'2005-10-01',NULL,NULL,replace(replace('Contiene Ultimate Spider-Man 59 y 60 USA \r\n¡Concluye Hollywood! Peter ha derrotado una vez más al Doctor Octopus, y regresa a casa sólo para encontrarse que Gwen conoce su secreto... ¡Y también piensa que Spiderman fue el culpable de la muerte de su padre! ¿Conseguirá el trepamuros sacarla de su error? Además, el arranque de Matanza, la historia que presenta el nacimiento de una horrible criatura asesina surgida de donde menos te lo esperas. Con las apariciones especiales de Nick Furia, el Gladiador y... ¿un joven llamado Ben Reilly?','\r',char(13)),'\n',char(10)),NULL,NULL,48,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776008869685-82qjje.jpg','read',0,NULL,NULL,'2026-04-12 15:47:50','2026-04-12 16:09:57',251,NULL,'Grapa','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Mark Bagley","role":"Dibujo"},{"name":"Scott Hanna","role":"Tinta"},{"name":"J.D. Smith","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2215,'Ultimate Spiderman Vol. 1 (2002-2006) #43','Ultimate Spiderman Vol. 1 (2002-2006)',43,NULL,'9770005310008-00043',NULL,'Brian Michael Bendis','Mark Bagley',NULL,NULL,'Planeta DeAgostini Cómics - Forum / Panini Comics España',NULL,'2005-11-01',NULL,NULL,replace(replace('Contiene Ultimate Spider-Man 61 y 62 USA \r\n¡Continúa Matanza! ¡Con el nacimiento del más mortífero enemigo al que haya hecho frente jamás el Hombre Araña definitivo y la muerte más inesperada del Universo Ultimate! Aunque el joven Peter Parker se haya probado a sí mismo en una ocasión tras otra, ¿cómo podrá hacer frente a una absoluta máquina de matar que carece de sentimiento alguno? Además, no te pierdas un encuentro por todo lo alto entre Spiderman y Punisher... ¡Puedes creernos si te decimos que no es precisamente para tomar café!','\r',char(13)),'\n',char(10)),NULL,NULL,48,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776008871678-rool1i.jpg','read',0,NULL,NULL,'2026-04-12 15:47:52','2026-04-12 16:09:57',251,NULL,'Grapa','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Mark Bagley","role":"Dibujo"},{"name":"Scott Hanna","role":"Tinta"},{"name":"John Dell","role":"Tinta"},{"name":"J.D. Smith","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2216,'Ultimate Spiderman Vol. 1 (2002-2006) #44','Ultimate Spiderman Vol. 1 (2002-2006)',44,NULL,'9770005310008-00044',NULL,'Brian Michael Bendis','Mark Bagley',NULL,NULL,'Planeta DeAgostini Cómics - Forum / Panini Comics España',NULL,'2005-12-01',NULL,NULL,replace(replace('Contiene Ultimate Spider-Man 63 y 64 USA \r\n¡Con el desenlace de Matanza! Después de los trágicos sucesos del capítulo anterior, Peter Parker se jura a sí mismo que hará todo lo que esté en su mano para acabar con la criatura asesina que ha desatado Curt Conners sobre la tierra... ¡Partiendo de la propia sangre del Hombre Araña! Asiste al combate definitivo entre Spiderman y la versión definitiva de Matanza, el peor villano contra el que jamás se haya enfrentado el joven Peter hasta ahora.','\r',char(13)),'\n',char(10)),NULL,NULL,48,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776008873793-hqjek8.jpg','read',0,NULL,NULL,'2026-04-12 15:47:54','2026-04-12 16:09:57',251,NULL,'Grapa','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Mark Bagley","role":"Dibujo"},{"name":"Scott Hanna","role":"Tinta"},{"name":"J.D. Smith","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2217,'Ultimate Spiderman Vol. 1 (2002-2006) #45','Ultimate Spiderman Vol. 1 (2002-2006)',45,NULL,'9770005310008-00045',NULL,'Brian Michael Bendis','Mark Bagley',NULL,NULL,'Planeta DeAgostini Cómics - Forum / Panini Comics España',NULL,'2006-01-01',NULL,NULL,replace(replace('Contiene Ultimate Spider-Man 65 y 66 USA \r\nDespués de los trágicos acontecimientos del episodio anterior, te presentamos el epílogo de Matanza. Una de las personas más cercanas y queridas por Peter ha sido asesinada y, una vez más, Spiderman no pudo hacer nada por impedirlo. ¿Cómo afectará eso a su futuro como justiciero? Además, comienza la más abracadabrante aventura jamás vivida por el trepamuros. Es un nuevo encuentro con Lobezno. “¿Otro más?”, te preguntarás... ¡Pero te aseguramos que jamás has leído algo ni remotamente parecido!','\r',char(13)),'\n',char(10)),NULL,NULL,48,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776008875936-ygowb6.jpg','read',0,NULL,NULL,'2026-04-12 15:47:56','2026-04-12 16:09:57',251,NULL,'Grapa','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Mark Bagley","role":"Dibujo"},{"name":"Scott Hanna","role":"Tinta"},{"name":"J.D. Smith","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2218,'Ultimate Spiderman Vol. 1 (2002-2006) #46','Ultimate Spiderman Vol. 1 (2002-2006)',46,NULL,'9770005310008-00046',NULL,'Brian Michael Bendis','Mark Bagley',NULL,NULL,'Planeta DeAgostini Cómics - Forum / Panini Comics España',NULL,'2006-02-01',NULL,NULL,replace(replace('Contiene Ultimate Spider-Man 67 y 68 USA \r\n¡Un episodio lleno de invitados especiales! Para empezar, damos carpetazo a la sorprendente aventura en la que Peter Parker y Lobezno intercambian sus cuerpos. ¿Conseguirá Spidey dejar de cortarse con las garras de Logan? ¿Será capaz Lobezno de columpiarse en red? ¿Asesinará Brian Bendis a su editor asistente? ¡Todas las respuestas están aquí! Y una nueva pregunta, también: ¿Qué ocurre cuando Johnny Storm se une a la pandilla de Peter? ¡Pues que la cosa se caldea! ¿Te lo vas a perder?','\r',char(13)),'\n',char(10)),NULL,NULL,48,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776008877807-263u92.jpg','read',0,NULL,NULL,'2026-04-12 15:47:58','2026-04-12 16:09:57',251,NULL,'Grapa','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Mark Bagley","role":"Dibujo"},{"name":"Scott Hanna","role":"Tinta"},{"name":"J.D. Smith","role":"Color"}]');
INSERT INTO "comics" ("id","title","series","number","volume","isbn","ean","writer","artist","colorist","cover_artist","publisher","collection","publish_date","original_publisher","original_title","synopsis","genre","format","pages","language","cover_url","read_status","owned","rating","notes","created_at","updated_at","collection_id","price","binding","authors") VALUES(2219,'Ultimate Spiderman Vol. 1 (2002-2006) #47','Ultimate Spiderman Vol. 1 (2002-2006)',47,NULL,'9770005310008-00047',NULL,'Brian Michael Bendis','Mark Bagley',NULL,NULL,'Planeta DeAgostini Cómics - Forum / Panini Comics España',NULL,'2006-03-01',NULL,NULL,replace(replace('Contiene Ultimate Spider-Man 69-71 USA \r\n¡Último número! En abril, la colección del Hombre Araña definitivo renacerá con un nuevo número uno. Mientras tanto, acompáñanos en esta despedida, con la peor pesadilla que jamás haya sufrido Peter Parker, un escalofriante sueño que le llevará a buscar la ayuda del Hechicero Supremo... ¡El Doctor Extraño! Y también: la segunda parte del encuentro entre el trepamuros y la Antorcha Humana: ¿Qué ocurrirá entre Johnny Storm y Liz Allen? ¿Logrará ella superar su animadversión hacia los superseres?','\r',char(13)),'\n',char(10)),NULL,NULL,48,'Español (España)','https://inventario-api.josepec.workers.dev/covers/1776008879538-4pu59f.jpg','read',0,NULL,NULL,'2026-04-12 15:48:00','2026-04-12 16:09:57',251,NULL,'Grapa','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Mark Bagley","role":"Dibujo"},{"name":"Scott Hanna","role":"Tinta"},{"name":"J.D. Smith","role":"Color"},{"name":"Chris Sotomayor","role":"Color"}]');
