INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(13,'672313','edition','Shin Zero','Grafito Editorial','https://inventario-api.josepec.workers.dev/covers/1775294526225-7wpshc.jpg',NULL,'Shin Zero es una historia de genero Súper Sentai (Ultramán, Power Rangers, Kamen Rider) que se sitúa en una realidad algo diferente de la nuestra, en la que monstruos gigantes salieron del mar aterrorizando a la población y destruyéndolo todo. En un esfuerzo desesperado se modificó a voluntarios para que pudiesen cambiar su tamaño y poder derrotarlos. Esta catástrofe pasó hace décadas y la amenaza ya ha desaparecido.','https://www.whakoom.com/ediciones/672313','2026-04-04 09:22:07','2026-04-04 09:32:57',1,'Rústica 216 pp','En curso','15 x 21 cm.','Shin Zero es una historia de genero Súper Sentai (Ultramán, Power Rangers, Kamen Rider) que se sitúa en una realidad algo diferente de la nuestra, en la que monstruos gigantes salieron del mar aterrorizando a la población y destruyéndolo todo. En un esfuerzo desesperado se modificó a voluntarios para que pudiesen cambiar su tamaño y poder derrotarlos. Esta catástrofe pasó hace décadas y la amenaza ya ha desaparecido.','[{"name":"Mathieu Bablet","role":"Guion"},{"name":"Guillaume Singelin","role":"Dibujo, Tinta, Color"}]','[{"id":"ftON7","number":1,"title":"Shin Zero #1","subtitle":"","cover":"https://i1.whakoom.com/small/0c/25/1dc982e930194e25bd9d23102b001cf6.jpg","published":true,"releaseDate":null}]','2026-04-04T09:32:56.068Z',NULL,NULL);
INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(14,'683934','edition','Atelier of Witch Hat. Edición Grimorio','Milky Way Ediciones','https://inventario-api.josepec.workers.dev/covers/1775295715854-uh6at7.jpg',2,'En un mundo donde existe la magia, pero solo unos pocos pueden usarla, Coco es una aprendiz del atelier del mago Qifrey. Coco desea dominar la magia para encontrar el conjuro que libere a su madre del hechizo que accidentalmente lanzó sobre ella. Junto con Agete, Tetia y Riche, las cuatro niñas vivirán varias aventuras mientras se adentran en un mundo de la magia que resulta ser más peligroso de lo que esperaban. Y es que, mientras los Sombreros de Mago siguen las normas sobre el uso de la magia, los Sombreros de Ala quieren acabar con el orden establecido el Día de la Conspiración.','https://www.whakoom.com/ediciones/683934','2026-04-04 09:41:56','2026-04-12 17:29:06',1,'Cartoné 416-432 pp','En curso','A5, B/N con páginas a color','En un mundo donde existe la magia, pero solo unos pocos pueden usarla, Coco es una aprendiz del atelier del mago Qifrey. Coco desea dominar la magia para encontrar el conjuro que libere a su madre del hechizo que accidentalmente lanzó sobre ella. Junto con Agete, Tetia y Riche, las cuatro niñas vivirán varias aventuras mientras se adentran en un mundo de la magia que resulta ser más peligroso de lo que esperaban. Y es que, mientras los Sombreros de Mago siguen las normas sobre el uso de la magia, los Sombreros de Ala quieren acabar con el orden establecido el Día de la Conspiración.','[{"name":"Kamome Shirahama","role":"Guion, Dibujo, Tinta, Color"}]','[{"id":"89XTb","number":1,"title":"Atelier of Witch Hat. Edición Grimorio #1","subtitle":"","cover":"https://i1.whakoom.com/small/1d/20/ecc8625af32b4e8997fa9c4a835f97ec.jpg","published":true,"releaseDate":null},{"id":"PA0vq","number":2,"title":"Atelier of Witch Hat. Edición Grimorio #2","subtitle":"","cover":"https://i1.whakoom.com/small/1e/19/219f91b6e54a4634870a7a1fd8d57b28.jpg","published":true,"releaseDate":null},{"id":"PpFM6","number":3,"title":"Atelier of Witch Hat. Edición Grimorio #3","subtitle":"","cover":"https://i1.whakoom.com/small/22/3b/b72d838c6f854a9b9f3011311424fbcc.jpg","published":false,"releaseDate":"may."}]','2026-04-12T17:29:07.224Z',NULL,NULL);
INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(15,'1947','edition','El Cuarto Mundo. Clásicos DC','Planeta Cómic','https://inventario-api.josepec.workers.dev/covers/1775295795853-04znqz.jpg',10,'Aquí comienza la descomunal saga del Cuarto Mundo. Una epopeya sin precedentes que en su día costó asimilar un poco pero que está reconocida actualmente como una de las cúspides del cómic de superhéroes y, sin duda alguna, la obra maestra de ese genio llamado Jack Kirby.','https://www.whakoom.com/ediciones/1947','2026-04-04 09:43:16','2026-04-06 09:10:38',1,'Rústica 112-176 pp','Terminada','Tamaño 15x23 cm.','Aquí comienza la descomunal saga del Cuarto Mundo. Una epopeya sin precedentes que en su día costó asimilar un poco pero que está reconocida actualmente como una de las cúspides del cómic de superhéroes y, sin duda alguna, la obra maestra de ese genio llamado Jack Kirby.','[{"name":"Jack Kirby","role":"Guion, Dibujo"},{"name":"Vince Colletta","role":"Tinta"},{"name":"Mike Roger","role":"Tinta"},{"name":"Mike Royer","role":"Tinta"},{"name":"Mark Evanier","role":"Dibujo"},{"name":"Werner Roth","role":"Dibujo"},{"name":"Robert Kanigher","role":"Guion"},{"name":"Steve Sherman","role":"Dibujo"}]','[{"id":"8zBF7","number":1,"title":"El Cuarto Mundo. Clásicos DC #1","subtitle":"","cover":"https://i1.whakoom.com/small/02/2a/ed217d5c1dc54345a0788fbeadbb890e.jpg","published":true,"releaseDate":null},{"id":"kzBW6","number":2,"title":"El Cuarto Mundo. Clásicos DC #2","subtitle":"","cover":"https://i1.whakoom.com/small/07/3a/2590b3d8e590468b8b8c80402473448f.jpg","published":true,"releaseDate":null},{"id":"zBB67","number":3,"title":"El Cuarto Mundo. Clásicos DC #3","subtitle":"","cover":"https://i1.whakoom.com/small/06/00/8a7f59e636314791af8f9e452060c0fc.jpg",