INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(29,'367307','edition','Transmetropolitan','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1775489172049-660ocv.jpg',10,'Estamos en una gran metropolis de un indeterminado futuro. Spider Jerusalem es un periodista que tras alcanzar la fama hace cinco años abandonó la ciudad para vivir aislado en la montaña. Ahora se ve obligado a volver a la ciudad y volver a trabajar, encargándose de una columna de opinión semanal en un periódico, donde habla de diferentes temas de actualidad social. La serie gira alrededor del proceso de investigación y documentación que Spider realiza sobre cada tema, que nos sirve para conocer la sociedad en la que se mueve el protagonista, a la vez que vamos conociendo un poco mejor al personaje y algunos detalles de su pasado.','https://www.whakoom.com/ediciones/367307','2026-04-06 15:26:12','2026-04-06 15:27:13',1,'Rústica 144 pp','Terminada','Tamaño 16,8 x 25,7 cm Color. La edición, plafinicada en 10 tomos, no se agrupa por arcos argumentales, por lo que algunos de ellos están divididos en dos tomos.','Estamos en una gran metropolis de un indeterminado futuro. Spider Jerusalem es un periodista que tras alcanzar la fama hace cinco años abandonó la ciudad para vivir aislado en la montaña. Ahora se ve obligado a volver a la ciudad y volver a trabajar, encargándose de una columna de opinión semanal en un periódico, donde habla de diferentes temas de actualidad social. La serie gira alrededor del proceso de investigación y documentación que Spider realiza sobre cada tema, que nos sirve para conocer la sociedad en la que se mueve el protagonista, a la vez que vamos conociendo un poco mejor al personaje y algunos detalles de su pasado.','[{"name":"Warren Ellis","role":"Guion"},{"name":"Darick Robertson","role":"Dibujo, Tinta"}]','[{"id":"zBGh6","number":1,"title":"Transmetropolitan #1","subtitle":"De Nuevo en la Calle","cover":"https://i1.whakoom.com/small/26/10/cc2610b492174e5f88f9143c775c9999.jpg","published":true,"releaseDate":null},{"id":"zoBm6","number":2,"title":"Transmetropolitan #2","subtitle":"Pasión por vivir","cover":"https://i1.whakoom.com/small/16/09/9c00b91db89a4c5ebe89052430e86a01.jpg","published":true,"releaseDate":null},{"id":"kOarT","number":3,"title":"Transmetropolitan #3","subtitle":"El año del cabrón","cover":"https://i1.whakoom.com/small/34/26/b421afc4d8ab4fedb001c97dd0c050d3.jpg","published":true,"releaseDate":null},{"id":"8Og19","number":4,"title":"Transmetropolitan #4","subtitle":"La Nueva Escoria","cover":"https://i1.whakoom.com/small/3f/34/0f18ea1a29de490db51d94674e49df74.jpg","published":true,"releaseDate":null},{"id":"kO0W0","number":5,"title":"Transmetropolitan #5","subtitle":"Ciudad Solitaria","cover":"https://i1.whakoom.com/small/30/0a/7bba8d96be0a4e049990a90d5d9fdf79.jpg","published":true,"releaseDate":null},{"id":"HOW5q","number":6,"title":"Transmetropolitan #6","subtitle":"Escarba Hondo","cover":"https://i1.whakoom.com/small/3c/21/eda11c1fae55428c98ac7a2c294e1ab0.jpg","published":true,"releaseDate":null},{"id":"jH4Vh","number":7,"title":"Transmetropolitan #7","subtitle":"Las Rajadas de Spider","cover":"https://i1.whakoom.com/small/2b/2a/9b700a191e884c69a9f40694703924f0.jpg","published":true,"releaseDate":null},{"id":"yHXGT","number":8,"title":"Transmetropolitan #8","subtitle":"Canto Fúnebre","cover":"https://i1.whakoom.com/small/32/0a/c7896431b80846dfa7d7260d461d5770.jpg","published":true,"releaseDate":null},{"id":"HnbMk","number":9,"title":"Transmetropolitan #9","subtitle":"La Cura","cover":"https://i1.whakoom.com/small/38/1c/1abb71fe9fe44c328cb3e5cc01b89df4.jpg","published":true,"releaseDate":null},{"id":"yt5HB","number":10,"title":"Transmetropolitan #10","subtitle":"Una Vez Más","cove