INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(30,'378650','edition','Muerdeuñas','Norma Editorial','https://inventario-api.josepec.workers.dev/covers/1775490438930-s7mkfo.jpg',8,'El pueblo de Buckaroo, Oregón, es la cuna de ni más ni menos que dieciséis asesinos en serie hasta la fecha y el agente Carroll del FBI está decidido a descubrir por qué. Pero cuando desaparece de pronto, una extraña alianza se forma para encontrarlo: la sheriff de Buckaroo, un agente de la NSA con un turbio pasado y el último y más notorio de los carniceros de Buckaroo, Edward “Muerdeuñas” Warren. Joshua Williamson y Mike Henderson presentan una intrigante historia con los mejores elementos de referentes como TWIN PEAKS, EL SILENCIO DE LOS CORDEROS o SE7EN','https://www.whakoom.com/ediciones/378650','2026-04-06 15:47:20','2026-04-06 15:47:27',1,'Rústica 132-144 pp','Terminada','Tamaño 17 x 26 cm Color','El pueblo de Buckaroo, Oregón, es la cuna de ni más ni menos que dieciséis asesinos en serie hasta la fecha y el agente Carroll del FBI está decidido a descubrir por qué. Pero cuando desaparece de pronto, una extraña alianza se forma para encontrarlo: la sheriff de Buckaroo, un agente de la NSA con un turbio pasado y el último y más notorio de los carniceros de Buckaroo, Edward “Muerdeuñas” Warren. Joshua Williamson y Mike Henderson presentan una intrigante historia con los mejores elementos de referentes como TWIN PEAKS, EL SILENCIO DE LOS CORDEROS o SE7EN','[{"name":"Joshua Williamson","role":"Guion"},{"name":"Mike Henderson","role":"Dibujo, Tinta"},{"name":"Adam Guzowski","role":"Color"},{"name":"Adam Markiewicz","role":"Dibujo, Tinta"}]','[{"id":"zop37","number":1,"title":"Muerdeuñas #1","subtitle":"Habrá sangre","cover":"https://i1.whakoom.com/small/2d/17/af842