INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(34,'229755','edition','Superman: La Llegada de H''el','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1775492205554-i0s6ap.jpg',3,'Ha aparecido sobre la Tierra un nuevo superviviente del planeta Krypton. Su nombre es H’El, y dice ser un antiguo alumno de Jor-El e íntimo amigo de la familia biológica de Kal y Kara, que fue enviado al espacio en una nave de pruebas en la que permaneció durante muchos años a merced de terribles inclemencias que transformaron su aspecto de forma monstruosa','https://www.whakoom.com/ediciones/229755','2026-04-06 16:16:46','2026-04-06 16:16:50',1,'Rústica 112-136-96 pp','Terminada',NULL,'Ha aparecido sobre la Tierra un nuevo superviviente del planeta Krypton. Su nombre es H’El, y dice ser un antiguo alumno de Jor-El e íntimo amigo de la familia biológica de Kal y Kara, que fue enviado al espacio en una nave de pruebas en la que permaneció durante muchos años a merced de terribles inclemencias que transformaron su aspecto de forma monstruosa','[{"name":"Scott Lobdell","role":""},{"name":"Mike Johnson","role":""},{"name":"Tom DeFalco","role":""},{"name":"Kenneth Rocafort","role":""},{"name":"Mahmud Asrar","role":""},{"name":"R. B. Silva","role":""},{"name":"Roger Robinson","role":""},{"name":"Ron Frenz","role":""},{"name":"Iban Coello","role":""},{"name":"Amilcar Pinna","role":""}]','[{"id":"wzOnq","number":1,"title":"Superman: La Llegada de H''el #1","subtitle":"","cover":"https://i1.whakoom.com/small/05/00/20fe391206ab4f56bf4fa2c8d3d3cf56.jpg","published":true,"releaseDate":null},{"id":"8wzOI","number":2,"title":"Superman: La Llegada de H''el #2","subtitle":"Lex Luthor. Reflexiones de una mente perturbada","cover":"https://i1.whakoom.com/small/2b/0a/