INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(50,'1376','edition','Creepy','Planeta Cómic','https://inventario-api.josepec.workers.dev/covers/1775516267323-2mpkth.jpg',22,'¡Recoge tus estacas de madera, tus hachas cubiertas de sangre y todos los esqueletos de las más oscuras profundidades de tu armario, y prepárate para una espeluznante aventura en los más horripilantes rincones de la historia de los cómics! La revista Creepy del editor Jim Warren conmocionó el mundo de la narración gráfica a principio de los años 60, cuando artistas tan magníficos como Joe Orlando, Alex Toth, Wallace Wood, Frank Frazetta y muchos otros alcanzaron nuevas cimas artísticas con sus fascinantes versiones de relatos de terror clásicos y modernos. Durante los siguientes 20 años, ninguna publicación hizo más que Creepy por llevar a los cómics terroríficas historias de calidad, y esta serie de Los archivos de Creepy resucita aquellos números originales hoy en día imposibles de encontrar.','https://www.whakoom.com/ediciones/1376','2026-04-06 22:57:47','2026-04-06 23:01:56',1,'Cartoné 232-296 pp B/N','En curso','20x27,6 cm 2.ª edición de varios volúmenes en 2024 y 2025 con nuevo ISBN (añadido a la ficha)','¡Recoge tus estacas de madera, tus hachas cubiertas de sangre y todos los esqueletos de las más oscuras profundidades de tu armario, y prepárate para una espeluznante aventura en los más horripilantes rincones de la historia de los cómics! La revista Creepy del editor Jim Warren conmocionó el mundo de la narración gráfica a principio de los años 60, cuando artistas tan magníficos como Joe Orlando, Alex Toth, Wallace Wood, Frank Frazetta y muchos otros alcanzaron nuevas cimas artísticas con sus fascinantes versiones de relatos de terror clásicos y modernos. Durante los siguientes 20 años, ninguna publicación hizo más que Creepy por llevar a los cómics terroríficas historias de calidad, y esta serie de Los archivos de Creepy resucita aquellos números originales hoy en día imposibles de encontrar.','[{"name":"Frank Frazetta","role":""},{"name":"Archie Goodwin","role":""},{"name":"Alex Toth","role":""},{"name":"Bernie Wrightson","role":"Guion, Dibujo"},{"name":"Al Williamson","role":""},{"name":"John Severin","role":"Dibujo"},{"name":"Al McWilliams","role":""},{"name":"Angelo Torres","role":""},{"name":"Reed Crandall","role":""},{"name":"Larry Englehart","role":""}]','[{"id":"j8Av5","number":1,"title":"Creepy #1","subtitle":"","cover":"https://i1.whakoom.com/small/2d/1c/dfc6f600d0894a5fb314d7e90d99c5e6.jpg","published":true,"releaseDate":null},{"id":"6AvVk","number":2,"title":"Creepy #2","subtitle":"","cover":"https://i1.whakoom.com/small/00/1d/f0da00576a954bc6a8ad320d3d2874b8.jpg","published":true,"releaseDate":null},{"id":"jyAvw","number":3,"title":"Creepy #3","subtitle":"","cover":"https://i1.whakoom.com/small/08/10/25d5f57734154f7998cc7a36ee79dfcc.jpg","published":true,"releaseDate":null},{"id":"8jAvA","number":4,"title":"Creepy #4","subtitle":"","cover":"https://i1.whakoom.com/small/3e/2d/f7ee9a5826c446259df03545e39c8a10.jpg","published":true,"releaseDate":null},{"id":"yAvaq","number":5,"title":"Creepy #5","subtitle":"","cover":"https://i1.whakoom.com/small/34/20/75e4b23ebb474813806eec2b93c462f5.jpg","published":true,"releaseDate":null},{"id":"yAvr7","number":6,"title":"Creepy #6","subtitle":"","cover":"https://i1.whakoom.com/small/02/33/977d05ff29624e42b2740b30381266b3.jpg","published":true,"releaseDate":null},{"id":"8AvM7","number":7,"title":"Creepy #7","subtitle":"","cover":"https://i1.whakoom.com/small/2f/2e/cb575df0f9f44e5eb4939fa54d8873c3.jpg","published":true,"releaseDate":null},{"id":"Avz6q","number":8,"title":"Creepy #8","subtitle":"","cover":"https://i1.whakoom.com/small/37/36/e7dad602f4ec48ad927c58270889b18a.jpg","