INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(55,'663882','edition','Biblioteca Disney','Panini Comics España','https://inventario-api.josepec.workers.dev/covers/1775547502022-qrq061.jpg',11,'¿Crees que la vida de un monarca es despreocupada? Eso es porque nunca has visitado el Reino de los Dos Lagos, donde el Rey Mickey vive asediado no sólo por los bárbaros, sino también por sus súbditos, rodeado de una corte que es, cuando menos, estrafalaria.Compuesta de ocho capítulos, más el epílogo El misterio de los gnomos invisibles, presentamos en versión integral y por primera vez en castellano esta hilarante saga fantástico-humorística,concebida por el genial Tito Faraci y dibujada con un inconfundible trazo irónico por Silvia Ziche, enriquecida con una larga entrevista con los autores','https://www.whakoom.com/ediciones/663882','2026-04-07 07:38:22','2026-04-07 07:38:26',1,'Rústica Color','En curso','18x24,5 cms','¿Crees que la vida de un monarca es despreocupada? Eso es porque nunca has visitado el Reino de los Dos Lagos, donde el Rey Mickey vive asediado no sólo por los bárbaros, sino también por sus súbditos, rodeado de una corte que es, cuando menos, estrafalaria.Compuesta de ocho capítulos, más el epílogo El misterio de los gnomos invisibles, presentamos en versión integral y por primera vez en castellano esta hilarante saga fantástico-humorística,concebida por el genial Tito Faraci y dibujada con un inconfundible trazo irónico por Silvia Ziche, enriquecida con una larga entrevista con los autores','[{"name":"Alessandro Perina","role":"Dibujo"},{"name":"Francesco Artibani","role":"Guion"},{"name":"Guido Martina","role":"Guion"},{"name":"Giovan Battista Carpi","role":"Dibujo, Tinta"},{"name":"Andrea Freccero","role":"Dibujo"},{"name":"Stefan