INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(56,'609289','edition','Mickey Mouse: Tiras de prensa','Planeta Cómic','https://inventario-api.josepec.workers.dev/covers/1775564512010-ljd4ps.jpg',NULL,'El público actual conoce a Mickey Mouse como un personaje risueño y bonachón. Pero durante su época dorada en los años treinta, Mickey se hizo famoso por sus heroicidades épicas. Era un aventurero atrevido y beligerante que se enfrentaba a monstruos, secuestradores y espías. Y las mayores hazañas de Mickey se llevaban a cabo en su tira cómica diaria, creada por uno de los mayores dibujantes de cómic de la historia: Floyd Gottfredson.','https://www.whakoom.com/ediciones/609289','2026-04-07 12:21:52','2026-04-07 12:21:56',1,'Cartoné 298 pp B/N','En curso','PVP 50 €','El público actual conoce a Mickey Mouse como un personaje risueño y bonachón. Pero durante su época dorada en los años treinta, Mickey se hizo famoso por sus heroicidades épicas. Era un aventurero atrevido y beligerante que se enfrentaba a monstruos, secuestradores y espías. Y las mayores hazañas de Mickey se llevaban a cabo en su tira cómica diaria, creada por uno de los mayores dibujantes de cómic de la historia: Floyd Gottfredson.','[{"name":"Floyd Gottfredson","role":"Guion, Dibujo"}]','[{"id":"8mmaX","number":1,"title":"Mickey Mouse: Tiras de prensa #1","subtitle":"\"Carrera hacia el valle de la Muerte\"","cover":"https://i1.whakoom.com/small/38/31/cf3d3f5fdeec45efa390a7387ac4d1c4.jpg","published":true,"releaseDate":null}]','2026-04-07T12:21:57.260Z',NULL,NULL);
