INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(65,'77949','edition','Batwoman. Nuevo Universo DC','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1775565865122-eum9dz.jpg',5,'Mientras trata de asumir los dolorosos secretos que le ocultó su propio padre, Kate Kane afronta la necesidad de entrenar a Flamebird, empeñada en convertirse en su compañera. Pero lo que realmente preocupa a Batwoman es resolver el caso abierto a raíz de la desaparición de varios niños, aparentemente secuestrados en el barrio hispano de Gotham City. Demasiados frentes abiertos, a los que hay que sumar el hecho de que esté siendo investigada por una misteriosa agencia gubernamental…','https://www.whakoom.com/ediciones/77949','2026-04-07 12:44:26','2026-04-07 12:44:38',1,'Rústica 144 pp','Terminada','17x26 cm., color','Mientras trata de asumir los dolorosos secretos que le ocultó su propio padre, Kate Kane afronta la necesidad de entrenar a Flamebird, empeñada en convertirse en su compañera. Pero lo que realmente preocupa a Batwoman es resolver el caso abierto a raíz de la desaparición de varios niños, aparentemente secuestrados en el barrio hispano de Gotham City. Demasiados frentes abiertos, a los que hay que sumar el hecho de que esté siendo investigada por una misteriosa agencia gubernamental…','[{"name":"Haden Blackman","role":"Guion"},{"name":"J. H. Williams III","role":"Guion, Dibujo"},{"name":"Trevor Mccarthy","role":"Dibujo"},{"name":"Amy Reeder","role":"Dibujo"},{"name":"Moritat","role":""},{"name":"Marc Andreyko","role":""},{"name":"Pere Pérez","role":""},{"name":"Francesco Francavilla","role":"Dibujo"}]','[{"id":"yNbLL","number":1,"title":"Batwoman. Nuevo Universo DC #1","subtitle":"Hidrología","cover":"https://i1.whakoom.com/small/29/28/6d52bbdbc7454ee1a0ba335730fb8dd1.jpg","published":true,"releaseDate":null},{"id":"8NbLX","number":2,"title":"Batwoman. Nuevo Universo DC #2","subtitle":"Un mundo anegado","cover":"https://i1.whakoom.com/small/07/26/c32e50d81015433f8f7add7b7543a6af.jpg","published":true,"releaseDate":null},{"id":"yNbL1","number":3,"title":"Batwoman. Nuevo Universo DC #3","subtitle":"Mareas de Sangre","cover":"https://i1.whakoom.com/small/08/35/27fec995ae3a46c684df70a635044f8e.jpg","published":true,"releaseDate":null},{"id":"ywMRX","number":4,"title":"Batwoman. Nuevo Universo DC #4","subtitle":"La sangre es espesa","cover":"https://i1.whakoom.com/small/02/31/5ee972497ca4436fa0c92cbf118da482.jpg","published":true,"releaseDate":null},{"id":"jMRzV","number":5,"title":"Batwoman. Nuevo Universo DC #5","subtitle":"La sangre es espesa. Final","cover":"https://i1.whakoom.com/small/1e/1b/e18a1652693c4b6887db87e6289cc423.jpg","published":true,"releaseDate":null}]','2026-04-07T12:44:39.057Z',NULL,NULL);
INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(66,'77951','edition','Catwoman. Nuevo Universo DC','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1775565900016-b0v87i.jpg',6,'Flash tomó la imprudente decisión de viajar al pasado y cambiar la historia en beneficio propio, salvando a su madre de morir a manos de otro viajero en el tiempo. El resultado fue la completa reescritura de la Historia, y el nacimiento de un mundo nuevo que pudimos ver en las páginas de Flashpoint. Finalmente, en un desesperado intento de corregir su error, volvió a cambiar el pasado provocando una paradoja que hizo pedazos la línea temporal existente para reconstruir con ellos la que conocía. O al menos lo intentó...En este Nuevo Universo DC no todo es como antes: héroes y villanos han seguido caminos semejantes a los de antaño, pero pocas veces coincidentes. Como muchos otros Selina Kyle, Catwoman, empieza hoy una nueva vida...','https://www.whakoom.com/ediciones/77951','2026-04-07 12:45:00','2026-04-07 12:45:00',1,'Rústica 144 pp','Terminada',NULL,'Flash tomó la imprudente decisión de viajar al pasado y cambiar la historia en beneficio propio, salvando a su madre de morir a manos de otro viajero en el tiempo. El resultado fue la completa reescritura de la Historia, y el nacimiento de un mundo nuevo que pudimos ver en las páginas de Flashpoint. Finalmente, en un desesperado intento de corregir su error, volvió a cambiar el pasado provocando una paradoja que hizo pedazos la línea temporal existente para reconstruir con ellos la que conocía. O al menos lo intentó...En este Nuevo Universo DC no todo es como antes: héroes y villanos han seguido caminos semejantes a los de antaño, pero pocas veces coincidentes. Como muchos otros Selina Kyle, Catwoman, empieza hoy una nueva vida...','[{"name":"Rafa Sandoval","role":"Dibujo"},{"name":"Ann Nocenti","role":"Guion"},{"name":"Guillem March","role":""},{"name":"Judd Winick","role":""},{"name":"Adriana Melo","role":""},{"name":"Matt Santolouco","role":"Dibujo, Tinta"},{"name":"Diógenes Neves","role":"Dibujo, Tinta"},{"name":"Sholly Fisch","role":"Guion"},{"name":"Emanuela Lupacchino","role":""},{"name":"Mike Bowden","role":""}]','[{"id":"NbLdq","number":1,"title":"Catwoman. Nuevo Universo DC #1","subtitle":"","cover":"https://i1.whakoom.com/small/34/23/bacba6831f37431e9f112a503b7029c6.jpg","published":true,"releaseDate":null},{"id":"NbLf7","number":2,"title":"Catwoman. Nuevo Universo DC #2","subtitle":"La noche de los búhos","cover":"https://i1.whakoom.com/small/09/2b/495e45ca6a8d44b09b683855501dd3b7.jpg","published":true,"releaseDate":null},{"id":"jNbL9","number":3,"title":"Catwoman. Nuevo Universo DC #3","subtitle":"La muerte de la familia ¡muerta de risa!","cover":"https://i1.whakoom.com/small/32/33/e4e3f47b71e54572ba3f95213eb61a2b.jpg","published":true,"releaseDate":null},{"id":"ADWTq","number":4,"title":"Catwoman. Nuevo Universo DC #4","subtitle":"","cover":"https://i1.whakoom.com/small/2c/0f/a40d5569fc374d7d86f84121fde17513.jpg","published":true,"releaseDate":null},{"id":"jMlAB","number":5,"title":"Catwoman. Nuevo Universo DC #5","subtitle":"","cover":"https://i1.whakoom.com/small/3d/34/0b1fe165ee604064aad18a78842cdf67.jpg","published":true,"releaseDate":null},{"id":"zBZI7","number":6,"title":"Catwoman. Nuevo Universo DC #6","subtitle":"Catwoman","cover":"https://i1.whakoom.com/small/17/03/8a1b4ec14ac048c38f6e268b49f7b64b.jpg","published":true,"releaseDate":null}]',NULL,NULL,NULL);
