INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(73,'77944','edition','Mundo Putrefacto','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1775566396993-0qm3aj.jpg',3,'Existen tres fuerzas elementales en nuestro planeta: El Verde (La vida vegetal), El Rojo (la vida animal) y la Putrefacción (La descomposición). La vida en la Tierra depende del equilibrio entre estas tres fuerzas, pero en determinadas epocas una de las tres fuerzas toma predominio sobre las demas e intenta dominar el planeta. En esas epocas de desequilibrio el parlamento de cada uno de las fuerzas elementales nombra a un Avatar y comienza entonces una batalla que decidirá la suerte del planeta. En esta epoca oscura Anton Arcane actúa como avatar de la Putrefacción y los Avatares del Rojo y el Verde, la Cosa del Pantano y Animal Man, unen sus fuerzas para restaurar el equilibrio. En este crossover se narra la batalla que decidirá si el Mundo Putrefacto será el destino del Nuevo Universo DC.','https://www.whakoom.com/ediciones/77944','2026-04-07 12:53:17','2026-04-07 12:53:24',1,'Rústica 176-160-184 pp','Terminada','. 26X17 cm. color','Existen tres fuerzas elementales en nuestro planeta: El Verde (La vida vegetal), El Rojo (la vida animal) y la Putrefacción (La descomposición). La vida en la Tierra depende del equilibrio entre estas tres fuerzas, pero en determinadas epocas una de las tres fuerzas toma predominio sobre las demas e intenta dominar el planeta. En esas epocas de desequilibrio el parlamento de cada uno de las fuerzas elementales nombra a un Avatar y comienza entonces una batalla que decidirá la suerte del planeta. En esta epoca oscura Anton Arcane actúa como avatar de la Putrefacción y los Avatares del Rojo y el Verde, la Cosa del Pantano y Animal Man, unen sus fuerzas para restaurar el equilibrio. En este crossover se narra la batalla que decidirá si el Mundo Putrefacto será el destino del Nuevo Universo DC.','[{"name":"Steve Pugh","role":"Dibujo, Tinta"},{"name":"Nathan Fairbairn","role":"Color"},{"name":"Yanick Paquette","role":"Dibujo, Tinta"},{"name":"Lovern Kindzierski","role":"Color"},{"name":"Tony Aviña","role":"Color"},{"name":"Jeff Lemire","role":"Guion"},{"name":"Scott Snyder","role":"Guion"},{"name":"Andrew Belanger","role":"Dibujo, Tinta"},{"name":"Becky Cloonan","role":"Dibujo, Tinta"},{"name":"Marco Rudy","role":"Dibujo, Tinta"}]','[{"id":"NbLHk","number":1,"title":"Mundo Putrefacto #1","subtitle":"El reino verde","cover":"https://i1.whakoom.com/small/33/3f/e871aef52b384c7ab80445724b953254.jpg","published":true,"releaseDate":null},{"id":"NbLt8","number":2,"title":"Mundo Putrefacto #2","subtitle":"Los secretos de los muertos","cover":"https://i1.whakoom.com/small/32/03/13965eecfd804e1c83888f27076eb563.jpg","published":true,"releaseDate":null},{"id":"NbLF7","number":3,"title":"Mundo Putrefacto #3","subtitle":"El reino rojo","cover":"https://i1.whakoom.com/small/2b/08/7874ce079fa44c29852df8b96c4ee1f2.jpg","published":true,"releaseDate":null}]','2026-04-07T12:53:25.411Z',NULL,NULL);
