INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(75,'78002','edition','Liga de la Justicia Oscura. Nuevo Universo DC','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1775566488440-yyfwjd.jpg',11,'LIGA DE LA JUSTICIA OSCURA: Hace cinco años, el hallazgo de un extraño artefacto alienígena obligó a Batman y a Green Lantern a pedir ayuda a Superman. Aquella misión se convirtió en la génesis de la Liga de la Justicia, un grupo que deslumbró al mundo entero cuando los superhéroes eran toda una novedad que ni las autoridades ni los ciudadanos de a pie habían asimilado. Pero no todas las amenazas a nuestro mundo proceden de alienigenas o malvados supervillanos, cuando la Liga de la Justicia no es capaz de detener a un monstruo sobrenatural o un ente de pura magia, es el momento de la Liga de la Justicia Oscura: un grupo de hechiceros, visionarios, fantasmas, sortílegos y demás criaturas de la magia capaces de combatir al otro lado del espejo.','https://www.whakoom.com/ediciones/78002','2026-04-07 12:54:49','2026-04-07 12:55:13',0,'Rústica 96-128 pp','Terminada','. Color. 26x17 cm','LIGA DE LA JUSTICIA OSCURA: Hace cinco años, el hallazgo de un extraño artefacto alienígena obligó a Batman y a Green Lantern a pedir ayuda a Superman. Aquella misión se convirtió en la génesis de la Liga de la Justicia, un grupo que deslumbró al mundo entero cuando los superhéroes eran toda una novedad que ni las autoridades ni los ciudadanos de a pie habían asimilado. Pero no todas las amenazas a nuestro mundo proceden de alienigenas o malvados supervillanos, cuando la Liga de la Justicia no es capaz de detener a un monstruo sobrenatural o un ente de pura magia, es el momento de la Liga de la Justicia Oscura: un grupo de hechiceros, visionarios, fantasma