INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(76,'77995','edition','Aquaman. Nuevo Universo DC / Renacimiento','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1775566536772-hn97pr.jpg',26,'AQUAMAN: El pequeño Arthur Curry creció en tierra firme con su padre, el farero Thomas, un solitario que había conocido el amor con Atlanna, fugitiva de la mítica ciudad sumergida de Atlantis. Huérfano de madre y ajeno a su legado, Arthur vivió sus primeros años educado en la bondad, como un niño más, pese a estar dotado de habilidades sobrehumanas como sus poderes telepáticos, que le permitían comunicarse con las criaturas marinas. Llegó a ser monarca de los atlantes, contrajo matrimonio con Mera y estuvo entre los miembros fundadores de la Liga de la Justicia. Sin embargo, prefiere llevar una vida más cercana a la de los habitantes de la superficie, por quienes se ve continuamente vilipendiado, que a la de aquellos que le venerarían como su rey.','https://www.whakoom.com/ediciones/77995','2026-04-07 12:55:37','2026-04-07 12:55:41',1,'Rústica 72-144 pp','Terminada','Color. 26x17 cm. Colección cuatrimestral de paginación variable.','AQUAMAN: El pequeño Arthur Curry creció en tierra firme con su padre, el farero Thomas, un solitario que había conocido el amor con Atlanna, fugitiva de la mítica ciudad sumergida de Atlantis. Huérfano de madre y ajeno a su legado, Arthur vivió sus primeros años educado en la bondad, como un niño más, pese a estar dotado de habilidades sobrehumanas como sus poderes telepáticos, que le permitían comunicarse con las criaturas marinas. Llegó a ser monarca de los atlantes, contrajo matrimonio con Mera y estuvo entre los miembros fundadores de la Liga de la Justicia. Sin embargo, prefiere llevar una vida más cercana a la de los habitantes de la superficie, por quienes se ve continuamente vilipendiado, que a la de aquellos que le venerarían como su rey.','[{"name":"Dan Abnett","role":"Guion"},{"name":"Rod Reis","role":"Color"},{"name":"Sean Parsons","role":"Tinta"},{"name":"Scot Eaton","role":"Dibujo"},{"name":"Philippe Briones","role":"Dibujo"},{"name":"Wayne Faucher","role":"Tinta"},{"name":"Paul Pelletier","role":"Dibujo"},{"name":"Geoff Johns","role":"Guion"},{"name":"Ivan Reis","role":"Dibujo, Tinta"},{"name":"Joe Prado","role":"Dibujo, Tinta"}]','[{"id":"xaoMk","number":0,"title":"Aquaman. Nuevo Universo DC / Renacimiento #24/10","subtitle":"El beso de despedida","cover":"https://i1.whakoom.com/small/1f/2d/15fed78b14374be398fb7fc0ed85bcc8.jpg","published":true,"releaseDate":null},{"id":"jxoDw","number":0,"title":"Aquaman. Nuevo Universo DC / Renacimiento #25/11","subtitle":"","cover":"https://i1.whakoom.com/small/13/3e/3bc9583e8f7f4b1c9b8a3f93c133feb1.jpg","published":true,"releaseDate":null},{"id":"6xDMf","number":0,"title":"Aquaman. Nuevo Universo DC / Renacimiento #26/12","subtitle":"¡Hundid Atlantis!","cover":"https://i1.whakoom.com/small/32/2f/afaa233114cf41629cd2f4d6163c1ac1.jpg","published":true,"releaseDate":null},{"id":"yNGf1","number":1,"title":"Aquaman. Nuevo Universo DC / Renacimiento #1","subtitle":"Aquaman de Geoff Johns","cover":"https://i1.whakoom.com/small/24/2e/ec84f685e16a401482a15ab5b29b6822.jpg","published":true,"releaseDate":null},{"id":"jNGfg","number":2,"title":"Aquaman. Nuevo Universo DC / Renacimiento #2","subtitle":"El secreto de los Otros","cover":"https://i1.whakoom.com/small/23/38/7204672739b0451e90082723d854da99.jpg","published":true,"releaseDate":null},{"id":"jNGfd","number":3,"title":"Aquaman. Nuevo Universo DC / Renacimiento #3","subtitle":"A la caza de Manta Negra","cover":"https://i1.whakoom.com/small/06/2e/879da25e9529461a88f6adf72b93110e.jpg","published":true,"releaseDate":null},{"id":"NGffq","number":4,"title":"Aquaman. Nuevo Unive