INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(77,'77985','edition','Wonder Woman (2012- 2022)','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1775567530769-uj1pwp.jpg',37,'WONDER WOMAN: Diana forma parte de la nación de Themyscira, isla donde las míticas amazonas fundaron una civilización sin el yugo de la sociedad patriarcal. Como hija de la reina Hipólita, asume su rol como princesa y embajadora de sus hermanas ante el mundo de los hombres, protegiéndolo como miembro de la Liga de la Justicia y difundiendo el mensaje de paz y armonía de su isla paraíso.','https://www.whakoom.com/ediciones/77985','2026-04-07 13:12:11','2026-04-10 12:53:24',0,'Rústica 96-136 pp','Terminada','26x17 cm. Color Colección de periodicidad cuatrimestral y paginación variable','WONDER WOMAN: Diana forma parte de la nación de Themyscira, isla donde las míticas amazonas fundaron una civilización sin el yugo de la sociedad patriarcal. Como hija de la reina Hipólita, asume su rol como princesa y embajadora de sus hermanas ante el mundo de los hombres, protegiéndolo como miembro de la Liga de la Justicia y difundiendo el mensaje de paz y armonía de su isla paraíso.','[{"name":"Brian Azzarello","role":"Guion"},{"name":"Cliff Chiang","role":"Dibujo, Tinta"},{"name":"Emanuela Lupacchino","role":"Dibujo"},{"name":"Greg Rucka","role":"Guion"},{"name":"Liam Sharp","role":"Dibujo"},{"name":"Jesús Merino","role":"Dibujo"},{"name":"G. Willow Wilson","role":"Guion"},{"name":"Goran Sudzuka","role":"Dibujo"},{"name":"James Robinson","role":"Guion"},{"name":"Nicola Scott","role":"Dibujo"}]','[{"id":"6NGdm","number":1,"title":"Wonder Woman (2012- 2022) #1","subtitle":"El nuevo Universo DC empieza aquí","cover":"https://i1.whakoom.com/small/37/37/29393862ea374f5f8d9