INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(79,'118213','edition','Batman Inc.','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1775572953540-jctz5c.jpg',3,'Tras regresar de su exilio temporal, Bruce Wayne sorprende a propios y extraños admitiendo que durante los últimos años ha subvencionado la cruzada contra el crimen del Hombre Murciélago. Una confesión que lleva un paso más allá al declarar su intención de, bajo el logo corporativo de Batman Incorporated, elevar dicha contienda a un nivel internacional. Un proceso que implicará el reclutamiento de nuevos héroes, dignos de portar el emblema del murciélago y capaces de afrontar la amenaza que representa la organización terrorista Leviatán.','https://www.whakoom.com/ediciones/118213','2026-04-07 14:42:34','2026-04-07 14:42:42',1,'Rústica 120 pp','Terminada',NULL,'Tras regresar de su exilio temporal, Bruce Wayne sorprende a propios y extraños admitiendo que durante los últimos años ha subvencionado la cruzada contra el crimen del Hombre Murciélago. Una confesión que lleva un paso más allá al declarar su intención de, bajo el logo corporativo de Batman Incorporated, elevar dicha contienda a un nivel internacional. Un proceso que implicará el reclutamiento de nuevos héroes, dignos de portar el emblema del murciélago y capaces de afrontar la amenaza que representa la organización terrorista Leviatán.','[{"name":"Nathan Fairbairn","role":"Color"},{"name":"Grant Morrison","role":"Guion"},{"name":"Chris Burnham","role":"Guion, Dibujo, Tinta"},{"name":"Jason Masters","role":"Dibujo, Tinta"},{"name":"Hi-Fi Desing","role":"Color"},{"name":"Frank Quitely","role":"Dibujo, Tinta"},{"name":"Jorge Lucas","role":"Dibujo, Tinta"},{"name":"Ian Hannin","role":"Color"},{"name":"Frazer Irvi