INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(81,'683513','edition','¡Shazam! DC Premiere.','Panini Comics España','https://inventario-api.josepec.workers.dev/covers/1775579266905-2dwodu.jpg',NULL,'El superequipo creativo compuesto por Mark Waid y Dan Mora te trae más magia! ¡Dinosaurios del espacio! ¡Gusanos homicidas y tigres parlantes! ¡Robots atómicos, mundos alienígenas, científicos locos, siniestras maldiciones y villanos traídos de todo el Universo DC! Todos ellos te dan la bienvenida a las salvajes aventuras de Billy Batson, cuyo enorme alter ego carmesí defiende la Tierra de las amenazas más extrañas. Si quieres parar a Lex Luthor o al Joker, llama a Superman o a Batman. Para crisis internacionales, acude a Wonder Woman. Pero cuando Garguax, Emperador de la Luna, se dirige a Ciudad Gorila, toca gritar “¡Shazam!”.','https://www.whakoom.com/ediciones/683513','2026-04-07 16:27:47','2026-04-07 16:28:01',1,'Rústica 144 pp','En curso','17x26 cm Color PVP 14€','El superequipo creativo compuesto por Mark Waid y Dan Mora te trae más magia! ¡Dinosaurios del espacio! ¡Gusanos homicidas y tigres parlantes! ¡Robots atómicos, mundos alienígenas, científicos locos, siniestras maldiciones y villanos traídos de todo el Universo DC! Todos ellos te dan la bienvenida a las salvajes aventuras de Billy Batson, cuyo enorme alter ego carmesí defiende la Tierra de las amenazas más extrañas. Si quieres parar a Lex Luthor o al Joker, llama a Superman o a Batman. Para crisis internacionales, acude a Wonder Woman. Pero cuando Garguax, Emperador de la Luna, se dirige a Ciudad Gorila, toca gritar “¡Shazam!”.','[{"name":"Mark Waid","role":"Guion"},{"name":"Dan Mora","role":"Dibujo"},{"name":"Alejandro Sánchez","role":"Color"}]','[{"id":"j9vtx","number":1,"title":"