INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(84,'678986','edition','All In Los Nuevos Dioses','Panini Comics España','https://inventario-api.josepec.workers.dev/covers/1775579421135-z8z340.jpg',3,'Ram V y Evan Cagle acercan el Cuarto Mundo a toda una nueva generación, con una épica de proporciones cósmicas. Las reverberaciones de la muerte de un viejo dios se sienten en todo el universo, despertando ejércitos intergalácticos y los letárgicos poderes de un misterioso niño terrestre. Todo esto fue vaticinado en la profecía de la Fuente con la que su agente, Metrón, sume a los habitantes de Nueva Génesis y Apókolips en el caos... Mientras, en la Tierra, Scott Free y Barda se enfrentan al desafío de la paternidad.','https://www.whakoom.com/ediciones/678986','2026-04-07 16:30:21','2026-04-07 16:30:27',1,'Rústica 72 pp','En curso','17x26 cm Color PVP 6,50€','Ram V y Evan Cagle acercan el Cuarto Mundo a toda una nueva generación, con una épica de proporciones cósmicas. Las reverberaciones de la muerte de un viejo dios se sienten en todo el universo, despertando ejércitos intergalácticos y los letárgicos poderes de un misterioso niño terrestre. Todo esto fue vaticinado en la profecía de la Fuente con la que su agente, Metrón, sume a los habitantes de Nueva Génesis y Apókolips en el caos... Mientras, en la Tierra, Scott Free y Barda se enfrentan al desafío de la paternidad.','[{"name":"Ram V","role":"Guion"},{"name":"Evan Cagle","role":""},{"name":"Pye Parr","role":""},{"name":"Denys Cowan","role":""},{"name":"Phil Hester","role":""}]','[{"id":"fRDRq","number":1,"title":"All In Los Nuevos Dioses #1","subtitle":"","cover":"https://i1.whakoom.com/small/14/07/8b99789c91164cc9b4c221c1e840cbe1.jpg","published":true,"releaseDate":null},{"id":"89t0H","numb