INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(86,'5775','edition','The Sandman','Planeta Cómic','https://inventario-api.josepec.workers.dev/covers/1775585427018-6wrpls.jpg',7,'El protagonista de The Sandman es Sueño, la personificación antropomórfica de los sueños mismos. Es conocido por una amplia variedad de nombres, encabezados por Morfeo, pero también Oneiros, el Formador, el Príncipe de las Historias, y muy raramente por el Arenero (por la leyenda celta acerca de un duende que arrojaba arena a los ojos de los durmientes permitiéndoles así el sueño). Este último nombre da título a la serie (The Sandman), aunque prácticamente es una herencia de otro personaje con el mismo nombre dentro del universo de DC.','https://www.whakoom.com/ediciones/5775','2026-04-07 18:10:07','2026-04-07 18:10:42',1,'Cartoné 496 pp','Terminada','(2010-2011)','El protagonista de The Sandman es Sueño, la personificación antropomórfica de los sueños mismos. Es conocido por una amplia variedad de nombres, encabezados por Morfeo, pero también Oneiros, el Formador, el Príncipe de las Historias, y muy raramente por el Arenero (por la leyenda celta acerca de un duende que arrojaba arena a los ojos de los durmientes permitiéndoles así el sueño). Este último nombre da título a la serie (The Sandman), aunque prácticamente es una herencia de otro personaje con el mismo nombre dentro del universo de DC.','[{"name":"Neil Gaiman","role":"Guion"},{"name":"Daniel Vozzo","role":"Dibujo, Color"},{"name":"Charles Vess","role":"Dibujo"},{"name":"Michael Zulli","role":"Dibujo"},{"name":"Dick Giordano","role":"Dibujo"},{"name":"Bryan Talbot","role":"Dibujo, Tinta"},{"name":"Vince Locke","role":"Dibujo"},{"name":"Malcolm Jones Iii","role":"Dibujo"},{"name":"Mike Dringenberg","role":"Dibujo"},{"name":"Colleen Doran","role":"Dibujo"},{"name":"Philip Craig Russell","role":"Dibujo"}]','[{"id":"81LR7","number":1,"title":"The Sandman #1","subtitle":"Sueño","cover":"https://i1.whakoom.com/small/39/1f/c5b4794abd404d0ca49194f88c834c14.jpg","published":true,"releaseDate":null},{"id":"j1LD7","number":2,"title":"The Sandman #2","subtitle":"Deseo","cover":"https://i1.whakoom.com/small/11/38/e9d4692f9e424a46ad21764890ecff13.jpg","published":true,"releaseDate":null},{"id":"jk1XT","number":3,"title":"The Sandman #3","subtitle":"Delirio","cover":"https://i1.whakoom.com/small/15/38/2351c4b600d0490386511040ef0b76a4.jpg","published":true,"releaseDate":null},{"id":"j1XNq","number":4,"title":"The Sandman #4","subtitle":"Destrucción","cover":"https://i1.whakoom.com/small/29/18/da5045a691d54242bdbf9fbad1a93a0c.jpg","published":true,"releaseDate":null},{"id":"jk1X5","number":5,"title":"The Sandman #5","subtitle":"Desesperación","cover":"https://i1.whakoom.com/small/24/39/c4d2dc4af4c2426ca362fd3250cc61b3.jpg","published":true,"releaseDate":null},{"id":"j1XVk","number":6,"title":"The Sandman #6","subtitle":"Destino","cover":"https://i1.whakoom.com/small/32/3f/73520c4c71cd458db5410d869f0f29f4.jpg","published":true,"releaseDate":null},{"id":"61Lik","number":7,"title":"The Sandman #7","subtitle":"Muerte","cover":"https://i1.whakoom.com/small/2d/10/6094ad336cdf40f096c48c1f4da20600.jpg","published":true,"releaseDate":null}]','2026-04-07T18:10:42.189Z',5,NULL);
