INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(88,'5423','edition','Predicador','Planeta Cómic','https://inventario-api.josepec.workers.dev/covers/1775585574796-t4dscs.jpg',3,'Sincero, cáustico y directamente profano, Predicador es un cómic que sigue el viaje épico del reverendo Jesse Custer en persecución de un Dios fugitivo, para hacerle responder por todo el sufrimiento de su creación. Desde las cenizas de una iglesia de pueblo hasta las luces brillantes de Nueva York, pasando por los pantanos de Louisiana, Jesse y sus amigos recorren el alma de América en una búsqueda de lo divino, un esfuerzo que se verá frenado por todo el mal que puedan reunir el Cielo y la Tierra.','https://www.whakoom.com/ediciones/5423','2026-04-07 18:12:55','2026-04-07 18:13:04',1,'Cartoné 568-816 pp','Terminada','(2010)','Sincero, cáustico y directamente profano, Predicador es un cómic que sigue el viaje épico del reverendo Jesse Custer en persecución de un Dios fugitivo, para hacerle responder por todo el sufrimiento de su creación. Desde las cenizas de una iglesia de pueblo hasta las luces brillantes de Nueva York, pasando por los pantanos de Louisiana, Jesse y sus amigos recorren el alma de América en una búsqueda de lo divino, un esfuerzo que se verá frenado por todo el mal que puedan reunir el Cielo y la Tierra.','[{"name":"Garth Ennis","role":""},{"name":"Steve Dillon","role":""}]','[{"id":"vfPq8","number":1,"title":"Predicador #1","subtitle":"Antiguo Testamento","cover":"https://i1.whakoom.com/small/15/01/dada79833d7b4ce283d2a4b0f2bc5a97.jpg","published":true,"releaseDate":null},{"id":"vfn77","number":2,"title":"Predicador #2","subtitle":"Antiguo Testamento","cover":"https://i1.whakoom.com/small/2f/23/e499d05172d24e5cac6e8280b617107c.jpg","published":true,"