INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(92,'6874','edition','Trigun','Glénat España - Editores de Tebeos','https://inventario-api.josepec.workers.dev/covers/1775635331150-nrug5g.jpg',2,'Trigun es todo un westernazo futurista con mucho humor. Vash la Estampida es el protagonista de este manga, un pistolero no muy espabilado pero con gran capacidad para crear desastres allí donde va. Para asegurarse de que no rompa nada, viaja acompañado de dos agentes de la compañía de seguros, Meryl y Milly, quienes intentarán poner algo de freno a las descabelladas ideas de Vash. Trigun 1 y 2 recogen los cuatro primeros volúmenes publicados en Japón.','https://www.whakoom.com/ediciones/6874','2026-04-08 08:02:11','2026-04-08 08:02:14',1,'Rústica con sobrecubierta','Terminada','360 páginas (2005)','Trigun es todo un westernazo futurista con mucho humor. Vash la Estampida es el protagonista de este manga, un pistolero no muy espabilado pero con gran capacidad para crear desastres allí donde va. Para asegurarse de que no rompa nada, viaja acompañado de dos agentes de la compañía de seguros, Meryl y Milly, quienes intentarán poner algo de freno a las descabelladas ideas de Vash. Trigun 1 y 2 recogen los cuatro primeros volúmenes publicados en Japón.','[{"name":"Yasuhiro Nightow","role":"Guion, Dibujo, Tinta"}]','[{"id":"8nAok","number":1,"title":"Trigun #1","subtitle":"","cover":"https://i1.whakoom.com/small/18/15/ffd0c03fb4754b49ba5ee65cc8e206f8.jpg","published":true,"releaseDate":null},{"id":"68nAI","number":2,"title":"Trigun #2","subtitle":"","cover":"https://i1.whakoom.com/small/1d/1e/4cf4bfdb5fc945299c93ecfa43b28f1b.jpg","published":true,"releaseDate":null}]','2026-04-08T08:02:15.148Z',NULL,NULL);
