INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(96,'7130','edition','Video Girl Ai','Planeta Cómic','https://inventario-api.josepec.workers.dev/covers/1775635570284-d9n6pk.jpg',15,'Yōta Moteuchi es un chico que está enamorado de su amiga Moemi; pero esta, a su vez, está enamorada de Takashi Niimai, amigo de ambos. Hablando con Yōta, Moemi confiesa sus sentimientos por Niimai, pero este la escucha y la rechaza, pensando en los sentimientos de su amigo, aunque lo que logra hacer es más bien hacerle daño, ya que a Yōta le importa mas la felicidad de Moemi que la suya propia.','https://www.whakoom.com/ediciones/7130','2026-04-08 08:06:11','2026-04-08 08:06:16',1,'Rústica con sobrecubierta 192 pp','Terminada','2001-2003)','Yōta Moteuchi es un chico que está enamorado de su amiga Moemi; pero esta, a su vez, está enamorada de Takashi Niimai, amigo de ambos. Hablando con Yōta, Moemi confiesa sus sentimientos por Niimai, pero este la escucha y la rechaza, pensando en los sentimientos de su amigo, aunque lo que logra hacer es más bien hacerle daño, ya que a Yōta le importa mas la felicidad de Moemi que la suya propia.','[{"name":"Masakazu Katsura","role":"Guion, Dibujo, Tinta"}]','[{"id":"jnDG7","number":1,"title":"Video Girl Ai #1","subtitle":"","cover":"https://i1.whakoom.com/small/03/3c/88aaa701090f4eda84c905f5acf3a99a.jpg","published":true,"releaseDate":null},{"id":"8nDl7","number":2,"title":"Video Girl Ai #2","subtitle":"","cover":"https://i1.whakoom.com/small/16/28/fcdb83549d7e4ee0a31b6b44eac9f4d1.jpg","published":true,"releaseDate":null},{"id":"ynD06","number":3,"title":"Video Girl Ai #3","subtitle":"","cover":"https://i1.whakoom.com/small/06/3e/32b12248525b4ff18230522dd3f3f0a5.jpg","published":true,"releaseDate":null},{"id":"jnD3k","number":4,"t