INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(97,'1675','edition','D・N・A²','Planeta Cómic','https://inventario-api.josepec.workers.dev/covers/1775657540717-4byuu6.jpg',5,'En un futuro donde el viaje en el tiempo y la alteración del ADN es una realidad, la sobrepoblación está llevando a la humanidad hacia la extinción. Los investigadores se dan cuenta de la existencia de un humano en el siglo XX con un gen especial, el cual lo convirtió en un superhumano extremadamente fértil e irresistible a las mujeres.','https://www.whakoom.com/ediciones/1675','2026-04-08 14:12:21','2026-04-08 14:12:24',1,'Rústica con sobrecubierta','Terminada',NULL,'En un futuro donde el viaje en el tiempo y la alteración del ADN es una realidad, la sobrepoblación está llevando a la humanidad hacia la extinción. Los investigadores se dan cuenta de la existencia de un humano en el siglo XX con un gen especial, el cual lo convirtió en un superhumano extremadamente fértil e irresistible a las mujeres.','[{"name":"Masakazu Katsura","role":"Guion, Dibujo, Tinta"}]','[{"id":"jjrNT","number":1,"title":"D・N・A² #1","subtitle":"DNA2","cover":"https://i1.whakoom.com/small/3d/29/9ce3c96189c54a5da813846776cfdb28.jpg","published":true,"releaseDate":null},{"id":"8rNNq","number":2,"title":"D・N・A² #2","subtitle":"","cover":"https://i1.whakoom.com/small/25/23/1423855694794dedbd970466de6d970f.jpg","published":true,"releaseDate":null},{"id":"ykrN5","number":3,"title":"D・N・A² #3","subtitle":"","cover":"https://i1.whakoom.com/small/2d/1f/ad3dbe28cb6c4e70800a194fec6cfc66.jpg","published":true,"releaseDate":null},{"id":"jrNV7","number":4,"title":"D・N・A² #4","subtitle":"","cover":"https://i1.whakoom.com/small/0c/07/101fd1f7f9244647a05cacfb59775d77.jpg","published":true,"releaseDate":null},{"id":"