INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(98,'287526','edition','Please Save My Earth','Mangaline España','https://inventario-api.josepec.workers.dev/covers/1775657581878-6koxnt.jpg',7,'La historia se sitúa en el Tokio de 1991. La cosmopolita capital de Japón. Allí encontramos a una tímida Alice Sakaguchi, quien se siente muy intimidada por su pequeño vecino de 8 años, Rin Kobayashi. Este niño la incomoda y siempre logra hacerla caer en sus trampas, inclusive, él le dará su primer beso. Tras esa bochornosa situación, Alice no querrá ver nunca más a Rin en su vida. Pero algo sucede. La madre de Rin va a su casa, para pedirle que se transforme en su niñera, pues dice que el niño este último tiempo se ha sentido muy a gusto con Alice. Al fin acepta, pese a sus temores.','https://www.whakoom.com/ediciones/287526','2026-04-08 14:13:02','2026-04-08 14:13:02',1,'Rústica con sobrecubierta','Terminada','Mangaline en esta edición sólo publicó los siete primeros números Tankōbon (2001)','La historia se sitúa en el Tokio de 1991. La cosmopolita capital de Japón. Allí encontramos a una tímida Alice Sakaguchi, quien se siente muy intimidada por su pequeño vecino de 8 años, Rin Kobayashi. Este niño la incomoda y siempre logra hacerla caer en sus trampas, inclusive, él le dará su primer beso. Tras esa bochornosa situación, Alice no querrá ver nunca más a Rin en su vida. Pero algo sucede. La madre de Rin va a su casa, para pedirle que se transforme en su niñera, pues dice que el niño este último tiempo se ha sentido muy a gusto con Alice. Al fin acepta, pese a sus temores.','[{"name":"Saki Hiwatari","role":"Guion, Dibujo, Tinta"}]','[{"id":"amHvq","number":1,"title":"Please Save My Earth #1","subtitle":"","cover":"https://i1.whakoom.com/small/3a/39/73c87afdd4de4610aeec6e6907229b5a.jpg","published":true,"releaseDate":null},{"id":"jamHL","number":2,"title":"Please Save My Earth #2","subtitle":"","cover":"https://i1.whakoom.com/small/36/0b/0972ccd6410f40db841e49feae7f54f7.jpg","published":true,"releaseDate":null},{"id":"8amHX","number":3,"title":"Please Save My Earth #3","subtitle":"","cover":"https://i1.whakoom.com/small/0a/3c/37e236a268e748ff8ff4bee204bbc27a.jpg","published":true,"releaseDate":null},{"id":"amH1k","number":4,"title":"Please Save My Earth #4","subtitle":"","cover":"https://i1.whakoom.com/small/2c/0c/27ab06ac7a3446aaaa1085ddb981f817.jpg","published":true,"releaseDate":null},{"id":"amHg7","number":5,"title":"Please Save My Earth #5","subtitle":"","cover":"https://i1.whakoom.com/small/38/25/ba51c2a4691e461b86534c92d69910fc.jpg","published":true,"releaseDate":null},{"id":"8amHd","number":6,"title":"Please Save My Earth #6","subtitle":"","cover":"https://i1.whakoom.com/small/33/0f/6225f936aaa847a8a51fa10dba728fbf.jpg","published":true,"releaseDate":null},{"id":"jrIGf","number":7,"title":"Please Save My Earth #7","subtitle":"","cover":"https://i1.whakoom.com/small/08/0f/3b102268b61141e7a93e327f6095ac10.jpg","published":true,"releaseDate":null}]',NULL,NULL,NULL);
