INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(106,'822','edition','Bobobo-bo bo-bobo','Planeta Cómic','https://inventario-api.josepec.workers.dev/covers/1775671458319-ahpm7w.jpg',21,'Para algunos de los que la padecen, la calvicie es un problema que puede llegar a nublar su juicio. Este parece ser el caso del Emperador Bola de Billar IV, quien, obsesionado con su falta de cabello, tiene una idea genial para no sentirse en inferioridad ante los que poseen una exuberante cabellera: crear un ejército cuya única misión es rapar la cabeza de todos los habitantes del imperio. Naturalmente, muchos de sus abnegados súbditos no se alegran, precisamente, de que les rapen al cero, y se sienten indefensos.','https://www.whakoom.com/ediciones/822','2026-04-08 18:04:19','2026-04-08 18:04:23',1,'Rústica','Terminada','Con sobrecubierta','Para algunos de los que la padecen, la calvicie es un problema que puede llegar a nublar su juicio. Este parece ser el caso del Emperador Bola de Billar IV, quien, obsesionado con su falta de cabello, tiene una idea genial para no sentirse en inferioridad ante los que poseen una exuberante cabellera: crear un ejército cuya única misión es rapar la cabeza de todos los habitantes del imperio. Naturalmente, muchos de sus abnegados súbditos no se alegran, precisamente, de que les rapen al cero, y se sienten indefensos.','[{"name":"Yoshio Sawai","role":"Guion, Dibujo, Tinta"}]','[{"id":"5Ot7q","number":1,"title":"Bobobo-bo bo-bobo #1","subtitle":"","cover":"https://i1.whakoom.com/small/3e/1f/195b13fa04d74d2bb79c979ebb0545b3.jpg","published":true,"releaseDate":null},{"id":"y5OF6","number":2,"title":"Bobobo-bo bo-bobo #2","subtitle":"","cover":"https://i1.whakoom.com/small/33/36/b8693cdd9c094c418260af4d7dec193c.jpg","published":tr