INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(116,'1740','edition','Dragon Ball - Ultimate Edition','Planeta Cómic','https://inventario-api.josepec.workers.dev/covers/1775729408495-skbc4b.jpg',34,'Son Goku es un chico muy especial que, tras la muerte de su abuelo, vive solo en el bosque. Posee una fuerza prodigiosa y parece bastante satisfecho con su vida al aire libre hasta que conoce a Bulma, una niña pija que está buscando las Bolas de Dragón, siete esferas mágicas que, una vez reunidas, pueden conceder cualquier deseo. Casualmente, Goku posee una de ellas, la de cuatro estrellas, por lo que a Bulma le cuesta un poco convencerle de que se una a ella en su búsqueda... ¡Así empieza el manga más popular de todos los tiempos!','https://www.whakoom.com/ediciones/1740','2026-04-09 10:10:09','2026-04-09 10:10:16',1,'Rústica','Terminada','Tomo A5 (148x210 mm) con Sobrecubierta','Son Goku es un chico muy especial que, tras la muerte de su abuelo, vive solo en el bosque. Posee una fuerza prodigiosa y parece bastante satisfecho con su vida al aire libre hasta que conoce a Bulma, una niña pija que está buscando las Bolas de Dragón, siete esferas mágicas que, una vez reunidas, pueden conceder cualquier deseo. Casualmente, Goku posee una de ellas, la de cuatro estrellas, por lo que a Bulma le cuesta un poco convencerle de que se una a ella en su búsqueda... ¡Así empieza el manga más popular de todos los tiempos!','[{"name":"Akira Toriyama","role":"Guion, Dibujo, Tinta"}]','[{"id":"r2Dqq","number":1,"title":"Dragon Ball - Ultimate Edition #1","subtitle":"","cover":"https://i1.whakoom.com/small/00/28/94ab9efc8413492d8b832ee6b9b70525.jpg","published":true,"releaseDate":null},{"id":"jr4Tk","number":2,"title":"Dragon Ball - Ultimate Edition #2","subtitle":"