INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(117,'121','edition','Abara','Panini Comics España','https://inventario-api.josepec.workers.dev/covers/1775729641917-121ogw.jpg',2,'Un mundo con gigantescos mausoleos cuyo origen nadie sabe si es producto de la naturaleza o de la mano del hombre. De repente, aparece un monstruo blanco como la nieve; se mueve tan rápido que el ojo humano no puede captarlo. Masacra y devora a las personas.','https://www.whakoom.com/ediciones/121','2026-04-09 10:14:02','2026-04-09 10:14:05',1,'Rústica con sobrecubierta','Terminada','B/N. 16,5x23 cm. PVP 9,95€','Un mundo con gigantescos mausoleos cuyo origen nadie sabe si es producto de la naturaleza o de la mano del hombre. De repente, aparece un monstruo blanco como la nieve; se mueve tan rápido que el ojo humano no puede captarlo. Masacra y devora a las personas.','[{"name":"Tsutomu Nihei","role":"Guion, Dibujo, Tinta"}]','[{"id":"HW77q","number":1,"title":"Abara #1","subtitle":"","cover":"https://i1.whakoom.com/small/22/08/de7ce5a10a6445cfa14c2cea67fb92f4.jpg","published":true,"releaseDate":null},{"id":"HF77q","number":2,"title":"Abara #2","subtitle":"","cover":"https://i1.whakoom.com/small/04/31/9dd63f13a1e049bd976b9d2426aa4396.jpg","published":true,"releaseDate":null}]','2026-04-09T10:14:06.425Z',NULL,NULL);
INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(118,'3649','edition','La espada del Inmortal','Glénat España - Editores de Tebeos / Planeta Cómic','https://inventario-api.josepec.workers.dev/covers/1775730197036-dtyaaz.jpg',30,'La historia está ambientada en el Japón de la era Edo. El protagonista, Manji, es un guerrero que tiene una gran ventaja sobre sus rivales: ninguna herida lo puede matar. En el pasado mató a otros 100 samuráis, entre ellos el marido de su hermana. Una monja anciana, de la que se dice que tiene 800 años, le concede el don de la inmortalidad mediante unos gusanos llamados kessenchū, que le curan cualquier herida y hasta restauran miembros amputados aunque la amputación haya sido hace horas. La muerte de su hermana lo lleva a aceptar la misión que acabará con su inmortalidad: debe matar a 1000 hombres malvados para redimirse.','https://www.whakoom.com/ediciones/3649','2026-04-09 10:23:17','2026-04-09 10:23:32',1,'Rústica','Terminada','Con sobrecubierta','La historia está ambientada en el Japón de la era Edo. El protagonista, Manji, es un guerrero que tiene una gran ventaja sobre sus rivales: ninguna herida lo puede matar. En el pasado mató a otros 100 samuráis, entre ellos el marido de su hermana. Una monja anciana, de la que se dice que tiene 800 años, le concede el don de la inmortalidad mediante unos gusanos llamados kessenchū, que le curan cualquier herida y hasta restauran miembros amputados aunque la amputación haya sido hace horas. La muerte de su hermana lo lleva a aceptar la misión que acabará con su inmortalidad: debe matar a 1000 hombres malvados para redimirse.','[{"name":"Hiroaki Samura","role":"Guion, Dibujo, Tinta"}]','[{"id":"B0D77","number":1,"title":"La espada del Inmortal #1","subtitle":"","cover":"https