INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(119,'5924','edition','Sidooh','Glénat España - Editores de Tebeos','https://inventario-api.josepec.workers.dev/covers/1775730312074-gx0oja.jpg',21,'Poco antes de la época de la historia japonesa conocida como "Bakumatsu" (fin del shogunato), dos hermanos fueron abandonados en medio de un mundo convulso. El mayor se llamaba Shotaro Yukimura y tenía 14 años; el menor, Gentaro Yukimura, tenía 10 años... Dos "Samuráis" infantiles que juran sobrevivir sin la ayuda de nadie en una época desprovista de piedad, repleta de caos y sangre por doquier. ¡He aquí el inicio del cómic "Rockero" de samuráis definitivo!','https://www.whakoom.com/ediciones/5924','2026-04-09 10:25:12','2026-04-09 10:25:19',1,'Rústica con sobrecubierta','Terminada','Edición cancelada en 21 de 25 Tomos','Poco antes de la época de la historia japonesa conocida como "Bakumatsu" (fin del shogunato), dos hermanos fueron abandonados en medio de un mundo convulso. El mayor se llamaba Shotaro Yukimura y tenía 14 años; el menor, Gentaro Yukimura, tenía 10 años... Dos "Samuráis" infantiles que juran sobrevivir sin la ayuda de nadie en una época desprovista de piedad, repleta de caos y sangre por doquier. ¡He aquí el inicio del cómic "Rockero" de samuráis definitivo!','[{"name":"Tsutomu Takahashi","role":"Guion, Dibujo, Tinta"}]','[{"id":"gOV7q","number":1,"title":"Sidooh #1","subtitle":"","cover":"https://i1.whakoom.com/small/05/0f/75d3cca230a249b2af26eb54de5e2880.jpg","published":true,"releaseDate":null},{"id":"gOwq6","number":2,"title":"Sidooh #2","subtitle":"","cover":"https://i1.whakoom.com/small/04/34/c91a369903a04e258d757c3b7f298933.jpg","published":true,"releaseDate":null},{"id":"8gOAq","number":3,"title":"Sidooh #3","subtitle":"","cove