INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(126,'356200','edition','Suiiki','Milky Way Ediciones','https://inventario-api.josepec.workers.dev/covers/1775818772189-0fffsm.jpg',2,'Un verano especialmente abrasador y además marcado por la escasez de agua. La pobre Chinami no aguanta más y se desmaya víctima de la sed y del agotamiento. Al despertar, se encuentra en un pueblo misterioro junto a un río cuyas aguas esconden muchos misterios...','https://www.whakoom.com/ediciones/356200','2026-04-10 10:59:32','2026-04-10 10:59:42',1,'Rústica con sobrecubierta','Terminada','Tamaño: 13x18 cm.  B/N con páginas a color','Un verano especialmente abrasador y además marcado por la escasez de agua. La pobre Chinami no aguanta más y se desmaya víctima de la sed y del agotamiento. Al despertar, se encuentra en un pueblo misterioro junto a un río cuyas aguas esconden muchos misterios...','[{"name":"Yuki Urushibara","role":""}]','[{"id":"zazz6","number":1,"title":"Suiiki #1","subtitle":"","cover":"https://i1.whakoom.com/small/02/00/aa107b62a2fb4a9c9725259c81598406.jpg","published":true,"releaseDate":null},{"id":"zPG2k","number":2,"title":"Suiiki #2","subtitle":"","cover":"https://i1.whakoom.com/small/17/39/2a97f61d756d4d2995b36c479ac69d72.jpg","published":true,"releaseDate":null}]','2026-04-10T10:59:38.680Z',4,NULL);
INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(127,'378382','edition','Utsubora','Milky Way Ediciones','https://inventario-api.josepec.workers.dev/covers/1775818826162-2xs05y.jpg',2,'Jun Mizorogi, afamado escritor, sucumbe a la tentación del plagio cuando una belleza que parece salida de las páginas de su última novela llega a su vida para seducirlo y atormentarlo. En medio de todo, deberá enfrentarse a las sospechas sobre la repentina y misteriosa muerte de la joven Aki Fujino, su anterior... ¿musa?','https://www.whakoom.com/ediciones/378382','2026-04-10 11:00:27','2026-04-10 11:00:31',1,'Rústica con sobrecubierta','Terminada','La sobrecubierta tiene una textura aterciopelada.','Jun Mizorogi, afamado escritor, sucumbe a la tentación del plagio cuando una belleza que parece salida de las páginas de su última novela llega a su vida para seducirlo y atormentarlo. En medio de todo, deberá enfrentarse a las sospechas sobre la repentina y misteriosa muerte de la joven Aki Fujino, su anterior... ¿musa?','[{"name":"Asumiko Nakamura","role":"Guion, Dibujo, Tinta"}]','[{"id":"zPGgk","number":1,"title":"Utsubora #1","subtitle":"","cover":"https://i1.whakoom.com/small/0b/0a/f802d6758563415c9dca2dc173885cb9.jpg","published":true,"releaseDate":null},{"id":"jzPGd","number":2,"title":"Utsubora #2","subtitle":"","cover":"https://i1.whakoom.com/small/04/25/6003b70450424469a28fc316f435fb65.jpg","published":true,"releaseDate":null}]','2026-04-10T11:00:32.111Z',NULL,NULL);
INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(128,'7039','edition','Vagabond','Ivrea','https://inventario-api.josepec.workers.dev/covers/1775818875925-38we8o.jpg',37,'Adaptación al cómic de uno de los clásicos de la literatura japonesa, la novela biográfica de Eiji Yoshikawa: "Musashi". cuenta la historia del legendario espadachín Musashi Miyamoto, la figura histórica más importante del Japón en lo que se refiere al desarrollo de las técnicas de lucha con espada. Al comienzo de la historia vemos al protagonista como un violento e iracundo joven llamado Takezo, el cual sobrevive (aun estando del lado perdedor) a una de las batallas más sangrientas de la historia: Sekigahara. Luego de que su vida da un giro gracias a la intervención de un monje llamado Takuan, el joven Takezo cambia su nombre a Musashi y se embarca en una búsqueda de autosuperación personal que lo llevará a enfrentarse con los más grandes expertos de las artes marciales del país.','https://www.whakoom.com/ediciones/7039','2026-04-10 11:01:16','2026-04-10 11:01:23',1,'Rústica con sobrecubierta','Terminada','B6','Adaptación al cómic de uno de los clásicos de la literatura japonesa, la novela biográfica de Eiji Yoshikawa: "Musashi". cuenta la historia del legendario espadachín Musashi Miyamoto, la figura histórica más importante del Japón en lo que se refiere al desarrollo de las técnicas de lucha con espada. Al comienzo de la historia vemos al protagonista como un violento e iracundo joven llamado Takezo, el cual sobrevive (aun estando del lado perdedor) a una de las batallas más sangrientas de la historia: Sekigahara. Luego de que su vida da un giro gracias a la intervención de un monje llamado Takuan, el joven Takezo cambia su nombre a Musashi y se embarca en una búsqueda de autosuperación personal que lo llevará a enfrentarse con los más grandes expertos de las artes marciales del país.','[{"name":"Takehiko Inoue","role":"Guion, Dibujo, Tinta"}]','[{"id":"noZ76","number":1,"title":"Vagabond #1","subtitle":"","cover":"https://i1.whakoom.com/small/28/20/1ed93bff3f3049dca156ddb003cf2221.jpg","published":true,"releaseDate":null},{"id":"6nobk","number":2,"title":"Vagabond #2","subtitle":"","cover":"https://i1.whakoom.com/small/1c/1e/ded0e7e1a0f343938884bb380060c749.jpg","published":true,"releaseDate":null},{"id":"y8noG","number":3,"title":"Vagabond #3","subtitle":"","cover":"https://i1.whakoom.com/small/3b/37/f03ebfa14a3345679a32b86ad0ba4d01.jpg","published":true,"releaseDate":null},{"id":"knol7","number":4,"title":"Vagabond #4","subtitle":"","cover":"https://i1.whakoom.com/small/39/32/c422830d580040d2b875ece39077e5d7.jpg","published":true,"releaseDate":null},{"id":"jkno0","number":5,"title":"Vagabond #5","subtitle":"","cover":"https://i1.whakoom.com/small/1b/36/57a27e1eef9448c882740b4226fc7ea6.jpg","published":true,"releaseDate":null},{"id":"no377","number":6,"title":"Vagabond #6","subtitle":"","cover":"https://i1.whakoom.com/small/22/04/f38679686a204aed917d6e7175bb31ae.jpg","published":true,"releaseDate":null},{"id":"ynoi7","number":7,"title":"Vagabond #7","subtitle":"","cover":"https://i1.whakoom.com/small/15/27/f1261632c19a4fbba4f32546cadb63c8.jpg","published":true,"releaseDate":null},{"id":"noR77","number":8,"title":"Vagabond #8","subtitle":"","cover":"https://i1.whakoom.com/small/37/1c/6a1da3c82870447995b4528e17916712.jpg","published":true,"releaseDate":null},{"id":"noDk7","number":9,"title":"Vagabond #9","subtitle":"","cover":"https://i1.whakoom.com/small/18/35/447f544c94344cf09016ea10ae1cfc4a.jpg","published":true,"releaseDate":null},{"id":"8jnZT","number":10,"title":"Vagabond #10","subtitle":"","cover":"https://i1.whakoom.com/small/3f/0a/99b41fdee86a47d6bdc3ba0ac7e76cfa.jpg","published":true,"releaseDate":null},{"id":"6nZNq","number