INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(131,'5748','edition','Saint Seiya - Los Caballeros del Zodíaco','Glénat España - Editores de Tebeos','https://inventario-api.josepec.workers.dev/covers/1775819324869-5c0a6i.jpg',28,'El argumento de la serie se centra en la historia de un grupo de jóvenes guerreros denominados Saints (Santos; o caballeros en varias traducciones), quienes luchan por proteger a la diosa griega Athena -que representa la sabiduria, el bien y la bondad- de las fuerzas del mal, que quieren tomar el control sobre el mundo. Para luchar, los Santos sólo utilizan su energía interior (denominada Cosmos), aplicándola a diferentes estilos de lucha y artes marciales. Sus puños y armaduras les confieren protección y están inspiradas en constelaciones o seres de la mitología griega y escandinava. Siendo el protagonista el representante de la constelación Pegaso.','https://www.whakoom.com/ediciones/5748','2026-04-10 11:08:45','2026-04-10 11:09:19',1,'Rústica','Terminada','2001-2003 Con sobrecubierta','El argumento de la serie se centra en la historia de un grupo de jóvenes guerreros denominados Saints (Santos; o caballeros en varias traducciones), quienes luchan por proteger a la diosa griega Athena -que representa la sabiduria, el bien y la bondad- de las fuerzas del mal, que quieren tomar el control sobre el mundo. Para luchar, los Santos sólo utilizan su energía interior (denominada Cosmos), aplicándola a diferentes estilos de lucha y artes marciales. Sus puños y armaduras les confieren protección y están inspiradas en constelaciones o seres de la mitología griega y escandinava. Siendo el protagonista el representante de la constelación Pegaso.','[{"name":"Masami Kurumada","role":"Guion, Dibujo, Tinta"}]','[{"id":"814p6","numbe