INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(132,'789','edition','Blame!','Glénat España - Editores de Tebeos','https://inventario-api.josepec.workers.dev/covers/1775837039385-3r03u7.jpg',10,'En un futuro dominado por la tecnología, los humanos representan una raza en peligro de extinción. La devastación asola los inmensos parajes cubiertos de metal. Nunca se sabe con certeza qué hay en niveles superiores y sólo se oyen rumores al respecto. Un humano trabaja para la Oficina Gubernamental localizando humanos con genes puros, en un contexto en que las mutaciones han ido deteriorando provocando que las máquinas no reconozcan a las personas, tomándolas por intrusos.','https://www.whakoom.com/ediciones/789','2026-04-10 16:04:00','2026-04-10 16:05:52',1,'Rústica','Terminada','Con sobrecubierta','En un futuro dominado por la tecnología, los humanos representan una raza en peligro de extinción. La devastación asola los inmensos parajes cubiertos de metal. Nunca se sabe con certeza qué hay en niveles superiores y sólo se oyen rumores al respecto. Un humano trabaja para la Oficina Gubernamental localizando humanos con genes puros, en un contexto en que las mutaciones han ido deteriorando provocando que las máquinas no reconozcan a las personas, tomándolas por intrusos.','[{"name":"Tsutomu Nihei","role":"Guion, Dibujo, Tinta"}]','[{"id":"65wg6","number":1,"title":"Blame! #1","subtitle":"","cover":"https://i1.whakoom.com/small/23/30/cff5dcc000594cdc831ee6c2cc8a799f.jpg","published":true,"releaseDate":null},{"id":"8y5wd","number":2,"title":"Blame! #2","subtitle":"","cover":"https://i1.whakoom.com/small/3c/05/b0de3bdb95c9499eab88b7e006ab1be0.jpg","published":true,"releaseDate":null},{"id":"y5wf7","number":3,"title":"Blame! #3","subtitle":"","cover":"http