INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(136,'4312','edition','Los Muertos Vivientes','Planeta Cómic','https://inventario-api.josepec.workers.dev/covers/1775851459199-0fmpyy.jpg',8,'The Walking Dead cuenta cómo Rick Grimmes, un policía estadounidense originario de Kentucky despierta de un estado de coma, después de un accidente ocurrido estando de servicio, para encontrarse con un mundo arrasado por cadáveres deseosos de carne fresca y, sin saber qué ha pasado a su alrededor, emprende la búsqueda de su familia. Aunque en realidad la causa de la aparición de los zombies no se revela por completo, dando sólo pequeños chispazos de la misma, la trama permite palpar el desarrollo humano y personal de los personajes y las vías para enfrentarse al panorama de persecución, destrucción y muerte provocado por los zombies, a quienes llaman caminantes o exterminadores.','https://www.whakoom.com/ediciones/4312','2026-04-10 20:04:20','2026-04-10 20:04:36',1,'Cartoné 592-632 pp','Terminada','26x17 cm ByN','The Walking Dead cuenta cómo Rick Grimmes, un policía estadounidense originario de Kentucky despierta de un estado de coma, después de un accidente ocurrido estando de servicio, para encontrarse con un mundo arrasado por cadáveres deseosos de carne fresca y, sin saber qué ha pasado a su alrededor, emprende la búsqueda de su familia. Aunque en realidad la causa de la aparición de los zombies no se revela por completo, dando sólo pequeños chispazos de la misma, la trama permite palpar el desarrollo humano y personal de los personajes y las vías para enfrentarse al panorama de persecución, destrucción y muerte provocado por los zombies, a quienes llaman caminantes o exterminadores.','[{"name":"Robert Kirkman","role":"Guion"},{"name":"Charlie Adlard","role":"Dibujo, Tinta"},{"name":"Cliff Rathburn","role":"Dibujo, Color"},{"name":"Stefano Gaudiano","role":"Dibujo, Tinta"},{"name":"Tony Moore","role":"Dibujo"}]','[{"id":"62Mx7","number":1,"title":"Los Muertos Vivientes #1","subtitle":"Libro uno","cover":"https://i1.whakoom.com/small/35/35/717fe92e25a741b6ba80cd5c7a30b13c.jpg","published":true,"releaseDate":null},{"id":"2Mhq7","number":2,"title":"Los Muertos Vivientes #2","subtitle":"Libro dos","cover":"https://i1.whakoom.com/small/2c/2c/0c7327b37c204e0895557b3c944fdd21.jpg","published":true,"releaseDate":null},{"id":"2MBqk","number":3,"title":"Los Muertos Vivientes #3","subtitle":"Libro tres","cover":"https://i1.whakoom.com/small/37/09/00be3953746d4099a76edd5fc0d151c4.jpg","published":true,"releaseDate":null},{"id":"jwIoF","number":4,"title":"Los Muertos Vivientes #4","subtitle":"Libro cuatro","cover":"https://i1.whakoom.com/small/12/05/062ce4f3493f4d948bf85ac0fa5de52d.jpg","published":true,"releaseDate":null},{"id":"MimZk","number":5,"title":"Los Muertos Vivientes #5","subtitle":"Libro cinco","cover":"https://i1.whakoom.com/small/06/2f/44927bb8e8604308ba195a29598f219b.jpg","published":true,"releaseDate":null},{"id":"8W2OH","number":6,"title":"Los Muertos Vivientes #6","subtitle":"","cover":"https://i1.whakoom.com/small/3c/18/ab4d87003bc640d480e924a42a3544fd.jpg","published":true,"releaseDate":null},{"id":"y2H23","number":7,"title":"Los Muertos Vivientes #7","subtitle":"","cover":"https://i1.whakoom.com/small/0c/31/defca1a4478343ea95873ab40429f2b3.jpg","published":true,"releaseDate":null},{"id":"4oxRq","number":8,"title":"Los Muertos Vivientes #8","subtitle":"","cover":"https://i1.whakoom.com/small/05/16/58ff10ef6b3f477da4b533e1387873f4.jpg","published":true,"releaseDate":null}]','2026-04-10T20:04:33.005Z',NULL,NULL);
INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(137,'524625','edition','Batman Condenado - DC Black Label','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1775983738637-zvdzty.jpg',3,'Batman: Condenado es una historia de terror sobrenatural contada por dos de los mejores autores del cómic contemporáneo: Brian Azzarello y Lee Bermejo, responsables de obras como Joker, Luthor o Antes de Watchmen: Rorschach.','https://www.whakoom.com/ediciones/524625','2026-04-12 08:48:59','2026-04-12 08:49:02',1,'Cartoné 48 pp','Terminada','Color.','Batman: Condenado es una historia de terror sobrenatural contada por dos de los mejores autores del cómic contemporáneo: Brian Azzarello y Lee Bermejo, responsables de obras como Joker, Luthor o Antes de Watchmen: Rorschach.','[{"name":"Brian Azzarello","role":"Guion"},{"name":"Lee Bermejo","role":"Dibujo, Tinta, Color"}]','[{"id":"xG3aq","number":1,"title":"Batman Condenado - DC Black Label #1","subtitle":"Batman Condenado Libro Uno","cover":"https://i1.whakoom.com/small/36/39/11edc0b5518b4da1939130851d55246a.jpg","published":true,"releaseDate":null},{"id":"hOb26","number":2,"title":"Batman Condenado - DC Black Label #2","subtitle":"Batman Condenado Libro Dos","cover":"https://i1.whakoom.com/small/37/37/c3f442f6054c431eb7acf0f392203b78.jpg","published":true,"releaseDate":null},{"id":"2VIAk","number":3,"title":"Batman Condenado - DC Black Label #3","subtitle":"Batman Condenado Libro Tres","cover":"https://i1.whakoom.com/small/21/2a/e5d4690e8d804b0381bbf78859d438ba.jpg","published":true,"releaseDate":null}]','2026-04-12T08:49:03.567Z',NULL,NULL);
INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(138,'5954','edition','Sin City. Integral','Norma Editorial','https://inventario-api.josepec.workers.dev/covers/1775983799091-y2nnwp.jpg',2,'Las historias de estas novelas gráficas transcurren en una ciudad llamada Basin City, pero Miller juega con el nombre llamándola Sin City borrando parte del nombre de la ciudad. La primera de ellas se llama El Duro Adiós y cuenta la historia de Marv, un hombre violento y desilusionado y su intento por encontrar a la persona que asesinó a Goldie, la única mujer que había sido amable con él. En un principio, esta historieta se llamaba simplemente "Sin City" y estaba pensada como una obra autoconclusiva, pero más adelante se la decidió ampliar y utilizar como universo de ficción de varias otras historias.','https://www.whakoom.com/ediciones/5954','2026-04-12 08:49:59','2026-04-12 08:50:03',1,'Cartoné 792 pp','Terminada','16,4 x 23,6 cm. Blanco/Negro. (2010-2011).','Las historias de estas novelas gráficas transcurren en una ciudad llamada Basin City, pero Miller juega con el nombre llamándola Sin City borrando parte del nombre de la ciudad. La primera de ellas se llama El Duro Adiós y cuenta la historia de Marv, un hombre violento y desilusionado y su intento por encontrar a la persona que asesinó a Goldie, la única mujer que había sido amable con él. En un principio, esta historieta se llamaba simplemente "Sin City" y estaba pensada como una obra autoconclusiva, pero más adelante se la decidió ampliar y utilizar como universo de ficción de varias otras historias.','[{"name":"Frank Miller","role":"Guion, Dibujo, Tinta, Color"}]','[{"id":"8gF27","number":1,"title":"Sin City. Integral #1","subtitle":"Edicion Integral Vol. 1","cover":"https://i1.whakoom.com/small/03/22/e36aa8cf2e144d3c800da97d47b182ae.jpg","published":true,"releaseDate":null},{"id":"8gFh7","number":2,"title":"Sin City. Integral #2","subtitle":"Edicion Integral Vol. 2","cover":"https://i1.whakoom.com/small/2a/28/652bd2dc4a0b429ca11a60da994755f6.jpg","published":true,"releaseDate":null}]','2026-04-12T08:50:04.616Z',NULL,NULL);
INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(139,'4860','edition','Mouse Guard','Norma Editorial','https://inventario-api.josepec.workers.dev/covers/1775983834895-9s62yx.jpg',3,'Tras una estética pseudo-infantil, Mouse Guard esconde una historia adulta en la que un grupo de ratones intentan apañárselas en la difícil sociedad medieval. En una tierra tranquila, los ratones viven apaciblemente en sus territorios mientras los Mouse Guards, comandados por la matriarca Gwendolyn, procuran ese estatus y protegen a comerciantes y viajeros de alimañas, lobos y comadrejas. Pero el otoño de 1152 será recordado como una época oscura: la del terror del ejército del Hacha Negra.','https://www.whakoom.com/ediciones/4860','2026-04-12 08:50:35','2026-04-12 08:50:37',1,'Cartoné 204 pp','Terminada','Tamaño 21x21 cm.','Tras una estética pseudo-infantil, Mouse Guard esconde una historia adulta en la que un grupo de ratones intentan apañárselas en la difícil sociedad medieval. En una tierra tranquila, los ratones viven apaciblemente en sus territorios mientras los Mouse Guards, comandados por la matriarca Gwendolyn, procuran ese estatus y protegen a comerciantes y viajeros de alimañas, lobos y comadrejas. Pero el otoño de 1152 será recordado como una época oscura: la del terror del ejército del Hacha Negra.','[{"name":"David Petersen","role":"Guion, Dibujo, Tinta"}]','[{"id":"yjplW","number":1,"title":"Mouse Guard #1","subtitle":"Otoño 1152","cover":"https://i1.whakoom.com/small/25/1d/be7eb6d8ad41477598d3f2e4e2dc3629.jpg","published":true,"releaseDate":null},{"id":"68plB","number":2,"title":"Mouse Guard #2","subtitle":"Invierno 1152","cover":"https://i1.whakoom.com/small/35/19/fabbadc7ee134ac69b5f643cd01233c9.jpg","published":true,"releaseDate":null},{"id":"jrtml","number":3,"title":"Mouse Guard #3","subtitle":"Hacha negra","cover":"https://i1.whakoom.com/small/25/3e/ac3dc08bbb05468fbe9334a7dcddef47.jpg","published":true,"releaseDate":null}]','2026-04-12T08:50:38.589Z',NULL,NULL);
