INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(143,'472727','edition','Lucifer. Integral','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1775984147022-lj54q9.jpg',3,'Entre 1999 y 2006, Mike Carey asumió el reto de dar forma al más esperado spin-off de la inolvidable Sandman. Contando con la colaboración de dibujantes tan reputados como Scott Hampton, Chris Weston, Peter Gross o Dean Ormston, supo sacar partido al carismático Lucifer, “el solipsista definitivo, que quemaría el mundo entero para encender su cigarrillo”. Una gran serie que desde 2016 se ha convertido también en todo un fenómeno televisivo, gracias a una producción protagonizada por Tom Ellis e impulsada por Warner Bros. Television, DC Entertainment y Jerry Bruckheimer Productions.','https://www.whakoom.com/ediciones/472727','2026-04-12 08:55:47','2026-04-12 08:55:50',1,'Cartoné 544-680 pp','Terminada','Tamaño 156x239 mm. Color','Entre 1999 y 2006, Mike Carey asumió el reto de dar forma al más esperado spin-off de la inolvidable Sandman. Contando con la colaboración de dibujantes tan reputados como Scott Hampton, Chris Weston, Peter Gross o Dean Ormston, supo sacar partido al carismático Lucifer, “el solipsista definitivo, que quemaría el mundo entero para encender su cigarrillo”. Una gran serie que desde 2016 se ha convertido también en todo un fenómeno televisivo, gracias a una producción protagonizada por Tom Ellis e impulsada por Warner Bros. Television, DC Entertainment y Jerry Bruckheimer Productions.','[{"name":"Mike Carey","role":"Guion"},{"name":"Ryan Kelly","role":"Dibujo"},{"name":"Dean Ormston","role":"Dibujo"},{"name":"Peter Gross","role":"Dibujo"},{"name":"Warren Pleece","role":"Dibujo"},{"name":"Ted Naifeh","role":""},{"name":"Zander Cannon","ro