INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(144,'397669','edition','Descender','Astiberri','https://inventario-api.josepec.workers.dev/covers/1775984171494-5gw2e1.jpg',6,'TIM-21, un joven androide, despierta de un largo sueño para descubrir que unos extraños robots alienígenas han atacado a la humanidad, al tiempo que se prohíbe la mera existencia de todos los autómatas. TIM-21 puede tener la clave de lo que quieren esos invasores y el porqué de su llegada, lo que le convierte en el robot más buscado. Para el Entertainment Weekly, “la nueva ciencia ficción está aquí con esta obra... Una historia espléndida y con carácter sobre un futuro en el que un robot solitario busca un hogar en una galaxia que lo odia y lo teme”.','https://www.whakoom.com/ediciones/397669','2026-04-12 08:56:12','2026-04-12 08:56:15',1,'Cartoné','Terminada','Tamaño 17 x 26 cm PVP 17€','TIM-21, un joven androide, despierta de un largo sueño para descubrir que unos extraños robots alienígenas han atacado a la humanidad, al tiempo que se prohíbe la mera existencia de todos los autómatas. TIM-21 puede tener la clave de lo que quieren esos invasores y el porqué de su llegada, lo que le convierte en el robot más buscado. Para el Entertainment Weekly, “la nueva ciencia ficción está aquí con esta obra... Una historia espléndida y con carácter sobre un futuro en el que un robot solitario busca un hogar en una galaxia que lo odia y lo teme”.','[{"name":"Jeff Lemire","role":""},{"name":"Dustin Nguyen","role":""}]','[{"id":"jHLvg","number":1,"title":"Descender #1","subtitle":"Estrellas de hojalata","cover":"https://i1.whakoom.com/small/32/05/eda9c174f8104aef8bab572467bab79f.jpg","published":true,"releaseDate":null},{"id":"taGaq","number":2,"title":"Descender #2","subtitle":"Luna máquina","cover":"https://i1.whakoom.com/small/05/2a/d68e2b7d04d64872bf5d742a3e427178.jpg","published":true,"releaseDate":null},{"id":"Wrai7","number":3,"title":"Descender #3","subtitle":"Singularidades","cover":"https://i1.whakoom.com/small/0a/1c/6bc5fd5f3b8741679210f1378be28d00.jpg","published":true,"releaseDate":null},{"id":"6W33X","number":4,"title":"Descender #4","subtitle":"Mecánica orbital","cover":"https://i1.whakoom.com/small/0b/06/1877c08072a54c52bbe644fc17d521fa.jpg","published":true,"releaseDate":null},{"id":"6B2ZN","number":5,"title":"Descender #5","subtitle":"La rebelión de los robots","cover":"https://i1.whakoom.com/small/09/2b/c903990fea4d4bb78fbaf2808d22bba9.jpg","published":true,"releaseDate":null},{"id":"xDWAq","number":6,"title":"Descender #6","subtitle":"Máquina de guerra","cover":"https://i1.whakoom.com/small/11/07/2a1db4eb310841fda29e37c41ea7f639.jpg","published":true,"releaseDate":null}]','2026-04-12T08:56:15.991Z',NULL,NULL);
INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(145,'527367','edition','Gideon Falls','Astiberri','https://inventario-api.josepec.workers.dev/covers/1775984208810-cbh2uf.jpg',6,'Existe una leyenda que habla sobre un edificio sobrenatural que ha aparecido y desaparecido a lo largo de la historia, sembrando la muerte y la locura a su paso. Esta construcción es el granero negro, eje sobre el que gira la historia de Gideon Falls, una pequeña población rural ubicada en un punto indefinido del mapa y del tiempo. Unidas por este misterio, las vidas de un joven ermitaño, obsesionado con encontrar pistas en la basura, y un cura católico en decadencia, que encuentra su sitio en este pequeño pueblo de fuertes convicciones religiosas, se ven entrelazadas. Sin embargo, ninguno de los dos está preparado para lo que hay dentro del granero negro. Jeff Lemire, autor de series como Descender, Black Hammer o Royal City demuestra por qué es uno de los creadores de cómic más exitosos.','https://www.whakoom.com/ediciones/527367','2026-04-12 08:56:49','2026-04-12 08:56:52',1,'Cartoné 160-136 pp','Terminada',NULL,'Existe una leyenda que habla sobre un edificio sobrenatural que ha aparecido y desaparecido a lo largo de la historia, sembrando la muerte y la locura a su paso. Esta construcción es el granero negro, eje sobre el que gira la historia de Gideon Falls, una pequeña población rural ubicada en un punto indefinido del mapa y del tiempo. Unidas por este misterio, las vidas de un joven ermitaño, obsesionado con encontrar pistas en la basura, y un cura católico en decadencia, que encuentra su sitio en este pequeño pueblo de fuertes convicciones religiosas, se ven entrelazadas. Sin embargo, ninguno de los dos está preparado para lo que hay dentro del granero negro. Jeff Lemire, autor de series como Descender, Black Hammer o Royal City demuestra por qué es uno de los creadores de cómic más exitosos.','[{"name":"Dave Stewart","role":"Color"},{"name":"Jeff Lemire","role":"Guion"},{"name":"Andrea Sorrentino","role":"Dibujo, Tinta"}]','[{"id":"hwaP7","number":1,"title":"Gideon Falls #1","subtitle":"El granero negro","cover":"https://i1.whakoom.com/small/1a/11/ff959775bbe74f3a98adf424dbfd24c3.jpg","published":true,"releaseDate":null},{"id":"2NlGk","number":2,"title":"Gideon Falls #2","subtitle":"Pecados originales","cover":"https://i1.whakoom.com/small/37/23/5d7144903b614a3782ba52cd51c7dce8.jpg","published":true,"releaseDate":null},{"id":"82lZD","number":3,"title":"Gideon Falls #3","subtitle":"Vía crucis","cover":"https://i1.whakoom.com/small/27/39/bed2e8abc9d148bf8dde94d0c6bf19c6.jpg","published":true,"releaseDate":null},{"id":"jpt9I","number":4,"title":"Gideon Falls #4","subtitle":"El pentáculo","cover":"https://i1.whakoom.com/small/0b/22/0852964eeb814413a4582332c5f8e3ca.jpg","published":true,"releaseDate":null},{"id":"6pLH4","number":5,"title":"Gideon Falls #5","subtitle":"Mundos perversos","cover":"https://i1.whakoom.com/small/13/16/fc39807110a0469da6bc2751cf62c79f.jpg","published":true,"releaseDate":null},{"id":"mgogq","number":6,"title":"Gideon Falls #6","subtitle":"El Fin","cover":"https://i1.whakoom.com/small/2a/25/7d8f803474394b27ac8861f5decf6c75.jpg","published":true,"releaseDate":null}]','2026-04-12T08:56:53.801Z',NULL,NULL);
INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(146,'409946','edition','I Hate Fairyland','Panini Comics España','https://inventario-api.josepec.workers.dev/covers/1775984241631-wpgvn4.jpg',6,'Skottie Young, el genio detrás de las versiones bebé de los héroes Marvel y de la serie de Mapache Cohete, vuelve del revés todos los tópicos sobre los cuentos de hadas. Imagina un cruce entre el escenario de Alicia en el País de las Maravillas y la violencia de Masacre. Te presentamos a Gert, una mujer de cuarenta años atrapada en el cuerpo de una niña de seis que no puede escapar de un mundo mágico al que llegó hace tres décadas. Únete a ella y a su gigantesca hacha para averiguar quién sobrevivirá a aquella que odia el Reino de las Hadas.','https://www.whakoom.com/ediciones/409946','2026-04-12 08:57:22','2026-04-12 08:57:28',1,'Cartoné 160-144 pp','En curso',NULL,'Skottie Young, el genio detrás de las versiones bebé de los héroes Marvel y de la serie de Mapache Cohete, vuelve del revés todos los tópicos sobre los cuentos de hadas. Imagina un cruce entre el escenario de Alicia en el País de las Maravillas y la violencia de Masacre. Te presentamos a Gert, una mujer de cuarenta años atrapada en el cuerpo de una niña de seis que no puede escapar de un mundo mágico al que llegó hace tres décadas. Únete a ella y a su gigantesca hacha para averiguar quién sobrevivirá a aquella que odia el Reino de las Hadas.','[{"name":"Skottie Young","role":"Guion, Dibujo, Tinta"},{"name":"Jean-Francois Beaulieu","role":"Color"},{"name":"Brett Bean","role":"Dibujo, Tinta"}]','[{"id":"6FzZ1","number":1,"title":"I Hate Fairyland #1","subtitle":"Loca para siempre","cover":"https://i1.whakoom.com/small/3c/3d/095c41e1c33c4a7ea0c2e93881127afd.jpg","published":true,"releaseDate":null},{"id":"BwDdk","number":2,"title":"I Hate Fairyland #2","subtitle":"De mal en peor","cover":"https://i1.whakoom.com/small/33/16/b0630fc3936a40ee8d323584bbb7d1be.jpg","published":true,"releaseDate":null},{"id":"yBgvD","number":3,"title":"I Hate Fairyland #3","subtitle":"Buena chica","cover":"https://i1.whakoom.com/small/1e/20/4636e0c09daf422885365f44e6001cfe.jpg","published":true,"releaseDate":null},{"id":"4Ra07","number":4,"title":"I Hate Fairyland #4","subtitle":"Infelices para siempre","cover":"https://i1.whakoom.com/small/2d/32/27e826e9adaf4a56b83cc181d3b237a8.jpg","published":true,"releaseDate":null},{"id":"8gm0x","number":5,"title":"I Hate Fairyland #5","subtitle":"El infierno de Gert","cover":"https://i1.whakoom.com/small/23/39/878b617071c24967bea80163713acefd.jpg","published":true,"releaseDate":null},{"id":"jdfFX","number":6,"title":"I Hate Fairyland #6","subtitle":"Solo puede quedar una","cover":"https://i1.whakoom.com/small/27/12/4edce2c16ffc49338e1717b96362ae99.jpg","published":true,"releaseDate":null}]','2026-04-12T08:57:29.283Z',NULL,NULL);
INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(147,'483768','edition','Sex Criminals','Astiberri','https://inventario-api.josepec.workers.dev/covers/1775984268800-sdm1yt.jpg',6,'Suzie y Jon tienen una habilidad particular: cuando tienen un orgasmo, el tiempo se suspende y el mundo a su alrededor se paraliza. De adolescentes, usaban ese don para escapar de una realidad gris y a veces cruel. Al conocerse en una fiesta, se enrollan y descubren que ambos tienen ese poder, y empiezan entonces a jugar juntos a entrar en esa dimensión orgásmica para divertirse y deshacerse de viejos fantasmas de su juventud... hasta que se les ocurre aprovechar ese periodo fuera del tiempo para robar un banco. Fraction y Zdarsky crean un thriller absorbente y adictivo, pero también para hablar de la sexualidad en nuestra sociedad, tanto desde un ángulo pícaro como más pedagógico, con personajes de psicología muy desarrollada, auténticos y veraces.','https://www.whakoom.com/ediciones/483768','2026-04-12 08:57:49','2026-04-12 08:57:54',1,'Cartoné 136 pp','Terminada','Tamaño 17 x 24 cm, color, PVP 16€','Suzie y Jon tienen una habilidad particular: cuando tienen un orgasmo, el tiempo se suspende y el mundo a su alrededor se paraliza. De adolescentes, usaban ese don para escapar de una realidad gris y a veces cruel. Al conocerse en una fiesta, se enrollan y descubren que ambos tienen ese poder, y empiezan entonces a jugar juntos a entrar en esa dimensión orgásmica para divertirse y deshacerse de viejos fantasmas de su juventud... hasta que se les ocurre aprovechar ese periodo fuera del tiempo para robar un banco. Fraction y Zdarsky crean un thriller absorbente y adictivo, pero también para hablar de la sexualidad en nuestra sociedad, tanto desde un ángulo pícaro como más pedagógico, con personajes de psicología muy desarrollada, auténticos y veraces.','[{"name":"Matt Fraction","role":"Guion"},{"name":"Chip Zdarsky","role":"Dibujo"}]','[{"id":"Whovq","number":1,"title":"Sex Criminals #1","subtitle":"Un truco sucio","cover":"https://i1.whakoom.com/small/33/05/79a8bf79146147859d81a1b81f4ce397.jpg","published":true,"releaseDate":null},{"id":"jBVoo","number":2,"title":"Sex Criminals #2","subtitle":"Dos mundos, una policía","cover":"https://i1.whakoom.com/small/3e/26/e8d7bbf86d0d4757a065376b0e182c6c.jpg","published":true,"releaseDate":null},{"id":"jB2ZT","number":3,"title":"Sex Criminals #3","subtitle":"Tres son multitud","cover":"https://i1.whakoom.com/small/35/3c/205a59e239e940a99addb6488308bad6.jpg","published":true,"releaseDate":null},{"id":"6xGGA","number":4,"title":"Sex Criminals #4","subtitle":"Cuatrorgía","cover":"https://i1.whakoom.com/small/05/3a/e1018ad4cae54d07a2a1baf173cab1d9.jpg","published":true,"releaseDate":null},{"id":"y4rip","number":5,"title":"Sex Criminals #5","subtitle":"Con el cinco te la hinco","cover":"https://i1.whakoom.com/small/2e/39/30917b79752f4f86bb8d83f8ffdc7eac.jpg","published":true,"releaseDate":null},{"id":"mLiBq","number":6,"title":"Sex Criminals #6","subtitle":"Seis criminales","cover":"https://i1.whakoom.com/small/14/36/fca66f68ed31464daab8a846422e325e.jpg","published":true,"releaseDate":null}]','2026-04-12T08:57:55.719Z',NULL,NULL);
INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(148,'4806','edition','Monster','Planeta Cómic','https://inventario-api.josepec.workers.dev/covers/1775984312493-xv41ji.jpg',9,'La serie sigue los pasos del neurocirujano Kenzo Tenma, que desobedece las órdenes del director del hospital, quien le había ordenado operar a un político influyente, y en su lugar opera a un niño llamado Johan que había llegado antes que el político de una herida de bala en la cabeza. La historia progresa rápidamente y muestra a aquel niño, ya adulto, como un peligroso psicópata y la búsqueda del Dr. Tenma a través de diferentes localizaciones (desde Düsseldorf, pasando por otras ciudades alemanas como Berlín, Frankfurt am Main, Múnich o Wiesbaden, e incluso ciudades checas como Praga), para encontrar a Johan y detenerlo.','https://www.whakoom.com/ediciones/4806','2026-04-12 08:58:33','2026-04-12 08:58:37',1,'Rústica con sobrecubierta 408-480 pp','Terminada','Edición Kanzenban con sobrecubiertas, B/N con páginas a color','La serie sigue los pasos del neurocirujano Kenzo Tenma, que desobedece las órdenes del director del hospital, quien le había ordenado operar a un político influyente, y en su lugar opera a un niño llamado Johan que había llegado antes que el político de una herida de bala en la cabeza. La historia progresa rápidamente y muestra a aquel niño, ya adulto, como un peligroso psicópata y la búsqueda del Dr. Tenma a través de diferentes localizaciones (desde Düsseldorf, pasando por otras ciudades alemanas como Berlín, Frankfurt am Main, Múnich o Wiesbaden, e incluso ciudades checas como Praga), para encontrar a Johan y detenerlo.','[{"name":"Naoki Urasawa","role":""},{"name":"Takashi Nagasaki","role":""}]','[{"id":"yj4id","number":1,"title":"Monster #1","subti