INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(151,'636938','edition','¡Yawara!','Planeta Cómic','https://inventario-api.josepec.workers.dev/covers/1775984556274-ux5q90.jpg',9,'La historia trata sobre Yawara Inokuma, una joven promesa del judo que habiendo sido fuertemente educada en este deporte desde muy pequeña, lo único que desea es tener una vida normal como todas las demás chicas. Su abuelo la convencerá de que su vida está ligada al judo y que un genio no puede desaprovechar los dones que tiene.','https://www.whakoom.com/ediciones/636938','2026-04-12 09:02:36','2026-04-12 09:02:40',1,'Rústica con sobrecubierta','En curso','• Set de 3 postales de regalo en la primera edición del tomo #1','La historia trata sobre Yawara Inokuma, una joven promesa del judo que habiendo sido fuertemente educada en este deporte desde muy pequeña, lo único que desea es tener una vida normal como todas las demás chicas. Su abuelo la convencerá de que su vida está ligada al judo y que un genio no puede desaprovechar los dones que tiene.','[{"name":"Naoki Urasawa","role":"Guion, Dibujo, Tinta"}]','[{"id":"yXanB","number":1,"title":"¡Yawara! #1","subtitle":"","cover":"https://i1.whakoom.com/small/0e/0a/7c3afcc6776046e1a77c6b757ed10365.jpg","published":true,"releaseDate":null},{"id":"jgzaB","number":2,"title":"¡Yawara! #2","subtitle":"","cover":"https://i1.whakoom.com/small/1c/1e/0d244cedaa8a4708889c255323a116f8.jpg","published":true,"releaseDate":null},{"id":"ygZoG","number":3,"title":"¡Yawara! #3","subtitle":"","cover":"https://i1.whakoom.com/small/2d/1a/be8797e43b634e6e90dbe4b2e471f0d0.jpg","published":true,"releaseDate":null},{"id":"ydAzA","number":4,"title":"¡Yawara! #4","subtitle":"","cover":"https://i1.whakoom.com/small/3c/39/bad4b74707eb4f7a9fb4e8098b36fb