INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(152,'636991','edition','Mermaid Saga','Planeta Cómic','https://inventario-api.josepec.workers.dev/covers/1775984660413-ns1j7z.jpg',3,'Debido a que comió la carne de una sirena, Yuta se volvió inmortal. Durante siglos, ha estado cruzando Japón en busca de una de estas mujeres-pez que finalmente podrá permitirle envejecer. Pero estas hechizantes criaturas son tan bellas como peligrosas y es a través de la sangre y los sacrificios que él las encontrará...','https://www.whakoom.com/ediciones/636991','2026-04-12 09:04:20','2026-04-12 09:04:24',1,'Rústica con sobrecubierta 264 pp','Terminada','21x14.8 cm PVP 12,95 €','Debido a que comió la carne de una sirena, Yuta se volvió inmortal. Durante siglos, ha estado cruzando Japón en busca de una de estas mujeres-pez que finalmente podrá permitirle envejecer. Pero estas hechizantes criaturas son tan bellas como peligrosas y es a través de la sangre y los sacrificios que él las encontrará...','[{"name":"Rumiko Takahashi","role":"Guion, Dibujo, Tinta"}]','[{"id":"jXaGr","number":1,"title":"Mermaid Saga #1","subtitle":"El bosque de la sirena","cover":"https://i1.whakoom.com/small/0d/0e/45c12ba9c85f463db97cbadf51d9fba6.jpg","published":true,"releaseDate":null},{"id":"X9pZq","number":2,"title":"Mermaid Saga #2","subtitle":"La herida de la sirena","cover":"https://i1.whakoom.com/small/2c/0e/7b17aec375414ef597835f4d47d8d4bf.jpg","published":true,"releaseDate":null},{"id":"XGr4k","number":3,"title":"Mermaid Saga #3","subtitle":"Ojos de demonio","cover":"https://i1.whakoom.com/small/28/25/0e47e5cc669649ba9c1f3b5bf3bd3e88.jpg","published":true,"releaseDate":null}]','2026-04-12T09:04:25.480Z',NULL,NULL);
INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(153,'597726','edition','F. Compo - Complete Edition','Arechi Manga','https://inventario-api.josepec.workers.dev/covers/1775984718326-ydg61l.jpg',11,'Masahiko Yanagiba queda huérfano poco antes de empezar la universidad, por lo que su tío y su tía lo acogen en su hogar, lo que Masahiko acepta, pues en ello ve la posibilidad de disfrutar por fin de una vida familiar. Lo que no sabe es que los Wakanae esconden un secreto algo particular que pondrá su mundo patas arriba.','https://www.whakoom.com/ediciones/597726','2026-04-12 09:05:19','2026-04-12 09:05:58',1,'Rústica','Terminada','Tamaño: 145×210 mm / PVP: 12.50 €','Masahiko Yanagiba queda huérfano poco antes de empezar la universidad, por lo que su tío y su tía lo acogen en su hogar, lo que Masahiko acepta, pues en ello ve la posibilidad de disfrutar por fin de una vida familiar. Lo que no sabe es que los Wakanae esconden un secreto algo particular que pondrá su mundo patas arriba.','[{"name":"Hojo Tsukasa","role":"Guion, Dibujo, Tinta"}]','[{"id":"pXDAk","number":1,"title":"F. Compo - Complete Edition #1","subtitle":"Family Compo","cover":"https://i1.whakoom.com/small/3c/0d/b1b75967dbd64c73905f398c9a8848c1.jpg","published":true,"releaseDate":null},{"id":"pXDa7","number":2,"title":"F. Compo - Complete Edition #2","subtitle":"","cover":"https://i1.whakoom.com/small/0e/15/c262621f5e134b129afde30d315c7be9.jpg","published":true,"releaseDate":null},{"id":"8mhA2","number":3,"title":"F. Compo - Complete Edition #3","subtitle":"","cover":"https://i1.whakoom.com/small/3d/10/5a72fee30e03441cb285a0acaf9ef40f.jpg","published":true,"releaseDate":null},{"id":"mp4f7","number":4,"title":"F. Compo - Complete Edition #4","subtitle":"","cover":"https://i1.whakoom.com