INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(157,'658703','edition','Naruto Jump Remix','Planeta Cómic','https://inventario-api.josepec.workers.dev/covers/1775985237777-cwb6l5.jpg',12,'La primera gran obra de Masashi Kishimoto nos cuenta la historia de un ninja llamado Naruto que sueña con convertirse en Hokage (el más alto rango de los ninjas de su villa). Para ello tendrá que colaborar con compañeros de lo más diversos y enfrentarse a peligrosos ninjas como el mítico Zabuza, el espeluznante Orochimaru o la peligrosa organización criminal Akatsuki, aprendiendo nuevas técnicas y siguiendo su propio camino ninja: el de no rendirse nunca.','https://www.whakoom.com/ediciones/658703','2026-04-12 09:13:58','2026-04-12 09:14:02',1,'Rústica','En curso','Edición 3 tomos en 1.','La primera gran obra de Masashi Kishimoto nos cuenta la historia de un ninja llamado Naruto que sueña con convertirse en Hokage (el más alto rango de los ninjas de su villa). Para ello tendrá que colaborar con compañeros de lo más diversos y enfrentarse a peligrosos ninjas como el mítico Zabuza, el espeluznante Orochimaru o la peligrosa organización criminal Akatsuki, aprendiendo nuevas técnicas y siguiendo su propio camino ninja: el de no rendirse nunca.','[{"name":"Masashi Kishimoto","role":"Guion, Dibujo, Tinta"}]','[{"id":"gI4a6","number":1,"title":"Naruto Jump Remix #1","subtitle":"¡Se forma el grupo 7 de Kakashi!","cover":"https://i1.whakoom.com/small/05/1b/0d6f258942be41b48006fe61fe065606.jpg","published":true,"releaseDate":null},{"id":"jg30M","number":2,"title":"Naruto Jump Remix #2","subtitle":"Exámenes de chûnin (1)","cover":"https://i1.whakoom.com/small/1a/2b/14274bbade844944abfee0c12313ab05.jpg","published":true,"releaseDate":null},{"id":"8dMF4","number":3,"title