INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(163,'649011','edition','Los viajes de Nicola por el Mundo Demoníaco','Milky Way Ediciones','https://inventario-api.josepec.workers.dev/covers/1775989936391-ghver0.jpg',4,'Nicola es una niña humana, la única que hay en el mundo de los demonios. Viaja en compañía de Simon, su amigo demonio, que la protege y oculta su origen para que las fuerzas del orden no la atrapen. ¡A saber qué harían con ella! Pero Nicola no es una humana normal: también es una brujita. Bueno, más o menos, porque aún no sabe controlar sus poderes. Juntos, Nicola y Simon recorren el mundo demoníaco viviendo mil y una peripecias mientras ella aprende a dominar la magia.','https://www.whakoom.com/ediciones/649011','2026-04-12 10:32:17','2026-04-12 10:32:20',1,'Rústica','Terminada',NULL,'Nicola es una niña humana, la única que hay en el mundo de los demonios. Viaja en compañía de Simon, su amigo demonio, que la protege y oculta su origen para que las fuerzas del orden no la atrapen. ¡A saber qué harían con ella! Pero Nicola no es una humana normal: también es una brujita. Bueno, más o menos, porque aún no sabe controlar sus poderes. Juntos, Nicola y Simon recorren el mundo demoníaco viviendo mil y una peripecias mientras ella aprende a dominar la magia.','[{"name":"Asaya Miyanaga","role":""}]','[{"id":"1PH47","number":1,"title":"Los viajes de Nicola por el Mundo Demoníaco #1","subtitle":"","cover":"https://i1.whakoom.com/small/00/1d/2b0389d2dc9b4df1b44ff42663f2d771.jpg","published":true,"releaseDate":null},{"id":"y1PHp","number":2,"title":"Los viajes de Nicola por el Mundo Demoníaco #2","subtitle":"","cover":"https://i1.whakoom.com/small/04/3f/c704a2779f9c4584b15246685adb085a.jpg","published":true,"releaseDate":null},{"id":"1PHm7"