INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(167,'287385','edition','Maldad Eterna','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1775999559893-6a2lw1.jpg',7,'El Infiltrado, el líder de la Sociedad Secreta, ha manipulado a las tres Ligas de la Justicia para hacerse con la famosa Caja de Pandora. Lejos de tener un origen mágico o mitológico, el artefacto es en realidad el portal al mundo natal del villano, Tierra 3, un lugar donde reinaba el mal encarnado por el Sindicato del Crimen, un grupo formado por versiones retorcidas de los principales héroes de nuestro planeta. Por su parte, debido a sus desavenencias con Batman, Nightwing se marchó de Gotham City, adonde no debería volver...','https://www.whakoom.com/ediciones/287385','2026-04-12 13:12:40','2026-04-12 13:12:45',1,'Grapa','Terminada',NULL,'El Infiltrado, el líder de la Sociedad Secreta, ha manipulado a las tres Ligas de la Justicia para hacerse con la famosa Caja de Pandora. Lejos de tener un origen mágico o mitológico, el artefacto es en realidad el portal al mundo natal del villano, Tierra 3, un lugar donde reinaba el mal encarnado por el Sindicato del Crimen, un grupo formado por versiones retorcidas de los principales héroes de nuestro planeta. Por su parte, debido a sus desavenencias con Batman, Nightwing se marchó de Gotham City, adonde no debería volver...','[{"name":"Geoff Johns","role":""},{"name":"David Finch","role":""}]','[{"id":"apwb6","number":1,"title":"Maldad Eterna #1","subtitle":"","cover":"https://i1.whakoom.com/small/02/38/f7293263b8534bd394f1ebc9bf49ad08.jpg","published":true,"releaseDate":null},{"id":"japwG","number":2,"title":"Maldad Eterna #2","subtitle":"","cover":"https://i1.whakoom.com/small/2b/3f/3428f12c690648f188385708b4ce34dc.jpg",