INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(169,'407727','edition','All-Star Batman. Renacimiento','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1776002920008-fw99u9.jpg',15,'All-Star Batman nace con el objetivo de mostrar una visión diferente y renovada de algunos de los personajes más importantes del universo del Hombre Murciélago, con especial atención a la legendaria galería de villanos del protector de Gotham. Tras su triunfal etapa en la serie regular de Batman, Scott Snyder se alía con algunos de los más importantes artistas de la industria del cómic, ofreciendo grandes dosis de entretenimiento y diversión. Un soplo de aire fresco para un personaje que se ha convertido en un indiscutible referente dentro y fuera del mundo de las viñetas.','https://www.whakoom.com/ediciones/407727','2026-04-12 13:15:31','2026-04-12 14:08:43',1,'Grapa','Terminada','Color. Tamaño 26x17 cm. Periodicidad: mensual','All-Star Batman nace con el objetivo de mostrar una visión diferente y renovada de algunos de los personajes más importantes del universo del Hombre Murciélago, con especial atención a la legendaria galería de villanos del protector de Gotham. Tras su triunfal etapa en la serie regular de Batman, Scott Snyder se alía con algunos de los más importantes artistas de la industria del cómic, ofreciendo grandes dosis de entretenimiento y diversión. Un soplo de aire fresco para un personaje que se ha convertido en un indiscutible referente dentro y fuera del mundo de las viñetas.','[{"name":"Scott Snyder","role":"Guion"},{"name":"John Romita Jr.","role":"Dibujo"},{"name":"Danny Miki","role":"Tinta"},{"name":"Dean White","role":"Color"},{"name":"Rafael Albuquerque","role":"Guion, Dibujo, Tinta"},{"name":"Sebastian Fiumara","role":