INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(170,'472710','edition','Liga de la Justicia contra Escuadrón Suicida. Renacimiento','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1775999754569-0bxguv.jpg',3,'El primer gran evento de la era Renacimiento arranca con un día que Amanda Waller siempre supo que llegaría: ¡la Liga de la Justicia ha descubierto la existencia del Escuadrón Suicida! Los defensores de la verdad y la justicia no ven con buenos ojos al grupo de operaciones encubiertas del gobierno, formado por supervillanos controlados a través de un sistema de bombas implantadas en sus cabezas. ¡Pero la Fuerza Especial X no está dispuesta a rendirse fácilmente!','https://www.whakoom.com/ediciones/472710','2026-04-12 13:15:55','2026-04-12 13:15:59',1,'Grapa 64 pp','Terminada',NULL,'El primer gran evento de la era Renacimiento arranca con un día que Amanda Waller siempre supo que llegaría: ¡la Liga de la Justicia ha descubierto la existencia del Escuadrón Suicida! Los defensores de la verdad y la justicia no ven con buenos ojos al grupo de operaciones encubiertas del gobierno, formado por supervillanos controlados a través de un sistema de bombas implantadas en sus cabezas. ¡Pero la Fuerza Especial X no está dispuesta a rendirse fácilmente!','[{"name":"Joshua Williamson","role":"Guion"},{"name":"Alex Sinclair","role":"Color"},{"name":"Sandu Florea","role":"Tinta"},{"name":"Jeremiah Skipper","role":"Color"},{"name":"Jesús Merino","role":"Dibujo"},{"name":"Howard Porter","role":"Dibujo, Tinta"},{"name":"Tony S. Daniel","role":"Dibujo"},{"name":"Andy Owens","role":"Tinta"},{"name":"Oclair Albert","role":"Tinta"},{"name":"Matt Ryan","role":"Tinta"},{"name":"Fernando Pasarín","role":"Dibujo"}]','[{"id":"WrRr7","number":1,"tit