INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(173,'487271','edition','Batman / Flash: La chapa. Renacimiento','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1775999883137-4b6850.jpg',4,'Tras los sucesos de Flash núm. 24/10, el trascendental argumento iniciado en el especial Universo DC: Renacimiento sigue adelante en esta imprescindible serie limitada. Batman y Flash, los dos mejores detectives del mundo, se unen para explorar el misterio que hay detrás de un extraño objeto encontrado en la Batcueva. Un misterio tejido a través del tiempo y el espacio. Un poder que amenaza a los héroes más grandes de todos los tiempos. ¡El tiempo corre para todo el Universo DC!','https://www.whakoom.com/ediciones/487271','2026-04-12 13:18:04','2026-04-12 13:18:08',1,'Grapa 24 pp','Terminada',NULL,'Tras los sucesos de Flash núm. 24/10, el trascendental argumento iniciado en el especial Universo DC: Renacimiento sigue adelante en esta imprescindible serie limitada. Batman y Flash, los dos mejores detectives del mundo, se unen para explorar el misterio que hay detrás de un extraño objeto encontrado en la Batcueva. Un misterio tejido a través del tiempo y el espacio. Un poder que amenaza a los héroes más grandes de todos los tiempos. ¡El tiempo corre para todo el Universo DC!','[{"name":"Joshua Williamson","role":"Guion"},{"name":"Tom King","role":"Guion"},{"name":"Jason Fabok","role":"Dibujo"},{"name":"Howard Porter","role":"Dibujo"}]','[{"id":"Wnm3k","number":1,"title":"Batman / Flash: La chapa. Renacimiento #1","subtitle":"","cover":"https://i1.whakoom.com/small/3f/2b/53c5c5e46dc44b1db9d4f2711896a866.jpg","published":true,"releaseDate":null},{"id":"Wnmiq","number":2,"title":"Batman / Flash: La chapa. Renacimiento #2","subtitle":"","cover":