INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(175,'484909','edition','Green Lantern / El Planeta de los Simios','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1775999971244-z3bn7c.jpg',6,'¡BOOM! Studios y DC Comics reúnen en un mismo título a dos de los universos de ficción más importantes de todos los tiempos! Cuando el coronel George Taylor desaparece, Cornelius inicia una investigación que le llevará a descubrir un antiguo anillo de poder. La aparición del anillo llama la atención de los Guardianes del Universo y de sus Green Lantern Corps, liderados por Hal Jordan... ¡pero también del malvado Sinestro! Ahora, todos se encaminan hacia un sorprendente lugar: el Planeta de los Simios.','https://www.whakoom.com/ediciones/484909','2026-04-12 13:19:32','2026-04-12 13:19:36',1,'Grapa 24 pp','Terminada',NULL,'¡BOOM! Studios y DC Comics reúnen en un mismo título a dos de los universos de ficción más importantes de todos los tiempos! Cuando el coronel George Taylor desaparece, Cornelius inicia una investigación que le llevará a descubrir un antiguo anillo de poder. La aparición del anillo llama la atención de los Guardianes del Universo y de sus Green Lantern Corps, liderados por Hal Jordan... ¡pero también del malvado Sinestro! Ahora, todos se encaminan hacia un sorprendente lugar: el Planeta de los Simios.','[{"name":"Justin Jordan","role":"Guion"},{"name":"Robbie Thompson","role":"Guion"},{"name":"Barnaby Bagenda","role":"Dibujo"},{"name":"Alex Guimaraes","role":"Color"},{"name":"Dn Mora","role":"Dibujo"}]','[{"id":"8WmHz","number":1,"title":"Green Lantern / El Planeta de los Simios #1","subtitle":"","cover":"https://i1.whakoom.com/small/07/00/01607f9b5d1947879234bd7b4c37a084.jpg","published":true,"releaseDate":null},{"id":"