INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(176,'411410','edition','Liga de la Justicia / Mighty Morphin Power Rangers','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1776000011911-5ns5rl.jpg',6,'Llega a España uno de los crossovers más esperados, fruto de la colaboración entre DC Comics y BOOM! Studios: ¡el encuentro entre la Liga de la Justicia y los Power Rangers! ¡En formato grapa y con periodicidad mensual! Tom Taylor, el aclamado guionista de Injustice: Gods among us, se asocia con el dibujante Stephen Byrne (Green Arrow) para dar forma a esta serie limitada de seis entregas, que no dejará indiferente a ningún aficionado. La mejor forma de preparar los próximos estrenos de Power Rangers (Dean Israelite, 2017) y Liga de la Justicia (Zack Snyder, 2017), producciones que marcarán el debut en la gran pantalla de ambos grupos.','https://www.whakoom.com/ediciones/411410','2026-04-12 13:20:12','2026-04-12 13:20:15',1,'Grapa 24 pp','Terminada',NULL,'Llega a España uno de los crossovers más esperados, fruto de la colaboración entre DC Comics y BOOM! Studios: ¡el encuentro entre la Liga de la Justicia y los Power Rangers! ¡En formato grapa y con periodicidad mensual! Tom Taylor, el aclamado guionista de Injustice: Gods among us, se asocia con el dibujante Stephen Byrne (Green Arrow) para dar forma a esta serie limitada de seis entregas, que no dejará indiferente a ningún aficionado. La mejor forma de preparar los próximos estrenos de Power Rangers (Dean Israelite, 2017) y Liga de la Justicia (Zack Snyder, 2017), producciones que marcarán el debut en la gran pantalla de ambos grupos.','[{"name":"Tom Taylor","role":"Guion"},{"name":"Stephen Byrne","role":"Dibujo"},{"name":"Karl Kerschl","role":"Dibujo"},{"name":"Deron Bennett