INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(177,'502406','edition','Batman: Caballero Blanco','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1776000055367-7be3vw.jpg',8,'El escritor y dibujante Sean Murphy, estrella del noveno arte, responsable de obras rompedoras como Punk Rock Jesus, presenta Batman: Caballero Blanco, una serie limitada de ocho entregas, ambientada en una retorcida versión de la ciudad de Gotham. Es el trágico relato de un héroe y un villano: Batman y el Joker. Pero, ¿cuál de ellos es el héroe, y cuál es el villano? ¡Descubre la respuesta en formato grapa mensual!.','https://www.whakoom.com/ediciones/502406','2026-04-12 13:20:56','2026-04-12 13:20:59',1,'Grapa 32 pp','Terminada','Colección correspondientes a Batman ''White Knight'' #1 al 8 (Diciembre de 2017 a Julio de 2018), de la edición USA. A color. 24x17cm.','El escritor y dibujante Sean Murphy, estrella del noveno arte, responsable de obras rompedoras como Punk Rock Jesus, presenta Batman: Caballero Blanco, una serie limitada de ocho entregas, ambientada en una retorcida versión de la ciudad de Gotham. Es el trágico relato de un héroe y un villano: Batman y el Joker. Pero, ¿cuál de ellos es el héroe, y cuál es el villano? ¡Descubre la respuesta en formato grapa mensual!.','[{"name":"Sean Murphy","role":"Guion, Dibujo, Tinta"},{"name":"Matt Hollingsworth","role":"Color"}]','[{"id":"jB2tZ","number":1,"title":"Batman: Caballero Blanco #1","subtitle":"","cover":"https://i1.whakoom.com/small/29/07/8fdd42afb6b04779a68658279d0325a3.jpg","published":true,"releaseDate":null},{"id":"Bvni7","number":2,"title":"Batman: Caballero Blanco #2","subtitle":"","cover":"https://i1.whakoom.com/small/3e/1b/828b2b201aed4f31b04798e7b9805cdc.jpg","published":true,"relea