INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(178,'529893','edition','El Batman que ríe','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1776000090881-7p66p8.jpg',8,'¡Nueva serie limitada! ¡Formato grapa mensual! Durante los eventos de Noches oscuras: Metal, Bruce Wayne y todos los héroes del Universo DC se vieron cara a cara con las malvadas versiones de Batman generadas por el Multiverso Oscuro. Aunque los héroes vencieron, la pesadilla no ha terminado. Batman acaba de descubrir que El Batman que ríe, la versión más peligrosa del Caballero Oscuro, logró sobrevivir y trata de finalizar sus siniestros planes. Parece que la única manera de detener a este loco es acabando con su vida. ¿Violará Batman su más sagrada norma? ¿Se cumplirá su destino y se convertirá realmente en el Batman que ríe? El estelar equipo creativo formado por Scott Snyder y Jock, responsables de Batman: Espejo oscuro, responden a estas y otras preguntas en uno de los proyectos más esperados de 2019.','https://www.whakoom.com/ediciones/529893','2026-04-12 13:21:31','2026-04-12 13:21:35',1,'Grapa 32 pp','Terminada',NULL,'¡Nueva serie limitada! ¡Formato grapa mensual! Durante los eventos de Noches oscuras: Metal, Bruce Wayne y todos los héroes del Universo DC se vieron cara a cara con las malvadas versiones de Batman generadas por el Multiverso Oscuro. Aunque los héroes vencieron, la pesadilla no ha terminado. Batman acaba de descubrir que El Batman que ríe, la versión más peligrosa del Caballero Oscuro, logró sobrevivir y trata de finalizar sus siniestros planes. Parece que la única manera de detener a este loco es acabando con su vida. ¿Violará Batman su más sagrada norma? ¿Se cumplirá su destino y se convertirá realmente en el Batman que ríe? El estelar equipo creativo formado por Scott Snyder y Jock, responsables de Batman: Espejo oscuro, responden a estas y otras preguntas en uno de los proyectos más esperados de 2019.','[{"name":"Jock","role":"Dibujo"},{"name":"Scott Snyder","role":"Guion"},{"name":"David Baron","role":"Color"},{"name":"Joshua Williamson","role":"Guion"},{"name":"James Tynion IV","role":"Guion"},{"name":"Alejandro Sánchez","role":"Color"},{"name":"Eduardo Risso","role":"Dibujo, Tinta"},{"name":"David Marquez","role":"Dibujo, Tinta"},{"name":"Dave Stewart","role":"Color"}]','[{"id":"hB9H6","number":1,"title":"El Batman que ríe #1","subtitle":"","cover":"https://i1.whakoom.com/small/0a/33/5ba3976fa6ff43cd9eebd37d5902b7a7.jpg","published":true,"releaseDate":null},{"id":"hmDL6","number":2,"title":"El Batman que ríe #2","subtitle":"","cover":"https://i1.whakoom.com/small/20/0a/881282aa25254d8995397facbcdf3ecc.jpg","published":true,"releaseDate":null},{"id":"yhlxI","number":3,"title":"El Batman que ríe #3","subtitle":"","cover":"https://i1.whakoom.com/small/3b/0f/b1689329a7124a5cbc4a5121e92ef567.jpg","published":true,"releaseDate":null},{"id":"8hilo","number":4,"title":"El Batman que ríe #4","subtitle":"","cover":"https://i1.whakoom.com/small/2d/23/f002889b582a406e972c655f4481f8e9.jpg","published":true,"releaseDate":null},{"id":"k2VIw","number":5,"title":"El Batman que ríe #5","subtitle":"","cover":"https://i1.whakoom.com/small/3f/2b/90cf666d37f145f58c88282f5be73516.jpg","published":true,"releaseDate":null},{"id":"j2BwX","number":6,"title":"El Batman que ríe #6","subtitle":"","cover":"https://i1.whakoom.com/small/0d/3b/ef2b139c43304d739ed3b32f86bbafe2.jpg","published":true,"releaseDate":null},{"id":"24Itq","number":7,"title":"El Batman que ríe #7","subtitle":"","cover":"https://i1.whakoom.com/small/1c/20/1f6abe43b3004e328e27481dad031914.jpg","published":true,"releaseDate":null},{"id":"62fH4","number":8,"title":"El Batman que ríe #8","subtitle":"","cover":"https://i1.whakoom.com/small/36/26/95054d9526