INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(179,'526146','edition','Héroes en Crisis','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1776000135580-bf9nl3.jpg',9,'En la tradición de Crisis en Tierras Infinitas, Crisis Infinita, Crisis de Identidad o Crisis Final, un nuevo evento reúne a todos los iconos del Universo DC. Todo empieza con una pregunta impactante, con un hecho en el que nadie ha reparado hasta la fecha o que nadie se atrevía verbalizar: ¿cómo afronta un superhéroe el trastorno de estrés postraumático, provocado por tantas situaciones al borde de la muerte? Tom King, antiguo operativo de la CIA, ganador de varios premios Eisner, responsable de Mr. Milagro, El Sheriff de Babilonia, Omega Men y Batman, trata de responder a esta inesperada cuestión, con la colaboración estelar del dibujante Clay Mann (Batman).','https://www.whakoom.com/ediciones/526146','2026-04-12 13:22:16','2026-04-12 13:22:20',1,'Grapa 24-32 pp','Terminada',NULL,'En la tradición de Crisis en Tierras Infinitas, Crisis Infinita, Crisis de Identidad o Crisis Final, un nuevo evento reúne a todos los iconos del Universo DC. Todo empieza con una pregunta impactante, con un hecho en el que nadie ha reparado hasta la fecha o que nadie se atrevía verbalizar: ¿cómo afronta un superhéroe el trastorno de estrés postraumático, provocado por tantas situaciones al borde de la muerte? Tom King, antiguo operativo de la CIA, ganador de varios premios Eisner, responsable de Mr. Milagro, El Sheriff de Babilonia, Omega Men y Batman, trata de responder a esta inesperada cuestión, con la colaboración estelar del dibujante Clay Mann (Batman).','[{"name":"Tom King","role":"Guion"},{"name":"Clay Mann","role":"Dibujo, Tinta"},{"name":"Tomeu Morey","role":"Color"},{"na