INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(183,'3790','edition','La Noche Más Oscura','Planeta Cómic','https://inventario-api.josepec.workers.dev/covers/1776000354021-mx9lyk.jpg',8,'Flash, uno de los mejores amigos de Green Lantern, ha vuelto al mundo de los vivos para averiguar que muchos de sus antiguos compañeros han fallecido... pero solo es cuestión de tiempo que regresen. Y es que Mano Negra, uno de los peores enemigos de Hal Jordan, se ha convertido en el adalid de una fuerza siniestra y desconocida que, por medio de unos anillos negros, está levantando a los muertos de sus tumbas para convertirlos en una de las amenazas más peligrosas que el universo haya conocido: ¡los Black Lanterns!','https://www.whakoom.com/ediciones/3790','2026-04-12 13:25:54','2026-04-12 13:25:58',1,'Grapa 64-32-48 pp','Terminada','El primer número (64) y el octavo (48) tuvieron una paginación especial','Flash, uno de los mejores amigos de Green Lantern, ha vuelto al mundo de los vivos para averiguar que muchos de sus antiguos compañeros han fallecido... pero solo es cuestión de tiempo que regresen. Y es que Mano Negra, uno de los peores enemigos de Hal Jordan, se ha convertido en el adalid de una fuerza siniestra y desconocida que, por medio de unos anillos negros, está levantando a los muertos de sus tumbas para convertirlos en una de las amenazas más peligrosas que el universo haya conocido: ¡los Black Lanterns!','[{"name":"Alex Sinclair","role":""},{"name":"Ivan Reis","role":""},{"name":"Oclair Albert","role":""},{"name":"Geoff Johns","role":""},{"name":"Joe Prado","role":""},{"name":"Julio Ferreira","role":""},{"name":"Rob Hunter","role":""}]','[{"id":"8xF4k","number":1,"title":"La Noche Más Oscura #1","subtitle":"","cover":"https://i1.whakoom.com/small