INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(206,'490518','edition','Mr. Milagro','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1776003081205-e8agvx.jpg',12,'Scott Free es el mejor escapista que jamás haya existido. Tan habilidoso, que escapó del espantoso orfanato de la Abuelita Bondad y de los peligros del planeta Apokolips para viajar a través del universo y establecerse en la Tierra, iniciando una nueva vida con su esposa, la mujer conocida como Big Barda. Empleando el nombre de Mister Milagro, Scott ha triunfado mostrando sus técnicas acrobáticas, ¡incluso forjó amistad con los componentes de la Liga de la Justicia! Se podría decir que Scott Free lo tiene todo... pero no es suficiente. Mister Milagro domina todos los trucos, excepto uno: evitar a la muerte. ¿Será capaz de lograrlo? Nuestro héroe tendrá que suicidarse si quiere descubrirlo...','https://www.whakoom.com/ediciones/490518','2026-04-12 14:11:21','2026-04-12 14:11:27',1,'Grapa 24 pp','Terminada',NULL,'Scott Free es el mejor escapista que jamás haya existido. Tan habilidoso, que escapó del espantoso orfanato de la Abuelita Bondad y de los peligros del planeta Apokolips para viajar a través del universo y establecerse en la Tierra, iniciando una nueva vida con su esposa, la mujer conocida como Big Barda. Empleando el nombre de Mister Milagro, Scott ha triunfado mostrando sus técnicas acrobáticas, ¡incluso forjó amistad con los componentes de la Liga de la Justicia! Se podría decir que Scott Free lo tiene todo... pero no es suficiente. Mister Milagro domina todos los trucos, excepto uno: evitar a la muerte. ¿Será capaz de lograrlo? Nuestro héroe tendrá que suicidarse si quiere descubrirlo...','[{"name":"Tom King","role":"Guion"},{"name":"Mitch Gerads","role"