INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(213,'7525','edition','Antes de Watchmen: Búho Nocturno','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1776004080637-z1a77b.jpg',4,'En los años sesenta, Dan Dreiberg era un adolescente con muchos problemas que idolatraba a su mayor héroe: el Búho Nocturno original, Hollis Mason. Tanto que llegaría a heredar el título del veterano justiciero e incluso conocería a otros enmascarados, como Rorschach y Lady Crepúsculo, en un pasado que Moore y Gibbons apenas insinuaron y que aquí se revela decisivo para la forja de la personalidad del protagonista.','https://www.whakoom.com/ediciones/7525','2026-04-12 14:28:01','2026-04-12 14:28:04',1,'Grapa 36-32 pp','Terminada',NULL,'En los años sesenta, Dan Dreiberg era un adolescente con muchos problemas que idolatraba a su mayor héroe: el Búho Nocturno original, Hollis Mason. Tanto que llegaría a heredar el título del veterano justiciero e incluso conocería a otros enmascarados, como Rorschach y Lady Crepúsculo, en un pasado que Moore y Gibbons apenas insinuaron y que aquí se revela decisivo para la forja de la personalidad del protagonista.','[{"name":"Joe Michael Straczynski","role":"Guion"},{"name":"Andy Kubert","role":"Dibujo"},{"name":"Brad Anderson","role":"Color"},{"name":"John Higgins","role":"Guion, Dibujo, Tinta, Color"},{"name":"Joe Kubert","role":"Tinta"},{"name":"Bill Sienkiewicz","role":"Tinta"},{"name":"Len Wein","role":"Guion"}]','[{"id":"ol0q7","number":1,"title":"Antes de Watchmen: Búho Nocturno #1","subtitle":"La Comida Gratis No Existe","cover":"https://i1.whakoom.com/small/0c/2a/bad5160d2f414d7ba3b0c5af4e57c276.jpg","published":true,"releaseDate":null},{"id":"o0t76","number":2,"title":"Antes de Watchmen: Búho Nocturno #2"