INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(215,'7536','edition','Antes de Watchmen: Dr. Manhattan','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1776004141994-tamnkr.jpg',4,'Incluso para alguien capaz de estar en todas partes a la vez, ¿son infinitas las posibilidades? El 20 de agosto de 1959, a las 13.15 horas, algo cambió el universo de Watchmen para siempre: Jonathan Osterman quedó atrapado en una cámara sellada y expuesto a la radiación de los campos intrínsecos, lo que le transformaría en el metahumano conocido como el Dr. Manhattan. A partir de entonces, su dominio sobre el espacio y el tiempo sería prácticamente absoluto, pero... ¿qué ocurre cuando regresa a aquel instante y descubre lo que habría pasado si no se hubiera hallado en esa cámara? J.M. Straczynski (Superman: Tierra uno) y Adam Hughes (Fábulas) relatan eso y mucho más.','https://www.whakoom.com/ediciones/7536','2026-04-12 14:29:02','2026-04-12 14:29:05',1,'Grapa 32 pp','Terminada',NULL,'Incluso para alguien capaz de estar en todas partes a la vez, ¿son infinitas las posibilidades? El 20 de agosto de 1959, a las 13.15 horas, algo cambió el universo de Watchmen para siempre: Jonathan Osterman quedó atrapado en una cámara sellada y expuesto a la radiación de los campos intrínsecos, lo que le transformaría en el metahumano conocido como el Dr. Manhattan. A partir de entonces, su dominio sobre el espacio y el tiempo sería prácticamente absoluto, pero... ¿qué ocurre cuando regresa a aquel instante y descubre lo que habría pasado si no se hubiera hallado en esa cámara? J.M. Straczynski (Superman: Tierra uno) y Adam Hughes (Fábulas) relatan eso y mucho más.','[{"name":"Joe Michael Straczynski","role":"Guion"},{"name":"Adam Hughes","role":"Dibujo, Tinta"},{"