INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(217,'198780','edition','Antes de Watchmen: Moloch','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1776004220850-qubgtp.jpg',2,'Una colección publicada por ECC Ediciones','https://www.whakoom.com/ediciones/198780','2026-04-12 14:30:21','2026-04-12 14:30:24',1,'Grapa 32 pp','Terminada',NULL,NULL,'[{"name":"Joe Michael Straczynski","role":"Guion"},{"name":"Eduardo Risso","role":"Dibujo"}]','[{"id":"6V1M2","number":1,"title":"Antes de Watchmen: Moloch #1","subtitle":"","cover":"https://i1.whakoom.com/small/28/24/ffd581aac417487ea26a4c3769e3998b.jpg","published":true,"releaseDate":null},{"id":"V1M4k","number":2,"title":"Antes de Watchmen: Moloch #2","subtitle":"","cover":"https://i1.whakoom.com/small/07/13/ae1a81b7cc7b42848fbcb60c5c7ea6a9.jpg","published":true,"releaseDate":null}]','2026-04-12T14:30:25.419Z',NULL,NULL);
INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(218,'320349','edition','Sandman Obertura','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1776004255548-igyq0u.jpg',6,'El último episodio de Sandman escrito por Neil Gaiman se publicó en marzo de 1996. Después, durante diecisiete años, el personaje durmió en el limbo de los seres imaginarios hasta que el guionista de Porchester decidió despertarlo para ofrecer una única función antes de devolverlo a su lecho mágico y silencioso. El resultado es Sandman: Obertura, la serie limitada que desvela los sucesos previos a la captura de Morfeo por parte del ocultista Roderick Burguess (tal como estableció el episodio inaugural de la serie). Esta nueva obra —portentosamente dibujada por J. H. Williams III— nos devuelve al Rey del Sueño en todo su pálido y altivo esplendor. También a los miembros más populares de su peculiar familia, como Muerte o Destino. Y sobre todo, nos restituye uno de los universos narrativos más imaginativos, poderosos y atemporales de las últimas décadas. Evidentemente, el sueño terminó hace diecisiete años. Pero Sandman: Obertura contiene todos los ingredientes que hicieron del original un clásico contemporáneo.','https://www.whakoom.com/ediciones/320349','2026-04-12 14:30:56','2026-04-12 14:30:59',1,'Grapa 28 pp','Terminada',NULL,'El último episodio de Sandman escrito por Neil Gaiman se publicó en marzo de 1996. Después, durante diecisiete años, el personaje durmió en el limbo de los seres imaginarios hasta que el guionista de Porchester decidió despertarlo para ofrecer una única función antes de devolverlo a su lecho mágico y silencioso. El resultado es Sandman: Obertura, la serie limitada que desvela los sucesos previos a la captura de Morfeo por parte del ocultista Roderick Burguess (tal como estableció el episodio inaugural de la serie). Esta nueva obra —portentosamente dibujada por J. H. Williams III— nos devuelve al Rey del Sueño en todo su pálido y altivo esplendor. También a los miembros más populares de su peculiar familia, como Muerte o Destino. Y sobre todo, nos restituye uno de los universos narrativos más imaginativos, poderosos y atemporales de las últimas décadas. Evidentemente, el sueño terminó hace diecisiete años. Pero Sandman: Obertura contiene todos los ingredientes que hicieron del original un clásico contemporáneo.','[{"name":"Neil Gaiman","role":"Guion"},{"name":"J. H. Williams III","role":"Dibujo"}]','[{"id":"8rl12","number":1,"title":"Sandman Obertura #1","subtitle":"","cover":"https://i1.whakoom.com/small/0d/11/5d414df4e0fa4694a05b1a86745721af.jpg","published":true,"releaseDate":null},{"id":"yMmxX","number":2,"title":"Sandman Obertura #2","subtitle":"","cover":"https://i1.whakoom.com/small/02/35/13270e07851d4430aaefaae3ea500127.jpg","published":true,"releaseDate":null},{"id":"yzVHg","number":3,"title":"Sandman Obertura #3","subtitle":"","cover":"https://i1.whakoom.com/small/18/2c/948b211154cc4e58952694d6e3f448bf.jpg","published":true,"releaseDate":null},{"id":"yzRht","number":4,"title":"Sandman Obertura #4","subtitle":"","cover":"https://i1.whakoom.com/small/19/30/c0ba9f323f2c470997c7ce82687e6c53.jpg","published":true,"releaseDate":null},{"id":"yO0Wb","number":5,"title":"Sandman Obertura #5","subtitle":"","cover":"https://i1.whakoom.com/small/02/30/5d06588d14f74a42ad2754f2aa368d5a.jpg","published":true,"releaseDate":null},{"id":"jHmi5","number":6,"title":"Sandman Obertura #6","subtitle":"","cover":"https://i1.whakoom.com/small/24/31/34ed8278b1ff4a739a323807a4dcefeb.jpg","published":true,"releaseDate":null}]','2026-04-12T14:31:00.690Z',NULL,NULL);
INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(219,'608484','edition','Las Tortugas Ninja: El último Ronin','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1776004294220-gqj8xq.jpg',5,'Nueva York, el futuro. Una ciudad muy diferente a la que conocemos hoy. En sus calles, la última Tortuga Ninja emprende una cruzada: busca justicia para su familia y para sus amigos caídos. Bienvenidos a una de las historias más memorables de las Tortugas Ninja, basada en una idea original de los creadores de los personajes, Kevin Eastman y Peter Laird, desarrollada para los lectores modernos por el guionista del exitoso reboot, Tom Waltz, en colaboración con los dibujantes Esau e Isaac Escorza, Ben Bishop y el propio Eastman. ¿Quién es el último Ronin?','https://www.whakoom.com/ediciones/608484','2026-04-12 14:31:35','2026-04-12 14:31:38',1,'Grapa','Terminada',NULL,'Nueva York, el futuro. Una ciudad muy diferente a la que conocemos hoy. En sus calles, la última Tortuga Ninja emprende una cruzada: busca justicia para su familia y para sus amigos caídos. Bienvenidos a una de las historias más memorables de las Tortugas Ninja, basada en una idea original de los creadores de los personajes, Kevin Eastman y Peter Laird, desarrollada para los lectores modernos por el guionista del exitoso reboot, Tom Waltz, en colaboración con los dibujantes Esau e Isaac Escorza, Ben Bishop y el propio Eastman. ¿Quién es el último Ronin?','[{"name":"Kevin Eastman","role":"Guion, Dibujo"},{"name":"Peter Laird","role":"Guion"},{"name":"Tom Waltz","role":"Guion, Dibujo"},{"name":"Esau Escorza","role":"Dibujo, Tinta"},{"name":"Isaac Escorza","role":"Dibujo, Tinta"},{"name":"Luis Antonio Delgado","role":"Color"},{"name":"Samuel Plata","role":"Color"},{"name":"Ben Bishop","role":"Dibujo"},{"name":"Ronda Pattison","role":"Color"},{"name":"Ryan Kinnaird","role":"Color"}]','[{"id":"m2GDq","number":1,"title":"Las Tortugas Ninja: El último Ronin #1","subtitle":"","cover":"https://i1.whakoom.com/small/38/20/4aa8a05ceadd4c3cb6082c024f321a03.jpg","published":true,"releaseDate":null},{"id":"mfi47","number":2,"title":"Las Tortugas Ninja: El último Ronin #2","subtitle":"","cover":"https://i1.whakoom.com/small/10/11/35df1c874347413698588e841382bc30.jpg","published":true,"releaseDate":null},{"id":"jmZRi","number":3,"title":"Las Tortugas Ninja: El último Ronin #3","subtitle":"","cover":"https://i1.whakoom.com/small/00/3f/281650b5d70b4d8591a9d60345e6fc96.jpg","published":true,"releaseDate":null},{"id":"mZRR8","number":4,"title":"Las Tortugas Ninja: El último Ronin #4","subtitle":"","cover":"https://i1.whakoom.com/small/1f/29/537cdcaf9f04437d8ff6c1e66d763ebf.jpg","published":true,"releaseDate":null},{"id":"kmZRD","number":5,"title":"Las Tortugas Ninja: El último Ronin #5","subtitle":"","cover":"https://i1.whakoom.com/small/1e/28/140d141dc163433e84757c2682f8c929.jpg","published":true,"releaseDate":null}]','2026-04-12T14:31:39.531Z',NULL,NULL);
INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(220,'378736','edition','Star Wars','Planeta Cómic','https://inventario-api.josepec.workers.dev/covers/1776004320632-gs1z2c.jpg',64,'La aventura espacial más grande de todos los tiempos regresa a Marvel. Luke Skywalker y la variada banda de rebeldes que lucha contra el Imperio acaban de salir de su mayor victoria hasta la fecha (la destrucción de la estación estelar conocida como La Estrella de la Muerte).','https://www.whakoom.com/ediciones/378736','2026-04-12 14:32:01','2026-04-12 14:32:01',1,'Grapa 56-32 pp.','Terminada','Color. Tamaño 16,8 x 25,7 cm La 1ª entrega de cada serie tendrá una tirada inicial y limitada, con un PVP especial de 1 euro. Reimpresiones y siguientes entregas, tendrán el precio habitual, 2.50€','La aventura espacial más grande de todos los tiempos regresa a Marvel. Luke Skywalker y la variada banda de rebeldes que lucha contra el Imperio acaban de salir de su mayor victoria hasta la fecha (la destrucción de la estación estelar conocida como La Estrella de la Muerte).','[{"name":"Jason Aaron","role":"Guion"},{"name":"Salvador Larroca","role":"Dibujo, Tinta"},{"name":"Kieron Gillen","role":"Guion"},{"name":"Guru-eFX","role":"Color"},{"name":"John Cassaday","role":"Dibujo, Tinta"},{"name":"Laura Martin","role":"Color"},{"name":"Justin Ponsor","role":"Color"},{"name":"Ángel Unzueta","role":"Dibujo, Tinta"},{"name":"Jorge Molina","role":"Dibujo"},{"name":"Wade Von Grawbadger","role":"Tinta"}]','[{"id":"zoIVq","number":1,"title":"Star Wars #1","subtitle":"","cover":"https://i1.whakoom.com/small/1c/21/8b0ffe2bb59f436e8f217a280a249574.jpg","published":true,"releaseDate":null},{"id":"8OTbg","number":2,"title":"Star Wars #2","subtitle":"","cover":"https://i1.whakoom.com/small/0e/0c/