INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(221,'675256','edition','All In Justice League Unlimited','Panini Comics España','https://inventario-api.josepec.workers.dev/covers/1776005068543-zbg2w6.jpg',13,'¡Emerge la Atalaya! ¡Vuelve la Liga de la Justicia, con más miembros que nunca! Tras Absolute Power y DC All In Special, la muerte de Darkseid ha generado un vacío de poder en el Universo DC. Superman, Batman y Wonder Woman han de hacer crecer la Liga de la Justicia hasta abarcar a cada héroe, cada fuerza del bien que haga frente al mal por venir. Y mientras todos ellos tratan de resolver un oscuro misterio, el Proyecto Atom de Ray Palmer inicia una carrera por el control de los superpoderes en el planeta Tierra. Mundos vivirán, mundos morirán… Aquí comienza una nueva era de justicia.','https://www.whakoom.com/ediciones/675256','2026-04-12 14:44:29','2026-04-12 14:44:40',1,'Grapa','En curso',NULL,'¡Emerge la Atalaya! ¡Vuelve la Liga de la Justicia, con más miembros que nunca! Tras Absolute Power y DC All In Special, la muerte de Darkseid ha generado un vacío de poder en el Universo DC. Superman, Batman y Wonder Woman han de hacer crecer la Liga de la Justicia hasta abarcar a cada héroe, cada fuerza del bien que haga frente al mal por venir. Y mientras todos ellos tratan de resolver un oscuro misterio, el Proyecto Atom de Ray Palmer inicia una carrera por el control de los superpoderes en el planeta Tierra. Mundos vivirán, mundos morirán… Aquí comienza una nueva era de justicia.','[{"name":"Mark Waid","role":"Guion"},{"name":"Dan Mora","role":"Dibujo, Tinta"},{"name":"Tamra Bonvillain","role":"Color"},{"name":"Clayton Henry","role":"Dibujo"},{"name":"Travis Moore","role":"Dibujo"},{"name":"Christopher Cantwell","role":"Guion"},{"name":"Cia