INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(222,'77891','edition','Liga de la Justicia (2012-2022)','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1776005119855-s4rdy8.jpg',129,'El mundo entero se ha visto sorprendido por la aparición de los primeros superhéroes, campeones con habilidades especiales que desconciertan a las autoridades. El caso más conocido es el de Superman, cuya conducta y poderes se han convertido en la pesadilla de la policía de Metropolis y del ejército de Estados Unidos. Pero dicha urbe no es la única que ha asistido a la llegada de estos hombres increíbles. Coast City se ha visto deslumbrada por Green Lantern, capaz de hacer casi cualquier cosa con su anillo de poder, y Flash recorre a toda velocidad Central City. Mientras tanto, en Gotham City, se ha extendido el rumor de la existencia de Batman, un hombre vestido de murciélago que lucha contra el crimen y que, para muchos, es aún una leyenda urbana.','https://www.whakoom.com/ediciones/77891','2026-04-12 14:45:20','2026-04-12 14:45:32',1,'Grapa','Terminada',NULL,'El mundo entero se ha visto sorprendido por la aparición de los primeros superhéroes, campeones con habilidades especiales que desconciertan a las autoridades. El caso más conocido es el de Superman, cuya conducta y poderes se han convertido en la pesadilla de la policía de Metropolis y del ejército de Estados Unidos. Pero dicha urbe no es la única que ha asistido a la llegada de estos hombres increíbles. Coast City se ha visto deslumbrada por Green Lantern, capaz de hacer casi cualquier cosa con su anillo de poder, y Flash recorre a toda velocidad Central City. Mientras tanto, en Gotham City, se ha extendido el rumor de la existencia de Batman, un hombre vestido de murciélago que lucha 