INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(223,'77999','edition','Liga de la Justicia de América','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1776005387682-eyd26x.jpg',15,'La imagen pública de la Liga de la Justicia se deterioró considerablemente durante la batalla contra David Graves, un antiguo escritor que estuvo a punto de matar al coronel Steve Trevor, el enlace del grupo con ARGUS, la agencia gubernamental que, entre otras cosas, vigila de cerca las andanzas del grupo. Destituido y sustituido por la implacable Amanda Waller, Trevor se ha reunido recientemente con su aliado Green Arrow, que ha encontrado pruebas de que algo gordo se está cociendo en los bajos fondos.','https://www.whakoom.com/ediciones/77999','2026-04-12 14:49:48','2026-04-12 14:49:51',1,'Grapa 32 pp','Terminada',', Color','La imagen pública de la Liga de la Justicia se deterioró considerablemente durante la batalla contra David Graves, un antiguo escritor que estuvo a punto de matar al coronel Steve Trevor, el enlace del grupo con ARGUS, la agencia gubernamental que, entre otras cosas, vigila de cerca las andanzas del grupo. Destituido y sustituido por la implacable Amanda Waller, Trevor se ha reunido recientemente con su aliado Green Arrow, que ha encontrado pruebas de que algo gordo se está cociendo en los bajos fondos.','[{"name":"Matt Kindt","role":"Guion"},{"name":"Geoff Johns","role":"Guion"},{"name":"Tom Derenick","role":"Dibujo"},{"name":"Eddy Barrows","role":"Dibujo"},{"name":"David Finch","role":""},{"name":"Ray Fawkes","role":""},{"name":"Jeff Lemire","role":""},{"name":"Manuel García","role":""},{"name":"Doug Mahnke","role":""},{"name":"Brett Booth","role":""}]','[{"id":"NG946","number":1,"title":"Liga de la Justicia de América #1"