INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(224,'396352','edition','JLA. Liga de la Justicia de América','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1776005448151-zcjrk2.jpg',10,'El intento de invasión de Darkseid y las huestes de Apokolips forzó la reunión de los superhéroes que el mundo empezaba a conocer: Superman, el defensor de los desfavorecidos; Batman, el protector de Gotham City; Wonder Woman, la princesa de las amazonas; Hal Jordan, el Green Lantern de la Tierra; Flash, el hombre más rápido del mundo; Aquaman, legítimo rey de los siete mares; y Cíborg, un prometedor deportista que estuvo a punto de morir durante la invasión. Ahora, conforman la Liga de la Justicia, el grupo más poderoso de la Tierra.','https://www.whakoom.com/ediciones/396352','2026-04-12 14:50:48','2026-04-12 14:50:55',1,'Grapa 32 pp','Terminada',NULL,'El intento de invasión de Darkseid y las huestes de Apokolips forzó la reunión de los superhéroes que el mundo empezaba a conocer: Superman, el defensor de los desfavorecidos; Batman, el protector de Gotham City; Wonder Woman, la princesa de las amazonas; Hal Jordan, el Green Lantern de la Tierra; Flash, el hombre más rápido del mundo; Aquaman, legítimo rey de los siete mares; y Cíborg, un prometedor deportista que estuvo a punto de morir durante la invasión. Ahora, conforman la Liga de la Justicia, el grupo más poderoso de la Tierra.','[{"name":"Bryan Hitch","role":"Guion, Dibujo"},{"name":"Matt Kindt","role":"Guion"},{"name":"Phillip Tan","role":"Dibujo"},{"name":"Rob Williams","role":"Guion"}]','[{"id":"8HhNx","number":1,"title":"JLA. Liga de la Justicia de América #1","subtitle":"","cover":"https://i1.whakoom.com/small/06/23/b56a4607c29d4a96857307a026617011.jpg","publ