INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(225,'511357','edition','Liga de la Justicia: Sin justicia','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1776005494572-ew8zk4.jpg',4,'Noches oscuras: Metal ha transformado al Universo DC, de forma aterradora... y maravillosa. En este contexto, ha llegado el momento de adaptar a la Liga a los nuevos tiempos. ¡Solo la Liga de la Justicia puede aglutinar suficiente poder como para derrotar a las amenazas que están por llegar! ¿O no? Cuatro devoradores de planetas, alimentados por las energías ancestrales que han dado forma al universo, están a punto de poner a prueba a nuestros héroes. Su única esperanza reside en olvidar las viejas tradiciones y formar nuevas alianzas, ¡y eso incluye a villanos como Brainiac!','https://www.whakoom.com/ediciones/511357','2026-04-12 14:51:35','2026-04-12 14:51:38',1,'Grapa 32 pp','Terminada',NULL,'Noches oscuras: Metal ha transformado al Universo DC, de forma aterradora... y maravillosa. En este contexto, ha llegado el momento de adaptar a la Liga a los nuevos tiempos. ¡Solo la Liga de la Justicia puede aglutinar suficiente poder como para derrotar a las amenazas que están por llegar! ¿O no? Cuatro devoradores de planetas, alimentados por las energías ancestrales que han dado forma al universo, están a punto de poner a prueba a nuestros héroes. Su única esperanza reside en olvidar las viejas tradiciones y formar nuevas alianzas, ¡y eso incluye a villanos como Brainiac!','[{"name":"James Tynion IV","role":"Guion"},{"name":"Joshua Williamson","role":"Guion"},{"name":"Scott Snyder","role":"Guion"},{"name":"Francis Manapul","role":"Dibujo"}]','[{"id":"8x2nz","number":1,"title":"Liga de la Justicia: Sin justicia #1","subtitle":"","cover":"https://i1.w