INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(226,'674315','edition','All In Detective Comics','Panini Comics España','https://inventario-api.josepec.workers.dev/covers/1776005616564-x5lugq.jpg',13,'Tiempo atrás, los asesinatos de Thomas y Martha Wayne cambiaron Gotham para siempre. Algo de su origen ha permanecido oculto al Caballero Oscuro, esperando para atacarle desde aquella trágica noche en el Callejón del Crimen. Y es ahora cuando este fantasma del pasado de Gotham va a salir a la luz en una historia firmada por dos superestrellas, Tom Taylor y Mikel Janín, que sacudirá los pilares del héroe.','https://www.whakoom.com/ediciones/674315','2026-04-12 14:53:37','2026-04-12 14:53:39',1,'Grapa 24 pp','En curso','26x17 cm Color PVP 1.50€','Tiempo atrás, los asesinatos de Thomas y Martha Wayne cambiaron Gotham para siempre. Algo de su origen ha permanecido oculto al Caballero Oscuro, esperando para atacarle desde aquella trágica noche en el Callejón del Crimen. Y es ahora cuando este fantasma del pasado de Gotham va a salir a la luz en una historia firmada por dos superestrellas, Tom Taylor y Mikel Janín, que sacudirá los pilares del héroe.','[{"name":"Tom Taylor","role":"Guion"},{"name":"Mikel Janin","role":"Dibujo"},{"name":"Lee Garbett","role":"Dibujo"},{"name":"Joshua Fialkov","role":""},{"name":"Mike Norton","role":""},{"name":"Mariko Tamaki","role":"Guion"},{"name":"Al Ewing","role":""},{"name":"Alvaro Martinez Bueno","role":"Dibujo"},{"name":"Amancay Nahuelpán","role":"Dibujo"},{"name":"Dan Watters","role":"Guion"},{"name":"Fico Ossio","role":""},{"name":"John McCrea","role":""}]','[{"id":"yfmaf","number":1,"title":"All In Detective Comics #1","subtitle":"La Compasión De Un Padre, Primera parte","cover":"https://i1.whakoom.com/small/23