INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(228,'77997','edition','Green Lantern (2012-2022)','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1776005808961-3f31og.jpg',121,'Hace unos años, un temerario piloto de pruebas llamado Hal Jordan se convirtió en el primer miembro terrícola del Cuerpo de Green Lanterns, una organización policial interestelar fundada por los Guardianes del Universo. Allí, conoció a su mentor, Sinestro, el mismo que terminaría corrompiéndose y convirtiéndose en su peor enemigo. Tras enfrentarse en numerosas ocasiones, estos viejos adversarios formaron equipo para derrotar a Krona, un Guardián renegado a quien Jordan asesinó. Y mientras el terrícola era expulsado de la organización por semejante acto, Sinestro recuperaba sin quererlo su puesto en el Cuerpo.Hoy en día, hay más Green Lanterns nacidos en la Tierra. Kyle Rayner, el más reciente, ha vuelto a su planeta sin sospechar lo que le espera...','https://www.whakoom.com/ediciones/77997','2026-04-12 14:56:49','2026-04-12 14:57:16',1,'Grapa','Terminada',NULL,'Hace unos años, un temerario piloto de pruebas llamado Hal Jordan se convirtió en el primer miembro terrícola del Cuerpo de Green Lanterns, una organización policial interestelar fundada por los Guardianes del Universo. Allí, conoció a su mentor, Sinestro, el mismo que terminaría corrompiéndose y convirtiéndose en su peor enemigo. Tras enfrentarse en numerosas ocasiones, estos viejos adversarios formaron equipo para derrotar a Krona, un Guardián renegado a quien Jordan asesinó. Y mientras el terrícola era expulsado de la organización por semejante acto, Sinestro recuperaba sin quererlo su puesto en el Cuerpo.Hoy en día, hay más Green Lanterns nacidos en la Tierra. Kyle Rayner, el más reciente,