INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(230,'487462','edition','Grandes Autores de Liga de la Justicia: Keith Giffen, J.M. Dematteis y Kevin Maguire - JLI','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1776006336549-gpmbsm.jpg',2,'Acompaña a narradores de primera como Keith Giffen, J.M. DeMatteis y Kevin Maguire a lo largo de estas historias hilarantes y repletas de acción que se recuerdan con cariño por haber redefinido el término “grupo de superhéroes”. Este volumen cuenta también con el buen hacer de Al Gordon y Terry Austin y con contenido extra e introducciones de Giffen y el editor Andy Helfer.','https://www.whakoom.com/ediciones/487462','2026-04-12 15:05:37','2026-04-12 15:05:40',1,'Cartoné 200 pp','Terminada','Color. Tomo 1 (200 pags, PVP 20.5€) [Incompleta]','Acompaña a narradores de primera como Keith Giffen, J.M. DeMatteis y Kevin Maguire a lo largo de estas historias hilarantes y repletas de acción que se recuerdan con cariño por haber redefinido el término “grupo de superhéroes”. Este volumen cuenta también con el buen hacer de Al Gordon y Terry Austin y con contenido extra e introducciones de Giffen y el editor Andy Helfer.','[{"name":"Kevin Maguire","role":"Dibujo"},{"name":"Keith Giffen","role":"Guion, Dibujo"},{"name":"J.M. DeMatteis","role":"Guion"},{"name":"John Ostrander","role":"Guion"},{"name":"Bill Willingham","role":"Dibujo"},{"name":"Luke McDonnell","role":"Dibujo"}]','[{"id":"WIwLk","number":1,"title":"Grandes Autores de Liga de la Justicia: Keith Giffen, J.M. Dematteis y Kevin Maguire - JLI #1","subtitle":"Liga de la Justicia - JLI vol. 1","cover":"https://i1.whakoom.com/small/27/38/d788d9d091cf45c39b1b88db24f25a26.jpg","published":true,"releaseDate":null},{"id":"xGRM6","number":2,"title":"Grandes Autores de Liga de la Justicia: Keith Giffen, J.M. Dematteis y Kevin Maguire - JLI #2","subtitle":"Liga de la Justicia - JLI vol. 2","cover":"https://i1.whakoom.com/small/34/09/7493ceeada2846409ffa1474d432ae89.jpg","published":true,"releaseDate":null}]','2026-04-12T15:05:41.848Z',NULL,NULL);
INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(231,'608246','edition','Superman Saga de Brian Michael Bendis','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1776006416273-d9xt56.jpg',5,'Ha llegado a la Tierra un monstruo de inmenso poder. Se llama Rogol Zaar y se ha propuesto terminar una misión que emprendió hace años. Y para eso, necesita matar tanto a Superman como a Supergirl, los últimos kryptonianos que quedan vivos. Este nuevo enemigo no podría llegar en peor momento, ya que el Hombre de Acero está inquieto por un asunto personal. Su padre, el científico Jor-El, dado por muerto durante décadas, regresó recientemente de entre los muertos. Y ahora, ha pedido a Superboy que lo acompañe a un viaje por el universo... y la respuesta del pequeño Jon no podría haber sido más entusiasta.','https://www.whakoom.com/ediciones/608246','2026-04-12 15:06:56','2026-04-12 15:07:00',1,'Cartoné 168-248 pp','Terminada',NULL,'Ha llegado a la Tierra un monstruo de inmenso poder. Se llama Rogol Zaar y se ha propuesto terminar una misión que emprendió hace años. Y para eso, necesita matar tanto a Superman como a Supergirl, los últimos kryptonianos que quedan vivos. Este nuevo enemigo no podría llegar en peor momento, ya que el Hombre de Acero está inquieto por un asunto personal. Su padre, el científico Jor-El, dado por muerto durante décadas, regresó recientemente de entre los muertos. Y ahora, ha pedido a Superboy que lo acompañe a un viaje por el universo... y la respuesta del pequeño Jon no podría haber sido más entusiasta.','[{"name":"Brian Michael Bendis","role":"Guion"},{"name":"Ivan Reis","role":""},{"name":"Joe Prado","role":"Tinta"},{"name":"Alex Sinclair","role":"Color"},{"name":"Oclair Albert","role":"Tinta"},{"name":"Kevin Maguire","role":"Dibujo, Tinta"},{"name":"Danny Miki","role":"Tinta"},{"name":"Julio Ferreira","role":"Tinta"},{"name":"Jason Fabok","role":"Dibujo, Tinta"},{"name":"Evan Shaner","role":"Dibujo, Tinta"},{"name":"Dave McCaig","role":"Color"},{"name":"John Timms","role":"Dibujo, Tinta"}]','[{"id":"mhGvq","number":1,"title":"Superman Saga de Brian Michael Bendis #1","subtitle":"El Hombre de Acero [La Saga de la Unidad parte 1]","cover":"https://i1.whakoom.com/small/3b/29/2be1170c9a784b94b71a4496fa9aab2f.jpg","published":true,"releaseDate":null},{"id":"yvFa1","number":2,"title":"Superman Saga de Brian Michael Bendis #2","subtitle":"La Tierra Fantasma [La Saga de la Unidad parte 2]","cover":"https://i1.whakoom.com/small/29/10/5f096c6f910449e2a93c9df1afa14f6e.jpg","published":true,"releaseDate":null},{"id":"8vmlv","number":3,"title":"Superman Saga de Brian Michael Bendis #3","subtitle":"La casa de El [La Saga de la Unidad parte 3]","cover":"https://i1.whakoom.com/small/04/3a/7ca6add2094e44688ebf823fd49e8d0d.jpg","published":true,"releaseDate":null},{"id":"LDpHq","number":4,"title":"Superman Saga de Brian Michael Bendis #4","subtitle":"La Verdad Sale a la Luz ( La Verdad Parte 1)","cover":"https://i1.whakoom.com/small/1b/19/35762f0f183547a4be455bc6f1daf0c7.jpg","published":true,"releaseDate":null},{"id":"k1NBd","number":5,"title":"Superman Saga de Brian Michael Bendis #5","subtitle":"Mitológico (La verdad. Parte 2)","cover":"https://i1.whakoom.com/small/3e/16/3d54d169917f4bcaa127f5c4e7fd2988.jpg","published":true,"releaseDate":null}]','2026-04-12T15:07:01.038Z',NULL,NULL);
INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(232,'552452','edition','Superman: Action Comics Saga Renacimiento','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1776006439219-2cj2us.jpg',4,'Fue el principal héroe del mundo. Y entonces, el mundo que conocía quedó borrado de la existencia. Superman escapó junto a su esposa y su hijo a una versión nueva y extraña de la Tierra donde operó en secreto mientras observaba cómo defendía el planeta un Hombre de Acero distinto, joven y menos experimentado. Aquel héroe joven murió, y ahora el Hombre de Acero original está preparado para dar un paso adelante y sustituirlo. Pero no está listo para lo que va a suceder.','https://www.whakoom.com/ediciones/552452','2026-04-12 15:07:20','2026-04-12 15:07:20',1,'Cartoné 144-368 pp','Terminada',NULL,'Fue el principal héroe del mundo. Y entonces, el mundo que conocía quedó borrado de la existencia. Superman escapó junto a su esposa y su hijo a una versión nueva y extraña de la Tierra donde operó en secreto mientras observaba cómo defendía el planeta un Hombre de Acero distinto, joven y menos experimentado. Aquel héroe joven murió, y ahora el Hombre de Acero original está preparado para dar un paso adelante y sustituirlo. Pero no está listo para lo que va a suceder.','[{"name":"Dan Jurgens","role":"Guion, Dibujo"},{"name":"Art Thibert","role":"Tinta"},{"name":"Patrick Zircher","role":"Dibujo, Tinta"},{"name":"Tyler Kirkham","role":"Dibujo, Tinta"},{"name":"Will Conrad","role":"Dibujo, Tinta"},{"name":"Trevor Scott","role":"Tinta"},{"name":"Hi-Fi Desing","role":"Color"},{"name":"Arif Prianto","role":"Color"},{"name":"Scott Hanna","role":"Tinta"},{"name":"Ulises Arreola","role":"Color"}]','[{"id":"jhlxp","number":1,"title":"Superman: Action Comic