INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(236,'287495','edition','Spiderman. Coleccionable Spider-Man','Panini Comics España','https://inventario-api.josepec.workers.dev/covers/1776006840011-ztfyq6.jpg',6,'En 1990, después de haberse alzado como el más comercial artista arácnido de la década, Todd McFarlane dio un paso adelante en su carrera al conseguir que Marvel le concediera una nueva colección en la que también sería el autor de las historias: relatos oscuros y siniestros, diferentes al espíritu tradicional del trepamuros. Esta serie de seis volúmenes ofrece tanto la etapa de McFarlane como la de su sucesor, Erik Larsen, así como los episodios de la misma cabecera que realizara Ann Nocenti.','https://www.whakoom.com/ediciones/287495','2026-04-12 15:14:00','2026-04-12 15:14:04',1,'Cartoné','Terminada',NULL,'En 1990, después de haberse alzado como el más comercial artista arácnido de la década, Todd McFarlane dio un paso adelante en su carrera al conseguir que Marvel le concediera una nueva colección en la que también sería el autor de las historias: relatos oscuros y siniestros, diferentes al espíritu tradicional del trepamuros. Esta serie de seis volúmenes ofrece tanto la etapa de McFarlane como la de su sucesor, Erik Larsen, así como los episodios de la misma cabecera que realizara Ann Nocenti.','[{"name":"Gregory Wright","role":"Color"},{"name":"Todd McFarlane","role":"Guion, Dibujo, Tinta, Color"},{"name":"Ann Nocenti","role":"Guion"},{"name":"Sam de la Rosa","role":"Tinta"},{"name":"Rob Liefeld","role":"Guion, Dibujo, Tinta"},{"name":"Kevin Tinsley","role":"Color"},{"name":"Chris Marrinan","role":"Dibujo"},{"name":"Erik Larsen","role":"Guion, Dibujo, Tinta"},{"name":"Renée Witterstaetter","role":"Color"},{"name":"Terry Kavanagh"