INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(240,'168369','edition','Batman: Tierra Uno','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1776007409450-unjjd0.jpg',3,'Batman no es un héroe. Es solamente un hombre. Susceptible de equivocarse, vulnerable y furioso. En una Gotham City donde amigos y enemigos son indistinguibles, el camino que llevará a Bruce Wayne a convertirse en el Caballero Oscuro presenta más obstáculos que nunca. Centrada en castigar a los verdaderos asesinos de sus padres, y a la corrupta fuerza policial que los dejó escapar, la sed de venganza de Bruce Wayne alimenta su enloquecida cruzada y nadie, ni siquiera Alfred, podrá detenerle.','https://www.whakoom.com/ediciones/168369','2026-04-12 15:22:33','2026-04-12 15:23:30',1,'Cartoné 144-160 pp','Terminada','Color.','Batman no es un héroe. Es solamente un hombre. Susceptible de equivocarse, vulnerable y furioso. En una Gotham City donde amigos y enemigos son indistinguibles, el camino que llevará a Bruce Wayne a convertirse en el Caballero Oscuro presenta más obstáculos que nunca. Centrada en castigar a los verdaderos asesinos de sus padres, y a la corrupta fuerza policial que los dejó escapar, la sed de venganza de Bruce Wayne alimenta su enloquecida cruzada y nadie, ni siquiera Alfred, podrá detenerle.','[{"name":"Geoff Johns","role":"Guion"},{"name":"Gary Frank","role":"Dibujo"},{"name":"Brad Anderson","role":"Color"},{"name":"Jonathan Sibal","role":"Tinta"}]','[{"id":"6VV5W","number":1,"title":"Batman: Tierra Uno #1","subtitle":"","cover":"https://i1.whakoom.com/small/0d/2f/e5cd7a9b64134daebf5a53dab3fd8d48.jpg","published":true,"releaseDate":null},{"id":"O0Ba7","number":2,"title":"Batman: Tierra Uno #2","subtitle":"","cover":"https://i1.whakoom.com/small/31/3d/01854e06863c42d7a1e537329e8c8031.jpg","published":true,"releaseDate":null},{"id":"8mXPH","number":3,"title":"Batman: Tierra Uno #3","subtitle":"","cover":"https://i1.whakoom.com/small/38/0d/836dc8c166bc4da1b55d3efe34708d85.jpg","published":true,"releaseDate":null}]',NULL,NULL,NULL);
INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(241,'263673','edition','Superman: Tierra Uno','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1776007379022-k1hmay.jpg',3,'Ahora el guionista J. Michael Straczynski ofrece la versión moderna del relato del único superviviente del planeta Krypton y de su lucha por salvar a la humanidad de las mismas fuerzas alienígenas que destruyeron su mundo natal. Junto al dibujante Shane Davis (Green Lantern), Straczynski presenta una encarnación muy distinta de Superman.','https://www.whakoom.com/ediciones/263673','2026-04-12 15:22:59','2026-04-12 15:23:03',1,'Cartoné 136 pp','Terminada','Color.','Ahora el guionista J. Michael Straczynski ofrece la versión moderna del relato del único superviviente del planeta Krypton y de su lucha por salvar a la humanidad de las mismas fuerzas alienígenas que destruyeron su mundo natal. Junto al dibujante Shane Davis (Green Lantern), Straczynski presenta una encarnación muy distinta de Superman.','[{"name":"Joe Michael Straczynski","role":"Guion"},{"name":"Shane Davis","role":"Dibujo"},{"name":"Sandra Hope","role":"Tinta"},{"name":"Bárbara Ciardo","role":"Color"},{"name":"Ardian Syaf","role":"Dibujo"}]','[{"id":"8Ahnh","number":1,"title":"Superman: Tierra Uno #1","subtitle":"Superman: Tierra Uno vol. 1","cover":"https://i1.whakoom.com/small/31/26/8b021a784ac242ad9a7d5cb24bd5f79d.jpg","published":true,"releaseDate":null},{"id":"6Ahn2","number":2,"title":"Superman: Tierra Uno #2","subtitle":"Superman: Tierra Uno vol. 2","cover":"https://i1.whakoom.com/small/3e/2a/abc1f019ec5d49269e3ba528d0056bac.jpg","published":true,"releaseDate":null},{"id":"OAFI6","number":3,"title":"Superman: Tierra Uno #3","subtitle":"Superman: Tierra Uno vol. 3","cover":"https://i1.wh