INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(244,'357063','edition','John Constantine. Hellblazer','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1776007485613-x4olii.jpg',18,'John Constantine es un mago inglés, poco convencional y uno de los personajes más importantes de la frontera magica y sobrenatural del Universo DC. Un personaje de pasado Punk, que se aleja de la visión típica del mago y que representa a cierta parte de la sociedad inglesa, respondiendo al reflejo de la época y tratando de personificar una visión cínica e irónica de la Inglaterra de los años 80. Una especie de antiheroe rudo, soez, a veces sin escrupulos, otras compasivo, siempre controvertido.','https://www.whakoom.com/ediciones/357063','2026-04-12 15:24:46','2026-04-12 15:25:22',0,'Cartoné 312-696 pp','Terminada','La colección se publicará en 18 tomos Integrales con periodicidad bimestral. En lugar de comenzar la publicación de la colección desde el inicio de la numeración USA, la editorial ha decidido publicar la serie comenzando por los guionistas mas populares. Así, cada tomo tiene una doble numeración: la del autor al que pertenece y la numeración que corresponde a ese tomo dentro de la colección.','John Constantine es un mago inglés, poco convencional y uno de los personajes más importantes de la frontera magica y sobrenatural del Universo DC. Un personaje de pasado Punk, que se aleja de la visión típica del mago y que representa a cierta parte de la sociedad inglesa, respondiendo al reflejo de la época y tratando de personificar una visión cínica e irónica de la Inglaterra de los años 80. Una especie de antiheroe rudo, soez, a veces sin escrupulos, otras compasivo, siempre controvertido.','[{"name":"Giuseppe Camuncoli","role":"Dibujo"},{"na