INSERT INTO "collections" ("id","whakoom_id","whakoom_type","title","publisher","cover_url","total_issues","description","url","created_at","updated_at","tracking","format","status","edition_details","synopsis","authors","issues","whakoom_synced_at","rating","notes") VALUES(248,'356295','edition','Orígenes secretos','ECC Ediciones','https://inventario-api.josepec.workers.dev/covers/1776008086259-n3maw6.jpg',4,'"El Nuevo Universo DC está repleto de incógnitas que afectan tanto a sus personajes más icónicos como a los más recónditos. Para aclararlas nace esta colección, Orígenes secretos, que recupera una cabecera clásica y arroja mucha luz sobre lo relatado en las actuales series. En este volumen inicial, que recopila los tres primeros números americanos, presenciamos los singulares comienzos de Superman, el primer Robin, Supergirl, Batman, Aquaman, Starfire, Green Lantern, Batwoman y Red Robin. Guionistas como Greg Pak, Ray Fawkes o Robert Venditti se unen a dibujantes de la talla de Lee Weeks, Doug Mahnke y el cántabro Álvaro Martínez en esta antología imprescindible para cualquier seguidor de DC."','https://www.whakoom.com/ediciones/356295','2026-04-12 15:34:47','2026-04-12 16:15:49',0,'Cartoné 112-128 pp','Terminada',NULL,'"El Nuevo Universo DC está repleto de incógnitas que afectan tanto a sus personajes más icónicos como a los más recónditos. Para aclararlas nace esta colección, Orígenes secretos, que recupera una cabecera clásica y arroja mucha luz sobre lo relatado en las actuales series. En este volumen inicial, que recopila los tres primeros números americanos, presenciamos los singulares comienzos de Superman, el primer Robin, Supergirl, Batman, Aquaman, Starfire, Green Lantern, Batwoman y Red Robin. Guionistas como Greg Pak, Ray Fawkes o Robert Venditti se unen a dibujantes de la talla de Lee Weeks, Doug Mahnke y el cántabro Álvaro Martínez en esta antología imprescindible para cualquier seguidor de DC."','[{"name":"Jeff Parker","role":"Guion"},{"name":"S